/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2018_SEED = {"dse/writing/part-b/2018/Q2":[{"front":"one step, one breath, one finish line","meaning":"一步、一口氣、一條終點線","examples":[{"en":"The marathon became a journey of one step, one breath and one finish line.","zh":"馬拉松變成一段一步、一口氣、一條終點線的旅程。"},{"en":"“One step, one breath, one finish line” means a difficult goal can be reached by focusing on each small action.","zh":"“One step, one breath, one finish line” 指困難目標可以透過專注每一個小動作來達成。"},{"en":"A tired runner may survive the final kilometres by thinking of one step and one breath at a time.","zh":"疲累的跑手可能靠想着一步、一口氣來撐過最後幾公里。"},{"en":"Big challenges feel less frightening when people break them into small moments.","zh":"當人們把大挑戰拆成細小時刻，挑戰就不那麼可怕。"},{"en":"This phrase turns the marathon into a lesson about patience and endurance.","zh":"這個短語把馬拉松變成關於耐性和耐力的教訓。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"finish line","meaning":"終點線","examples":[{"en":"Crossing the finish line changed the way he saw himself.","zh":"衝過終點線改變了他看待自己的方式。"},{"en":"The finish line is the line or point where a race officially ends.","zh":"Finish line 指比賽正式結束的線或位置。"},{"en":"Runners often feel emotional when they finally see the finish line after hours of effort.","zh":"跑手努力數小時後終於看見終點線，常會感到激動。"},{"en":"A finish line can represent not only the end of a race but also the proof of persistence.","zh":"終點線不只代表比賽結束，也代表堅持的證明。"},{"en":"This phrase is useful when talking about goals, effort, and completion.","zh":"這個短語適合用來談目標、努力和完成。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"have you ever looked at","meaning":"你有沒有看過","examples":[{"en":"Have you ever looked at marathon runners on television and felt inspired?","zh":"你有沒有看過電視上的馬拉松跑手，並感到受鼓舞？"},{"en":"“Have you ever looked at” asks whether someone has seen or noticed something before.","zh":"“Have you ever looked at” 用來詢問某人以前是否看過或留意過某事。"},{"en":"Have you ever looked at old photos and remembered how much you have changed?","zh":"你有沒有看過舊照片，然後想起自己改變了多少？"},{"en":"This question often invites readers to connect the topic with their own experience.","zh":"這個問題常邀請讀者把題目與自己的經驗連繫起來。"},{"en":"It is useful at the beginning of an essay because it draws the reader in.","zh":"它適合用於文章開首，因為可以吸引讀者投入。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"marathon runners","meaning":"馬拉松跑手","examples":[{"en":"Marathon runners often look impossibly strong on television.","zh":"電視上的馬拉松跑手常看起來強得不可思議。"},{"en":"Marathon runners are people who train to run a long-distance race of 42.195 kilometres.","zh":"Marathon runners 指訓練自己去跑 42.195 公里長距離賽事的人。"},{"en":"Marathon runners need endurance, planning, and mental strength.","zh":"馬拉松跑手需要耐力、計劃和心理力量。"},{"en":"Many marathon runners are ordinary people who improve through months of practice.","zh":"許多馬拉松跑手是透過數月練習進步的普通人。"},{"en":"This phrase refers to both professional athletes and everyday runners who join marathons.","zh":"這個短語可以指職業運動員，也可以指參加馬拉松的日常跑手。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"That could never be me","meaning":"那永遠不可能是我","examples":[{"en":"He used to think, “That could never be me.”","zh":"他以前常想：「那永遠不可能是我。」"},{"en":"“That could never be me” means I believe I could never become that kind of person or do that thing.","zh":"“That could never be me” 指我相信自己永遠不可能成為那種人或做到那件事。"},{"en":"A student may say, “That could never be me,” when watching someone give a confident speech.","zh":"學生看見別人自信演講時，可能會說：「那永遠不可能是我。」"},{"en":"People often say this before they discover what training and patience can do.","zh":"人們常在發現訓練和耐性有多大作用之前這樣說。"},{"en":"This phrase shows self-doubt before growth begins.","zh":"這個短語顯示成長開始前的自我懷疑。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"used to think","meaning":"以前常常認為","examples":[{"en":"He used to think that running a marathon was impossible.","zh":"他以前常常認為跑馬拉松是不可能的。"},{"en":"Used to think means believed something in the past, but may not believe it now.","zh":"Used to think 指以前相信某事，但現在可能不再這樣相信。"},{"en":"I used to think exercise was only for sporty people.","zh":"我以前常常認為運動只屬於愛運動的人。"},{"en":"A person may change what they used to think after trying something difficult.","zh":"一個人嘗試困難事情後，可能會改變以前常常認為的事。"},{"en":"This phrase helps show a clear change in opinion.","zh":"這個短語幫助顯示想法上的清楚轉變。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"exactly the same thing","meaning":"完全一樣的想法","examples":[{"en":"Many young people think exactly the same thing.","zh":"許多年輕人都有完全一樣的想法。"},{"en":"Exactly the same thing means the very same idea, feeling, or opinion.","zh":"Exactly the same thing 指完全相同的想法、感受或意見。"},{"en":"Many students think exactly the same thing before their first public speech.","zh":"許多學生在第一次公開演講前都有完全一樣的想法。"},{"en":"When people share the same fear, they may feel less alone.","zh":"當人們有相同恐懼時，他們可能會覺得不那麼孤單。"},{"en":"This phrase stresses that the feeling is common, not unusual.","zh":"這個短語強調這種感覺很普遍，並不奇怪。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"sounded like something for","meaning":"聽起來像是……才會做的事","examples":[{"en":"Running 42.195 kilometres sounded like something for professional athletes.","zh":"跑 42.195 公里聽起來像是職業運動員才會做的事。"},{"en":"Sounded like something for means seemed suitable only for a certain type of person.","zh":"Sounded like something for 指看似只適合某一類人做的事。"},{"en":"Joining a debate team sounded like something for confident students, not shy beginners.","zh":"加入辯論隊聽起來像是自信學生才會做的事，而不是害羞初學者。"},{"en":"A challenge may sound like something for experts until ordinary people try it step by step.","zh":"一項挑戰可能聽起來像是專家才會做的事，直到普通人一步一步嘗試。"},{"en":"This phrase shows how first impressions can limit people.","zh":"這個短語顯示第一印象如何限制人。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"professional athletes","meaning":"職業運動員","examples":[{"en":"A marathon sounded like something for professional athletes.","zh":"馬拉松聽起來像是職業運動員才會做的事。"},{"en":"Professional athletes are people who train and compete in sports as their job.","zh":"Professional athletes 指以訓練和參加體育比賽為職業的人。"},{"en":"Professional athletes usually follow strict training, diet, and recovery plans.","zh":"職業運動員通常跟從嚴格的訓練、飲食和恢復計劃。"},{"en":"Ordinary runners may not be professional athletes, but they can still train safely for races.","zh":"普通跑手未必是職業運動員，但仍可以安全地為比賽訓練。"},{"en":"This phrase contrasts trained sports experts with everyday people.","zh":"這個短語把受訓運動專家與普通人作對比。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"ordinary young people","meaning":"普通年輕人","examples":[{"en":"The writer wants ordinary young people to try the marathon.","zh":"作者想鼓勵普通年輕人嘗試馬拉松。"},{"en":"Ordinary young people are normal teenagers or young adults, not famous athletes or experts.","zh":"Ordinary young people 指普通青少年或年輕成年人，不是著名運動員或專家。"},{"en":"Ordinary young people may have school, work, family duties, and limited time.","zh":"普通年輕人可能有學業、工作、家庭責任和有限時間。"},{"en":"The marathon becomes inspiring when ordinary young people realise they can train for it.","zh":"當普通年輕人明白自己也可以訓練參加馬拉松時，這件事就變得鼓舞人心。"},{"en":"This phrase reminds readers that big goals are not only for special people.","zh":"這個短語提醒讀者，大目標不只屬於特別的人。"}],"source":"2018 Q2.pdf","sourcePage":1},{"front":"part-time jobs","meaning":"兼職工作","examples":[{"en":"Young people may have homework, exams and part-time jobs.","zh":"年輕人可能有功課、考試和兼職工作。"},{"en":"Part-time jobs are jobs that people do for only part of the day or week.","zh":"Part-time jobs 指每天或每星期只做部分時間的工作。"},{"en":"A student may take part-time jobs after school to earn money and gain experience.","zh":"學生可能放學後做兼職工作來賺錢和累積經驗。"},{"en":"Part-time jobs can make training harder because free time becomes limited.","zh":"兼職工作會令訓練更困難，因為空閒時間變少。"},{"en":"This phrase is useful when describing young people’s busy lives.","zh":"這個短語適合用來描述年輕人忙碌的生活。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"keep snoozing","meaning":"不斷按鬧鐘延後","examples":[{"en":"Many students keep snoozing their alarm clocks in the morning.","zh":"許多學生早上不斷按鬧鐘延後。"},{"en":"Keep snoozing means repeatedly press the alarm to delay waking up.","zh":"Keep snoozing 指反覆按鬧鐘，把起床時間延後。"},{"en":"If you keep snoozing every morning, you may have less time to exercise or eat breakfast.","zh":"如果你每天早上不斷按鬧鐘延後，就可能少了時間運動或吃早餐。"},{"en":"Runners often stop snoozing because early training requires discipline.","zh":"跑手常會停止賴床，因為早晨訓練需要紀律。"},{"en":"This phrase describes a small habit that can affect a whole day.","zh":"這個短語描述一個會影響整天的小習慣。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"for the first time","meaning":"第一次","examples":[{"en":"He ran the Hong Kong Marathon for the first time.","zh":"他第一次跑香港馬拉松。"},{"en":"For the first time means doing something that has never been done by that person before.","zh":"For the first time 指某人以前從未做過某事，這是首次。"},{"en":"She joined a running group for the first time and felt nervous at the start.","zh":"她第一次加入跑步小組，開始時感到緊張。"},{"en":"Trying something for the first time can be frightening but also exciting.","zh":"第一次嘗試某事可能令人害怕，但也令人興奮。"},{"en":"This phrase marks the beginning of a new experience.","zh":"這個短語標示新經歷的開始。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"neither was I","meaning":"我也不是","examples":[{"en":"He was not the fastest runner, and neither was he the strongest.","zh":"他不是最快的跑手，也不是最強壯的跑手。"},{"en":"Neither was I means I was not that thing either.","zh":"Neither was I 指我也不是那樣。"},{"en":"My friend was not confident before the race, and neither was I.","zh":"我的朋友賽前沒有信心，我也不是很有信心。"},{"en":"This phrase is used when a negative statement is also true for another person.","zh":"當一個否定說法也適用於另一個人時，可以使用這個短語。"},{"en":"It helps show shared weakness or shared experience.","zh":"它幫助顯示共同弱點或共同經驗。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"at one point","meaning":"有一刻；某一刻","examples":[{"en":"At one point, he was not even sure he was still sane.","zh":"有一刻，他甚至不確定自己是否仍然神志清醒。"},{"en":"At one point means at a particular moment during a longer experience.","zh":"At one point 指在一段較長經歷中的某個特定時刻。"},{"en":"At one point during training, he wanted to stop and go home.","zh":"在訓練某一刻，他想停下來回家。"},{"en":"Long challenges often include one difficult moment when people question themselves.","zh":"長時間挑戰常會有一個困難時刻，令人質疑自己。"},{"en":"This phrase helps focus on one important moment in a story.","zh":"這個短語幫助集中描述故事中的一個重要時刻。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"not even sure","meaning":"甚至不確定","examples":[{"en":"He was not even sure he could finish the race.","zh":"他甚至不確定自己能否完成比賽。"},{"en":"Not even sure means lacking confidence even about something important or basic.","zh":"Not even sure 指連重要或基本的事情也沒有信心確定。"},{"en":"The beginner was not even sure he could run five kilometres without stopping.","zh":"那位初學者甚至不確定自己能否不停下來跑五公里。"},{"en":"Fear grows when someone is not even sure they can continue.","zh":"當一個人甚至不確定自己能否繼續，恐懼會增加。"},{"en":"This phrase shows strong doubt.","zh":"這個短語顯示強烈懷疑。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"still sane","meaning":"仍然神志清醒","examples":[{"en":"At one point, he wondered whether he was still sane.","zh":"有一刻，他懷疑自己是否仍然神志清醒。"},{"en":"Still sane means still able to think clearly and sensibly.","zh":"Still sane 指仍然能清楚而理智地思考。"},{"en":"After waking up at 5 a.m. for training, he wondered if he was still sane.","zh":"凌晨五點起床訓練後，他懷疑自己是否仍然神志清醒。"},{"en":"People may jokingly question whether they are still sane when they choose a very hard challenge.","zh":"當人們選擇非常困難的挑戰時，可能會半開玩笑地懷疑自己是否仍然清醒。"},{"en":"This phrase can show both stress and humour.","zh":"這個短語可以同時表現壓力和幽默。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"crossing that finish line","meaning":"衝過那條終點線","examples":[{"en":"Crossing that finish line changed the way he saw himself.","zh":"衝過那條終點線改變了他看待自己的方式。"},{"en":"Crossing that finish line means passing the end point of the race after all the effort.","zh":"Crossing that finish line 指在所有努力之後越過比賽終點。"},{"en":"Crossing that finish line proved that months of training had not been wasted.","zh":"衝過那條終點線證明數月訓練沒有白費。"},{"en":"A runner may cry after crossing the finish line because the goal has become real.","zh":"跑手衝過終點線後可能會哭，因為目標終於成真。"},{"en":"This phrase focuses on the powerful moment of completion.","zh":"這個短語集中表現完成一刻的力量。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"change the way I saw myself","meaning":"改變我看待自己的方式","examples":[{"en":"The marathon changed the way he saw himself.","zh":"馬拉松改變了他看待自己的方式。"},{"en":"To change the way I saw myself means to make me understand my own strength or identity differently.","zh":"To change the way I saw myself 指令我以不同方式理解自己的力量或身份。"},{"en":"Finishing the race changed the way I saw myself because I no longer felt weak.","zh":"完成比賽改變了我看待自己的方式，因為我不再覺得自己軟弱。"},{"en":"A difficult challenge can change the way people see themselves by revealing hidden courage.","zh":"困難挑戰可以透過揭示隱藏勇氣，改變人們看待自己的方式。"},{"en":"This phrase is useful when an experience changes self-belief.","zh":"當經歷改變自我信念時，這個短語很有用。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"make me realise that","meaning":"令我明白","examples":[{"en":"The race made him realise that courage can be trained.","zh":"這場比賽令他明白勇氣是可以訓練出來的。"},{"en":"Make me realise that means cause me to understand something clearly.","zh":"Make me realise that 指令我清楚明白某事。"},{"en":"Training made me realise that small habits can change a whole life.","zh":"訓練令我明白小習慣可以改變整個人生。"},{"en":"Failure can make people realise that they need a better plan.","zh":"失敗可以令人明白自己需要更好的計劃。"},{"en":"This phrase connects an experience with a new lesson.","zh":"這個短語把經歷和新教訓連接起來。"}],"source":"2018 Q2.pdf","sourcePage":2},{"front":"not just a race","meaning":"不只是一場比賽","examples":[{"en":"The marathon is not just a race.","zh":"馬拉松不只是一場比賽。"},{"en":"Not just a race means it is more than a competition; it also teaches life lessons.","zh":"Not just a race 指它不只是競賽，也教人生道理。"},{"en":"For beginners, a marathon is not just a race but a test of patience.","zh":"對初學者來說，馬拉松不只是一場比賽，而是耐性的考驗。"},{"en":"It becomes more meaningful when runners learn discipline and courage from it.","zh":"當跑手從中學到紀律和勇氣，它就變得更有意義。"},{"en":"This phrase moves from the surface meaning to a deeper meaning.","zh":"這個短語把表面意思推向更深層意思。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, the marathon teaches young people discipline.","zh":"事實上，馬拉松教會年輕人紀律。"},{"en":"In fact introduces a clearer, stronger, or more accurate point.","zh":"In fact 用來引出更清楚、更有力或更準確的一點。"},{"en":"Running may look simple; in fact, it requires planning and patience.","zh":"跑步可能看似簡單；事實上，它需要計劃和耐性。"},{"en":"Writers use in fact when they want to correct or deepen an earlier idea.","zh":"作者想修正或深化前面的想法時，會用 in fact。"},{"en":"This phrase helps strengthen an argument.","zh":"這個短語幫助加強論點。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"truly teach young people","meaning":"真正教會年輕人","examples":[{"en":"The marathon truly teaches young people courage and discipline.","zh":"馬拉松真正教會年輕人勇氣和紀律。"},{"en":"Truly teach young people means genuinely help young people learn something important through experience.","zh":"Truly teach young people 指透過經驗真正幫助年輕人學到重要東西。"},{"en":"Hard training can truly teach young people patience better than a lecture can.","zh":"艱苦訓練比講座更能真正教會年輕人耐性。"},{"en":"The marathon truly teaches young people because the lesson is felt in the body.","zh":"馬拉松真正教會年輕人，因為這個教訓是身體親自感受到的。"},{"en":"This phrase stresses real learning, not just hearing advice.","zh":"這個短語強調真實學習，而不只是聽建議。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"courage, discipline and connection","meaning":"勇氣、紀律和連結","examples":[{"en":"The marathon teaches courage, discipline and connection.","zh":"馬拉松教會人勇氣、紀律和連結。"},{"en":"Courage, discipline and connection are bravery, self-control, and a feeling of belonging with others.","zh":"Courage, discipline and connection 指勇敢、自我控制，以及與他人有歸屬感。"},{"en":"Training builds discipline, race day requires courage, and cheering crowds create connection.","zh":"訓練建立紀律，比賽當日需要勇氣，而打氣的人群創造連結。"},{"en":"These three qualities make the marathon more than a physical event.","zh":"這三種特質令馬拉松不只是體能活動。"},{"en":"This phrase summarises the main lessons of the experience.","zh":"這個短語總結這段經歷的主要教訓。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"encourage you to sign up for","meaning":"鼓勵你報名參加","examples":[{"en":"The writer wants to encourage readers to sign up for the next marathon.","zh":"作者想鼓勵讀者報名參加下一次馬拉松。"},{"en":"To encourage you to sign up for something means to persuade you kindly to register for it.","zh":"To encourage you to sign up for something 指友善地說服你報名參加某事。"},{"en":"A coach may encourage you to sign up for a short race before trying a marathon.","zh":"教練可能鼓勵你先報名參加短跑比賽，再嘗試馬拉松。"},{"en":"Encouragement can make a nervous beginner take the first step.","zh":"鼓勵可以令緊張的初學者踏出第一步。"},{"en":"This phrase is useful when giving advice with support.","zh":"這個短語適合用來表達帶支持的建議。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"no matter whether","meaning":"無論是否","examples":[{"en":"You can sign up no matter whether you are nervous or inexperienced.","zh":"無論你是否緊張或缺乏經驗，你都可以報名。"},{"en":"No matter whether means it does not matter if one condition is true or another is true.","zh":"No matter whether 指無論某個條件是否成立，都沒有關係。"},{"en":"You can start exercising no matter whether you are fast or slow.","zh":"無論你跑得快還是慢，都可以開始運動。"},{"en":"This phrase makes advice feel open to different kinds of people.","zh":"這個短語令建議感覺對不同人都開放。"},{"en":"It is useful when removing excuses or fears.","zh":"它適合用來消除藉口或恐懼。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"full of doubts","meaning":"充滿疑慮","examples":[{"en":"Some beginners are nervous, inexperienced and full of doubts.","zh":"有些初學者緊張、缺乏經驗，而且充滿疑慮。"},{"en":"Full of doubts means having many worries and uncertain thoughts.","zh":"Full of doubts 指有很多憂慮和不確定的想法。"},{"en":"Before the first training run, he was full of doubts about his ability.","zh":"第一次訓練跑之前，他對自己的能力充滿疑慮。"},{"en":"Beginners may be full of doubts because they cannot yet imagine finishing.","zh":"初學者可能充滿疑慮，因為他們還不能想像自己完成比賽。"},{"en":"This phrase describes a mind crowded with fear.","zh":"這個短語描述充滿恐懼的心境。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"the first thing","meaning":"第一樣東西","examples":[{"en":"The first thing the marathon gave him was confidence.","zh":"馬拉松給他的第一樣東西是自信。"},{"en":"The first thing means the earliest or most immediate point in a list of ideas.","zh":"The first thing 指一系列想法中最早或最先出現的一點。"},{"en":"The first thing training taught him was to respect his limits.","zh":"訓練教他的第一樣東西是尊重自己的限制。"},{"en":"Writers use this phrase to organise several lessons clearly.","zh":"作者用這個短語清楚組織幾個教訓。"},{"en":"It helps readers know that more points may follow.","zh":"它幫助讀者知道後面可能還有其他重點。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"confidence that no classroom speech could have taught me","meaning":"課堂演講教不到的自信","examples":[{"en":"The marathon gave him confidence that no classroom speech could have taught him.","zh":"馬拉松給了他課堂演講教不到的自信。"},{"en":"This phrase means real experience gave him a kind of confidence that words alone could not give.","zh":"這個短語指真實經驗給了他一種單靠說話無法給予的自信。"},{"en":"A student may gain confidence from finishing a project that no motivational speech could have taught.","zh":"學生完成一個專題後，可能得到勵志演講教不到的自信。"},{"en":"Some lessons become powerful because the learner has lived through them.","zh":"有些教訓之所以有力量，是因為學習者親身經歷過。"},{"en":"This phrase contrasts practical experience with spoken advice.","zh":"這個短語把實際經驗與口頭建議作對比。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"start training","meaning":"開始訓練","examples":[{"en":"Before he started training, he could barely run three kilometres.","zh":"在他開始訓練之前，他幾乎跑不了三公里。"},{"en":"Start training means begin regular practice to prepare for a sport or challenge.","zh":"Start training 指開始有規律地練習，為運動或挑戰作準備。"},{"en":"Beginners should start training slowly instead of running too far on the first day.","zh":"初學者應慢慢開始訓練，而不是第一天就跑太遠。"},{"en":"Starting training early gives the body time to become stronger safely.","zh":"早點開始訓練讓身體有時間安全地變強。"},{"en":"This phrase marks the beginning of preparation.","zh":"這個短語標示準備的開始。"}],"source":"2018 Q2.pdf","sourcePage":3},{"front":"could barely run","meaning":"幾乎跑不了","examples":[{"en":"He could barely run three kilometres at first.","zh":"起初，他幾乎跑不了三公里。"},{"en":"Could barely run means could run only with great difficulty or almost not at all.","zh":"Could barely run 指跑得非常吃力，或幾乎跑不了。"},{"en":"After a long break from exercise, she could barely run around the park.","zh":"很久沒有運動後，她幾乎跑不了公園一圈。"},{"en":"A person who could barely run at first can improve with steady practice.","zh":"起初幾乎跑不了的人，可以透過穩定練習進步。"},{"en":"This phrase shows a weak starting point before progress.","zh":"這個短語顯示進步前的弱起點。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"bargain with myself","meaning":"跟自己討價還價","examples":[{"en":"He kept bargaining with himself during early training runs.","zh":"他在早期訓練跑中不斷跟自己討價還價。"},{"en":"To bargain with myself means to make small mental deals to keep going.","zh":"To bargain with myself 指在心裏和自己作小交易，好讓自己繼續。"},{"en":"I bargained with myself by promising I could rest after the next corner.","zh":"我跟自己討價還價，答應自己跑到下一個街角後可以休息。"},{"en":"Runners bargain with themselves when their bodies want to stop but their minds try to continue.","zh":"當身體想停下而頭腦努力繼續時，跑手會跟自己討價還價。"},{"en":"This phrase shows an inner conversation during difficulty.","zh":"這個短語顯示困難中的內心對話。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"reach the next lamp post","meaning":"跑到下一支燈柱","examples":[{"en":"He told himself to reach the next lamp post before stopping.","zh":"他告訴自己先跑到下一支燈柱才停下。"},{"en":"Reach the next lamp post means run or walk as far as the next street light before resting.","zh":"Reach the next lamp post 指先跑或走到下一支街燈才休息。"},{"en":"Beginners can use the next lamp post as a small, clear target.","zh":"初學者可以把下一支燈柱作為細小而清楚的目標。"},{"en":"Small targets help runners continue when the whole distance feels too big.","zh":"當整段距離感覺太大時，小目標能幫助跑手繼續。"},{"en":"This phrase shows how people break a challenge into manageable parts.","zh":"這個短語顯示人們如何把挑戰拆成可處理的部分。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"slowly but surely","meaning":"慢慢但穩步地","examples":[{"en":"Slowly but surely, his short runs became longer.","zh":"慢慢但穩步地，他的短跑變成較長的跑步。"},{"en":"Slowly but surely means gradually but with steady progress.","zh":"Slowly but surely 指逐漸但穩定地進步。"},{"en":"Slowly but surely, the student improved her English through daily reading.","zh":"慢慢但穩步地，那位學生透過每天閱讀改善英文。"},{"en":"Training works slowly but surely when runners repeat small efforts over time.","zh":"當跑手長時間重複小努力，訓練會慢慢但穩步地見效。"},{"en":"This phrase gives hope because progress does not need to be sudden.","zh":"這個短語帶來希望，因為進步不需要突然出現。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"weekend long run","meaning":"週末長課；週末長跑訓練","examples":[{"en":"The promenade eventually became a weekend long run.","zh":"海濱長廊最終變成他的週末長跑訓練路線。"},{"en":"A weekend long run is a longer training run done on Saturday or Sunday.","zh":"A weekend long run 指在星期六或星期日進行的較長距離訓練跑。"},{"en":"Many marathon plans include a weekend long run to build endurance.","zh":"許多馬拉松計劃包括週末長跑訓練，以建立耐力。"},{"en":"A weekend long run gives runners time to practise distance without rushing to school or work.","zh":"週末長跑訓練讓跑手有時間練習距離，而不用急着上學或上班。"},{"en":"This phrase is common in marathon training.","zh":"這個短語常見於馬拉松訓練。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"the more..., the more...","meaning":"越……就越……","examples":[{"en":"The more he trained, the more confident he became.","zh":"他訓練得越多，就變得越有自信。"},{"en":"The more..., the more... shows that one thing increases as another thing increases.","zh":"The more..., the more... 表示一件事增加時，另一件事也增加。"},{"en":"The more students practise speaking, the more natural they sound.","zh":"學生練習說話越多，聽起來就越自然。"},{"en":"The more runners train sensibly, the more prepared they feel.","zh":"跑手越合理地訓練，就越感到準備充足。"},{"en":"This structure clearly connects effort with result.","zh":"這個結構清楚連接努力和結果。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"arrive suddenly","meaning":"突然出現","examples":[{"en":"Confidence does not arrive suddenly.","zh":"自信不會突然出現。"},{"en":"Arrive suddenly means appear quickly without warning or gradual development.","zh":"Arrive suddenly 指在沒有預告或逐步發展下快速出現。"},{"en":"Fitness does not arrive suddenly after one day of exercise.","zh":"體能不會在運動一天後突然出現。"},{"en":"Confidence usually grows through repeated effort, not sudden magic.","zh":"自信通常透過反覆努力成長，而不是突然像魔法般出現。"},{"en":"This phrase helps explain that real progress takes time.","zh":"這個短語幫助解釋真正進步需要時間。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"built step by step","meaning":"一步一步建立","examples":[{"en":"Confidence is built step by step.","zh":"自信是一步一步建立的。"},{"en":"Built step by step means developed gradually through small actions.","zh":"Built step by step 指透過小行動逐漸建立。"},{"en":"A student’s writing skill is built step by step through practice and feedback.","zh":"學生的寫作能力透過練習和回饋一步一步建立。"},{"en":"Marathon confidence is built step by step each time a runner completes a training run.","zh":"跑手每完成一次訓練跑，馬拉松自信就一步一步建立。"},{"en":"This phrase stresses process instead of instant success.","zh":"這個短語強調過程，而不是即時成功。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"breath by breath","meaning":"一口氣一口氣地","examples":[{"en":"Endurance is built step by step and breath by breath.","zh":"耐力是一步一步、一口氣一口氣地建立的。"},{"en":"Breath by breath means gradually, with each act of breathing during effort.","zh":"Breath by breath 指在努力時隨着每一次呼吸逐漸進行。"},{"en":"During a difficult run, he calmed himself breath by breath.","zh":"在困難的跑步中，他一口氣一口氣地讓自己冷靜下來。"},{"en":"Long-distance running teaches patience because progress comes breath by breath.","zh":"長跑教人耐性，因為進步是一口氣一口氣地來的。"},{"en":"This phrase makes endurance feel physical and slow.","zh":"這個短語令耐力感覺具體而緩慢。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"on race day","meaning":"比賽當日","examples":[{"en":"On race day, he stood among thousands of runners.","zh":"比賽當日，他站在數千名跑手之中。"},{"en":"On race day means on the day when the competition takes place.","zh":"On race day 指比賽舉行的那一天。"},{"en":"On race day, runners wake early, check their shoes, and eat carefully.","zh":"比賽當日，跑手早起、檢查跑鞋，並小心進食。"},{"en":"Months of training become real on race day.","zh":"數月訓練在比賽當日變成真實行動。"},{"en":"This phrase marks the move from preparation to action.","zh":"這個短語標示由準備進入行動。"}],"source":"2018 Q2.pdf","sourcePage":4},{"front":"stand among thousands of runners","meaning":"站在數千名跑手之中","examples":[{"en":"He stood among thousands of runners before sunrise.","zh":"日出前，他站在數千名跑手之中。"},{"en":"To stand among thousands of runners means to be in a large crowd of people ready to race.","zh":"To stand among thousands of runners 指站在準備比賽的大批跑手人群中。"},{"en":"Standing among thousands of runners can make a beginner feel nervous and excited.","zh":"站在數千名跑手之中，可以令初學者既緊張又興奮。"},{"en":"The crowd reminds each runner that the challenge is shared.","zh":"人群提醒每位跑手，這個挑戰是大家一起面對的。"},{"en":"This phrase creates a strong image of race-day atmosphere.","zh":"這個短語營造強烈的比賽日氣氛。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"before sunrise","meaning":"日出前","examples":[{"en":"The runners gathered before sunrise.","zh":"跑手們在日出前聚集。"},{"en":"Before sunrise means before the sun appears in the morning.","zh":"Before sunrise 指早上太陽出現之前。"},{"en":"Many marathon runners arrive before sunrise to prepare calmly.","zh":"許多馬拉松跑手在日出前到達，以便平靜準備。"},{"en":"Training before sunrise shows discipline because most people are still asleep.","zh":"日出前訓練顯示紀律，因為大多數人仍在睡覺。"},{"en":"This phrase adds an early-morning mood to the scene.","zh":"這個短語為場景加入清晨氣氛。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"stomach twist with fear","meaning":"緊張得胃部一縮","examples":[{"en":"He felt his stomach twist with fear before the race.","zh":"比賽前，他緊張得胃部一縮。"},{"en":"Stomach twist with fear means feel so nervous that the stomach seems tight or uncomfortable.","zh":"Stomach twist with fear 指緊張到胃部像收緊或不舒服。"},{"en":"My stomach twisted with fear before I gave my first speech.","zh":"第一次演講前，我緊張得胃部一縮。"},{"en":"Before a marathon, fear can feel physical, not just mental.","zh":"馬拉松前，恐懼可以是身體感覺，而不只是心理感覺。"},{"en":"This phrase shows anxiety through the body.","zh":"這個短語透過身體表現焦慮。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"What if...?","meaning":"如果……怎麼辦","examples":[{"en":"He kept asking himself, “What if I give up?”","zh":"他不斷問自己：「如果我放棄怎麼辦？」"},{"en":"What if...? introduces a worried question about a possible problem.","zh":"What if...? 用來提出關於可能問題的擔心。"},{"en":"What if I cramp before the final stretch?","zh":"如果我在最後一段路前抽筋怎麼辦？"},{"en":"People often ask “What if...?” when fear makes them imagine failure.","zh":"當恐懼令人想像失敗時，人們常會問 “What if...?”"},{"en":"This phrase shows uncertainty before an important action.","zh":"這個短語顯示重要行動前的不確定。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"cramp","meaning":"抽筋","examples":[{"en":"He worried that he might cramp during the marathon.","zh":"他擔心自己在馬拉松期間可能會抽筋。"},{"en":"Cramp means a sudden painful tightening of a muscle.","zh":"Cramp 指肌肉突然疼痛地收緊。"},{"en":"A runner may cramp if they are tired, dehydrated, or poorly prepared.","zh":"如果跑手疲倦、缺水或準備不足，可能會抽筋。"},{"en":"Stretching, pacing, and drinking properly can reduce the risk of cramp.","zh":"伸展、控制速度和適當飲水可以減低抽筋風險。"},{"en":"This word is important in sports and health contexts.","zh":"這個詞在運動和健康語境中很重要。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"give up","meaning":"放棄","examples":[{"en":"He worried that he might give up before the finish line.","zh":"他擔心自己可能在終點線前放棄。"},{"en":"Give up means stop trying before completing something.","zh":"Give up 指在完成某事前停止嘗試。"},{"en":"A tired runner may want to give up when the road feels endless.","zh":"當道路像沒有盡頭，疲累的跑手可能想放棄。"},{"en":"Encouragement helps people continue when they are close to giving up.","zh":"當人們快要放棄時，鼓勵能幫助他們繼續。"},{"en":"This phrase is useful for talking about persistence and failure.","zh":"這個短語適合用來談堅持和失敗。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"better prepared","meaning":"準備得更好","examples":[{"en":"He wondered whether everyone else was better prepared.","zh":"他 wondered 其他人是否都準備得更好。"},{"en":"Better prepared means more ready because of stronger training, planning, or knowledge.","zh":"Better prepared 指因訓練、計劃或知識較強而準備更充分。"},{"en":"Some runners looked better prepared because they had proper shoes and calm faces.","zh":"有些跑手看起來準備得更好，因為他們有合適跑鞋和平靜表情。"},{"en":"Feeling less prepared than others can increase nervousness before a race.","zh":"覺得自己比別人準備不足，會增加賽前緊張。"},{"en":"This phrase compares levels of readiness.","zh":"這個短語比較準備程度。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"the starting signal sounded","meaning":"起步訊號響起","examples":[{"en":"The starting signal sounded, and all he could do was move forward.","zh":"起步訊號響起，他唯一能做的就是向前跑。"},{"en":"The starting signal sounded means the sound that begins the race was heard.","zh":"The starting signal sounded 指開始比賽的聲音響起。"},{"en":"When the starting signal sounded, thousands of runners began to move.","zh":"起步訊號響起時，數千名跑手開始移動。"},{"en":"A starting signal turns waiting into action.","zh":"起步訊號把等待變成行動。"},{"en":"This phrase marks the official beginning of a race.","zh":"這個短語標示比賽正式開始。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"move forward","meaning":"向前走；向前跑","examples":[{"en":"After the signal sounded, he simply moved forward.","zh":"訊號響起後，他只是向前跑。"},{"en":"Move forward means go ahead physically or continue despite fear.","zh":"Move forward 指身體向前移動，或即使害怕仍繼續前進。"},{"en":"When the race began, he stopped thinking and moved forward.","zh":"比賽開始時，他停止多想，只是向前跑。"},{"en":"In life, moving forward can mean taking the next step even without full confidence.","zh":"在人生中，向前走可以指即使沒有完全信心仍踏出下一步。"},{"en":"This phrase connects physical movement with mental courage.","zh":"這個短語把身體動作與心理勇氣連接起來。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time he reached the final stretch, his mind was clear.","zh":"到他跑到最後一段路時，他的頭腦很清晰。"},{"en":"By the time means when a particular point or moment has arrived.","zh":"By the time 指某個特定時刻或階段到來時。"},{"en":"By the time the sun rose, the runners had already covered several kilometres.","zh":"到太陽升起時，跑手已經跑了幾公里。"},{"en":"This phrase connects a later moment with a result or change.","zh":"這個短語把較後的時刻與結果或變化連接起來。"},{"en":"It is useful for showing progress across time.","zh":"它適合用來顯示隨時間推進的進展。"}],"source":"2018 Q2.pdf","sourcePage":5},{"front":"final stretch","meaning":"最後一段路","examples":[{"en":"His legs were heavy when he reached the final stretch.","zh":"他跑到最後一段路時，雙腿很沉重。"},{"en":"The final stretch is the last part of a race, journey, or difficult task.","zh":"Final stretch 指比賽、旅程或困難任務的最後部分。"},{"en":"Runners often need the most mental strength during the final stretch.","zh":"跑手在最後一段路常最需要心理力量。"},{"en":"The final stretch feels hard because the body is tired but the goal is close.","zh":"最後一段路很艱難，因為身體疲累，但目標已接近。"},{"en":"This phrase can be used for races, exams, and long projects.","zh":"這個短語可用於比賽、考試和長期專題。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"legs were heavy","meaning":"雙腿沉重","examples":[{"en":"His legs were heavy near the end of the race.","zh":"比賽接近尾聲時，他雙腿沉重。"},{"en":"Legs were heavy means the legs felt tired, slow, and difficult to lift.","zh":"Legs were heavy 指雙腿感到疲倦、遲緩，難以提起。"},{"en":"After twenty kilometres, my legs were heavy but I kept moving.","zh":"跑了二十公里後，我雙腿沉重，但仍繼續前進。"},{"en":"Heavy legs show physical tiredness after long effort.","zh":"雙腿沉重顯示長時間努力後的身體疲勞。"},{"en":"This phrase helps readers feel the runner’s exhaustion.","zh":"這個短語幫助讀者感受跑手的疲憊。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"strangely clear","meaning":"異常清晰","examples":[{"en":"His mind was strangely clear during the final stretch.","zh":"在最後一段路，他的頭腦異常清晰。"},{"en":"Strangely clear means unexpectedly calm, focused, and easy to understand.","zh":"Strangely clear 指出乎意料地平靜、專注和清楚。"},{"en":"Although his body was tired, his mind became strangely clear.","zh":"雖然身體疲累，他的頭腦卻變得異常清晰。"},{"en":"Difficult moments can make priorities strangely clear because only the next step matters.","zh":"困難時刻可以令人優先次序異常清晰，因為只剩下一步最重要。"},{"en":"This phrase shows an unexpected mental state.","zh":"這個短語顯示出乎意料的心理狀態。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"prove to myself that","meaning":"向自己證明","examples":[{"en":"He proved to himself that he could face something difficult.","zh":"他向自己證明自己能面對困難的事。"},{"en":"Prove to myself that means show myself through action that something is true.","zh":"Prove to myself that 指透過行動向自己顯示某事是真的。"},{"en":"I wanted to prove to myself that I could finish a hard task without quitting.","zh":"我想向自己證明，我可以不放棄地完成困難任務。"},{"en":"Crossing the finish line proves to a runner that effort can change limits.","zh":"衝過終點線向跑手證明，努力可以改變限制。"},{"en":"This phrase is about self-belief, not showing off to others.","zh":"這個短語關於自我信念，而不是向別人炫耀。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"face something difficult","meaning":"面對困難的事","examples":[{"en":"The marathon taught him to face something difficult.","zh":"馬拉松教會他面對困難的事。"},{"en":"To face something difficult means to deal with a challenge instead of avoiding it.","zh":"To face something difficult 指處理挑戰，而不是避開它。"},{"en":"Students face something difficult when they keep trying after failing a test.","zh":"學生考試失敗後仍繼續努力，就是面對困難的事。"},{"en":"Running a marathon teaches people to stay present with discomfort.","zh":"跑馬拉松教人與不舒服感共處，不逃避當下。"},{"en":"This phrase shows courage through action.","zh":"這個短語透過行動顯示勇氣。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"without running away from it","meaning":"而不是逃避它","examples":[{"en":"He faced the challenge without running away from it.","zh":"他面對挑戰，而不是逃避它。"},{"en":"Without running away from it means without avoiding or escaping the problem.","zh":"Without running away from it 指不避開或逃離問題。"},{"en":"She talked to her teacher without running away from the difficult conversation.","zh":"她和老師談那段困難對話，而不是逃避它。"},{"en":"A marathon forces runners to meet tiredness without running away from it.","zh":"馬拉松迫使跑手面對疲累，而不是逃避它。"},{"en":"This phrase contrasts courage with avoidance.","zh":"這個短語把勇氣與逃避作對比。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"feel judged by","meaning":"感到被……評價","examples":[{"en":"Young people often feel judged by marks and rankings.","zh":"年輕人常感到被分數和排名評價。"},{"en":"Feel judged by means feel that others measure your value using something.","zh":"Feel judged by 指感到別人用某些東西衡量自己的價值。"},{"en":"Students may feel judged by exam scores even when they work hard.","zh":"學生即使努力，也可能感到被考試分數評價。"},{"en":"Feeling judged by numbers can make young people forget their other strengths.","zh":"感到被數字評價，可能令年輕人忘記自己的其他優點。"},{"en":"This phrase describes pressure from outside standards.","zh":"這個短語描述來自外在標準的壓力。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"marks, rankings and expectations","meaning":"分數、排名和期望","examples":[{"en":"Students often feel judged by marks, rankings and expectations.","zh":"學生常感到被分數、排名和期望評價。"},{"en":"Marks, rankings and expectations are scores, positions, and hopes that others place on students.","zh":"Marks, rankings and expectations 指分數、名次，以及別人放在學生身上的期望。"},{"en":"Marks show exam results, rankings compare students, and expectations create pressure.","zh":"分數顯示考試結果，排名比較學生，期望則製造壓力。"},{"en":"Young people need confidence beyond marks, rankings and expectations.","zh":"年輕人需要超越分數、排名和期望的自信。"},{"en":"This phrase summarises common school pressures.","zh":"這個短語總結常見的學校壓力。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"that lesson is priceless","meaning":"那個教訓十分寶貴","examples":[{"en":"For young people, that lesson is priceless.","zh":"對年輕人來說，那個教訓十分寶貴。"},{"en":"That lesson is priceless means the lesson is extremely valuable and cannot be measured by money.","zh":"That lesson is priceless 指那個教訓極有價值，不能用金錢衡量。"},{"en":"Learning that failure is not the end is priceless for students.","zh":"學會失敗不是終點，對學生來說十分寶貴。"},{"en":"The marathon’s lesson is priceless because it changes how young people face difficulty.","zh":"馬拉松的教訓十分寶貴，因為它改變年輕人面對困難的方式。"},{"en":"This phrase strongly praises the value of an experience.","zh":"這個短語強烈讚賞一段經歷的價值。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"health goes beyond","meaning":"健康不止於","examples":[{"en":"Health goes beyond simply looking fit.","zh":"健康不止於看起來健美。"},{"en":"Health goes beyond means health includes more than one surface idea.","zh":"Health goes beyond 指健康包括多於一個表面概念。"},{"en":"Health goes beyond weight, because sleep, mood, and energy also matter.","zh":"健康不止於體重，因為睡眠、情緒和精力也重要。"},{"en":"Running teaches that health is not only about appearance but also habits and balance.","zh":"跑步教人明白，健康不只是外表，也包括習慣和平衡。"},{"en":"This phrase expands a narrow idea into a broader one.","zh":"這個短語把狹窄想法擴闊成更廣泛的概念。"}],"source":"2018 Q2.pdf","sourcePage":6},{"front":"looking fit","meaning":"看起來健美","examples":[{"en":"Health is about more than simply looking fit.","zh":"健康不只是看起來健美。"},{"en":"Looking fit means appearing strong, slim, or sporty on the outside.","zh":"Looking fit 指外表看起來強壯、苗條或有運動感。"},{"en":"Someone may look fit but still sleep poorly or feel stressed.","zh":"有人可能看起來健美，但仍睡得不好或感到壓力大。"},{"en":"Training for a marathon should focus on real health, not only looking fit.","zh":"馬拉松訓練應集中於真正健康，而不只是看起來健美。"},{"en":"This phrase contrasts appearance with actual well-being.","zh":"這個短語把外貌與真正身心健康作對比。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"respect your body and mind","meaning":"尊重自己的身體和心靈","examples":[{"en":"Health is about respecting your body and mind.","zh":"健康是關於尊重自己的身體和心靈。"},{"en":"Respect your body and mind means care for both physical needs and mental well-being.","zh":"Respect your body and mind 指照顧身體需要和心理健康。"},{"en":"Runners respect their body and mind by resting when they are injured or exhausted.","zh":"跑手受傷或筋疲力竭時休息，就是尊重自己的身體和心靈。"},{"en":"Eating properly and sleeping earlier are ways to respect your body and mind.","zh":"好好進食和早點睡，都是尊重身體和心靈的方法。"},{"en":"This phrase teaches balanced health.","zh":"這個短語教人平衡地理解健康。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"sleep earlier","meaning":"早點睡","examples":[{"en":"Training taught him to sleep earlier.","zh":"訓練教會他早點睡。"},{"en":"Sleep earlier means go to bed at an earlier time than before.","zh":"Sleep earlier 指比以前更早上床睡覺。"},{"en":"Runners sleep earlier so their bodies can recover before morning training.","zh":"跑手早點睡，讓身體在早晨訓練前恢復。"},{"en":"A student may focus better in class after learning to sleep earlier.","zh":"學生學會早點睡後，上課可能更能集中。"},{"en":"This phrase describes a healthy habit built through discipline.","zh":"這個短語描述透過紀律建立的健康習慣。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"eat properly","meaning":"好好進食","examples":[{"en":"He learnt to eat properly during training.","zh":"他在訓練期間學會好好進食。"},{"en":"Eat properly means eat enough healthy food in a sensible way.","zh":"Eat properly 指以合理方式進食足夠而健康的食物。"},{"en":"Marathon training requires runners to eat properly so they have energy.","zh":"馬拉松訓練要求跑手好好進食，才有足夠能量。"},{"en":"Eating properly is different from eating snacks whenever you feel tired.","zh":"好好進食不同於一累就吃零食。"},{"en":"This phrase connects food with health and preparation.","zh":"這個短語把食物與健康和準備連接起來。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"survive on","meaning":"靠……勉強過活","examples":[{"en":"He stopped surviving on snacks and excuses.","zh":"他不再靠零食和藉口勉強過活。"},{"en":"Survive on means manage to live or continue using only something limited or unhealthy.","zh":"Survive on 指只靠有限或不健康的東西勉強生活或繼續。"},{"en":"A student cannot survive on instant noodles and four hours of sleep forever.","zh":"學生不能永遠靠即食麵和四小時睡眠勉強過活。"},{"en":"Runners need real meals, not just surviving on sugar and hope.","zh":"跑手需要真正的飯餐，而不是只靠糖分和希望勉強支撐。"},{"en":"This phrase often suggests the habit is not good enough.","zh":"這個短語常暗示這種習慣並不足夠好。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"endless excuses","meaning":"沒完沒了的藉口","examples":[{"en":"Training helped him stop relying on endless excuses.","zh":"訓練幫助他停止依賴沒完沒了的藉口。"},{"en":"Endless excuses are repeated reasons people give to avoid doing something.","zh":"Endless excuses 指人們為逃避做某事而反覆提出的理由。"},{"en":"“I am too tired” became one of his endless excuses before he started training.","zh":"在開始訓練前，「我太累」成了他沒完沒了的藉口之一。"},{"en":"Endless excuses keep people from beginning even when the goal matters.","zh":"沒完沒了的藉口會阻止人開始，即使目標很重要。"},{"en":"This phrase criticises repeated avoidance.","zh":"這個短語批評反覆逃避。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"clear my head","meaning":"令頭腦清醒","examples":[{"en":"Running became the best way to clear his head.","zh":"跑步成了令他頭腦清醒的最好方法。"},{"en":"To clear my head means to calm my mind and think more clearly.","zh":"To clear my head 指令頭腦平靜下來，並思考得更清楚。"},{"en":"After a stressful lesson, a short walk can help me clear my head.","zh":"壓力大的課堂後，短短散步可以幫我令頭腦清醒。"},{"en":"Running can clear your head because breathing and movement reduce mental noise.","zh":"跑步可以令頭腦清醒，因為呼吸和動作能減少心理雜音。"},{"en":"This phrase connects physical activity with mental calm.","zh":"這個短語把身體活動和心理平靜連接起來。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"schoolwork felt overwhelming","meaning":"課業令人不勝負荷","examples":[{"en":"A short jog helped whenever schoolwork felt overwhelming.","zh":"每當課業令人不勝負荷，短短慢跑都能幫助他。"},{"en":"Schoolwork felt overwhelming means homework or study felt too much to handle.","zh":"Schoolwork felt overwhelming 指功課或學習內容多到難以應付。"},{"en":"Before exams, schoolwork may feel overwhelming because deadlines arrive together.","zh":"考試前，課業可能令人不勝負荷，因為限期一起到來。"},{"en":"When schoolwork feels overwhelming, a short break can help students return calmly.","zh":"當課業令人不勝負荷，短暫休息可以幫助學生平靜地回來。"},{"en":"This phrase describes stress caused by study pressure.","zh":"這個短語描述由學習壓力造成的焦慮。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"short jog","meaning":"短跑；慢跑一會","examples":[{"en":"A short jog helped him breathe and think.","zh":"短短慢跑幫助他呼吸和思考。"},{"en":"A short jog is a brief, gentle run, usually not very fast or long.","zh":"A short jog 指短時間、輕鬆的慢跑，通常不太快也不太長。"},{"en":"A short jog after school can refresh a tired student.","zh":"放學後慢跑一會，可以令疲累學生恢復精神。"},{"en":"Beginners can start with a short jog before trying longer distances.","zh":"初學者可以先從短短慢跑開始，再嘗試更長距離。"},{"en":"This phrase describes a simple form of exercise.","zh":"這個短語描述一種簡單運動方式。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"return stronger","meaning":"以更好的狀態回來","examples":[{"en":"After running, he could return stronger.","zh":"跑步後，他能以更好的狀態回來。"},{"en":"Return stronger means come back with more energy, confidence, or calmness.","zh":"Return stronger 指帶着更多精力、信心或平靜回來。"},{"en":"After a short jog, the student returned stronger and finished his homework.","zh":"短跑後，那位學生以更好的狀態回來並完成了功課。"},{"en":"Rest and exercise can help people return stronger after stress.","zh":"休息和運動可以幫助人在壓力後以更好的狀態回來。"},{"en":"This phrase shows recovery and improvement.","zh":"這個短語顯示恢復和進步。"}],"source":"2018 Q2.pdf","sourcePage":7},{"front":"preparation is essential","meaning":"準備是必要的","examples":[{"en":"Preparation is essential before running a marathon.","zh":"跑馬拉松前，準備是必要的。"},{"en":"Preparation is essential means careful planning and practice are necessary.","zh":"Preparation is essential 指仔細計劃和練習是必需的。"},{"en":"Preparation is essential before an exam because guessing is not enough.","zh":"考試前準備是必要的，因為單靠猜測並不足夠。"},{"en":"Marathon preparation is essential because the distance can harm an untrained body.","zh":"馬拉松準備是必要的，因為距離可能傷害未受訓練的身體。"},{"en":"This phrase gives serious practical advice.","zh":"這個短語給出嚴肅而實用的建議。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"rush into","meaning":"倉促投入","examples":[{"en":"You should not rush into a full marathon without training.","zh":"你不應在沒有訓練下倉促投入全程馬拉松。"},{"en":"Rush into means start something too quickly without enough preparation.","zh":"Rush into 指在沒有足夠準備下太快開始某事。"},{"en":"Students should not rush into answering before reading the question carefully.","zh":"學生不應未仔細讀題就倉促回答。"},{"en":"Rushing into a marathon can turn excitement into injury.","zh":"倉促投入馬拉松可能把興奮變成受傷。"},{"en":"This phrase warns against careless speed.","zh":"這個短語提醒人不要草率求快。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"full marathon","meaning":"全程馬拉松","examples":[{"en":"A full marathon requires serious training.","zh":"全程馬拉松需要認真訓練。"},{"en":"A full marathon is a race of 42.195 kilometres.","zh":"A full marathon 指 42.195 公里的比賽。"},{"en":"Beginners may train for shorter races before attempting a full marathon.","zh":"初學者嘗試全程馬拉松前，可能先為較短比賽訓練。"},{"en":"A full marathon tests endurance, pacing, and mental strength.","zh":"全程馬拉松考驗耐力、配速和心理力量。"},{"en":"This phrase distinguishes the complete marathon distance from shorter events.","zh":"這個短語把完整馬拉松距離與較短賽事分開。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"excitement may turn into injury","meaning":"興奮可能變成受傷","examples":[{"en":"Without training, excitement may turn into injury.","zh":"沒有訓練，興奮可能變成受傷。"},{"en":"Excitement may turn into injury means enthusiasm can lead to physical harm if someone is careless.","zh":"Excitement may turn into injury 指如果人太草率，熱情可能導致身體受傷。"},{"en":"A beginner who runs too far too soon may turn excitement into injury.","zh":"初學者太快跑太遠，可能把興奮變成受傷。"},{"en":"Careful preparation protects runners from hurting themselves.","zh":"仔細準備可以保護跑手免於弄傷自己。"},{"en":"This phrase warns that motivation still needs wisdom.","zh":"這個短語提醒人，有動力仍需要智慧。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"start with short distances","meaning":"從短距離開始","examples":[{"en":"Beginners should start with short distances.","zh":"初學者應該從短距離開始。"},{"en":"Start with short distances means begin by running or walking manageable lengths.","zh":"Start with short distances 指先跑或走自己能處理的距離。"},{"en":"A new runner may start with short distances such as one or two kilometres.","zh":"新跑手可以從一至兩公里等短距離開始。"},{"en":"Short distances help the body adapt before longer training begins.","zh":"短距離幫助身體適應，然後才開始較長訓練。"},{"en":"This phrase gives safe advice for beginners.","zh":"這個短語為初學者提供安全建議。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"join a running group","meaning":"加入跑步小組","examples":[{"en":"Joining a running group can help beginners train safely.","zh":"加入跑步小組可以幫助初學者安全訓練。"},{"en":"Join a running group means become part of a group that runs together regularly.","zh":"Join a running group 指加入一個定期一起跑步的群組。"},{"en":"A running group can give beginners advice, company, and motivation.","zh":"跑步小組可以給初學者建議、陪伴和動力。"},{"en":"People are less likely to quit when they train with others.","zh":"當人們和別人一起訓練，就較不容易放棄。"},{"en":"This phrase connects exercise with community support.","zh":"這個短語把運動和社群支持連接起來。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"follow a sensible plan","meaning":"跟從合理的計劃","examples":[{"en":"Beginners should follow a sensible training plan.","zh":"初學者應跟從合理的訓練計劃。"},{"en":"Follow a sensible plan means use a realistic and safe plan instead of guessing.","zh":"Follow a sensible plan 指使用實際而安全的計劃，而不是胡亂猜測。"},{"en":"A sensible plan increases distance gradually and includes rest days.","zh":"合理的計劃會逐漸增加距離，並包括休息日。"},{"en":"Runners who follow a sensible plan are less likely to get injured.","zh":"跟從合理計劃的跑手較不容易受傷。"},{"en":"This phrase stresses careful progress.","zh":"這個短語強調小心地進步。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"listen to your body","meaning":"聆聽身體的訊號","examples":[{"en":"Runners should listen to their bodies during training.","zh":"跑手訓練期間應聆聽身體的訊號。"},{"en":"Listen to your body means notice pain, tiredness, hunger, and other physical signals.","zh":"Listen to your body 指留意痛楚、疲累、飢餓和其他身體訊號。"},{"en":"If your knee hurts sharply, listen to your body and rest.","zh":"如果膝蓋劇痛，就要聆聽身體的訊號並休息。"},{"en":"Good runners do not ignore warning signs just to look tough.","zh":"好跑手不會為了顯得堅強而無視警告訊號。"},{"en":"This phrase teaches safe self-awareness.","zh":"這個短語教人安全地自我覺察。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"no shame in","meaning":"……並不羞恥","examples":[{"en":"There is no shame in walking for a while.","zh":"走一會兒並不羞恥。"},{"en":"No shame in means something is acceptable and should not make you feel embarrassed.","zh":"No shame in 指某事可以接受，不應令人感到尷尬。"},{"en":"There is no shame in asking for help when training feels confusing.","zh":"訓練令人困惑時，求助並不羞恥。"},{"en":"Walking during a race can be smart if it prevents injury.","zh":"比賽中走一會兒如果能避免受傷，就是明智的。"},{"en":"This phrase removes unnecessary embarrassment.","zh":"這個短語消除不必要的羞恥感。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"walking for a while","meaning":"走一會兒","examples":[{"en":"There is no shame in walking for a while during a race.","zh":"比賽中走一會兒並不羞恥。"},{"en":"Walking for a while means walking for a short period before running again.","zh":"Walking for a while 指短時間步行，之後再跑。"},{"en":"A tired runner may recover by walking for a while.","zh":"疲累的跑手可以透過走一會兒恢復。"},{"en":"Walking for a while can help control breathing and prevent panic.","zh":"走一會兒可以幫助控制呼吸並防止慌張。"},{"en":"This phrase shows a temporary pause, not failure.","zh":"這個短語顯示暫時停頓，而不是失敗。"}],"source":"2018 Q2.pdf","sourcePage":8},{"front":"no glory in","meaning":"……並不光榮","examples":[{"en":"There is no glory in ignoring pain.","zh":"無視痛楚並不光榮。"},{"en":"No glory in means something is not admirable, even if it may look brave.","zh":"No glory in 指某事並不值得敬佩，即使看起來好像勇敢。"},{"en":"There is no glory in studying all night if your health suffers.","zh":"如果健康受損，通宵溫習並不光榮。"},{"en":"There is no glory in running through serious pain and making an injury worse.","zh":"帶着嚴重痛楚繼續跑並令傷勢惡化，並不光榮。"},{"en":"This phrase corrects a false idea of bravery.","zh":"這個短語糾正對勇敢的錯誤理解。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"ignoring pain","meaning":"無視痛楚","examples":[{"en":"Ignoring pain can lead to injury.","zh":"無視痛楚可能導致受傷。"},{"en":"Ignoring pain means pretending physical discomfort or warning signs are not there.","zh":"Ignoring pain 指假裝身體不適或警告訊號不存在。"},{"en":"A runner who ignores knee pain may need weeks to recover later.","zh":"無視膝痛的跑手之後可能需要幾星期恢復。"},{"en":"Ignoring pain is different from dealing with ordinary tiredness.","zh":"無視痛楚不同於處理普通疲累。"},{"en":"This phrase warns people to protect their bodies.","zh":"這個短語提醒人保護身體。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"what matters is not..., but...","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not pretending to be invincible, but improving safely.","zh":"重要的不是假裝自己無敵，而是安全地進步。"},{"en":"What matters is not..., but... points away from the wrong priority and toward the right one.","zh":"What matters is not..., but... 把人從錯誤重點帶向正確重點。"},{"en":"What matters is not running fastest, but finishing safely and honestly.","zh":"重要的不是跑得最快，而是安全而誠實地完成。"},{"en":"This structure helps explain the real value of a challenge.","zh":"這個結構幫助解釋挑戰的真正價值。"},{"en":"It is useful for giving balanced advice.","zh":"它適合用來給出平衡建議。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"pretend to be invincible","meaning":"假裝自己無敵","examples":[{"en":"Runners should not pretend to be invincible.","zh":"跑手不應假裝自己無敵。"},{"en":"Pretend to be invincible means act as if nothing can hurt or stop you.","zh":"Pretend to be invincible 指表現得好像沒有任何東西能傷害或阻止自己。"},{"en":"A student pretending to be invincible may hide stress until it becomes serious.","zh":"假裝自己無敵的學生可能隱藏壓力，直到問題變嚴重。"},{"en":"Runners who pretend to be invincible may ignore pain and get injured.","zh":"假裝自己無敵的跑手可能無視痛楚並受傷。"},{"en":"This phrase criticises false toughness.","zh":"這個短語批評虛假的堅強。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"disciplined enough to","meaning":"有足夠紀律去","examples":[{"en":"He became disciplined enough to improve safely.","zh":"他變得有足夠紀律去安全地進步。"},{"en":"Disciplined enough to means having enough self-control to do something properly.","zh":"Disciplined enough to 指有足夠自制力去正確完成某事。"},{"en":"A runner must be disciplined enough to rest when the plan says rest.","zh":"跑手必須有足夠紀律在計劃要求休息時休息。"},{"en":"Students who are disciplined enough to revise regularly feel less panic before exams.","zh":"有足夠紀律定期溫習的學生，在考試前較少驚慌。"},{"en":"This phrase connects self-control with a positive result.","zh":"這個短語把自制力與正面結果連接起來。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"improve safely","meaning":"安全地進步","examples":[{"en":"A sensible plan helps runners improve safely.","zh":"合理的計劃幫助跑手安全地進步。"},{"en":"Improve safely means get better without causing harm or injury.","zh":"Improve safely 指在不造成傷害或受傷的情況下變得更好。"},{"en":"Beginners improve safely when they increase distance slowly.","zh":"初學者慢慢增加距離時，就能安全地進步。"},{"en":"Rest days help runners improve safely because the body needs time to recover.","zh":"休息日幫助跑手安全地進步，因為身體需要時間恢復。"},{"en":"This phrase shows that progress should not be reckless.","zh":"這個短語顯示進步不應魯莽。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"what surprised me most","meaning":"最令我驚訝的是","examples":[{"en":"What surprised him most was the sense of community.","zh":"最令他驚訝的是那種社群感。"},{"en":"What surprised me most introduces the most unexpected part of an experience.","zh":"What surprised me most 用來引出經歷中最出乎意料的部分。"},{"en":"What surprised me most about the race was how kind strangers were.","zh":"最令我驚訝的是，比賽中陌生人如此友善。"},{"en":"Writers use this phrase when reality is different from expectation.","zh":"當現實與預期不同時，作者會用這個短語。"},{"en":"This phrase prepares readers for an important discovery.","zh":"這個短語讓讀者準備看見重要發現。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"sense of community","meaning":"社群感；社區連結感","examples":[{"en":"The marathon gave him a strong sense of community.","zh":"馬拉松給了他強烈的社群感。"},{"en":"A sense of community is the feeling that people belong together and support one another.","zh":"Sense of community 指人們感到彼此同屬一群並互相支持。"},{"en":"Volunteers, runners, and cheering families created a sense of community.","zh":"義工、跑手和打氣的家人創造了社群感。"},{"en":"A strong sense of community can make a lonely challenge feel shared.","zh":"強烈的社群感可以令孤單挑戰變成共同經歷。"},{"en":"This phrase describes emotional connection among people.","zh":"這個短語描述人與人之間的情感連結。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"expect something to be lonely","meaning":"以為……會很孤單","examples":[{"en":"He had expected the marathon to be lonely.","zh":"他原以為馬拉松會很孤單。"},{"en":"Expect something to be lonely means think an experience will feel isolated or without support.","zh":"Expect something to be lonely 指以為某段經歷會令人孤立或沒有支持。"},{"en":"She expected studying abroad to be lonely before she met kind classmates.","zh":"她在遇見友善同學前，以為海外留學會很孤單。"},{"en":"A runner may expect a marathon to be lonely because each person must move their own legs.","zh":"跑手可能以為馬拉松會很孤單，因為每個人都要靠自己的雙腿前進。"},{"en":"This phrase shows an assumption that may later be proved wrong.","zh":"這個短語顯示之後可能被推翻的假設。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"one runner, one road, one battle","meaning":"一個跑手、一條路、一場戰鬥","examples":[{"en":"He imagined the marathon as one runner, one road and one battle.","zh":"他把馬拉松想像成一個跑手、一條路、一場戰鬥。"},{"en":"“One runner, one road, one battle” means a challenge that seems lonely and personal.","zh":"“One runner, one road, one battle” 指看似孤單而個人的挑戰。"},{"en":"Before the race, he thought only of himself, the road, and the struggle ahead.","zh":"比賽前，他只想到自己、道路和前方的掙扎。"},{"en":"The crowd later proved that the marathon was more than one private battle.","zh":"人群後來證明馬拉松不只是一場個人的戰鬥。"},{"en":"This phrase creates a dramatic image of individual struggle.","zh":"這個短語營造個人奮鬥的戲劇化畫面。"}],"source":"2018 Q2.pdf","sourcePage":9},{"front":"prove someone downright wrong","meaning":"證明某人完全錯了","examples":[{"en":"The experience proved him downright wrong.","zh":"這段經歷證明他完全錯了。"},{"en":"To prove someone downright wrong means show clearly that their belief was completely mistaken.","zh":"To prove someone downright wrong 指清楚顯示某人的信念完全錯誤。"},{"en":"He thought strangers would ignore him, but their support proved him downright wrong.","zh":"他以為陌生人會忽視他，但他們的支持證明他完全錯了。"},{"en":"A real experience can prove someone wrong more powerfully than advice can.","zh":"真實經歷比建議更有力地證明一個人錯了。"},{"en":"This phrase strongly emphasises a corrected belief.","zh":"這個短語強烈強調被糾正的信念。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"hand out water","meaning":"派發水","examples":[{"en":"Volunteers handed out water to the runners.","zh":"義工向跑手派發水。"},{"en":"Hand out water means give bottles or cups of water to many people.","zh":"Hand out water 指向很多人派發瓶裝水或杯裝水。"},{"en":"Students handed out water during sports day to help classmates stay hydrated.","zh":"學生在運動會派發水，幫助同學保持水分。"},{"en":"Volunteers who hand out water help runners continue safely.","zh":"派發水的義工幫助跑手安全地繼續。"},{"en":"This phrase describes practical support in a public event.","zh":"這個短語描述公共活動中的實際支援。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"as bright as medals","meaning":"像獎牌一樣耀眼","examples":[{"en":"Volunteers smiled as bright as medals.","zh":"義工的笑容像獎牌一樣耀眼。"},{"en":"As bright as medals means shining, cheerful, or encouraging like prize medals.","zh":"As bright as medals 指像獎牌一樣閃亮、開朗或令人鼓舞。"},{"en":"The children’s faces were as bright as medals when they finished the race.","zh":"孩子們完成比賽時，臉上的表情像獎牌一樣耀眼。"},{"en":"A smile as bright as a medal can encourage a tired runner.","zh":"像獎牌一樣耀眼的笑容可以鼓勵疲累的跑手。"},{"en":"This phrase uses comparison to make kindness feel visible.","zh":"這個短語用比較令善意變得可見。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"shout encouragement","meaning":"大聲打氣","examples":[{"en":"Strangers shouted encouragement from the roadside.","zh":"陌生人在路邊大聲打氣。"},{"en":"Shout encouragement means call out supportive words loudly.","zh":"Shout encouragement 指大聲喊出支持的說話。"},{"en":"Parents shouted encouragement as students ran around the school field.","zh":"學生繞着操場跑時，父母大聲打氣。"},{"en":"During a marathon, shouted encouragement can help tired runners keep moving.","zh":"在馬拉松期間，大聲打氣可以幫助疲累跑手繼續前進。"},{"en":"This phrase shows active support from others.","zh":"這個短語顯示他人的主動支持。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"Keep going","meaning":"繼續加油","examples":[{"en":"Strangers shouted, “Keep going!” during the race.","zh":"比賽期間，陌生人大喊：「繼續加油！」"},{"en":"Keep going means continue and do not stop.","zh":"Keep going 指繼續，不要停下來。"},{"en":"A teacher may say “Keep going” when a student is close to solving a hard problem.","zh":"當學生快要解開難題時，老師可能會說：「繼續加油。」"},{"en":"Hearing “Keep going” can give a tired runner just enough strength for the next step.","zh":"聽到 “Keep going” 可以給疲累跑手足夠力量踏出下一步。"},{"en":"This phrase is short, simple, and encouraging.","zh":"這個短語簡短、直接，而且鼓舞人心。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"as if they had known me for years","meaning":"好像認識我多年一樣","examples":[{"en":"They encouraged him as if they had known him for years.","zh":"他們鼓勵他，好像認識他多年一樣。"},{"en":"As if they had known me for years means like old friends, even though they were strangers.","zh":"As if they had known me for years 指像老朋友一樣，雖然其實是陌生人。"},{"en":"The volunteers cheered for each runner as if they had known them for years.","zh":"義工為每位跑手打氣，好像認識他們多年一樣。"},{"en":"This phrase shows warmth that feels surprisingly personal.","zh":"這個短語顯示出乎意料地個人的溫暖。"},{"en":"It helps describe kindness from strangers.","zh":"它幫助描述來自陌生人的善意。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"notice I was slowing down","meaning":"留意到我正在慢下來","examples":[{"en":"A runner beside him noticed he was slowing down.","zh":"他身旁的一位跑手留意到他正在慢下來。"},{"en":"Notice I was slowing down means realise that I was moving more slowly than before.","zh":"Notice I was slowing down 指察覺我比之前移動得更慢。"},{"en":"My friend noticed I was slowing down and suggested we walk for one minute.","zh":"我的朋友留意到我正在慢下來，便建議我們走一分鐘。"},{"en":"In a race, noticing someone slowing down can lead to timely encouragement.","zh":"在比賽中，留意到某人慢下來可以帶來及時鼓勵。"},{"en":"This phrase shows careful attention to another person’s struggle.","zh":"這個短語顯示對別人掙扎的細心留意。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"one step at a time","meaning":"一步一步來","examples":[{"en":"The runner told him to take one step at a time.","zh":"那位跑手告訴他一步一步來。"},{"en":"One step at a time means focus on the next small action instead of the whole difficult task.","zh":"One step at a time 指專注下一個小行動，而不是整個困難任務。"},{"en":"When homework feels endless, finish it one question at a time.","zh":"當功課像沒有盡頭，就一題一題完成。"},{"en":"Marathon runners often survive hard moments by thinking one step at a time.","zh":"馬拉松跑手常靠一步一步來撐過困難時刻。"},{"en":"This phrase gives calm advice during pressure.","zh":"這個短語在壓力中給予平靜建議。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"carry me for another kilometre","meaning":"支撐我再跑一公里","examples":[{"en":"Those five words carried him for another kilometre.","zh":"那五個字支撐他再跑了一公里。"},{"en":"Carry me for another kilometre means give me enough emotional strength to continue a little farther.","zh":"Carry me for another kilometre 指給我足夠情感力量，讓我再繼續一小段路。"},{"en":"A friend’s encouragement can carry a tired runner for another kilometre.","zh":"朋友的鼓勵可以支撐疲累跑手再跑一公里。"},{"en":"Words can carry people forward when their bodies feel finished.","zh":"當身體像已經用盡，說話仍可以支撐人向前。"},{"en":"This phrase shows the power of support.","zh":"這個短語顯示支持的力量。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"in that moment","meaning":"在那一刻","examples":[{"en":"In that moment, Hong Kong felt generous.","zh":"在那一刻，香港顯得慷慨。"},{"en":"In that moment means at that exact time or during that brief experience.","zh":"In that moment 指在那個確切時間或短暫經歷中。"},{"en":"In that moment, the cheering crowd made him feel less alone.","zh":"在那一刻，打氣的人群令他感到不再孤單。"},{"en":"Writers use this phrase to focus attention on a strong feeling.","zh":"作者用這個短語把注意力集中在強烈感受上。"},{"en":"It helps make a memory feel immediate.","zh":"它幫助令記憶感覺即時而真實。"}],"source":"2018 Q2.pdf","sourcePage":10},{"front":"far from","meaning":"絕不是；遠非","examples":[{"en":"Hong Kong felt far from rushed or distant.","zh":"香港感覺絕不是匆忙或疏離的。"},{"en":"Far from means not at all; it often corrects an expected idea.","zh":"Far from 指完全不是，常用來糾正預期中的想法。"},{"en":"Far from being lonely, the marathon felt full of human warmth.","zh":"馬拉松絕不是孤單的，反而充滿人情味。"},{"en":"The city was far from distant when strangers cheered for every runner.","zh":"當陌生人為每位跑手打氣，這座城市絕不疏離。"},{"en":"This phrase strongly rejects a wrong impression.","zh":"這個短語有力否定錯誤印象。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"rushed, impatient or distant","meaning":"匆忙、不耐煩或疏離","examples":[{"en":"The city did not feel rushed, impatient or distant during the race.","zh":"比賽期間，這座城市並不顯得匆忙、不耐煩或疏離。"},{"en":"Rushed, impatient or distant means hurried, easily annoyed, or emotionally separated.","zh":"Rushed, impatient or distant 指匆忙、容易不耐煩，或情感上疏離。"},{"en":"A city can feel rushed and distant when everyone avoids eye contact.","zh":"當每個人都避免眼神接觸，城市可能顯得匆忙和疏離。"},{"en":"During the marathon, kindness made Hong Kong feel warm instead of rushed or distant.","zh":"馬拉松期間，善意令香港感到溫暖，而不是匆忙或疏離。"},{"en":"This phrase describes the emotional character of a place.","zh":"這個短語描述一個地方的情感特質。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"teenagers in school team shirts","meaning":"穿校隊衫的青少年","examples":[{"en":"Teenagers in school team shirts ran alongside older runners.","zh":"穿校隊衫的青少年與年長跑手並肩而跑。"},{"en":"Teenagers in school team shirts are young runners wearing shirts that show their school team.","zh":"Teenagers in school team shirts 指穿着代表學校隊伍衣服的年輕跑手。"},{"en":"Teenagers in school team shirts can make a race feel lively and hopeful.","zh":"穿校隊衫的青少年可以令比賽顯得有活力和希望。"},{"en":"Running beside older people shows that the marathon connects different generations.","zh":"與年長人士一起跑，顯示馬拉松連結不同世代。"},{"en":"This phrase gives a concrete image of community.","zh":"這個短語給出社群感的具體畫面。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"elderly runners still going strong","meaning":"仍然精力充沛的年長跑手","examples":[{"en":"Elderly runners were still going strong during the marathon.","zh":"年長跑手在馬拉松中仍然精力充沛地前進。"},{"en":"Elderly runners still going strong are older runners who continue with energy and determination.","zh":"Elderly runners still going strong 指年長跑手仍帶着精力和決心繼續。"},{"en":"Seeing elderly runners still going strong can inspire younger runners who feel tired.","zh":"看見年長跑手仍然精力充沛，可以鼓舞感到疲累的年輕跑手。"},{"en":"Their effort proves that strength is not only for the young.","zh":"他們的努力證明力量不只屬於年輕人。"},{"en":"This phrase combines age with impressive endurance.","zh":"這個短語把年齡和令人佩服的耐力結合起來。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"going strong","meaning":"仍然很有活力","examples":[{"en":"Many elderly runners were still going strong.","zh":"許多年長跑手仍然很有活力。"},{"en":"Going strong means continuing with energy, health, or success.","zh":"Going strong 指仍然有精力、健康或成功地繼續。"},{"en":"After thirty kilometres, she was tired but still going strong.","zh":"跑了三十公里後，她雖然疲累，但仍然很有活力。"},{"en":"A running club that has lasted twenty years is still going strong.","zh":"一個存在二十年的跑會仍然運作良好。"},{"en":"This phrase shows lasting strength.","zh":"這個短語顯示持久力量。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"tell the same story","meaning":"訴說同一個故事","examples":[{"en":"Every runner seemed to be telling the same story.","zh":"每位跑手似乎都在訴說同一個故事。"},{"en":"Tell the same story means express the same message through actions or experience.","zh":"Tell the same story 指透過行動或經驗表達同一訊息。"},{"en":"Their tired faces and steady steps told the same story of effort.","zh":"他們疲累的臉和穩定的步伐訴說着同一個努力的故事。"},{"en":"In a marathon, different runners can tell the same story of refusing to quit.","zh":"在馬拉松中，不同跑手可以訴說同一個拒絕放棄的故事。"},{"en":"This phrase shows shared meaning among different people.","zh":"這個短語顯示不同人之間的共同意義。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"ordinary people can do extraordinary things","meaning":"普通人也能做出非凡的事","examples":[{"en":"The marathon shows that ordinary people can do extraordinary things.","zh":"馬拉松顯示普通人也能做出非凡的事。"},{"en":"Ordinary people can do extraordinary things means normal people can achieve remarkable goals.","zh":"Ordinary people can do extraordinary things 指普通人也能達成令人驚嘆的目標。"},{"en":"A student who trains for months may discover that ordinary people can do extraordinary things.","zh":"訓練數月的學生可能發現普通人也能做出非凡的事。"},{"en":"This idea encourages beginners because greatness can grow from steady effort.","zh":"這個想法鼓勵初學者，因為偉大可以從穩定努力中成長。"},{"en":"The phrase turns a race into a hopeful life lesson.","zh":"這個短語把比賽變成充滿希望的人生教訓。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"refuse to quit","meaning":"拒絕放棄","examples":[{"en":"Ordinary people can achieve more when they refuse to quit.","zh":"當普通人拒絕放棄，他們可以做到更多。"},{"en":"Refuse to quit means firmly decide not to give up.","zh":"Refuse to quit 指堅決決定不放棄。"},{"en":"A runner may slow down but still refuse to quit.","zh":"跑手可能慢下來，但仍拒絕放棄。"},{"en":"People often achieve difficult goals because they continue after the easy part ends.","zh":"人們常因在容易部分結束後仍繼續，才達成困難目標。"},{"en":"This phrase shows determination.","zh":"這個短語顯示決心。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"a resounding yes","meaning":"一個響亮的「是」","examples":[{"en":"His answer to joining the next marathon is a resounding yes.","zh":"對於參加下一次馬拉松，他的答案是一個響亮的「是」。"},{"en":"A resounding yes means a very strong and confident yes.","zh":"A resounding yes 指非常強烈而有信心的「是」。"},{"en":"If someone asks whether training changed him, his answer is a resounding yes.","zh":"如果有人問訓練是否改變了他，他的答案會是一個響亮的「是」。"},{"en":"A resounding yes shows enthusiasm, not hesitation.","zh":"一個響亮的「是」顯示熱情，而不是猶豫。"},{"en":"This phrase is stronger than simply saying “yes.”","zh":"這個短語比簡單說 “yes” 更強烈。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"not because..., but because...","meaning":"不是因為……而是因為……","examples":[{"en":"Join not because it is easy, but because it can make you stronger.","zh":"參加不是因為它容易，而是因為它可以令你更強。"},{"en":"Not because..., but because... corrects one reason and gives the real reason.","zh":"Not because..., but because... 修正一個原因，並給出真正原因。"},{"en":"Train not because you want to impress others, but because you want to grow.","zh":"訓練不是因為你想令別人刮目相看，而是因為你想成長。"},{"en":"This structure helps explain a deeper purpose.","zh":"這個結構幫助解釋更深層目的。"},{"en":"It is useful for persuasive writing.","zh":"它適合用於說服性寫作。"}],"source":"2018 Q2.pdf","sourcePage":11},{"front":"willing to begin","meaning":"願意開始","examples":[{"en":"Join because you are willing to begin.","zh":"參加，因為你願意開始。"},{"en":"Willing to begin means ready to start, even without perfect confidence or experience.","zh":"Willing to begin 指準備開始，即使沒有完美信心或經驗。"},{"en":"A beginner only needs to be willing to begin with one short run.","zh":"初學者只需要願意從一次短跑開始。"},{"en":"Being willing to begin is often more important than feeling ready.","zh":"願意開始往往比感到準備好更重要。"},{"en":"This phrase values the first step.","zh":"這個短語重視第一步。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"difficult things often make us better people","meaning":"困難的事往往令我們成為更好的人","examples":[{"en":"Difficult things often make us better people.","zh":"困難的事往往令我們成為更好的人。"},{"en":"This means hard experiences can help people become stronger, kinder, or more disciplined.","zh":"這句話指艱難經歷可以幫助人變得更強、更善良或更有紀律。"},{"en":"Preparing for a marathon may make a young person more patient and responsible.","zh":"為馬拉松作準備可能令年輕人更有耐性和責任感。"},{"en":"Difficult things improve us when we learn from them instead of only complaining.","zh":"當我們從困難中學習，而不只是抱怨，困難就能改善我們。"},{"en":"This phrase presents hardship as a path to growth.","zh":"這個短語把艱辛呈現為成長之路。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"ask a friend to train with you","meaning":"邀請朋友一起訓練","examples":[{"en":"Ask a friend to train with you for the marathon.","zh":"邀請朋友和你一起為馬拉松訓練。"},{"en":"Ask a friend to train with you means invite someone to practise together.","zh":"Ask a friend to train with you 指邀請某人一起練習。"},{"en":"Training with a friend can make early mornings less lonely.","zh":"和朋友一起訓練可以令清晨不那麼孤單。"},{"en":"A friend can remind you to continue when motivation becomes weak.","zh":"當動力變弱，朋友可以提醒你繼續。"},{"en":"This phrase gives practical advice for building support.","zh":"這個短語提供建立支持的實用建議。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"make room in your schedule","meaning":"在日程中騰出時間","examples":[{"en":"Make room in your schedule for regular training.","zh":"在你的日程中騰出時間作定期訓練。"},{"en":"Make room in your schedule means set aside time for something important.","zh":"Make room in your schedule 指為重要事情預留時間。"},{"en":"Students may need to make room in their schedule by reducing screen time.","zh":"學生可能需要減少看屏幕時間，才能在日程中騰出時間。"},{"en":"Marathon training requires time, so it cannot depend only on free moments.","zh":"馬拉松訓練需要時間，所以不能只依靠空閒零碎時間。"},{"en":"This phrase connects planning with commitment.","zh":"這個短語把計劃和承諾連接起來。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"register when the opportunity comes","meaning":"有機會時就報名","examples":[{"en":"Register when the opportunity comes.","zh":"有機會時就報名。"},{"en":"Register when the opportunity comes means sign up when the chance becomes available.","zh":"Register when the opportunity comes 指機會出現時就報名。"},{"en":"If the marathon opens for entry, register when the opportunity comes instead of waiting forever.","zh":"如果馬拉松開始接受報名，有機會時就報名，不要永遠等待。"},{"en":"Sometimes a clear deadline helps people turn intention into action.","zh":"有時清楚的限期能幫助人把意願變成行動。"},{"en":"This phrase encourages timely action.","zh":"這個短語鼓勵及時行動。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"on race day","meaning":"比賽當日","examples":[{"en":"On race day, the city wakes around the runners.","zh":"比賽當日，城市在跑手身邊醒來。"},{"en":"On race day means on the day when the race happens.","zh":"On race day 指比賽發生的那一天。"},{"en":"On race day, quiet streets can become full of footsteps, volunteers, and cheers.","zh":"比賽當日，安靜街道可以充滿腳步聲、義工和歡呼聲。"},{"en":"The phrase creates a sense that the whole city joins the event.","zh":"這個短語營造整座城市都參與活動的感覺。"},{"en":"It marks the special atmosphere of the marathon morning.","zh":"它標示馬拉松早晨的特別氣氛。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"shoes hit the road","meaning":"鞋踏上路面","examples":[{"en":"When your shoes hit the road, the journey feels real.","zh":"當你的鞋踏上路面，旅程就變得真實。"},{"en":"Shoes hit the road means you begin running or taking real action.","zh":"Shoes hit the road 指開始跑步或真正採取行動。"},{"en":"Training plans matter, but the challenge begins when your shoes hit the road.","zh":"訓練計劃很重要，但當你的鞋踏上路面，挑戰才真正開始。"},{"en":"The sound of shoes hitting the road can make a race feel alive.","zh":"鞋踏上路面的聲音可以令比賽變得有生命力。"},{"en":"This phrase turns preparation into movement.","zh":"這個短語把準備變成行動。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"the city wakes around you","meaning":"城市在你身邊醒來","examples":[{"en":"On race day, the city wakes around you.","zh":"比賽當日，城市在你身邊醒來。"},{"en":"The city wakes around you means the streets, people, and atmosphere become active as you move through them.","zh":"The city wakes around you 指街道、人群和氣氛隨着你前進而活躍起來。"},{"en":"During a morning race, the city wakes around you with lights, voices, and footsteps.","zh":"在清晨比賽中，城市伴着燈光、人聲和腳步聲在你身邊醒來。"},{"en":"This image makes the runner feel part of something larger.","zh":"這個畫面令跑手感到自己屬於更大的事物。"},{"en":"The phrase connects personal effort with urban life.","zh":"這個短語把個人努力與城市生活連接起來。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"discover what I discovered","meaning":"發現我所發現的事","examples":[{"en":"You may discover what the writer discovered during the marathon.","zh":"你可能會發現作者在馬拉松中所發現的事。"},{"en":"Discover what I discovered means learn the same important lesson through your own experience.","zh":"Discover what I discovered 指透過自己的經驗學到同一個重要教訓。"},{"en":"If you train patiently, you may discover what I discovered about courage.","zh":"如果你有耐性地訓練，你可能會發現我對勇氣所發現的事。"},{"en":"This phrase invites readers to experience the lesson themselves.","zh":"這個短語邀請讀者親身經歷這個教訓。"},{"en":"It suggests that understanding comes from action, not just reading.","zh":"它暗示理解來自行動，而不只是閱讀。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"where the journey ends","meaning":"旅程結束的地方","examples":[{"en":"The finish line is not where the journey ends.","zh":"終點線不是旅程結束的地方。"},{"en":"Where the journey ends means the place or moment when an experience is finished.","zh":"Where the journey ends 指一段經歷完成的地方或時刻。"},{"en":"Graduation is not always where the journey ends, because learning continues after school.","zh":"畢業不一定是旅程結束的地方，因為學習在離校後仍繼續。"},{"en":"For a marathon runner, the finish line may begin a new sense of self.","zh":"對馬拉松跑手來說，終點線可能開啟新的自我感覺。"},{"en":"This phrase questions whether an ending is really final.","zh":"這個短語質疑結束是否真的就是終結。"}],"source":"2018 Q2.pdf","sourcePage":12},{"front":"a braver version of yourself","meaning":"更勇敢的自己","examples":[{"en":"A braver version of yourself may begin at the finish line.","zh":"更勇敢的自己可能在終點線開始。"},{"en":"A braver version of yourself means a stronger, more courageous self that grows from experience.","zh":"A braver version of yourself 指由經歷中成長出來、更堅強和更勇敢的自己。"},{"en":"After facing the marathon, he met a braver version of himself.","zh":"面對馬拉松後，他遇見了更勇敢的自己。"},{"en":"Difficult goals can reveal a braver version of yourself that daily life hides.","zh":"困難目標可以揭示日常生活中隱藏的更勇敢的自己。"},{"en":"This phrase describes personal growth in a hopeful way.","zh":"這個短語以充滿希望的方式描述個人成長。"}],"source":"2018 Q2.pdf","sourcePage":13},{"front":"has just begun","meaning":"才剛剛開始","examples":[{"en":"At the finish line, a braver version of yourself has just begun.","zh":"在終點線，更勇敢的自己才剛剛開始。"},{"en":"Has just begun means has only recently started and will continue from now.","zh":"Has just begun 指才剛開始，並會從現在繼續下去。"},{"en":"After the first successful run, his new confidence had just begun.","zh":"第一次成功跑步後，他的新自信才剛剛開始。"},{"en":"A finish line can feel like an ending, but personal growth may have just begun.","zh":"終點線可能像結束，但個人成長才剛剛開始。"},{"en":"This phrase shows that completion can also be a beginning.","zh":"這個短語顯示完成也可以是一個開始。"}],"source":"2018 Q2.pdf","sourcePage":13}],"dse/writing/part-b/2018/Q3":[{"front":"protecting our time","meaning":"保護我們的時間","examples":[{"en":"The letter is about protecting our time and protecting our team.","zh":"這封信是關於保護我們的時間和保護我們的團隊。"},{"en":"Protecting our time means keeping personal or working time from being used unfairly or carelessly.","zh":"保護我們的時間，意思是避免私人時間或工作時間被不公平或粗心地佔用。"},{"en":"A student protects their time by turning off notifications while studying.","zh":"學生在溫習時關掉通知，就是在保護自己的時間。"},{"en":"Clear rules protect our time because fewer people interrupt us after work.","zh":"清晰規則可以保護我們的時間，因為較少人在下班後打擾我們。"},{"en":"Protecting our time helps people rest properly and return to work with more focus.","zh":"保護我們的時間幫助人們好好休息，並以更專注的狀態回到工作。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"protecting our team","meaning":"保護我們的團隊","examples":[{"en":"The new guidelines aim at protecting our team.","zh":"新指引旨在保護我們的團隊。"},{"en":"Protecting our team means keeping colleagues safe, healthy, and able to work well together.","zh":"保護我們的團隊，意思是讓同事保持安全、健康，並能良好合作。"},{"en":"A manager protects the team by stopping unfair late-night demands.","zh":"經理阻止不公平的深夜要求，就是在保護團隊。"},{"en":"Protecting our team can reduce stress and prevent burnout.","zh":"保護我們的團隊可以減少壓力並防止過勞。"},{"en":"Good workplace rules protect our team by respecting both work and rest.","zh":"好的職場規則透過尊重工作和休息來保護我們的團隊。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"new guidelines","meaning":"新指引","examples":[{"en":"The company announced new guidelines on after-hours work messages.","zh":"公司宣布了關於下班後工作訊息的新指引。"},{"en":"New guidelines are new rules or advice that tell people how to behave.","zh":"新指引，是新的規則或建議，告訴人們應如何行事。"},{"en":"A school may announce new guidelines on phone use during lessons.","zh":"學校可能宣布課堂中使用手機的新指引。"},{"en":"New guidelines help people understand what is acceptable and what is not.","zh":"新指引幫助人們明白甚麼可以接受，甚麼不可以。"},{"en":"These new guidelines tell staff when work messages should wait.","zh":"這些新指引告訴員工哪些工作訊息應該等待。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"after-hours work messages","meaning":"下班後工作訊息","examples":[{"en":"The letter discusses after-hours work messages.","zh":"這封信討論下班後工作訊息。"},{"en":"After-hours work messages are job-related messages sent outside normal office hours.","zh":"下班後工作訊息，是在正常辦公時間以外發出的與工作有關訊息。"},{"en":"An email sent at 11 p.m. about tomorrow’s meeting is an after-hours work message.","zh":"晚上十一時發出的關於明天會議的電郵，就是下班後工作訊息。"},{"en":"Too many after-hours work messages can make staff feel they are always working.","zh":"太多下班後工作訊息會令員工覺得自己一直在工作。"},{"en":"The company wants non-urgent after-hours work messages to wait until morning.","zh":"公司希望非緊急的下班後工作訊息等到早上才處理。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"over the past fortnight","meaning":"在過去兩星期","examples":[{"en":"Over the past fortnight, several complaints have been received.","zh":"在過去兩星期，公司收到幾宗投訴。"},{"en":"Over the past fortnight means during the last two weeks.","zh":"在過去兩星期，意思是在最近十四天內。"},{"en":"Over the past fortnight, many students have been preparing for exams.","zh":"在過去兩星期，很多學生一直在準備考試。"},{"en":"If the same problem appears over the past fortnight, it may need attention.","zh":"如果同一問題在過去兩星期反覆出現，它可能需要關注。"},{"en":"The complaints over the past fortnight showed that the issue was not isolated.","zh":"過去兩星期的投訴顯示，這個問題不是個別事件。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"thoughtful complaints","meaning":"經深思熟慮的投訴；有建設性的意見","examples":[{"en":"The Managing Director received several thoughtful complaints.","zh":"董事總經理收到幾宗經深思熟慮的投訴。"},{"en":"Thoughtful complaints are carefully considered comments that explain a problem clearly.","zh":"經深思熟慮的投訴，是仔細考慮後清楚解釋問題的意見。"},{"en":"A student may write a thoughtful complaint about noisy study areas.","zh":"學生可能就自修區太吵寫出有建設性的意見。"},{"en":"Thoughtful complaints help leaders improve because they point to real causes.","zh":"有建設性的意見幫助領導者改善，因為它指出真正原因。"},{"en":"These complaints were thoughtful because they were not just angry; they offered useful concerns.","zh":"這些投訴是經深思熟慮的，因為它們不只是憤怒，而是提出有用憂慮。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"work-related emails","meaning":"與工作有關的電郵","examples":[{"en":"Staff have been receiving work-related emails after office hours.","zh":"員工在辦公時間後一直收到與工作有關的電郵。"},{"en":"Work-related emails are emails connected to tasks, meetings, projects, or company duties.","zh":"與工作有關的電郵，是關於任務、會議、項目或公司職責的電郵。"},{"en":"A message about a report deadline is a work-related email.","zh":"關於報告截止日期的訊息，就是與工作有關的電郵。"},{"en":"Work-related emails after dinner can pull people back into job mode.","zh":"晚餐後收到與工作有關的電郵，會把人拉回工作狀態。"},{"en":"The new policy asks staff not to send non-urgent work-related emails at night.","zh":"新政策要求員工不要在晚上發送非緊急的工作電郵。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"text messages","meaning":"短訊","examples":[{"en":"Some staff have received text messages after office hours.","zh":"有些員工在辦公時間後收到短訊。"},{"en":"Text messages are short written messages usually sent by phone.","zh":"短訊，是通常透過手機發送的簡短文字訊息。"},{"en":"A manager may send a text message to confirm a meeting time.","zh":"經理可能發短訊確認會議時間。"},{"en":"Text messages can feel urgent because they appear directly on a person’s phone.","zh":"短訊可能令人覺得緊急，因為它們直接出現在手機上。"},{"en":"Work text messages after hours can disturb family time and rest.","zh":"下班後的工作短訊可以打擾家庭時間和休息。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"reaching staff","meaning":"傳到職員那裏","examples":[{"en":"Work-related messages have been reaching staff after office hours.","zh":"與工作有關的訊息一直在辦公時間後傳到職員那裏。"},{"en":"Reaching staff means arriving on employees’ phones, computers, or inboxes.","zh":"傳到職員那裏，意思是到達員工的手機、電腦或收件箱。"},{"en":"Notices reach staff more quickly when sent through the company app.","zh":"透過公司應用程式發送通知，可以更快傳到職員那裏。"},{"en":"If messages keep reaching staff at night, they may feel unable to switch off.","zh":"如果訊息晚上不斷傳到職員那裏，他們可能覺得無法下班。"},{"en":"The problem is not only sending messages, but also when they reach staff.","zh":"問題不只是發送訊息，也包括訊息何時傳到職員那裏。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"after office hours","meaning":"辦公時間後","examples":[{"en":"Staff have received messages after office hours.","zh":"員工在辦公時間後收到訊息。"},{"en":"After office hours means after the normal working day has ended.","zh":"辦公時間後，意思是正常工作日結束之後。"},{"en":"A call at 9 p.m. is usually after office hours for most office workers.","zh":"對大多數辦公室員工來說，晚上九時的電話通常是在辦公時間後。"},{"en":"Messages after office hours can interrupt rest even if they are short.","zh":"辦公時間後的訊息即使很短，也可能打斷休息。"},{"en":"The policy says non-urgent matters should wait until after office hours are over.","zh":"政策指出，非緊急事項應等到辦公時間後結束才處理。"}],"source":"2018 Q3.pdf","sourcePage":1},{"front":"Managing Director","meaning":"董事總經理","examples":[{"en":"Chris Wong is the Managing Director of Reboot Online Company.","zh":"Chris Wong 是 Reboot Online Company 的董事總經理。"},{"en":"A Managing Director is a senior leader responsible for running a company.","zh":"董事總經理，是負責管理公司的高層領導。"},{"en":"The Managing Director may announce major workplace policies.","zh":"董事總經理可能宣布重要職場政策。"},{"en":"When staff raise serious concerns, the Managing Director should respond clearly.","zh":"當員工提出嚴重憂慮，董事總經理應清楚回應。"},{"en":"In this letter, the Managing Director explains how the company will protect staff time.","zh":"在這封信中，董事總經理解釋公司將如何保護員工時間。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"take these concerns seriously","meaning":"認真看待這些憂慮","examples":[{"en":"The Managing Director takes these concerns seriously.","zh":"董事總經理認真看待這些憂慮。"},{"en":"To take these concerns seriously means to treat people’s worries as important and worth action.","zh":"認真看待這些憂慮，意思是把人們的擔心視為重要並值得行動。"},{"en":"A school takes safety concerns seriously when it repairs broken stairs quickly.","zh":"學校迅速修理損壞樓梯，就是認真看待安全憂慮。"},{"en":"Leaders take concerns seriously by listening, investigating, and changing rules when needed.","zh":"領導者透過聆聽、調查和在需要時改變規則來認真看待憂慮。"},{"en":"The company takes these concerns seriously because they affect staff health.","zh":"公司認真看待這些憂慮，因為它們影響員工健康。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"go to the heart of","meaning":"觸及……的核心","examples":[{"en":"These concerns go to the heart of the workplace the company claims to be.","zh":"這些憂慮觸及公司聲稱要建立的工作場所核心。"},{"en":"To go to the heart of something means to touch its most important part.","zh":"觸及某事的核心，意思是碰到它最重要的部分。"},{"en":"A complaint about unfair treatment goes to the heart of school trust.","zh":"關於不公平待遇的投訴觸及學校信任的核心。"},{"en":"Questions about rest go to the heart of how a company values people.","zh":"關於休息的問題觸及公司如何重視人的核心。"},{"en":"After-hours messages go to the heart of whether the workplace is truly respectful.","zh":"下班後訊息觸及工作場所是否真正互相尊重的核心。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"the workplace we claim to be","meaning":"我們聲稱要建立的工作場所","examples":[{"en":"The concerns challenge the workplace we claim to be.","zh":"這些憂慮挑戰我們聲稱要建立的工作場所。"},{"en":"The workplace we claim to be means the kind of company we say we are.","zh":"我們聲稱要建立的工作場所，意思是我們說自己是怎樣的公司。"},{"en":"If a school claims to be caring, bullying challenges the school it claims to be.","zh":"如果學校聲稱關愛，欺凌事件就會挑戰它聲稱要建立的學校。"},{"en":"A company must match the workplace it claims to be with daily behaviour.","zh":"公司必須用日常行為配合它聲稱要建立的工作場所。"},{"en":"If staff cannot rest, the workplace we claim to be may not match reality.","zh":"如果員工不能休息，我們聲稱要建立的工作場所可能與現實不符。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"move across time zones","meaning":"跨越不同時區","examples":[{"en":"Projects move across time zones.","zh":"項目跨越不同時區。"},{"en":"To move across time zones means to involve people working in different parts of the world at different local times.","zh":"跨越不同時區，意思是涉及在世界不同地方、不同本地時間工作的人。"},{"en":"An online class moves across time zones when students join from Hong Kong, London, and Toronto.","zh":"當學生從香港、倫敦和多倫多加入，網上課堂就跨越不同時區。"},{"en":"Projects across time zones can create late messages if rules are unclear.","zh":"如果規則不清晰，跨越不同時區的項目可能造成深夜訊息。"},{"en":"The company needs better planning because its projects move across time zones.","zh":"公司需要更好規劃，因為它的項目跨越不同時區。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"sending updates","meaning":"發送最新進度","examples":[{"en":"Some staff have begun sending updates late at night.","zh":"有些員工開始在深夜發送最新進度。"},{"en":"Sending updates means giving new information about progress, changes, or decisions.","zh":"發送最新進度，意思是提供關於進展、改變或決定的新資訊。"},{"en":"A class monitor may be sending updates about a school trip schedule.","zh":"班長可能發送關於學校旅行時間表的最新進度。"},{"en":"Sending updates too often can make people feel they must check messages constantly.","zh":"太頻密發送最新進度，會令人覺得必須不斷查看訊息。"},{"en":"Staff should send non-urgent updates during office hours whenever possible.","zh":"員工應盡可能在辦公時間內發送非緊急的最新進度。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"late at night","meaning":"深夜","examples":[{"en":"Some staff send updates late at night.","zh":"有些員工在深夜發送最新進度。"},{"en":"Late at night means during the later hours of the night, when people usually rest.","zh":"深夜，意思是在夜晚較晚的時間，通常是人們休息的時候。"},{"en":"Studying late at night can make students tired the next morning.","zh":"深夜溫習可能令學生第二天早上疲倦。"},{"en":"Messages sent late at night may disturb sleep and family time.","zh":"深夜發送的訊息可能打擾睡眠和家庭時間。"},{"en":"The new rules discourage sending work updates late at night.","zh":"新規則不鼓勵在深夜發送工作進度。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"during weekends","meaning":"週末期間","examples":[{"en":"Some updates are sent during weekends.","zh":"有些最新進度在週末期間發送。"},{"en":"During weekends means on Saturday or Sunday.","zh":"週末期間，意思是在星期六或星期日。"},{"en":"Students may rest or see family during weekends.","zh":"學生可能在週末期間休息或見家人。"},{"en":"Work messages during weekends can make people feel their break has disappeared.","zh":"週末期間的工作訊息會令人覺得休息消失了。"},{"en":"Non-urgent project updates should not be sent during weekends under the new policy.","zh":"根據新政策，非緊急項目進度不應在週末期間發送。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"led the company to consider","meaning":"促使公司考慮","examples":[{"en":"This issue has led the company to consider clearer communication rules.","zh":"這個問題促使公司考慮更清晰的溝通規則。"},{"en":"Led the company to consider means caused the company to think seriously about doing something.","zh":"促使公司考慮，意思是令公司認真思考做某事。"},{"en":"Repeated complaints led the school to consider changing its lunch menu.","zh":"反覆投訴促使學校考慮改變午餐餐單。"},{"en":"A serious problem can lead leaders to consider new rules.","zh":"嚴重問題可以促使領導者考慮新規則。"},{"en":"After-hours messages led the company to consider how to protect rest.","zh":"下班後訊息促使公司考慮如何保障休息。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"introducing clearer communication rules","meaning":"推出更清晰的溝通規則","examples":[{"en":"The company is considering introducing clearer communication rules.","zh":"公司正考慮推出更清晰的溝通規則。"},{"en":"Introducing clearer communication rules means bringing in better rules for how people share information.","zh":"推出更清晰的溝通規則，意思是引入更好的資訊分享規則。"},{"en":"A school may introduce clearer communication rules so homework instructions are not confusing.","zh":"學校可能推出更清晰的溝通規則，令功課指示不再混亂。"},{"en":"Clearer communication rules reduce mistakes because everyone knows what to send and when.","zh":"更清晰的溝通規則可以減少錯誤，因為每個人都知道發送甚麼和何時發送。"},{"en":"The company wants clearer rules so fewer issues spill into private time.","zh":"公司希望有更清晰的規則，讓較少問題延伸至私人時間。"}],"source":"2018 Q3.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"The rules are introduced in order to protect rest.","zh":"這些規則是為了保障休息時間而推出。"},{"en":"In order to means for the purpose of doing something.","zh":"為了，意思是以做某事為目的。"},{"en":"Students practise daily in order to improve their speaking skills.","zh":"學生每天練習，是為了改善說話能力。"},{"en":"A company may change rules in order to reduce stress.","zh":"公司可能改變規則，是為了減少壓力。"},{"en":"These rules exist in order to protect both work quality and personal time.","zh":"這些規則存在，是為了保護工作質素和私人時間。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"protect rest","meaning":"保障休息時間","examples":[{"en":"The policy aims to protect staff rest.","zh":"這項政策旨在保障員工休息時間。"},{"en":"To protect rest means to make sure people have time to recover without work interruptions.","zh":"保障休息時間，意思是確保人們有不受工作打擾的恢復時間。"},{"en":"Families protect rest by keeping phones away during dinner.","zh":"家庭在晚餐時把手機放開，就是在保障休息時間。"},{"en":"Protecting rest can improve health, mood, and work quality.","zh":"保障休息時間可以改善健康、心情和工作質素。"},{"en":"The company protects rest by stopping non-urgent messages after hours.","zh":"公司透過停止下班後非緊急訊息來保障休息時間。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"reduce unnecessary pressure","meaning":"減少不必要壓力","examples":[{"en":"The rules are intended to reduce unnecessary pressure.","zh":"這些規則旨在減少不必要壓力。"},{"en":"To reduce unnecessary pressure means to lower stress that does not need to exist.","zh":"減少不必要壓力，意思是降低本來不需要存在的壓力。"},{"en":"Clear homework deadlines can reduce unnecessary pressure on students.","zh":"清晰的功課限期可以減少學生的不必要壓力。"},{"en":"Unclear messages create unnecessary pressure because people do not know what is urgent.","zh":"不清晰的訊息會造成不必要壓力，因為人們不知道甚麼是緊急。"},{"en":"The policy reduces unnecessary pressure by letting staff ignore non-urgent messages after work.","zh":"政策容許員工下班後不理會非緊急訊息，從而減少不必要壓力。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"sustain high-quality work","meaning":"維持高質素工作","examples":[{"en":"The company wants to sustain high-quality work.","zh":"公司希望維持高質素工作。"},{"en":"To sustain high-quality work means to keep producing good work over time.","zh":"維持高質素工作，意思是長時間保持良好的工作成果。"},{"en":"Students sustain high-quality work by resting before important exams.","zh":"學生在重要考試前休息，有助維持高質素學習表現。"},{"en":"A tired team may struggle to sustain high-quality work for long.","zh":"疲倦的團隊可能難以長期維持高質素工作。"},{"en":"Protecting rest helps employees sustain high-quality work without burning out.","zh":"保障休息幫助員工維持高質素工作，而不會過勞。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"let me be clear","meaning":"讓我說清楚","examples":[{"en":"Let me be clear: our success must never come at the cost of your health.","zh":"讓我說清楚：我們的成功絕不能以犧牲你們的健康為代價。"},{"en":"Let me be clear is used before saying something directly and firmly.","zh":"讓我說清楚，用於直接而堅定地說明某事之前。"},{"en":"Let me be clear: bullying is not acceptable in this school.","zh":"讓我說清楚：欺凌在這間學校不可接受。"},{"en":"A leader says “let me be clear” when the message should not be misunderstood.","zh":"當訊息不應被誤解時，領導者會說「讓我說清楚」。"},{"en":"The Managing Director uses this phrase to make the company’s position firm.","zh":"董事總經理使用這個短語，是為了堅定表明公司的立場。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"come at the cost of","meaning":"以犧牲……為代價","examples":[{"en":"Success must never come at the cost of health or personal time.","zh":"成功絕不能以犧牲健康或私人時間為代價。"},{"en":"To come at the cost of something means to be achieved by sacrificing it.","zh":"以犧牲某事為代價，意思是透過放棄它來取得成果。"},{"en":"Good grades should not come at the cost of sleep every night.","zh":"好成績不應以每晚犧牲睡眠為代價。"},{"en":"Company growth comes at too high a cost if staff lose their health.","zh":"如果員工失去健康，公司成長付出的代價就太高。"},{"en":"The letter argues that work success should not come at the cost of human wellbeing.","zh":"這封信主張，工作成功不應以犧牲人的福祉為代價。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"family life","meaning":"家庭生活","examples":[{"en":"Work success should not come at the cost of family life.","zh":"工作成功不應以犧牲家庭生活為代價。"},{"en":"Family life means the time, relationships, and responsibilities people share with family members.","zh":"家庭生活，是人們與家人共享的時間、關係和責任。"},{"en":"Eating dinner together is an important part of family life for many people.","zh":"對很多人來說，一起吃晚飯是家庭生活的重要部分。"},{"en":"Late-night work messages can damage family life by interrupting shared time.","zh":"深夜工作訊息會打斷共享時間，從而損害家庭生活。"},{"en":"A healthy workplace respects that employees also have family life.","zh":"健康的工作場所會尊重員工也有家庭生活。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"personal time","meaning":"私人時間","examples":[{"en":"The company wants to protect staff personal time.","zh":"公司希望保護員工的私人時間。"},{"en":"Personal time is time that belongs to a person outside work or public duties.","zh":"私人時間，是工作或公共責任以外屬於個人的時間。"},{"en":"A person may use personal time to rest, exercise, study, or see family.","zh":"一個人可能用私人時間休息、運動、學習或見家人。"},{"en":"If work messages enter personal time every night, rest becomes difficult.","zh":"如果工作訊息每晚進入私人時間，休息就會變得困難。"},{"en":"The policy protects personal time by setting limits on after-hours contact.","zh":"政策透過限制下班後聯絡來保護私人時間。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"acknowledge the problem plainly","meaning":"坦率承認問題","examples":[{"en":"The Managing Director acknowledges the problem plainly.","zh":"董事總經理坦率承認問題。"},{"en":"To acknowledge the problem plainly means to admit it clearly without hiding or softening it.","zh":"坦率承認問題，意思是清楚承認問題，不隱瞞或淡化。"},{"en":"A teacher acknowledges a problem plainly when they say a class rule has not worked.","zh":"老師說某班規沒有成效時，就是坦率承認問題。"},{"en":"Plainly acknowledging a problem helps people trust that change may happen.","zh":"坦率承認問題有助人們相信改變可能發生。"},{"en":"The Managing Director acknowledges the problem plainly before announcing the new policy.","zh":"董事總經理在宣布新政策前坦率承認問題。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"just one quick email","meaning":"只是一封簡短電郵","examples":[{"en":"It is easy to say that just one quick email does no harm.","zh":"人們很容易說只是一封簡短電郵沒有害處。"},{"en":"Just one quick email means a short message that seems small and harmless.","zh":"只是一封簡短電郵，意思是看似細小而無傷大雅的短訊息。"},{"en":"A manager may think just one quick email at night will not disturb anyone.","zh":"經理可能以為晚上只是一封簡短電郵，不會打擾任何人。"},{"en":"Many “quick” emails can become a long chain of interruptions.","zh":"許多「簡短」電郵可以變成一長串干擾。"},{"en":"The letter warns that just one quick email may still pull someone back into work.","zh":"這封信提醒我們，只是一封簡短電郵也可能把人拉回工作。"}],"source":"2018 Q3.pdf","sourcePage":3},{"front":"does no harm","meaning":"沒有害處；無傷大雅","examples":[{"en":"One quick email may seem to do no harm.","zh":"一封簡短電郵可能看似沒有害處。"},{"en":"Does no harm means does not seem to cause damage or trouble.","zh":"沒有害處，意思是看起來不會造成損害或麻煩。"},{"en":"One small snack may seem to do no harm, but many snacks can affect health.","zh":"一份小零食可能看似無傷大雅，但很多零食會影響健康。"},{"en":"A message that does no harm to the sender may still disturb the receiver.","zh":"對發送者沒有害處的訊息，仍可能打擾接收者。"},{"en":"The letter questions the idea that late-night emails do no harm.","zh":"這封信質疑深夜電郵沒有害處這種想法。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"the reality is that","meaning":"現實是","examples":[{"en":"The reality is that small interruptions can become another work session.","zh":"現實是，小干擾可以變成另一段工作時間。"},{"en":"The reality is that introduces what is actually true, especially when it differs from what people think.","zh":"現實是，用來引出實際真相，特別是當它與人們想法不同時。"},{"en":"The reality is that online learning still needs discipline and planning.","zh":"現實是，網上學習仍需要紀律和計劃。"},{"en":"People may think a message is small; the reality is that it can disturb rest.","zh":"人們可能以為訊息很小；現實是，它可以打擾休息。"},{"en":"The phrase helps the writer move from excuse to real effect.","zh":"這個短語幫助作者由藉口轉向真實影響。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"a string of small interruptions","meaning":"一連串小干擾","examples":[{"en":"A string of small interruptions can turn an evening into work time.","zh":"一連串小干擾可以把一個晚上變成工作時間。"},{"en":"A string of small interruptions means many small disturbances happening one after another.","zh":"一連串小干擾，意思是許多小打擾一個接一個發生。"},{"en":"A string of phone alerts can stop a student from focusing on revision.","zh":"一連串手機提示可以令學生無法專心溫習。"},{"en":"Small interruptions become tiring when they form a long string.","zh":"當小干擾形成長串時，就會令人疲倦。"},{"en":"After-hours messages are harmful because a string of small interruptions can steal rest.","zh":"下班後訊息有害，因為一連串小干擾可以偷走休息。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"turn an evening into","meaning":"把一個晚上變成","examples":[{"en":"Small interruptions can turn an evening into another work session.","zh":"小干擾可以把一個晚上變成另一段工作時間。"},{"en":"To turn an evening into something means to change the nature of that evening.","zh":"把一個晚上變成某種情況，意思是改變那個晚上的性質。"},{"en":"A long family argument can turn an evening into a stressful night.","zh":"一場長時間家庭爭吵可以把一個晚上變成壓力之夜。"},{"en":"Several work calls can turn an evening into unpaid office time.","zh":"幾個工作電話可以把一個晚上變成無薪辦公時間。"},{"en":"The company wants to stop messages from turning evenings into work sessions.","zh":"公司希望阻止訊息把晚上變成工作時間。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"another work session","meaning":"另一段工作時間","examples":[{"en":"An evening can become another work session.","zh":"一個晚上可以變成另一段工作時間。"},{"en":"Another work session means an extra period of doing work after the normal working day.","zh":"另一段工作時間，意思是在正常工作日之後額外工作的時段。"},{"en":"Checking one report after dinner can become another work session.","zh":"晚餐後查看一份報告，可以變成另一段工作時間。"},{"en":"Another work session at night reduces the time people need for rest.","zh":"晚上的另一段工作時間會減少人們需要的休息時間。"},{"en":"The policy tries to stop private evenings from becoming another work session.","zh":"這項政策嘗試阻止私人晚上變成另一段工作時間。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time a designer has replied, private time has already been affected.","zh":"到設計師回覆的時候，私人時間已經受到影響。"},{"en":"By the time means when something has happened or when a certain point is reached.","zh":"到……的時候，意思是某事已經發生或某個時間點已到達時。"},{"en":"By the time students reach school, the rain may have stopped.","zh":"到學生到達學校的時候，雨可能已經停了。"},{"en":"By the time someone answers several messages, their rest may already be interrupted.","zh":"到某人回覆幾個訊息的時候，他的休息可能已經被打斷。"},{"en":"The phrase shows that harm may happen before people notice it.","zh":"這個短語顯示，傷害可能在人們注意到之前已經發生。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"answered one message","meaning":"回覆了一個訊息","examples":[{"en":"A designer may have answered one message after work.","zh":"設計師可能在下班後回覆了一個訊息。"},{"en":"Answered one message means replied to a single text, email, or request.","zh":"回覆了一個訊息，意思是回應一則短訊、電郵或要求。"},{"en":"A student may think answering one message during dinner is harmless.","zh":"學生可能以為晚餐期間回覆一個訊息無傷大雅。"},{"en":"Answering one message can lead to checking another file or solving another problem.","zh":"回覆一個訊息可能導致查看另一份文件或處理另一個問題。"},{"en":"The letter shows how answering one message can begin a new work session.","zh":"這封信顯示，回覆一個訊息可以開始另一段工作時間。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"checked an attachment","meaning":"查看附件","examples":[{"en":"The designer checked an attachment after answering the message.","zh":"設計師回覆訊息後查看附件。"},{"en":"Checked an attachment means opened and looked at a file sent with a message.","zh":"查看附件，意思是打開並閱讀隨訊息發送的檔案。"},{"en":"A teacher may check an attachment to see a student’s homework.","zh":"老師可能查看附件，以閱讀學生功課。"},{"en":"Checking an attachment after hours can turn a quick reply into real work.","zh":"下班後查看附件，可以把簡短回覆變成真正工作。"},{"en":"The designer’s rest was interrupted because one message led to checking an attachment.","zh":"設計師的休息被打斷，因為一個訊息引致查看附件。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"clarified a deadline","meaning":"釐清截止日期","examples":[{"en":"The designer clarified a deadline after office hours.","zh":"設計師在辦公時間後釐清截止日期。"},{"en":"Clarified a deadline means made the due date or time clear.","zh":"釐清截止日期，意思是把到期日期或時間弄清楚。"},{"en":"A student may clarify a deadline by asking whether homework is due Monday or Tuesday.","zh":"學生可能詢問功課是星期一還是星期二到期，以釐清截止日期。"},{"en":"Clarifying deadlines is useful, but it can usually wait until office hours.","zh":"釐清截止日期有用，但通常可以等到辦公時間。"},{"en":"The designer clarified a deadline at night, so private time became work time.","zh":"設計師晚上釐清截止日期，所以私人時間變成工作時間。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"private time","meaning":"私人時間","examples":[{"en":"Private time can be swallowed by work.","zh":"私人時間可能被工作吞噬。"},{"en":"Private time is time for personal life, rest, family, or interests outside work.","zh":"私人時間，是工作以外用於個人生活、休息、家庭或興趣的時間。"},{"en":"Reading quietly before bed can be part of private time.","zh":"睡前安靜閱讀可以是私人時間的一部分。"},{"en":"Private time disappears when work messages demand constant attention.","zh":"當工作訊息要求不斷注意，私人時間就會消失。"},{"en":"The new guidelines aim to protect private time from unnecessary interruptions.","zh":"新指引旨在保護私人時間免受不必要干擾。"}],"source":"2018 Q3.pdf","sourcePage":4},{"front":"swallowed by work","meaning":"被工作吞噬","examples":[{"en":"Private time has already been swallowed by work.","zh":"私人時間已經被工作吞噬。"},{"en":"Swallowed by work means completely taken over by job duties.","zh":"被工作吞噬，意思是完全被工作職責佔據。"},{"en":"A student’s weekend can be swallowed by homework if deadlines are badly planned.","zh":"如果限期安排不佳，學生的週末可能被功課吞噬。"},{"en":"Personal life is swallowed by work when people feel unable to stop checking messages.","zh":"當人們覺得不能停止查看訊息，私人生活就會被工作吞噬。"},{"en":"The policy tries to stop evenings from being swallowed by work.","zh":"這項政策嘗試阻止晚上被工作吞噬。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"caring for children","meaning":"照顧小朋友","examples":[{"en":"Some colleagues may be caring for children.","zh":"有些同事可能正在照顧小朋友。"},{"en":"Caring for children means looking after young people and meeting their daily needs.","zh":"照顧小朋友，意思是照料年幼的人並滿足他們的日常需要。"},{"en":"A parent may be caring for children by helping with homework and preparing dinner.","zh":"家長可能透過幫忙做功課和準備晚餐來照顧小朋友。"},{"en":"Work messages can interrupt colleagues who are caring for children after work.","zh":"工作訊息可能打擾下班後正在照顧小朋友的同事。"},{"en":"Respecting family responsibilities includes respecting time spent caring for children.","zh":"尊重家庭責任，包括尊重用於照顧小朋友的時間。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"elderly parents","meaning":"年邁父母","examples":[{"en":"Some colleagues may be caring for elderly parents.","zh":"有些同事可能正在照顧年邁父母。"},{"en":"Elderly parents are older mothers or fathers who may need support or care.","zh":"年邁父母，是可能需要支援或照顧的年長母親或父親。"},{"en":"A worker may take an elderly parent to a clinic after work.","zh":"員工可能下班後帶年邁父母去診所。"},{"en":"Caring for elderly parents can be tiring, so rest time matters.","zh":"照顧年邁父母可能令人疲倦，所以休息時間很重要。"},{"en":"Late messages may disturb staff who are looking after elderly parents.","zh":"深夜訊息可能打擾正在照顧年邁父母的員工。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"flashing beside them","meaning":"在旁邊閃亮","examples":[{"en":"Some staff need dinner without a phone flashing beside them.","zh":"有些員工需要吃晚飯時沒有手機在旁邊閃亮。"},{"en":"Flashing beside them means a phone or screen lights up repeatedly near them.","zh":"在旁邊閃亮，意思是手機或螢幕在身邊反覆亮起。"},{"en":"A student may lose focus if a phone keeps flashing beside them while studying.","zh":"如果手機在旁邊不斷閃亮，學生溫習時可能失去專注。"},{"en":"A phone flashing beside someone can make them feel they must respond.","zh":"手機在某人旁邊閃亮，可能令他覺得必須回覆。"},{"en":"The letter argues that staff deserve meals without work notifications flashing beside them.","zh":"這封信指出，員工應享有沒有工作通知在旁邊閃亮的用餐時間。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"leaves people anxious","meaning":"令人感到焦慮","examples":[{"en":"A poor system leaves people anxious when notifications appear.","zh":"差劣制度會在通知出現時令人感到焦慮。"},{"en":"Leaves people anxious means makes people feel worried or tense.","zh":"令人感到焦慮，意思是令人擔心或緊張。"},{"en":"Unclear exam rules can leave students anxious before a test.","zh":"不清晰的考試規則可能令學生在測驗前感到焦慮。"},{"en":"Constant alerts leave people anxious because they expect new demands.","zh":"不斷出現的提示令人感到焦慮，因為人們預期有新要求。"},{"en":"A communication system is unhealthy if it leaves people anxious after work.","zh":"如果溝通制度令人在下班後感到焦慮，它就是不健康的。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"whenever a notification appears","meaning":"每當通知出現時","examples":[{"en":"Some people feel anxious whenever a notification appears.","zh":"有些人每當通知出現時都感到焦慮。"},{"en":"Whenever a notification appears means every time a phone or computer alert shows up.","zh":"每當通知出現時，意思是每一次手機或電腦提示出現時。"},{"en":"A student may look at their phone whenever a notification appears.","zh":"學生可能每當通知出現時就查看手機。"},{"en":"If work pressure is high, employees may worry whenever a notification appears.","zh":"如果工作壓力很高，員工每當通知出現時都可能擔心。"},{"en":"The policy aims to stop staff feeling afraid whenever a notification appears after hours.","zh":"政策旨在阻止員工在下班後每當通知出現時都感到害怕。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"it is not efficient; it is unhealthy","meaning":"這不是高效，而是不健康","examples":[{"en":"If a system causes anxiety, it is not efficient; it is unhealthy.","zh":"如果一個制度造成焦慮，這不是高效，而是不健康。"},{"en":"It is not efficient; it is unhealthy means something may look productive but actually harms people.","zh":"這不是高效，而是不健康，意思是某事看似有效率，但其實傷害人。"},{"en":"Studying all night is not efficient; it is unhealthy if it destroys sleep.","zh":"如果通宵溫習破壞睡眠，這不是高效，而是不健康。"},{"en":"A workplace that demands instant replies may seem fast, but it is unhealthy.","zh":"要求即時回覆的工作場所可能看似快速，但其實不健康。"},{"en":"The sentence rejects the idea that constant availability is good management.","zh":"這句話否定了永遠待命是良好管理的想法。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"I hear you","meaning":"我聽到你們的意見","examples":[{"en":"The Managing Director says, “I hear you.”","zh":"董事總經理說：「我聽到你們的意見。」"},{"en":"I hear you means I understand your concern and am listening seriously.","zh":"我聽到你們的意見，意思是我明白你們的憂慮，並正在認真聆聽。"},{"en":"A teacher may say “I hear you” when students explain why homework is too much.","zh":"當學生解釋功課太多，老師可能說「我聽到你們的意見」。"},{"en":"Saying “I hear you” can help people feel respected before a solution is offered.","zh":"在提出解決方法前說「我聽到你們的意見」，可以令人感到受尊重。"},{"en":"The Managing Director uses this phrase to show staff their complaints matter.","zh":"董事總經理使用這句話，表示員工的投訴很重要。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"apologise that","meaning":"為……道歉","examples":[{"en":"He apologises that the issue was not addressed earlier.","zh":"他為這個問題沒有更早處理而道歉。"},{"en":"To apologise that means to say sorry because something happened or did not happen.","zh":"為某事道歉，意思是因某事發生或沒有發生而表示歉意。"},{"en":"A principal may apologise that parents were not informed sooner.","zh":"校長可能為家長沒有更早獲通知而道歉。"},{"en":"Leaders apologise when they accept responsibility for a delay or mistake.","zh":"當領導者承認延誤或錯誤的責任，就會道歉。"},{"en":"The Managing Director apologises that staff concerns were not handled earlier.","zh":"董事總經理為員工憂慮沒有更早處理而道歉。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"addressed earlier","meaning":"更早處理","examples":[{"en":"The issue should have been addressed earlier.","zh":"這個問題本應更早處理。"},{"en":"Addressed earlier means dealt with sooner.","zh":"更早處理，意思是更早去應對或解決。"},{"en":"A broken lift should have been addressed earlier before students complained.","zh":"壞掉的升降機本應在學生投訴前更早處理。"},{"en":"Problems often become bigger when they are not addressed earlier.","zh":"問題如果沒有更早處理，常會變得更大。"},{"en":"The company admits that after-hours messages should have been addressed earlier.","zh":"公司承認下班後訊息問題本應更早處理。"}],"source":"2018 Q3.pdf","sourcePage":5},{"front":"from 1 May","meaning":"自5月1日起","examples":[{"en":"From 1 May, Reboot Online will adopt a new policy.","zh":"自5月1日起，Reboot Online 將採用一項新政策。"},{"en":"From 1 May means starting on the first day of May.","zh":"自5月1日起，意思是由五月一日開始。"},{"en":"From 1 May, students must use the new library booking system.","zh":"自5月1日起，學生必須使用新的圖書館預約系統。"},{"en":"Giving a clear start date helps everyone prepare for a new rule.","zh":"給出清晰開始日期，可以幫助所有人準備新規則。"},{"en":"From 1 May, staff will follow the new after-hours communication policy.","zh":"自5月1日起，員工將遵守新的下班後溝通政策。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"adopt a policy","meaning":"採用一項政策","examples":[{"en":"Reboot Online will adopt an after-hours communication policy.","zh":"Reboot Online 將採用一項下班後溝通政策。"},{"en":"To adopt a policy means to officially accept and begin using a rule or plan.","zh":"採用一項政策，意思是正式接受並開始使用某項規則或計劃。"},{"en":"A school may adopt a policy on healthy lunches.","zh":"學校可能採用一項健康午餐政策。"},{"en":"Companies adopt policies when they want behaviour to change across the workplace.","zh":"公司想改變整個工作場所的行為時，會採用政策。"},{"en":"Reboot Online will adopt this policy to protect staff from unnecessary messages.","zh":"Reboot Online 將採用這項政策，以保護員工免受不必要訊息打擾。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"after-hours communication policy","meaning":"下班後溝通政策","examples":[{"en":"The company will adopt an after-hours communication policy.","zh":"公司將採用下班後溝通政策。"},{"en":"An after-hours communication policy is a rule about contacting staff outside office hours.","zh":"下班後溝通政策，是關於辦公時間以外聯絡員工的規則。"},{"en":"A school may create a policy about when teachers should reply to parent messages.","zh":"學校可能制定一項政策，說明老師何時應回覆家長訊息。"},{"en":"An after-hours communication policy helps people know what can wait.","zh":"下班後溝通政策幫助人們知道甚麼可以等待。"},{"en":"This policy protects staff by setting limits on night and weekend messages.","zh":"這項政策透過限制夜晚和週末訊息來保護員工。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"unless a matter is genuinely urgent","meaning":"除非事情真正緊急","examples":[{"en":"Staff should not send messages unless a matter is genuinely urgent.","zh":"除非事情真正緊急，否則員工不應發送訊息。"},{"en":"Unless a matter is genuinely urgent means except when the issue truly cannot wait.","zh":"除非事情真正緊急，意思是除了問題真的不能等待之外。"},{"en":"Students should not call a teacher at night unless a matter is genuinely urgent.","zh":"除非事情真正緊急，否則學生不應在晚上致電老師。"},{"en":"This rule prevents ordinary tasks from pretending to be emergencies.","zh":"這條規則防止普通任務被假裝成緊急事件。"},{"en":"Staff should pause before sending a message and ask whether it is genuinely urgent.","zh":"員工發送訊息前應停一停，問自己事情是否真正緊急。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"genuinely urgent","meaning":"真正緊急","examples":[{"en":"Only genuinely urgent matters should be sent after hours.","zh":"只有真正緊急的事項才應在下班後發送。"},{"en":"Genuinely urgent means truly needing immediate attention and unable to wait.","zh":"真正緊急，意思是真的需要立即關注，不能等待。"},{"en":"A fire alarm is genuinely urgent, but a normal timetable question is not.","zh":"火警鐘是真正緊急，但普通時間表問題不是。"},{"en":"Labelling everything as genuinely urgent makes real emergencies harder to see.","zh":"把所有事情都標記為真正緊急，會令真正緊急事件更難看見。"},{"en":"The policy asks staff to send after-hours messages only when the matter is genuinely urgent.","zh":"政策要求員工只在事情真正緊急時才發送下班後訊息。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"work emails","meaning":"工作電郵","examples":[{"en":"Staff should not send work emails late at night.","zh":"員工不應在深夜發送工作電郵。"},{"en":"Work emails are emails about tasks, projects, clients, or workplace duties.","zh":"工作電郵，是關於任務、項目、客戶或職場職責的電郵。"},{"en":"A work email may ask for approval of a report.","zh":"工作電郵可能要求批核一份報告。"},{"en":"Work emails sent late at night can make staff feel they must respond.","zh":"深夜發出的工作電郵會令員工覺得必須回覆。"},{"en":"Non-urgent work emails should be scheduled for the next working morning.","zh":"非緊急工作電郵應安排在下一個工作天早上發送。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"WhatsApp messages","meaning":"WhatsApp 訊息","examples":[{"en":"Staff should not send WhatsApp messages after hours.","zh":"員工不應在下班後發送 WhatsApp 訊息。"},{"en":"WhatsApp messages are texts or media sent through the WhatsApp app.","zh":"WhatsApp 訊息，是透過 WhatsApp 應用程式發送的文字或媒體訊息。"},{"en":"A team may use WhatsApp messages to confirm meeting times quickly.","zh":"團隊可能使用 WhatsApp 訊息快速確認會議時間。"},{"en":"Work WhatsApp messages can feel personal because they appear beside family chats.","zh":"工作 WhatsApp 訊息可能感覺更私人，因為它們出現在家庭聊天旁邊。"},{"en":"The policy limits WhatsApp messages after hours unless the matter is urgent.","zh":"政策限制下班後 WhatsApp 訊息，除非事情緊急。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"platform notifications","meaning":"平台通知","examples":[{"en":"Platform notifications should not be sent after hours.","zh":"平台通知不應在下班後發送。"},{"en":"Platform notifications are alerts from work tools, apps, or online systems.","zh":"平台通知，是工作工具、應用程式或網上系統發出的提示。"},{"en":"A project app may send platform notifications when a task is updated.","zh":"當任務更新時，項目應用程式可能發出平台通知。"},{"en":"Too many platform notifications can make people check work constantly.","zh":"太多平台通知會令人不斷查看工作。"},{"en":"The company wants non-urgent platform notifications to wait until office hours.","zh":"公司希望非緊急平台通知等到辦公時間才發出。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"between 7.30 p.m. and 8.30 a.m.","meaning":"晚上7時半至早上8時半之間","examples":[{"en":"Staff should not send non-urgent messages between 7.30 p.m. and 8.30 a.m.","zh":"員工不應在晚上7時半至早上8時半之間發送非緊急訊息。"},{"en":"Between 7.30 p.m. and 8.30 a.m. means during the night period from evening to morning.","zh":"晚上7時半至早上8時半之間，意思是由晚上到早上的夜間時段。"},{"en":"Students may be asked not to send class messages between 10 p.m. and 7 a.m.","zh":"學生可能被要求不要在晚上十時至早上七時之間發送班級訊息。"},{"en":"Setting a time range tells people clearly when communication should stop.","zh":"設定時間範圍可以清楚告訴人們何時應停止溝通。"},{"en":"This rule protects rest between 7.30 p.m. and 8.30 a.m.","zh":"這條規則保護晚上7時半至早上8時半之間的休息時間。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"on weekdays","meaning":"在平日","examples":[{"en":"The rule applies between 7.30 p.m. and 8.30 a.m. on weekdays.","zh":"這條規則在平日晚上7時半至早上8時半之間適用。"},{"en":"On weekdays means from Monday to Friday.","zh":"在平日，意思是星期一至星期五。"},{"en":"Many people work or attend school on weekdays.","zh":"很多人在平日工作或上學。"},{"en":"Rules on weekdays may differ from weekend rules because working patterns are different.","zh":"平日規則可能與週末規則不同，因為工作模式不同。"},{"en":"On weekdays, staff should avoid non-urgent messages during the protected night period.","zh":"在平日，員工應避免在受保護的夜間時段發送非緊急訊息。"}],"source":"2018 Q3.pdf","sourcePage":6},{"front":"public holidays","meaning":"公眾假期","examples":[{"en":"The rule also applies during weekends and public holidays.","zh":"這條規則也適用於週末和公眾假期。"},{"en":"Public holidays are official days when many people do not have to work or attend school.","zh":"公眾假期，是很多人不用工作或上學的官方假日。"},{"en":"Lunar New Year and Christmas may be public holidays in some places.","zh":"在某些地方，農曆新年和聖誕節可能是公眾假期。"},{"en":"Work messages on public holidays can disturb family plans and rest.","zh":"公眾假期的工作訊息可以打擾家庭計劃和休息。"},{"en":"The policy protects staff during public holidays as well as weekends.","zh":"這項政策保護員工的公眾假期，也保護週末。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"scheduled for","meaning":"安排在……發送","examples":[{"en":"Messages should be scheduled for the next working morning.","zh":"訊息應安排在下一個工作天早上發送。"},{"en":"Scheduled for a time means arranged to be sent or happen at that time.","zh":"安排在某時間發送，意思是設定訊息在那個時間發出或事情在那時發生。"},{"en":"A teacher may schedule an announcement for Monday morning.","zh":"老師可能把公告安排在星期一早上發送。"},{"en":"Scheduling messages prevents them from disturbing people at night.","zh":"預約發送訊息可以防止它們在晚上打擾人。"},{"en":"Non-urgent emails should be scheduled for office hours instead of sent immediately.","zh":"非緊急電郵應安排在辦公時間發送，而不是立即發出。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"the next working morning","meaning":"下一個工作天早上","examples":[{"en":"Non-urgent messages should be sent the next working morning.","zh":"非緊急訊息應在下一個工作天早上發送。"},{"en":"The next working morning means the next morning when staff are normally at work.","zh":"下一個工作天早上，意思是員工正常上班的下一個早上。"},{"en":"A message written on Friday night may wait until the next working morning, usually Monday.","zh":"星期五晚上寫好的訊息可以等到下一個工作天早上，通常是星期一。"},{"en":"Waiting until the next working morning helps protect evenings and weekends.","zh":"等到下一個工作天早上，有助保護晚上和週末。"},{"en":"The policy encourages staff to send ordinary updates the next working morning.","zh":"這項政策鼓勵員工在下一個工作天早上發送普通進度。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, employees are not expected to reply outside office hours.","zh":"更重要的是，員工毋須在辦公時間以外回覆。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"更重要的是，用來引出比前一點更重要的內容。"},{"en":"The trip was enjoyable; more importantly, everyone returned safely.","zh":"旅程很愉快；更重要的是，所有人都安全回來。"},{"en":"A policy may stop late messages; more importantly, it should remove pressure to reply.","zh":"政策可以停止深夜訊息；更重要的是，它應消除回覆壓力。"},{"en":"The phrase shows that the right not to respond is central to the policy.","zh":"這個短語顯示，不必回應的權利是政策核心。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"are not expected to","meaning":"毋須；不被期望","examples":[{"en":"Employees are not expected to read non-urgent messages after work.","zh":"員工毋須在下班後閱讀非緊急訊息。"},{"en":"Are not expected to means people do not have to do something and should not feel required.","zh":"毋須或不被期望，意思是人們不必做某事，也不應感到被要求。"},{"en":"Students are not expected to answer school emails during holidays.","zh":"學生在假期毋須回覆學校電郵。"},{"en":"If staff are not expected to reply, managers should not punish silence.","zh":"如果員工毋須回覆，經理就不應懲罰沉默。"},{"en":"The policy says employees are not expected to read or reply outside office hours.","zh":"政策指出，員工毋須在辦公時間以外閱讀或回覆。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"read or reply to","meaning":"閱讀或回覆","examples":[{"en":"Employees are not expected to read or reply to non-urgent messages.","zh":"員工毋須閱讀或回覆非緊急訊息。"},{"en":"To read or reply to messages means to open them and answer them.","zh":"閱讀或回覆訊息，意思是打開它們並作答。"},{"en":"A student may read or reply to class messages during lunch, not during sleep time.","zh":"學生可以在午飯時閱讀或回覆班級訊息，而不是在睡覺時間。"},{"en":"If people must read or reply to every alert, they cannot truly rest.","zh":"如果人們必須閱讀或回覆每個提示，他們就不能真正休息。"},{"en":"The policy tells staff they do not need to read or reply to non-urgent messages after work.","zh":"政策告訴員工，下班後不用閱讀或回覆非緊急訊息。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"non-urgent messages","meaning":"非緊急訊息","examples":[{"en":"Staff do not need to reply to non-urgent messages after work.","zh":"員工下班後不需要回覆非緊急訊息。"},{"en":"Non-urgent messages are messages that do not require immediate action.","zh":"非緊急訊息，是不需要立即行動的訊息。"},{"en":"A reminder about next month’s meeting is usually a non-urgent message.","zh":"關於下個月會議的提醒通常是非緊急訊息。"},{"en":"Sending non-urgent messages at night can create unnecessary pressure.","zh":"晚上發送非緊急訊息可能造成不必要壓力。"},{"en":"Under the policy, non-urgent messages should wait until office hours.","zh":"根據政策，非緊急訊息應等到辦公時間。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"outside office hours","meaning":"辦公時間以外","examples":[{"en":"Employees are not expected to reply outside office hours.","zh":"員工毋須在辦公時間以外回覆。"},{"en":"Outside office hours means not during the normal working time.","zh":"辦公時間以外，意思是不在正常工作時間內。"},{"en":"A teacher may choose not to answer parent emails outside office hours.","zh":"老師可能選擇不在辦公時間以外回覆家長電郵。"},{"en":"People need boundaries outside office hours so they can rest properly.","zh":"人們在辦公時間以外需要界線，才能好好休息。"},{"en":"The policy removes the expectation that staff must reply outside office hours.","zh":"這項政策移除了員工必須在辦公時間以外回覆的期望。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"treat something as","meaning":"把……視為","examples":[{"en":"No manager may treat a delayed response as a lack of commitment.","zh":"任何經理都不得把延遲回覆視為缺乏承擔。"},{"en":"To treat something as something else means to regard or judge it in that way.","zh":"把某事視為另一件事，意思是以那種方式看待或判斷它。"},{"en":"A teacher should not treat one mistake as proof that a student is lazy.","zh":"老師不應把一次錯誤視為學生懶惰的證明。"},{"en":"Managers should not treat silence after work as poor attitude.","zh":"經理不應把下班後沉默視為態度差。"},{"en":"The policy says delayed replies must not be treated as lack of commitment.","zh":"政策指出，延遲回覆不得被視為缺乏承擔。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"delayed after-hours response","meaning":"下班後延遲回覆","examples":[{"en":"A delayed after-hours response should not be criticised.","zh":"下班後延遲回覆不應受到批評。"},{"en":"A delayed after-hours response is a reply sent later to a message received outside working time.","zh":"下班後延遲回覆，是對辦公時間以外收到的訊息較遲作出回覆。"},{"en":"A worker may give a delayed after-hours response the next morning.","zh":"員工可能在第二天早上作出下班後延遲回覆。"},{"en":"Delayed after-hours responses are reasonable when the issue is not urgent.","zh":"當事情不緊急，下班後延遲回覆是合理的。"},{"en":"Managers should not criticise a delayed after-hours response as poor commitment.","zh":"經理不應把下班後延遲回覆批評為缺乏承擔。"}],"source":"2018 Q3.pdf","sourcePage":7},{"front":"lack of commitment","meaning":"缺乏承擔","examples":[{"en":"A delayed response is not a lack of commitment.","zh":"延遲回覆並不是缺乏承擔。"},{"en":"Lack of commitment means not showing enough care, effort, or responsibility.","zh":"缺乏承擔，意思是沒有表現出足夠關心、努力或責任感。"},{"en":"Missing practice repeatedly may show a lack of commitment to a team.","zh":"反覆缺席練習可能顯示對團隊缺乏承擔。"},{"en":"Not answering a non-urgent message at night is not lack of commitment.","zh":"晚上不回覆非緊急訊息並不是缺乏承擔。"},{"en":"The policy protects staff from unfair claims of lack of commitment.","zh":"這項政策保護員工，避免他們被不公平地指責缺乏承擔。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"urgent matter","meaning":"緊急事項","examples":[{"en":"An urgent matter means a serious issue that cannot wait.","zh":"緊急事項指不能等待的嚴重問題。"},{"en":"An urgent matter is something that needs immediate attention or action.","zh":"緊急事項，是需要立即關注或行動的事情。"},{"en":"A burst pipe in a school building is an urgent matter.","zh":"學校大樓水管爆裂是緊急事項。"},{"en":"If a matter is urgent, delaying it could cause harm or serious loss.","zh":"如果事情緊急，延遲處理可能造成傷害或嚴重損失。"},{"en":"The policy defines urgent matters so staff know when after-hours contact is allowed.","zh":"這項政策界定緊急事項，讓員工知道何時容許下班後聯絡。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"live client-system failure","meaning":"正在運作的客戶系統故障","examples":[{"en":"A live client-system failure counts as an urgent matter.","zh":"正在運作的客戶系統故障算作緊急事項。"},{"en":"A live client-system failure is a breakdown in a customer’s active online service or system.","zh":"正在運作的客戶系統故障，是客戶正在使用的網上服務或系統出現故障。"},{"en":"If a client’s payment system stops working during business hours, that may be a live client-system failure.","zh":"如果客戶的付款系統在營業期間停止運作，那可能是正在運作的客戶系統故障。"},{"en":"Such failures are urgent because customers may lose service or money.","zh":"這類故障緊急，因為客戶可能失去服務或金錢。"},{"en":"The policy allows after-hours contact for a live client-system failure.","zh":"這項政策容許因正在運作的客戶系統故障而在下班後聯絡。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"security risk","meaning":"保安風險","examples":[{"en":"A security risk may require immediate action.","zh":"保安風險可能需要立即行動。"},{"en":"A security risk is a danger that could harm data, systems, property, or people.","zh":"保安風險，是可能傷害數據、系統、財產或人的危險。"},{"en":"A stolen company laptop can become a security risk if it contains private data.","zh":"如果被偷的公司手提電腦含有私人資料，就可能成為保安風險。"},{"en":"Security risks must be handled quickly because damage can spread.","zh":"保安風險必須迅速處理，因為損害可以擴散。"},{"en":"After-hours contact is allowed when a real security risk appears.","zh":"當真正保安風險出現時，下班後聯絡是容許的。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"legal deadline within 24 hours","meaning":"24小時內的法律期限","examples":[{"en":"A legal deadline within 24 hours is an urgent matter.","zh":"24小時內的法律期限是緊急事項。"},{"en":"A legal deadline within 24 hours is a law-related due time that must be met before one day passes.","zh":"24小時內的法律期限，是必須在一天內完成的法律相關限期。"},{"en":"A company may need to submit documents before a legal deadline within 24 hours.","zh":"公司可能需要在24小時內的法律期限前提交文件。"},{"en":"Missing a legal deadline can create penalties or serious consequences.","zh":"錯過法律期限可能造成罰款或嚴重後果。"},{"en":"The policy treats a legal deadline within 24 hours as urgent.","zh":"這項政策把24小時內的法律期限視為緊急。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"operational issue","meaning":"營運問題","examples":[{"en":"An operational issue may become urgent if it would cause serious damage.","zh":"如果營運問題會造成嚴重損害，它可能變成緊急事項。"},{"en":"An operational issue is a problem affecting how daily work or services run.","zh":"營運問題，是影響日常工作或服務運作的問題。"},{"en":"A broken delivery system can be an operational issue for an online shop.","zh":"壞掉的送貨系統可能是網店的營運問題。"},{"en":"Operational issues are not always urgent, but some can become serious quickly.","zh":"營運問題不一定緊急，但有些可以很快變得嚴重。"},{"en":"The policy allows contact only when an operational issue cannot wait safely.","zh":"政策只在營運問題不能安全等待時容許聯絡。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"cause serious damage","meaning":"造成嚴重損害","examples":[{"en":"The issue would cause serious damage if left until morning.","zh":"如果這個問題留到早上才處理，會造成嚴重損害。"},{"en":"To cause serious damage means to create major harm, loss, or disruption.","zh":"造成嚴重損害，意思是產生重大傷害、損失或干擾。"},{"en":"Ignoring a water leak overnight could cause serious damage to a classroom.","zh":"整晚不理會漏水，可能對課室造成嚴重損害。"},{"en":"Some problems must be fixed quickly because delay can cause serious damage.","zh":"有些問題必須迅速修理，因為延誤會造成嚴重損害。"},{"en":"Only issues that may cause serious damage should interrupt staff after hours.","zh":"只有可能造成嚴重損害的問題才應在下班後打擾員工。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"if left until morning","meaning":"如果留到早上才處理","examples":[{"en":"Some problems would cause serious damage if left until morning.","zh":"有些問題如果留到早上才處理，會造成嚴重損害。"},{"en":"If left until morning means if the problem is not handled until the next morning.","zh":"如果留到早上才處理，意思是問題到第二天早上才處理。"},{"en":"A small leak may flood a room if left until morning.","zh":"小漏水如果留到早上才處理，可能淹浸房間。"},{"en":"If a problem can wait safely, it should be left until morning.","zh":"如果問題可以安全等待，就應留到早上才處理。"},{"en":"The policy allows urgent contact only when waiting until morning would be harmful.","zh":"只有當等到早上會有害時，政策才容許緊急聯絡。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"anything else","meaning":"其他任何事情","examples":[{"en":"Anything else must wait until office hours.","zh":"其他任何事情都必須等到辦公時間。"},{"en":"Anything else means all other matters not included in the urgent category.","zh":"其他任何事情，意思是不屬於緊急類別的所有其他事項。"},{"en":"If the message is not about safety, systems, or legal deadlines, it may be anything else.","zh":"如果訊息不是關於安全、系統或法律期限，它可能屬於其他任何事情。"},{"en":"Saying anything else must wait helps make the rule simple.","zh":"說其他任何事情都必須等待，有助令規則簡單。"},{"en":"The policy is strict: anything else should not disturb people’s rest.","zh":"這項政策很清楚：其他任何事情都不應打擾人們休息。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"however important it may feel","meaning":"不論當下感覺多重要","examples":[{"en":"Anything else, however important it may feel at midnight, must wait.","zh":"其他任何事情，不論午夜時當下感覺多重要，都必須等待。"},{"en":"However important it may feel means even if it seems very important at that moment.","zh":"不論當下感覺多重要，意思是即使那一刻看起來非常重要。"},{"en":"A homework question, however important it may feel at night, can usually wait until school.","zh":"功課問題不論晚上感覺多重要，通常都可以等到上學時。"},{"en":"Stress can make ordinary tasks feel urgent when they are not.","zh":"壓力會令普通任務感覺緊急，即使它們其實不是。"},{"en":"The phrase reminds staff to separate real urgency from midnight pressure.","zh":"這個短語提醒員工分清真正緊急和午夜壓力。"}],"source":"2018 Q3.pdf","sourcePage":8},{"front":"must wait","meaning":"必須等待","examples":[{"en":"Non-urgent matters must wait.","zh":"非緊急事項必須等待。"},{"en":"Must wait means cannot be dealt with immediately and should be delayed.","zh":"必須等待，意思是不能立即處理，應該延後。"},{"en":"A club announcement must wait if the teacher is handling an emergency.","zh":"如果老師正在處理緊急事件，學會公告必須等待。"},{"en":"When something must wait, people should not keep pushing for an answer.","zh":"當某事必須等待，人們不應一直催促答案。"},{"en":"Under the policy, ordinary work questions must wait until office hours.","zh":"根據政策，普通工作問題必須等到辦公時間。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"improve communication","meaning":"改善溝通","examples":[{"en":"The company will improve communication during office hours.","zh":"公司將在辦公時間內改善溝通。"},{"en":"To improve communication means to make information clearer, better timed, and easier to understand.","zh":"改善溝通，意思是令資訊更清楚、時間更合適、更容易理解。"},{"en":"A class can improve communication by writing homework instructions on one board.","zh":"班級可以把功課指示寫在同一塊板上，以改善溝通。"},{"en":"Better communication reduces repeated questions and late confusion.","zh":"更好的溝通可以減少重複問題和深夜混亂。"},{"en":"The company wants to improve communication so fewer messages are needed after work.","zh":"公司希望改善溝通，讓下班後需要發送的訊息減少。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"during office hours","meaning":"在辦公時間內","examples":[{"en":"Communication should be improved during office hours.","zh":"溝通應在辦公時間內改善。"},{"en":"During office hours means within the normal working period of the day.","zh":"在辦公時間內，意思是在一天正常工作時段之中。"},{"en":"Staff can ask questions during office hours instead of sending messages at night.","zh":"員工可以在辦公時間內提問，而不是晚上發訊息。"},{"en":"Handling tasks during office hours protects personal time after work.","zh":"在辦公時間內處理任務，可以保護下班後的私人時間。"},{"en":"The company wants important updates to happen during office hours whenever possible.","zh":"公司希望重要進度盡可能在辦公時間內發出。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"spill over into","meaning":"延伸至；蔓延到","examples":[{"en":"Fewer matters should spill over into private time.","zh":"較少事情應延伸至私人時間。"},{"en":"To spill over into something means to spread beyond its proper place and affect another area.","zh":"延伸至或蔓延到某處，意思是超出原本範圍並影響另一個領域。"},{"en":"School stress can spill over into family life if students never rest.","zh":"如果學生從不休息，學校壓力可能蔓延到家庭生活。"},{"en":"Work problems spill over into private time when messages continue at night.","zh":"當訊息晚上仍持續，工作問題就會延伸至私人時間。"},{"en":"Better planning helps stop office duties from spilling over into evenings.","zh":"更好規劃有助阻止辦公室職責延伸至晚上。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"private time","meaning":"私人時間","examples":[{"en":"Work matters should not spill over into private time.","zh":"工作事項不應延伸至私人時間。"},{"en":"Private time is time outside work that belongs to a person’s own life.","zh":"私人時間，是工作以外屬於個人生活的時間。"},{"en":"Exercising after work can be valuable private time.","zh":"下班後運動可以是寶貴的私人時間。"},{"en":"Private time is protected when managers avoid unnecessary messages.","zh":"當經理避免不必要訊息，私人時間就得到保護。"},{"en":"The policy draws a boundary so work matters do not enter private time too easily.","zh":"這項政策劃下界線，使工作事項不會太容易進入私人時間。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"set aside","meaning":"預留","examples":[{"en":"Each department will set aside two fixed windows for updates.","zh":"每個部門將預留兩個固定時段用於更新進度。"},{"en":"To set aside time means to reserve it for a particular purpose.","zh":"預留時間，意思是把時間保留給特定用途。"},{"en":"A student may set aside thirty minutes each day for reading.","zh":"學生可能每天預留三十分鐘閱讀。"},{"en":"Departments set aside update windows so information does not arrive all day.","zh":"部門預留更新時段，使資訊不會一整天不斷出現。"},{"en":"Setting aside fixed times makes communication calmer and more organised.","zh":"預留固定時間令溝通更冷靜、更有組織。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"fixed windows","meaning":"固定時段","examples":[{"en":"Each department will set aside fixed windows for project updates.","zh":"每個部門將為項目最新進度預留固定時段。"},{"en":"Fixed windows are set periods of time reserved for a certain activity.","zh":"固定時段，是為某項活動保留的指定時間。"},{"en":"A school may have fixed windows for parents to call teachers.","zh":"學校可能設有固定時段讓家長致電老師。"},{"en":"Fixed windows reduce interruptions because people know when updates will arrive.","zh":"固定時段可以減少干擾，因為人們知道進度何時會到達。"},{"en":"The company uses fixed windows to stop constant messaging.","zh":"公司使用固定時段來阻止不斷發訊息。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"project updates","meaning":"項目最新進度","examples":[{"en":"Departments will share project updates in batches.","zh":"各部門將分批分享項目最新進度。"},{"en":"Project updates are new pieces of information about the progress or changes of a project.","zh":"項目最新進度，是關於項目進展或變化的新資訊。"},{"en":"A team may give project updates every Friday afternoon.","zh":"團隊可能每個星期五下午提供項目最新進度。"},{"en":"Project updates should be clear so people know what has changed.","zh":"項目最新進度應清楚，讓人知道甚麼已改變。"},{"en":"Sharing project updates in batches reduces constant interruptions.","zh":"分批分享項目最新進度可以減少不斷出現的干擾。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"shared in batches","meaning":"分批分享","examples":[{"en":"Information will be shared in batches.","zh":"資訊將會分批分享。"},{"en":"Shared in batches means sent or given in groups, not one small piece at a time.","zh":"分批分享，意思是成組發送或提供，而不是一次一小部分。"},{"en":"A teacher may share notices in batches at the end of the day.","zh":"老師可能在一天結束時分批分享通知。"},{"en":"Information shared in batches is easier to manage than constant alerts.","zh":"分批分享的資訊比不斷提示更容易處理。"},{"en":"The company will share updates in batches to protect focus time.","zh":"公司將分批分享最新進度，以保護專注時間。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"email subject lines","meaning":"電郵主旨","examples":[{"en":"Email subject lines should state the action required.","zh":"電郵主旨應說明所需行動。"},{"en":"Email subject lines are the short titles that show what emails are about.","zh":"電郵主旨，是顯示電郵內容的簡短標題。"},{"en":"A clear email subject line helps readers know whether they must act.","zh":"清晰的電郵主旨幫助讀者知道自己是否必須行動。"},{"en":"Poor subject lines create confusion because people cannot judge urgency.","zh":"差劣的主旨會造成混亂，因為人們不能判斷緊急程度。"},{"en":"The company wants subject lines to show the deadline and required action.","zh":"公司希望電郵主旨顯示截止日期和所需行動。"}],"source":"2018 Q3.pdf","sourcePage":9},{"front":"state the action required","meaning":"說明所需行動","examples":[{"en":"Subject lines should state the action required.","zh":"主旨應說明所需行動。"},{"en":"To state the action required means to clearly say what the reader needs to do.","zh":"說明所需行動，意思是清楚指出讀者需要做甚麼。"},{"en":"A message should state the action required, such as “please approve” or “please review.”","zh":"訊息應說明所需行動，例如「請批核」或「請審閱」。"},{"en":"If emails do not state the action required, people may waste time guessing.","zh":"如果電郵沒有說明所需行動，人們可能浪費時間猜測。"},{"en":"Clear subject lines state the action required before the reader opens the email.","zh":"清晰主旨在讀者打開電郵前已說明所需行動。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"the deadline and the urgency","meaning":"截止日期和緊急程度","examples":[{"en":"Subject lines should state the deadline and the urgency.","zh":"主旨應說明截止日期和緊急程度。"},{"en":"The deadline and the urgency means when something is due and how quickly it needs attention.","zh":"截止日期和緊急程度，意思是某事何時到期，以及需要多快處理。"},{"en":"A homework notice should show the deadline and urgency so students can plan.","zh":"功課通知應顯示截止日期和緊急程度，讓學生可以計劃。"},{"en":"Messages without the deadline and urgency may make everything feel equally important.","zh":"沒有截止日期和緊急程度的訊息，可能令所有事情感覺同樣重要。"},{"en":"Clear emails reduce stress by showing both the deadline and the urgency.","zh":"清晰電郵透過顯示截止日期和緊急程度來減少壓力。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"for approval by Friday 4 p.m.","meaning":"於星期五下午4時前批核","examples":[{"en":"“For approval by Friday 4 p.m.” is a clear subject line.","zh":"「於星期五下午4時前批核」是一個清晰主旨。"},{"en":"For approval by Friday 4 p.m. means someone must review and approve something before that time.","zh":"於星期五下午4時前批核，意思是某人必須在那個時間前審閱並批准某事。"},{"en":"A teacher may write “For correction by Monday 9 a.m.” to make a task clear.","zh":"老師可能寫「於星期一上午9時前修改」，使任務清楚。"},{"en":"This subject line works because it states both the action and the deadline.","zh":"這個主旨有效，因為它同時說明行動和截止日期。"},{"en":"It is clearer than “quick question” because readers know exactly what is needed.","zh":"它比「quick question」更清晰，因為讀者確切知道需要甚麼。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"far better than","meaning":"遠比……好","examples":[{"en":"A clear subject line is far better than “Quick question”.","zh":"清晰主旨遠比「Quick question」好。"},{"en":"Far better than means much better than something else.","zh":"遠比某事好，意思是比另一件事好得多。"},{"en":"Clear instructions are far better than vague hints before an exam.","zh":"考試前，清晰指示遠比含糊提示好。"},{"en":"A precise deadline is far better than a message that simply says “soon.”","zh":"精確截止日期遠比只說「很快」的訊息好。"},{"en":"“For approval by Friday 4 p.m.” is far better than “Quick question” because it reduces guessing.","zh":"「於星期五下午4時前批核」遠比「Quick question」好，因為它減少猜測。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"distinguish between","meaning":"區分","examples":[{"en":"Managers should distinguish between different types of messages.","zh":"經理應區分不同類型的訊息。"},{"en":"To distinguish between things means to recognise how they are different.","zh":"區分事物，意思是辨認它們之間的不同。"},{"en":"Students learn to distinguish between facts and opinions in reading lessons.","zh":"學生在閱讀課中學習區分事實和意見。"},{"en":"Managers must distinguish between urgent tasks and ordinary updates.","zh":"經理必須區分緊急任務和普通進度。"},{"en":"Distinguishing between message types helps staff know what needs action.","zh":"區分訊息類型幫助員工知道甚麼需要行動。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"for information","meaning":"供參考","examples":[{"en":"Managers should mark some messages as for information.","zh":"經理應把某些訊息標記為供參考。"},{"en":"For information means the message is only to inform people, not to ask for action.","zh":"供參考，意思是訊息只是提供資訊，而不是要求行動。"},{"en":"A school notice about a past event may be marked for information.","zh":"關於過去活動的學校通知可能標記為供參考。"},{"en":"Labelling messages for information reduces pressure because no reply is needed.","zh":"把訊息標記為供參考可以減少壓力，因為不需要回覆。"},{"en":"Staff can read for-information messages when they have time.","zh":"員工可以在有時間時閱讀供參考的訊息。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"for discussion","meaning":"供討論","examples":[{"en":"Some messages should be marked as for discussion.","zh":"有些訊息應標記為供討論。"},{"en":"For discussion means the message is meant to be talked about before a decision is made.","zh":"供討論，意思是訊息需要先談論，然後才作決定。"},{"en":"A teacher may mark a class rule proposal as for discussion.","zh":"老師可能把班規建議標記為供討論。"},{"en":"Messages for discussion should usually wait for a meeting or office hours.","zh":"供討論的訊息通常應等到會議或辦公時間處理。"},{"en":"Marking something for discussion shows that immediate action is not always required.","zh":"把某事標記為供討論，顯示不一定需要立即行動。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"for action","meaning":"需要行動","examples":[{"en":"Urgent tasks should be marked as for action.","zh":"緊急任務應標記為需要行動。"},{"en":"For action means the reader must do something, not just read the message.","zh":"需要行動，意思是讀者必須做某事，而不只是閱讀訊息。"},{"en":"A message marked for action may ask someone to approve, call, or repair something.","zh":"標記為需要行動的訊息可能要求某人批核、致電或修理某物。"},{"en":"Clear “for action” labels help people avoid missing important tasks.","zh":"清晰的「需要行動」標籤幫助人們避免遺漏重要任務。"},{"en":"Managers should use “for action” carefully so staff know what truly needs response.","zh":"經理應小心使用「需要行動」，讓員工知道甚麼真正需要回應。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"such simple practices","meaning":"這些簡單做法","examples":[{"en":"Such simple practices will reduce confusion.","zh":"這些簡單做法將減少混亂。"},{"en":"Such simple practices means these easy habits or methods just mentioned.","zh":"這些簡單做法，意思是剛剛提到的容易習慣或方法。"},{"en":"Writing clear titles and deadlines are such simple practices that help a class run smoothly.","zh":"寫清楚標題和截止日期，就是幫助班級順利運作的簡單做法。"},{"en":"Simple practices can make a big difference when everyone follows them.","zh":"當每個人都遵守，簡單做法可以帶來很大分別。"},{"en":"In this policy, simple practices include clear subject lines and fixed update windows.","zh":"在這項政策中，簡單做法包括清晰主旨和固定更新時段。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"reduce confusion","meaning":"減少混亂","examples":[{"en":"Clear communication can reduce confusion.","zh":"清晰溝通可以減少混亂。"},{"en":"To reduce confusion means to make people less uncertain about what is happening or what to do.","zh":"減少混亂，意思是令人較不疑惑發生甚麼或應做甚麼。"},{"en":"A clear timetable can reduce confusion on the first day of school.","zh":"清晰時間表可以減少開學第一天的混亂。"},{"en":"Confusion is reduced when messages state deadlines and actions clearly.","zh":"當訊息清楚說明截止日期和行動，混亂就會減少。"},{"en":"The policy reduces confusion by making urgent and non-urgent messages easier to tell apart.","zh":"這項政策透過令緊急和非緊急訊息更容易分辨來減少混亂。"}],"source":"2018 Q3.pdf","sourcePage":10},{"front":"prevent duplication","meaning":"避免重複","examples":[{"en":"Clear updates can prevent duplication.","zh":"清晰的最新進度可以避免重複。"},{"en":"To prevent duplication means to stop people from doing the same work unnecessarily.","zh":"避免重複，意思是阻止人們不必要地做同一項工作。"},{"en":"A shared class checklist can prevent duplication when students organise an event.","zh":"共享班級清單可以在學生籌辦活動時避免重複。"},{"en":"Duplication wastes time because two people may complete the same task.","zh":"重複會浪費時間，因為兩個人可能完成同一任務。"},{"en":"Clear project updates prevent duplication by showing who has already done what.","zh":"清晰項目進度透過顯示誰已做了甚麼來避免重複。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"breathing room","meaning":"喘息空間","examples":[{"en":"Better communication gives everyone more breathing room.","zh":"更好的溝通給每個人更多喘息空間。"},{"en":"Breathing room means space or time to think, rest, or work without pressure.","zh":"喘息空間，意思是可以思考、休息或無壓力工作的空間或時間。"},{"en":"A student needs breathing room between exams to recover.","zh":"學生在考試之間需要喘息空間來恢復。"},{"en":"Clear schedules create breathing room because people are not surprised by last-minute tasks.","zh":"清晰時間表創造喘息空間，因為人們不會被最後一刻任務突襲。"},{"en":"The policy gives staff breathing room by reducing constant after-hours contact.","zh":"這項政策透過減少持續的下班後聯絡，給員工喘息空間。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, clear messages make for calmer teams.","zh":"簡單來說，清晰訊息有助團隊更冷靜。"},{"en":"Put simply means said in a simple and direct way.","zh":"簡單來說，意思是用簡單直接的方式說。"},{"en":"Put simply, sleep helps students learn better.","zh":"簡單來說，睡眠幫助學生學得更好。"},{"en":"Writers use put simply before giving the main idea without extra detail.","zh":"作者在不加額外細節地說出主要意思前，會使用「簡單來說」。"},{"en":"Put simply, the policy asks people to communicate clearly and respect rest.","zh":"簡單來說，這項政策要求人們清晰溝通並尊重休息。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"make for calmer teams","meaning":"有助團隊更冷靜","examples":[{"en":"Clear messages make for calmer teams.","zh":"清晰訊息有助團隊更冷靜。"},{"en":"To make for calmer teams means to help teams become less stressed and more steady.","zh":"有助團隊更冷靜，意思是幫助團隊減少壓力並更穩定。"},{"en":"Clear homework instructions make for calmer students before deadlines.","zh":"清晰功課指示有助學生在限期前更冷靜。"},{"en":"Better planning makes for calmer teams because fewer problems appear suddenly.","zh":"更好規劃有助團隊更冷靜，因為較少問題突然出現。"},{"en":"Clear messages make for calmer teams by reducing guessing and repeated questions.","zh":"清晰訊息透過減少猜測和重複問題，有助團隊更冷靜。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"review workloads","meaning":"檢視工作量","examples":[{"en":"The company will review workloads, not merely message habits.","zh":"公司將檢視工作量，而不只是發訊習慣。"},{"en":"To review workloads means to examine how much work people have and whether it is reasonable.","zh":"檢視工作量，意思是檢查人們有多少工作，以及是否合理。"},{"en":"A school may review workloads if students have too much homework every night.","zh":"如果學生每晚功課太多，學校可能檢視工作量。"},{"en":"Reviewing workloads helps leaders find pressure that late messages only reveal.","zh":"檢視工作量幫助領導者找出深夜訊息只是揭示出來的壓力。"},{"en":"The company will review workloads to see whether deadlines and staffing are realistic.","zh":"公司將檢視工作量，以了解限期和人手是否切實際。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"not merely","meaning":"不只是","examples":[{"en":"The company will review workloads, not merely message habits.","zh":"公司將檢視工作量，而不只是發訊習慣。"},{"en":"Not merely means not only or not just one limited thing.","zh":"不只是，意思是不僅僅是某一件有限的事情。"},{"en":"A school should improve learning, not merely exam scores.","zh":"學校應改善學習，而不只是考試分數。"},{"en":"The problem may involve planning, not merely communication style.","zh":"問題可能涉及規劃，而不只是溝通方式。"},{"en":"The phrase shows that the company wants to look beyond surface behaviour.","zh":"這個短語顯示，公司想看得比表面行為更深入。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"message habits","meaning":"發訊習慣","examples":[{"en":"Late-night messages may reveal unhealthy message habits.","zh":"深夜訊息可能反映不健康的發訊習慣。"},{"en":"Message habits are the usual ways people send, read, or reply to messages.","zh":"發訊習慣，是人們發送、閱讀或回覆訊息的慣常方式。"},{"en":"Checking every notification immediately is a common message habit.","zh":"立即查看每個通知是一種常見發訊習慣。"},{"en":"Unhealthy message habits can make people feel permanently available.","zh":"不健康的發訊習慣會令人覺得自己永遠待命。"},{"en":"The company wants to improve message habits by setting clearer rules.","zh":"公司希望透過設定更清晰規則來改善發訊習慣。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"contacting one another","meaning":"彼此聯絡","examples":[{"en":"Staff may be contacting one another late at night.","zh":"員工可能在深夜彼此聯絡。"},{"en":"Contacting one another means communicating with each other by message, call, or email.","zh":"彼此聯絡，意思是互相透過訊息、電話或電郵溝通。"},{"en":"Students may contact one another to plan a group project.","zh":"學生可能彼此聯絡以計劃小組 project。"},{"en":"Contacting one another late at night can create pressure even when no one intends harm.","zh":"深夜彼此聯絡可能造成壓力，即使沒有人有意傷害。"},{"en":"The policy limits when staff should be contacting one another about work.","zh":"這項政策限制員工何時應就工作彼此聯絡。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"deadlines are unrealistic","meaning":"截止日期不切實際","examples":[{"en":"If staff work late, deadlines may be unrealistic.","zh":"如果員工工作到很晚，截止日期可能不切實際。"},{"en":"Deadlines are unrealistic means the due dates are too difficult to meet with the available time and resources.","zh":"截止日期不切實際，意思是限期以現有時間和資源來看太難完成。"},{"en":"A homework deadline is unrealistic if students need ten hours to finish it overnight.","zh":"如果學生要一晚用十小時完成作業，功課限期就是不切實際。"},{"en":"Unrealistic deadlines often lead to stress and late messages.","zh":"不切實際的截止日期常導致壓力和深夜訊息。"},{"en":"The company will review timelines to see whether deadlines are unrealistic.","zh":"公司將檢視時間表，以了解截止日期是否不切實際。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"not so much… as…","meaning":"與其說是……不如說是……","examples":[{"en":"The problem is not so much communication as planning.","zh":"這個問題與其說是溝通，不如說是規劃。"},{"en":"Not so much A as B means B is the real issue more than A.","zh":"與其說是 A，不如說是 B，意思是 B 比 A 更接近真正問題。"},{"en":"The student’s problem is not so much laziness as lack of sleep.","zh":"這名學生的問題與其說是懶惰，不如說是睡眠不足。"},{"en":"This structure helps writers correct a mistaken explanation.","zh":"這個結構幫助作者修正錯誤解釋。"},{"en":"The letter suggests the issue is not so much message style as poor workload planning.","zh":"這封信暗示，問題與其說是訊息方式，不如說是工作量規劃差。"}],"source":"2018 Q3.pdf","sourcePage":11},{"front":"department heads","meaning":"部門主管","examples":[{"en":"Department heads will review project timelines every Monday.","zh":"部門主管將每星期一檢視項目時間表。"},{"en":"Department heads are the people responsible for leading each department.","zh":"部門主管，是負責領導各部門的人。"},{"en":"A department head may organise tasks for teachers in the English department.","zh":"部門主管可能為英文科老師安排任務。"},{"en":"Department heads can reduce pressure by checking whether deadlines are realistic.","zh":"部門主管可以透過檢查限期是否切實際來減少壓力。"},{"en":"In the policy, department heads must review timelines regularly.","zh":"在這項政策中，部門主管必須定期檢視時間表。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"project timelines","meaning":"項目時間表","examples":[{"en":"Department heads will review project timelines.","zh":"部門主管將檢視項目時間表。"},{"en":"Project timelines are plans showing when project tasks should happen or finish.","zh":"項目時間表，是顯示項目任務何時進行或完成的計劃。"},{"en":"A school play needs a project timeline for auditions, rehearsals, and performance day.","zh":"學校戲劇需要項目時間表，安排試鏡、綵排和演出日。"},{"en":"Unrealistic project timelines can force people to work late.","zh":"不切實際的項目時間表可能迫使人們工作到很晚。"},{"en":"Reviewing project timelines helps prevent unnecessary after-hours messages.","zh":"檢視項目時間表有助避免不必要的下班後訊息。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"identify tasks","meaning":"找出任務","examples":[{"en":"Managers will identify tasks that can be postponed or simplified.","zh":"經理將找出可以延後或簡化的任務。"},{"en":"To identify tasks means to find and name specific pieces of work.","zh":"找出任務，意思是尋找並指出具體工作。"},{"en":"A teacher may identify tasks students must finish before a field trip.","zh":"老師可能找出學生在考察前必須完成的任務。"},{"en":"Managers identify tasks so they can decide what matters most.","zh":"經理找出任務，才能決定甚麼最重要。"},{"en":"Identifying tasks that can wait helps reduce late-night pressure.","zh":"找出可以等待的任務，有助減少深夜壓力。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"be postponed","meaning":"被延後","examples":[{"en":"Some tasks can be postponed.","zh":"有些任務可以被延後。"},{"en":"Be postponed means be delayed until a later time.","zh":"被延後，意思是被推遲到較後時間。"},{"en":"A school picnic may be postponed because of heavy rain.","zh":"學校野餐可能因大雨而被延後。"},{"en":"Tasks should be postponed when doing them immediately would create unnecessary stress.","zh":"當立即做任務會造成不必要壓力，它們就應被延後。"},{"en":"The company will identify work that can be postponed instead of done at night.","zh":"公司將找出可以被延後而不是晚上完成的工作。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"be reassigned","meaning":"被重新分配","examples":[{"en":"Some tasks can be reassigned.","zh":"有些任務可以被重新分配。"},{"en":"Be reassigned means be given to another person or team.","zh":"被重新分配，意思是被交給另一個人或團隊。"},{"en":"A teacher may reassign a task if one student is absent.","zh":"如果一名學生缺席，老師可能重新分配任務。"},{"en":"Tasks are reassigned when the original person has too much work.","zh":"當原本負責的人工作太多，任務就會被重新分配。"},{"en":"Reassigning tasks can prevent one employee from carrying unfair pressure.","zh":"重新分配任務可以防止一名員工承受不公平壓力。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"be simplified","meaning":"被簡化","examples":[{"en":"Some tasks can be simplified.","zh":"有些任務可以被簡化。"},{"en":"Be simplified means be made easier, clearer, or less complicated.","zh":"被簡化，意思是變得更容易、更清楚或較不複雜。"},{"en":"A teacher may simplify homework instructions for younger students.","zh":"老師可能為年幼學生簡化功課指示。"},{"en":"Tasks should be simplified if they take too much time for little value.","zh":"如果任務花太多時間但價值很少，就應被簡化。"},{"en":"Simplifying tasks can reduce the need for late-night messages.","zh":"簡化任務可以減少深夜訊息的需要。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"Human Resources","meaning":"人力資源部","examples":[{"en":"Human Resources will open a confidential channel.","zh":"人力資源部將開設保密渠道。"},{"en":"Human Resources is the department that deals with staff matters such as hiring, support, and workplace concerns.","zh":"人力資源部，是處理員工事務的部門，例如招聘、支援和職場憂慮。"},{"en":"Human Resources may help employees report unfair treatment.","zh":"人力資源部可能幫助員工匯報不公平待遇。"},{"en":"Staff contact Human Resources when they need confidential advice about work problems.","zh":"員工需要關於工作問題的保密建議時，會聯絡人力資源部。"},{"en":"In this policy, Human Resources will collect reports about repeated after-hours contact.","zh":"在這項政策中，人力資源部將收集關於多次下班後聯絡的匯報。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"confidential channel","meaning":"保密渠道","examples":[{"en":"Staff can use a confidential channel to report repeated contact.","zh":"員工可以使用保密渠道匯報多次聯絡。"},{"en":"A confidential channel is a private way to share sensitive information safely.","zh":"保密渠道，是安全分享敏感資訊的私人途徑。"},{"en":"A school may create a confidential channel for students to report bullying.","zh":"學校可能建立保密渠道，讓學生匯報欺凌。"},{"en":"Confidential channels help people speak honestly without fear of embarrassment.","zh":"保密渠道幫助人們誠實說話，而不用害怕尷尬。"},{"en":"The company’s confidential channel will help identify repeated after-hours contact.","zh":"公司的保密渠道將幫助找出多次下班後聯絡的情況。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"reporting repeated after-hours contact","meaning":"匯報多次下班後聯絡","examples":[{"en":"The channel is for reporting repeated after-hours contact.","zh":"這個渠道是用於匯報多次下班後聯絡。"},{"en":"Reporting repeated after-hours contact means telling the company that someone keeps contacting staff outside work time.","zh":"匯報多次下班後聯絡，意思是告訴公司有人持續在工作時間外聯絡員工。"},{"en":"A worker may report repeated after-hours contact if a manager messages every weekend.","zh":"如果經理每個週末都發訊息，員工可能匯報多次下班後聯絡。"},{"en":"Reporting patterns helps the company fix problems before they become normal.","zh":"匯報模式幫助公司在問題變成常態前修正它們。"},{"en":"The channel is not for punishing one mistake, but for reporting repeated behaviour.","zh":"這個渠道不是為了懲罰一次錯誤，而是用於匯報重複行為。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"meant to punish","meaning":"旨在懲罰","examples":[{"en":"The policy is not meant to punish honest mistakes.","zh":"這項政策並非旨在懲罰無心之失。"},{"en":"Meant to punish means designed or intended to blame or penalise someone.","zh":"旨在懲罰，意思是設計或意圖去責怪或處罰某人。"},{"en":"A classroom rule is not meant to punish students but to keep everyone safe.","zh":"班規不是旨在懲罰學生，而是保持所有人安全。"},{"en":"If a policy is meant to punish, people may become afraid to speak honestly.","zh":"如果政策旨在懲罰，人們可能害怕誠實說話。"},{"en":"This policy is meant to change habits, not punish one careless message.","zh":"這項政策旨在改變習慣，而不是懲罰一次粗心訊息。"}],"source":"2018 Q3.pdf","sourcePage":12},{"front":"honest mistakes","meaning":"無心之失","examples":[{"en":"The policy is not meant to punish honest mistakes.","zh":"這項政策並非旨在懲罰無心之失。"},{"en":"Honest mistakes are errors made without bad intention.","zh":"無心之失，是沒有惡意下犯的錯誤。"},{"en":"A student makes an honest mistake when they write the wrong date by accident.","zh":"學生不小心寫錯日期，就是無心之失。"},{"en":"Honest mistakes should be corrected, but they do not always deserve punishment.","zh":"無心之失應被糾正，但不一定應受懲罰。"},{"en":"The company wants to notice patterns, not punish honest mistakes.","zh":"公司希望察覺模式，而不是懲罰無心之失。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, it is a way to notice patterns.","zh":"而是，它是一種察覺模式的方法。"},{"en":"Rather introduces the real idea after rejecting another idea.","zh":"而是，用來在否定另一個想法後引出真正意思。"},{"en":"The rule is not to control students; rather, it is to keep them safe.","zh":"這條規則不是為了控制學生；而是為了保護他們安全。"},{"en":"Writers use rather to correct a possible misunderstanding.","zh":"作者使用「而是」來糾正可能的誤解。"},{"en":"The policy is not punishment; rather, it helps the company see repeated problems.","zh":"這項政策不是懲罰；而是幫助公司看見重複問題。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"notice patterns","meaning":"察覺模式","examples":[{"en":"The company wants to notice patterns before they become a culture.","zh":"公司希望在它們變成文化之前察覺模式。"},{"en":"To notice patterns means to see repeated behaviours or problems.","zh":"察覺模式，意思是看見重複出現的行為或問題。"},{"en":"A teacher may notice patterns when the same students are always tired on Mondays.","zh":"如果同一批學生每逢星期一都很累，老師可能察覺模式。"},{"en":"Noticing patterns helps leaders fix causes, not just single events.","zh":"察覺模式幫助領導者修正原因，而不只是處理單一事件。"},{"en":"The company wants to notice patterns of late contact early.","zh":"公司希望及早察覺深夜聯絡的模式。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"become a culture","meaning":"變成一種文化","examples":[{"en":"Repeated after-hours contact can become a culture.","zh":"多次下班後聯絡可以變成一種文化。"},{"en":"Become a culture means become a normal shared habit in a group or workplace.","zh":"變成一種文化，意思是在群體或工作場所中變成正常的共同習慣。"},{"en":"If students always arrive late and no one responds, lateness can become a culture.","zh":"如果學生總是遲到而沒有人處理，遲到可能變成一種文化。"},{"en":"Small behaviours become a culture when people repeat them and accept them.","zh":"當人們重複並接受小行為，它們就會變成一種文化。"},{"en":"The company wants to stop late-night messaging before it becomes a culture.","zh":"公司希望在深夜發訊變成文化前阻止它。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"make this policy work","meaning":"令這項政策奏效","examples":[{"en":"All staff are asked to help make this policy work.","zh":"所有員工都被要求協助令這項政策奏效。"},{"en":"To make this policy work means to help the rule succeed in real life.","zh":"令這項政策奏效，意思是幫助規則在現實中成功運作。"},{"en":"A school policy works only if teachers and students both follow it.","zh":"學校政策只有在老師和學生都遵守時才會奏效。"},{"en":"Staff can make this policy work by scheduling non-urgent messages.","zh":"員工可以透過預約發送非緊急訊息來令這項政策奏效。"},{"en":"The company needs everyone’s cooperation to make this policy work.","zh":"公司需要每個人合作，才能令這項政策奏效。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"scheduled sending","meaning":"預約發送","examples":[{"en":"Staff should use scheduled sending for non-urgent messages.","zh":"員工應為非緊急訊息使用預約發送。"},{"en":"Scheduled sending means setting a message to be sent later at a chosen time.","zh":"預約發送，意思是設定訊息在稍後選定時間發出。"},{"en":"A teacher may use scheduled sending to send homework reminders on Monday morning.","zh":"老師可能使用預約發送，在星期一早上發出功課提醒。"},{"en":"Scheduled sending lets people write messages now without disturbing others now.","zh":"預約發送讓人現在寫訊息，但不會現在打擾別人。"},{"en":"Staff can use scheduled sending to protect colleagues’ evenings.","zh":"員工可以使用預約發送來保護同事的晚上時間。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"think twice before","meaning":"三思而後","examples":[{"en":"Staff should think twice before marking a message urgent.","zh":"員工應三思而後將訊息標記為緊急。"},{"en":"To think twice before doing something means to consider carefully before acting.","zh":"三思而後做某事，意思是在行動前仔細考慮。"},{"en":"Students should think twice before posting angry comments online.","zh":"學生在網上發布憤怒留言前應三思而後行。"},{"en":"Thinking twice prevents people from treating ordinary problems as emergencies.","zh":"三思可以防止人們把普通問題當作緊急情況。"},{"en":"Staff should think twice before sending messages that may disturb rest.","zh":"員工在發送可能打擾休息的訊息前應三思。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"marking a message urgent","meaning":"將訊息標記為緊急","examples":[{"en":"Staff should think twice before marking a message urgent.","zh":"員工應在將訊息標記為緊急前三思。"},{"en":"Marking a message urgent means labelling it as needing immediate attention.","zh":"將訊息標記為緊急，意思是把它標示為需要立即關注。"},{"en":"A teacher may mark a safety notice urgent if students must act at once.","zh":"如果學生必須立刻行動，老師可能把安全通知標記為緊急。"},{"en":"Marking too many messages urgent makes the word lose meaning.","zh":"把太多訊息標記為緊急，會令這個詞失去意義。"},{"en":"Staff should mark a message urgent only when delay could cause serious harm.","zh":"員工只應在延誤可能造成嚴重傷害時，才將訊息標記為緊急。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"respect your colleagues’ silence","meaning":"尊重同事的安靜時間","examples":[{"en":"Staff should respect their colleagues’ silence after work.","zh":"員工應尊重同事下班後的安靜時間。"},{"en":"To respect your colleagues’ silence means to accept that coworkers may not reply outside work time.","zh":"尊重同事的安靜時間，意思是接受同事可能不在工作時間以外回覆。"},{"en":"A student respects a friend’s silence by not demanding instant replies at night.","zh":"學生晚上不要求朋友即時回覆，就是尊重朋友的安靜時間。"},{"en":"Respecting silence helps people rest without guilt.","zh":"尊重安靜時間幫助人們無愧疚地休息。"},{"en":"The policy asks staff to respect colleagues’ silence after work as a normal boundary.","zh":"這項政策要求員工把尊重同事下班後的安靜時間視為正常界線。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"after work","meaning":"下班後","examples":[{"en":"Colleagues’ silence after work should be respected.","zh":"同事下班後的安靜時間應受到尊重。"},{"en":"After work means after the working day has ended.","zh":"下班後，意思是工作日結束之後。"},{"en":"Many people cook, exercise, or see family after work.","zh":"很多人下班後煮飯、運動或見家人。"},{"en":"Messages after work can feel stressful when people expect rest.","zh":"當人們期待休息時，下班後的訊息可能令人有壓力。"},{"en":"The policy protects the quiet time employees need after work.","zh":"這項政策保護員工下班後需要的安靜時間。"}],"source":"2018 Q3.pdf","sourcePage":13},{"front":"should a true emergency arise","meaning":"如真正緊急情況發生","examples":[{"en":"Should a true emergency arise, call the department head first.","zh":"如真正緊急情況發生，請先致電部門主管。"},{"en":"Should a true emergency arise means if a real emergency happens.","zh":"如真正緊急情況發生，意思是如果真的出現緊急事件。"},{"en":"Should a fire alarm sound, students should leave the building calmly.","zh":"如火警鐘響起，學生應冷靜離開大樓。"},{"en":"This structure sounds formal and is often used in official instructions.","zh":"這個結構語氣正式，常用於官方指示。"},{"en":"The policy says that if a true emergency arises, staff should contact one responsible person first.","zh":"政策指出，如真正緊急情況發生，員工應先聯絡一名負責人。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"responsible department head","meaning":"相關部門主管","examples":[{"en":"Staff should call the responsible department head first.","zh":"員工應先致電相關部門主管。"},{"en":"The responsible department head is the manager in charge of the relevant team or issue.","zh":"相關部門主管，是負責有關團隊或問題的經理。"},{"en":"A school trip problem should be reported to the responsible teacher first.","zh":"學校旅行問題應先向相關老師匯報。"},{"en":"Calling the responsible department head prevents too many people from being disturbed.","zh":"致電相關部門主管可以避免太多人被打擾。"},{"en":"In an emergency, the responsible department head can decide who truly needs to respond.","zh":"在緊急情況中，相關部門主管可以決定誰真正需要回應。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"coordinate the response","meaning":"協調應對","examples":[{"en":"One person can coordinate the response.","zh":"一個人可以協調應對。"},{"en":"To coordinate the response means to organise how people react to a problem.","zh":"協調應對，意思是組織人們如何回應一個問題。"},{"en":"During a school emergency, one teacher may coordinate the response.","zh":"在學校緊急情況中，一名老師可能協調應對。"},{"en":"Coordinating the response prevents repeated calls and confused instructions.","zh":"協調應對可以防止重複電話和混亂指示。"},{"en":"The policy asks one person to coordinate the response instead of waking the whole team.","zh":"這項政策要求一個人協調應對，而不是叫醒整個團隊。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"instead of disturbing","meaning":"而不是打擾","examples":[{"en":"One person should coordinate the response instead of disturbing the whole team.","zh":"一個人應協調應對，而不是打擾整個團隊。"},{"en":"Instead of disturbing means choosing an alternative that avoids interrupting people unnecessarily.","zh":"而不是打擾，意思是選擇另一種方式，避免不必要地中斷別人。"},{"en":"A student can write down a question instead of disturbing the class.","zh":"學生可以寫下問題，而不是打擾全班。"},{"en":"In an emergency, one clear contact is better than disturbing everyone.","zh":"在緊急情況中，一個清晰聯絡人比打擾所有人更好。"},{"en":"The policy protects rest by coordinating action instead of disturbing an entire team.","zh":"這項政策透過協調行動而不是打擾整個團隊來保護休息。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"an entire team","meaning":"整個團隊","examples":[{"en":"A true emergency should not disturb an entire team unnecessarily.","zh":"真正緊急情況也不應不必要地打擾整個團隊。"},{"en":"An entire team means every member of the team.","zh":"整個團隊，意思是團隊中的每一位成員。"},{"en":"A teacher should not message an entire team if only one student needs the information.","zh":"如果只有一名學生需要資訊，老師不應通知整個團隊。"},{"en":"Disturbing an entire team at night creates wider stress than necessary.","zh":"晚上打擾整個團隊會造成比必要更大的壓力。"},{"en":"The policy says only the people needed should be contacted, not an entire team.","zh":"政策指出，只應聯絡需要的人，而不是整個團隊。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"come a long way","meaning":"取得長足進步","examples":[{"en":"Reboot Online has come a long way.","zh":"Reboot Online 已經取得長足進步。"},{"en":"To come a long way means to make great progress over time.","zh":"取得長足進步，意思是長時間內取得很大進展。"},{"en":"A student who once feared English but now writes confidently has come a long way.","zh":"一名曾害怕英文、現在能自信寫作的學生，已經取得長足進步。"},{"en":"Companies come a long way through effort, learning, and teamwork.","zh":"公司透過努力、學習和團隊合作取得長足進步。"},{"en":"Reboot Online has come a long way, but it still needs healthier work boundaries.","zh":"Reboot Online 已取得長足進步，但仍需要更健康的工作界線。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"professionalism and resilience","meaning":"專業精神和韌性","examples":[{"en":"The company has grown because of staff professionalism and resilience.","zh":"公司因員工的專業精神和韌性而成長。"},{"en":"Professionalism and resilience mean responsible work behaviour and the ability to recover from difficulty.","zh":"專業精神和韌性，意思是負責任的工作表現，以及從困難中恢復的能力。"},{"en":"A nurse shows professionalism and resilience during a busy hospital shift.","zh":"護士在繁忙醫院值班中展現專業精神和韌性。"},{"en":"Teams need professionalism and resilience when projects become difficult.","zh":"當項目變得困難，團隊需要專業精神和韌性。"},{"en":"The letter praises staff professionalism and resilience while also asking for healthier limits.","zh":"這封信讚揚員工的專業精神和韌性，同時要求更健康界線。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"the core of leadership","meaning":"領導的核心","examples":[{"en":"The core of leadership lies in creating the right conditions.","zh":"領導的核心在於創造合適條件。"},{"en":"The core of leadership means the most important part of being a leader.","zh":"領導的核心，意思是作為領導者最重要的部分。"},{"en":"The core of teaching is helping students understand, not just giving marks.","zh":"教學的核心是幫助學生理解，而不只是給分數。"},{"en":"The core of leadership is shown when leaders protect people’s ability to work well.","zh":"當領導者保護人們做好工作的能力時，就展現領導的核心。"},{"en":"In the letter, leadership is about creating conditions for sustainable work.","zh":"在這封信中，領導關乎創造可持續工作的條件。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"lies in","meaning":"在於","examples":[{"en":"The core of leadership lies in creating the right conditions.","zh":"領導的核心在於創造合適條件。"},{"en":"Lies in means is found in or depends mainly on something.","zh":"在於，意思是在某事之中，或主要取決於某事。"},{"en":"The value of teamwork lies in people trusting one another.","zh":"團隊合作的價值在於人們互相信任。"},{"en":"Success often lies in steady habits, not sudden effort.","zh":"成功常在於穩定習慣，而不是突然努力。"},{"en":"The letter says leadership lies in building conditions where good work can continue.","zh":"這封信指出，領導在於建立讓好工作能持續的條件。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"the right conditions","meaning":"合適條件","examples":[{"en":"Leaders should create the right conditions for good work.","zh":"領導者應為良好工作創造合適條件。"},{"en":"The right conditions are the situations, resources, and rules that allow something to succeed.","zh":"合適條件，是讓某事成功的情況、資源和規則。"},{"en":"Students need the right conditions, such as quiet space and enough sleep, to study well.","zh":"學生需要合適條件，例如安靜空間和足夠睡眠，才能好好學習。"},{"en":"Without the right conditions, even hardworking people may struggle.","zh":"沒有合適條件，即使努力的人也可能吃力。"},{"en":"The company wants to create the right conditions for focused and healthy work.","zh":"公司希望為專注和健康的工作創造合適條件。"}],"source":"2018 Q3.pdf","sourcePage":14},{"front":"continue doing good work","meaning":"繼續做好工作","examples":[{"en":"Good people need conditions in which they can continue doing good work.","zh":"好員工需要能讓他們繼續做好工作的條件。"},{"en":"Continue doing good work means keep producing valuable and responsible work over time.","zh":"繼續做好工作，意思是長時間保持有價值和負責任的工作。"},{"en":"Teachers need rest so they can continue doing good work for students.","zh":"老師需要休息，才能為學生繼續做好工作。"},{"en":"People cannot continue doing good work if they are always exhausted.","zh":"如果人們總是筋疲力盡，就不能繼續做好工作。"},{"en":"The policy supports staff so they can continue doing good work sustainably.","zh":"這項政策支援員工，讓他們能可持續地繼續做好工作。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"the time has come to","meaning":"是時候","examples":[{"en":"The time has come to draw a healthier line.","zh":"是時候劃下更健康的界線。"},{"en":"The time has come to do something means now is the right moment to act.","zh":"是時候做某事，意思是現在是採取行動的合適時刻。"},{"en":"The time has come to repair the playground before another accident happens.","zh":"是時候在另一宗意外發生前修理遊樂場。"},{"en":"Leaders use this phrase when delay is no longer acceptable.","zh":"當不能再延遲時，領導者會使用這個短語。"},{"en":"The letter says the time has come to set better boundaries between work and rest.","zh":"這封信指出，是時候在工作和休息之間設定更好界線。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"draw a healthier line","meaning":"劃下更健康的界線","examples":[{"en":"The company needs to draw a healthier line between work and availability.","zh":"公司需要在工作和待命之間劃下更健康的界線。"},{"en":"To draw a healthier line means to set a clearer and safer boundary.","zh":"劃下更健康的界線，意思是設定更清晰、更安全的界線。"},{"en":"A student may draw a healthier line by not studying after midnight every night.","zh":"學生不再每晚午夜後溫習，就是劃下更健康的界線。"},{"en":"Healthy lines protect people from pressure that slowly becomes normal.","zh":"健康界線保護人們免受慢慢變成正常的壓力。"},{"en":"The company draws a healthier line by saying staff need not be permanently available.","zh":"公司透過說明員工毋須永遠待命來劃下更健康的界線。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"working hard","meaning":"努力工作","examples":[{"en":"The policy draws a line between working hard and being permanently available.","zh":"這項政策在努力工作和永遠待命之間劃下界線。"},{"en":"Working hard means putting serious effort into tasks or responsibilities.","zh":"努力工作，意思是認真投入任務或責任。"},{"en":"A student can work hard during study time and still rest at night.","zh":"學生可以在學習時間努力，並仍然在晚上休息。"},{"en":"Working hard should not mean answering messages at every hour.","zh":"努力工作不應等於每個時段都要回覆訊息。"},{"en":"The policy respects working hard but rejects permanent availability.","zh":"這項政策尊重努力工作，但拒絕永遠待命。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"permanently available","meaning":"永遠待命","examples":[{"en":"Staff should not be permanently available.","zh":"員工不應永遠待命。"},{"en":"Permanently available means always ready to answer or work, at any time.","zh":"永遠待命，意思是任何時候都準備回覆或工作。"},{"en":"A teacher should not be permanently available to parents every night.","zh":"老師不應每晚都對家長永遠待命。"},{"en":"Being permanently available can damage health because people never truly switch off.","zh":"永遠待命會損害健康，因為人們永遠不能真正下班。"},{"en":"The new policy says good employees do not need to be permanently available.","zh":"新政策指出，好員工毋須永遠待命。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"review this arrangement","meaning":"檢討這項安排","examples":[{"en":"The Managing Director will review this arrangement after one month.","zh":"董事總經理將在一個月後檢討這項安排。"},{"en":"To review this arrangement means to examine how the new plan is working.","zh":"檢討這項安排，意思是檢查新計劃運作得如何。"},{"en":"A school may review a new lunch arrangement after two weeks.","zh":"學校可能在兩星期後檢討新的午餐安排。"},{"en":"Reviewing an arrangement helps leaders decide whether changes are needed.","zh":"檢討安排幫助領導者決定是否需要改變。"},{"en":"The company will review this arrangement to see if it protects staff time.","zh":"公司將檢討這項安排，以了解它是否保護員工時間。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"after one month","meaning":"一個月後","examples":[{"en":"The arrangement will be reviewed after one month.","zh":"這項安排將於一個月後檢討。"},{"en":"After one month means when one month has passed.","zh":"一個月後，意思是一個月過去之後。"},{"en":"A teacher may check students’ progress after one month of new lessons.","zh":"老師可能在新課程開始一個月後檢查學生進度。"},{"en":"Reviewing a policy after one month gives people time to test it.","zh":"一個月後檢討政策，可以給人們時間測試它。"},{"en":"The company will share findings after one month of using the policy.","zh":"公司將在使用政策一個月後分享結果。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"share the findings","meaning":"分享結果","examples":[{"en":"The Managing Director will share the findings with all staff.","zh":"董事總經理將與所有員工分享結果。"},{"en":"To share the findings means to tell people what has been learned after a review or study.","zh":"分享結果，意思是在檢討或研究後告訴人們所了解的內容。"},{"en":"A science group may share the findings of its experiment with the class.","zh":"科學小組可能向全班分享實驗結果。"},{"en":"Sharing findings builds trust because people can see what was discovered.","zh":"分享結果可以建立信任，因為人們能看見發現了甚麼。"},{"en":"The Managing Director will share the findings so staff know whether the policy worked.","zh":"董事總經理將分享結果，讓員工知道政策是否奏效。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"raising the issue honestly","meaning":"坦誠提出問題","examples":[{"en":"Staff are thanked for raising the issue honestly.","zh":"公司感謝員工坦誠提出問題。"},{"en":"Raising the issue honestly means bringing up a problem truthfully and directly.","zh":"坦誠提出問題，意思是真實而直接地提出一個問題。"},{"en":"A student raises an issue honestly when they explain that group work is unfair.","zh":"學生解釋小組工作不公平時，就是坦誠提出問題。"},{"en":"Honest issue-raising helps leaders see problems they may have missed.","zh":"坦誠提出問題幫助領導者看見他們可能忽略的問題。"},{"en":"The company thanks staff for speaking openly about after-hours pressure.","zh":"公司感謝員工坦誠說出下班後壓力。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"thank you in advance","meaning":"預先感謝","examples":[{"en":"Thank you in advance for helping us build a better workplace.","zh":"預先感謝你們幫助我們建立更好的工作場所。"},{"en":"Thank you in advance is a polite way to thank people before they do something.","zh":"預先感謝，是在人們做某事之前先禮貌地表示感謝。"},{"en":"A teacher may write “thank you in advance” before asking students to return forms.","zh":"老師可能在要求學生交回表格前寫「預先感謝」。"},{"en":"This phrase shows confidence that the reader will cooperate.","zh":"這個短語顯示作者相信讀者會合作。"},{"en":"The Managing Director uses it to politely ask staff to support the new policy.","zh":"董事總經理使用它，禮貌地請員工支持新政策。"}],"source":"2018 Q3.pdf","sourcePage":15},{"front":"respectful, focused and sustainable workplace","meaning":"互相尊重、專注而可持續的工作場所","examples":[{"en":"The company wants to build a respectful, focused and sustainable workplace.","zh":"公司希望建立一個互相尊重、專注而可持續的工作場所。"},{"en":"A respectful, focused and sustainable workplace values people, supports attention, and can remain healthy over time.","zh":"互相尊重、專注而可持續的工作場所，重視人、支持專注，並能長期保持健康。"},{"en":"A school becomes more respectful and focused when people listen and avoid unnecessary interruptions.","zh":"當人們聆聽並避免不必要干擾，學校會變得更互相尊重和專注。"},{"en":"A sustainable workplace does not depend on tired employees working every night.","zh":"可持續的工作場所不會依靠疲倦員工每晚工作。"},{"en":"The policy aims to make Reboot Online more respectful, focused, and sustainable.","zh":"這項政策旨在令 Reboot Online 更互相尊重、專注而可持續。"}],"source":"2018 Q3.pdf","sourcePage":16},{"front":"Yours sincerely","meaning":"謹啟；此致","examples":[{"en":"The letter ends with “Yours sincerely.”","zh":"這封信以「Yours sincerely」結束。"},{"en":"Yours sincerely is a formal closing used at the end of a letter.","zh":"「Yours sincerely」是正式書信結尾使用的用語。"},{"en":"A student may end a formal application letter with “Yours sincerely.”","zh":"學生可能用「Yours sincerely」結束正式申請信。"},{"en":"This closing shows respect and keeps the tone professional.","zh":"這個結尾顯示尊重，並保持專業語氣。"},{"en":"“Yours sincerely” fits this letter because it is formal and addressed to staff.","zh":"「Yours sincerely」適合這封信，因為它正式並寫給員工。"}],"source":"2018 Q3.pdf","sourcePage":16},{"front":"Managing Director","meaning":"董事總經理","examples":[{"en":"Chris Wong signs the letter as Managing Director.","zh":"Chris Wong 以董事總經理身份簽署這封信。"},{"en":"Managing Director is a senior company role with responsibility for leadership and major decisions.","zh":"董事總經理，是負責領導和重大決策的公司高層職位。"},{"en":"A Managing Director may sign a company notice to show it is official.","zh":"董事總經理可能簽署公司通知，以顯示它是正式的。"},{"en":"When the Managing Director signs a policy letter, staff know it has senior support.","zh":"當董事總經理簽署政策信，員工就知道它得到高層支持。"},{"en":"Chris Wong signs as Managing Director to show responsibility for the new arrangement.","zh":"Chris Wong 以董事總經理身份簽署，顯示他對新安排負責。"}],"source":"2018 Q3.pdf","sourcePage":16}],"dse/writing/part-b/2018/Q4":[{"front":"when a dream meets a door","meaning":"當夢想遇上阻礙","examples":[{"en":"The letter is about what to do when a dream meets a door.","zh":"這封信是關於當夢想遇上阻礙時應該怎樣做。"},{"en":"When a dream meets a door means a person’s hope faces an obstacle, refusal, or limit.","zh":"當夢想遇上阻礙，是指一個人的希望面對障礙、拒絕或限制。"},{"en":"A student’s dream meets a door when parents say no to an expensive course.","zh":"當父母拒絕一門昂貴課程時，學生的夢想可能遇上阻礙。"},{"en":"When a dream meets a door, the person needs patience, evidence, and a realistic plan.","zh":"當夢想遇上阻礙時，人需要耐性、證據和實際計劃。"},{"en":"This phrase suggests that a blocked dream is not necessarily a dead dream.","zh":"這個短語表示受阻的夢想不一定是已死的夢想。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"thank you for writing to","meaning":"感謝你寫信給……","examples":[{"en":"Thank you for writing to Teen.","zh":"感謝你寫信給 Teen。"},{"en":"Thank you for writing to is a polite way to show appreciation for someone’s letter or message.","zh":"感謝你寫信給……，是禮貌地感謝某人的來信或訊息。"},{"en":"An advice column may begin, “Thank you for writing to us about your problem.”","zh":"諮詢專欄可能以「感謝你寫信給我們分享你的問題」作開首。"},{"en":"This phrase helps the reader feel heard before advice is given.","zh":"這個短語在給予建議前，能令讀者感到被聆聽。"},{"en":"It is useful in formal replies, advice letters, and customer responses.","zh":"它適用於正式回覆、建議信和客戶回應。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"take a breath","meaning":"深呼吸；先冷靜下來","examples":[{"en":"First, take a breath.","zh":"首先，先深呼吸。"},{"en":"Take a breath means pause, calm down, and give yourself a moment before reacting.","zh":"深呼吸是指停一停、冷靜下來，給自己一點時間再反應。"},{"en":"A student should take a breath before answering an angry message from a friend.","zh":"學生在回覆朋友憤怒的訊息前，應先深呼吸。"},{"en":"Taking a breath can stop a difficult conversation from becoming a fight.","zh":"深呼吸可以防止困難對話變成爭吵。"},{"en":"This phrase is often used when someone feels shocked, hurt, or overwhelmed.","zh":"當某人感到震驚、受傷或不知所措時，這個短語常會使用。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"it must have felt as if","meaning":"一定感覺好像","examples":[{"en":"It must have felt as if your parents were shutting a door.","zh":"那一定感覺好像你的父母正在關上一扇門。"},{"en":"It must have felt as if is used to show understanding of how someone probably experienced a situation.","zh":"一定感覺好像……，是用來表示理解某人可能如何經歷某種情況。"},{"en":"When your teacher rejected your idea, it must have felt as if your effort did not matter.","zh":"當老師否定你的想法時，那一定感覺好像你的努力並不重要。"},{"en":"This phrase helps a writer sound sympathetic rather than cold.","zh":"這個短語幫助作者聽起來有同理心，而不是冷淡。"},{"en":"It does not state a fact; it gently imagines another person’s feeling.","zh":"它不是陳述事實，而是溫和地想像別人的感受。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"shut a door","meaning":"關上一扇門","examples":[{"en":"Your parents’ refusal may have felt like shutting a door.","zh":"你父母的拒絕可能感覺像關上一扇門。"},{"en":"To shut a door means to block an opportunity or make a dream seem impossible.","zh":"關上一扇門是指阻擋一個機會，或令夢想看似不可能。"},{"en":"A scholarship rejection may feel like shutting a door on a student’s study plan.","zh":"獎學金申請被拒，可能感覺像關上了學生升學計劃的一扇門。"},{"en":"Sometimes people shut a door because they are afraid, not because they want to hurt you.","zh":"有時人們關上一扇門，是因為害怕，而不是因為想傷害你。"},{"en":"A shut door can sometimes be opened again with time, trust, and evidence.","zh":"關上的門有時可以透過時間、信任和證據再次打開。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"walk towards something for years","meaning":"多年來一直朝着……走","examples":[{"en":"You had been walking towards this dream for years.","zh":"你多年來一直朝着這個夢想走。"},{"en":"To walk towards something for years means to work slowly and steadily toward a goal for a long time.","zh":"多年來一直朝着某事走，是指長時間慢慢而穩定地朝目標努力。"},{"en":"A dancer may walk towards a professional career for years through daily practice.","zh":"舞者可能透過每天練習，多年來一直朝着專業事業走。"},{"en":"When someone has walked towards a dream for years, rejection can feel deeply painful.","zh":"當某人多年來一直朝着夢想走時，被拒絕會感到很痛。"},{"en":"This phrase shows long commitment, not a sudden wish.","zh":"這個短語顯示長期投入，而不是一時願望。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"it is easy to see why","meaning":"不難理解為甚麼","examples":[{"en":"It is easy to see why you feel frustrated.","zh":"不難理解為甚麼你感到沮喪。"},{"en":"It is easy to see why means the reason for someone’s feeling or reaction is understandable.","zh":"不難理解為甚麼，是指某人的感受或反應有可以理解的原因。"},{"en":"It is easy to see why a student feels nervous before an important interview.","zh":"不難理解為甚麼學生在重要面試前會感到緊張。"},{"en":"This phrase helps the writer recognise another person’s emotion before giving advice.","zh":"這個短語幫助作者在給予建議前，先承認別人的情緒。"},{"en":"It is useful when the listener needs comfort and understanding.","zh":"當聽者需要安慰和理解時，這個短語很有用。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"feel frustrated","meaning":"感到沮喪","examples":[{"en":"It is easy to see why you feel frustrated.","zh":"不難理解為甚麼你感到沮喪。"},{"en":"To feel frustrated means to feel upset because something blocks what you want to do.","zh":"感到沮喪是指因某事阻礙你想做的事而感到難過。"},{"en":"A student may feel frustrated when hard work does not lead to the result they hoped for.","zh":"當努力沒有帶來期望中的結果時，學生可能感到沮喪。"},{"en":"People feel frustrated when they are not heard or when a plan is suddenly stopped.","zh":"當人們不被聆聽，或計劃突然被阻止時，會感到沮喪。"},{"en":"Frustration is natural, but it should be turned into a calmer next step.","zh":"沮喪是自然的，但應被轉化成更冷靜的下一步。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"a weekend outing","meaning":"週末外出活動","examples":[{"en":"You are not asking for a new phone or a weekend outing.","zh":"你不是在要求一部新電話或一次週末外出活動。"},{"en":"A weekend outing is a short trip or activity people do during the weekend.","zh":"週末外出活動是人們在週末進行的短途活動或旅行。"},{"en":"A family may plan a weekend outing to a beach, museum, or country park.","zh":"家庭可能計劃到海灘、博物館或郊野公園作週末外出活動。"},{"en":"Comparing a career dream with a weekend outing shows that the dream is more serious.","zh":"把職業夢想與週末外出活動比較，能顯示這個夢想更嚴肅。"},{"en":"This phrase helps show the difference between a small request and a life plan.","zh":"這個短語幫助顯示小請求與人生計劃之間的差別。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"a future that matters to you","meaning":"對你重要的未來","examples":[{"en":"You are talking about a future that matters to you.","zh":"你正在談論一個對你重要的未來。"},{"en":"A future that matters to you means a life direction you deeply care about.","zh":"對你重要的未來，是指你深深在意的人生方向。"},{"en":"Choosing subjects can feel serious when they connect to a future that matters to you.","zh":"當選科與對你重要的未來有關時，它會感覺很嚴肅。"},{"en":"Parents should listen carefully when a child speaks about a future that matters to them.","zh":"當孩子談論對自己重要的未來時，父母應仔細聆聽。"},{"en":"This phrase shows that the issue is emotional, personal, and important.","zh":"這個短語顯示問題是有情感、個人化和重要的。"}],"source":"2018 Q4.pdf","sourcePage":1},{"front":"their first reaction","meaning":"他們的第一反應","examples":[{"en":"Their first reaction does not have to be the final answer.","zh":"他們的第一反應不必是最終答案。"},{"en":"Their first reaction means what they think, say, or feel immediately at the beginning.","zh":"他們的第一反應，是指他們一開始立即想到、說出或感受到的事情。"},{"en":"A parent’s first reaction to a risky plan may be fear, not careful judgement.","zh":"父母面對有風險的計劃時，第一反應可能是害怕，而不是仔細判斷。"},{"en":"First reactions can change after people receive more information.","zh":"當人們得到更多資訊後，第一反應可以改變。"},{"en":"This phrase gives hope because an early “no” may not be permanent.","zh":"這個短語帶來希望，因為最初的「不」未必是永久的。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"the final answer","meaning":"最終答案","examples":[{"en":"Their first reaction does not have to be the final answer.","zh":"他們的第一反應不必是最終答案。"},{"en":"The final answer means the decision that is settled after discussion, thought, or evidence.","zh":"最終答案是指經過討論、思考或證據後確定的決定。"},{"en":"A teacher’s first comment on a proposal may not be the final answer after revision.","zh":"老師對建議書的第一個評論，在修改後未必是最終答案。"},{"en":"A final answer should come after people understand the facts and risks.","zh":"最終答案應在人們理解事實和風險後才出現。"},{"en":"This phrase shows that a conversation may still continue.","zh":"這個短語顯示對話仍可能繼續。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"the way I see it","meaning":"在我看來","examples":[{"en":"The way I see it, your aim now is to create a realistic plan.","zh":"在我看來，你現在的目標是制定一個實際的計劃。"},{"en":"The way I see it means from my point of view or in my opinion.","zh":"在我看來，是指從我的角度或以我的意見來說。"},{"en":"The way I see it, the problem is not your dream but how to present it clearly.","zh":"在我看來，問題不是你的夢想，而是如何清楚呈現它。"},{"en":"This phrase allows the writer to give advice without sounding too forceful.","zh":"這個短語讓作者給予建議時不會聽起來太強硬。"},{"en":"It is useful when explaining a personal judgement gently.","zh":"溫和地解釋個人判斷時，這個短語很有用。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"win an argument overnight","meaning":"一夜之間贏得爭論","examples":[{"en":"Your aim is not to win an argument overnight.","zh":"你的目標不是一夜之間贏得爭論。"},{"en":"To win an argument overnight means to make others agree with you very quickly after one disagreement.","zh":"一夜之間贏得爭論，是指在一次分歧後很快令別人同意你。"},{"en":"A teenager may want to win an argument overnight, but parents often need time to think.","zh":"青少年可能想一夜之間贏得爭論，但父母通常需要時間思考。"},{"en":"Trying to win an argument overnight can make both sides more defensive.","zh":"試圖一夜之間贏得爭論，可能令雙方更防衛。"},{"en":"A careful plan usually works better than one emotional victory.","zh":"細心計劃通常比一次情緒化勝利更有效。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"turn your love for animals into","meaning":"把你對動物的熱愛轉化為……","examples":[{"en":"Your aim is to turn your love for animals into a calm, realistic plan.","zh":"你的目標是把你對動物的熱愛轉化為冷靜而實際的計劃。"},{"en":"To turn your love for animals into something means to change a feeling into action, study, or planning.","zh":"把你對動物的熱愛轉化為某事，是指把感受變成行動、學習或計劃。"},{"en":"A student can turn love for animals into volunteer work at a shelter.","zh":"學生可以把對動物的熱愛轉化為在收容所做義工。"},{"en":"Turning love into a plan shows parents that the dream is serious.","zh":"把熱愛轉化為計劃，能向父母顯示夢想是認真的。"},{"en":"This phrase connects emotion with practical steps.","zh":"這個短語把情感與實際步驟連接起來。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"a calm, realistic plan","meaning":"冷靜而實際的計劃","examples":[{"en":"You need a calm, realistic plan your parents can respect.","zh":"你需要一個父母可以尊重的冷靜而實際的計劃。"},{"en":"A calm, realistic plan is a sensible plan based on facts, not only emotion.","zh":"冷靜而實際的計劃，是指基於事實而不只是情緒的合理計劃。"},{"en":"A student creates a calm, realistic plan by listing courses, costs, grades, and work experience.","zh":"學生透過列出課程、費用、成績和工作經驗，制定冷靜而實際的計劃。"},{"en":"Such a plan can reduce parents’ fear because it shows preparation.","zh":"這樣的計劃可以減少父母的恐懼，因為它顯示準備。"},{"en":"A dream becomes easier to discuss when it is presented as a calm, realistic plan.","zh":"當夢想被呈現為冷靜而實際的計劃時，就更容易討論。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"respect a plan","meaning":"尊重一個計劃","examples":[{"en":"Your parents may respect a careful plan.","zh":"你的父母可能會尊重一個細心的計劃。"},{"en":"To respect a plan means to take it seriously because it is thoughtful and well prepared.","zh":"尊重一個計劃，是指因它有思考和準備而認真看待它。"},{"en":"Teachers respect a plan more when students include deadlines and responsibilities.","zh":"當學生包括截止日期和責任時，老師會更尊重一個計劃。"},{"en":"Parents may respect a career plan if it includes risks as well as hopes.","zh":"如果職業計劃包含風險和希望，父母可能會尊重它。"},{"en":"A respected plan is usually clearer than a simple emotional request.","zh":"受尊重的計劃通常比單純情緒化請求更清晰。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"the first thing to do","meaning":"第一件要做的事","examples":[{"en":"The first thing to do is to understand their real concern.","zh":"第一件要做的事是了解他們真正的憂慮。"},{"en":"The first thing to do means the first practical step someone should take.","zh":"第一件要做的事，是指某人應採取的第一個實際步驟。"},{"en":"When a plan is rejected, the first thing to do is listen before arguing.","zh":"當計劃被拒絕時，第一件要做的事是先聆聽，而不是爭辯。"},{"en":"Naming the first thing to do helps a person feel less lost.","zh":"指出第一件要做的事，能幫助人少一點迷惘。"},{"en":"This phrase is useful in advice because it gives a clear starting point.","zh":"這個短語在建議中很有用，因為它給出清楚起點。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"what their “no” actually means","meaning":"他們說「不」真正代表甚麼","examples":[{"en":"You need to understand what their “no” actually means.","zh":"你需要明白他們說「不」真正代表甚麼。"},{"en":"What their “no” actually means refers to the real fear or reason behind a refusal.","zh":"他們說「不」真正代表甚麼，是指拒絕背後真正的恐懼或原因。"},{"en":"A parent’s “no” may actually mean “I am worried about money,” not “I do not believe in you.”","zh":"父母的「不」可能真正代表「我擔心金錢」，而不是「我不相信你」。"},{"en":"Understanding the real meaning of “no” helps you answer the right concern.","zh":"理解「不」的真正意思，能幫助你回應正確的憂慮。"},{"en":"This phrase teaches people to listen beneath the surface.","zh":"這個短語教人聆聽表面以下的意思。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"becoming a vet","meaning":"成為獸醫","examples":[{"en":"Your parents may worry that becoming a vet is too difficult.","zh":"你的父母可能擔心成為獸醫太困難。"},{"en":"Becoming a vet means studying and training to become an animal doctor.","zh":"成為獸醫是指學習和受訓成為動物醫生。"},{"en":"A student interested in becoming a vet needs strong science skills and real experience with animals.","zh":"有興趣成為獸醫的學生需要強的科學能力和真實動物經驗。"},{"en":"Becoming a vet can be demanding because it involves sick animals and worried owners.","zh":"成為獸醫可能很艱難，因為它涉及生病動物和焦急的主人。"},{"en":"This phrase describes a serious career path, not just liking pets.","zh":"這個短語描述嚴肅的職業道路，而不只是喜歡寵物。"}],"source":"2018 Q4.pdf","sourcePage":2},{"front":"too emotionally demanding","meaning":"情感負擔太重","examples":[{"en":"Veterinary work may be too emotionally demanding.","zh":"獸醫工作可能情感負擔太重。"},{"en":"Too emotionally demanding means requiring more emotional strength than someone may be ready for.","zh":"情感負擔太重，是指需要的情緒承受力超過某人可能準備好的程度。"},{"en":"Caring for very sick animals can be emotionally demanding because not every case ends happily.","zh":"照顧病重動物可能情感負擔很重，因為不是每個個案都有快樂結局。"},{"en":"A job becomes too emotionally demanding when sadness, pressure, and responsibility feel overwhelming.","zh":"當悲傷、壓力和責任令人無法承受時，一份工作就變得情感負擔太重。"},{"en":"This phrase helps explain why a caring career can still be difficult.","zh":"這個短語幫助解釋為何關懷性的職業仍然可以很困難。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"playing with pets","meaning":"和寵物玩耍","examples":[{"en":"Veterinary work is not just playing with pets.","zh":"獸醫工作不只是和寵物玩耍。"},{"en":"Playing with pets means enjoying friendly time with animals, such as stroking, feeding, or playing games with them.","zh":"和寵物玩耍是指與動物愉快相處，例如撫摸、餵食或和牠們玩遊戲。"},{"en":"Many children enjoy playing with pets, but veterinary work also includes science and medical decisions.","zh":"許多孩子喜歡和寵物玩耍，但獸醫工作也包括科學和醫療決定。"},{"en":"Confusing vet work with playing with pets may lead to unrealistic expectations.","zh":"把獸醫工作誤以為只是和寵物玩耍，可能帶來不切實際的期望。"},{"en":"This phrase shows the difference between love for animals and professional responsibility.","zh":"這個短語顯示愛動物與專業責任之間的差別。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"whereas","meaning":"然而；但是","examples":[{"en":"You may like animals, whereas veterinary work also involves painful decisions.","zh":"你可能喜歡動物，然而獸醫工作也涉及痛苦的決定。"},{"en":"Whereas is used to show a contrast between two facts or ideas.","zh":"Whereas 用來顯示兩個事實或想法之間的對比。"},{"en":"A student may enjoy drawing, whereas art school also requires deadlines and criticism.","zh":"學生可能喜歡繪畫，然而藝術學院也需要面對截止日期和批評。"},{"en":"Whereas helps writers show that one side of a situation is not the whole story.","zh":"Whereas 幫助作者顯示情況的一面並不是全部。"},{"en":"This word is useful when comparing a dream with its harder realities.","zh":"比較夢想與其較艱難現實時，這個詞很有用。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"veterinary work","meaning":"獸醫工作","examples":[{"en":"Veterinary work involves biology, sick animals, and anxious owners.","zh":"獸醫工作涉及生物、生病動物和焦急的主人。"},{"en":"Veterinary work is the professional work of caring for animal health and treating animal illness.","zh":"獸醫工作是照顧動物健康和治療動物疾病的專業工作。"},{"en":"Veterinary work may include check-ups, surgery, medicine, records, and conversations with owners.","zh":"獸醫工作可能包括檢查、手術、藥物、記錄和與主人溝通。"},{"en":"Veterinary work can be rewarding, but it also brings stress and responsibility.","zh":"獸醫工作可以很有意義，但也帶來壓力和責任。"},{"en":"Understanding veterinary work clearly helps students decide whether the career truly suits them.","zh":"清楚理解獸醫工作，能幫助學生決定這個職業是否真正適合自己。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"involve studying biology","meaning":"涉及學習生物","examples":[{"en":"Veterinary work involves studying biology.","zh":"獸醫工作涉及學習生物。"},{"en":"To involve studying biology means to require learning about living things, bodies, cells, and health.","zh":"涉及學習生物，是指需要學習關於生物、身體、細胞和健康的知識。"},{"en":"Becoming a vet involves studying biology because animals’ organs and diseases must be understood.","zh":"成為獸醫涉及學習生物，因為必須理解動物器官和疾病。"},{"en":"Students who dislike science may struggle if a career involves studying biology every day.","zh":"如果一份職業每天都涉及學習生物，不喜歡科學的學生可能會吃力。"},{"en":"This phrase shows that animal care is also scientific study.","zh":"這個短語顯示動物照顧也屬於科學學習。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"treating sick animals","meaning":"治療生病動物","examples":[{"en":"Veterinary work involves treating sick animals.","zh":"獸醫工作涉及治療生病動物。"},{"en":"Treating sick animals means helping animals recover from illness, injury, or pain.","zh":"治療生病動物是指幫助動物從疾病、受傷或痛楚中康復。"},{"en":"A vet treats sick animals by examining symptoms and choosing suitable medicine or care.","zh":"獸醫透過檢查症狀並選擇合適藥物或護理來治療生病動物。"},{"en":"Treating sick animals can be stressful because some animals cannot explain what hurts.","zh":"治療生病動物可能有壓力，因為有些動物不能說出哪裡痛。"},{"en":"This phrase shows the medical side of loving animals.","zh":"這個短語顯示愛動物背後的醫療一面。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"anxious owners","meaning":"焦急的主人","examples":[{"en":"Vets often speak to anxious owners.","zh":"獸醫經常與焦急的主人說話。"},{"en":"Anxious owners are pet owners who feel worried or afraid about their animals’ health.","zh":"焦急的主人是指為動物健康感到擔心或害怕的寵物主人。"},{"en":"A vet may calm anxious owners by explaining test results in simple language.","zh":"獸醫可以透過用簡單語言解釋檢查結果，安撫焦急的主人。"},{"en":"Anxious owners need patience because fear can make them ask many questions.","zh":"焦急的主人需要耐性對待，因為恐懼可能令他們問很多問題。"},{"en":"Veterinary work includes caring for people’s emotions as well as animals’ bodies.","zh":"獸醫工作既包括照顧動物身體，也包括照顧人的情緒。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"make painful decisions","meaning":"作出痛苦的決定","examples":[{"en":"Vets sometimes have to make painful decisions.","zh":"獸醫有時必須作出痛苦的決定。"},{"en":"To make painful decisions means to choose something necessary but emotionally difficult.","zh":"作出痛苦的決定，是指選擇必要但情感上很困難的事情。"},{"en":"A family may have to make a painful decision when an old pet is suffering badly.","zh":"當年老寵物非常痛苦時，家庭可能需要作出痛苦的決定。"},{"en":"Vets face painful decisions when treatment may not save an animal or may cause more suffering.","zh":"當治療可能救不了動物，或可能造成更多痛苦時，獸醫要面對痛苦的決定。"},{"en":"This phrase shows why the job requires emotional strength.","zh":"這個短語顯示為何這份工作需要情緒承受力。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"the real reason","meaning":"真正原因","examples":[{"en":"You should know the real reason before you argue.","zh":"在爭辯前，你應該知道真正原因。"},{"en":"The real reason is the true cause behind someone’s words, action, or decision.","zh":"真正原因是某人說話、行動或決定背後的真實原因。"},{"en":"A parent may say no because of money, but the real reason may be fear for the child’s future.","zh":"父母可能因金錢而說不，但真正原因可能是擔心孩子的未來。"},{"en":"Knowing the real reason helps people solve the actual problem.","zh":"知道真正原因能幫助人們解決真正問題。"},{"en":"Arguments become fairer when both sides understand the real reason.","zh":"當雙方都明白真正原因時，爭論會更公平。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"end up fighting the wrong battle","meaning":"最終打錯仗；爭錯焦點","examples":[{"en":"If you argue too soon, you may end up fighting the wrong battle.","zh":"如果你太快爭辯，可能最終爭錯焦點。"},{"en":"To end up fighting the wrong battle means to spend energy arguing about the wrong issue.","zh":"最終打錯仗，是指花力氣爭論錯誤的問題。"},{"en":"A student may fight the wrong battle if they argue about freedom when their parents are really worried about safety.","zh":"如果父母真正擔心的是安全，而學生卻只爭論自由，他可能就是爭錯焦點。"},{"en":"Fighting the wrong battle wastes time because the real concern remains unanswered.","zh":"爭錯焦點會浪費時間，因為真正憂慮仍未被回應。"},{"en":"This phrase warns people to understand the problem before reacting.","zh":"這個短語提醒人們在反應前先理解問題。"}],"source":"2018 Q4.pdf","sourcePage":3},{"front":"choose a quiet time","meaning":"選一個安靜的時間","examples":[{"en":"Choose a quiet time to speak to your parents.","zh":"選一個安靜的時間和父母說話。"},{"en":"To choose a quiet time means to pick a calm moment when people can listen properly.","zh":"選一個安靜的時間，是指選擇人們能好好聆聽的冷靜時刻。"},{"en":"A teenager should choose a quiet time instead of starting a serious talk during an argument.","zh":"青少年應選一個安靜的時間，而不是在爭吵中開始嚴肅對話。"},{"en":"Choosing a quiet time makes it easier for parents to think and respond calmly.","zh":"選一個安靜的時間，能令父母更容易冷靜思考和回應。"},{"en":"Difficult conversations need the right moment as well as the right words.","zh":"困難對話既需要合適說話，也需要合適時機。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"I hear you","meaning":"我明白你的意思","examples":[{"en":"You can say, “I hear you.”","zh":"你可以說：「我明白你的意思。」"},{"en":"I hear you means I understand that you have a concern or point.","zh":"我明白你的意思，是指我理解你有一個憂慮或觀點。"},{"en":"A teenager may say “I hear you” before asking parents to explain their worries.","zh":"青少年可能在請父母解釋憂慮前說：「我明白你的意思。」"},{"en":"This phrase helps reduce tension because it shows listening.","zh":"這個短語顯示聆聽，因此有助減少緊張。"},{"en":"It does not mean giving up; it means taking the other person seriously.","zh":"它不代表放棄，而是代表認真看待對方。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"help me understand","meaning":"幫我明白","examples":[{"en":"Could you help me understand what worries you most?","zh":"你可以幫我明白你最擔心的是甚麼嗎？"},{"en":"Help me understand is a polite request for someone to explain their thoughts or feelings.","zh":"幫我明白，是禮貌地請別人解釋其想法或感受。"},{"en":"A student may say, “Help me understand why this course worries you.”","zh":"學生可能會說：「請幫我明白為何這門課令你擔心。」"},{"en":"This phrase invites conversation instead of creating a fight.","zh":"這個短語邀請對話，而不是製造爭吵。"},{"en":"It shows respect because the speaker is asking before arguing.","zh":"它表達尊重，因為講者先詢問再爭辯。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"what worries you most","meaning":"你最擔心的是甚麼","examples":[{"en":"Ask your parents what worries them most.","zh":"問問你的父母他們最擔心的是甚麼。"},{"en":"What worries you most asks someone to name their biggest fear or concern.","zh":"你最擔心的是甚麼，是請某人說出最大的恐懼或憂慮。"},{"en":"A parent may say money, safety, grades, or job prospects worry them most.","zh":"父母可能會說金錢、安全、成績或就業前景是他們最擔心的。"},{"en":"Asking what worries someone most helps focus the conversation on the real issue.","zh":"詢問某人最擔心甚麼，能幫助對話集中於真正問題。"},{"en":"This question can turn a general refusal into a specific discussion.","zh":"這個問題可以把籠統拒絕變成具體討論。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"show respect","meaning":"表示尊重","examples":[{"en":"This sentence shows respect without surrendering your dream.","zh":"這句話表示尊重，同時不放棄你的夢想。"},{"en":"To show respect means to speak or act in a way that recognises another person’s feelings or position.","zh":"表示尊重，是指以承認他人感受或立場的方式說話或行動。"},{"en":"A teenager shows respect by listening to parents before explaining a different view.","zh":"青少年先聆聽父母，再解釋不同看法，就是表示尊重。"},{"en":"Showing respect can make others more willing to listen.","zh":"表示尊重可以令別人更願意聆聽。"},{"en":"Respect does not mean silence; it means disagreement with care.","zh":"尊重不代表沉默，而是帶着關懷地不同意。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"without surrendering your dream","meaning":"不放棄夢想","examples":[{"en":"You can show respect without surrendering your dream.","zh":"你可以表示尊重，同時不放棄夢想。"},{"en":"Without surrendering your dream means not giving up your hope while still acting respectfully.","zh":"不放棄夢想，是指仍抱住希望，同時保持尊重。"},{"en":"A student can listen to parents’ concerns without surrendering a dream of studying art.","zh":"學生可以聆聽父母的憂慮，而不放棄讀藝術的夢想。"},{"en":"This phrase shows that respect and determination can exist together.","zh":"這個短語顯示尊重與決心可以並存。"},{"en":"It helps young people stay calm without abandoning what matters to them.","zh":"它幫助年輕人保持冷靜，同時不拋棄對自己重要的事。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"more often than not","meaning":"往往；通常","examples":[{"en":"Parents, more often than not, say “no” quickly when they are afraid.","zh":"父母在害怕時，往往會很快說「不」。"},{"en":"More often than not means usually or in most cases.","zh":"往往是指通常或在大多數情況下。"},{"en":"More often than not, students feel calmer after they understand the reason for criticism.","zh":"通常，學生理解批評原因後會感到較冷靜。"},{"en":"Parents more often than not want safety before they want control.","zh":"父母往往想要的是安全，而不是控制。"},{"en":"This phrase shows a common pattern without saying it happens every time.","zh":"這個短語顯示常見模式，但不是說每次都如此。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"beneath the refusal","meaning":"拒絕背後","examples":[{"en":"You need to hear the fear beneath the refusal.","zh":"你需要聽出拒絕背後的恐懼。"},{"en":"Beneath the refusal means hidden under the “no” or behind the rejection.","zh":"拒絕背後，是指隱藏在「不」之下或拒絕後面的東西。"},{"en":"Beneath a parent’s refusal may be fear about money, failure, or emotional pain.","zh":"父母拒絕背後可能是對金錢、失敗或情感痛苦的恐懼。"},{"en":"Listening beneath the refusal helps you answer the real worry.","zh":"聆聽拒絕背後的意思，能幫助你回應真正憂慮。"},{"en":"This phrase suggests that a refusal may have a deeper reason.","zh":"這個短語表示拒絕可能有更深層原因。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"answer it more intelligently","meaning":"更明智地回應","examples":[{"en":"If you understand the fear, you can answer it more intelligently.","zh":"如果你理解那份恐懼，就可以更明智地回應它。"},{"en":"To answer it more intelligently means to respond with clearer thought, evidence, and understanding.","zh":"更明智地回應，是指以更清晰的思考、證據和理解作回應。"},{"en":"A student answers parents more intelligently by addressing their concern about cost with scholarship information.","zh":"學生用獎學金資料回應父母對費用的憂慮，就是更明智地回應。"},{"en":"Understanding the real fear helps you avoid emotional arguing.","zh":"理解真正恐懼能幫助你避免情緒化爭辯。"},{"en":"This phrase shows that good responses begin with good listening.","zh":"這個短語顯示好的回應始於好的聆聽。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"show evidence","meaning":"展示證據","examples":[{"en":"After that, show them evidence, not emotion alone.","zh":"之後，向他們展示證據，而不只是情緒。"},{"en":"To show evidence means to present facts, examples, records, or information that support your point.","zh":"展示證據是指提出支持你觀點的事實、例子、記錄或資料。"},{"en":"A student can show evidence by bringing course requirements and volunteer records.","zh":"學生可以透過帶來課程要求和義工記錄來展示證據。"},{"en":"Evidence helps parents see preparation instead of only passion.","zh":"證據幫助父母看見準備，而不只是熱情。"},{"en":"Showing evidence makes a dream sound more serious and realistic.","zh":"展示證據令夢想聽起來更認真和實際。"}],"source":"2018 Q4.pdf","sourcePage":4},{"front":"not emotion alone","meaning":"不只是情緒","examples":[{"en":"You need evidence, not emotion alone.","zh":"你需要證據，而不只是情緒。"},{"en":"Not emotion alone means feelings are important but not enough by themselves.","zh":"不只是情緒，是指感受很重要，但單靠感受並不足夠。"},{"en":"Saying “I love animals” is not emotion alone if you also show experience and research.","zh":"如果你同時展示經驗和資料，說「我愛動物」就不只是情緒。"},{"en":"Parents may listen better when a dream is supported by facts, not emotion alone.","zh":"當夢想由事實支持，而不只是情緒時，父母可能更願意聆聽。"},{"en":"This phrase reminds people to balance passion with preparation.","zh":"這個短語提醒人們要平衡熱情與準備。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"a beautiful beginning","meaning":"美好的開始","examples":[{"en":"Loving animals is a beautiful beginning.","zh":"愛動物是一個美好的開始。"},{"en":"A beautiful beginning is a good and meaningful starting point, but not the whole journey.","zh":"美好的開始是好而有意義的起點，但不是整個旅程。"},{"en":"Caring about the environment is a beautiful beginning for someone who wants to study science.","zh":"對想讀科學的人來說，關心環境是一個美好的開始。"},{"en":"A beautiful beginning must be followed by effort, knowledge, and discipline.","zh":"美好的開始之後，還必須有努力、知識和紀律。"},{"en":"This phrase praises the feeling while gently saying more is needed.","zh":"這個短語讚賞感受，同時溫和地指出還需要更多。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"not enough by itself","meaning":"本身並不足夠","examples":[{"en":"Loving animals is not enough by itself.","zh":"愛動物本身並不足夠。"},{"en":"Not enough by itself means something is helpful but cannot succeed alone.","zh":"本身並不足夠，是指某事有幫助，但單靠它不能成功。"},{"en":"Talent is not enough by itself if a musician never practises.","zh":"如果音樂人從不練習，天分本身並不足夠。"},{"en":"Love for animals is not enough by itself because veterinary work also needs science and resilience.","zh":"愛動物本身並不足夠，因為獸醫工作也需要科學和承受力。"},{"en":"This phrase shows that a good start still needs support.","zh":"這個短語顯示好的起點仍需要支撐。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"demonstrate that","meaning":"證明","examples":[{"en":"You need to demonstrate that you understand the profession.","zh":"你需要證明你了解這個職業。"},{"en":"To demonstrate that means to show clearly through evidence, action, or explanation.","zh":"證明是指透過證據、行動或解釋清楚顯示某事。"},{"en":"A student can demonstrate that she is serious by keeping a record of volunteer hours.","zh":"學生可以透過保存義工時數記錄，證明自己是認真的。"},{"en":"Demonstrating understanding is stronger than simply insisting on a dream.","zh":"證明理解比單純堅持夢想更有力。"},{"en":"This phrase is useful when proof is needed.","zh":"當需要證據時，這個短語很有用。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"both the charm and the burden","meaning":"魅力與負擔兩者","examples":[{"en":"You should understand both the charm and the burden of the profession.","zh":"你應該了解這個職業的魅力與負擔兩者。"},{"en":"Both the charm and the burden means the attractive parts and the difficult responsibilities together.","zh":"魅力與負擔兩者，是指吸引人的部分和困難責任同時存在。"},{"en":"Teaching has both the charm of helping children and the burden of heavy preparation.","zh":"教書既有幫助孩子的魅力，也有大量備課的負擔。"},{"en":"Understanding both charm and burden helps people choose a career realistically.","zh":"理解魅力與負擔兩者，能幫助人實際地選擇職業。"},{"en":"This phrase prevents a dream from becoming too romantic or one-sided.","zh":"這個短語防止夢想變得太浪漫或片面。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"the burden of the profession","meaning":"這個職業的負擔","examples":[{"en":"Veterinary work has both charm and burden.","zh":"獸醫工作既有魅力，也有負擔。"},{"en":"The burden of the profession means the difficult duties, pressure, or emotional cost of a job.","zh":"這個職業的負擔，是指一份工作的困難職責、壓力或情感代價。"},{"en":"The burden of the profession for nurses may include long shifts and painful situations.","zh":"對護士來說，這個職業的負擔可能包括長時間輪班和痛苦情況。"},{"en":"A student should understand the burden of the profession before choosing it.","zh":"學生在選擇一份職業前，應了解這個職業的負擔。"},{"en":"Knowing the burden does not destroy a dream; it makes the dream more realistic.","zh":"知道負擔不會摧毀夢想，而會令夢想更實際。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"career folder","meaning":"職業資料夾","examples":[{"en":"Make a simple career folder.","zh":"製作一個簡單的職業資料夾。"},{"en":"A career folder is a collection of information about a possible job or future path.","zh":"職業資料夾是關於可能工作或未來道路的資料集合。"},{"en":"A student’s career folder may include courses, grades, costs, interviews, and volunteer records.","zh":"學生的職業資料夾可能包括課程、成績、費用、訪問和義工記錄。"},{"en":"Making a career folder shows parents that the student has researched seriously.","zh":"製作職業資料夾能向父母顯示學生已認真搜集資料。"},{"en":"This tool turns a dream into something organised and discussable.","zh":"這個工具把夢想變成有組織、可討論的東西。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"possible university courses","meaning":"可能的大學課程","examples":[{"en":"Your folder should include possible university courses.","zh":"你的資料夾應包括可能的大學課程。"},{"en":"Possible university courses are degree programmes a student may apply for in the future.","zh":"可能的大學課程，是指學生將來可能申請的學位課程。"},{"en":"A student interested in animals may list veterinary medicine, animal science, and biology as possible university courses.","zh":"對動物有興趣的學生可能把獸醫學、動物科學和生物列為可能的大學課程。"},{"en":"Comparing possible university courses helps students understand choices and requirements.","zh":"比較可能的大學課程能幫助學生理解選擇和要求。"},{"en":"This phrase shows that planning a dream involves real academic options.","zh":"這個短語顯示規劃夢想涉及真實學術選項。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"entry requirements","meaning":"入學要求","examples":[{"en":"Include the entry requirements for veterinary courses.","zh":"包括獸醫課程的入學要求。"},{"en":"Entry requirements are the grades, subjects, tests, or experience needed to enter a course.","zh":"入學要求是進入一門課程所需的成績、科目、測驗或經驗。"},{"en":"A university may list biology and chemistry as entry requirements for veterinary medicine.","zh":"大學可能把生物和化學列為獸醫學的入學要求。"},{"en":"Knowing entry requirements helps students choose subjects and set study goals.","zh":"知道入學要求能幫助學生選科和設定學習目標。"},{"en":"This phrase connects a dream with the practical steps needed to reach it.","zh":"這個短語把夢想與達成夢想所需的實際步驟連接起來。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"estimated costs","meaning":"估計費用","examples":[{"en":"Include estimated costs in your career folder.","zh":"在你的職業資料夾中包括估計費用。"},{"en":"Estimated costs are approximate amounts of money something may require.","zh":"估計費用是某事可能需要的大約金額。"},{"en":"A student may calculate estimated costs for tuition, books, transport, and accommodation.","zh":"學生可能計算學費、書本、交通和住宿的估計費用。"},{"en":"Estimated costs help families discuss whether a plan is financially possible.","zh":"估計費用幫助家庭討論計劃在財政上是否可行。"},{"en":"Costs do not need to be exact at first, but they should be realistic enough to guide planning.","zh":"費用一開始不必完全準確，但應足夠實際以指導計劃。"}],"source":"2018 Q4.pdf","sourcePage":5},{"front":"scholarships","meaning":"獎學金","examples":[{"en":"Your folder may include possible scholarships.","zh":"你的資料夾可以包括可能的獎學金。"},{"en":"Scholarships are financial awards that help students pay for study.","zh":"獎學金是幫助學生支付學習費用的財政獎項。"},{"en":"A student with strong grades or volunteer experience may apply for scholarships.","zh":"成績好或有義工經驗的學生可能申請獎學金。"},{"en":"Scholarships can reduce parents’ concern about the cost of university.","zh":"獎學金可以減少父母對大學費用的憂慮。"},{"en":"Listing scholarships shows that the student has thought about money responsibly.","zh":"列出獎學金顯示學生已負責任地考慮金錢。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"related jobs such as","meaning":"相關工作，例如……","examples":[{"en":"Include related jobs such as veterinary nursing or animal welfare work.","zh":"包括相關工作，例如獸醫護理或動物福利工作。"},{"en":"Related jobs such as introduces other careers connected to the same interest or field.","zh":"相關工作，例如……，是用來引出與同一興趣或範疇有關的其他職業。"},{"en":"A student interested in medicine may explore related jobs such as nursing, physiotherapy, or laboratory work.","zh":"對醫療有興趣的學生可能探索相關工作，例如護理、物理治療或實驗室工作。"},{"en":"Including related jobs helps show that a dream has more than one possible route.","zh":"包括相關工作有助顯示夢想有不只一條可能路線。"},{"en":"This phrase is useful when giving examples of alternative paths.","zh":"舉出替代道路的例子時，這個短語很有用。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"veterinary nursing","meaning":"獸醫護理","examples":[{"en":"Veterinary nursing is a related job.","zh":"獸醫護理是一份相關工作。"},{"en":"Veterinary nursing means supporting vets by caring for animals before, during, and after treatment.","zh":"獸醫護理是指透過在治療前、治療中和治療後照顧動物來支援獸醫。"},{"en":"A veterinary nurse may prepare equipment, comfort animals, and explain care instructions to owners.","zh":"獸醫護士可能準備設備、安撫動物，並向主人解釋護理指示。"},{"en":"Veterinary nursing requires patience, animal-handling skills, and scientific understanding.","zh":"獸醫護理需要耐性、處理動物的技巧和科學理解。"},{"en":"It may suit someone who loves animal care but wants a different path from becoming a vet.","zh":"它可能適合熱愛動物照顧，但想走不同於成為獸醫道路的人。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"animal welfare work","meaning":"動物福利工作","examples":[{"en":"Animal welfare work is another possible career path.","zh":"動物福利工作是另一條可能的職業道路。"},{"en":"Animal welfare work means protecting animals’ health, safety, living conditions, and rights.","zh":"動物福利工作是指保護動物的健康、安全、生活環境和權益。"},{"en":"Workers in animal welfare may rescue abandoned pets or improve shelter conditions.","zh":"動物福利工作者可能拯救被遺棄寵物，或改善收容所環境。"},{"en":"Animal welfare work can help many animals even outside a veterinary clinic.","zh":"即使在獸醫診所以外，動物福利工作也能幫助很多動物。"},{"en":"This career path is connected to compassion, responsibility, and public education.","zh":"這條職業道路與同情心、責任和公眾教育有關。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"the daily duties of a vet","meaning":"獸醫的日常職責","examples":[{"en":"You should understand the daily duties of a vet.","zh":"你應該了解獸醫的日常職責。"},{"en":"The daily duties of a vet are the regular tasks a veterinarian does in normal work.","zh":"獸醫的日常職責，是獸醫在平常工作中定期要做的任務。"},{"en":"These duties may include checking animals, giving medicine, talking to owners, and keeping records.","zh":"這些職責可能包括檢查動物、給藥、與主人交談和保存記錄。"},{"en":"Understanding daily duties prevents students from seeing the job only through romantic ideas.","zh":"了解日常職責能防止學生只用浪漫想像看待這份工作。"},{"en":"This phrase helps turn a career dream into a clearer picture of real work.","zh":"這個短語幫助把職業夢想變成更清楚的真實工作圖像。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, try to gain experience.","zh":"更好的是，嘗試累積經驗。"},{"en":"Better still introduces an even better suggestion than the one before it.","zh":"更好的是，用來引出比之前更好的建議。"},{"en":"Research the career; better still, speak to someone who works in it.","zh":"研究這份職業；更好的是，與從事這份工作的人交談。"},{"en":"This phrase helps advice move from a good step to a stronger step.","zh":"這個短語幫助建議由好的步驟推進到更有力的步驟。"},{"en":"It shows that action can be more convincing than words alone.","zh":"它顯示行動可以比單靠說話更有說服力。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"gain experience","meaning":"累積經驗","examples":[{"en":"You should try to gain experience with animals.","zh":"你應該嘗試累積與動物相處的經驗。"},{"en":"To gain experience means to learn by doing real tasks, not only reading about them.","zh":"累積經驗是指透過做真實任務來學習，而不只是閱讀資料。"},{"en":"A student can gain experience by helping at an animal shelter during holidays.","zh":"學生可以在假期到動物收容所幫忙來累積經驗。"},{"en":"Experience helps people understand whether a career suits them.","zh":"經驗能幫助人理解一份職業是否適合自己。"},{"en":"Parents may trust a dream more when the student has gained real experience.","zh":"當學生累積了真實經驗時，父母可能更信任這個夢想。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"volunteer at an animal shelter","meaning":"在動物收容所做義工","examples":[{"en":"You could volunteer at an animal shelter.","zh":"你可以在動物收容所做義工。"},{"en":"To volunteer at an animal shelter means to help care for rescued or homeless animals without being paid.","zh":"在動物收容所做義工，是指無償幫助照顧被救助或無家可歸的動物。"},{"en":"A student may volunteer at an animal shelter by cleaning spaces, feeding animals, and helping staff.","zh":"學生可以透過清潔空間、餵飼動物和幫助職員，在動物收容所做義工。"},{"en":"Volunteering at a shelter teaches responsibility and shows what animal care really involves.","zh":"在收容所做義工能教人責任，並顯示動物照顧真正涉及甚麼。"},{"en":"This experience can make a career plan more believable.","zh":"這種經驗可以令職業計劃更可信。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"animal shelter","meaning":"動物收容所","examples":[{"en":"An animal shelter can offer useful volunteer experience.","zh":"動物收容所可以提供有用的義工經驗。"},{"en":"An animal shelter is a place that cares for animals without homes or proper care.","zh":"動物收容所是照顧沒有家或缺乏適當照顧的動物的地方。"},{"en":"Animal shelters may look after stray cats, abandoned dogs, or injured animals.","zh":"動物收容所可能照顧流浪貓、被遺棄的狗或受傷動物。"},{"en":"Helping at an animal shelter can show students both the joy and difficulty of animal care.","zh":"在動物收容所幫忙，可以讓學生看見動物照顧的喜悅和困難。"},{"en":"This place gives real contact with animal welfare work.","zh":"這個地方提供與動物福利工作的真實接觸。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"pet adoption event","meaning":"寵物領養活動","examples":[{"en":"You could help at a pet adoption event.","zh":"你可以在寵物領養活動中幫忙。"},{"en":"A pet adoption event is an activity where rescued animals meet people who may give them homes.","zh":"寵物領養活動是讓被救助動物接觸可能給牠們家庭的人的活動。"},{"en":"Volunteers at a pet adoption event may answer questions, clean cages, or guide visitors.","zh":"寵物領養活動的義工可能回答問題、清潔籠子或引導訪客。"},{"en":"Such events teach students how animal welfare connects with public education.","zh":"這類活動教學生動物福利如何與公眾教育有關。"},{"en":"Helping at one can show responsibility, patience, and care.","zh":"在活動中幫忙可以顯示責任、耐性和關懷。"}],"source":"2018 Q4.pdf","sourcePage":6},{"front":"interview a local vet","meaning":"訪問本地獸醫","examples":[{"en":"You could interview a local vet.","zh":"你可以訪問本地獸醫。"},{"en":"To interview a local vet means to ask a nearby veterinarian questions about the job.","zh":"訪問本地獸醫，是指向附近的獸醫詢問有關工作的問題。"},{"en":"A student may interview a local vet about study routes, daily duties, and difficult cases.","zh":"學生可能訪問本地獸醫，了解升學路線、日常職責和困難個案。"},{"en":"Interviewing a vet gives real information that websites may not explain fully.","zh":"訪問獸醫能得到網站未必完整解釋的真實資訊。"},{"en":"This step shows parents that the student is researching the career seriously.","zh":"這個步驟向父母顯示學生正在認真研究這份職業。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"biology-related activity","meaning":"與生物相關的活動","examples":[{"en":"You could join a biology-related activity at school.","zh":"你可以參加學校與生物相關的活動。"},{"en":"A biology-related activity is an activity connected to living things, health, animals, plants, or the human body.","zh":"與生物相關的活動，是與生物、健康、動物、植物或人體有關的活動。"},{"en":"A science club project about animal behaviour can be a biology-related activity.","zh":"關於動物行為的科學學會專題，可以是與生物相關的活動。"},{"en":"Joining such activities helps students test whether they truly enjoy the science behind veterinary work.","zh":"參加這類活動能幫助學生測試自己是否真正喜歡獸醫工作背後的科學。"},{"en":"This phrase links career interest with school learning.","zh":"這個短語把職業興趣與學校學習連接起來。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take caring for an injured stray cat, for example.","zh":"以照顧一隻受傷流浪貓為例。"},{"en":"Take something for example means using one case to make a wider point clearer.","zh":"以……為例，是指用一個例子令較大的觀點更清楚。"},{"en":"Take a school project, for example: planning matters as much as enthusiasm.","zh":"以學校專題為例：計劃和熱情同樣重要。"},{"en":"This phrase helps a writer move from general advice to a concrete situation.","zh":"這個短語幫助作者由一般建議轉向具體情況。"},{"en":"Examples make abstract advice easier to understand.","zh":"例子令抽象建議更容易理解。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"caring for","meaning":"照顧","examples":[{"en":"Caring for an injured stray cat requires responsibility.","zh":"照顧一隻受傷流浪貓需要責任感。"},{"en":"Caring for means looking after someone or something with attention and responsibility.","zh":"照顧是指用心和負責任地照料某人或某物。"},{"en":"Caring for a sick pet may include feeding it, cleaning it, and watching its symptoms.","zh":"照顧生病寵物可能包括餵食、清潔和留意症狀。"},{"en":"True caring for animals involves patience, not just affection.","zh":"真正照顧動物需要耐性，而不只是喜愛。"},{"en":"This phrase shows active responsibility rather than simple liking.","zh":"這個短語顯示主動責任，而不是單純喜歡。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"injured stray cat","meaning":"受傷流浪貓","examples":[{"en":"Caring for an injured stray cat can show maturity.","zh":"照顧一隻受傷流浪貓可以顯示成熟。"},{"en":"An injured stray cat is a homeless cat that has been hurt.","zh":"受傷流浪貓是受了傷、沒有家的貓。"},{"en":"A student who finds an injured stray cat should ask an adult or animal expert for help.","zh":"學生發現受傷流浪貓時，應向成人或動物專家求助。"},{"en":"Helping an injured stray cat requires safety, hygiene, and careful observation.","zh":"幫助受傷流浪貓需要安全、衛生和細心觀察。"},{"en":"This example shows that animal care can involve pain and responsibility.","zh":"這個例子顯示動物照顧可能涉及痛苦和責任。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"noticing symptoms","meaning":"留意症狀","examples":[{"en":"Noticing symptoms is more mature than simply feeding the cat.","zh":"留意症狀比只是餵貓更成熟。"},{"en":"Noticing symptoms means observing signs that an animal or person may be ill or injured.","zh":"留意症狀是指觀察動物或人可能生病或受傷的跡象。"},{"en":"A pet owner notices symptoms when a dog stops eating or moves strangely.","zh":"當狗停止進食或走路奇怪時，寵物主人就是在留意症狀。"},{"en":"Noticing symptoms early can help an animal receive treatment sooner.","zh":"及早留意症狀可以幫助動物更快接受治療。"},{"en":"This phrase shows careful attention, not just kindness.","zh":"這個短語顯示細心注意，而不只是善良。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"keeping records","meaning":"保存記錄","examples":[{"en":"Keeping records shows responsibility.","zh":"保存記錄顯示責任感。"},{"en":"Keeping records means writing down important information so it can be checked later.","zh":"保存記錄是指寫下重要資訊，以便日後查看。"},{"en":"A volunteer may keep records of feeding times, medicine, symptoms, and vet visits.","zh":"義工可能保存餵食時間、藥物、症狀和看獸醫次數的記錄。"},{"en":"Keeping records helps people notice changes that memory alone may miss.","zh":"保存記錄幫助人們注意單靠記憶可能錯過的變化。"},{"en":"This habit shows discipline and serious care.","zh":"這個習慣顯示紀律和認真照顧。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"cleaning responsibly","meaning":"負責任地清潔","examples":[{"en":"Cleaning responsibly is part of caring for animals.","zh":"負責任地清潔是照顧動物的一部分。"},{"en":"Cleaning responsibly means cleaning in a safe, careful, and hygienic way.","zh":"負責任地清潔，是指以安全、細心和衛生的方式清潔。"},{"en":"At an animal shelter, volunteers clean responsibly by using gloves and following instructions.","zh":"在動物收容所，義工透過戴手套和遵守指示負責任地清潔。"},{"en":"Responsible cleaning protects animals, workers, and visitors from illness.","zh":"負責任的清潔保護動物、工作人員和訪客免受疾病影響。"},{"en":"This phrase shows that animal care includes ordinary but important tasks.","zh":"這個短語顯示動物照顧包括普通但重要的任務。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"ask an expert for help","meaning":"向專家求助","examples":[{"en":"Asking an expert for help shows maturity.","zh":"向專家求助顯示成熟。"},{"en":"To ask an expert for help means to seek advice from someone with proper knowledge or training.","zh":"向專家求助，是指向具備適當知識或訓練的人尋求建議。"},{"en":"A student should ask an expert for help before touching an injured wild animal.","zh":"學生在接觸受傷野生動物前，應向專家求助。"},{"en":"Asking for expert help can prevent mistakes caused by good intentions alone.","zh":"向專家求助可以防止單靠好意造成錯誤。"},{"en":"This phrase shows that maturity includes knowing your limits.","zh":"這個短語顯示成熟包括知道自己的限制。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"show maturity","meaning":"顯示成熟","examples":[{"en":"Keeping records and asking for expert help show maturity.","zh":"保存記錄和向專家求助顯示成熟。"},{"en":"To show maturity means to act with responsibility, patience, and good judgement.","zh":"顯示成熟是指以責任、耐性和良好判斷行事。"},{"en":"A teenager shows maturity by listening calmly during a difficult family conversation.","zh":"青少年在困難家庭對話中冷靜聆聽，就是顯示成熟。"},{"en":"Parents may trust a dream more when actions show maturity.","zh":"當行動顯示成熟時，父母可能更信任一個夢想。"},{"en":"This phrase links behaviour with readiness for greater responsibility.","zh":"這個短語把行為與承擔更大責任的準備連接起來。"}],"source":"2018 Q4.pdf","sourcePage":7},{"front":"be willing to","meaning":"願意","examples":[{"en":"Your parents need to see that you are willing to face unpleasant realities.","zh":"你的父母需要看見你願意面對不愉快的現實。"},{"en":"To be willing to means to be ready or prepared to do something.","zh":"願意是指準備好或樂意做某事。"},{"en":"A student who wants to be a vet must be willing to study science seriously.","zh":"想成為獸醫的學生必須願意認真學習科學。"},{"en":"Being willing to do hard tasks shows that a dream is more than a fantasy.","zh":"願意做困難任務顯示夢想不只是幻想。"},{"en":"This phrase highlights readiness, not just interest.","zh":"這個短語突出準備程度，而不只是興趣。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"wake up early","meaning":"早起","examples":[{"en":"You may need to wake up early to help with animals.","zh":"你可能需要早起幫忙照顧動物。"},{"en":"To wake up early means to get out of bed earlier than usual or before the day becomes busy.","zh":"早起是指比平常更早或在一天變忙前起床。"},{"en":"Shelter volunteers may wake up early to feed animals before school.","zh":"收容所義工可能早起，在上學前餵飼動物。"},{"en":"Waking up early shows discipline when the work is not convenient.","zh":"當工作不方便時，早起顯示紀律。"},{"en":"This phrase reminds students that animal care may interrupt comfortable routines.","zh":"這個短語提醒學生，動物照顧可能打斷舒適的日常習慣。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"clean cages","meaning":"清潔籠子","examples":[{"en":"Animal work may require you to clean cages.","zh":"動物工作可能需要你清潔籠子。"},{"en":"To clean cages means to remove waste and keep animals’ living spaces hygienic.","zh":"清潔籠子是指清除污物，並保持動物居住空間衛生。"},{"en":"Volunteers clean cages so animals have safe and healthy places to stay.","zh":"義工清潔籠子，讓動物有安全健康的地方停留。"},{"en":"Cleaning cages may not be glamorous, but it is essential animal care.","zh":"清潔籠子可能不吸引，但它是必要的動物照顧。"},{"en":"This task tests whether someone accepts the less pleasant side of animal work.","zh":"這項任務測試某人是否接受動物工作較不愉快的一面。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"read science texts","meaning":"閱讀科學文本","examples":[{"en":"A future vet must be willing to read science texts.","zh":"未來的獸醫必須願意閱讀科學文本。"},{"en":"To read science texts means to study written material about scientific ideas, facts, and methods.","zh":"閱讀科學文本，是指學習關於科學概念、事實和方法的文字材料。"},{"en":"Veterinary students read science texts about anatomy, disease, medicine, and animal behaviour.","zh":"獸醫學生會閱讀關於解剖、疾病、藥物和動物行為的科學文本。"},{"en":"Reading science texts helps students understand that veterinary work is academic as well as caring.","zh":"閱讀科學文本能幫助學生明白獸醫工作既是關懷工作，也是學術工作。"},{"en":"This phrase connects career passion with serious study.","zh":"這個短語把職業熱情與認真學習連接起來。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"face unpleasant realities","meaning":"面對不愉快的現實","examples":[{"en":"You must be ready to face unpleasant realities.","zh":"你必須準備好面對不愉快的現實。"},{"en":"To face unpleasant realities means to accept difficult facts instead of avoiding them.","zh":"面對不愉快的現實，是指接受困難事實，而不是逃避它們。"},{"en":"A future vet must face unpleasant realities such as illness, injury, and animal suffering.","zh":"未來獸醫必須面對疾病、受傷和動物痛苦等不愉快的現實。"},{"en":"Facing unpleasant realities helps people prepare for a career honestly.","zh":"面對不愉快的現實能幫助人誠實地為職業作準備。"},{"en":"This phrase shows maturity because it accepts both hope and hardship.","zh":"這個短語顯示成熟，因為它同時接受希望與困難。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"impression may change from…to…","meaning":"印象可能由……變成……","examples":[{"en":"Their impression may change from “J.C. likes animals” to “J.C. is disciplined.”","zh":"他們的印象可能由「J.C. 喜歡動物」變成「J.C. 有紀律」。"},{"en":"Impression may change from A to B means people may begin to see someone or something differently.","zh":"印象可能由A變成B，是指人們可能開始以不同方式看待某人或某事。"},{"en":"A teacher’s impression may change from “this student is quiet” to “this student is thoughtful.”","zh":"老師的印象可能由「這個學生很安靜」變成「這個學生很有思想」。"},{"en":"Actions can change parents’ impression from simple interest to serious commitment.","zh":"行動可以令父母的印象由單純興趣變成認真投入。"},{"en":"This phrase shows how behaviour can reshape other people’s views.","zh":"這個短語顯示行為如何改變別人的看法。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"disciplined enough to","meaning":"有足夠紀律去……","examples":[{"en":"Your parents may see that you are disciplined enough to work with animals.","zh":"你的父母可能會看見你有足夠紀律去照顧動物。"},{"en":"Disciplined enough to means having enough self-control, effort, and consistency to do something well.","zh":"有足夠紀律去做某事，是指有足夠自制力、努力和持續性去做好它。"},{"en":"A student is disciplined enough to prepare for exams when she studies regularly without reminders.","zh":"當學生不用提醒也定期溫習時，她就是有足夠紀律去準備考試。"},{"en":"Parents may trust a dream more when the student seems disciplined enough to handle its demands.","zh":"當學生看似有足夠紀律去應付夢想的要求時，父母可能更信任這個夢想。"},{"en":"This phrase shows readiness through repeated responsible action.","zh":"這個短語透過持續負責任行動顯示準備。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"that shift is really powerful","meaning":"那個轉變很有力量","examples":[{"en":"Remember, that shift is really powerful.","zh":"記住，那個轉變很有力量。"},{"en":"That shift is really powerful means that change in how people see you can have a strong effect.","zh":"那個轉變很有力量，是指別人看待你的方式改變後，會產生強大影響。"},{"en":"The shift from “I just like animals” to “I am prepared for hard work” can change a family conversation.","zh":"由「我只是喜歡動物」到「我準備好努力工作」的轉變，可以改變家庭對話。"},{"en":"A powerful shift can make parents take a dream more seriously.","zh":"有力量的轉變可以令父母更認真看待一個夢想。"},{"en":"This phrase highlights the importance of changing perception through action.","zh":"這個短語突出透過行動改變印象的重要性。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"at the same time","meaning":"與此同時","examples":[{"en":"At the same time, be prepared to compromise without giving up.","zh":"與此同時，準備好妥協但不放棄。"},{"en":"At the same time means while another idea is also true or happening.","zh":"與此同時，是指另一個想法也成立或正在發生。"},{"en":"You can be determined; at the same time, you can listen to your parents’ worries.","zh":"你可以有決心；與此同時，你也可以聆聽父母的憂慮。"},{"en":"This phrase helps balance two ideas that should happen together.","zh":"這個短語幫助平衡兩個應同時存在的想法。"},{"en":"It is useful when advice needs both firmness and flexibility.","zh":"當建議需要堅定和彈性時，它很有用。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"be prepared to","meaning":"準備好去","examples":[{"en":"Be prepared to compromise without giving up.","zh":"準備好去妥協但不放棄。"},{"en":"Be prepared to means be ready to do something if the situation requires it.","zh":"準備好去做某事，是指如果情況需要，就已經準備好行動。"},{"en":"A student should be prepared to answer questions about costs and study requirements.","zh":"學生應準備好回答關於費用和學習要求的問題。"},{"en":"Being prepared to compromise shows maturity, not weakness.","zh":"準備好去妥協顯示成熟，而不是軟弱。"},{"en":"This phrase suggests practical readiness before a difficult conversation.","zh":"這個短語表示在困難對話前已有實際準備。"}],"source":"2018 Q4.pdf","sourcePage":8},{"front":"compromise without giving up","meaning":"妥協但不放棄","examples":[{"en":"You should compromise without giving up.","zh":"你應該妥協但不放棄。"},{"en":"To compromise without giving up means to adjust your method while keeping your main dream alive.","zh":"妥協但不放棄，是指調整方法，同時保留主要夢想。"},{"en":"A student may compromise by trying a three-month volunteer plan before applying for a course.","zh":"學生可能先嘗試三個月義工計劃，再申請課程，這就是妥協。"},{"en":"Compromise can reduce fear while still moving the dream forward.","zh":"妥協可以減少恐懼，同時仍推動夢想向前。"},{"en":"This phrase shows flexibility without surrender.","zh":"這個短語顯示有彈性但不投降。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"three-month trial period","meaning":"三個月試行期","examples":[{"en":"You could ask your parents for a three-month trial period.","zh":"你可以向父母要求一個三個月試行期。"},{"en":"A three-month trial period is a limited time of three months used to test a plan.","zh":"三個月試行期是用三個月的有限時間來測試一個計劃。"},{"en":"During a three-month trial period, a student may volunteer regularly and keep school grades steady.","zh":"在三個月試行期中，學生可以定期做義工並保持學業成績穩定。"},{"en":"A trial period feels safer because parents are not asked to agree forever immediately.","zh":"試行期感覺較安全，因為父母不是被要求立即永久同意。"},{"en":"This phrase turns a big decision into a smaller experiment.","zh":"這個短語把重大決定變成較小的實驗。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"continue working hard","meaning":"繼續努力","examples":[{"en":"You can continue working hard at school during the trial period.","zh":"你可以在試行期內繼續在學校努力。"},{"en":"To continue working hard means to keep making serious effort over time.","zh":"繼續努力是指在一段時間內保持認真付出。"},{"en":"A student can continue working hard by revising regularly even while volunteering.","zh":"學生即使做義工，也可以透過定期溫習繼續努力。"},{"en":"Continuing to work hard shows parents that the dream does not damage school responsibility.","zh":"繼續努力向父母顯示夢想不會損害學業責任。"},{"en":"This phrase stresses consistency, not just short excitement.","zh":"這個短語強調持續性，而不只是一時興奮。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"supervised animal-related volunteering","meaning":"受監督的動物相關義工服務","examples":[{"en":"You could do supervised animal-related volunteering.","zh":"你可以做受監督的動物相關義工服務。"},{"en":"Supervised animal-related volunteering means helping with animals under the guidance of responsible adults or professionals.","zh":"受監督的動物相關義工服務，是指在負責任成人或專業人士指導下幫助動物。"},{"en":"A student may clean cages at a shelter while staff supervise the work.","zh":"學生可能在收容所職員監督下清潔籠子。"},{"en":"Supervision makes animal-related volunteering safer for both students and animals.","zh":"監督令動物相關義工服務對學生和動物都更安全。"},{"en":"This phrase shows a careful way to gain experience.","zh":"這個短語顯示累積經驗的謹慎方法。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"sit down together","meaning":"坐下來一起","examples":[{"en":"You can sit down together to review what you have learned.","zh":"你們可以坐下來一起檢視你學到了甚麼。"},{"en":"To sit down together means to meet calmly and discuss something carefully.","zh":"坐下來一起，是指冷靜見面並仔細討論某事。"},{"en":"A family may sit down together after dinner to talk about a school choice.","zh":"家庭可能在晚飯後坐下來一起談論學校選擇。"},{"en":"Sitting down together helps people listen instead of shouting from separate rooms.","zh":"坐下來一起有助人們聆聽，而不是在不同房間大叫。"},{"en":"This phrase suggests a serious but peaceful conversation.","zh":"這個短語表示一場認真但和平的對話。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"review what you have learned","meaning":"檢視你學到了甚麼","examples":[{"en":"You can review what you have learned after three months.","zh":"三個月後，你可以檢視你學到了甚麼。"},{"en":"To review what you have learned means to look back and examine new knowledge or experience.","zh":"檢視你學到了甚麼，是指回望並審視新的知識或經驗。"},{"en":"After volunteering, a student can review what they learned about animal care and responsibility.","zh":"做義工後，學生可以檢視自己學到關於動物照顧和責任的事情。"},{"en":"Reviewing learning helps people decide whether the plan should continue or change.","zh":"檢視學習成果能幫助人決定計劃應繼續還是改變。"},{"en":"This phrase turns experience into reflection.","zh":"這個短語把經驗轉化為反思。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"give someone breathing room","meaning":"給某人喘息空間","examples":[{"en":"A trial period gives your parents breathing room.","zh":"試行期給你的父母喘息空間。"},{"en":"To give someone breathing room means to give them time and space to think without pressure.","zh":"給某人喘息空間，是指給他們時間和空間思考，而沒有壓力。"},{"en":"Asking for a short trial gives parents breathing room because they do not need to decide everything now.","zh":"要求短期試行能給父母喘息空間，因為他們不需要現在決定所有事情。"},{"en":"Breathing room can make a difficult discussion feel less frightening.","zh":"喘息空間可以令困難討論感覺不那麼可怕。"},{"en":"This phrase shows respect for other people’s need to process information.","zh":"這個短語顯示尊重別人處理資訊的需要。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"a fair chance","meaning":"公平的機會","examples":[{"en":"A trial period gives you a fair chance.","zh":"試行期給你一個公平的機會。"},{"en":"A fair chance is a reasonable opportunity to try or prove something.","zh":"公平的機會是嘗試或證明某事的合理機會。"},{"en":"A student asks for a fair chance when they request time to show responsibility.","zh":"當學生要求時間來展示責任感時，他就是在要求公平的機會。"},{"en":"A fair chance does not guarantee success, but it allows evidence to appear.","zh":"公平的機會不保證成功，但容許證據出現。"},{"en":"This phrase is useful when someone wants to be judged by action, not assumption.","zh":"當某人希望由行動而不是假設來被評價時，這個短語很有用。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"careers adviser","meaning":"升學及就業輔導老師","examples":[{"en":"You may ask a careers adviser to join one conversation.","zh":"你可以請升學及就業輔導老師參與一次對話。"},{"en":"A careers adviser is a person who helps students understand study choices and job paths.","zh":"升學及就業輔導老師是幫助學生理解升學選擇和職業道路的人。"},{"en":"A careers adviser can explain university courses, entry requirements, and related careers.","zh":"升學及就業輔導老師可以解釋大學課程、入學要求和相關職業。"},{"en":"Having a careers adviser present can make a family discussion more factual.","zh":"有升學及就業輔導老師在場，可以令家庭討論更基於事實。"},{"en":"This person can support the conversation without replacing the parents’ role.","zh":"這個人可以支援對話，而不取代父母的角色。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"relative or family friend","meaning":"親戚或家庭朋友","examples":[{"en":"A relative or family friend may help make the discussion calmer.","zh":"親戚或家庭朋友可能幫助令討論更冷靜。"},{"en":"A relative or family friend is someone connected to the family who may be trusted by both sides.","zh":"親戚或家庭朋友，是與家庭有關並可能被雙方信任的人。"},{"en":"An aunt, uncle, older cousin, or trusted neighbour can be a relative or family friend.","zh":"姨媽、叔叔、年長表親或可信任鄰居都可以是親戚或家庭朋友。"},{"en":"Such a person may help if parents and children are too emotional to listen well.","zh":"如果父母和孩子太情緒化而無法好好聆聽，這樣的人可能有幫助。"},{"en":"The purpose is to support calm conversation, not to take sides.","zh":"目的在於支援冷靜對話，而不是偏幫一方。"}],"source":"2018 Q4.pdf","sourcePage":9},{"front":"not to pressure your parents, but to","meaning":"不是為了……而是為了……","examples":[{"en":"Ask someone to join not to pressure your parents, but to make the discussion less emotional.","zh":"請人參與不是為了向父母施壓，而是為了令討論沒那麼情緒化。"},{"en":"Not to A, but to B shows the real purpose by first rejecting the wrong purpose.","zh":"不是為了A，而是為了B，先否定錯誤目的，再顯示真正目的。"},{"en":"Ask the adviser to join not to win the argument, but to explain the facts clearly.","zh":"請輔導老師參與不是為了贏得爭論，而是為了清楚解釋事實。"},{"en":"This structure helps prevent misunderstanding about your intention.","zh":"這個句式有助避免別人誤解你的意圖。"},{"en":"It is useful when you want your action to sound respectful and balanced.","zh":"當你想令行動聽起來尊重而平衡時，這個句式很有用。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"make the discussion less emotional","meaning":"令討論沒那麼情緒化","examples":[{"en":"A trusted adult may make the discussion less emotional.","zh":"一位可信任成人可能令討論沒那麼情緒化。"},{"en":"To make the discussion less emotional means to help people talk with more calm and fewer strong reactions.","zh":"令討論沒那麼情緒化，是指幫助人們更冷靜、少一點強烈反應地交談。"},{"en":"A careers adviser can make the discussion less emotional by focusing on facts and options.","zh":"升學及就業輔導老師可以透過集中於事實和選項，令討論沒那麼情緒化。"},{"en":"A less emotional discussion allows both sides to listen more carefully.","zh":"沒那麼情緒化的討論能讓雙方更仔細聆聽。"},{"en":"This phrase shows that the goal is not victory, but clearer communication.","zh":"這個短語顯示目標不是勝利，而是更清晰的溝通。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"make the mistake of","meaning":"犯下……的錯誤","examples":[{"en":"Do not make the mistake of presenting your dream as “vet or nothing.”","zh":"不要犯下把夢想呈現為「非獸醫不可」的錯誤。"},{"en":"To make the mistake of doing something means to choose an unwise action that may create problems.","zh":"犯下做某事的錯誤，是指選擇可能造成問題的不明智行動。"},{"en":"A student may make the mistake of shouting instead of explaining a careful plan.","zh":"學生可能犯下大叫而不是解釋細心計劃的錯誤。"},{"en":"Making this mistake can make parents more worried and less open to discussion.","zh":"犯下這個錯誤可能令父母更擔心，也更不願討論。"},{"en":"This phrase warns someone before they take an unhelpful path.","zh":"這個短語在某人走向沒有幫助的道路前提出警告。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"present your dream as","meaning":"把夢想呈現為……","examples":[{"en":"Do not present your dream as “vet or nothing.”","zh":"不要把夢想呈現為「非獸醫不可」。"},{"en":"To present your dream as something means to describe or frame your dream in a certain way.","zh":"把夢想呈現為某種樣子，是指以某種方式描述或包裝你的夢想。"},{"en":"A student can present a dream as a careful plan rather than a demand.","zh":"學生可以把夢想呈現為細心計劃，而不是要求。"},{"en":"If you present your dream as “all or nothing,” others may feel pressured.","zh":"如果你把夢想呈現為「全有或全無」，別人可能感到受壓。"},{"en":"This phrase shows that how you explain a dream affects how people receive it.","zh":"這個短語顯示你如何解釋夢想，會影響別人如何接收它。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"vet or nothing","meaning":"非獸醫不可","examples":[{"en":"Do not present your dream as “vet or nothing.”","zh":"不要把夢想呈現為「非獸醫不可」。"},{"en":"Vet or nothing means believing that becoming a vet is the only acceptable future.","zh":"非獸醫不可，是指相信成為獸醫是唯一可接受的未來。"},{"en":"A “vet or nothing” attitude may make parents think the student has not considered risks.","zh":"「非獸醫不可」的態度可能令父母覺得學生沒有考慮風險。"},{"en":"Avoiding “vet or nothing” does not weaken the dream; it makes the plan more flexible.","zh":"避免「非獸醫不可」不會削弱夢想，而會令計劃更有彈性。"},{"en":"This phrase warns against turning one career path into the only possible identity.","zh":"這個短語提醒人們不要把一條職業道路變成唯一可能的身份。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"veterinary medicine","meaning":"獸醫學","examples":[{"en":"If veterinary medicine proves unsuitable later, there are other options.","zh":"如果獸醫學日後證明不適合，仍有其他選擇。"},{"en":"Veterinary medicine is the field of study and work that focuses on animal health and disease treatment.","zh":"獸醫學是專注於動物健康和疾病治療的學習與工作領域。"},{"en":"Students who study veterinary medicine learn about anatomy, biology, surgery, and animal care.","zh":"修讀獸醫學的學生會學習解剖、生物、手術和動物照顧。"},{"en":"Veterinary medicine can be demanding because it combines science, communication, and emotional decisions.","zh":"獸醫學可能很艱難，因為它結合科學、溝通和情感決定。"},{"en":"Understanding the field clearly helps students choose it for the right reasons.","zh":"清楚理解這個領域，能幫助學生基於正確原因選擇它。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"prove unsuitable","meaning":"證明不適合","examples":[{"en":"Veterinary medicine may prove unsuitable later.","zh":"獸醫學日後可能證明不適合。"},{"en":"To prove unsuitable means to turn out not to fit someone’s needs, abilities, or situation.","zh":"證明不適合，是指後來發現不符合某人的需要、能力或情況。"},{"en":"A course may prove unsuitable if a student discovers they dislike the main subject.","zh":"如果學生發現自己不喜歡主要科目，一門課程可能證明不適合。"},{"en":"A career path can prove unsuitable after real experience reveals unexpected pressure.","zh":"真實經驗揭示意料之外的壓力後，一條職業道路可能證明不適合。"},{"en":"This phrase shows that changing direction can be based on evidence, not failure.","zh":"這個短語顯示改變方向可以基於證據，而不是失敗。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"lead to","meaning":"通向；帶來","examples":[{"en":"Your love for animals could still lead to other careers.","zh":"你對動物的熱愛仍可以通向其他職業。"},{"en":"To lead to means to result in, guide toward, or open the way to something.","zh":"通向是指導致、引向或打開通往某事的道路。"},{"en":"Volunteer work at a shelter may lead to an interest in animal welfare.","zh":"在收容所做義工可能帶來對動物福利的興趣。"},{"en":"One passion can lead to several different careers if a student explores carefully.","zh":"如果學生仔細探索，一份熱情可以通向幾種不同職業。"},{"en":"This phrase shows that a dream can develop in more than one direction.","zh":"這個短語顯示夢想可以向不只一個方向發展。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"animal science","meaning":"動物科學","examples":[{"en":"Your love for animals could lead to animal science.","zh":"你對動物的熱愛可以通向動物科學。"},{"en":"Animal science is the study of animals, including their biology, behaviour, nutrition, and care.","zh":"動物科學是研究動物的學科，包括牠們的生物、行為、營養和照顧。"},{"en":"A student in animal science may learn how farms, zoos, and shelters keep animals healthy.","zh":"動物科學學生可能學習農場、動物園和收容所如何保持動物健康。"},{"en":"Animal science can suit people who like animals and scientific investigation.","zh":"動物科學可能適合喜歡動物和科學研究的人。"},{"en":"This field is related to veterinary medicine but not exactly the same.","zh":"這個領域與獸醫學有關，但並不完全相同。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"conservation","meaning":"保育","examples":[{"en":"Your love for animals could lead to conservation.","zh":"你對動物的熱愛可以通向保育。"},{"en":"Conservation means protecting nature, wildlife, and habitats from damage or loss.","zh":"保育是指保護自然、野生動物和棲息地免受破壞或失去。"},{"en":"A conservation worker may help protect endangered birds, forests, or wetlands.","zh":"保育工作者可能幫助保護瀕危鳥類、森林或濕地。"},{"en":"Conservation connects love for animals with protecting the places where they live.","zh":"保育把對動物的熱愛與保護牠們生活的地方連接起來。"},{"en":"This career path may suit someone who cares about wild animals and the environment.","zh":"這條職業道路可能適合關心野生動物和環境的人。"}],"source":"2018 Q4.pdf","sourcePage":10},{"front":"pet nutrition","meaning":"寵物營養","examples":[{"en":"Your love for animals could lead to pet nutrition.","zh":"你對動物的熱愛可以通向寵物營養。"},{"en":"Pet nutrition is the study or work of planning healthy food for pets.","zh":"寵物營養是研究或規劃寵物健康飲食的學習或工作。"},{"en":"A pet nutrition specialist may advise owners on suitable diets for dogs or cats.","zh":"寵物營養專家可能建議主人為狗或貓選擇合適飲食。"},{"en":"Pet nutrition matters because the wrong diet can affect an animal’s health.","zh":"寵物營養很重要，因為錯誤飲食會影響動物健康。"},{"en":"This field shows that helping animals can include science, food, and everyday care.","zh":"這個領域顯示幫助動物可以包括科學、食物和日常照顧。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"animal-assisted therapy","meaning":"動物輔助治療","examples":[{"en":"Your love for animals could lead to animal-assisted therapy.","zh":"你對動物的熱愛可以通向動物輔助治療。"},{"en":"Animal-assisted therapy uses trained animals to support people’s physical, emotional, or social needs.","zh":"動物輔助治療是使用受訓動物來支援人的身體、情緒或社交需要。"},{"en":"A therapy dog may help anxious students feel calmer during a school counselling session.","zh":"治療犬可能在學校輔導期間幫助焦慮學生感到較冷靜。"},{"en":"Animal-assisted therapy requires care for both the person and the animal.","zh":"動物輔助治療需要同時照顧人和動物。"},{"en":"This path connects animal work with health, education, and emotional support.","zh":"這條道路把動物工作與健康、教育和情感支援連接起來。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"charity work","meaning":"慈善工作","examples":[{"en":"Your love for animals could lead to charity work.","zh":"你對動物的熱愛可以通向慈善工作。"},{"en":"Charity work means work done to help people, animals, or communities in need, often through non-profit organisations.","zh":"慈善工作是指透過非牟利機構等方式，幫助有需要的人、動物或社區的工作。"},{"en":"Animal charity work may include rescue, adoption, fundraising, and public education.","zh":"動物慈善工作可能包括救援、領養、籌款和公眾教育。"},{"en":"Charity work can turn personal compassion into organised help.","zh":"慈善工作可以把個人同情心轉化成有組織的幫助。"},{"en":"This phrase shows that a caring dream can serve society in many ways.","zh":"這個短語顯示關懷性的夢想可以用很多方式服務社會。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"weaken your ambition","meaning":"削弱你的抱負","examples":[{"en":"Knowing alternatives does not weaken your ambition.","zh":"了解替代選擇不會削弱你的抱負。"},{"en":"To weaken your ambition means to make your goal or determination seem less strong.","zh":"削弱你的抱負，是指令你的目標或決心看起來較弱。"},{"en":"Exploring related careers does not weaken your ambition; it shows you are thinking carefully.","zh":"探索相關職業不會削弱你的抱負；它顯示你正在仔細思考。"},{"en":"Ambition becomes safer when it includes more than one possible route.","zh":"當抱負包括不只一條可能路線時，它會變得更穩妥。"},{"en":"This phrase reassures students that flexibility is not failure.","zh":"這個短語安慰學生，彈性並不是失敗。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"if anything","meaning":"反而","examples":[{"en":"If anything, knowing alternatives makes your plan safer.","zh":"反而，了解替代選擇會令你的計劃更穩妥。"},{"en":"If anything means the opposite is more likely to be true than what was just suggested.","zh":"If anything 意思是剛才可能暗示的說法不對，反而相反情況更可能是真的。"},{"en":"Exploring backup plans does not show weakness; if anything, it shows maturity.","zh":"探索後備計劃不顯示軟弱；反而，它顯示成熟。"},{"en":"This phrase is used to correct a possible misunderstanding.","zh":"這個短語用來修正可能的誤解。"},{"en":"It helps the writer argue that a feared action may actually be helpful.","zh":"它幫助作者指出令人擔心的行動其實可能有幫助。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"safer and more mature","meaning":"更穩妥和成熟","examples":[{"en":"Knowing alternatives makes your plan safer and more mature.","zh":"了解替代選擇會令你的計劃更穩妥和成熟。"},{"en":"Safer and more mature means less risky and more thoughtful.","zh":"更穩妥和成熟，是指風險較低，並且更有思考。"},{"en":"A career plan becomes safer and more mature when it includes costs, risks, and backup options.","zh":"當職業計劃包括費用、風險和後備選項時，它會變得更穩妥和成熟。"},{"en":"Parents may trust a plan that is safer and more mature because it shows responsibility.","zh":"父母可能信任更穩妥和成熟的計劃，因為它顯示責任感。"},{"en":"This phrase praises careful planning instead of blind insistence.","zh":"這個短語讚賞細心規劃，而不是盲目堅持。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"only by showing that","meaning":"只有透過證明……才可以","examples":[{"en":"Only by showing that you have thought about risks can you earn more freedom.","zh":"只有透過證明你已考慮風險，你才可以贏得更多自由。"},{"en":"Only by showing that means you can achieve something only through proving a certain fact.","zh":"只有透過證明……才可以，是指只能透過證明某個事實來達成某事。"},{"en":"Only by showing that you can manage time well can you ask for more independence.","zh":"只有透過證明你能好好管理時間，你才可以要求更多獨立。"},{"en":"This structure strongly links proof with permission or trust.","zh":"這個句式強烈連接證明與許可或信任。"},{"en":"It shows that freedom often comes after responsibility is demonstrated.","zh":"它顯示自由常在責任被證明後才出現。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"think about risks","meaning":"考慮風險","examples":[{"en":"You need to show that you have thought about risks.","zh":"你需要顯示你已考慮風險。"},{"en":"To think about risks means to consider possible problems before making a decision.","zh":"考慮風險是指在作決定前思考可能出現的問題。"},{"en":"A student thinking about risks may ask what happens if grades fall or costs rise.","zh":"考慮風險的學生可能會問，如果成績下降或費用上升會怎樣。"},{"en":"Thinking about risks does not destroy hope; it makes planning safer.","zh":"考慮風險不會摧毀希望，而會令計劃更安全。"},{"en":"This phrase shows that serious dreams include honest preparation.","zh":"這個短語顯示認真的夢想包括誠實準備。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"earn the freedom to","meaning":"贏得……的自由","examples":[{"en":"You can earn the freedom to pursue the possibility.","zh":"你可以贏得追求這個可能性的自由。"},{"en":"To earn the freedom to do something means to gain trust or permission through responsible action.","zh":"贏得做某事的自由，是指透過負責任行動獲得信任或許可。"},{"en":"A teenager may earn the freedom to travel alone by proving they can plan safely.","zh":"青少年可以透過證明自己能安全計劃，贏得獨自外出的自由。"},{"en":"Responsibility helps people earn freedom because others see they can handle it.","zh":"責任感幫助人贏得自由，因為別人看見他們能應付。"},{"en":"This phrase connects independence with trust earned over time.","zh":"這個短語把獨立與隨時間贏得的信任連接起來。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"pursue the possibility","meaning":"追求這個可能性","examples":[{"en":"You can earn the freedom to pursue the possibility.","zh":"你可以贏得追求這個可能性的自由。"},{"en":"To pursue the possibility means to explore a possible future or goal seriously.","zh":"追求這個可能性，是指認真探索一個可能的未來或目標。"},{"en":"A student may pursue the possibility of becoming a vet by researching courses and volunteering.","zh":"學生可以透過研究課程和做義工，追求成為獸醫的可能性。"},{"en":"Pursuing a possibility does not mean the result is guaranteed.","zh":"追求一個可能性不代表結果有保證。"},{"en":"This phrase keeps the dream open while allowing for learning and change.","zh":"這個短語讓夢想保持開放，同時容許學習和改變。"}],"source":"2018 Q4.pdf","sourcePage":11},{"front":"a verdict on","meaning":"對……的判決","examples":[{"en":"A parent’s first “no” is not a verdict on your whole future.","zh":"父母第一次說「不」，並不是對你整個未來的判決。"},{"en":"A verdict on something is a final judgement about it.","zh":"對某事的判決，是指對它作出的最終判斷。"},{"en":"One rejected application is not a verdict on a student’s ability.","zh":"一次申請被拒，並不是對學生能力的判決。"},{"en":"A first refusal should not be treated as a verdict on an entire dream.","zh":"最初的拒絕不應被視為對整個夢想的判決。"},{"en":"This phrase reassures people that one judgement does not decide everything.","zh":"這個短語安慰人們，一個判斷不會決定一切。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"whole future","meaning":"整個未來","examples":[{"en":"Their first refusal is not a verdict on your whole future.","zh":"他們第一次拒絕並不是對你整個未來的判決。"},{"en":"Whole future means all of a person’s life and possibilities ahead.","zh":"整個未來是指一個人前方全部的人生和可能性。"},{"en":"One failed test does not decide a student’s whole future.","zh":"一次測驗失敗不會決定學生的整個未來。"},{"en":"A whole future is built from many decisions, not one conversation.","zh":"整個未來由許多決定建立，而不是由一次對話決定。"},{"en":"This phrase helps people see beyond a painful moment.","zh":"這個短語幫助人們看見痛苦時刻以外的可能。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"stand firm","meaning":"立場堅定","examples":[{"en":"Stand firm, but stay gracious.","zh":"立場要堅定，但也要保持有禮大方。"},{"en":"To stand firm means to keep your position or belief even when others disagree.","zh":"立場堅定是指即使別人不同意，也保持自己的立場或信念。"},{"en":"A student can stand firm by calmly saying that the dream still matters.","zh":"學生可以透過冷靜地說夢想仍然重要來保持立場堅定。"},{"en":"Standing firm does not require shouting; it requires steady respect and courage.","zh":"立場堅定不需要大叫，而需要穩定的尊重和勇氣。"},{"en":"This phrase shows determination without aggression.","zh":"這個短語顯示決心，而不是攻擊性。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"stay gracious","meaning":"保持有禮大方","examples":[{"en":"Stand firm, but stay gracious.","zh":"立場要堅定，但也要保持有禮大方。"},{"en":"To stay gracious means to remain polite, generous, and respectful even during disagreement.","zh":"保持有禮大方，是指即使在分歧中仍保持禮貌、寬容和尊重。"},{"en":"A teenager stays gracious by thanking parents for listening, even if they still disagree.","zh":"即使仍不同意，青少年感謝父母聆聽，就是保持有禮大方。"},{"en":"Staying gracious keeps the conversation open for future discussion.","zh":"保持有禮大方能讓對話保持開放，方便日後再討論。"},{"en":"This phrase balances strength with kindness.","zh":"這個短語平衡力量與善意。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"speak respectfully","meaning":"尊重地說話","examples":[{"en":"Prepare well, speak respectfully, and listen carefully.","zh":"好好準備、尊重地說話，並仔細聆聽。"},{"en":"To speak respectfully means to express ideas without insulting, shouting, or dismissing others.","zh":"尊重地說話是指表達想法時不侮辱、不大叫，也不否定別人。"},{"en":"A student can speak respectfully while still explaining why the dream matters.","zh":"學生仍可以解釋夢想為何重要，同時尊重地說話。"},{"en":"Respectful speech helps parents hear the message instead of reacting to the tone.","zh":"尊重的說話幫助父母聽到信息，而不是只對語氣作反應。"},{"en":"This phrase shows that how we speak can affect whether others listen.","zh":"這個短語顯示我們如何說話會影響別人是否聆聽。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"let your actions do part of the talking","meaning":"讓行動替你說明一部分","examples":[{"en":"Let your actions do part of the talking.","zh":"讓行動替你說明一部分。"},{"en":"Let your actions do part of the talking means prove your seriousness through behaviour, not only words.","zh":"讓行動替你說明一部分，是指透過行為而不只是說話證明你的認真。"},{"en":"A student lets actions speak by volunteering regularly and keeping grades steady.","zh":"學生透過定期做義工並保持成績穩定，就是讓行動說話。"},{"en":"Actions can persuade parents because they show discipline over time.","zh":"行動可以說服父母，因為它隨時間顯示紀律。"},{"en":"This phrase reminds people that evidence can be lived, not just spoken.","zh":"這個短語提醒人們，證據可以活出來，而不只是說出來。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"the more…, the harder…","meaning":"越……就越難……","examples":[{"en":"The more responsible you become, the harder it will be to dismiss your dream.","zh":"你越負責任，別人就越難否定你的夢想。"},{"en":"The more A, the harder B means as A increases, B becomes more difficult.","zh":"「越A，就越難B」意思是A增加時，B變得更困難。"},{"en":"The more evidence you collect, the harder it is for others to call your plan childish.","zh":"你收集的證據越多，別人就越難說你的計劃幼稚。"},{"en":"This structure clearly shows cause and increasing effect.","zh":"這個句式清楚顯示原因和逐漸增加的效果。"},{"en":"It is useful for explaining how steady effort changes other people’s reactions.","zh":"它適合解釋持續努力如何改變別人的反應。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"dismiss your dream as childish","meaning":"把你的夢想視為幼稚而否定","examples":[{"en":"It will be harder for others to dismiss your dream as childish.","zh":"別人將更難把你的夢想視為幼稚而否定。"},{"en":"To dismiss your dream as childish means to reject it as immature, unrealistic, or not serious.","zh":"把你的夢想視為幼稚而否定，是指認為它不成熟、不實際或不認真而拒絕它。"},{"en":"Parents may dismiss a dream as childish if it is presented only with emotion and no plan.","zh":"如果夢想只以情緒而沒有計劃呈現，父母可能把它視為幼稚而否定。"},{"en":"Evidence and experience make it harder for people to dismiss your dream as childish.","zh":"證據和經驗令別人更難把你的夢想視為幼稚而否定。"},{"en":"This phrase shows the fear of not being taken seriously.","zh":"這個短語顯示人害怕不被認真看待。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"one piece of research","meaning":"一項資料搜集","examples":[{"en":"Start with one conversation, one piece of research, and one practical experience.","zh":"從一次對話、一項資料搜集和一次實際經驗開始。"},{"en":"One piece of research means one useful item of information found through reading, asking, or checking.","zh":"一項資料搜集，是指透過閱讀、詢問或查證找到的一項有用資訊。"},{"en":"A student may begin with one piece of research about veterinary course requirements.","zh":"學生可以從一項關於獸醫課程入學要求的資料搜集開始。"},{"en":"One piece of research can make a dream clearer and less emotional.","zh":"一項資料搜集可以令夢想更清楚，也沒那麼情緒化。"},{"en":"This phrase encourages a small but concrete first step.","zh":"這個短語鼓勵小而具體的第一步。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"practical experience","meaning":"實際經驗","examples":[{"en":"You should begin with one practical experience.","zh":"你應從一次實際經驗開始。"},{"en":"Practical experience is real experience gained by doing something, not just thinking or reading about it.","zh":"實際經驗是透過做某事而得到的真實經驗，而不只是思考或閱讀。"},{"en":"Helping at a pet adoption event gives practical experience with animals and people.","zh":"在寵物領養活動中幫忙，能提供與動物和人相處的實際經驗。"},{"en":"Practical experience helps students discover what a career feels like in real life.","zh":"實際經驗幫助學生發現一份職業在現實中感覺如何。"},{"en":"This phrase shows that action can teach what imagination cannot.","zh":"這個短語顯示行動可以教會想像無法教的事情。"}],"source":"2018 Q4.pdf","sourcePage":12},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"Little by little, your dream will grow stronger or become clearer.","zh":"一點一點地，你的夢想會變得更堅定或更清晰。"},{"en":"Little by little means slowly, step by step, over time.","zh":"一點一點地，是指隨時間慢慢地、一步一步地。"},{"en":"Little by little, a nervous student becomes more confident through practice.","zh":"一點一點地，緊張的學生透過練習變得更有信心。"},{"en":"Big dreams often become realistic little by little, not all at once.","zh":"大夢想通常是一點一點地變得實際，而不是一次過完成。"},{"en":"This phrase gives patience and hope during a long process.","zh":"這個短語在漫長過程中帶來耐性和希望。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"grow stronger","meaning":"變得更堅定","examples":[{"en":"Your dream may grow stronger with experience.","zh":"你的夢想可能隨着經驗變得更堅定。"},{"en":"To grow stronger means to become more powerful, certain, or steady over time.","zh":"變得更堅定，是指隨時間變得更有力量、更確定或更穩定。"},{"en":"A student’s interest in veterinary work may grow stronger after volunteering with animals.","zh":"學生在與動物做義工後，對獸醫工作的興趣可能變得更堅定。"},{"en":"Dreams grow stronger when real experience confirms that the work still matters.","zh":"當真實經驗證明這份工作仍然重要時，夢想會變得更堅定。"},{"en":"This phrase shows development through time and action.","zh":"這個短語顯示透過時間和行動而來的發展。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"become clearer in a different shape","meaning":"以另一種形式變得更清晰","examples":[{"en":"Your dream may become clearer in a different shape.","zh":"你的夢想可能以另一種形式變得更清晰。"},{"en":"Become clearer in a different shape means the original hope may change form while keeping its deeper purpose.","zh":"以另一種形式變得更清晰，是指原本的希望可能改變形式，但保留更深層目的。"},{"en":"A dream of becoming a vet may become clearer as animal welfare work after real experience.","zh":"成為獸醫的夢想在真實經驗後，可能以動物福利工作的形式變得更清晰。"},{"en":"This change does not mean losing the dream; it may mean understanding it better.","zh":"這種改變不代表失去夢想，而可能代表更好地理解它。"},{"en":"The phrase shows that a dream can mature into a new but related direction.","zh":"這個短語顯示夢想可以成熟為新的相關方向。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"either way","meaning":"無論如何","examples":[{"en":"Either way, you will not be lost.","zh":"無論如何，你都不會迷失。"},{"en":"Either way means whichever of the two possibilities happens.","zh":"無論如何，是指兩種可能性中不論哪一種發生。"},{"en":"You may become a vet or choose another animal-related path; either way, the experience will teach you something.","zh":"你可能成為獸醫，也可能選擇另一條與動物有關的道路；無論如何，經驗都會教你一些東西。"},{"en":"This phrase offers comfort when the future has more than one possible result.","zh":"當未來有不只一個可能結果時，這個短語帶來安慰。"},{"en":"It shows that both outcomes can still lead to growth.","zh":"它顯示兩種結果都仍可帶來成長。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"build a future","meaning":"建立未來","examples":[{"en":"You are learning how to build a future.","zh":"你正在學習如何建立未來。"},{"en":"To build a future means to create a life direction through choices, effort, and planning.","zh":"建立未來是指透過選擇、努力和計劃創造人生方向。"},{"en":"Students build a future by studying, gaining experience, and learning from mistakes.","zh":"學生透過學習、累積經驗和從錯誤中學習來建立未來。"},{"en":"Building a future takes time because identity and goals develop slowly.","zh":"建立未來需要時間，因為身份和目標會慢慢發展。"},{"en":"This phrase makes the student’s struggle sound active and hopeful.","zh":"這個短語令學生的掙扎聽起來主動而有希望。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"truly belongs to","meaning":"真正屬於……","examples":[{"en":"You can build a future that truly belongs to you.","zh":"你可以建立一個真正屬於你的未來。"},{"en":"Truly belongs to means genuinely fits someone’s values, choices, and identity.","zh":"真正屬於，是指真正符合某人的價值、選擇和身份。"},{"en":"A career truly belongs to a student when it reflects both passion and responsibility.","zh":"當一份職業反映學生的熱情和責任時，它就真正屬於那位學生。"},{"en":"A future that truly belongs to you is not simply copied from parents or friends.","zh":"真正屬於你的未來，不只是複製父母或朋友的選擇。"},{"en":"This phrase values personal ownership and thoughtful choice.","zh":"這個短語重視個人擁有感和有思想的選擇。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"your confident self","meaning":"自信的自己","examples":[{"en":"You can build a future that belongs to your confident self.","zh":"你可以建立一個屬於自信的自己的未來。"},{"en":"Your confident self means the version of you that feels stronger, clearer, and more ready.","zh":"自信的自己，是指那個更堅強、更清楚和更準備好的你。"},{"en":"A student meets their confident self when they can explain a dream calmly with evidence.","zh":"當學生能用證據冷靜解釋夢想時，就遇見了自信的自己。"},{"en":"Building toward your confident self takes practice, courage, and patience.","zh":"走向自信的自己需要練習、勇氣和耐性。"},{"en":"This phrase encourages the reader to grow into a braver version of themselves.","zh":"這個短語鼓勵讀者成長為更勇敢的自己。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"warmly","meaning":"溫暖地；祝好","examples":[{"en":"Warmly, Teen Advice Column.","zh":"祝好，Teen 諮詢專欄。"},{"en":"Warmly is a friendly closing used at the end of a letter or message.","zh":"Warmly 是信件或訊息結尾使用的友善結語。"},{"en":"An advice writer may end with “Warmly” to sound kind and supportive.","zh":"建議專欄作者可能用 Warmly 作結，令語氣顯得親切和支持。"},{"en":"This closing is softer and more personal than a very formal ending.","zh":"這個結語比非常正式的結尾更柔和和個人化。"},{"en":"It helps the letter finish with care rather than distance.","zh":"它幫助信件以關懷而不是距離感結束。"}],"source":"2018 Q4.pdf","sourcePage":13},{"front":"advice column","meaning":"諮詢專欄","examples":[{"en":"The reply comes from the Teen Advice Column.","zh":"這封回覆來自 Teen 諮詢專欄。"},{"en":"An advice column is a regular section where readers send problems and receive suggestions.","zh":"諮詢專欄是讀者寄出問題並收到建議的定期欄目。"},{"en":"A teen advice column may answer questions about family, school, friendships, and future plans.","zh":"青少年諮詢專欄可能回答關於家庭、學校、友誼和未來計劃的問題。"},{"en":"Advice columns help readers feel less alone because other people may face similar problems.","zh":"諮詢專欄幫助讀者感到不那麼孤單，因為其他人可能面對相似問題。"},{"en":"This phrase describes both the source of the reply and the kind of writing.","zh":"這個短語同時描述回覆來源和寫作種類。"}],"source":"2018 Q4.pdf","sourcePage":13}],"dse/writing/part-b/2018/Q5":[{"front":"abolish the rank","meaning":"廢除排名","examples":[{"en":"The speech argues that schools should abolish the rank but preserve the standard.","zh":"這篇演講主張學校應廢除排名，但保留標準。"},{"en":"To abolish the rank means to stop using class position as an official measure.","zh":"廢除排名意思是停止把班內名次用作正式衡量方法。"},{"en":"A school may abolish the rank if it wants students to focus on progress instead of comparison.","zh":"如果學校希望學生專注於進步而不是比較，便可能廢除排名。"},{"en":"Abolishing the rank does not mean ignoring marks or academic effort.","zh":"廢除排名並不等於忽視分數或學業努力。"},{"en":"This phrase suggests removing a harmful system while keeping useful standards.","zh":"這個片語表示移除有害制度，同時保留有用標準。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"preserve the standard","meaning":"保留標準","examples":[{"en":"Schools can abolish class ranking while preserving academic standards.","zh":"學校可以廢除班內排名，同時保留學術標準。"},{"en":"To preserve the standard means to keep the level of quality or achievement high.","zh":"保留標準意思是維持高水平的質素或成就要求。"},{"en":"A teacher can preserve the standard by using clear marking criteria without ranking students.","zh":"老師可以透過使用清晰評分準則而不排名學生來保留標準。"},{"en":"If schools give detailed feedback, they can preserve standards and reduce unhealthy pressure.","zh":"如果學校提供詳細回饋，便可以保留標準並減少不健康壓力。"},{"en":"Preserving the standard is different from preserving the ranking system.","zh":"保留標準不同於保留排名制度。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"Chairperson, adjudicators and fellow students","meaning":"主席、評判及各位同學","examples":[{"en":"The speaker begins by addressing the Chairperson, adjudicators and fellow students.","zh":"演講者一開始稱呼主席、評判及各位同學。"},{"en":"“Chairperson, adjudicators and fellow students” is a formal opening used in a debate speech.","zh":"“Chairperson, adjudicators and fellow students” 是辯論演講中的正式開首語。"},{"en":"A debater uses this greeting to show respect to the judge, audience, and other speakers.","zh":"辯論員使用這個稱呼，以向評判、觀眾和其他講者表示尊重。"},{"en":"This opening signals that the speech is formal and organised.","zh":"這個開首語顯示演講是正式而有組織的。"},{"en":"It helps the speaker begin confidently before presenting the argument.","zh":"它幫助演講者在提出論點前自信地開始。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"stand firmly for the motion","meaning":"堅定支持辯題","examples":[{"en":"Today I stand firmly for the motion that class position should be abolished.","zh":"今天，我堅定支持班內排名應被廢除這項辯題。"},{"en":"To stand firmly for the motion means to support the debate topic clearly and strongly.","zh":"堅定支持辯題意思是清楚而有力地支持辯論題目。"},{"en":"A speaker may stand firmly for the motion after giving moral and practical reasons.","zh":"講者提出道德和實際理由後，可能會堅定支持辯題。"},{"en":"This phrase shows confidence instead of hesitation.","zh":"這個片語顯示信心，而不是猶豫。"},{"en":"In a debate, standing firmly for the motion helps the audience understand your side.","zh":"在辯論中，堅定支持辯題有助觀眾理解你的立場。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"the motion that","meaning":"……這項辯題","examples":[{"en":"The speaker supports the motion that class position should be abolished.","zh":"演講者支持班內排名應被廢除這項辯題。"},{"en":"The motion that introduces the exact idea being debated.","zh":"the motion that 用來引出正在辯論的確切主張。"},{"en":"The motion that homework should be reduced would require speakers to argue for or against it.","zh":"「應減少功課」這項辯題會要求講者支持或反對它。"},{"en":"In a debate, the motion tells everyone what question must be discussed.","zh":"在辯論中，辯題告訴所有人必須討論甚麼問題。"},{"en":"This phrase is useful when formally stating a debate topic.","zh":"這個片語適合用於正式說明辯論題目。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"class position","meaning":"班內排名；班名次","examples":[{"en":"The policy of reporting students’ class position should be abolished.","zh":"匯報學生班內排名的政策應被廢除。"},{"en":"Class position means a student’s rank compared with classmates in the same class.","zh":"班內排名指學生與同班同學比較後所得的名次。"},{"en":"A report card may show that a student is fifth in class as their class position.","zh":"成績表可能顯示學生全班第五，這就是班內排名。"},{"en":"Class position tells students where they stand, but not what they need to improve.","zh":"班內排名告訴學生自己處於甚麼位置，卻不說明需要改善甚麼。"},{"en":"This measure can create pressure because it turns learning into comparison.","zh":"這種衡量方式可能造成壓力，因為它把學習變成比較。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"should be abolished","meaning":"應該被廢除","examples":[{"en":"The policy of reporting class position should be abolished.","zh":"匯報班內排名的政策應該被廢除。"},{"en":"Should be abolished means should be officially ended or removed.","zh":"should be abolished 意思是應正式結束或移除。"},{"en":"A harmful school rule should be abolished if it damages students’ confidence.","zh":"如果有害校規損害學生信心，就應該被廢除。"},{"en":"If a practice creates more harm than help, people may argue it should be abolished.","zh":"如果一種做法造成的傷害多於幫助，人們可能主張它應被廢除。"},{"en":"This phrase is strong because it calls for complete removal, not small changes.","zh":"這個片語語氣強烈，因為它要求完全移除，而不是小修小改。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"report cards","meaning":"成績表","examples":[{"en":"Many report cards tell students both their marks and class positions.","zh":"許多成績表告訴學生他們的分數和班內排名。"},{"en":"Report cards are school documents that show students’ academic results and comments.","zh":"成績表是顯示學生學業成績和評語的學校文件。"},{"en":"Parents read report cards to understand how their children are doing at school.","zh":"家長閱讀成績表，以了解孩子在學校的表現。"},{"en":"A useful report card should explain strengths, weaknesses, and next steps.","zh":"有用的成績表應解釋強項、弱項和下一步。"},{"en":"Report cards can encourage students if they focus on progress, not only rank.","zh":"如果成績表著重進步而不只是排名，它可以鼓勵學生。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"Report cards tell students not only their marks, but also their class positions.","zh":"成績表不但告訴學生分數，而且告訴他們班內排名。"},{"en":"Not only…but also… is used to add a second important point.","zh":"not only…but also… 用來加入第二個重要重點。"},{"en":"Good feedback should show not only mistakes, but also ways to improve.","zh":"好回饋不但應指出錯誤，而且應指出改善方法。"},{"en":"Ranking affects not only students’ marks, but also their confidence.","zh":"排名不但影響學生分數，也影響他們的信心。"},{"en":"This structure helps writers show that two things are both important.","zh":"這個句式幫助作者顯示兩件事都重要。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"marks they have obtained","meaning":"他們取得的分數","examples":[{"en":"Report cards show what marks students have obtained.","zh":"成績表顯示學生取得的分數。"},{"en":"Marks they have obtained means the scores students received in tests or assignments.","zh":"marks they have obtained 指學生在測驗或功課中取得的分數。"},{"en":"A student may be proud of the marks she has obtained after hard revision.","zh":"學生努力溫習後，可能會為自己取得的分數感到自豪。"},{"en":"Marks show performance, but they do not fully explain learning habits or effort.","zh":"分數顯示表現，但不能完全解釋學習習慣或努力。"},{"en":"Students need comments as well as marks they have obtained.","zh":"學生除了需要知道取得的分數，也需要評語。"}],"source":"2018 Q5.pdf","sourcePage":1},{"front":"first, tenth or fortieth in class","meaning":"全班第一、第十或第四十","examples":[{"en":"A report card may show whether a student is first, tenth or fortieth in class.","zh":"成績表可能顯示學生是全班第一、第十或第四十。"},{"en":"First, tenth or fortieth in class shows a student’s position compared with classmates.","zh":"全班第一、第十或第四十顯示學生與同班同學比較後的位置。"},{"en":"A student who is tenth in class may still have improved greatly.","zh":"全班第十的學生仍可能已大有進步。"},{"en":"A student who is first in a weak class may still need stronger skills.","zh":"在較弱班別中全班第一的學生仍可能需要更強技能。"},{"en":"These numbers compare students, but they do not explain what each student understands.","zh":"這些數字比較學生，卻沒有解釋每個學生理解了甚麼。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"this practice","meaning":"這種做法","examples":[{"en":"This practice may look efficient.","zh":"這種做法可能看似有效率。"},{"en":"This practice means the action or system just mentioned.","zh":"this practice 指剛才提到的行動或制度。"},{"en":"Giving every student a rank is a practice some schools use to report results.","zh":"給每位學生排名是一些學校用來匯報成績的做法。"},{"en":"This practice may seem simple, but it can hide important learning details.","zh":"這種做法可能看似簡單，但會掩蓋重要學習細節。"},{"en":"When a practice harms students, schools should reconsider it.","zh":"當一種做法傷害學生時，學校應重新考慮。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"look efficient","meaning":"看似有效率","examples":[{"en":"Class ranking may look efficient at first.","zh":"班內排名起初可能看似有效率。"},{"en":"Look efficient means seem quick, organised, and easy to use.","zh":"看似有效率意思是看起來快捷、有組織和容易使用。"},{"en":"A single ranking number may look efficient because parents can understand it quickly.","zh":"單一排名數字可能看似有效率，因為家長可以快速理解。"},{"en":"However, something that looks efficient may still be unfair or incomplete.","zh":"然而，看似有效率的東西仍可能不公平或不完整。"},{"en":"Good education should be accurate, not just efficient-looking.","zh":"好教育應準確，而不只是看起來有效率。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"one number, one hierarchy, one clear message","meaning":"一個數字、一個階級、一個清晰訊息","examples":[{"en":"The system gives one number, one hierarchy and one clear message.","zh":"這個制度給出一個數字、一個階級和一個清晰訊息。"},{"en":"This phrase means ranking reduces students to a simple order from top to bottom.","zh":"這個片語意思是排名把學生簡化成由高至低的次序。"},{"en":"One number may be easy to read, but it cannot explain a student’s learning needs.","zh":"一個數字可能容易閱讀，但不能解釋學生的學習需要。"},{"en":"One hierarchy can make students feel like winners or losers.","zh":"一個階級可能令學生覺得自己是勝利者或失敗者。"},{"en":"The clear message may be powerful, but it may also be misleading.","zh":"清晰訊息可能有力，但也可能具誤導性。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"its very simplicity","meaning":"它本身的簡單","examples":[{"en":"Its very simplicity is exactly the problem.","zh":"它本身的簡單正正是問題所在。"},{"en":"Its very simplicity means the fact that it is so simple is itself important.","zh":"its very simplicity 意思是它如此簡單這一點本身很重要。"},{"en":"A ranking system’s very simplicity makes it easy to use but too narrow to be fair.","zh":"排名制度本身的簡單令它容易使用，卻過於狹窄而不公平。"},{"en":"A simple number can hide effort, progress, and specific weaknesses.","zh":"一個簡單數字可以掩蓋努力、進步和具體弱點。"},{"en":"This phrase emphasises that the problem comes from the system’s simplicity itself.","zh":"這個片語強調問題正來自制度本身的簡單。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"exactly the problem","meaning":"正正是問題所在","examples":[{"en":"The simplicity of class position is exactly the problem.","zh":"班內排名的簡單正正是問題所在。"},{"en":"Exactly the problem means this is the precise thing that creates the difficulty.","zh":"exactly the problem 意思是這正是造成困難的關鍵。"},{"en":"A report that gives only rank may seem clear, but that clarity is exactly the problem.","zh":"只給排名的報告可能看似清楚，但這種清楚正正是問題所在。"},{"en":"When students see only one number, they miss the details they need.","zh":"當學生只看到一個數字，他們便錯過真正需要的細節。"},{"en":"This phrase helps the speaker turn an apparent strength into a weakness.","zh":"這個片語幫助講者把表面優點轉化為缺點。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"in pursuit of","meaning":"為了追求……","examples":[{"en":"In pursuit of better education, schools must reconsider class ranking.","zh":"為了追求更好的教育，學校必須重新考慮班內排名。"},{"en":"In pursuit of means trying to achieve something important.","zh":"in pursuit of 意思是為了努力達成某個重要目標。"},{"en":"In pursuit of better health, people may exercise and sleep earlier.","zh":"為了追求更好的健康，人們可能會運動和早睡。"},{"en":"In pursuit of fair assessment, schools should give more useful feedback.","zh":"為了追求公平評估，學校應提供更有用的回饋。"},{"en":"This phrase gives a serious purpose for taking action.","zh":"這個片語為行動提供嚴肅目的。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"better education","meaning":"更好的教育","examples":[{"en":"Schools should reconsider ranking in pursuit of better education.","zh":"學校應為追求更好的教育而重新考慮排名。"},{"en":"Better education means teaching and assessment that help students truly learn and grow.","zh":"更好的教育指真正幫助學生學習和成長的教學與評估。"},{"en":"Better education gives students feedback, support, and fair chances to improve.","zh":"更好的教育給學生回饋、支援和公平進步機會。"},{"en":"Ranking alone may not create better education because it shows comparison more than learning.","zh":"單靠排名未必能創造更好的教育，因為它顯示比較多於學習。"},{"en":"A school seeking better education should value progress as well as results.","zh":"追求更好教育的學校應重視進步以及成績。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"be forced to consider whether","meaning":"被迫考慮是否","examples":[{"en":"Schools are now forced to consider whether class ranking should continue.","zh":"學校現在被迫考慮班內排名是否應繼續。"},{"en":"Be forced to consider whether means have no choice but to think seriously about a question.","zh":"be forced to consider whether 意思是別無選擇，只能認真思考某問題。"},{"en":"Rising stress levels may force schools to consider whether ranking is still useful.","zh":"壓力水平上升可能迫使學校考慮排名是否仍有用。"},{"en":"Parents’ concerns can force a school to consider whether its assessment is fair.","zh":"家長的關注可以迫使學校考慮其評估是否公平。"},{"en":"This phrase suggests that the issue has become too serious to ignore.","zh":"這個片語表示問題已嚴重到不能忽視。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"ranking children against","meaning":"把孩子與……比較排名","examples":[{"en":"Schools should not keep ranking children against their classmates.","zh":"學校不應繼續把孩子與同班同學比較排名。"},{"en":"Ranking children against others means judging them mainly by comparison with other children.","zh":"把孩子與他人比較排名意思是主要按與其他孩子的比較來評價他們。"},{"en":"Ranking children against classmates may make friendship feel like competition.","zh":"把孩子與同學比較排名可能令友誼變成競爭。"},{"en":"A child can improve a lot while still ranking low against a very strong class.","zh":"孩子即使大有進步，在很強的班中仍可能排名較低。"},{"en":"Education should compare students with learning goals, not only with one another.","zh":"教育應把學生與學習目標比較，而不只是彼此比較。"}],"source":"2018 Q5.pdf","sourcePage":2},{"front":"report learning","meaning":"匯報學習情況","examples":[{"en":"Schools should report learning in a way that helps students improve.","zh":"學校應以幫助學生進步的方式匯報學習情況。"},{"en":"To report learning means to describe what students know, can do, and still need to practise.","zh":"匯報學習情況意思是描述學生知道甚麼、能做甚麼，以及仍需練習甚麼。"},{"en":"A teacher reports learning well when she explains both strengths and next steps.","zh":"老師若能解釋強項和下一步，就是良好地匯報學習情況。"},{"en":"Reporting learning through rank alone gives too little information.","zh":"單靠排名匯報學習情況提供的資訊太少。"},{"en":"Good reports help parents understand learning, not only results.","zh":"好報告幫助家長理解學習，而不只是成績。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"in a way that","meaning":"以……的方式","examples":[{"en":"Schools should report learning in a way that helps students improve.","zh":"學校應以幫助學生進步的方式匯報學習情況。"},{"en":"In a way that means using a method that creates a certain result.","zh":"in a way that 意思是使用會造成某種結果的方法。"},{"en":"Teachers should give comments in a way that students can understand.","zh":"老師應以學生能理解的方式給予評語。"},{"en":"Schools should assess students in a way that encourages effort, not fear.","zh":"學校應以鼓勵努力而不是恐懼的方式評估學生。"},{"en":"This phrase links the method with its purpose.","zh":"這個片語把方法與目的連接起來。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"actually helps students improve","meaning":"真正幫助學生進步","examples":[{"en":"Feedback should actually help students improve.","zh":"回饋應真正幫助學生進步。"},{"en":"Actually helps students improve means truly gives students useful guidance for progress.","zh":"actually helps students improve 意思是真正給學生有用指引，使他們進步。"},{"en":"A comment like “use stronger evidence” actually helps students improve more than a rank.","zh":"「使用更有力證據」這類評語比排名更能真正幫助學生進步。"},{"en":"Feedback that only says “poor” may not actually help students improve.","zh":"只寫「差」的回饋未必真正幫助學生進步。"},{"en":"Useful feedback should show students what to do next.","zh":"有用回饋應告訴學生下一步該做甚麼。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"our stance is clear","meaning":"我們的立場清楚","examples":[{"en":"Our stance is clear: class position should go.","zh":"我們的立場清楚：班內排名應該取消。"},{"en":"Our stance is clear means our position or opinion is easy to understand.","zh":"our stance is clear 意思是我們的立場或意見容易理解。"},{"en":"In a debate, a clear stance helps listeners follow the argument.","zh":"在辯論中，清楚立場幫助聽眾跟上論點。"},{"en":"Our stance is clear when we say ranking harms learning and should end.","zh":"當我們說排名傷害學習並應結束時，我們的立場便很清楚。"},{"en":"This phrase is useful before stating a strong conclusion.","zh":"這個片語適合在提出強烈結論前使用。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"should go","meaning":"應該取消","examples":[{"en":"Class position should go.","zh":"班內排名應該取消。"},{"en":"Should go means should be removed or stopped.","zh":"should go 意思是應被移除或停止。"},{"en":"A school rule that creates shame instead of learning should go.","zh":"造成羞辱而不是學習的校規應該取消。"},{"en":"If class position harms confidence, it should go from report cards.","zh":"如果班內排名損害信心，它就應從成績表中取消。"},{"en":"This phrase is short and forceful, suitable for debate speeches.","zh":"這個片語簡短有力，適合辯論演講。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"distort learning","meaning":"扭曲學習","examples":[{"en":"Class position can distort learning.","zh":"班內排名可能扭曲學習。"},{"en":"To distort learning means to change the purpose of learning in a harmful or misleading way.","zh":"扭曲學習意思是以有害或誤導的方式改變學習目的。"},{"en":"Ranking distorts learning when students study only to beat others.","zh":"當學生只為擊敗他人而讀書時，排名便扭曲了學習。"},{"en":"Fear of losing rank can distort learning by discouraging risk-taking.","zh":"害怕失去排名可能透過阻止學生冒險而扭曲學習。"},{"en":"Learning is distorted when marks matter more than understanding.","zh":"當分數比理解更重要時，學習便被扭曲。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"damage students’ confidence","meaning":"損害學生信心","examples":[{"en":"Class position can damage students’ confidence.","zh":"班內排名可能損害學生信心。"},{"en":"To damage students’ confidence means to make students believe less in their own ability.","zh":"損害學生信心意思是令學生較不相信自己的能力。"},{"en":"A low rank may damage a hardworking student’s confidence.","zh":"低排名可能損害努力學生的信心。"},{"en":"If students only see failure on a report card, their confidence may fall.","zh":"如果學生在成績表上只看到失敗，他們的信心可能下降。"},{"en":"Schools should give feedback that builds confidence through clear next steps.","zh":"學校應透過清晰下一步提供能建立信心的回饋。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"be replaced by","meaning":"被……取代","examples":[{"en":"Class position can be replaced by fairer feedback.","zh":"班內排名可以被更公平的回饋取代。"},{"en":"Be replaced by means be removed and have something else used instead.","zh":"be replaced by 意思是被移除，並由其他東西代替。"},{"en":"A rank can be replaced by comments about strengths and weaknesses.","zh":"排名可以被關於強項和弱項的評語取代。"},{"en":"If a system is harmful, it should be replaced by a more useful one.","zh":"如果制度有害，它應被更有用的制度取代。"},{"en":"This phrase shows a solution, not only criticism.","zh":"這個片語顯示解決方案，而不只是批評。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"fairer, richer feedback","meaning":"更公平、更豐富的回饋","examples":[{"en":"Students need fairer, richer feedback.","zh":"學生需要更公平、更豐富的回饋。"},{"en":"Fairer, richer feedback means comments that are more just, detailed, and helpful.","zh":"更公平、更豐富的回饋指更公正、詳細和有幫助的評語。"},{"en":"A teacher gives richer feedback by explaining why an answer is weak.","zh":"老師透過解釋答案為何薄弱來提供更豐富回饋。"},{"en":"Fair feedback considers progress as well as final marks.","zh":"公平回饋會考慮進步以及最終分數。"},{"en":"Such feedback helps students know how to improve instead of only where they rank.","zh":"這種回饋幫助學生知道如何改善，而不只是知道自己排第幾。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"our first argument is that","meaning":"我們的第一個論點是","examples":[{"en":"Our first argument is that class position turns education into a narrow race.","zh":"我們的第一個論點是班內排名把教育變成狹隘的競賽。"},{"en":"Our first argument is that introduces the first main reason in a debate or essay.","zh":"our first argument is that 用來引出辯論或文章中的第一個主要理由。"},{"en":"Our first argument is that ranking gives students too little useful information.","zh":"我們的第一個論點是排名給學生太少有用資訊。"},{"en":"This phrase helps organise ideas clearly for the audience.","zh":"這個片語幫助為觀眾清楚組織理念。"},{"en":"A strong first argument should explain both the problem and its effect.","zh":"有力的第一個論點應解釋問題及其影響。"}],"source":"2018 Q5.pdf","sourcePage":3},{"front":"turn education into","meaning":"把教育變成","examples":[{"en":"Class position turns education into a narrow race.","zh":"班內排名把教育變成狹隘的競賽。"},{"en":"To turn education into something means to change its nature or purpose.","zh":"把教育變成某物意思是改變教育的性質或目的。"},{"en":"Too much exam pressure can turn education into memorisation.","zh":"過多考試壓力可以把教育變成背誦。"},{"en":"Ranking turns education into competition when students focus only on beating classmates.","zh":"當學生只專注於擊敗同學，排名便把教育變成競爭。"},{"en":"Education should remain a process of growth, not become a race.","zh":"教育應保持為成長過程，而不是變成競賽。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"a narrow race","meaning":"狹隘的競賽","examples":[{"en":"Class position turns education into a narrow race.","zh":"班內排名把教育變成狹隘的競賽。"},{"en":"A narrow race is a limited competition where people care mainly about who comes first.","zh":"狹隘的競賽是只主要關心誰第一的有限競爭。"},{"en":"Learning becomes a narrow race when students ignore curiosity and only chase marks.","zh":"當學生忽視好奇心，只追求分數時，學習便變成狹隘的競賽。"},{"en":"A narrow race can make classmates see one another as threats.","zh":"狹隘的競賽可以令同學把彼此視為威脅。"},{"en":"Education should be wider than a race for rank.","zh":"教育應比排名競賽更廣闊。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"instead of","meaning":"而不是","examples":[{"en":"Education should be a meaningful process of learning instead of a narrow race.","zh":"教育應是有意義的學習過程，而不是狹隘的競賽。"},{"en":"Instead of is used to show that one thing should replace another.","zh":"instead of 用來表示一件事應取代另一件事。"},{"en":"Students need feedback instead of only a ranking number.","zh":"學生需要回饋，而不是只有排名數字。"},{"en":"Schools should encourage progress instead of fear.","zh":"學校應鼓勵進步，而不是恐懼。"},{"en":"This phrase makes contrast clear and direct.","zh":"這個片語令對比清晰直接。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"a meaningful process of learning","meaning":"有意義的學習過程","examples":[{"en":"Education should be a meaningful process of learning.","zh":"教育應是有意義的學習過程。"},{"en":"A meaningful process of learning helps students understand, practise, make mistakes, and improve.","zh":"有意義的學習過程幫助學生理解、練習、犯錯和進步。"},{"en":"Reading, asking questions, and receiving feedback are parts of a meaningful learning process.","zh":"閱讀、提問和接受回饋都是有意義學習過程的一部分。"},{"en":"Ranking can weaken this process if students care only about position.","zh":"如果學生只關心名次，排名可能削弱這個過程。"},{"en":"Meaningful learning focuses on growth, not only final results.","zh":"有意義的學習著重成長，而不只是最終結果。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"where he stands among","meaning":"在……之中處於甚麼位置","examples":[{"en":"A ranking tells a student where he stands among classmates.","zh":"排名告訴學生他在同學之中處於甚麼位置。"},{"en":"Where he stands among means his position compared with other people in the same group.","zh":"where he stands among 意思是他與同一群體中其他人比較時的位置。"},{"en":"A race result tells a runner where he stands among other runners.","zh":"比賽結果告訴跑手在其他跑手之中處於甚麼位置。"},{"en":"Class position shows where a student stands among classmates, but not why.","zh":"班內排名顯示學生在同學之中處於甚麼位置，但沒有解釋原因。"},{"en":"Knowing where one stands may be useful, but it is not enough for improvement.","zh":"知道自己處於甚麼位置可能有用，但不足以幫助進步。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"has mastered","meaning":"已經掌握","examples":[{"en":"A ranking does not show what a student has mastered.","zh":"排名並不顯示學生已經掌握甚麼。"},{"en":"Has mastered means has learned something well and can use it confidently.","zh":"has mastered 意思是已學好某事，並能有信心地使用。"},{"en":"A student may have mastered fractions even if she is not first in class.","zh":"學生即使不是全班第一，也可能已經掌握分數。"},{"en":"Good feedback tells students which skills they have mastered.","zh":"好回饋會告訴學生他們已經掌握哪些技能。"},{"en":"Knowing what has been mastered helps students build on their strengths.","zh":"知道已掌握甚麼有助學生建立在自己的強項之上。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"has misunderstood","meaning":"誤解了","examples":[{"en":"A ranking does not show what a student has misunderstood.","zh":"排名並不顯示學生誤解了甚麼。"},{"en":"Has misunderstood means has understood something wrongly.","zh":"has misunderstood 意思是錯誤理解了某事。"},{"en":"A student may have misunderstood the question even if his grammar is strong.","zh":"學生即使文法強，也可能誤解了題目。"},{"en":"Teachers need to know what students have misunderstood before helping them improve.","zh":"老師需要知道學生誤解了甚麼，才能幫助他們改善。"},{"en":"Ranking hides misunderstandings because it gives a position, not an explanation.","zh":"排名掩蓋誤解，因為它給出位置，而不是解釋。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"what to do next","meaning":"下一步該做甚麼","examples":[{"en":"Good feedback tells students what to do next.","zh":"好回饋告訴學生下一步該做甚麼。"},{"en":"What to do next means the next action or step a student should take.","zh":"what to do next 意思是學生應採取的下一個行動或步驟。"},{"en":"A teacher may tell a student to add evidence as what to do next.","zh":"老師可能告訴學生加入證據，作為下一步該做的事。"},{"en":"A rank tells students where they are, but not what to do next.","zh":"排名告訴學生他們在哪裡，卻不告訴他們下一步該做甚麼。"},{"en":"Clear next steps turn feedback into improvement.","zh":"清晰下一步把回饋轉化為進步。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"the fundamental logic","meaning":"基本邏輯","examples":[{"en":"The fundamental logic is as follows.","zh":"基本邏輯如下。"},{"en":"The fundamental logic means the basic reasoning behind an argument.","zh":"the fundamental logic 指論點背後的基本推理。"},{"en":"The fundamental logic of ranking is comparison, not personal progress.","zh":"排名的基本邏輯是比較，而不是個人進步。"},{"en":"If the fundamental logic is unfair, the system built on it will also be weak.","zh":"如果基本邏輯不公平，建立在其上的制度也會薄弱。"},{"en":"This phrase prepares listeners for the core explanation.","zh":"這個片語讓聽眾準備聆聽核心解釋。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"is as follows","meaning":"如下","examples":[{"en":"The fundamental logic is as follows: if everyone improves, someone is still last.","zh":"基本邏輯如下：即使每個人都有進步，仍然有人排最後。"},{"en":"Is as follows is used before giving a clear explanation or list.","zh":"is as follows 用於提出清晰解釋或列表之前。"},{"en":"The rule is as follows: students must submit the form before Friday.","zh":"規則如下：學生必須在星期五前提交表格。"},{"en":"In speeches, this phrase signals that the next point will be explained directly.","zh":"在演講中，這個片語表示下一點會被直接解釋。"},{"en":"It helps listeners follow the structure of the argument.","zh":"它幫助聽眾跟上論點結構。"}],"source":"2018 Q5.pdf","sourcePage":4},{"front":"the entire class improves","meaning":"全班都有進步","examples":[{"en":"If the entire class improves, someone must still be last.","zh":"如果全班都有進步，仍然有人必定排最後。"},{"en":"The entire class improves means every student in the class gets better.","zh":"the entire class improves 意思是班中每位學生都變得更好。"},{"en":"The entire class may improve after extra lessons and better feedback.","zh":"經過額外課堂和更好回饋後，全班可能都有進步。"},{"en":"Ranking can hide this improvement because it still places one student at the bottom.","zh":"排名可能掩蓋這種進步，因為它仍把一位學生放在最後。"},{"en":"This example shows why comparison is not the same as progress.","zh":"這個例子顯示比較不等於進步。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"someone must still be last","meaning":"仍然有人必定排最後","examples":[{"en":"Even if the entire class improves, someone must still be last.","zh":"即使全班都有進步，仍然有人必定排最後。"},{"en":"Someone must still be last means ranking always puts one person at the bottom.","zh":"someone must still be last 意思是排名總會把某個人放在最底。"},{"en":"In a race, someone must still be last even if everyone runs faster than before.","zh":"在賽跑中，即使每個人都比以前跑得快，仍然有人必定排最後。"},{"en":"This is unfair as a learning message because the last student may have improved a lot.","zh":"作為學習訊息，這並不公平，因為最後一名也可能大有進步。"},{"en":"The phrase exposes the weakness of judging only by position.","zh":"這個片語揭示只按位置判斷的弱點。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"if a class is weak","meaning":"如果全班水平較弱","examples":[{"en":"If a class is weak, someone may still be first.","zh":"如果全班水平較弱，仍然有人可能排第一。"},{"en":"If a class is weak means if the overall academic level of the group is low.","zh":"if a class is weak 意思是如果整個群體的學術水平較低。"},{"en":"A student may rank first in a weak class but still need stronger writing skills.","zh":"學生可能在較弱班別中排第一，但仍需要更強寫作能力。"},{"en":"Ranking can make weak performance look successful if the comparison group is weaker.","zh":"如果比較群體較弱，排名可能令薄弱表現看起來成功。"},{"en":"This shows that rank alone does not measure real ability.","zh":"這顯示排名本身不能衡量真正能力。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, class position measures comparison more than competence.","zh":"換言之，班內排名衡量比較，多於衡量能力。"},{"en":"In other words is used to explain the same idea more simply or clearly.","zh":"in other words 用來以更簡單或清楚的方式解釋同一想法。"},{"en":"A rank tells who is ahead; in other words, it compares students.","zh":"排名告訴誰在前面；換言之，它在比較學生。"},{"en":"In other words, a low position does not always mean no progress.","zh":"換言之，低名次不一定代表沒有進步。"},{"en":"This phrase helps the speaker restate an important point.","zh":"這個片語幫助講者重新表達重要重點。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"measure comparison","meaning":"衡量比較","examples":[{"en":"Class position measures comparison more than competence.","zh":"班內排名衡量比較，多於衡量能力。"},{"en":"To measure comparison means to judge people by how they perform against others.","zh":"衡量比較意思是根據人們與他人相比的表現來評價。"},{"en":"A race measures comparison because runners are placed from first to last.","zh":"賽跑衡量比較，因為跑手會由第一排到最後。"},{"en":"Class ranking measures comparison, not the exact skills each student has learned.","zh":"班內排名衡量比較，而不是顯示每位學生學會了哪些具體技能。"},{"en":"Education needs measures that show progress, not only comparison.","zh":"教育需要顯示進步的衡量方法，而不只是比較。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"more than competence","meaning":"多於衡量能力","examples":[{"en":"Class position measures comparison more than competence.","zh":"班內排名衡量比較，多於衡量能力。"},{"en":"More than competence means more than real ability or skill.","zh":"more than competence 意思是多於真正能力或技能。"},{"en":"A student’s rank may show class position more than competence in writing.","zh":"學生的排名可能顯示班內位置，多於顯示寫作能力。"},{"en":"If everyone in the class is weak, first place may show comparison more than competence.","zh":"如果全班都較弱，第一名可能顯示比較多於能力。"},{"en":"This phrase helps separate relative position from actual ability.","zh":"這個片語幫助區分相對位置和實際能力。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"worse still","meaning":"更糟的是","examples":[{"en":"Worse still, ranking encourages students to protect marks.","zh":"更糟的是，排名鼓勵學生保住分數。"},{"en":"Worse still means an even more serious problem is being added.","zh":"worse still 意思是再加入一個更嚴重的問題。"},{"en":"Ranking is narrow; worse still, it may damage confidence.","zh":"排名很狹窄；更糟的是，它可能損害信心。"},{"en":"A school rule may waste time; worse still, it may make students afraid to learn.","zh":"校規可能浪費時間；更糟的是，它可能令學生害怕學習。"},{"en":"This phrase helps build a stronger criticism.","zh":"這個片語有助建立更強批評。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"protect marks","meaning":"保住分數","examples":[{"en":"Students may try to protect marks rather than pursue understanding.","zh":"學生可能試圖保住分數，而不是追求理解。"},{"en":"To protect marks means to avoid risks so one’s score will not fall.","zh":"保住分數意思是避免冒險，以免分數下降。"},{"en":"A student may choose an easy topic to protect marks.","zh":"學生可能選擇容易題目來保住分數。"},{"en":"Protecting marks can stop students from trying harder books or original ideas.","zh":"保住分數可能阻止學生嘗試更難的書或原創想法。"},{"en":"Learning suffers when students protect marks more than seek understanding.","zh":"當學生更重視保住分數而不是追求理解時，學習便受損。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"rather than pursue understanding","meaning":"而不是追求理解","examples":[{"en":"Students may protect marks rather than pursue understanding.","zh":"學生可能保住分數，而不是追求理解。"},{"en":"Rather than pursue understanding means instead of trying to truly learn the meaning.","zh":"rather than pursue understanding 意思是沒有努力真正理解意思。"},{"en":"A student may memorise answers rather than pursue understanding of the topic.","zh":"學生可能背誦答案，而不是追求對題目的理解。"},{"en":"Ranking may push students to choose safety rather than pursue understanding.","zh":"排名可能推動學生選擇安全做法，而不是追求理解。"},{"en":"This phrase contrasts shallow score-chasing with deeper learning.","zh":"這個片語把表面的追分與更深層學習作對比。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a capable Form Four student, for example.","zh":"以一位有能力的中四學生為例。"},{"en":"Take…for example is used before giving a specific case to explain an argument.","zh":"take…for example 用於提出具體個案來解釋論點之前。"},{"en":"Take a shy student, for example: ranking may make him speak even less.","zh":"以一位害羞學生為例：排名可能令他更少發言。"},{"en":"This phrase helps listeners understand an abstract point through a real situation.","zh":"這個片語幫助聽眾透過真實情況理解抽象重點。"},{"en":"Examples make debate arguments easier to believe and remember.","zh":"例子令辯論論點更容易相信和記住。"}],"source":"2018 Q5.pdf","sourcePage":5},{"front":"a capable Form Four student","meaning":"有能力的中四學生","examples":[{"en":"A capable Form Four student may avoid risks if every mark affects her rank.","zh":"如果每一分都影響排名，有能力的中四學生可能會避免冒險。"},{"en":"A capable Form Four student is a Secondary Four student with strong ability.","zh":"有能力的中四學生是具有較強能力的中四學生。"},{"en":"Such a student may still feel pressure if class position matters too much.","zh":"如果班內排名太重要，這樣的學生仍可能感到壓力。"},{"en":"A capable student can become cautious when rankings punish mistakes.","zh":"當排名懲罰錯誤時，有能力的學生可能變得保守。"},{"en":"Ability should be developed through challenge, not limited by fear of losing rank.","zh":"能力應透過挑戰發展，而不是被失去排名的恐懼限制。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"affect her rank","meaning":"影響她的排名","examples":[{"en":"Every mark may affect her rank.","zh":"每一分都可能影響她的排名。"},{"en":"To affect her rank means to change her position compared with classmates.","zh":"affect her rank 意思是改變她與同班同學比較後的位置。"},{"en":"One careless mistake may affect her rank if the class scores are close.","zh":"如果全班分數接近，一個粗心錯誤可能影響她的排名。"},{"en":"Fear that every mark may affect her rank can make a student avoid creative risks.","zh":"害怕每一分都影響排名，可能令學生避免創意冒險。"},{"en":"This phrase shows how ranking creates pressure around small differences.","zh":"這個片語顯示排名如何圍繞細微差異製造壓力。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"safe essay structures","meaning":"穩妥的作文結構","examples":[{"en":"She may choose safe essay structures to protect her rank.","zh":"她可能選擇穩妥的作文結構來保住排名。"},{"en":"Safe essay structures are familiar writing patterns that are unlikely to lose marks.","zh":"穩妥的作文結構是熟悉而不太容易失分的寫作模式。"},{"en":"A student may use the same introduction every time because it feels safe.","zh":"學生可能每次都使用同一種開首，因為它感覺穩妥。"},{"en":"Safe structures can help beginners, but overusing them may limit original thinking.","zh":"穩妥結構可以幫助初學者，但過度使用可能限制原創思考。"},{"en":"Ranking may make students choose safety over developing their own style.","zh":"排名可能令學生選擇安全，而不是發展個人風格。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"challenging books","meaning":"有挑戰性的書籍","examples":[{"en":"She may avoid challenging books.","zh":"她可能避免閱讀有挑戰性的書籍。"},{"en":"Challenging books are books that are difficult but can help readers grow.","zh":"有挑戰性的書籍是困難但能幫助讀者成長的書。"},{"en":"A challenging book may contain complex ideas, unfamiliar vocabulary, or deeper themes.","zh":"有挑戰性的書籍可能包含複雜理念、不熟悉詞彙或更深主題。"},{"en":"Students may avoid challenging books if they fear making mistakes in tests.","zh":"如果學生害怕在測驗中犯錯，可能會避開有挑戰性的書籍。"},{"en":"Reading challenging books can build stronger thinking over time.","zh":"閱讀有挑戰性的書籍能隨時間建立更強思考能力。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"memorise model answers","meaning":"背誦範文答案","examples":[{"en":"Students may memorise model answers instead of developing their own voices.","zh":"學生可能背誦範文答案，而不是發展自己的聲音。"},{"en":"To memorise model answers means to learn sample answers by heart and repeat them.","zh":"背誦範文答案意思是把示範答案記住並重複使用。"},{"en":"Some students memorise model answers because they think it is safer for exams.","zh":"有些學生背誦範文答案，因為他們認為這對考試較安全。"},{"en":"This habit may improve short-term marks but weaken independent thinking.","zh":"這個習慣可能改善短期分數，但削弱獨立思考。"},{"en":"Good education should teach students how to think, not only what to copy.","zh":"好教育應教學生如何思考，而不只是複製甚麼。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"develop her own voice","meaning":"發展自己的聲音；形成個人風格","examples":[{"en":"A student should develop her own voice in writing.","zh":"學生應在寫作中發展自己的聲音。"},{"en":"To develop her own voice means to build a personal style and way of expressing ideas.","zh":"發展自己的聲音意思是建立個人風格和表達想法的方式。"},{"en":"A writer develops her own voice by reading widely and writing honestly.","zh":"作者透過廣泛閱讀和真誠寫作來發展自己的聲音。"},{"en":"Overusing model answers may stop a student from developing her own voice.","zh":"過度使用範文答案可能阻止學生發展自己的聲音。"},{"en":"Students need room to take risks if they are to develop original writing.","zh":"如果學生要發展原創寫作，就需要冒險空間。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"a weaker student","meaning":"較弱的學生","examples":[{"en":"A weaker student may conclude that effort is pointless.","zh":"較弱的學生可能得出努力沒有意義的結論。"},{"en":"A weaker student is a student who currently finds the subject more difficult than others.","zh":"較弱的學生是目前覺得某科比其他人更困難的學生。"},{"en":"A weaker student may still be hardworking and capable of progress.","zh":"較弱的學生仍可能勤力，也有能力進步。"},{"en":"Ranking can discourage a weaker student if improvement is hidden by comparison.","zh":"如果進步被比較掩蓋，排名可能令較弱學生灰心。"},{"en":"Supportive feedback helps weaker students see what they can do next.","zh":"支持性回饋幫助較弱學生看見下一步可以做甚麼。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"A weaker student, meanwhile, may feel discouraged by a low class position.","zh":"與此同時，較弱的學生可能因低班名次而感到氣餒。"},{"en":"Meanwhile is used to show what is happening at the same time in another situation.","zh":"meanwhile 用來顯示另一情況同時正在發生。"},{"en":"Strong students may protect their marks; meanwhile, weaker students may lose hope.","zh":"成績強的學生可能保住分數；與此同時，較弱學生可能失去希望。"},{"en":"This word helps compare two different effects of the same system.","zh":"這個字幫助比較同一制度的兩種不同影響。"},{"en":"It is useful when showing that one policy can harm different students in different ways.","zh":"當展示一項政策如何以不同方式傷害不同學生時，它很有用。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"conclude that","meaning":"得出……的結論","examples":[{"en":"The student may conclude that effort is pointless.","zh":"學生可能得出努力沒有意義的結論。"},{"en":"To conclude that means to decide something after thinking about evidence or experience.","zh":"conclude that 意思是在思考證據或經驗後作出判斷。"},{"en":"A student may conclude that she is weak if she sees only a low rank.","zh":"如果學生只看到低排名，可能會得出自己很弱的結論。"},{"en":"If feedback shows progress, students are less likely to conclude that effort is useless.","zh":"如果回饋顯示進步，學生較不會得出努力無用的結論。"},{"en":"This phrase often introduces a belief formed from experience.","zh":"這個片語常用來引出由經驗形成的信念。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"effort is pointless","meaning":"努力是沒有意義的","examples":[{"en":"A low ranking may make a student think effort is pointless.","zh":"低排名可能令學生覺得努力是沒有意義的。"},{"en":"Effort is pointless means trying hard seems useless and unable to change the result.","zh":"effort is pointless 意思是努力似乎無用，不能改變結果。"},{"en":"A student may feel effort is pointless if hard work never appears on the report card.","zh":"如果努力從不出現在成績表上，學生可能覺得努力沒有意義。"},{"en":"Ranking can create this feeling when progress is not recognised.","zh":"當進步不被承認時，排名可能製造這種感覺。"},{"en":"Good feedback shows students that effort can lead to improvement.","zh":"好回饋向學生顯示努力可以帶來進步。"}],"source":"2018 Q5.pdf","sourcePage":6},{"front":"even though","meaning":"即使","examples":[{"en":"A student may feel hopeless even though he has improved greatly.","zh":"即使學生已大有進步，他仍可能感到絕望。"},{"en":"Even though is used to show contrast between two facts.","zh":"even though 用來顯示兩個事實之間的對比。"},{"en":"Even though a student works hard, his rank may stay low in a strong class.","zh":"即使學生努力，在強班中排名仍可能較低。"},{"en":"Even though ranking seems clear, it may hide important progress.","zh":"即使排名看似清楚，它仍可能掩蓋重要進步。"},{"en":"This phrase helps show that two things can be true at the same time.","zh":"這個片語幫助顯示兩件事可以同時成立。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"improved greatly","meaning":"大有進步","examples":[{"en":"He has improved greatly, although his class position remains low.","zh":"他已大有進步，雖然班內排名仍然較低。"},{"en":"Improved greatly means become much better than before.","zh":"improved greatly 意思是比以前好很多。"},{"en":"A student who once failed may have improved greatly after months of practice.","zh":"曾經不合格的學生經過數月練習後可能大有進步。"},{"en":"Ranking may not show that a student has improved greatly.","zh":"排名未必顯示學生已大有進步。"},{"en":"Reports should recognise great improvement because it motivates further effort.","zh":"報告應承認顯著進步，因為這會鼓勵繼續努力。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"what matters is not whether…but whether…","meaning":"重要的不是是否……而是是否……","examples":[{"en":"What matters is not whether a child is above another child, but whether the child is moving forward.","zh":"重要的不是孩子是否排在另一個孩子之上，而是孩子是否正在進步。"},{"en":"This structure shows that one question is less important than the real question.","zh":"這個句式顯示一個問題較不重要，而真正問題是另一個。"},{"en":"What matters is not whether students are first, but whether they understand more than before.","zh":"重要的不是學生是否第一，而是他們是否比以前更理解。"},{"en":"It shifts attention from comparison to growth.","zh":"它把注意力由比較轉向成長。"},{"en":"This phrase is useful for correcting the focus of a debate.","zh":"這個片語適合用來修正辯論焦點。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"above or below another child","meaning":"排在另一個孩子之上或之下","examples":[{"en":"The issue is not whether a child is above or below another child.","zh":"問題不在於孩子是否排在另一個孩子之上或之下。"},{"en":"Above or below another child means ranked higher or lower than another student.","zh":"above or below another child 意思是排名高於或低於另一位學生。"},{"en":"A child below another child in rank may still be improving quickly.","zh":"排在另一個孩子之下的學生仍可能正在快速進步。"},{"en":"A child above another child may still have weaknesses that need support.","zh":"排在另一個孩子之上的學生仍可能有需要支援的弱點。"},{"en":"Education should not reduce children to being above or below one another.","zh":"教育不應把孩子簡化為排在彼此之上或之下。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"moving forward","meaning":"正在進步","examples":[{"en":"What matters is whether a student is actually moving forward.","zh":"重要的是學生是否真正正在進步。"},{"en":"Moving forward means making progress, even if the progress is gradual.","zh":"moving forward 意思是正在取得進步，即使進步是逐步的。"},{"en":"A student is moving forward when she makes fewer grammar mistakes than before.","zh":"如果學生比以前少犯文法錯誤，她就是正在進步。"},{"en":"Ranking may hide whether a student is moving forward.","zh":"排名可能掩蓋學生是否正在進步。"},{"en":"Teachers should help students see the next step so they keep moving forward.","zh":"老師應幫助學生看見下一步，讓他們繼續進步。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"hide progress behind comparison","meaning":"讓比較掩蓋進步","examples":[{"en":"A ranking system hides progress behind comparison.","zh":"排名制度讓比較掩蓋進步。"},{"en":"To hide progress behind comparison means to make improvement less visible because rank is shown first.","zh":"讓比較掩蓋進步意思是因為先顯示排名而令改善變得不明顯。"},{"en":"A student may improve by ten marks but still look weak because others also improved.","zh":"學生可能進步十分，但因其他人也進步而仍看似薄弱。"},{"en":"Ranking hides progress when it reports position without explaining growth.","zh":"當排名只匯報位置而不解釋成長時，它便掩蓋進步。"},{"en":"This phrase criticises systems that value comparison over development.","zh":"這個片語批評重比較多於重發展的制度。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"educationally unsound","meaning":"在教育上站不住腳","examples":[{"en":"A system that hides progress behind comparison is educationally unsound.","zh":"讓比較掩蓋進步的制度在教育上站不住腳。"},{"en":"Educationally unsound means not suitable or defensible from an educational point of view.","zh":"educationally unsound 意思是從教育角度看不合適或不能成立。"},{"en":"A test that rewards memorisation but ignores understanding may be educationally unsound.","zh":"只獎勵背誦而忽視理解的測驗可能在教育上站不住腳。"},{"en":"Ranking is educationally unsound if it discourages students from learning deeply.","zh":"如果排名阻止學生深入學習，它就在教育上站不住腳。"},{"en":"This phrase gives a strong professional judgement about a school practice.","zh":"這個片語對學校做法作出強烈專業判斷。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"our second argument is that","meaning":"我們的第二個論點是","examples":[{"en":"Our second argument is that class position harms students’ wellbeing.","zh":"我們的第二個論點是班內排名傷害學生的身心健康。"},{"en":"Our second argument is that introduces the next main reason in a debate.","zh":"our second argument is that 用來引出辯論中的下一個主要理由。"},{"en":"Our second argument is that ranking damages confidence and relationships.","zh":"我們的第二個論點是排名損害信心和人際關係。"},{"en":"This phrase helps the audience follow the order of the speech.","zh":"這個片語幫助觀眾跟上演講次序。"},{"en":"A second argument should add a new reason, not repeat the first one.","zh":"第二個論點應加入新理由，而不是重複第一點。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"emotional wellbeing","meaning":"情緒健康","examples":[{"en":"Reporting class position harms students’ emotional wellbeing.","zh":"匯報班內排名會傷害學生的情緒健康。"},{"en":"Emotional wellbeing means a person’s mental and emotional health, including confidence and calmness.","zh":"情緒健康指一個人的心理和情感狀態，包括信心和平靜。"},{"en":"Constant comparison can harm emotional wellbeing by creating shame or anxiety.","zh":"持續比較可能透過造成羞愧或焦慮來傷害情緒健康。"},{"en":"A student’s emotional wellbeing improves when effort and progress are recognised.","zh":"當努力和進步被承認時，學生的情緒健康會改善。"},{"en":"Schools should assess learning without damaging students’ emotional wellbeing.","zh":"學校應評估學習，而不傷害學生情緒健康。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"relationships","meaning":"人際關係","examples":[{"en":"Class ranking can harm students’ relationships.","zh":"班內排名可能傷害學生的人際關係。"},{"en":"Relationships are the connections people have with classmates, friends, teachers, or family.","zh":"人際關係是人們與同學、朋友、老師或家人的連繫。"},{"en":"Ranking may harm relationships if friends begin to see one another as rivals.","zh":"如果朋友開始把彼此視為競爭對手，排名可能傷害人際關係。"},{"en":"Healthy relationships help students ask for help and learn together.","zh":"健康的人際關係幫助學生求助和一起學習。"},{"en":"Schools should avoid assessment practices that damage trust between students.","zh":"學校應避免破壞學生之間信任的評估做法。"}],"source":"2018 Q5.pdf","sourcePage":7},{"front":"some argue","meaning":"有些人認為","examples":[{"en":"Some argue that class position is only a number.","zh":"有些人認為班內排名只是一個數字。"},{"en":"Some argue means some people claim or believe a certain point.","zh":"some argue 意思是有些人聲稱或相信某一點。"},{"en":"Some argue that competition motivates students to work harder.","zh":"有些人認為競爭會激勵學生更努力。"},{"en":"This phrase is useful when introducing the opposing side.","zh":"這個片語適合用來引入反方觀點。"},{"en":"A strong speaker then explains why that argument is incomplete or wrong.","zh":"有力的講者之後會解釋為何該論點不完整或錯誤。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"with all due respect","meaning":"恕我直言","examples":[{"en":"With all due respect, class position is not only a number.","zh":"恕我直言，班內排名不只是一個數字。"},{"en":"With all due respect is a polite phrase used before disagreeing strongly.","zh":"with all due respect 是在強烈不同意前使用的禮貌說法。"},{"en":"With all due respect, a rank can affect a child’s confidence deeply.","zh":"恕我直言，排名可以深深影響孩子的信心。"},{"en":"This phrase keeps the tone respectful while challenging another view.","zh":"這個片語在挑戰另一觀點時仍保持尊重語氣。"},{"en":"It is useful in debate because disagreement should still sound controlled.","zh":"它在辯論中很有用，因為不同意也應聽起來克制。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"in the eyes of","meaning":"在……眼中","examples":[{"en":"In the eyes of a twelve-year-old, that number can become a label.","zh":"在一個十二歲孩子眼中，那個數字可以變成標籤。"},{"en":"In the eyes of means from the viewpoint or feeling of a particular person.","zh":"in the eyes of 意思是從某人的角度或感受來看。"},{"en":"In the eyes of a child, a low rank may feel like proof of failure.","zh":"在孩子眼中，低排名可能感覺像失敗的證明。"},{"en":"In the eyes of parents, detailed feedback may be more useful than a number.","zh":"在家長眼中，詳細回饋可能比一個數字更有用。"},{"en":"This phrase helps the speaker show how someone experiences a situation.","zh":"這個片語幫助講者展示某人如何經歷某情況。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"become a label","meaning":"變成標籤","examples":[{"en":"A ranking number can become a label.","zh":"排名數字可以變成標籤。"},{"en":"To become a label means to turn into a fixed identity that people attach to someone.","zh":"become a label 意思是變成加在人身上的固定身分。"},{"en":"A child ranked last may feel the number has become a label of weakness.","zh":"排最後的孩子可能覺得那個數字變成了薄弱的標籤。"},{"en":"Labels are harmful when they make students forget they can improve.","zh":"當標籤令學生忘記自己可以進步時，便很有害。"},{"en":"Education should describe learning, not label children.","zh":"教育應描述學習，而不是標籤孩子。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"turn a report card into a trial","meaning":"把成績表變成審判","examples":[{"en":"At home, class position can turn a report card into a trial.","zh":"在家中，班內排名可以把成績表變成審判。"},{"en":"To turn a report card into a trial means to make receiving results feel like being judged harshly.","zh":"把成績表變成審判意思是令收取成績感覺像被嚴厲審判。"},{"en":"A child may fear going home if the report card becomes a trial.","zh":"如果成績表變成審判，孩子可能害怕回家。"},{"en":"Ranking can make family discussion focus on blame instead of improvement.","zh":"排名可能令家庭討論集中於責備，而不是改善。"},{"en":"Report cards should start helpful conversations, not emotional trials.","zh":"成績表應開始有幫助的對話，而不是情緒上的審判。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"divide friends into","meaning":"把朋友分成","examples":[{"en":"In class, ranking can divide friends into winners and losers.","zh":"在班中，排名可以把朋友分成勝利者和失敗者。"},{"en":"To divide friends into groups means to separate them by status or result.","zh":"divide friends into groups 意思是按地位或結果把朋友分開。"},{"en":"A ranking list can divide friends into top students and weak students.","zh":"排名表可以把朋友分成尖子和弱生。"},{"en":"This division may make classmates less willing to help one another.","zh":"這種分隔可能令同學較不願意互相幫助。"},{"en":"Schools should build cooperation instead of dividing friends by rank.","zh":"學校應建立合作，而不是按排名把朋友分開。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"winners and losers","meaning":"勝利者和失敗者","examples":[{"en":"Ranking can divide friends into winners and losers.","zh":"排名可以把朋友分成勝利者和失敗者。"},{"en":"Winners and losers are people seen as successful or unsuccessful in a competition.","zh":"勝利者和失敗者是在競爭中被視為成功或不成功的人。"},{"en":"A classroom should not make students feel like permanent winners and losers.","zh":"課室不應令學生覺得自己是永久的勝利者或失敗者。"},{"en":"When learning becomes about winners and losers, cooperation may weaken.","zh":"當學習變成勝利者和失敗者之分，合作可能削弱。"},{"en":"Students need to see one another as classmates, not opponents.","zh":"學生需要把彼此視為同學，而不是對手。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"the more…the more…","meaning":"越……越……","examples":[{"en":"The more schools attach identity to ranking, the more students see one another as threats.","zh":"學校越把身分與排名掛鈎，學生越會把彼此視為威脅。"},{"en":"The more…the more… shows that one change increases together with another change.","zh":"the more…the more… 顯示一種變化會與另一種變化一同增加。"},{"en":"The more students fear ranking, the more they may avoid difficult tasks.","zh":"學生越害怕排名，便越可能避開困難任務。"},{"en":"The more feedback focuses on progress, the more students may feel hopeful.","zh":"回饋越著重進步，學生便越可能感到有希望。"},{"en":"This structure is useful for showing cause and effect.","zh":"這個句式適合用來展示因果關係。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"attach identity to ranking","meaning":"把身分與排名掛鈎","examples":[{"en":"Schools should not attach students’ identity to ranking.","zh":"學校不應把學生的身分與排名掛鈎。"},{"en":"To attach identity to ranking means to make students feel their worth depends on their rank.","zh":"把身分與排名掛鈎意思是令學生覺得自己的價值取決於排名。"},{"en":"A child should not think “I am last, so I am useless.”","zh":"孩子不應想「我是最後，所以我沒用」。"},{"en":"Attaching identity to ranking can damage confidence and friendship.","zh":"把身分與排名掛鈎可能損害信心和友誼。"},{"en":"Students’ identity should be connected to growth, effort, and character.","zh":"學生的身分應與成長、努力和品格相連。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"see one another as threats","meaning":"把彼此視為威脅","examples":[{"en":"Students may learn to see one another as threats.","zh":"學生可能學會把彼此視為威脅。"},{"en":"To see one another as threats means to view classmates as dangers to one’s success.","zh":"把彼此視為威脅意思是把同學看成自己成功的危險。"},{"en":"Ranking can make students see helpful classmates as rivals.","zh":"排名可以令學生把願意幫忙的同學看成競爭對手。"},{"en":"If students see one another as threats, they may stop sharing notes.","zh":"如果學生把彼此視為威脅，他們可能停止分享筆記。"},{"en":"Good learning communities help students see one another as partners.","zh":"良好的學習社群幫助學生把彼此視為夥伴。"}],"source":"2018 Q5.pdf","sourcePage":8},{"front":"consider","meaning":"試想；考慮","examples":[{"en":"Consider a newly arrived student adapting to an English-medium environment.","zh":"試想一位新轉入的學生正在適應英語教學環境。"},{"en":"Consider is used to ask listeners to think about a specific example.","zh":"consider 用來請聽眾思考一個具體例子。"},{"en":"Consider a student who improves by ten marks but remains last.","zh":"試想一位學生進步十分，但仍然排最後。"},{"en":"This word helps introduce a case that supports the speaker’s argument.","zh":"這個字幫助引入支持講者論點的個案。"},{"en":"In speeches, “consider” invites the audience to imagine the situation fairly.","zh":"在演講中，consider 邀請觀眾公平地想像情況。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"a newly arrived student","meaning":"新來港學生；新轉入的學生","examples":[{"en":"A newly arrived student may struggle with a new learning environment.","zh":"新轉入的學生可能難以適應新的學習環境。"},{"en":"A newly arrived student is someone who has recently joined a school or place.","zh":"newly arrived student 指最近加入學校或某地方的學生。"},{"en":"A newly arrived student may need time to understand the language and routines.","zh":"新轉入的學生可能需要時間理解語言和日常規律。"},{"en":"Ranking such a student too early may be unfair.","zh":"太早為這樣的學生排名可能不公平。"},{"en":"Support helps newly arrived students adapt and show their real ability.","zh":"支援幫助新轉入的學生適應並展示真正能力。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"adapt to","meaning":"適應","examples":[{"en":"The student is adapting to an English-medium environment.","zh":"這位學生正在適應英語教學環境。"},{"en":"To adapt to something means to get used to a new situation.","zh":"adapt to 意思是習慣新的情況。"},{"en":"A student may need months to adapt to a new school system.","zh":"學生可能需要數月適應新的學校制度。"},{"en":"While adapting to a new language, a student may make temporary mistakes.","zh":"在適應新語言時，學生可能會暫時犯錯。"},{"en":"Teachers should support students who are still adapting.","zh":"老師應支援仍在適應的學生。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"an English-medium environment","meaning":"英語教學環境","examples":[{"en":"A newly arrived student may need time to adapt to an English-medium environment.","zh":"新轉入的學生可能需要時間適應英語教學環境。"},{"en":"An English-medium environment is a school or class where English is used for teaching.","zh":"英語教學環境是使用英語授課的學校或課堂。"},{"en":"Students may understand the subject but struggle to express answers in English.","zh":"學生可能理解科目內容，但難以用英語表達答案。"},{"en":"A low rank in an English-medium environment may reflect language adjustment, not low ability.","zh":"在英語教學環境中的低排名，可能反映語言適應，而不是能力低。"},{"en":"Schools should give language support in such an environment.","zh":"學校應在這種環境中提供語言支援。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"brave enough to ask for help","meaning":"有足夠勇氣求助","examples":[{"en":"She is brave enough to ask for help.","zh":"她有足夠勇氣求助。"},{"en":"Brave enough to ask for help means having the courage to admit difficulty and seek support.","zh":"brave enough to ask for help 意思是有勇氣承認困難並尋求支援。"},{"en":"A student is brave enough to ask for help when she raises her hand despite feeling nervous.","zh":"學生即使緊張仍舉手，就是有足夠勇氣求助。"},{"en":"Ranking may discourage students from asking for help because they fear looking weak.","zh":"排名可能令學生不敢求助，因為他們害怕顯得薄弱。"},{"en":"Schools should praise students who are brave enough to seek guidance.","zh":"學校應讚賞有足夠勇氣尋求指導的學生。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, one low class position may make her look like a failure.","zh":"然而，一個低班名次可能令她看起來像失敗者。"},{"en":"Nevertheless means however, despite what has just been said.","zh":"nevertheless 意思是然而，儘管剛才所說成立。"},{"en":"She works hard; nevertheless, her rank remains low.","zh":"她很努力；然而，她的排名仍然較低。"},{"en":"This word introduces a contrast between effort and unfair appearance.","zh":"這個字引出努力與不公平表象之間的對比。"},{"en":"It is useful when showing that a positive fact does not prevent a negative result.","zh":"當顯示正面事實不能阻止負面結果時，它很有用。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"one low class position","meaning":"一個低班名次","examples":[{"en":"One low class position may make a hardworking student look like a failure.","zh":"一個低班名次可能令勤力學生看起來像失敗者。"},{"en":"One low class position means a single low rank on a report card.","zh":"one low class position 指成績表上一個較低的名次。"},{"en":"One low class position should not define a student’s whole ability.","zh":"一個低班名次不應定義學生的整體能力。"},{"en":"A low rank may reflect adjustment, language difficulty, or a very strong class.","zh":"低排名可能反映適應、語言困難或班別很強。"},{"en":"This phrase shows how one number can create an unfair impression.","zh":"這個片語顯示一個數字如何造成不公平印象。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"unfairly","meaning":"不公平地","examples":[{"en":"A low class position may unfairly make her look like a failure.","zh":"低班名次可能不公平地令她看起來像失敗者。"},{"en":"Unfairly means in a way that is not just or reasonable.","zh":"unfairly 意思是以不公正或不合理的方式。"},{"en":"A student may be judged unfairly if only rank is considered.","zh":"如果只考慮排名，學生可能被不公平地評價。"},{"en":"Ranking newly arrived students too early may treat them unfairly.","zh":"太早為新轉入學生排名可能不公平地對待他們。"},{"en":"Fair assessment should avoid unfairly labelling students.","zh":"公平評估應避免不公平地標籤學生。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"look like a failure","meaning":"看起來像失敗者","examples":[{"en":"A low ranking may make a student look like a failure.","zh":"低排名可能令學生看起來像失敗者。"},{"en":"Look like a failure means appear unsuccessful, even if the full story is different.","zh":"look like a failure 意思是看似不成功，即使完整情況並非如此。"},{"en":"A student adapting to a new language may look like a failure on paper.","zh":"正在適應新語言的學生在紙面上可能看起來像失敗者。"},{"en":"Ranking can make improvement invisible and make students look worse than they are.","zh":"排名可以令進步不明顯，並令學生看起來比實際更差。"},{"en":"No report should make a child look like a failure without explaining context.","zh":"任何報告都不應在不解釋背景下令孩子看起來像失敗者。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"be made to feel small","meaning":"被迫感到自己渺小","examples":[{"en":"No student should be made to feel small because of ranking.","zh":"沒有學生應因排名而被迫感到自己渺小。"},{"en":"Be made to feel small means be caused to feel unimportant, ashamed, or inferior.","zh":"be made to feel small 意思是被令到感到不重要、羞愧或低人一等。"},{"en":"A child may be made to feel small if adults compare him harshly with classmates.","zh":"如果成年人嚴厲地把孩子與同學比較，孩子可能被迫感到自己渺小。"},{"en":"Ranking can make students feel small when it ignores their effort.","zh":"當排名忽視努力時，可能令學生感到渺小。"},{"en":"Education should enlarge students’ confidence, not make them feel small.","zh":"教育應擴大學生信心，而不是令他們感到渺小。"}],"source":"2018 Q5.pdf","sourcePage":9},{"front":"simply because","meaning":"只因為","examples":[{"en":"No student should feel small simply because others scored higher.","zh":"沒有學生應只因為其他人取得較高分數而感到渺小。"},{"en":"Simply because means only for that reason and no deeper reason.","zh":"simply because 意思是只因那個原因，而沒有更深理由。"},{"en":"A student should not be labelled weak simply because one test went badly.","zh":"學生不應只因一次測驗表現差就被標籤為弱。"},{"en":"Students should not lose confidence simply because classmates scored higher.","zh":"學生不應只因同學取得較高分數就失去信心。"},{"en":"This phrase shows that the reason is too narrow to justify the result.","zh":"這個片語顯示該理由太狹窄，不足以支持結果。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"scored higher","meaning":"取得較高分數","examples":[{"en":"Other students scored higher in the same group.","zh":"同一組別中的其他學生取得較高分數。"},{"en":"Scored higher means received more marks than someone else.","zh":"scored higher 意思是比其他人取得更多分數。"},{"en":"A student may score higher on one test but still need help in another skill.","zh":"學生可能在一次測驗中取得較高分數，但另一項技能仍需要幫助。"},{"en":"If others scored higher, it does not mean the lower-scoring student did not improve.","zh":"即使其他人取得較高分數，也不代表分數較低的學生沒有進步。"},{"en":"Scores should be used to guide learning, not shame students.","zh":"分數應用來指導學習，而不是羞辱學生。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"in the same group","meaning":"在同一組別中","examples":[{"en":"Ranking compares students within the same group.","zh":"排名比較同一組別中的學生。"},{"en":"In the same group means among people placed together for comparison or activity.","zh":"in the same group 意思是在被放在一起比較或活動的人之中。"},{"en":"Students in the same group may have very different starting points.","zh":"同一組別中的學生可能有非常不同的起點。"},{"en":"Being ranked low in the same group does not show a student’s progress over time.","zh":"在同一組別中排名低，並不顯示學生長期以來的進步。"},{"en":"Fair assessment should consider more than position inside one group.","zh":"公平評估應考慮多於一個組別內的位置。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"work up to a point","meaning":"在某程度上有效","examples":[{"en":"Competition works up to a point.","zh":"競爭在某程度上有效。"},{"en":"Works up to a point means is useful only to a limited degree.","zh":"works up to a point 意思是只在有限程度上有用。"},{"en":"Competition may work up to a point by encouraging practice.","zh":"競爭可能透過鼓勵練習而在某程度上有效。"},{"en":"Beyond that point, it may create fear, jealousy, or stress.","zh":"超過那個限度後，它可能造成恐懼、妒忌或壓力。"},{"en":"This phrase helps make a balanced argument instead of rejecting competition completely.","zh":"這個片語有助提出平衡論點，而不是完全否定競爭。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"beyond that","meaning":"超過那個限度後","examples":[{"en":"Beyond that, competition can damage trust and self-respect.","zh":"超過那個限度後，競爭可以損害信任和自尊。"},{"en":"Beyond that means after that limit or past that point.","zh":"beyond that 意思是在那個限制之後或超過那個程度。"},{"en":"A little pressure may help students focus; beyond that, it may harm sleep.","zh":"一點壓力可能幫助學生集中；超過那個限度後，可能傷害睡眠。"},{"en":"Competition can motivate at first, but beyond that it may damage relationships.","zh":"競爭起初可以激勵人，但超過那個限度後可能損害人際關係。"},{"en":"This phrase helps show when something useful becomes harmful.","zh":"這個片語幫助顯示有用的事情何時變成有害。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"damage trust","meaning":"損害信任","examples":[{"en":"Excessive competition can damage trust.","zh":"過度競爭可以損害信任。"},{"en":"To damage trust means to make people less willing to believe or rely on one another.","zh":"損害信任意思是令人較不願意相信或依靠彼此。"},{"en":"Ranking may damage trust if students hide notes from classmates.","zh":"如果學生不願與同學分享筆記，排名可能損害信任。"},{"en":"Harsh comparison can damage trust between children and parents.","zh":"嚴厲比較可以損害孩子與家長之間的信任。"},{"en":"Schools should protect trust because learning often depends on cooperation.","zh":"學校應保護信任，因為學習往往依賴合作。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"cooperation","meaning":"合作","examples":[{"en":"Competition can damage cooperation among students.","zh":"競爭可以損害學生之間的合作。"},{"en":"Cooperation means working together and helping one another.","zh":"合作意思是一起工作並互相幫助。"},{"en":"Students show cooperation when they explain difficult questions to classmates.","zh":"學生向同學解釋困難問題時，就是展現合作。"},{"en":"Ranking may weaken cooperation if students fear helping others will lower their own position.","zh":"如果學生害怕幫助別人會降低自己的位置，排名可能削弱合作。"},{"en":"A healthy classroom needs cooperation as well as personal effort.","zh":"健康課室既需要個人努力，也需要合作。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"self-respect","meaning":"自尊","examples":[{"en":"Ranking may harm a student’s self-respect.","zh":"排名可能傷害學生的自尊。"},{"en":"Self-respect means the feeling that you have value and deserve dignity.","zh":"自尊意思是覺得自己有價值並應得到尊重。"},{"en":"A student’s self-respect may suffer if he is always called last.","zh":"如果學生總是被稱為最後一名，他的自尊可能受損。"},{"en":"Feedback should correct mistakes without destroying self-respect.","zh":"回饋應糾正錯誤，而不摧毀自尊。"},{"en":"Students learn better when they feel respected, even while improving weaknesses.","zh":"當學生即使在改善弱項時仍感到被尊重，他們會學得更好。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"stretch students","meaning":"促使學生突破自己","examples":[{"en":"Education should stretch students.","zh":"教育應促使學生突破自己。"},{"en":"To stretch students means to challenge them enough to help them grow.","zh":"stretch students 意思是給學生足夠挑戰，幫助他們成長。"},{"en":"A teacher stretches students by giving tasks that are difficult but possible.","zh":"老師透過給予困難但可做到的任務來促使學生突破自己。"},{"en":"Ranking may stop students from stretching themselves if they fear losing marks.","zh":"如果學生害怕失分，排名可能阻止他們挑戰自己。"},{"en":"Good challenge stretches students without humiliating them.","zh":"好挑戰會促使學生突破自己，而不羞辱他們。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"sort their dignity","meaning":"將學生的尊嚴分等級","examples":[{"en":"Education should not sort students’ dignity by rank.","zh":"教育不應按排名將學生的尊嚴分等級。"},{"en":"To sort their dignity by rank means to treat students’ worth as higher or lower according to position.","zh":"將學生的尊嚴按排名分等級，意思是根據名次把學生價值分高低。"},{"en":"A child’s dignity should not depend on being first or last.","zh":"孩子的尊嚴不應取決於第一或最後。"},{"en":"Ranking may make students feel their value has been sorted into levels.","zh":"排名可能令學生覺得自己的價值被分成等級。"},{"en":"Schools should assess performance without grading human worth.","zh":"學校應評估表現，而不為人的價值分級。"}],"source":"2018 Q5.pdf","sourcePage":10},{"front":"our opponents may argue that","meaning":"我方對手可能會認為","examples":[{"en":"Our opponents may argue that class position motivates students.","zh":"我方對手可能會認為班內排名能激勵學生。"},{"en":"Our opponents may argue that introduces what the other side may say.","zh":"our opponents may argue that 用來引出對方可能提出的說法。"},{"en":"Our opponents may argue that ranking gives parents clear information.","zh":"我方對手可能會認為排名給家長清晰資料。"},{"en":"This phrase prepares the speaker to answer the opposing argument.","zh":"這個片語讓講者準備回應反方論點。"},{"en":"A good rebuttal first states the opposing view fairly.","zh":"好反駁會先公平陳述對方觀點。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"motivate students","meaning":"激勵學生","examples":[{"en":"Some people believe class position can motivate students.","zh":"有些人相信班內排名可以激勵學生。"},{"en":"To motivate students means to encourage them to work harder or keep trying.","zh":"激勵學生意思是鼓勵他們更努力或繼續嘗試。"},{"en":"Praise, clear goals, and useful feedback can motivate students.","zh":"讚賞、清晰目標和有用回饋可以激勵學生。"},{"en":"Ranking may motivate some students briefly but discourage others deeply.","zh":"排名可能短暫激勵一些學生，但深深打擊另一些學生。"},{"en":"Healthier motivation should come from progress, purpose, and support.","zh":"更健康的動力應來自進步、目的和支援。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"understand performance","meaning":"了解表現","examples":[{"en":"Parents need clear information to understand performance.","zh":"家長需要清晰資料來了解表現。"},{"en":"To understand performance means to know how well someone is doing and why.","zh":"了解表現意思是知道某人做得如何以及原因。"},{"en":"Parents understand performance better when reports explain strengths and weaknesses.","zh":"當報告解釋強項和弱項時，家長能更好了解表現。"},{"en":"A rank alone does not help parents fully understand performance.","zh":"單靠排名不能幫助家長全面了解表現。"},{"en":"Detailed feedback shows whether the problem is vocabulary, reasoning, or exam technique.","zh":"詳細回饋顯示問題是詞彙、推理還是考試技巧。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, parents deserve clear information.","zh":"誠然，家長應得到清晰資料。"},{"en":"Granted means the speaker accepts part of the opposing argument before responding.","zh":"granted 意思是講者在回應前先接受反方論點的一部分。"},{"en":"Granted, ranking is easy to read, but it is not enough.","zh":"誠然，排名容易閱讀，但它並不足夠。"},{"en":"This word makes the speaker sound fair and reasonable.","zh":"這個字令講者聽起來公平而合理。"},{"en":"It helps show that rejecting ranking does not mean rejecting standards.","zh":"它幫助顯示反對排名並不等於反對標準。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"deserve clear information","meaning":"應得到清晰資料","examples":[{"en":"Parents deserve clear information about their children’s learning.","zh":"家長應得到關於孩子學習的清晰資料。"},{"en":"Deserve clear information means have a fair right to receive understandable details.","zh":"deserve clear information 意思是公平地有權獲得容易理解的細節。"},{"en":"Parents deserve clear information so they can support their children at home.","zh":"家長應得到清晰資料，以便在家支援孩子。"},{"en":"Students also deserve clear information about how to improve.","zh":"學生也應得到關於如何改善的清晰資料。"},{"en":"Clear information should explain learning, not only rank.","zh":"清晰資料應解釋學習，而不只是排名。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"need standards","meaning":"需要標準","examples":[{"en":"Students need standards.","zh":"學生需要標準。"},{"en":"Need standards means need clear levels or expectations to guide learning.","zh":"need standards 意思是需要清晰水平或期望來指導學習。"},{"en":"Students need standards so they know what strong writing looks like.","zh":"學生需要標準，才能知道好文章是怎樣的。"},{"en":"Removing class position does not mean students no longer need standards.","zh":"移除班內排名並不代表學生不再需要標準。"},{"en":"Standards should guide improvement without turning children into ranks.","zh":"標準應指導改善，而不是把孩子變成排名。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"a crude answer to","meaning":"對……的粗糙回應","examples":[{"en":"Class position is a crude answer to a legitimate need.","zh":"班內排名是對合理需要的粗糙回應。"},{"en":"A crude answer to something is a rough or overly simple response to a real problem.","zh":"a crude answer to something 指對真實問題作出粗略或過分簡化的回應。"},{"en":"Ranking is a crude answer to parents’ need for information because it gives one number only.","zh":"排名是對家長資訊需要的粗糙回應，因為它只給一個數字。"},{"en":"A crude answer may be easy, but it often misses important details.","zh":"粗糙回應可能容易，但往往錯過重要細節。"},{"en":"This phrase criticises a solution without denying the need behind it.","zh":"這個片語批評一個解決方案，但不否定背後需要。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"a legitimate need","meaning":"合理需要","examples":[{"en":"Parents’ need for clear information is a legitimate need.","zh":"家長對清晰資料的需要是合理需要。"},{"en":"A legitimate need is a reasonable and acceptable need.","zh":"合理需要是合理且可以接受的需要。"},{"en":"Students’ need for useful feedback is also a legitimate need.","zh":"學生對有用回饋的需要也是合理需要。"},{"en":"A legitimate need should be answered carefully, not with a harmful shortcut.","zh":"合理需要應被仔細回應，而不是用有害捷徑處理。"},{"en":"Ranking may respond to a legitimate need in the wrong way.","zh":"排名可能以錯誤方式回應合理需要。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"vocabulary is weak","meaning":"詞彙薄弱","examples":[{"en":"A report should show whether a student’s vocabulary is weak.","zh":"報告應顯示學生的詞彙是否薄弱。"},{"en":"Vocabulary is weak means the student does not know enough words or uses words inaccurately.","zh":"詞彙薄弱意思是學生認識的字不夠，或用字不準確。"},{"en":"If vocabulary is weak, a student may struggle to express ideas clearly.","zh":"如果詞彙薄弱，學生可能難以清楚表達想法。"},{"en":"A helpful report tells students how to build vocabulary through reading and practice.","zh":"有幫助的報告會告訴學生如何透過閱讀和練習建立詞彙。"},{"en":"This detail is more useful than simply saying the student ranks low.","zh":"這個細節比單純說學生排名低更有用。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"reasoning is shallow","meaning":"推理膚淺","examples":[{"en":"A report should show whether a student’s reasoning is shallow.","zh":"報告應顯示學生的推理是否膚淺。"},{"en":"Reasoning is shallow means the explanation lacks depth, evidence, or careful thinking.","zh":"推理膚淺意思是解釋缺乏深度、證據或仔細思考。"},{"en":"A student’s reasoning may be shallow if he gives an opinion without examples.","zh":"如果學生只提出意見而沒有例子，他的推理可能膚淺。"},{"en":"Teacher comments can help students develop deeper reasoning.","zh":"老師評語可以幫助學生發展更深入推理。"},{"en":"Ranking cannot show whether the real weakness is shallow reasoning.","zh":"排名不能顯示真正弱點是否推理膚淺。"}],"source":"2018 Q5.pdf","sourcePage":11},{"front":"exam technique is careless","meaning":"考試技巧粗心","examples":[{"en":"A report should show whether a student’s exam technique is careless.","zh":"報告應顯示學生的考試技巧是否粗心。"},{"en":"Exam technique is careless means the student loses marks through avoidable mistakes in the exam.","zh":"考試技巧粗心意思是學生在考試中因可避免錯誤而失分。"},{"en":"A student may know the answer but lose marks because exam technique is careless.","zh":"學生可能知道答案，但因考試技巧粗心而失分。"},{"en":"Careless exam technique can include misreading questions or poor time management.","zh":"粗心考試技巧可包括看錯題目或時間分配差。"},{"en":"Feedback on technique gives students a clear way to improve.","zh":"關於技巧的回饋給學生清晰改善方法。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"improvement is remarkable","meaning":"進步顯著","examples":[{"en":"A report should show whether a student’s improvement is remarkable.","zh":"報告應顯示學生的進步是否顯著。"},{"en":"Improvement is remarkable means the progress is large and worth noticing.","zh":"進步顯著意思是進展很大，值得注意。"},{"en":"A student who rises from failing to passing has made remarkable improvement.","zh":"從不合格進步到合格的學生已取得顯著進步。"},{"en":"Ranking may hide remarkable improvement if the student still remains near the bottom.","zh":"如果學生仍接近榜末，排名可能掩蓋顯著進步。"},{"en":"Recognising remarkable improvement can encourage students to keep working.","zh":"承認顯著進步可以鼓勵學生繼續努力。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"better yet","meaning":"更好的是","examples":[{"en":"Better yet, schools can provide richer forms of feedback.","zh":"更好的是，學校可以提供更豐富形式的回饋。"},{"en":"Better yet means an even better option or idea is being introduced.","zh":"better yet 意思是正在引入一個更好的選擇或想法。"},{"en":"Schools can remove ranking; better yet, they can replace it with diagnostic reports.","zh":"學校可以移除排名；更好的是，可以用診斷式報告取代它。"},{"en":"This phrase helps the speaker move from criticism to improvement.","zh":"這個片語幫助講者由批評轉向改善。"},{"en":"It suggests that the proposed solution is stronger than the basic alternative.","zh":"它表示提出的解決方案比基本選項更強。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"subject grades","meaning":"科目等級","examples":[{"en":"Schools can provide subject grades.","zh":"學校可以提供科目等級。"},{"en":"Subject grades are results given for individual subjects such as English, Maths, or Science.","zh":"科目等級是英語、數學或科學等個別科目的成績。"},{"en":"Subject grades show performance in each subject more clearly than one class rank.","zh":"科目等級比一個班內排名更清楚顯示各科表現。"},{"en":"A student may have a strong Maths grade but need support in English writing.","zh":"學生可能數學等級強，但需要英語寫作支援。"},{"en":"Subject grades help parents understand learning area by area.","zh":"科目等級幫助家長按學習範疇理解表現。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"standards-based descriptors","meaning":"按標準描述的評語","examples":[{"en":"Schools can provide standards-based descriptors.","zh":"學校可以提供按標準描述的評語。"},{"en":"Standards-based descriptors are comments that describe what a student can do according to clear learning standards.","zh":"按標準描述的評語是根據清晰學習標準描述學生能做甚麼的評語。"},{"en":"A descriptor may say that a student can explain ideas but needs stronger evidence.","zh":"評語可能指出學生能解釋想法，但需要更有力證據。"},{"en":"These descriptors are more helpful than rank because they describe actual skills.","zh":"這些評語比排名更有幫助，因為它們描述實際技能。"},{"en":"They help students understand what the standard requires.","zh":"它們幫助學生理解標準要求。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"progress indicators","meaning":"進度指標","examples":[{"en":"Schools can provide progress indicators.","zh":"學校可以提供進度指標。"},{"en":"Progress indicators are signs or measures that show how much a student has improved.","zh":"進度指標是顯示學生進步多少的標誌或衡量方法。"},{"en":"A progress indicator may show that a student’s writing score rose by eight marks.","zh":"進度指標可能顯示學生寫作分數提高了八分。"},{"en":"Progress indicators help students see growth even if rank does not change.","zh":"即使排名沒有改變，進度指標也幫助學生看見成長。"},{"en":"They encourage effort because improvement becomes visible.","zh":"它們令進步變得可見，因此鼓勵努力。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"teacher comments","meaning":"老師評語","examples":[{"en":"Teacher comments can help students understand how to improve.","zh":"老師評語可以幫助學生了解如何改善。"},{"en":"Teacher comments are written or spoken feedback from teachers about learning.","zh":"老師評語是老師就學習給出的書面或口頭回饋。"},{"en":"A teacher comment may tell a student to add examples to strengthen an argument.","zh":"老師評語可能告訴學生加入例子以加強論點。"},{"en":"Good comments explain both what is working and what needs attention.","zh":"好評語會解釋甚麼做得好，以及甚麼需要注意。"},{"en":"Teacher comments are useful because they give direction, not only judgement.","zh":"老師評語有用，因為它給方向，而不只是判斷。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"instead of writing","meaning":"與其寫上……","examples":[{"en":"Instead of writing a class position, a report could give diagnostic feedback.","zh":"與其寫上班內排名，報告可以提供診斷式回饋。"},{"en":"Instead of writing means choosing not to put certain words or information down.","zh":"instead of writing 意思是選擇不寫下某些文字或資料。"},{"en":"Instead of writing only a rank, teachers can write one clear improvement target.","zh":"與其只寫上排名，老師可以寫一個清晰改善目標。"},{"en":"This phrase shows what should be removed and what should replace it.","zh":"這個片語顯示應移除甚麼，以及用甚麼取代。"},{"en":"It helps the speaker propose a practical alternative.","zh":"它幫助講者提出實際替代方案。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"reading comprehension","meaning":"閱讀理解","examples":[{"en":"Reading comprehension is secure.","zh":"閱讀理解是穩固的。"},{"en":"Reading comprehension means the ability to understand written texts.","zh":"閱讀理解指理解書面文本的能力。"},{"en":"A student with strong reading comprehension can identify main ideas and details.","zh":"閱讀理解強的學生能找出主旨和細節。"},{"en":"If reading comprehension is weak, the student may misunderstand exam questions.","zh":"如果閱讀理解薄弱，學生可能誤解考試題目。"},{"en":"A report on reading comprehension gives clearer guidance than a rank.","zh":"關於閱讀理解的報告比排名提供更清晰指引。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"is secure","meaning":"穩固","examples":[{"en":"The report says that the student’s reading comprehension is secure.","zh":"報告指出學生的閱讀理解是穩固的。"},{"en":"Is secure means is stable, reliable, and strong enough for the current level.","zh":"is secure 意思是穩定、可靠，並足以應付目前水平。"},{"en":"If a student’s grammar is secure, she can use basic structures accurately.","zh":"如果學生的文法穩固，她能準確使用基本結構。"},{"en":"Saying a skill is secure helps students know what they can rely on.","zh":"指出某項技能穩固，幫助學生知道可以依靠甚麼。"},{"en":"This phrase is useful in feedback because it identifies a clear strength.","zh":"這個片語在回饋中有用，因為它指出清晰強項。"}],"source":"2018 Q5.pdf","sourcePage":12},{"front":"argumentative writing","meaning":"議論文寫作","examples":[{"en":"Argumentative writing needs stronger evidence.","zh":"議論文寫作需要更有力的證據。"},{"en":"Argumentative writing is writing that gives a viewpoint and supports it with reasons and evidence.","zh":"議論文寫作是提出觀點並用理由和證據支持的寫作。"},{"en":"A student practises argumentative writing when arguing whether homework should be reduced.","zh":"學生討論是否應減少功課時，就是練習議論文寫作。"},{"en":"Weak argumentative writing may give opinions without examples.","zh":"薄弱的議論文寫作可能只有意見而沒有例子。"},{"en":"Feedback on argumentative writing helps students build clearer and stronger arguments.","zh":"關於議論文寫作的回饋幫助學生建立更清晰有力的論點。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"stronger evidence","meaning":"更有力的證據","examples":[{"en":"Argumentative writing needs stronger evidence.","zh":"議論文寫作需要更有力的證據。"},{"en":"Stronger evidence means more convincing facts, examples, or reasons that support a claim.","zh":"更有力的證據指更具說服力、能支持主張的事實、例子或理由。"},{"en":"A student can use statistics or real cases as stronger evidence.","zh":"學生可以使用統計或真實個案作為更有力的證據。"},{"en":"Without stronger evidence, an argument may sound like personal opinion only.","zh":"沒有更有力的證據，論點可能聽起來只是個人意見。"},{"en":"Teachers can help students improve by showing what evidence is missing.","zh":"老師可以透過指出缺少甚麼證據來幫助學生改善。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"overall score","meaning":"總分","examples":[{"en":"The student’s overall score has improved by eight marks.","zh":"學生的總分提高了八分。"},{"en":"Overall score means the total or combined result across a test, subject, or report.","zh":"overall score 指測驗、科目或報告中的總成績或綜合結果。"},{"en":"A student’s overall score may rise even if one section remains weak.","zh":"即使某部分仍薄弱，學生的總分也可能上升。"},{"en":"Overall score can show progress more clearly than class position alone.","zh":"總分可以比單靠班內排名更清楚顯示進步。"},{"en":"Reports should explain what caused the overall score to improve or fall.","zh":"報告應解釋總分上升或下降的原因。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"has improved by","meaning":"提高了……","examples":[{"en":"The overall score has improved by eight marks.","zh":"總分提高了八分。"},{"en":"Has improved by means has increased or become better by a certain amount.","zh":"has improved by 意思是增加或改善了某個數量。"},{"en":"Her reading score has improved by five marks after regular practice.","zh":"經過定期練習後，她的閱讀分數提高了五分。"},{"en":"Saying the score has improved by eight marks makes progress measurable.","zh":"說分數提高了八分，令進步可以被衡量。"},{"en":"This phrase helps reports show growth clearly.","zh":"這個片語幫助報告清楚顯示成長。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, parents receive direction and students receive hope.","zh":"這樣一來，家長得到方向，學生得到希望。"},{"en":"That way means by doing this, or as a result of this method.","zh":"that way 意思是透過這樣做，或作為這種方法的結果。"},{"en":"Give clear comments; that way, students know what to practise.","zh":"給出清晰評語；這樣一來，學生便知道要練習甚麼。"},{"en":"Replace ranking with feedback; that way, parents still understand performance.","zh":"用回饋取代排名；這樣一來，家長仍能了解表現。"},{"en":"This phrase connects a proposal with its positive result.","zh":"這個片語把建議與正面結果連接起來。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"receive direction","meaning":"得到方向","examples":[{"en":"Parents receive direction from detailed feedback.","zh":"家長從詳細回饋中得到方向。"},{"en":"To receive direction means to get guidance about what action to take next.","zh":"receive direction 意思是獲得關於下一步行動的指引。"},{"en":"Parents receive direction when a report explains which skill needs practice.","zh":"當報告解釋哪項技能需要練習時，家長便得到方向。"},{"en":"A rank alone gives little direction because it does not explain the problem.","zh":"單靠排名提供很少方向，因為它沒有解釋問題。"},{"en":"Clear direction helps families support learning at home.","zh":"清晰方向幫助家庭在家支援學習。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"receive hope","meaning":"得到希望","examples":[{"en":"Students receive hope from progress-based feedback.","zh":"學生從以進步為本的回饋中得到希望。"},{"en":"To receive hope means to feel that improvement is possible.","zh":"receive hope 意思是感到進步是可能的。"},{"en":"A student receives hope when a teacher says his writing has improved.","zh":"當老師說學生的寫作已有改善時，學生便得到希望。"},{"en":"Progress-based feedback gives hope because it shows effort can work.","zh":"以進步為本的回饋給人希望，因為它顯示努力可以有效。"},{"en":"Ranking may remove hope if students see only a low position.","zh":"如果學生只看到低名次，排名可能奪走希望。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"remain accountable","meaning":"保持問責","examples":[{"en":"Teachers remain accountable when reports are specific.","zh":"當報告具體時，老師保持問責。"},{"en":"Remain accountable means continue to be responsible for explaining decisions and results.","zh":"remain accountable 意思是繼續有責任解釋決定和結果。"},{"en":"Teachers remain accountable when comments clearly show why a grade was given.","zh":"當評語清楚顯示為何給出某等級時，老師便保持問責。"},{"en":"Detailed reports make assessment more accountable than a simple ranking list.","zh":"詳細報告比簡單排名表令評估更具問責性。"},{"en":"Accountability protects both students and parents because decisions can be checked.","zh":"問責保障學生和家長，因為決定可以被檢查。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"to say that…is not to say that…","meaning":"說……並不是說……","examples":[{"en":"To say that we should abolish class position is not to say that we should abolish excellence.","zh":"說我們應廢除班內排名，並不是說我們應廢除卓越。"},{"en":"This structure means one claim should not be misunderstood as another claim.","zh":"這個句式意思是某個主張不應被誤解為另一個主張。"},{"en":"To say that tests need reform is not to say that students should stop studying.","zh":"說測驗需要改革，並不是說學生應停止讀書。"},{"en":"It helps the speaker prevent opponents from twisting the argument.","zh":"它幫助講者防止對方扭曲論點。"},{"en":"This phrase is useful for drawing a careful distinction.","zh":"這個片語適合用來作出仔細區分。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"abolish excellence","meaning":"廢除卓越","examples":[{"en":"Abolishing class position does not mean abolishing excellence.","zh":"廢除班內排名並不代表廢除卓越。"},{"en":"To abolish excellence would mean to remove high standards or stop valuing strong achievement.","zh":"廢除卓越意思是移除高標準或停止重視優秀成就。"},{"en":"Schools can value excellence without ranking every child publicly.","zh":"學校可以重視卓越，而不公開為每個孩子排名。"},{"en":"Feedback can encourage excellence by showing students how to improve.","zh":"回饋可以透過指出改善方法來鼓勵卓越。"},{"en":"This phrase helps answer the fear that ending ranking means lowering standards.","zh":"這個片語幫助回應「取消排名等於降低標準」的擔憂。"}],"source":"2018 Q5.pdf","sourcePage":13},{"front":"be measured intelligently","meaning":"被明智地衡量","examples":[{"en":"Excellence should be measured intelligently.","zh":"卓越應被明智地衡量。"},{"en":"Be measured intelligently means be assessed in a thoughtful, fair, and useful way.","zh":"be measured intelligently 意思是以有思考、公平和有用的方式評估。"},{"en":"Writing ability is measured intelligently when teachers assess ideas, evidence, and language separately.","zh":"當老師分別評估理念、證據和語言時，寫作能力便被明智地衡量。"},{"en":"Ranking alone does not measure excellence intelligently because it gives too little detail.","zh":"單靠排名不能明智地衡量卓越，因為它提供太少細節。"},{"en":"Intelligent measurement helps students improve while keeping standards high.","zh":"明智衡量幫助學生進步，同時保持高標準。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"adjudicators","meaning":"評判","examples":[{"en":"The speaker addresses the adjudicators in the final section.","zh":"講者在最後部分稱呼評判。"},{"en":"Adjudicators are judges who listen to a debate and decide which side performs better.","zh":"adjudicators 是聆聽辯論並決定哪一方表現較好的評判。"},{"en":"Debaters address adjudicators respectfully because they evaluate the arguments.","zh":"辯論員尊重地稱呼評判，因為評判會評估論點。"},{"en":"Adjudicators consider logic, evidence, delivery, and rebuttal.","zh":"評判會考慮邏輯、證據、演繹和反駁。"},{"en":"This word is common in formal debate settings.","zh":"這個字常見於正式辯論場合。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"the question before us","meaning":"擺在我們面前的問題","examples":[{"en":"The question before us is not whether students should work hard.","zh":"擺在我們面前的問題不是學生是否應努力。"},{"en":"The question before us means the main issue we must discuss or decide now.","zh":"the question before us 指我們現在必須討論或決定的主要問題。"},{"en":"The question before us is whether ranking helps learning or harms it.","zh":"擺在我們面前的問題是排名幫助學習還是傷害學習。"},{"en":"This phrase focuses the audience on the real debate.","zh":"這個片語把觀眾焦點放在真正辯題上。"},{"en":"It is useful when the speaker wants to avoid a misleading side issue.","zh":"當講者想避免誤導性旁枝問題時，這個片語很有用。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"of course","meaning":"當然","examples":[{"en":"Of course, students should work hard.","zh":"當然，學生應該努力。"},{"en":"Of course means naturally or obviously.","zh":"of course 意思是自然地或顯然地。"},{"en":"Of course, parents need information about their children’s learning.","zh":"當然，家長需要了解孩子學習的資料。"},{"en":"This phrase can show agreement with a reasonable point before making a stronger argument.","zh":"這個片語可在提出更強論點前表示同意合理觀點。"},{"en":"It helps the speaker sound balanced, not extreme.","zh":"它幫助講者聽起來平衡，而不是極端。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"keep using","meaning":"繼續使用","examples":[{"en":"Schools should not keep using a harmful ranking system.","zh":"學校不應繼續使用有害的排名制度。"},{"en":"Keep using means continue to use something.","zh":"keep using 意思是繼續使用某物。"},{"en":"A school should not keep using an old method if it hurts students.","zh":"如果舊方法傷害學生，學校不應繼續使用它。"},{"en":"If better feedback is available, schools need not keep using class position.","zh":"如果已有更好回饋方法，學校不必繼續使用班內排名。"},{"en":"This phrase suggests that continuing the practice is a choice.","zh":"這個片語表示延續這種做法是一個選擇。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"ranking system","meaning":"排名制度","examples":[{"en":"The speaker argues against the current ranking system.","zh":"講者反對現行排名制度。"},{"en":"A ranking system is a method that places people in order from highest to lowest.","zh":"排名制度是把人由高至低排列的方法。"},{"en":"A school ranking system may list students by marks after each exam.","zh":"學校排名制度可能在每次考試後按分數排列學生。"},{"en":"A ranking system can be simple but may ignore individual progress.","zh":"排名制度可以很簡單，但可能忽視個人進步。"},{"en":"Good assessment systems should explain learning, not only order students.","zh":"好評估制度應解釋學習，而不只是排列學生。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"relative position","meaning":"相對位置","examples":[{"en":"A ranking system rewards relative position.","zh":"排名制度獎勵相對位置。"},{"en":"Relative position means where someone stands compared with others, not their absolute ability.","zh":"relative position 指某人與他人相比的位置，而不是絕對能力。"},{"en":"A student’s relative position may fall even after improving if others improve more.","zh":"如果其他人進步更多，學生即使進步，相對位置也可能下降。"},{"en":"Ranking rewards relative position by praising those above others.","zh":"排名透過讚揚排在他人之上的人來獎勵相對位置。"},{"en":"Education should value real growth more than relative position.","zh":"教育應重視真正成長，多於相對位置。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"at the cost of","meaning":"以犧牲……為代價","examples":[{"en":"The system rewards relative position at the cost of real growth.","zh":"這個制度以犧牲真正成長為代價來獎勵相對位置。"},{"en":"At the cost of means gaining one thing by losing or damaging another.","zh":"at the cost of 意思是透過失去或損害另一事物來得到某事。"},{"en":"A student may protect marks at the cost of curiosity.","zh":"學生可能以犧牲好奇心為代價來保住分數。"},{"en":"Ranking may create clear order at the cost of confidence and cooperation.","zh":"排名可能以犧牲信心和合作為代價來創造清晰次序。"},{"en":"This phrase shows the hidden price of a choice.","zh":"這個片語顯示一個選擇背後的隱藏代價。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"real growth","meaning":"真正成長","examples":[{"en":"Education should focus on real growth.","zh":"教育應專注於真正成長。"},{"en":"Real growth means genuine improvement in knowledge, skills, confidence, and character.","zh":"真正成長指知識、技能、信心和品格上的真實改善。"},{"en":"A student shows real growth when he learns from mistakes and writes better arguments.","zh":"當學生從錯誤中學習並寫出更好論點時，他展現真正成長。"},{"en":"Ranking may ignore real growth if it only reports position.","zh":"如果排名只匯報位置，便可能忽視真正成長。"},{"en":"Schools should celebrate real growth because it shows learning is happening.","zh":"學校應肯定真正成長，因為這顯示學習正在發生。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"the time has come for","meaning":"是時候……","examples":[{"en":"The time has come for schools to stop printing class positions.","zh":"是時候讓學校停止印上班名次。"},{"en":"The time has come for means now is the right moment to take action.","zh":"the time has come for 意思是現在是採取行動的適當時刻。"},{"en":"The time has come for schools to use more helpful forms of feedback.","zh":"是時候讓學校使用更有幫助的回饋形式。"},{"en":"This phrase creates a strong sense of urgency in a speech.","zh":"這個片語在演講中創造強烈迫切感。"},{"en":"It suggests that delay is no longer acceptable.","zh":"它表示不應再拖延。"}],"source":"2018 Q5.pdf","sourcePage":14},{"front":"stop printing class positions","meaning":"停止印上班名次","examples":[{"en":"Schools should stop printing class positions on report cards.","zh":"學校應停止在成績表上印上班名次。"},{"en":"To stop printing class positions means to no longer include class ranks in written reports.","zh":"stop printing class positions 意思是不再在書面報告中加入班內排名。"},{"en":"Schools can stop printing class positions while still giving marks and comments.","zh":"學校可以停止印上班名次，同時仍提供分數和評語。"},{"en":"This change would reduce harmful comparison on report cards.","zh":"這項改變會減少成績表上的有害比較。"},{"en":"Students would then focus more on feedback than on a single rank.","zh":"學生之後會更專注於回饋，而不是單一排名。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"diagnostic reports","meaning":"診斷式報告","examples":[{"en":"Schools should give parents diagnostic reports.","zh":"學校應向家長提供診斷式報告。"},{"en":"Diagnostic reports explain strengths, weaknesses, causes, and next steps in learning.","zh":"診斷式報告解釋學習中的強項、弱項、原因和下一步。"},{"en":"A diagnostic report may say that vocabulary is weak but reading comprehension is secure.","zh":"診斷式報告可能指出詞彙薄弱，但閱讀理解穩固。"},{"en":"Such reports help parents understand what kind of support is needed.","zh":"這類報告幫助家長了解需要哪種支援。"},{"en":"Diagnostic reports are more useful than ranks because they explain the learning problem.","zh":"診斷式報告比排名更有用，因為它解釋學習問題。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"recognise students not as…but as…","meaning":"不把學生視為……而視為……","examples":[{"en":"Schools should recognise students not as numbers in a queue, but as learners.","zh":"學校不應把學生視為隊列中的數字，而應視為學習者。"},{"en":"This structure contrasts a wrong way of seeing people with a better way.","zh":"這個句式把錯誤看待人的方式與更好的方式作對比。"},{"en":"Teachers should recognise students not as exam machines, but as developing young people.","zh":"老師不應把學生視為考試機器，而應視為正在成長的年輕人。"},{"en":"The phrase helps make the argument more humane and memorable.","zh":"這個片語令論點更有人情味，也更容易記住。"},{"en":"It changes the focus from ranking students to understanding them.","zh":"它把焦點由排列學生轉向理解學生。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"numbers in a queue","meaning":"隊列中的數字","examples":[{"en":"Students should not be treated as numbers in a queue.","zh":"學生不應被當作隊列中的數字。"},{"en":"Numbers in a queue suggests people are seen only as ordered positions, not individuals.","zh":"numbers in a queue 表示人只被看成排列位置，而不是個體。"},{"en":"A student is more than number 30 on a list.","zh":"學生不只是名單上的第三十號。"},{"en":"Treating students as numbers in a queue ignores their different starting points.","zh":"把學生視為隊列中的數字會忽視他們不同的起點。"},{"en":"Education should recognise students’ stories, needs, and growth.","zh":"教育應承認學生的故事、需要和成長。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"learners with different starting points","meaning":"起點不同的學習者","examples":[{"en":"Students are learners with different starting points.","zh":"學生是起點不同的學習者。"},{"en":"Learners with different starting points are students who begin with different levels, backgrounds, or experiences.","zh":"起點不同的學習者是以不同水平、背景或經驗開始學習的學生。"},{"en":"A newly arrived student and a local student may have different starting points in English.","zh":"新來港學生和本地學生在英語方面可能有不同起點。"},{"en":"Fair assessment considers starting points when judging progress.","zh":"公平評估在判斷進步時會考慮起點。"},{"en":"This phrase reminds us that students should not be compared too simply.","zh":"這個片語提醒我們不應過分簡單地比較學生。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"strengths and paths","meaning":"強項與路徑","examples":[{"en":"Students have different starting points, strengths and paths.","zh":"學生有不同起點、強項與路徑。"},{"en":"Strengths and paths means what students are good at and the different ways they may grow.","zh":"strengths and paths 指學生擅長的地方，以及他們可能成長的不同方式。"},{"en":"One student may have strength in speaking, while another follows a slower path in writing.","zh":"一位學生可能擅長說話，而另一位在寫作上走較慢的路徑。"},{"en":"Ranking often ignores students’ different strengths and paths.","zh":"排名往往忽視學生不同的強項與路徑。"},{"en":"Education should help each student develop from their own starting point.","zh":"教育應幫助每位學生從自己的起點發展。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"for the sake of","meaning":"為了……","examples":[{"en":"For the sake of fair assessment, I urge you to support the motion.","zh":"為了公平評估，我敦促你們支持辯題。"},{"en":"For the sake of means for the purpose or benefit of something important.","zh":"for the sake of 意思是為了某件重要事情的目的或好處。"},{"en":"For the sake of students’ wellbeing, schools should reduce harmful comparison.","zh":"為了學生的情緒健康，學校應減少有害比較。"},{"en":"This phrase gives a moral reason for supporting the argument.","zh":"這個片語為支持論點提供道德理由。"},{"en":"It is often used near the end of persuasive speeches.","zh":"它常用於說服性演講的結尾部分。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"fair assessment","meaning":"公平評估","examples":[{"en":"Schools should use fair assessment.","zh":"學校應使用公平評估。"},{"en":"Fair assessment means judging students in a just, accurate, and helpful way.","zh":"公平評估意思是以公正、準確和有幫助的方式評價學生。"},{"en":"Fair assessment considers marks, progress, skills, and learning context.","zh":"公平評估會考慮分數、進步、技能和學習背景。"},{"en":"Ranking alone may not be fair assessment because it ignores many details.","zh":"單靠排名未必是公平評估，因為它忽略許多細節。"},{"en":"Fair assessment should help students understand how to grow.","zh":"公平評估應幫助學生理解如何成長。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"healthier motivation","meaning":"更健康的動力","examples":[{"en":"Students need healthier motivation.","zh":"學生需要更健康的動力。"},{"en":"Healthier motivation means encouragement that supports effort without causing harmful pressure.","zh":"更健康的動力指支持努力而不造成有害壓力的鼓勵。"},{"en":"Feedback about progress can create healthier motivation than public ranking.","zh":"關於進步的回饋可以比公開排名創造更健康的動力。"},{"en":"Students feel healthier motivation when they believe improvement is possible.","zh":"當學生相信進步是可能的，他們會感到更健康的動力。"},{"en":"Schools should motivate students through goals, support, and hope.","zh":"學校應透過目標、支援和希望來激勵學生。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"genuine progress","meaning":"真正進步","examples":[{"en":"The policy should support genuine progress.","zh":"政策應支持真正進步。"},{"en":"Genuine progress means real improvement, not just looking better in comparison.","zh":"真正進步指真實改善，而不只是比較上看起來更好。"},{"en":"A student who writes clearer paragraphs has made genuine progress.","zh":"能寫出更清晰段落的學生取得了真正進步。"},{"en":"Ranking may fail to show genuine progress if other classmates also improve.","zh":"如果其他同學也進步，排名可能無法顯示真正進步。"},{"en":"Good assessment recognises genuine progress and tells students how to continue it.","zh":"好評估會承認真正進步，並告訴學生如何延續它。"}],"source":"2018 Q5.pdf","sourcePage":15},{"front":"urge you to support the motion","meaning":"敦促你們支持辯題","examples":[{"en":"I urge you to support the motion.","zh":"我敦促你們支持辯題。"},{"en":"To urge you to support the motion means to strongly ask the audience to agree with the debate topic.","zh":"urge you to support the motion 意思是強烈請求觀眾同意辯題。"},{"en":"A speaker may urge judges to support the motion after summarising the main arguments.","zh":"講者總結主要論點後，可能敦促評判支持辯題。"},{"en":"This phrase is direct, persuasive, and suitable for a debate conclusion.","zh":"這個片語直接、有說服力，適合辯論結論。"},{"en":"It reminds listeners clearly which side the speaker wants them to choose.","zh":"它清楚提醒聽眾講者希望他們選擇哪一方。"}],"source":"2018 Q5.pdf","sourcePage":16},{"front":"Thank you","meaning":"多謝","examples":[{"en":"The speech ends with Thank you.","zh":"演講以「多謝」結束。"},{"en":"Thank you is a polite closing used to show respect to the audience.","zh":"Thank you 是有禮貌的結尾，用來向觀眾表示尊重。"},{"en":"A debater says “Thank you” after finishing the final appeal.","zh":"辯論員完成最後呼籲後會說 “Thank you”。"},{"en":"This ending signals that the speech is complete.","zh":"這個結尾表示演講已完成。"},{"en":"Even in strong debate, ending with thanks keeps the tone respectful.","zh":"即使在強烈辯論中，以感謝作結仍能保持尊重語氣。"}],"source":"2018 Q5.pdf","sourcePage":16}],"dse/writing/part-b/2018/Q6":[{"front":"a new uniform for modern life","meaning":"現代生活的新制服","examples":[{"en":"Athleisure has become a new uniform for modern life.","zh":"運動休閒服飾已成為現代生活的新制服。"},{"en":"“A new uniform for modern life” means a style of clothing that many people now wear regularly in everyday situations.","zh":"「a new uniform for modern life」表示一種很多人現在在日常不同場合經常穿着的服裝風格。"},{"en":"Jeans once became an everyday uniform for young people, and athleisure now plays a similar role.","zh":"牛仔褲曾成為年輕人的日常制服，而運動休閒服飾現在也扮演類似角色。"},{"en":"When the same comfortable clothes appear at work, cafés and shops, they begin to feel like a new uniform for modern life.","zh":"當同一類舒適服裝同時出現在工作場所、咖啡店和商店，它便開始像現代生活的新制服。"},{"en":"The phrase suggests that athleisure reflects how people now live, work and move through the day.","zh":"這個說法表示運動休閒服飾反映了現代人的生活、工作和活動方式。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"athleisure","meaning":"運動休閒服飾","examples":[{"en":"Athleisure is now common in offices, cafés and supermarkets.","zh":"運動休閒服飾現在常見於辦公室、咖啡店和超級市場。"},{"en":"Athleisure is clothing designed to look stylish while offering the comfort and flexibility of sportswear.","zh":"運動休閒服飾是兼具時尚外觀，以及運動服舒適和靈活特點的服裝。"},{"en":"Leggings, trainers and simple sports jackets are common examples of athleisure.","zh":"緊身褲、運動鞋和簡約運動外套都是常見的運動休閒服飾。"},{"en":"Athleisure has become popular because people want clothes that can suit several activities in one day.","zh":"運動休閒服飾變得受歡迎，是因為人們希望一套衣服可以配合一天內多種活動。"},{"en":"Unlike traditional gym wear, athleisure is designed to be worn both during exercise and in ordinary public settings.","zh":"與傳統健身服不同，運動休閒服飾既適合運動，也適合一般公眾場合。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"Gone are the days when","meaning":"……的日子已經過去","examples":[{"en":"Gone are the days when sportswear belonged only in gyms and stadiums.","zh":"運動服飾只屬於健身室和運動場的日子已經過去。"},{"en":"“Gone are the days when” means a past situation is no longer normal or true.","zh":"「Gone are the days when」表示過去某種情況已不再正常或成立。"},{"en":"Gone are the days when students had to visit a library to find every piece of information.","zh":"學生每次找資料都必須親身去圖書館的日子已經過去。"},{"en":"Gone are the days when comfortable clothing automatically looked too casual for public places.","zh":"舒適服裝一定會顯得過分隨便的日子已經過去。"},{"en":"This expression emphasises that society or habits have changed significantly.","zh":"這個句式強調社會或生活習慣已出現明顯改變。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"sportswear","meaning":"運動服飾","examples":[{"en":"Sportswear no longer belongs only in gyms, stadiums and school playgrounds.","zh":"運動服飾不再只屬於健身室、運動場和學校操場。"},{"en":"Sportswear is clothing designed for exercise, sport or physical activity.","zh":"運動服飾是為運動、體育或體能活動而設計的服裝。"},{"en":"Running shorts, training tops and tracksuits are common forms of sportswear.","zh":"跑步短褲、訓練上衣和運動套裝都是常見運動服飾。"},{"en":"Modern sportswear often uses light, flexible and breathable materials.","zh":"現代運動服飾常使用輕巧、有彈性和透氣的物料。"},{"en":"Sportswear has moved into daily fashion because many designs now look neat enough for ordinary life.","zh":"因為很多設計現在足夠整齊得體，運動服飾已進入日常時尚。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"belong only in","meaning":"只屬於……","examples":[{"en":"Sportswear used to belong only in gyms, stadiums and school playgrounds.","zh":"運動服飾以前只屬於健身室、運動場和學校操場。"},{"en":"“Belong only in” means to be considered suitable for just one type of place or situation.","zh":"「belong only in」表示被認為只適合某一類地方或情況。"},{"en":"Heavy hiking boots belong only in outdoor settings if they are too dirty for the office.","zh":"如果厚重行山鞋太骯髒，不適合辦公室，它們可能只適合戶外環境。"},{"en":"Sportswear once seemed to belong only in places connected with exercise.","zh":"運動服飾以前看起來只屬於與運動有關的地方。"},{"en":"Fashion changes when clothes that once belonged only in one setting become acceptable elsewhere.","zh":"當原本只屬於某一場合的衣服開始在其他地方被接受，時尚便出現改變。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"sleek trainers","meaning":"時尚俐落的運動鞋","examples":[{"en":"A pair of sleek trainers may appear in an office lift.","zh":"一雙時尚俐落的運動鞋可能出現在辦公室升降機裏。"},{"en":"Sleek trainers are sports shoes with a smooth, modern and stylish design.","zh":"時尚俐落的運動鞋是外形流線、現代而有品味的運動鞋。"},{"en":"She wore sleek trainers with dark trousers and a simple jacket.","zh":"她以時尚俐落的運動鞋配搭深色長褲和簡單外套。"},{"en":"Sleek trainers can look more polished than bulky running shoes.","zh":"時尚俐落的運動鞋可以比厚重跑鞋顯得更精緻。"},{"en":"Their clean design helps sports shoes fit more easily into smart-casual outfits.","zh":"它們整潔的設計令運動鞋更容易融入半正式休閒造型。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"an office lift","meaning":"辦公室升降機","examples":[{"en":"Sleek trainers may appear in an office lift.","zh":"時尚俐落的運動鞋可能出現在辦公室升降機裏。"},{"en":"An office lift is an elevator inside a workplace or office building.","zh":"辦公室升降機是工作場所或辦公大樓內的電梯。"},{"en":"Workers crowded into the office lift during the morning rush.","zh":"早上繁忙時間，員工擠進辦公室升降機。"},{"en":"Seeing trainers in an office lift shows that casual footwear has entered professional spaces.","zh":"在辦公室升降機看到運動鞋，反映休閒鞋履已進入專業工作環境。"},{"en":"Everyday fashion can be observed in ordinary places such as an office lift, train or café.","zh":"日常時尚可以在辦公室升降機、列車或咖啡店等普通地方觀察到。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"a café meeting","meaning":"咖啡店會面","examples":[{"en":"A hoodie may be seen in a café meeting.","zh":"在咖啡店會面時可能會看到有人穿連帽衫。"},{"en":"A café meeting is an informal discussion or appointment held in a coffee shop.","zh":"咖啡店會面是在咖啡店進行的較非正式討論或約會。"},{"en":"The designer met her client for a café meeting before work.","zh":"那位設計師上班前與客戶進行了一次咖啡店會面。"},{"en":"Casual clothes are common at a café meeting because the setting is less formal than an office boardroom.","zh":"咖啡店會面比辦公室會議室較不正式，所以休閒服裝十分常見。"},{"en":"A café meeting shows how work and leisure spaces increasingly overlap.","zh":"咖啡店會面反映工作與休閒空間越來越互相重疊。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"yoga pants","meaning":"瑜伽褲","examples":[{"en":"Yoga pants can travel from a fitness studio to the supermarket.","zh":"瑜伽褲可以從健身工作室一路穿到超級市場。"},{"en":"Yoga pants are close-fitting, flexible trousers originally designed for yoga and exercise.","zh":"瑜伽褲是貼身而有彈性的長褲，原本為瑜伽和運動而設計。"},{"en":"Many people wear yoga pants for stretching, walking or everyday errands.","zh":"很多人穿瑜伽褲伸展、步行或處理日常雜務。"},{"en":"Their comfort and simple shape make yoga pants easy to wear outside the gym.","zh":"瑜伽褲舒適而款式簡單，因此容易在健身室以外穿着。"},{"en":"Yoga pants show how clothing designed for exercise can become ordinary daily wear.","zh":"瑜伽褲反映原本為運動而設計的服裝如何變成普通日常服。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"a fitness studio","meaning":"健身工作室","examples":[{"en":"Yoga pants may travel from a fitness studio to the supermarket.","zh":"瑜伽褲可以從健身工作室一路穿到超級市場。"},{"en":"A fitness studio is a place where people attend exercise classes such as yoga, Pilates or group training.","zh":"健身工作室是人們參加瑜伽、普拉提或團體訓練等運動課堂的地方。"},{"en":"She joined an evening class at a small fitness studio near her office.","zh":"她在辦公室附近一間小型健身工作室參加晚間課堂。"},{"en":"People often arrive at a fitness studio already wearing comfortable exercise clothes.","zh":"人們前往健身工作室時，常已穿上舒適運動服。"},{"en":"Athleisure makes it easier to go directly from a fitness studio to another daily activity.","zh":"運動休閒服飾令人更容易由健身工作室直接前往另一項日常活動。"}],"source":"2018 Q6.pdf","sourcePage":1},{"front":"without looking out of place","meaning":"不顯得格格不入","examples":[{"en":"Yoga pants can be worn in many places without looking out of place.","zh":"瑜伽褲可以在很多地方穿着而不顯得格格不入。"},{"en":"“Without looking out of place” means without appearing unsuitable, strange or inappropriate in that setting.","zh":"「without looking out of place」表示在某個場合不會顯得不合適、奇怪或不恰當。"},{"en":"A simple jacket can be worn at a casual dinner without looking out of place.","zh":"一件簡單外套可以在休閒晚餐中穿着，而不顯得格格不入。"},{"en":"Modern trainers can enter offices without looking out of place if the dress code is relaxed.","zh":"如果辦公室衣着規定較寬鬆，現代運動鞋在辦公室也不會顯得格格不入。"},{"en":"Fashion becomes widely accepted when people can wear it in many settings without looking out of place.","zh":"當一種時尚可以在很多場合穿着而不顯得格格不入，它便會更廣泛被接受。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"reconsider what they expect from","meaning":"重新思考對……的期望","examples":[{"en":"This shift has made consumers reconsider what they expect from clothing.","zh":"這種轉變令消費者重新思考對服裝的期望。"},{"en":"To reconsider what they expect from something means to think again about the qualities or benefits they believe it should provide.","zh":"「reconsider what they expect from」表示重新思考某樣東西應提供哪些特質或好處。"},{"en":"Online learning made students reconsider what they expect from a classroom.","zh":"網上學習令學生重新思考對課室的期望。"},{"en":"Busy lifestyles make consumers reconsider what they expect from everyday clothes.","zh":"忙碌的生活方式令消費者重新思考對日常服裝的期望。"},{"en":"People may begin demanding comfort, flexibility and style once they reconsider what clothing should do for them.","zh":"當人們重新思考衣服應為自己做到甚麼，就可能開始要求舒適、靈活和時尚兼備。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"be pushed to design","meaning":"被推動去設計","examples":[{"en":"Fashion brands have been pushed to design outfits that offer comfort and style.","zh":"時裝品牌被推動去設計兼具舒適和時尚的服裝。"},{"en":"To be pushed to design something means to face pressure or strong demand that encourages new designs.","zh":"「be pushed to design」表示受到壓力或強烈需求，因而被促使作出新設計。"},{"en":"Rising temperatures have pushed companies to design cooler school uniforms.","zh":"氣溫上升推動公司設計更涼快的校服。"},{"en":"Consumer demand has pushed fashion brands to design clothes suitable for both movement and public settings.","zh":"消費者需求推動時裝品牌設計既適合活動又適合公眾場合的服裝。"},{"en":"Companies are often pushed to change when customers’ needs and expectations change.","zh":"當顧客需要和期望改變，公司往往會被推動去改變。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"offer comfort and style","meaning":"提供舒適感和時尚感","examples":[{"en":"Modern outfits often offer comfort and style at the same time.","zh":"現代服裝常同時提供舒適感和時尚感。"},{"en":"To offer comfort and style means to be pleasant to wear while also looking attractive or fashionable.","zh":"提供舒適感和時尚感表示衣服既舒服好穿，同時外觀吸引和時尚。"},{"en":"Soft trousers with a clean cut can offer comfort and style during a long workday.","zh":"柔軟而剪裁俐落的長褲，可以在漫長工作日提供舒適感和時尚感。"},{"en":"Athleisure succeeds because it tries to offer comfort and style rather than forcing people to choose one.","zh":"運動休閒服飾成功，是因為它嘗試同時提供舒適和時尚，而不是逼人二選一。"},{"en":"Clothing that offers comfort and style can suit both practical needs and appearance.","zh":"同時提供舒適感和時尚感的衣服，可以兼顧實際需要和外觀。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"at the same time","meaning":"同時","examples":[{"en":"Athleisure offers comfort, movement and style at the same time.","zh":"運動休閒服飾同時提供舒適、活動自由和時尚感。"},{"en":"“At the same time” means two or more things happen or are true together.","zh":"「at the same time」表示兩件或以上事情同時發生或成立。"},{"en":"This bag is light and strong at the same time.","zh":"這個袋同時輕巧又堅固。"},{"en":"Modern clothes can look relaxed and presentable at the same time.","zh":"現代服裝可以同時看起來休閒又得體。"},{"en":"The phrase is useful when one product or situation provides several qualities simultaneously.","zh":"當某項產品或情況同時具備幾種特質時，可以使用這個片語。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"the rise of athleisure","meaning":"運動休閒服飾的興起","examples":[{"en":"The rise of athleisure is not a sudden accident.","zh":"運動休閒服飾的興起並不是突然出現的偶然現象。"},{"en":"The rise of athleisure means the growing popularity and acceptance of sports-inspired casual clothing.","zh":"運動休閒服飾的興起是指這類受運動風格啟發的休閒服裝越來越受歡迎和被接受。"},{"en":"The rise of athleisure can be seen in offices, shopping centres and social media.","zh":"辦公室、商場和社交媒體上都可以看到運動休閒服飾的興起。"},{"en":"Changing lifestyles and health awareness have contributed to the rise of athleisure.","zh":"生活方式改變和健康意識提高，都促成了運動休閒服飾的興起。"},{"en":"A fashion trend “rises” when more people begin buying, wearing and accepting it.","zh":"當更多人開始購買、穿着和接受一種時尚，它便可說正在「興起」。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"a sudden accident","meaning":"突然出現的偶然現象","examples":[{"en":"The rise of athleisure is not a sudden accident.","zh":"運動休閒服飾的興起並不是突然出現的偶然現象。"},{"en":"“A sudden accident” here means something that appeared unexpectedly without deeper causes or development.","zh":"「a sudden accident」在這裏表示某件事沒有深層原因或發展便意外出現。"},{"en":"The popularity of smartphones was not a sudden accident; it followed years of technological change.","zh":"智能手機受歡迎並不是突然出現的偶然現象，而是多年科技轉變的結果。"},{"en":"Athleisure did not become popular by chance but grew from changes in work, health and fashion.","zh":"運動休閒服飾並非偶然流行，而是由工作、健康和時尚的改變逐步形成。"},{"en":"Saying something is not a sudden accident means there are understandable reasons behind it.","zh":"說某件事不是突然出現的偶然現象，表示背後其實有可以理解的原因。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"reflect changing lifestyles","meaning":"反映生活方式的轉變","examples":[{"en":"Athleisure reflects changing lifestyles and new ideas about fashion.","zh":"運動休閒服飾反映生活方式的轉變和新的時尚觀念。"},{"en":"To reflect changing lifestyles means to show how people’s daily habits, needs and routines are becoming different.","zh":"反映生活方式的轉變是指顯示人們的日常習慣、需要和生活節奏如何正在改變。"},{"en":"Smaller homes reflect changing lifestyles in crowded cities.","zh":"較小的住宅反映擠迫城市中生活方式的轉變。"},{"en":"Clothes that work for commuting, exercise and social activities reflect changing lifestyles.","zh":"能配合通勤、運動和社交活動的衣服反映生活方式的轉變。"},{"en":"Fashion often reflects changing lifestyles because people choose clothes that fit how they actually live.","zh":"時尚往往反映生活方式的轉變，因為人們會選擇配合實際生活的衣服。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"health-conscious culture","meaning":"注重健康的文化","examples":[{"en":"Athleisure reflects a stronger health-conscious culture.","zh":"運動休閒服飾反映一種更強的注重健康文化。"},{"en":"A health-conscious culture is a society in which people pay strong attention to exercise, diet and physical well-being.","zh":"注重健康的文化是人們高度重視運動、飲食和身體健康的社會文化。"},{"en":"Healthy food labels become more important in a health-conscious culture.","zh":"在注重健康的文化中，健康食品標籤會變得更重要。"},{"en":"A health-conscious culture encourages many people to treat exercise as part of ordinary life.","zh":"注重健康的文化鼓勵很多人把運動視為普通生活的一部分。"},{"en":"Athleisure fits such a culture because its appearance is closely linked with fitness and activity.","zh":"運動休閒服飾適合這種文化，因為其形象與健身和活動密切相關。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"the growing influence of","meaning":"……日益增長的影響力","examples":[{"en":"The trend shows the growing influence of social media.","zh":"這股潮流顯示社交媒體日益增長的影響力。"},{"en":"“The growing influence of” means something is becoming increasingly powerful in shaping behaviour or opinions.","zh":"「the growing influence of」表示某事物在塑造行為或意見方面變得越來越有力量。"},{"en":"The growing influence of online reviews affects where people eat.","zh":"網上評價日益增長的影響力會影響人們到哪裏吃飯。"},{"en":"Fashion trends reveal the growing influence of celebrities and influencers on young consumers.","zh":"時尚潮流反映名人和KOL對年輕消費者日益增長的影響力。"},{"en":"When influence grows, people increasingly notice, copy or respond to what that source presents.","zh":"當影響力增加，人們會越來越留意、模仿或回應該來源所展示的內容。"}],"source":"2018 Q6.pdf","sourcePage":2},{"front":"what people see as fashionable","meaning":"人們眼中時尚的事物","examples":[{"en":"Social media affects what people see as fashionable.","zh":"社交媒體影響人們眼中甚麼是時尚。"},{"en":"“What people see as fashionable” means the clothes or styles people consider attractive, modern and socially desirable.","zh":"「what people see as fashionable」表示人們認為吸引、現代而符合社會潮流的服裝或風格。"},{"en":"Celebrities can change what teenagers see as fashionable.","zh":"名人可以改變青少年眼中甚麼是時尚。"},{"en":"Repeated images online may slowly influence what people see as fashionable.","zh":"網上反覆出現的圖片可能慢慢影響人們眼中時尚的事物。"},{"en":"Fashion is partly social because people’s ideas about what looks good are influenced by what they repeatedly see around them.","zh":"時尚部分屬於社會現象，因為人們對甚麼好看的看法會受到周圍反覆看見的東西影響。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"the popularity of","meaning":"……的受歡迎程度","examples":[{"en":"The popularity of athleisure comes partly from convenience.","zh":"運動休閒服飾的受歡迎程度部分來自方便性。"},{"en":"“The popularity of” means how widely liked, chosen or accepted something is.","zh":"「the popularity of」表示某事物有多廣泛受到喜愛、選擇或接受。"},{"en":"The popularity of online shopping increased because it saves time.","zh":"網上購物的受歡迎程度增加，是因為它能節省時間。"},{"en":"The popularity of trainers has grown as workplaces have become more casual.","zh":"隨着工作場所變得較休閒，運動鞋的受歡迎程度也有所上升。"},{"en":"When explaining the popularity of something, we usually look at the reasons many people choose it.","zh":"解釋某事物為何受歡迎時，通常要分析為甚麼很多人會選擇它。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"modern life demands convenience","meaning":"現代生活講求方便","examples":[{"en":"Modern life demands convenience from the clothes people wear.","zh":"現代生活要求人們所穿的衣服具有方便性。"},{"en":"“Modern life demands convenience” means today’s routines make practical and time-saving choices increasingly necessary.","zh":"「modern life demands convenience」表示今天的生活節奏令實際和省時的選擇變得越來越必要。"},{"en":"Modern life demands convenience because many people combine work, travel and family duties in one day.","zh":"現代生活講求方便，因為很多人一天內要兼顧工作、交通和家庭責任。"},{"en":"Clothing that requires constant changing may not suit a lifestyle that demands convenience.","zh":"需要經常更換的服裝，未必適合講求方便的生活方式。"},{"en":"Convenience becomes more valuable when schedules are busy and people move frequently between places.","zh":"當日程忙碌而人們經常在不同地方移動時，方便性便更有價值。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"a fast-moving city","meaning":"節奏急速的城市","examples":[{"en":"Hong Kong is a fast-moving city where people are often busy.","zh":"香港是一個節奏急速、很多人都十分忙碌的城市。"},{"en":"A fast-moving city is a city where work, transport, business and daily activities happen at a quick pace.","zh":"節奏急速的城市是工作、交通、商業和日常活動都以快速步伐進行的城市。"},{"en":"In a fast-moving city, commuters may eat breakfast while travelling to work.","zh":"在節奏急速的城市，通勤者可能一邊乘車上班一邊吃早餐。"},{"en":"Flexible clothing is useful in a fast-moving city because plans can change quickly.","zh":"在節奏急速的城市，靈活的服裝很有用，因為計劃可以很快改變。"},{"en":"Life in a fast-moving city often leaves people with little time for unnecessary changes or delays.","zh":"節奏急速的城市生活往往令人在不必要的更換或延誤上沒有太多時間。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"move from one activity to another","meaning":"從一項活動趕到另一項活動","examples":[{"en":"Many people move from one activity to another with little rest.","zh":"很多人幾乎沒有休息便從一項活動趕到另一項活動。"},{"en":"To move from one activity to another means to finish one task and quickly begin a different one.","zh":"「move from one activity to another」表示完成一項事情後，很快又開始另一項活動。"},{"en":"A student may move from lessons to sports practice and then to homework.","zh":"學生可能由上課趕去運動訓練，再回家做功課。"},{"en":"Busy workers move from one activity to another throughout the day.","zh":"忙碌的上班族一整天都從一項活動趕到另一項活動。"},{"en":"Clothes that suit several situations are useful when people constantly move from one activity to another.","zh":"當人們經常從一項活動趕到另一項活動，能適合不同場合的衣服便很實用。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"with little breathing room","meaning":"幾乎沒有喘息空間","examples":[{"en":"Many people move through the day with little breathing room.","zh":"很多人一天的行程幾乎沒有喘息空間。"},{"en":"“With little breathing room” means with very little free time, rest or space between activities.","zh":"「with little breathing room」表示活動之間幾乎沒有空閒、休息或緩衝時間。"},{"en":"Her timetable was so full that she had little breathing room between classes.","zh":"她的時間表排得很滿，兩堂課之間幾乎沒有喘息空間。"},{"en":"A packed workday leaves little breathing room for changing outfits several times.","zh":"工作日程排得太滿，幾乎沒有時間讓人反覆換衣服。"},{"en":"When people have little breathing room, convenient choices become more valuable.","zh":"當人們幾乎沒有喘息空間，方便的選擇便更加重要。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"attend lessons","meaning":"上課","examples":[{"en":"A student may attend lessons and then go to tutorial classes.","zh":"學生可能先上課，然後再去補習班。"},{"en":"To attend lessons means to go to and take part in classes where teaching takes place.","zh":"「attend lessons」表示前往並參與有教學活動的課堂。"},{"en":"Students must attend lessons regularly if they want to keep up with the course.","zh":"學生如果想跟上課程進度，就必須定期上課。"},{"en":"Someone may attend lessons in the morning and play sports in the afternoon.","zh":"有人可能早上上課，下午參加運動。"},{"en":"Clothing that remains comfortable for hours is useful for students who attend lessons all day.","zh":"對整天都要上課的學生來說，長時間仍然舒適的衣服很實用。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"tutorial classes","meaning":"補習班","examples":[{"en":"A student may go to tutorial classes after school.","zh":"學生放學後可能要去補習班。"},{"en":"Tutorial classes are extra lessons, often outside normal school hours, designed to help students practise or improve academically.","zh":"補習班通常是在正常上課時間以外，幫助學生練習或提升學業表現的額外課堂。"},{"en":"Many students attend tutorial classes before important examinations.","zh":"很多學生在重要考試前會參加補習班。"},{"en":"Tutorial classes can make a student’s day longer because they begin after regular lessons end.","zh":"因為補習班在正常課堂後才開始，學生一天的行程會變得更長。"},{"en":"Students with tutorial classes may prefer clothing that remains comfortable from morning until evening.","zh":"要去補習班的學生可能更喜歡從早到晚仍然舒適的服裝。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"squeeze in a short workout","meaning":"抽時間做短暫運動","examples":[{"en":"A student may squeeze in a short workout before returning home.","zh":"學生回家前可能抽時間做短暫運動。"},{"en":"To squeeze in a short workout means to find a small amount of time for exercise within a busy schedule.","zh":"「squeeze in a short workout」表示在繁忙日程中勉強找出一小段時間做運動。"},{"en":"She squeezed in a twenty-minute workout between work and dinner.","zh":"她在工作和晚餐之間抽了二十分鐘做短暫運動。"},{"en":"Comfortable clothes make it easier to squeeze in a short workout without changing first.","zh":"舒適服裝令人更容易不用先換衣服便抽時間做短暫運動。"},{"en":"People with packed schedules often exercise in short periods whenever they can squeeze them in.","zh":"日程排得很滿的人常在可以騰出時間時做短時間運動。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"commute by MTR","meaning":"乘港鐵通勤","examples":[{"en":"An office worker may commute by MTR every day.","zh":"上班族可能每天乘港鐵通勤。"},{"en":"To commute by MTR means to travel regularly between home and work or school using Hong Kong’s railway system.","zh":"乘港鐵通勤是指經常使用香港鐵路系統往返住所與工作或學校地點。"},{"en":"Thousands of people commute by MTR during the morning rush hour.","zh":"每天早上繁忙時間，數以千計的人乘港鐵通勤。"},{"en":"Comfortable shoes are useful for workers who commute by MTR and walk between stations and offices.","zh":"對需要乘港鐵並在車站和辦公室之間步行的上班族來說，舒適鞋履很有用。"},{"en":"Daily commuting can involve standing, walking and climbing stairs, not only sitting on a train.","zh":"日常通勤不只是坐車，還可能包括站立、步行和上樓梯。"}],"source":"2018 Q6.pdf","sourcePage":3},{"front":"climb several flights of stairs","meaning":"爬幾層樓梯","examples":[{"en":"An office worker may climb several flights of stairs during the day.","zh":"上班族一天內可能要爬幾層樓梯。"},{"en":"To climb several flights of stairs means to walk up multiple levels of a staircase.","zh":"「climb several flights of stairs」表示沿樓梯向上走幾個樓層。"},{"en":"The lift was broken, so we had to climb several flights of stairs.","zh":"升降機壞了，所以我們要爬幾層樓梯。"},{"en":"Flexible trousers are useful if a worker often climbs several flights of stairs.","zh":"如果員工經常要爬幾層樓梯，有彈性的長褲便很實用。"},{"en":"Ordinary city life can involve more physical movement than people realise.","zh":"普通城市生活涉及的身體活動，可能比人們想像中更多。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"sit through meetings","meaning":"捱完整場會議","examples":[{"en":"An office worker may sit through meetings for hours.","zh":"上班族可能要坐幾個小時捱完整場會議。"},{"en":"To sit through something means to remain seated until a long event, meeting or performance finishes.","zh":"「sit through」表示一直坐着，直到一場長時間活動、會議或表演結束。"},{"en":"We had to sit through a three-hour presentation before lunch.","zh":"午飯前，我們要坐足三小時捱完整場簡報。"},{"en":"Comfortable clothing matters when workers sit through meetings for long periods.","zh":"員工長時間捱完整場會議時，舒適服裝十分重要。"},{"en":"“Sit through” often suggests that an activity feels long or requires patience.","zh":"「sit through」常帶有活動很長、需要耐性捱過去的感覺。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"run errands","meaning":"辦雜務","examples":[{"en":"An office worker may run errands after work.","zh":"上班族下班後可能要辦雜務。"},{"en":"To run errands means to go out and complete small practical tasks such as shopping, collecting items or paying bills.","zh":"「run errands」表示外出去完成購物、取物件或繳費等小型實際任務。"},{"en":"I need to run errands after work, including buying groceries and collecting a parcel.","zh":"我下班後要辦幾件雜務，包括買菜和取包裹。"},{"en":"Comfortable clothes are useful when someone has to run errands around the city.","zh":"當一個人要在城市裏四處辦雜務，舒適服裝便很實用。"},{"en":"Running errands often involves walking between several places in a short period.","zh":"辦雜務通常需要在短時間內步行前往幾個不同地方。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"a packed schedule","meaning":"滿滿的日程","examples":[{"en":"Changing clothes repeatedly is impractical in a packed schedule.","zh":"在滿滿的日程中反覆換衣服並不切實際。"},{"en":"A packed schedule is a timetable filled with many activities and very little free time.","zh":"滿滿的日程是安排了很多活動，而幾乎沒有空閒時間的時間表。"},{"en":"She had a packed schedule of classes, meetings and family duties.","zh":"她的日程排滿了課堂、會議和家庭責任。"},{"en":"A packed schedule makes convenience more important because there is little time for unnecessary tasks.","zh":"滿滿的日程令人更加重視方便，因為沒有太多時間處理不必要的事情。"},{"en":"Clothes that work in several settings are useful for anyone with a packed schedule.","zh":"對日程排得很滿的人來說，能適合不同場合的衣服很實用。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"changing clothes repeatedly","meaning":"反覆更換衣服","examples":[{"en":"Changing clothes repeatedly is impractical for busy people.","zh":"對忙碌的人來說，反覆更換衣服並不切實際。"},{"en":"“Changing clothes repeatedly” means putting on different outfits several times during the same day.","zh":"「changing clothes repeatedly」表示一天內多次換上不同服裝。"},{"en":"Someone who goes from work to exercise to dinner may dislike changing clothes repeatedly.","zh":"一個人由工作去運動再去晚餐，可能不喜歡反覆更換衣服。"},{"en":"Athleisure reduces the need for changing clothes repeatedly between activities.","zh":"運動休閒服飾減少了不同活動之間反覆更換衣服的需要。"},{"en":"Repeated outfit changes take time and require carrying extra clothing.","zh":"反覆換衣服既花時間，也需要攜帶額外衣物。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"be impractical","meaning":"不切實際","examples":[{"en":"Changing clothes repeatedly is impractical in modern city life.","zh":"在現代城市生活中，反覆換衣服並不切實際。"},{"en":"To be impractical means to be inconvenient, difficult or unsuitable in real-life conditions.","zh":"「be impractical」表示在現實情況中不方便、困難或不合用。"},{"en":"Carrying five pairs of shoes on a short trip would be impractical.","zh":"短途旅行帶五雙鞋會很不切實際。"},{"en":"Formal clothing can be impractical if someone spends the whole day walking and travelling.","zh":"如果一個人整天步行和乘車，正式服裝可能並不切實際。"},{"en":"Something may look attractive in theory but still be impractical in daily use.","zh":"某樣東西理論上可以很好看，但實際使用時仍可能不切實際。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"solve this problem by","meaning":"透過……解決這個問題","examples":[{"en":"Athleisure solves this problem by combining flexibility with presentability.","zh":"運動休閒服飾透過結合靈活性和得體外觀來解決這個問題。"},{"en":"“Solve this problem by” introduces the method used to deal with a difficulty.","zh":"「solve this problem by」用來帶出處理某個困難的方法。"},{"en":"The school solved the transport problem by adding another bus route.","zh":"學校透過增加另一條巴士路線來解決交通問題。"},{"en":"Athleisure solves the problem of frequent outfit changes by working in several settings.","zh":"運動休閒服飾透過適合多種場合，解決頻繁換衣服的問題。"},{"en":"This structure clearly connects a problem with the action that addresses it.","zh":"這個句式清楚把問題與解決它的行動連接起來。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"combine flexibility with presentability","meaning":"結合靈活性和得體外觀","examples":[{"en":"Athleisure combines flexibility with presentability.","zh":"運動休閒服飾結合靈活性和得體外觀。"},{"en":"To combine flexibility with presentability means to allow easy movement while still looking neat enough for public situations.","zh":"結合靈活性和得體外觀是指衣服既方便活動，同時看起來足夠整齊，適合公眾場合。"},{"en":"Stretch trousers can combine flexibility with presentability when they have a clean cut.","zh":"有彈性的長褲如果剪裁整潔，就可以結合靈活性和得體外觀。"},{"en":"Office-friendly athleisure combines flexibility with presentability better than old-style gym clothes.","zh":"適合辦公室的運動休閒服飾，比舊式健身服更能結合靈活性和得體外觀。"},{"en":"Combining these qualities helps one outfit work across several parts of the day.","zh":"結合這兩種特質，可以令一套衣服適合一天內多個場合。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"presentability","meaning":"得體外觀","examples":[{"en":"Modern athleisure gives people comfort and presentability.","zh":"現代運動休閒服飾為人提供舒適感和得體外觀。"},{"en":"Presentability means looking neat, suitable and respectable enough for other people to see you in public.","zh":"得體外觀表示看起來整潔、合適和足以在公眾面前令人感到體面。"},{"en":"A clean shirt improves presentability even when the overall outfit is casual.","zh":"即使整體造型較休閒，一件乾淨恤衫也能提升得體外觀。"},{"en":"Modern joggers offer presentability when they are well cut and made from quality fabric.","zh":"現代運動褲如果剪裁良好並使用優質布料，也可以有得體外觀。"},{"en":"Presentability matters when comfortable clothes are worn outside private or exercise settings.","zh":"當舒適服裝穿到私人或運動場合以外時，得體外觀便很重要。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"stretchy joggers","meaning":"有彈性的運動長褲","examples":[{"en":"Stretchy joggers allow people to move comfortably.","zh":"有彈性的運動長褲讓人可以舒適活動。"},{"en":"Stretchy joggers are casual sports-style trousers made from fabric that can expand and move with the body.","zh":"有彈性的運動長褲是使用能隨身體伸展和活動的布料製成的休閒運動風長褲。"},{"en":"She wore stretchy joggers on the flight because they were comfortable for sitting and walking.","zh":"她乘飛機時穿有彈性的運動長褲，因為無論坐着還是步行都很舒服。"},{"en":"Stretchy joggers are useful for people who climb stairs or travel frequently.","zh":"對經常爬樓梯或四處乘車的人來說，有彈性的運動長褲很實用。"},{"en":"Their flexible fabric makes them more practical than stiff trousers for active days.","zh":"與硬挺長褲相比，它們有彈性的布料更適合活動量大的日子。"}],"source":"2018 Q6.pdf","sourcePage":4},{"front":"breathable tops","meaning":"透氣上衣","examples":[{"en":"Breathable tops are useful in hot and busy cities.","zh":"透氣上衣在炎熱而繁忙的城市很實用。"},{"en":"Breathable tops are shirts made from materials that allow heat and moisture to escape easily.","zh":"透氣上衣是使用能讓熱力和濕氣較容易散出的物料製成的上衣。"},{"en":"Runners often wear breathable tops so sweat can dry more quickly.","zh":"跑手常穿透氣上衣，讓汗水更快乾。"},{"en":"A breathable top is comfortable when someone walks long distances in hot weather.","zh":"炎熱天氣下長距離步行時，透氣上衣會比較舒服。"},{"en":"Breathable fabric helps clothing remain comfortable when the body becomes warm.","zh":"當身體變熱，透氣布料可以幫助衣服保持舒適。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"lightweight jackets","meaning":"輕便外套","examples":[{"en":"Lightweight jackets are easy to wear throughout the day.","zh":"輕便外套很容易整天穿着。"},{"en":"Lightweight jackets are outer garments made to provide some protection without feeling heavy or bulky.","zh":"輕便外套是提供一定保護，但不會感覺沉重或厚大的外衣。"},{"en":"She carried a lightweight jacket because the office air conditioning was cold.","zh":"她帶了一件輕便外套，因為辦公室冷氣很冷。"},{"en":"Lightweight jackets are useful when temperatures change between outdoors and indoor spaces.","zh":"當戶外和室內溫度不同，輕便外套很實用。"},{"en":"A light jacket can be layered over different outfits without becoming inconvenient.","zh":"輕便外套可以套在不同衣服外面，而不會帶來太大不便。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"without feeling restricted","meaning":"不覺得受束縛","examples":[{"en":"Athleisure allows people to move without feeling restricted.","zh":"運動休閒服飾令人活動時不覺得受束縛。"},{"en":"“Without feeling restricted” means without clothing making movement tight, difficult or uncomfortable.","zh":"「without feeling restricted」表示衣服不會令人活動時感到緊、困難或不舒服。"},{"en":"Stretch fabric lets cyclists bend their knees without feeling restricted.","zh":"有彈性的布料讓單車手屈膝時不覺得受束縛。"},{"en":"Loose and flexible clothes help commuters walk quickly without feeling restricted.","zh":"鬆身而靈活的衣服令通勤者快步走時不覺得受束縛。"},{"en":"Freedom of movement is important when clothing must support both sitting and physical activity.","zh":"當衣服既要配合坐着也要配合活動，自由活動便十分重要。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"neat enough to be worn in public","meaning":"整齊得足以在公眾場合穿着","examples":[{"en":"Many designs are neat enough to be worn in public.","zh":"很多設計都整齊得足以在公眾場合穿着。"},{"en":"“Neat enough to be worn in public” means tidy and presentable enough for ordinary social or public settings.","zh":"「neat enough to be worn in public」表示足夠整潔和得體，可以在普通社交或公眾場合穿着。"},{"en":"These joggers are neat enough to be worn in public because the cut is simple and clean.","zh":"這條運動褲剪裁簡潔，因此整齊得足以在公眾場合穿着。"},{"en":"A plain sports jacket may be neat enough to be worn in public even if it was designed for exercise.","zh":"即使一件簡單運動外套原本為運動而設計，也可能整齊得足以在公眾場合穿着。"},{"en":"Athleisure succeeds when comfort does not make the wearer look untidy.","zh":"當舒適不會令穿着者看起來凌亂，運動休閒服飾便更容易成功。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"give the impression that","meaning":"給人……的印象","examples":[{"en":"Modern designs do not give the impression that the wearer has just left a football pitch.","zh":"現代設計不會給人穿着者剛離開足球場的印象。"},{"en":"To give the impression that something is true means to make people think or feel that it is probably the case.","zh":"「give the impression that」表示令別人認為或感覺某種情況可能是真的。"},{"en":"His formal jacket gave the impression that he was attending an important meeting.","zh":"他的正式外套給人他要參加重要會議的印象。"},{"en":"Poorly fitted sportswear may give the impression that the wearer has just finished training.","zh":"不合身的運動服可能給人穿着者剛完成訓練的印象。"},{"en":"Clothing influences first impressions because style can suggest where someone has been or what they are doing.","zh":"衣服會影響第一印象，因為風格可以令人猜想一個人剛去過哪裏或正在做甚麼。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"the wearer","meaning":"穿着者","examples":[{"en":"The wearer can look casual without seeming careless.","zh":"穿着者可以看起來休閒而不顯得隨便。"},{"en":"The wearer is the person who has a particular piece of clothing, footwear or accessory on their body.","zh":"穿着者是身上穿着某件衣物、鞋履或配飾的人。"},{"en":"A well-cut jacket can make the wearer appear taller and more polished.","zh":"剪裁良好的外套可以令穿着者看起來更高和更精緻。"},{"en":"Comfortable clothing should support the wearer rather than restrict movement.","zh":"舒適服裝應該配合穿着者，而不是限制活動。"},{"en":"Designers consider how fabric, shape and colour will look and feel on the wearer.","zh":"設計師會考慮布料、剪裁和顏色穿在穿着者身上時的外觀和感覺。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"a football pitch","meaning":"足球場","examples":[{"en":"The wearer does not look as if they have just left a football pitch.","zh":"穿着者看起來不像剛離開足球場。"},{"en":"A football pitch is the marked field where a football match is played.","zh":"足球場是有清楚標記、用來進行足球比賽的場地。"},{"en":"Players ran onto the football pitch before the match began.","zh":"比賽開始前，球員跑進足球場。"},{"en":"Traditional sportswear may look natural on a football pitch but too casual in some offices.","zh":"傳統運動服在足球場很自然，但在某些辦公室可能顯得太休閒。"},{"en":"Athleisure aims to keep some sporting features without making the wearer look ready for a match.","zh":"運動休閒服飾希望保留部分運動元素，同時不令穿着者看起來像準備落場比賽。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"fit the rhythm of urban life","meaning":"符合城市生活節奏","examples":[{"en":"Athleisure fits the rhythm of urban life.","zh":"運動休閒服飾符合城市生活節奏。"},{"en":"To fit the rhythm of urban life means to suit the fast pace, frequent movement and changing demands of city living.","zh":"符合城市生活節奏是指適合城市生活快速、頻繁移動和不斷變化的需要。"},{"en":"Contactless payment fits the rhythm of urban life because it saves time.","zh":"感應式付款符合城市生活節奏，因為它能節省時間。"},{"en":"Flexible clothing fits the rhythm of urban life when people move between work, transport and leisure quickly.","zh":"當人們快速穿梭於工作、交通和休閒之間，靈活服裝便符合城市生活節奏。"},{"en":"Products succeed in cities when they match how people actually move through the day.","zh":"當產品配合城市人實際一天的活動方式，就更容易成功。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"urban life","meaning":"城市生活","examples":[{"en":"Urban life is often quick, crowded and unpredictable.","zh":"城市生活往往急速、擠迫而難以預測。"},{"en":"Urban life means everyday living in a city or densely populated town.","zh":"城市生活是指在城市或人口密集地區的日常生活。"},{"en":"Urban life may involve public transport, apartment living and busy commercial areas.","zh":"城市生活可能包括使用公共交通、住在公寓和經常出入繁忙商業區。"},{"en":"People in urban life often travel between several places in one day.","zh":"過城市生活的人一天內常要前往幾個不同地方。"},{"en":"Clothing for urban life needs to handle both movement and changing social situations.","zh":"適合城市生活的衣服需要同時應付活動和不斷改變的社交場合。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"quick, crowded and mobile","meaning":"急速、擠迫而流動性高","examples":[{"en":"Modern urban life is quick, crowded and mobile.","zh":"現代城市生活急速、擠迫而流動性高。"},{"en":"“Quick, crowded and mobile” describes a lifestyle that moves fast, involves many people and requires frequent travel.","zh":"「quick, crowded and mobile」形容一種節奏快、人多而需要頻繁移動的生活方式。"},{"en":"Railway stations are especially quick, crowded and mobile during rush hour.","zh":"繁忙時間的鐵路車站特別急速、擠迫而流動性高。"},{"en":"Clothing for a quick, crowded and mobile lifestyle should allow easy movement.","zh":"適合急速、擠迫而流動性高生活的衣服，應方便活動。"},{"en":"These three qualities explain why city residents often value practicality.","zh":"這三個特點解釋了為甚麼城市居民往往重視實用性。"}],"source":"2018 Q6.pdf","sourcePage":5},{"front":"often unpredictable","meaning":"往往難以預測","examples":[{"en":"City life is quick, mobile and often unpredictable.","zh":"城市生活節奏快、流動性高，而且往往難以預測。"},{"en":"“Often unpredictable” means situations frequently change in ways that cannot be known in advance.","zh":"「often unpredictable」表示情況經常以事先無法知道的方式改變。"},{"en":"Weather can be unpredictable, so she always carries a light jacket.","zh":"天氣難以預測，所以她總會帶一件輕便外套。"},{"en":"Workdays are often unpredictable because meetings or errands can appear suddenly.","zh":"工作日往往難以預測，因為會議或雜務可能突然出現。"},{"en":"Versatile clothing is useful when daily plans are often unpredictable.","zh":"當每日計劃往往難以預測，多用途服裝便很實用。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"the growing desire to","meaning":"越來越渴望……","examples":[{"en":"Athleisure reflects the growing desire to look and feel healthy.","zh":"運動休閒服飾反映人們越來越渴望看起來和感覺都健康。"},{"en":"“The growing desire to” means more people increasingly want to do or achieve something.","zh":"「the growing desire to」表示越來越多人希望做某事或達成某個目標。"},{"en":"There is a growing desire to work more flexibly among younger employees.","zh":"年輕員工越來越渴望更靈活地工作。"},{"en":"The growing desire to live actively has increased interest in comfortable sports-inspired clothing.","zh":"人們越來越渴望過活躍生活，因此更有興趣購買舒適的運動風服裝。"},{"en":"A growing desire can influence markets when many consumers begin wanting the same thing.","zh":"當很多消費者開始想要同一樣東西，這種日益增長的渴望便會影響市場。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"look and feel healthy","meaning":"看起來和感覺都健康","examples":[{"en":"Many consumers want to look and feel healthy.","zh":"很多消費者希望看起來和感覺都健康。"},{"en":"To look and feel healthy means both appearing active or well and personally experiencing physical well-being.","zh":"看起來和感覺都健康，是指外表顯得有活力或健康，同時自己也感受到身體狀況良好。"},{"en":"Regular sleep can help people look and feel healthy.","zh":"定時睡眠可以幫助人看起來和感覺都健康。"},{"en":"Some people wear sports-inspired clothing because it helps them look and feel healthy even on non-exercise days.","zh":"有些人在沒有運動的日子也穿運動風服裝，因為這令他們看起來和感覺都健康。"},{"en":"Looking healthy is about appearance, while feeling healthy is about the body’s actual condition.","zh":"看起來健康關乎外表，而感覺健康則關乎身體實際狀況。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"no longer viewed merely as","meaning":"不再只被視為……","examples":[{"en":"Fitness is no longer viewed merely as a private hobby.","zh":"健身不再只被視為私人嗜好。"},{"en":"“No longer viewed merely as” means people have stopped seeing something as only one limited type of activity or idea.","zh":"「no longer viewed merely as」表示人們已不再把某事只看成一種有限的活動或概念。"},{"en":"Smartphones are no longer viewed merely as communication devices.","zh":"智能手機不再只被視為通訊工具。"},{"en":"Exercise is no longer viewed merely as something people do privately in a gym.","zh":"運動不再只被視為人們私下在健身室做的事情。"},{"en":"This phrase signals that society now gives something a broader meaning or role.","zh":"這個片語表示社會現在賦予某件事更廣泛的意義或角色。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"a private hobby","meaning":"私人嗜好","examples":[{"en":"Fitness is no longer just a private hobby.","zh":"健身不再只是一項私人嗜好。"},{"en":"A private hobby is an activity someone enjoys personally without necessarily making it part of their public identity.","zh":"私人嗜好是某人個人喜歡做，但未必會把它變成公開身份一部分的活動。"},{"en":"Painting at home can be a private hobby if someone never shares the work publicly.","zh":"如果一個人從不公開作品，在家畫畫可以是一項私人嗜好。"},{"en":"Fitness becomes more than a private hobby when people talk about it, post it online and use it to express identity.","zh":"當人們談論健身、在網上分享，並用它表達身份時，健身就不再只是私人嗜好。"},{"en":"Modern social media can turn private hobbies into visible parts of public life.","zh":"現代社交媒體可以把私人嗜好變成公開生活中可見的一部分。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"slowly but steadily","meaning":"緩慢但穩步地","examples":[{"en":"Fitness has slowly but steadily become part of many people’s identity.","zh":"健身已緩慢但穩步地成為很多人身份認同的一部分。"},{"en":"“Slowly but steadily” means change happens gradually but continuously and reliably.","zh":"「slowly but steadily」表示改變雖然逐漸發生，但持續而穩定。"},{"en":"The neighbourhood slowly but steadily became more environmentally friendly.","zh":"那個社區緩慢但穩步地變得更環保。"},{"en":"Athleisure slowly but steadily moved from gyms into everyday fashion.","zh":"運動休閒服飾緩慢但穩步地由健身室進入日常時尚。"},{"en":"This phrase describes progress that is not sudden but continues over time.","zh":"這個片語形容並非突然發生，但會隨時間持續的進展。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"become part of someone’s identity","meaning":"成為某人身分認同的一部分","examples":[{"en":"Fitness has become part of many people’s identity.","zh":"健身已成為很多人身分認同的一部分。"},{"en":"To become part of someone’s identity means to become one of the qualities or activities through which they understand and present who they are.","zh":"成為某人身份認同的一部分，是指成為他理解和向別人呈現自己是誰的其中一項重要特質或活動。"},{"en":"Music can become part of someone’s identity if it strongly shapes their friends and lifestyle.","zh":"如果音樂強烈影響一個人的朋友和生活方式，它可以成為其身份認同的一部分。"},{"en":"Exercise becomes part of someone’s identity when they see themselves as an active person.","zh":"當一個人把自己視為活躍的人，運動便會成為其身份認同的一部分。"},{"en":"Clothing can support identity by showing interests, values or the type of person someone wants to be.","zh":"衣着可以透過展示興趣、價值觀或想成為怎樣的人，來支持身份認同。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"quietly signal that","meaning":"默默傳達……","examples":[{"en":"Wearing athleisure can quietly signal that one is active and disciplined.","zh":"穿運動休閒服飾可以默默傳達一個人活躍而自律的形象。"},{"en":"To quietly signal that something is true means to suggest it indirectly without saying it openly.","zh":"「quietly signal that」表示不直接說出口，而是間接暗示某種情況。"},{"en":"Carrying a reusable bottle may quietly signal that someone cares about the environment.","zh":"攜帶可重用水樽可能默默傳達某人關心環境。"},{"en":"Running shoes may quietly signal that the wearer values fitness.","zh":"跑鞋可能默默傳達穿着者重視健身。"},{"en":"Clothing often sends small social messages even when the wearer says nothing.","zh":"即使穿着者甚麼也沒有說，衣着常會傳遞細小的社會訊息。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"active, disciplined and energetic","meaning":"活躍、自律而有活力","examples":[{"en":"Athleisure can suggest that the wearer is active, disciplined and energetic.","zh":"運動休閒服飾可以令人覺得穿着者活躍、自律而有活力。"},{"en":"“Active, disciplined and energetic” describes someone who moves often, controls their habits and appears full of energy.","zh":"「active, disciplined and energetic」形容經常活動、能控制自己習慣，而且看起來充滿精神的人。"},{"en":"Regular training may make an athlete seem active, disciplined and energetic.","zh":"定期訓練可以令運動員看起來活躍、自律而有活力。"},{"en":"Sports-inspired clothing can create an active, disciplined and energetic image even on a rest day.","zh":"即使在休息日，運動風服裝也能營造活躍、自律而有活力的形象。"},{"en":"Clothing can suggest these qualities, although appearance does not prove behaviour.","zh":"衣着可以令人聯想到這些特質，但外表並不能證明實際行為。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"on days when","meaning":"在……的日子","examples":[{"en":"People may wear athleisure even on days when they do little exercise.","zh":"即使在幾乎沒有做運動的日子，人們也可能穿運動休閒服飾。"},{"en":"“On days when” introduces a condition or situation that happens on particular days.","zh":"「on days when」用來帶出某些特定日子會出現的情況。"},{"en":"On days when I work from home, I usually wear more comfortable clothes.","zh":"在我在家工作的日子，我通常會穿得更舒服。"},{"en":"Some people wear trainers even on days when they never visit a gym.","zh":"有些人即使在完全沒有去健身室的日子也會穿運動鞋。"},{"en":"This phrase helps explain how behaviour changes according to what happens on a particular day.","zh":"這個片語可以解釋人的行為如何隨某一天的活動而改變。"}],"source":"2018 Q6.pdf","sourcePage":6},{"front":"athletic activity","meaning":"體能活動","examples":[{"en":"Walking quickly to catch a bus may be the most athletic activity of the day.","zh":"快步走去趕巴士可能已是一天中最具體能要求的活動。"},{"en":"Athletic activity is physical movement that requires energy, strength, speed or fitness.","zh":"體能活動是需要能量、力量、速度或體能的身體活動。"},{"en":"Running, swimming and playing basketball are common forms of athletic activity.","zh":"跑步、游泳和打籃球都是常見體能活動。"},{"en":"For some office workers, climbing stairs may be their main athletic activity on a busy day.","zh":"對某些上班族來說，忙碌一天中爬樓梯可能已是主要體能活動。"},{"en":"Wearing sportswear does not necessarily mean someone has done much athletic activity.","zh":"穿運動服並不代表一個人一定做了很多體能活動。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"catch a bus","meaning":"趕巴士","examples":[{"en":"Some people only walk quickly to catch a bus.","zh":"有些人一天只會快步走去趕巴士。"},{"en":"To catch a bus means to reach the bus in time before it leaves.","zh":"「catch a bus」表示及時到達巴士站，在巴士離開前上車。"},{"en":"She ran across the street to catch the last bus home.","zh":"她跑過馬路去趕最後一班回家的巴士。"},{"en":"Comfortable shoes help when commuters need to walk quickly to catch a bus.","zh":"當通勤者要快步走去趕巴士，舒適鞋履會很有幫助。"},{"en":"Missing a bus can delay the whole journey, so people often hurry to catch it.","zh":"錯過巴士可能令整段行程延誤，所以人們常會急着去趕巴士。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"sound superficial","meaning":"聽起來膚淺","examples":[{"en":"This may sound superficial, but clothing often expresses identity.","zh":"這聽起來可能很膚淺，但衣着經常表達身份。"},{"en":"To sound superficial means to appear shallow or concerned only with appearance rather than deeper meaning.","zh":"「sound superficial」表示聽起來很表面，只關注外觀而不是更深層意義。"},{"en":"Talking about shoes may sound superficial until we consider how clothing affects confidence and identity.","zh":"談鞋子可能聽起來膚淺，直到我們考慮衣着如何影響自信和身份。"},{"en":"The idea may sound superficial because fashion seems less serious than health or work.","zh":"這個想法可能聽起來膚淺，因為時尚似乎不及健康或工作那麼嚴肅。"},{"en":"Something can sound superficial at first while still revealing deeper social behaviour.","zh":"某件事起初可以聽起來很膚淺，卻仍可能反映更深層的社會行為。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"express who they are","meaning":"表達自己是怎樣的人","examples":[{"en":"Clothing helps people express who they are.","zh":"衣着幫助人們表達自己是怎樣的人。"},{"en":"To express who they are means to show aspects of their personality, values, interests or identity.","zh":"表達自己是怎樣的人，是指展示自己的個性、價值觀、興趣或身份。"},{"en":"A musician may use clothing to express who they are creatively.","zh":"音樂人可能透過衣着有創意地表達自己是怎樣的人。"},{"en":"People express who they are through colours, styles and brands they choose.","zh":"人們透過選擇不同顏色、風格和品牌來表達自己是怎樣的人。"},{"en":"Fashion becomes meaningful when clothes communicate more than simple practical needs.","zh":"當衣服傳達的不只是實際需要，時尚便會變得更有意義。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"who they want to become","meaning":"自己想成為怎樣的人","examples":[{"en":"Clothing can express who people want to become.","zh":"衣着可以表達人們自己想成為怎樣的人。"},{"en":"“Who they want to become” refers to the future identity, qualities or lifestyle a person hopes to develop.","zh":"「who they want to become」指一個人希望將來建立的身份、特質或生活方式。"},{"en":"A student may dress professionally because that reflects who they want to become after graduation.","zh":"學生可能穿得較專業，因為那代表他畢業後想成為怎樣的人。"},{"en":"Wearing fitness clothing can connect with the image of an active person someone wants to become.","zh":"穿健身服裝可以與一個人想成為活躍人士的形象連結。"},{"en":"People sometimes choose clothes not only for who they are now, but also for the person they hope to be.","zh":"人有時選衣服，不只因為現在是怎樣的人，也因為希望將來成為怎樣的人。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"be more willing to","meaning":"更願意……","examples":[{"en":"A person wearing running shoes may be more willing to walk home.","zh":"穿跑鞋的人可能會更願意步行回家。"},{"en":"To be more willing to do something means to feel more ready or prepared to choose that action.","zh":"「be more willing to」表示更願意或更準備選擇某種行動。"},{"en":"Students may be more willing to participate when the teacher creates a relaxed atmosphere.","zh":"如果老師營造輕鬆氣氛，學生可能更願意參與。"},{"en":"Comfortable shoes can make someone more willing to walk instead of taking transport.","zh":"舒適鞋履可以令人更願意步行，而不是乘車。"},{"en":"Small practical changes can make healthy behaviour feel easier and therefore more likely.","zh":"細小的實際改變可以令健康行為感覺較容易，因此人們更可能去做。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"instead of taking a taxi","meaning":"而不是乘的士","examples":[{"en":"A person may walk home instead of taking a taxi.","zh":"一個人可能步行回家，而不是乘的士。"},{"en":"“Instead of taking a taxi” means choosing another way to travel rather than using a taxi.","zh":"「instead of taking a taxi」表示選擇另一種交通方式，而不是坐的士。"},{"en":"We took the MTR instead of taking a taxi because traffic was heavy.","zh":"因為交通擠塞，我們乘港鐵而不是乘的士。"},{"en":"Someone in comfortable shoes may walk instead of taking a taxi for a short journey.","zh":"如果穿着舒適鞋履，短途時有人可能會步行而不是乘的士。"},{"en":"Choosing active transport for short trips can add physical movement to daily life.","zh":"短途選擇較活躍的交通方式，可以在日常生活增加身體活動。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"dressed in gym leggings","meaning":"穿着健身緊身褲","examples":[{"en":"Someone already dressed in gym leggings may find it easier to exercise.","zh":"已穿着健身緊身褲的人可能更容易去做運動。"},{"en":"“Dressed in gym leggings” means wearing close-fitting stretch trousers designed for exercise.","zh":"「dressed in gym leggings」表示穿着為運動而設計的貼身有彈性長褲。"},{"en":"She arrived at the yoga studio already dressed in gym leggings.","zh":"她到瑜伽室時已經穿着健身緊身褲。"},{"en":"Someone dressed in gym leggings does not need to change before a short workout.","zh":"已穿着健身緊身褲的人不用先換衣服便可以做短暫運動。"},{"en":"Being dressed for exercise can remove one small practical barrier to becoming active.","zh":"已穿好運動服可以消除開始活動前其中一個細小的實際障礙。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"join a yoga class","meaning":"參加瑜伽班","examples":[{"en":"Someone in gym leggings may find it easier to join a yoga class.","zh":"穿着健身緊身褲的人可能更容易參加瑜伽班。"},{"en":"To join a yoga class means to take part in an organised session where yoga is taught or practised.","zh":"參加瑜伽班是指參與由導師教授或練習瑜伽的有組織課堂。"},{"en":"She decided to join a yoga class near her office after work.","zh":"她決定下班後參加辦公室附近的瑜伽班。"},{"en":"Comfortable clothing can make it easier to join a yoga class without extra preparation.","zh":"舒適服裝可以令人不用額外準備便較容易參加瑜伽班。"},{"en":"People are more likely to join an activity when practical barriers are small.","zh":"當實際障礙很少，人們會更容易參加某項活動。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"by themselves","meaning":"單靠本身","examples":[{"en":"The clothes do not create health by themselves.","zh":"這些衣服單靠本身並不能創造健康。"},{"en":"“By themselves” means alone, without help or influence from anything else.","zh":"「by themselves」表示單獨地，沒有其他東西的幫助或影響。"},{"en":"Healthy shoes cannot improve fitness by themselves if someone never moves.","zh":"如果一個人從不活動，健康鞋履單靠本身不能改善體能。"},{"en":"Clothes by themselves cannot create discipline, but they may make action more convenient.","zh":"衣服單靠本身不能創造自律，但可以令行動更方便。"},{"en":"This phrase emphasises that one factor alone is not enough to produce a result.","zh":"這個片語強調單一因素本身不足以產生某個結果。"}],"source":"2018 Q6.pdf","sourcePage":7},{"front":"at the very least","meaning":"至少","examples":[{"en":"At the very least, athleisure lowers the barrier to healthy choices.","zh":"至少，運動休閒服飾降低了作出健康選擇的門檻。"},{"en":"“At the very least” introduces the minimum benefit or conclusion that can reasonably be accepted.","zh":"「at the very least」用來帶出最低限度可以合理接受的好處或結論。"},{"en":"The course may not make you fluent, but at the very least it will improve your vocabulary.","zh":"這個課程未必令你流利，但至少可以改善詞彙量。"},{"en":"Athleisure cannot make people healthy, but at the very least it can make movement easier.","zh":"運動休閒服飾不能令人自動健康，但至少可以令活動更容易。"},{"en":"This phrase is useful when making a careful claim without exaggerating.","zh":"當希望謹慎提出一個不誇大的主張時，這個片語很有用。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"lower the barrier to","meaning":"降低……的門檻","examples":[{"en":"Athleisure can lower the barrier to healthy choices.","zh":"運動休閒服飾可以降低作出健康選擇的門檻。"},{"en":"To lower the barrier to something means to make it easier to begin, access or choose.","zh":"「lower the barrier to」表示令某件事更容易開始、接觸或選擇。"},{"en":"Cheaper public transport can lower the barrier to travelling for low-income families.","zh":"較便宜的公共交通可以降低低收入家庭出行的門檻。"},{"en":"Wearing comfortable clothes may lower the barrier to going for a walk after work.","zh":"穿舒適衣服可能降低下班後去散步的門檻。"},{"en":"Small practical changes can increase participation by making an activity less difficult to start.","zh":"細小的實際改變可以令活動更容易開始，從而增加參與。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"healthy choices","meaning":"健康選擇","examples":[{"en":"Comfortable clothes can make healthy choices easier.","zh":"舒適衣服可以令健康選擇更容易作出。"},{"en":"Healthy choices are decisions that support physical or mental well-being.","zh":"健康選擇是有助身體或心理健康的決定。"},{"en":"Walking instead of taking a short taxi ride can be a healthy choice.","zh":"短途時步行而不是乘的士，可以是一個健康選擇。"},{"en":"Preparing balanced meals and getting enough sleep are healthy choices too.","zh":"準備均衡膳食和獲得充足睡眠也是健康選擇。"},{"en":"Clothing cannot create health, but it may make some healthy choices more convenient.","zh":"衣服不能創造健康，但可以令某些健康選擇更方便。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"pay more attention to","meaning":"更加留意","examples":[{"en":"People gradually pay more attention to mental well-being.","zh":"人們逐漸更加留意心理健康。"},{"en":"To pay more attention to something means to notice it more carefully and consider it more important.","zh":"「pay more attention to」表示更仔細留意某件事，並認為它更加重要。"},{"en":"Schools now pay more attention to students’ stress and sleep.","zh":"學校現在更加留意學生的壓力和睡眠。"},{"en":"Consumers pay more attention to fabric comfort when they wear clothes for long hours.","zh":"當人們長時間穿一件衣服，消費者會更加留意布料舒適度。"},{"en":"Social priorities change when people begin paying more attention to issues once ignored.","zh":"當人們開始更加留意以前被忽視的問題，社會重點也會改變。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"mental well-being","meaning":"精神健康；心理健康","examples":[{"en":"Many people now care more about mental well-being.","zh":"很多人現在更加關心心理健康。"},{"en":"Mental well-being is a person’s emotional and psychological state, including stress, mood and ability to cope with life.","zh":"心理健康是人的情緒和心理狀態，包括壓力、情緒和應付生活的能力。"},{"en":"Regular rest and supportive relationships can improve mental well-being.","zh":"定期休息和有支持性的關係可以改善心理健康。"},{"en":"Comfortable clothing may contribute slightly to mental well-being by reducing physical discomfort.","zh":"舒適服裝可以透過減少身體不適，稍微有助心理健康。"},{"en":"Mental well-being is broader than simply not having a mental illness; it also involves feeling able to function and cope.","zh":"心理健康不只是沒有精神疾病，也包括感到自己有能力生活和應付問題。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"body image","meaning":"身體形象","examples":[{"en":"People are paying more attention to body image.","zh":"人們更加留意身體形象。"},{"en":"Body image is the way a person thinks and feels about the appearance and shape of their own body.","zh":"身體形象是人對自己身體外觀和形狀的看法與感受。"},{"en":"Social media can affect body image by repeatedly showing idealised bodies.","zh":"社交媒體反覆展示理想化身形，可能影響身體形象。"},{"en":"Comfortable clothing may help some people feel less self-conscious about body image.","zh":"舒適服裝可能幫助某些人減少對身體形象的過度不安。"},{"en":"A healthy body image means judging yourself with balance rather than comparing constantly with unrealistic standards.","zh":"健康的身體形象表示較平衡地看待自己，而不是不斷與不現實標準比較。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"work-life balance","meaning":"工作與生活平衡","examples":[{"en":"Consumers are paying more attention to work-life balance.","zh":"消費者更加留意工作與生活平衡。"},{"en":"Work-life balance is the ability to manage work responsibilities while still having enough time and energy for personal life.","zh":"工作與生活平衡是指能處理工作責任，同時仍有足夠時間和精力投入私人生活。"},{"en":"Flexible hours can improve work-life balance for parents.","zh":"彈性工作時間可以改善父母的工作與生活平衡。"},{"en":"Clothing that suits both commuting and leisure can support a lifestyle focused on work-life balance.","zh":"同時適合通勤和休閒的服裝，可以配合重視工作與生活平衡的生活方式。"},{"en":"Poor work-life balance can leave people tired because work takes too much time from rest and relationships.","zh":"工作與生活平衡不足會令人疲倦，因為工作佔用了太多休息和人際關係時間。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"be drawn to","meaning":"被……吸引","examples":[{"en":"Consumers are drawn to functional clothes.","zh":"消費者被功能性服裝吸引。"},{"en":"To be drawn to something means to feel naturally attracted or interested in it.","zh":"「be drawn to」表示自然地被某事物吸引或對它感興趣。"},{"en":"Visitors are drawn to the café because of its quiet atmosphere.","zh":"訪客被那間咖啡店安靜的氣氛吸引。"},{"en":"Busy consumers are drawn to clothes that solve practical problems.","zh":"忙碌的消費者會被能解決實際問題的衣服吸引。"},{"en":"People are often drawn to products that match both their needs and desired identity.","zh":"人通常會被同時符合需要和理想身份的產品吸引。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"functional clothes","meaning":"功能性服裝","examples":[{"en":"Functional clothes can support an active lifestyle.","zh":"功能性服裝可以配合活躍生活方式。"},{"en":"Functional clothes are designed to perform practical tasks such as stretching, keeping cool, protecting from rain or storing items.","zh":"功能性服裝是為伸展、保持涼快、防雨或儲物等實際用途而設計的服裝。"},{"en":"A jacket with secure pockets is functional clothing for commuters.","zh":"有安全口袋的外套是適合通勤者的功能性服裝。"},{"en":"Breathable fabric makes functional clothes useful in hot weather.","zh":"透氣布料令功能性服裝在炎熱天氣更實用。"},{"en":"Functional clothes are valued for what they help the wearer do, not only how they look.","zh":"功能性服裝的價值不只在外觀，也在於它能幫助穿着者做甚麼。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"make an active lifestyle feel more achievable","meaning":"令活躍生活方式感覺更容易做到","examples":[{"en":"Functional clothes make an active lifestyle feel more achievable.","zh":"功能性服裝令活躍生活方式感覺更容易做到。"},{"en":"This means practical clothing can make regular movement and exercise seem easier to fit into everyday life.","zh":"這句話表示實用服裝可以令日常加入活動和運動感覺較容易。"},{"en":"Comfortable shoes can make walking to work feel more achievable.","zh":"舒適鞋履可以令步行上班感覺更容易做到。"},{"en":"Clothes that do not need changing may make exercise after work feel more achievable.","zh":"不需要換衣服的服裝，可以令下班後做運動感覺更容易做到。"},{"en":"People are more likely to try healthy habits when those habits seem practical rather than difficult.","zh":"當健康習慣感覺實際而不是困難，人們會更願意嘗試。"}],"source":"2018 Q6.pdf","sourcePage":8},{"front":"the fundamental way","meaning":"根本方式","examples":[{"en":"The third reason lies in the fundamental way fashion has changed.","zh":"第三個原因在於時尚發生改變的根本方式。"},{"en":"“The fundamental way” refers to the basic or deepest manner in which something works or has changed.","zh":"「the fundamental way」指某件事運作或改變的基本、最深層方式。"},{"en":"Online banking changed the fundamental way many people manage money.","zh":"網上銀行改變了很多人管理金錢的根本方式。"},{"en":"Athleisure reflects a change in the fundamental way people judge whether clothes look fashionable.","zh":"運動休閒服飾反映人們判斷衣服是否時尚的根本方式已經改變。"},{"en":"A fundamental change affects the underlying rules, not just small surface details.","zh":"根本改變影響的是底層規則，而不只是表面細節。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"fashion itself has changed","meaning":"時尚本身已經改變","examples":[{"en":"Fashion itself has changed in recent years.","zh":"近年時尚本身已經改變。"},{"en":"“Fashion itself has changed” means the standards and ideas defining what counts as stylish have become different.","zh":"「fashion itself has changed」表示界定甚麼是時尚的標準和觀念已經不同。"},{"en":"Fashion itself has changed as workplaces have accepted more casual clothing.","zh":"隨着工作場所接受較休閒服裝，時尚本身已經改變。"},{"en":"The rise of trainers with formal outfits shows that fashion itself has changed.","zh":"運動鞋開始配搭正式服裝，顯示時尚本身已經改變。"},{"en":"When fashion itself changes, old rules about what looks appropriate may lose importance.","zh":"當時尚本身改變，舊有關於甚麼才算合適的規則便可能失去重要性。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"not simply about","meaning":"不單純是關於……","examples":[{"en":"Athleisure is not simply about comfort.","zh":"運動休閒服飾不單純是關於舒適。"},{"en":"“Not simply about” means something has a deeper or broader meaning than the one obvious explanation.","zh":"「not simply about」表示某件事有比最明顯解釋更深或更廣泛的意義。"},{"en":"Education is not simply about passing examinations.","zh":"教育不單純是關於通過考試。"},{"en":"Athleisure is not simply about comfort because style and identity also matter.","zh":"運動休閒服飾不單純是關於舒適，因為時尚和身份也很重要。"},{"en":"This phrase helps introduce additional reasons beyond a basic explanation.","zh":"這個片語有助帶出基本解釋以外的其他原因。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"underneath the surface","meaning":"表面之下；深層而言","examples":[{"en":"Underneath the surface, athleisure is about making comfort look deliberate.","zh":"深層而言，運動休閒服飾是在於令舒適看起來像刻意設計。"},{"en":"“Underneath the surface” means at a deeper level beyond what is immediately visible.","zh":"「underneath the surface」表示在立即可見的表面以外，更深的一層。"},{"en":"Underneath the surface, the argument was really about trust rather than money.","zh":"表面之下，那場爭論真正關乎的是信任，而不是金錢。"},{"en":"Athleisure looks simple, but underneath the surface it reflects changing ideas about work and identity.","zh":"運動休閒服飾看起來簡單，但深層而言反映工作和身份觀念的改變。"},{"en":"This phrase is useful when explaining deeper causes or meanings hidden behind appearances.","zh":"當解釋外表背後較深層的原因或意義時，可以使用這個片語。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"be closely associated with","meaning":"與……密切相關","examples":[{"en":"Athleisure is closely associated with deliberate comfort.","zh":"運動休閒服飾與刻意設計的舒適感密切相關。"},{"en":"To be closely associated with something means to have a strong connection with it in people’s minds or in reality.","zh":"「be closely associated with」表示在現實或人們心中與某事有強烈連繫。"},{"en":"The city is closely associated with finance and international business.","zh":"這個城市與金融和國際商業密切相關。"},{"en":"Athleisure is closely associated with fitness, movement and casual modern style.","zh":"運動休閒服飾與健身、活動和現代休閒風格密切相關。"},{"en":"Strong associations develop when two things repeatedly appear together.","zh":"當兩件事反覆一起出現，便容易建立強烈聯想。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"make comfort look deliberate","meaning":"令舒適看起來像刻意設計","examples":[{"en":"Athleisure makes comfort look deliberate rather than careless.","zh":"運動休閒服飾令舒適看起來像刻意設計，而不是隨便。"},{"en":"To make comfort look deliberate means to make relaxed clothing appear intentionally designed and stylish.","zh":"令舒適看起來像刻意設計，是指令休閒服裝看起來有意識地經過設計，而且有時尚感。"},{"en":"Clean lines can make a loose outfit look deliberate rather than untidy.","zh":"簡潔線條可以令鬆身造型看起來有意設計，而不是凌亂。"},{"en":"Premium fabric helps athleisure make comfort look deliberate.","zh":"優質布料幫助運動休閒服飾令舒適看起來像刻意設計。"},{"en":"The goal is to look relaxed by choice, not as if no effort was made.","zh":"目標是看起來像有意選擇休閒，而不是完全沒有花心思。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"loose T-shirts","meaning":"鬆身T恤","examples":[{"en":"Loose T-shirts used to be seen as casual or careless.","zh":"鬆身T恤以前常被視為休閒或隨便。"},{"en":"Loose T-shirts are T-shirts cut wider than the body so they do not fit closely.","zh":"鬆身T恤是剪裁比身體更寬、不貼身的T恤。"},{"en":"Loose T-shirts are comfortable in hot weather because they allow more air around the body.","zh":"鬆身T恤在炎熱天氣很舒服，因為身體周圍有更多空氣流通。"},{"en":"A loose T-shirt can look stylish when matched with clean trousers and good shoes.","zh":"鬆身T恤如果配上整潔長褲和合適鞋履，也可以很時尚。"},{"en":"The same loose shape can look careless or fashionable depending on fabric, fit and styling.","zh":"同樣的鬆身剪裁可以看起來隨便或時尚，視乎布料、版型和配搭。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"sweatpants","meaning":"運動褲","examples":[{"en":"Sweatpants can now look polished with the right design.","zh":"運動褲配合合適設計，現在也可以顯得精緻得體。"},{"en":"Sweatpants are soft casual trousers originally designed for exercise, warming up or relaxation.","zh":"運動褲是柔軟休閒長褲，原本為運動、熱身或放鬆而設計。"},{"en":"Many people wear sweatpants at home because they are loose and comfortable.","zh":"很多人在家穿運動褲，因為它們鬆身而舒適。"},{"en":"Modern sweatpants can look polished when they use better fabric and cleaner cuts.","zh":"現代運動褲使用更好的布料和更乾淨剪裁時，可以顯得很精緻。"},{"en":"Their changing image shows how casual clothing can move into more public settings.","zh":"它們形象上的轉變反映休閒服裝如何進入更多公眾場合。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"be seen as careless","meaning":"被視為隨便","examples":[{"en":"Loose T-shirts and sweatpants might once have been seen as careless.","zh":"鬆身T恤和運動褲以前可能被視為隨便。"},{"en":"To be seen as careless means to be judged as looking untidy or showing too little effort.","zh":"「be seen as careless」表示被人認為外表凌亂或沒有花足夠心思。"},{"en":"Dirty shoes may be seen as careless in a formal workplace.","zh":"在正式工作場所，骯髒鞋履可能被視為隨便。"},{"en":"Casual clothing can be seen as careless if the fit and condition look poor.","zh":"如果版型和狀態看起來不好，休閒服裝可能被視為隨便。"},{"en":"Fashion changes when styles once seen as careless become accepted as intentional.","zh":"當以前被視為隨便的風格開始被接受為刻意設計，時尚便改變了。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"on the contrary","meaning":"相反","examples":[{"en":"Now, on the contrary, similar items can appear polished.","zh":"現在，相反地，類似衣物可以顯得精緻得體。"},{"en":"“On the contrary” introduces a statement that is the opposite of what was just suggested.","zh":"「on the contrary」用來帶出與剛才說法相反的觀點。"},{"en":"Some people think exercise makes them tired; on the contrary, regular activity can improve energy.","zh":"有些人以為運動只會令人疲倦；相反，定期活動可以提升精神。"},{"en":"Casual clothes are not always sloppy; on the contrary, good design can make them sophisticated.","zh":"休閒服裝不一定邋遢；相反，良好設計可以令它顯得高雅。"},{"en":"This phrase is used to strongly correct or reverse a previous idea.","zh":"這個片語用來強烈更正或反轉之前的想法。"}],"source":"2018 Q6.pdf","sourcePage":9},{"front":"better cutting","meaning":"更好的剪裁","examples":[{"en":"Better cutting can make casual clothes look polished.","zh":"更好的剪裁可以令休閒服裝顯得精緻得體。"},{"en":"Better cutting means improved garment construction and shape so clothes fit the body more attractively.","zh":"更好的剪裁是指改善衣服的結構和形狀，令它更合身和吸引。"},{"en":"Better cutting can make simple trousers fall more neatly around the legs.","zh":"更好的剪裁可以令簡單長褲在雙腿周圍垂墜得更整齊。"},{"en":"A hoodie with better cutting may look more suitable under a blazer.","zh":"剪裁更好的連帽衫可能更適合穿在西裝外套下面。"},{"en":"Clothing can appear more expensive and deliberate when the cut is clean and well proportioned.","zh":"當剪裁乾淨而比例良好，衣服可以看起來更昂貴和更有設計感。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"premium fabrics","meaning":"優質布料","examples":[{"en":"Premium fabrics make athleisure look more refined.","zh":"優質布料令運動休閒服飾看起來更精緻。"},{"en":"Premium fabrics are higher-quality materials chosen for their feel, appearance, durability or performance.","zh":"優質布料是因觸感、外觀、耐用度或功能表現較好而被選用的高品質物料。"},{"en":"A premium fabric may feel softer and keep its shape longer after washing.","zh":"優質布料可能觸感更柔軟，而且洗滌後更能保持形狀。"},{"en":"Brands use premium fabrics to make casual clothes look more expensive.","zh":"品牌使用優質布料令休閒服看起來更昂貴。"},{"en":"Fabric quality can change how the same simple design is judged.","zh":"布料質素可以改變人們對同一個簡單設計的評價。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"minimalist colours","meaning":"極簡色系","examples":[{"en":"Minimalist colours help casual clothes look modern.","zh":"極簡色系幫助休閒服裝顯得現代。"},{"en":"Minimalist colours are simple, restrained colours such as black, white, grey, navy or neutral tones.","zh":"極簡色系是黑、白、灰、深藍或中性色等簡單而克制的顏色。"},{"en":"The room uses minimalist colours to create a calm and clean appearance.","zh":"那個房間使用極簡色系，營造平靜和整潔外觀。"},{"en":"Athleisure in minimalist colours is easier to match with office clothing.","zh":"極簡色系的運動休閒服飾更容易與辦公服裝配搭。"},{"en":"Simple colour choices can make sports-inspired designs look less busy and more polished.","zh":"簡單配色可以令運動風設計少一點雜亂感，更顯精緻。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"appear polished","meaning":"顯得精緻得體","examples":[{"en":"With better cutting, similar items can appear polished.","zh":"配合更好的剪裁，類似衣物可以顯得精緻得體。"},{"en":"To appear polished means to look refined, neat and carefully put together.","zh":"「appear polished」表示看起來精緻、整潔，而且經過仔細配搭。"},{"en":"Simple clothes can appear polished when they fit properly and are clean.","zh":"簡單衣服如果合身而乾淨，也可以顯得精緻得體。"},{"en":"A plain sweatshirt may appear polished when matched with tailored trousers.","zh":"一件普通衛衣配上剪裁長褲後，可能顯得很精緻。"},{"en":"Looking polished depends on overall presentation, not only whether clothing is formal.","zh":"外觀是否精緻取決於整體呈現，而不只是衣服是否正式。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"a black hoodie under a blazer","meaning":"西裝外套內配黑色連帽衫","examples":[{"en":"A black hoodie under a blazer can look modern.","zh":"西裝外套內配黑色連帽衫可以顯得很現代。"},{"en":"“A black hoodie under a blazer” describes layering a casual hooded top beneath a more formal jacket.","zh":"「a black hoodie under a blazer」表示在較正式的西裝外套下面穿黑色連帽上衣。"},{"en":"He wore a black hoodie under a blazer with clean white trainers.","zh":"他在西裝外套內配黑色連帽衫，再穿乾淨白色運動鞋。"},{"en":"This combination mixes relaxed clothing with a smarter outer layer.","zh":"這種配搭把休閒服裝和較醒目的正式外層結合起來。"},{"en":"Pairings like this show how fashion now allows casual and formal elements to appear together.","zh":"這類配搭顯示現代時尚容許休閒和正式元素同時出現。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"cropped trousers","meaning":"九分褲","examples":[{"en":"White trainers with cropped trousers can look stylish.","zh":"白色運動鞋配九分褲可以很有型。"},{"en":"Cropped trousers are trousers cut shorter than full length, usually ending above the ankle.","zh":"九分褲是比一般長褲短，通常在腳踝以上結束的長褲。"},{"en":"Cropped trousers make the shoes more visible.","zh":"九分褲會令鞋子更加顯眼。"},{"en":"She paired cropped trousers with trainers for a clean smart-casual look.","zh":"她以九分褲配運動鞋，營造乾淨的半正式休閒造型。"},{"en":"Their shorter length can give an outfit a lighter and more modern shape.","zh":"較短褲長可以令整體造型顯得較輕盈和現代。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"matched with","meaning":"與……配搭","examples":[{"en":"A sports jacket matched with a simple dress can look modern.","zh":"運動外套與簡單連身裙配搭可以顯得很現代。"},{"en":"“Matched with” means combined or paired with another item so the two work well together.","zh":"「matched with」表示與另一件物品組合或配搭，令兩者互相配合。"},{"en":"Dark trousers matched with white trainers create a simple contrast.","zh":"深色長褲與白色運動鞋配搭，形成簡單對比。"},{"en":"Athleisure pieces look more polished when matched with cleaner, smarter items.","zh":"運動休閒單品與更乾淨、更正式的衣物配搭時，會顯得更精緻。"},{"en":"Good matching can change how casual or formal the same piece appears.","zh":"良好配搭可以改變同一件衣物看起來有多休閒或正式。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"rather than lazy","meaning":"而不是懶散","examples":[{"en":"Athleisure can look modern rather than lazy.","zh":"運動休閒服飾可以顯得現代，而不是懶散。"},{"en":"“Rather than lazy” means appearing intentional and stylish instead of careless or lacking effort.","zh":"「rather than lazy」表示看起來有意識和有風格，而不是隨便或沒有花心思。"},{"en":"A loose outfit can look relaxed rather than lazy when it is clean and well matched.","zh":"鬆身造型如果乾淨而配搭得宜，可以顯得休閒而不是懶散。"},{"en":"Better fabric helps sweatpants look modern rather than lazy.","zh":"更好的布料令運動褲顯得現代，而不是懶散。"},{"en":"The difference often comes from styling, fit and condition rather than the clothing category itself.","zh":"差別往往來自配搭、版型和衣服狀態，而不只是服裝類別本身。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"accelerate this change","meaning":"加快這種轉變","examples":[{"en":"Social media has accelerated this change.","zh":"社交媒體加快了這種轉變。"},{"en":"To accelerate this change means to make an existing change happen faster.","zh":"「accelerate this change」表示令本來已在發生的轉變更快進行。"},{"en":"Online shopping accelerated the change from physical stores to digital retail.","zh":"網上購物加快了零售由實體店轉向數碼平台的改變。"},{"en":"Social media accelerated athleisure’s acceptance by showing the style repeatedly to millions of users.","zh":"社交媒體向數以百萬計使用者反覆展示運動休閒風格，加快了它被接受的速度。"},{"en":"A trend spreads faster when media, celebrities and brands all reinforce the same change.","zh":"當媒體、名人和品牌都強化同一種改變，潮流便會傳播得更快。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"celebrities, athletes and influencers","meaning":"名人、運動員和網紅","examples":[{"en":"Celebrities, athletes and influencers often appear in stylish casual wear.","zh":"名人、運動員和網紅經常穿着時尚休閒服出現。"},{"en":"Celebrities, athletes and influencers are public figures whose clothing choices may attract wide attention.","zh":"名人、運動員和網紅都是其衣着選擇會受到廣泛注意的公眾人物。"},{"en":"Brands often use celebrities, athletes and influencers to introduce new styles.","zh":"品牌常利用名人、運動員和網紅介紹新風格。"},{"en":"Fans may copy what celebrities, athletes and influencers wear online.","zh":"粉絲可能模仿名人、運動員和網紅在網上穿的衣服。"},{"en":"Their visibility gives them strong power to normalise new fashion choices.","zh":"他們高度曝光，因此有很大力量令新的時尚選擇變得正常。"}],"source":"2018 Q6.pdf","sourcePage":10},{"front":"K-pop stars","meaning":"韓國流行音樂明星","examples":[{"en":"K-pop stars help shape casual fashion trends.","zh":"韓國流行音樂明星幫助塑造休閒時尚潮流。"},{"en":"K-pop stars are singers and performers associated with the Korean pop music industry.","zh":"韓國流行音樂明星是與韓國流行音樂產業有關的歌手和表演者。"},{"en":"Many K-pop stars wear carefully styled casual outfits in airports and public appearances.","zh":"很多韓國流行音樂明星在機場和公開場合會穿經仔細配搭的休閒服。"},{"en":"Fans may copy trainers, jackets or colours worn by K-pop stars.","zh":"粉絲可能模仿韓國流行音樂明星穿的運動鞋、外套或顏色。"},{"en":"Because their images spread internationally, K-pop stars can influence fashion far beyond Korea.","zh":"因為他們的形象在國際間廣泛傳播，韓國流行音樂明星可以影響韓國以外的時尚。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"be photographed in","meaning":"被拍到穿着……","examples":[{"en":"Influencers are often photographed in stylish casual wear.","zh":"網紅經常被拍到穿着時尚休閒服。"},{"en":"To be photographed in something means to have pictures taken while wearing that clothing.","zh":"「be photographed in」表示穿着某種衣服時被拍攝。"},{"en":"The actor was photographed in a simple tracksuit at the airport.","zh":"那位演員在機場被拍到穿着簡單運動套裝。"},{"en":"When celebrities are repeatedly photographed in athleisure, the style becomes more visible.","zh":"當名人反覆被拍到穿運動休閒服，這種風格便會有更高曝光。"},{"en":"Public photographs can influence fashion because people see how clothes look in real-life settings.","zh":"公開照片會影響時尚，因為人們能看到衣服在真實場合的效果。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"stylish casual wear","meaning":"時尚休閒服","examples":[{"en":"Stylish casual wear is now widely accepted.","zh":"時尚休閒服現在已被廣泛接受。"},{"en":"Stylish casual wear is comfortable, informal clothing that is still deliberately fashionable and well presented.","zh":"時尚休閒服是舒適而非正式，但同時經過刻意配搭、具時尚感的服裝。"},{"en":"Clean trainers, simple trousers and a fitted sweatshirt can form stylish casual wear.","zh":"乾淨運動鞋、簡單長褲和合身衛衣可以組成時尚休閒服。"},{"en":"Many modern offices allow stylish casual wear on ordinary workdays.","zh":"很多現代辦公室在普通工作日容許時尚休閒服。"},{"en":"Stylish casual wear shows that informal clothing does not have to look careless.","zh":"時尚休閒服說明非正式服裝不一定要顯得隨便。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"relaxed can also mean fashionable","meaning":"休閒也可以代表時尚","examples":[{"en":"Followers quickly learn that relaxed can also mean fashionable.","zh":"追蹤者很快明白休閒也可以代表時尚。"},{"en":"“Relaxed can also mean fashionable” means comfortable or informal clothing can still be stylish.","zh":"「relaxed can also mean fashionable」表示舒適或非正式服裝仍然可以很有時尚感。"},{"en":"A loose knit top can look relaxed and fashionable at the same time.","zh":"一件鬆身針織上衣可以同時顯得休閒和時尚。"},{"en":"Social media has helped people see that relaxed can also mean fashionable when styling is deliberate.","zh":"社交媒體幫助人們明白，只要配搭有心思，休閒也可以代表時尚。"},{"en":"This idea challenges the old belief that fashion must be formal or uncomfortable.","zh":"這個觀念挑戰了時尚一定要正式或不舒服的舊想法。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"respond by producing","meaning":"以生產……作回應","examples":[{"en":"Brands respond by producing more attractive designs.","zh":"品牌以生產更多吸引人的設計作回應。"},{"en":"To respond by producing something means to react to a situation or demand by making new products.","zh":"「respond by producing」表示以製造新產品來回應某種情況或需求。"},{"en":"Food companies responded to health concerns by producing lower-sugar drinks.","zh":"食品公司以生產低糖飲品來回應健康關注。"},{"en":"Fashion brands respond to consumer interest by producing more polished athleisure.","zh":"時裝品牌以生產更精緻的運動休閒服飾來回應消費者興趣。"},{"en":"Companies often react to trends by creating products that strengthen the same trend further.","zh":"公司常透過製造新產品回應潮流，而這些產品又會進一步強化潮流。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"attractive designs","meaning":"吸引人的設計","examples":[{"en":"Brands produce attractive designs that reinforce the trend.","zh":"品牌生產吸引人的設計，進一步強化這股潮流。"},{"en":"Attractive designs are products whose appearance, shape, colour or details appeal to consumers.","zh":"吸引人的設計是外觀、形狀、顏色或細節能吸引消費者的產品設計。"},{"en":"Simple lines and balanced colours can create attractive designs.","zh":"簡潔線條和協調顏色可以形成吸引人的設計。"},{"en":"Attractive athleisure designs persuade more people to wear sports-inspired clothing in public.","zh":"吸引人的運動休閒設計會說服更多人在公眾場合穿運動風服裝。"},{"en":"Good design can turn a practical product into something consumers actively want.","zh":"良好設計可以把實用產品變成消費者真正想要的東西。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"further normalise","meaning":"進一步令……正常化","examples":[{"en":"New designs further normalise athleisure.","zh":"新設計進一步令運動休閒服飾正常化。"},{"en":"To further normalise something means to make it even more common, ordinary and socially accepted.","zh":"「further normalise」表示令某事更加常見、普通和被社會接受。"},{"en":"Flexible work policies further normalised working from home.","zh":"彈性工作政策進一步令在家工作正常化。"},{"en":"Seeing athleisure in more shops and offices further normalises the style.","zh":"在更多商店和辦公室看到運動休閒服飾，會進一步令這種風格正常化。"},{"en":"A behaviour becomes normalised when people stop seeing it as unusual.","zh":"當人們不再把某種行為視為奇怪，它便逐漸正常化。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"reinforce the trend","meaning":"強化這股潮流","examples":[{"en":"Fashion brands help reinforce the trend.","zh":"時裝品牌幫助強化這股潮流。"},{"en":"To reinforce the trend means to strengthen an existing pattern so it becomes more established.","zh":"「reinforce the trend」表示加強一個已存在的趨勢，令它更加穩固。"},{"en":"More bicycle lanes can reinforce the trend towards cycling.","zh":"增加單車徑可以強化騎單車的潮流。"},{"en":"Attractive products reinforce the athleisure trend by encouraging more consumers to join it.","zh":"吸引人的產品鼓勵更多消費者加入，從而強化運動休閒潮流。"},{"en":"A trend grows stronger when media attention, product supply and public acceptance all reinforce one another.","zh":"當媒體關注、產品供應和公眾接受度互相加強，潮流便會變得更強。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"the more…, the more…","meaning":"越……，就越……","examples":[{"en":"The more people see athleisure in public, the more acceptable it becomes.","zh":"越多人在公眾場合看到運動休閒服飾，它就越容易被接受。"},{"en":"“The more A, the more B” shows that as one thing increases, another thing also increases.","zh":"「the more A, the more B」表示當一件事增加，另一件事也會隨之增加。"},{"en":"The more students practise speaking, the more confident they become.","zh":"學生越多練習說話，就越有信心。"},{"en":"The more often casual sportswear appears in offices, the more normal it feels.","zh":"休閒運動服越常出現在辦公室，人們就越覺得它正常。"},{"en":"This pattern is useful for showing a direct relationship between two changing conditions.","zh":"這個句式適合表示兩個會改變的條件之間有直接關係。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"in public","meaning":"在公眾場合","examples":[{"en":"The more people see athleisure in public, the more acceptable it becomes.","zh":"越多人在公眾場合看到運動休閒服飾，它就越容易被接受。"},{"en":"“In public” means in places where other people can see you, rather than in private.","zh":"「in public」表示在其他人可以看見你的地方，而不是私人空間。"},{"en":"Some people feel comfortable singing at home but not in public.","zh":"有些人在家唱歌很自在，但不敢在公眾場合唱。"},{"en":"Sportswear once seemed unusual in public outside exercise settings.","zh":"運動服以前在運動場合以外的公眾地方會顯得奇怪。"},{"en":"A style becomes socially normal when people repeatedly wear it in public.","zh":"當人們反覆在公眾場合穿某種風格，它就會逐漸成為社會常態。"}],"source":"2018 Q6.pdf","sourcePage":11},{"front":"acceptable","meaning":"可接受的","examples":[{"en":"Athleisure has become more acceptable in everyday settings.","zh":"運動休閒服飾在日常場合已變得更可接受。"},{"en":"Acceptable means considered suitable, reasonable or socially allowed.","zh":"「acceptable」表示被認為合適、合理或在社會上容許。"},{"en":"Trainers may be acceptable in one office but not in another with a strict dress code.","zh":"運動鞋在一間辦公室可能可接受，但在衣着規定嚴格的公司則未必。"},{"en":"Casual clothing became more acceptable as workplace culture changed.","zh":"隨着工作文化改變，休閒服裝變得更可接受。"},{"en":"Whether something is acceptable depends partly on social rules and expectations.","zh":"某件事是否可接受，部分取決於社會規則和期望。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"be willing to wear","meaning":"願意穿着","examples":[{"en":"More people are willing to wear athleisure in public.","zh":"更多人願意在公眾場合穿運動休閒服飾。"},{"en":"To be willing to wear something means to feel comfortable or prepared to choose that clothing.","zh":"「be willing to wear」表示感到自在或準備好選擇穿某種衣服。"},{"en":"Employees may be more willing to wear trainers when managers also wear them.","zh":"當經理也穿運動鞋，員工可能更願意穿着。"},{"en":"People are willing to wear athleisure in more places because it no longer looks unusual.","zh":"因為運動休閒服飾不再顯得奇怪，人們願意在更多地方穿着。"},{"en":"Social acceptance can strongly affect what people are willing to wear.","zh":"社會接受程度可以強烈影響人們願意穿甚麼。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, the rise of athleisure is easy to understand.","zh":"綜合而言，運動休閒服飾的興起很容易理解。"},{"en":"“All things considered” means after thinking about all the main facts, causes, advantages and disadvantages.","zh":"「all things considered」表示考慮所有主要事實、原因、優點和缺點之後。"},{"en":"All things considered, travelling by train is the most practical choice.","zh":"綜合而言，乘火車是最實際的選擇。"},{"en":"All things considered, athleisure fits modern life because it combines convenience, identity and fashion.","zh":"綜合而言，運動休閒服飾適合現代生活，因為它結合方便、身份和時尚。"},{"en":"This phrase is useful for introducing a balanced final judgement.","zh":"這個片語適合用來帶出平衡的最終判斷。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"be easy to understand","meaning":"容易理解","examples":[{"en":"The rise of athleisure is easy to understand.","zh":"運動休閒服飾的興起很容易理解。"},{"en":"To be easy to understand means the reasons or meaning are clear once the main facts are considered.","zh":"「be easy to understand」表示考慮主要事實後，其原因或意思很清楚。"},{"en":"Her decision is easy to understand because the new job offers better hours.","zh":"她的決定很容易理解，因為新工作提供較好的工時。"},{"en":"Athleisure’s popularity is easy to understand when people have busy and active schedules.","zh":"當人們生活忙碌而活動量大，運動休閒服飾受歡迎就很容易理解。"},{"en":"Something can seem surprising at first but become easy to understand after its causes are explained.","zh":"有些事情起初看似令人意外，但解釋原因後便很容易理解。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"practical clothing","meaning":"實用服裝","examples":[{"en":"Athleisure gives busy people practical clothing.","zh":"運動休閒服飾為忙碌的人提供實用服裝。"},{"en":"Practical clothing is clothing designed to work well in real daily situations rather than only look attractive.","zh":"實用服裝是為真實日常情況而設計，不只是為了好看的衣服。"},{"en":"A rainproof jacket with useful pockets is practical clothing for commuters.","zh":"一件防雨又有實用口袋的外套，是適合通勤者的實用服裝。"},{"en":"Stretchy trousers are practical clothing for people who walk, sit and travel throughout the day.","zh":"有彈性的長褲對整天要步行、坐着和乘車的人來說是實用服裝。"},{"en":"Practical clothing saves time and effort because it suits the wearer’s actual activities.","zh":"實用服裝配合穿着者真正的活動，因此可以節省時間和精力。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"health-conscious consumers","meaning":"注重健康的消費者","examples":[{"en":"Athleisure allows health-conscious consumers to project an active image.","zh":"運動休閒服飾讓注重健康的消費者展現活躍形象。"},{"en":"Health-conscious consumers are buyers who pay close attention to products connected with exercise, diet and well-being.","zh":"注重健康的消費者是特別留意運動、飲食和健康相關產品的買家。"},{"en":"Health-conscious consumers may read food labels carefully before buying.","zh":"注重健康的消費者購物前可能會仔細閱讀食品標籤。"},{"en":"Many health-conscious consumers choose clothing that supports walking and exercise.","zh":"很多注重健康的消費者會選擇方便步行和運動的服裝。"},{"en":"Brands often design products specifically for consumers who see health as part of their lifestyle.","zh":"品牌常特別為把健康視為生活方式一部分的消費者設計產品。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"project an active image","meaning":"展現活躍形象","examples":[{"en":"Consumers can project an active image through athleisure.","zh":"消費者可以透過運動休閒服飾展現活躍形象。"},{"en":"To project an active image means to present yourself to others as energetic, sporty or physically engaged.","zh":"展現活躍形象是指令別人覺得自己有活力、愛運動或經常活動。"},{"en":"Carrying sports equipment may project an active image even before someone begins exercising.","zh":"即使還未開始運動，攜帶運動用品也可能展現活躍形象。"},{"en":"Trainers and fitted sportswear can help a wearer project an active image.","zh":"運動鞋和合身運動服可以幫助穿着者展現活躍形象。"},{"en":"Projecting an image is about how others may see you, not necessarily what your real habits are.","zh":"展現某種形象關乎別人如何看你，並不一定等於你的真實習慣。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"satisfy a fashion culture","meaning":"滿足一種時尚文化","examples":[{"en":"Athleisure satisfies a fashion culture that values effortless style.","zh":"運動休閒服飾滿足一種重視不費力時尚感的文化。"},{"en":"To satisfy a fashion culture means to meet the tastes and expectations that are common in a particular style environment.","zh":"「satisfy a fashion culture」表示符合某種時尚環境中常見的品味和期望。"},{"en":"Minimalist brands satisfy a fashion culture that values clean design.","zh":"極簡品牌滿足一種重視乾淨設計的時尚文化。"},{"en":"Athleisure satisfies today’s fashion culture by looking stylish without appearing overly formal.","zh":"運動休閒服飾以時尚但不過分正式的外觀滿足現今時尚文化。"},{"en":"Products succeed when they fit the values consumers currently associate with good style.","zh":"當產品符合消費者當下對好品味的價值觀，就更容易成功。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"increasingly values","meaning":"越來越重視","examples":[{"en":"Fashion culture increasingly values effortless style.","zh":"時尚文化越來越重視不費力的時尚感。"},{"en":"“Increasingly values” means considers something more and more important over time.","zh":"「increasingly values」表示隨時間越來越認為某件事重要。"},{"en":"Employers increasingly value communication skills as teamwork becomes more important.","zh":"隨着團隊合作變得更重要，僱主越來越重視溝通能力。"},{"en":"Fashion increasingly values comfort as people reject unnecessary discomfort.","zh":"當人們拒絕不必要的不舒服，時尚便越來越重視舒適。"},{"en":"What society increasingly values often shapes what companies design and sell.","zh":"社會越來越重視的東西，往往會影響公司設計和銷售甚麼。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"effortless style","meaning":"不費力的時尚感","examples":[{"en":"Athleisure fits a culture that values effortless style.","zh":"運動休閒服飾符合重視不費力時尚感的文化。"},{"en":"Effortless style means looking fashionable and well put together without appearing as if great effort was required.","zh":"不費力的時尚感是指看起來時尚和配搭得宜，卻不顯得花了很多力氣。"},{"en":"A simple white shirt and clean trousers can create effortless style.","zh":"一件簡單白恤衫和乾淨長褲可以營造不費力的時尚感。"},{"en":"Athleisure aims for effortless style by combining comfort with carefully chosen design.","zh":"運動休閒服飾透過結合舒適和仔細設計，追求不費力的時尚感。"},{"en":"Effortless style looks natural, but it may still depend on thoughtful choices about fit and colour.","zh":"不費力的時尚感看起來自然，但仍可能依靠對版型和顏色的細心選擇。"}],"source":"2018 Q6.pdf","sourcePage":12},{"front":"for better or worse","meaning":"不論好壞","examples":[{"en":"For better or worse, clothes now have to support real life.","zh":"不論好壞，衣服現在都必須配合現實生活。"},{"en":"“For better or worse” means whether the result is positive or negative, the situation is now a reality.","zh":"「for better or worse」表示無論結果是好是壞，這種情況已經成為現實。"},{"en":"For better or worse, smartphones have changed how people communicate.","zh":"不論好壞，智能手機已改變人們溝通的方式。"},{"en":"For better or worse, casual dress has entered many workplaces.","zh":"不論好壞，休閒衣着已進入很多工作場所。"},{"en":"This phrase recognises that a change may have both advantages and disadvantages.","zh":"這個片語承認一項改變可能同時有優點和缺點。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"do more than","meaning":"不只是……","examples":[{"en":"Clothes now have to do more than look good on a hanger.","zh":"衣服現在不只是掛起來好看。"},{"en":"“Do more than” means provide additional functions or benefits beyond one basic role.","zh":"「do more than」表示除了基本功能外，還要提供其他作用或好處。"},{"en":"A smartphone does more than make phone calls.","zh":"智能手機不只是用來打電話。"},{"en":"Modern clothing must do more than look attractive; it also needs to support movement and comfort.","zh":"現代服裝不只是要好看，還要配合活動和舒適需要。"},{"en":"Products become more valuable when they do more than satisfy appearance alone.","zh":"當產品不只滿足外觀需要，而有更多用途，它的價值便會提高。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"look good on a hanger","meaning":"掛起來好看","examples":[{"en":"Clothes have to do more than look good on a hanger.","zh":"衣服不能只是掛起來好看。"},{"en":"To look good on a hanger means to appear attractive when displayed, without considering how practical or comfortable the clothing is when worn.","zh":"「look good on a hanger」表示展示時外觀吸引，但沒有考慮真正穿着時是否實用或舒適。"},{"en":"The jacket looked good on a hanger but felt stiff when she tried it on.","zh":"那件外套掛起來好看，但她試穿時覺得很硬。"},{"en":"A beautiful design is not enough if clothes only look good on a hanger and fail in daily life.","zh":"如果衣服只是掛起來好看，卻不適合日常生活，再漂亮的設計也不夠。"},{"en":"Fashion must be judged on the wearer, not only in shops or photographs.","zh":"時尚應該看真正穿在人身上的效果，而不只是商店展示或照片。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"support real life","meaning":"配合現實生活","examples":[{"en":"Ultimately, clothes have to support real life.","zh":"最終，衣服必須配合現實生活。"},{"en":"To support real life means to work well with the actual movements, responsibilities and situations people experience every day.","zh":"配合現實生活是指能真正配合人每天的活動、責任和實際情況。"},{"en":"A school bag supports real life when it is strong, comfortable and easy to carry.","zh":"書包如果堅固、舒服又容易攜帶，就能配合現實生活。"},{"en":"Clothing supports real life when it can handle commuting, sitting, walking and changing weather.","zh":"衣服如果能應付通勤、坐着、步行和天氣轉變，就能配合現實生活。"},{"en":"Good design should serve the person’s actual day rather than only create an attractive image.","zh":"良好設計應服務一個人的真實日程，而不只是製造吸引外觀。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"durable and tasteful","meaning":"耐用而有品味","examples":[{"en":"Fashion brands should design athleisure that is durable and tasteful.","zh":"時裝品牌應設計耐用而有品味的運動休閒服飾。"},{"en":"“Durable and tasteful” means able to last through regular use while also looking stylish in a balanced and attractive way.","zh":"「durable and tasteful」表示既能經得起經常使用，同時外觀有品味、協調而吸引。"},{"en":"A durable and tasteful bag can be used for years without looking old-fashioned.","zh":"一個耐用而有品味的袋可以使用多年而不顯得過時。"},{"en":"Athleisure should be durable enough for movement and tasteful enough for public settings.","zh":"運動休閒服飾應足夠耐用以配合活動，也應足夠有品味以適合公眾場合。"},{"en":"Combining durability with good taste makes clothing both practical and visually appealing.","zh":"把耐用和良好品味結合，可以令衣服同時實用又好看。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"choose pieces that suit","meaning":"選擇適合……的單品","examples":[{"en":"Consumers should choose pieces that suit their lifestyle and the occasion.","zh":"消費者應選擇適合自己生活方式和場合的單品。"},{"en":"To choose pieces that suit something means to select individual clothing items that are appropriate for particular needs or situations.","zh":"「choose pieces that suit」表示挑選符合特定需要或情況的個別服裝單品。"},{"en":"Travellers should choose shoes that suit long days of walking.","zh":"旅客應選擇適合長時間步行的鞋。"},{"en":"Office workers should choose athleisure pieces that suit both comfort needs and workplace expectations.","zh":"上班族應選擇同時適合舒適需要和工作場所要求的運動休閒單品。"},{"en":"A fashionable item is useful only if it suits the person who will actually wear it.","zh":"一件時尚單品只有真正適合穿着者時才有實際價值。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"suit both their lifestyle and the occasion","meaning":"同時配合生活方式和場合","examples":[{"en":"Consumers should choose pieces that suit both their lifestyle and the occasion.","zh":"消費者應選擇同時配合自己生活方式和場合的單品。"},{"en":"This means clothing should fit both a person’s normal activities and the specific social situation in which it is worn.","zh":"這表示衣服既應符合一個人的日常活動，也應符合當時特定社交場合。"},{"en":"Comfortable trainers may suit someone’s lifestyle but not every formal occasion.","zh":"舒適運動鞋可能適合某人的生活方式，但不一定適合每一個正式場合。"},{"en":"A simple jacket can suit both an active lifestyle and a casual business meeting.","zh":"一件簡單外套可以同時配合活躍生活方式和休閒商務會面。"},{"en":"Good clothing choices balance personal convenience with respect for the setting.","zh":"良好的衣着選擇會在個人方便與尊重場合之間取得平衡。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"begin as a trend","meaning":"以潮流的形式開始","examples":[{"en":"Athleisure may have begun as a trend.","zh":"運動休閒服飾可能最初以潮流的形式開始。"},{"en":"To begin as a trend means to start as a temporary popular style before possibly becoming something more permanent.","zh":"「begin as a trend」表示最初只是一種暫時流行風格，之後可能變得更長久。"},{"en":"Online food delivery began as a trend for some users but later became part of everyday life.","zh":"網上外賣對部分使用者來說最初只是一股潮流，後來卻成為日常生活一部分。"},{"en":"Athleisure may have begun as a trend among fitness-focused consumers before spreading widely.","zh":"運動休閒服飾可能最初在注重健身的消費者之間以潮流形式出現，之後才廣泛傳播。"},{"en":"Some trends disappear quickly, while others become lasting changes in behaviour.","zh":"有些潮流很快消失，另一些則會變成長期行為改變。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"show something deeper","meaning":"反映更深層的事情","examples":[{"en":"Its success shows something deeper about modern life.","zh":"它的成功反映了現代生活中一些更深層的事情。"},{"en":"To show something deeper means to reveal a more important underlying meaning beyond the obvious surface fact.","zh":"「show something deeper」表示揭示表面事實以外更重要的深層意義。"},{"en":"Rising demand for flexible work shows something deeper about how people value time.","zh":"對彈性工作需求增加，反映人們如何重視時間這件更深層的事情。"},{"en":"Athleisure’s success shows something deeper about modern expectations of comfort, identity and convenience.","zh":"運動休閒服飾的成功反映現代人對舒適、身份和方便的更深層期望。"},{"en":"A fashion trend can reveal wider social change when we examine why people adopt it.","zh":"當我們研究人們為何接受某種潮流，時尚也可以揭示更廣泛的社會改變。"}],"source":"2018 Q6.pdf","sourcePage":13},{"front":"comfort and style are no longer enemies","meaning":"舒適與時尚不再互相排斥","examples":[{"en":"Athleisure shows that comfort and style are no longer enemies.","zh":"運動休閒服飾顯示舒適與時尚不再互相排斥。"},{"en":"“Comfort and style are no longer enemies” means people no longer have to choose between feeling comfortable and looking fashionable.","zh":"「comfort and style are no longer enemies」表示人們不再必須在舒適和時尚之間二選一。"},{"en":"Stretch fabrics show that comfort and style are no longer enemies in modern workwear.","zh":"有彈性的布料顯示在現代工作服中，舒適與時尚不再互相排斥。"},{"en":"A well-designed pair of trainers can be comfortable and stylish at the same time.","zh":"設計良好的運動鞋可以同時舒適又時尚。"},{"en":"The phrase captures the main idea of athleisure: practical clothing can also be attractive.","zh":"這個說法總結了運動休閒服飾的核心概念：實用服裝同樣可以有吸引力。"}],"source":"2018 Q6.pdf","sourcePage":13}],"dse/writing/part-b/2018/Q7":[{"front":"Screen First, Stage Next","meaning":"先看螢幕，再進劇場","examples":[{"en":"The idea can be described as “screen first, stage next.”","zh":"這個想法可以形容為「先看螢幕，再進劇場」。"},{"en":"Screen first, stage next means people begin by watching a recorded performance, then move on to live theatre.","zh":"Screen first, stage next 指人們先觀看錄製演出，然後再接觸現場劇場。"},{"en":"A student may watch a play recording first and then decide to buy a ticket for the real stage show.","zh":"學生可以先觀看舞台劇錄像，然後決定購買真正舞台演出的門票。"},{"en":"This approach can reduce fear because beginners meet theatre on a familiar screen before entering a theatre.","zh":"這種方法可以減少恐懼，因為初學者先在熟悉的螢幕上接觸劇場，再走進劇院。"},{"en":"Screen first, stage next should lead people toward live performance, not keep them away from it.","zh":"先看螢幕，再進劇場應該帶人走向現場演出，而不是令他們遠離現場演出。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"drama recordings","meaning":"戲劇錄像","examples":[{"en":"HKAPA’s drama recordings could attract new theatre fans.","zh":"香港演藝學院的戲劇錄像可以吸引新的劇場觀眾。"},{"en":"Drama recordings are video versions of stage plays or theatrical performances.","zh":"drama recordings 指舞台劇或戲劇演出的錄像版本。"},{"en":"A school may use drama recordings to introduce students to plays they cannot see live.","zh":"學校可以使用戲劇錄像，向學生介紹他們不能現場觀看的劇目。"},{"en":"Drama recordings help beginners pause, replay, and understand difficult scenes more easily.","zh":"戲劇錄像幫助初學者暫停、重看，並更容易理解困難場面。"},{"en":"Drama recordings are useful introductions, but they are not the same as sitting in a theatre.","zh":"戲劇錄像是有用的入門方式，但它們不同於坐在劇場裏觀看。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"win new theatre fans","meaning":"吸引新的劇場觀眾","examples":[{"en":"Drama recordings could win new theatre fans.","zh":"戲劇錄像可以吸引新的劇場觀眾。"},{"en":"To win new theatre fans means to make more people interested in theatre.","zh":"win new theatre fans 指令更多人對劇場產生興趣。"},{"en":"A funny short performance online may win new theatre fans among students.","zh":"網上一段有趣的短演出，可能在學生之間吸引新的劇場觀眾。"},{"en":"Recordings can win new theatre fans by showing that plays are lively, emotional, and understandable.","zh":"錄像可以透過展示舞台劇生動、有情感和可理解，吸引新的劇場觀眾。"},{"en":"Winning new theatre fans matters because theatre needs fresh audiences to stay alive.","zh":"吸引新的劇場觀眾很重要，因為劇場需要新觀眾才能保持生命力。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"theatre fans","meaning":"劇場愛好者","examples":[{"en":"The recordings may help create more theatre fans.","zh":"這些錄像可能有助培養更多劇場愛好者。"},{"en":"Theatre fans are people who enjoy watching plays and following theatre performances.","zh":"theatre fans 指喜歡觀看舞台劇和關注劇場演出的人。"},{"en":"Theatre fans may read reviews, buy tickets early, and recommend plays to friends.","zh":"劇場愛好者可能會閱讀評論、提早買票，並向朋友推薦劇目。"},{"en":"People often become theatre fans after one performance makes them feel deeply involved.","zh":"人們常在一次演出令他們深深投入後，成為劇場愛好者。"},{"en":"Theatre fans support the art form by returning to watch live shows.","zh":"劇場愛好者透過再次觀看現場演出，支持這種藝術形式。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"awkward problem","meaning":"尷尬的問題","examples":[{"en":"Theatre has always had one awkward problem.","zh":"劇場一直有一個尷尬的問題。"},{"en":"An awkward problem is a difficult issue that is uncomfortable to discuss or solve.","zh":"awkward problem 指難以處理，而且令人不太舒服去討論或解決的問題。"},{"en":"A school may face an awkward problem when students want freedom but teachers need rules.","zh":"當學生想要自由，但老師需要規則時，學校可能面對尷尬的問題。"},{"en":"Theatre’s awkward problem is that people who do not know it may feel afraid to try it.","zh":"劇場的尷尬問題是，不認識它的人可能害怕嘗試。"},{"en":"Calling it awkward shows that the problem is not simple, but it must still be addressed.","zh":"稱它為尷尬的問題，顯示問題不簡單，但仍必須處理。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"people who already love it","meaning":"已經喜歡它的人","examples":[{"en":"People who already love theatre know why it matters.","zh":"已經喜歡劇場的人明白它為何重要。"},{"en":"People who already love it are those who already understand and enjoy the activity or art form.","zh":"people who already love it 指已經理解並喜歡某活動或藝術形式的人。"},{"en":"People who already love reading may not understand why others find books boring.","zh":"已經喜歡閱讀的人，未必理解為何其他人覺得書本沉悶。"},{"en":"A challenge appears when people who already love something speak only to each other.","zh":"當已經喜歡某事的人只與彼此交談時，挑戰就會出現。"},{"en":"Theatre must reach beyond people who already love it if it wants new audiences.","zh":"如果劇場想要新觀眾，就必須接觸已經喜歡它的人以外的人。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"know why it matters","meaning":"明白它為何重要","examples":[{"en":"Theatre lovers know why theatre matters.","zh":"劇場愛好者明白劇場為何重要。"},{"en":"To know why it matters means to understand why something is valuable or important.","zh":"know why it matters 指理解某事為何有價值或重要。"},{"en":"Students know why sleep matters when tiredness affects their memory and mood.","zh":"當疲累影響記憶和心情時，學生會明白睡眠為何重要。"},{"en":"People support an art form more strongly when they know why it matters.","zh":"當人們明白一種藝術形式為何重要時，會更有力地支持它。"},{"en":"Recordings can help beginners know why theatre matters before they attend in person.","zh":"錄像可以幫助初學者在親身入場前，明白劇場為何重要。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"assume it is expensive","meaning":"以為它很昂貴","examples":[{"en":"Some people assume theatre is expensive.","zh":"有些人以為劇場很昂貴。"},{"en":"To assume it is expensive means to believe it costs a lot without checking carefully.","zh":"assume it is expensive 指沒有仔細查證就相信它花費很高。"},{"en":"Some students assume classical music concerts are expensive, so they never look for student tickets.","zh":"有些學生以為古典音樂會很昂貴，所以從不尋找學生票。"},{"en":"This assumption can stop people from trying theatre even when affordable seats exist.","zh":"即使有可負擔的座位，這種假設也可能阻止人們嘗試劇場。"},{"en":"Clear information about ticket prices can challenge the belief that theatre is always expensive.","zh":"清楚的票價資訊可以挑戰劇場總是昂貴的想法。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"not for them","meaning":"不適合他們","examples":[{"en":"Some people feel that theatre is not for them.","zh":"有些人覺得劇場不適合他們。"},{"en":"Not for them means they feel something does not suit their taste, background, or confidence level.","zh":"not for them 指他們覺得某事不符合自己的品味、背景或信心水平。"},{"en":"A teenager may think museums are not for them until a lively exhibition changes their mind.","zh":"青少年可能以為博物館不適合自己，直到一個生動展覽改變他的想法。"},{"en":"People may avoid theatre if they believe it is only for educated or wealthy audiences.","zh":"如果人們相信劇場只屬於受過高等教育或富有的觀眾，他們可能會避開劇場。"},{"en":"A good introduction can show beginners that theatre may be for them after all.","zh":"好的介紹可以讓初學者看見，劇場其實也可能適合他們。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"against this background","meaning":"在這背景下","examples":[{"en":"Against this background, HKAPA is considering a new screening scheme.","zh":"在這背景下，香港演藝學院正在考慮一項新的放映計劃。"},{"en":"Against this background means because of the situation just described.","zh":"against this background 指由於剛才描述的情況。"},{"en":"Against this background of falling reading habits, the school opened a new library corner.","zh":"在閱讀習慣下降的背景下，學校開設了新的圖書角。"},{"en":"Writers use this phrase to connect a problem with a proposed response.","zh":"作者使用這個短語，把一個問題與建議回應連接起來。"},{"en":"Against this background, drama recordings appear as a possible way to reach new audiences.","zh":"在這背景下，戲劇錄像看起來是一種接觸新觀眾的可能方法。"}],"source":"2018 Q7.pdf","sourcePage":1},{"front":"the Hong Kong Academy for Performing Arts","meaning":"香港演藝學院","examples":[{"en":"The Hong Kong Academy for Performing Arts is considering the idea.","zh":"香港演藝學院正在考慮這個想法。"},{"en":"The Hong Kong Academy for Performing Arts is an institution connected with training and promoting the performing arts.","zh":"the Hong Kong Academy for Performing Arts 指與表演藝術培訓和推廣有關的機構。"},{"en":"Students interested in acting, dance, music, or theatre may learn about this academy.","zh":"對演戲、舞蹈、音樂或劇場有興趣的學生，可能會認識這所學院。"},{"en":"If the academy screens drama recordings, it can connect education with public access.","zh":"如果學院放映戲劇錄像，就能把教育與公眾接觸機會連接起來。"},{"en":"The name is often shortened to HKAPA in discussion.","zh":"這個名稱在討論中常被簡稱為 HKAPA。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"be considering","meaning":"正在考慮","examples":[{"en":"HKAPA is considering screening recordings of live drama performances.","zh":"香港演藝學院正在考慮放映現場戲劇演出的錄像。"},{"en":"To be considering something means to be thinking seriously about whether to do it.","zh":"be considering something 指正在認真思考是否要做某事。"},{"en":"A school may be considering longer library hours if many students ask for study space.","zh":"如果很多學生要求自修空間，學校可能正在考慮延長圖書館開放時間。"},{"en":"People consider an idea before deciding because they need to weigh benefits and problems.","zh":"人們在決定前會考慮一個想法，因為他們需要衡量好處和問題。"},{"en":"Being considering a plan does not mean it is confirmed; it means it is under serious thought.","zh":"正在考慮一項計劃不代表已經確認；而是代表它正被認真思考。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"screen video recordings","meaning":"放映錄像","examples":[{"en":"HKAPA may screen video recordings of live drama performances.","zh":"香港演藝學院可能放映現場戲劇演出的錄像。"},{"en":"To screen video recordings means to show recorded videos to an audience.","zh":"screen video recordings 指向觀眾播放錄製影片。"},{"en":"A film club may screen video recordings of old performances for students.","zh":"電影會可能為學生放映舊演出的錄像。"},{"en":"Screening recordings can make distant or expensive productions easier for the public to see.","zh":"放映錄像可以令遙遠或昂貴的製作更容易讓公眾看見。"},{"en":"When an organisation screens video recordings, it should explain what viewers are watching and why it matters.","zh":"當機構放映錄像時，應解釋觀眾正在看甚麼，以及它為何重要。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"live drama performances","meaning":"現場戲劇演出","examples":[{"en":"The recordings show live drama performances from around the world.","zh":"這些錄像展示來自世界各地的現場戲劇演出。"},{"en":"Live drama performances are plays acted in front of an audience in real time.","zh":"live drama performances 指演員在觀眾面前即時演出的舞台劇。"},{"en":"A live drama performance may feel different each night because actors and audiences react to one another.","zh":"現場戲劇演出每晚都可能感覺不同，因為演員和觀眾會互相反應。"},{"en":"Recordings of live drama performances can preserve a show for people who missed it.","zh":"現場戲劇演出的錄像可以為錯過演出的人保存該劇。"},{"en":"However, a recording cannot fully capture the energy of being in the same room.","zh":"然而，錄像不能完全捕捉身處同一空間的能量。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"from theatres around the world","meaning":"來自世界各地劇院","examples":[{"en":"The recordings come from theatres around the world.","zh":"這些錄像來自世界各地劇院。"},{"en":"From theatres around the world means from performance spaces in many different countries or regions.","zh":"from theatres around the world 指來自許多不同國家或地區的表演空間。"},{"en":"Students can learn different acting styles from theatres around the world.","zh":"學生可以從世界各地劇院的演出中學習不同演技風格。"},{"en":"Recordings from theatres around the world can widen what local audiences imagine theatre to be.","zh":"來自世界各地劇院的錄像，可以擴闊本地觀眾對劇場的想像。"},{"en":"This phrase suggests variety beyond one city or one culture.","zh":"這個短語暗示超越單一城市或單一文化的多樣性。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"widen public access","meaning":"擴大公眾接觸機會","examples":[{"en":"The scheme aims to widen public access to theatre.","zh":"這項計劃旨在擴大公眾接觸劇場的機會。"},{"en":"To widen public access means to make something easier for more ordinary people to reach or use.","zh":"widen public access 指令更多普通人更容易接觸或使用某事物。"},{"en":"A library widens public access to knowledge by offering free books and computers.","zh":"圖書館透過提供免費書本和電腦，擴大公眾接觸知識的機會。"},{"en":"Recordings widen public access by letting people try theatre without high cost or pressure.","zh":"錄像讓人們不用高昂成本或壓力就能嘗試劇場，從而擴大公眾接觸機會。"},{"en":"Widening public access matters when an art form feels distant from everyday life.","zh":"當一種藝術形式令人覺得遙遠時，擴大公眾接觸機會很重要。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"public access","meaning":"公眾接觸機會","examples":[{"en":"Video recordings can improve public access to theatre.","zh":"錄像可以改善公眾接觸劇場的機會。"},{"en":"Public access means the chance for ordinary people to reach, use, or experience something.","zh":"public access 指普通人接觸、使用或體驗某事物的機會。"},{"en":"Public access to parks is important because families need affordable places to rest.","zh":"公眾接觸公園的機會很重要，因為家庭需要可負擔的休息地方。"},{"en":"Better public access to theatre can help students, elderly people, and low-income audiences take part.","zh":"更好的劇場公眾接觸機會，可以幫助學生、長者和低收入觀眾參與。"},{"en":"Public access does not mean everything is free; it means fewer people are unfairly excluded.","zh":"公眾接觸機會不代表所有東西都免費；而是代表較少人被不公平地排除。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"turn curiosity into actual attendance","meaning":"將好奇心轉化為實際入場","examples":[{"en":"The recordings may turn curiosity into actual attendance.","zh":"這些錄像可能將好奇心轉化為實際入場。"},{"en":"To turn curiosity into actual attendance means to change interest into the action of going to an event.","zh":"turn curiosity into actual attendance 指把興趣轉化為到場參與活動的行動。"},{"en":"A school open day can turn curiosity into actual attendance at a new club.","zh":"學校開放日可以把學生的好奇心轉化為實際參加新社團。"},{"en":"If viewers enjoy a recording, they may become more willing to attend a live show.","zh":"如果觀眾喜歡一段錄像，他們可能更願意出席現場演出。"},{"en":"Curiosity is only the beginning; actual attendance shows people have taken the next step.","zh":"好奇心只是開始；實際入場顯示人們已踏出下一步。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"having just watched","meaning":"剛剛看完","examples":[{"en":"Having just watched one of these recordings, I support the idea.","zh":"剛剛看完其中一段錄像後，我支持這個想法。"},{"en":"Having just watched means after recently watching something.","zh":"having just watched 指最近剛看完某事物之後。"},{"en":"Having just watched a documentary about food waste, the students discussed how to reduce lunch leftovers.","zh":"剛剛看完一部關於食物浪費的紀錄片後，學生討論如何減少午餐剩食。"},{"en":"This phrase is useful when a recent experience explains someone’s opinion.","zh":"當近期經驗能解釋某人的觀點時，這個短語很有用。"},{"en":"Having just watched a play recording, a beginner may feel more confident about live theatre.","zh":"剛剛看完舞台劇錄像後，初學者可能對現場劇場更有信心。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"I would argue that","meaning":"我會認為","examples":[{"en":"I would argue that the idea is not a replacement for live theatre.","zh":"我會認為這個想法不是現場劇場的替代品。"},{"en":"I would argue that is a formal way to introduce your opinion or position.","zh":"I would argue that 是正式地引入自己意見或立場的說法。"},{"en":"I would argue that homework is useful only when it helps students practise clearly.","zh":"我會認為，功課只有在清楚幫助學生練習時才有用。"},{"en":"Writers use this phrase to sound thoughtful rather than too forceful.","zh":"作者使用這個短語，令語氣顯得經過思考，而不是過分強硬。"},{"en":"In an essay, I would argue that helps present a claim that will be explained later.","zh":"在文章中，I would argue that 有助提出稍後會解釋的主張。"}],"source":"2018 Q7.pdf","sourcePage":2},{"front":"replacement for","meaning":"……的替代品","examples":[{"en":"The recording is not a replacement for live theatre.","zh":"錄像不是現場劇場的替代品。"},{"en":"A replacement for something is something used instead of the original thing.","zh":"replacement for 某事物，指用來代替原本事物的東西。"},{"en":"Online classes can help during illness, but they are not always a replacement for classroom learning.","zh":"網課可以在生病期間有幫助，但不一定是課室學習的替代品。"},{"en":"A recording may support theatre education without replacing the live experience.","zh":"錄像可以支援劇場教育，而不取代現場體驗。"},{"en":"Calling something a replacement suggests it could take the original thing’s place.","zh":"稱某物為替代品，暗示它可以取代原本事物的位置。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"live theatre","meaning":"現場劇場","examples":[{"en":"Live theatre offers something that a screen cannot fully reproduce.","zh":"現場劇場提供螢幕不能完全重現的東西。"},{"en":"Live theatre is theatre performed in front of an audience in the same space and time.","zh":"live theatre 指在同一空間和時間裏，於觀眾面前演出的劇場。"},{"en":"In live theatre, actors can feel the audience’s silence, laughter, and attention.","zh":"在現場劇場中，演員可以感受到觀眾的沉默、笑聲和注意力。"},{"en":"Live theatre feels special because mistakes, pauses, and reactions happen in the moment.","zh":"現場劇場特別之處在於錯誤、停頓和反應都在當下發生。"},{"en":"A recording can introduce theatre, but live theatre gives the shared presence.","zh":"錄像可以介紹劇場，但現場劇場提供共同臨場感。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"remarkably effective doorway into","meaning":"進入……非常有效的門路","examples":[{"en":"The recordings are a remarkably effective doorway into theatre.","zh":"這些錄像是進入劇場非常有效的門路。"},{"en":"A remarkably effective doorway into something is a very successful first route into a new area.","zh":"remarkably effective doorway into 某領域，指進入新範疇的非常成功的初步途徑。"},{"en":"Short stories can be a remarkably effective doorway into reading for students who fear long novels.","zh":"對害怕長篇小說的學生來說，短篇故事可以是進入閱讀非常有效的門路。"},{"en":"Recordings are effective because they let beginners try theatre without pressure.","zh":"錄像有效，因為它讓初學者不用承受壓力就能嘗試劇場。"},{"en":"A good doorway invites people to enter, not to stay outside forever.","zh":"好的門路會邀請人進入，而不是永遠留在外面。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"from my perspective","meaning":"從我的角度看","examples":[{"en":"From my perspective, the recordings can attract more people to stage plays.","zh":"從我的角度看，這些錄像可以吸引更多人接觸舞台劇。"},{"en":"From my perspective means from my point of view or based on how I see the issue.","zh":"from my perspective 指從我的觀點或我看待問題的方式來說。"},{"en":"From my perspective, school rules work best when students understand the reasons behind them.","zh":"從我的角度看，當學生明白校規背後原因時，校規最有效。"},{"en":"This phrase is useful when presenting an opinion while admitting others may see things differently.","zh":"當提出意見但承認別人可能有不同看法時，這個短語很有用。"},{"en":"From my perspective, recordings should be treated as invitations to theatre.","zh":"從我的角度看，錄像應被視為走進劇場的邀請。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"attract more people to","meaning":"吸引更多人接觸","examples":[{"en":"The scheme can attract more people to stage plays.","zh":"這項計劃可以吸引更多人接觸舞台劇。"},{"en":"To attract more people to something means to make more people interested in joining, visiting, or trying it.","zh":"attract more people to 某事，指令更多人有興趣參加、到訪或嘗試它。"},{"en":"Free workshops can attract more people to a community art centre.","zh":"免費工作坊可以吸引更多人接觸社區藝術中心。"},{"en":"Clear explanations attract more people to difficult subjects because they reduce fear.","zh":"清楚解釋能吸引更多人接觸困難科目，因為它們減少恐懼。"},{"en":"To attract more people to theatre, the first experience should feel welcoming.","zh":"要吸引更多人接觸劇場，第一次體驗應該令人感到受歡迎。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"stage plays","meaning":"舞台劇","examples":[{"en":"The recordings can encourage audiences to watch stage plays.","zh":"這些錄像可以鼓勵觀眾觀看舞台劇。"},{"en":"Stage plays are stories performed by actors on a stage before an audience.","zh":"stage plays 指演員在舞台上向觀眾表演的故事。"},{"en":"Students may study stage plays to learn dialogue, character, movement, and conflict.","zh":"學生可能研究舞台劇，以學習對白、角色、動作和衝突。"},{"en":"Stage plays feel different from films because the action happens live in front of viewers.","zh":"舞台劇與電影不同，因為行動在觀眾面前現場發生。"},{"en":"Watching recordings may help beginners understand stage plays before buying tickets.","zh":"觀看錄像可以幫助初學者在買票前理解舞台劇。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"provided that","meaning":"前提是；只要","examples":[{"en":"The idea works, provided that HKAPA presents it as a first step.","zh":"這個想法可行，前提是香港演藝學院把它定位為第一步。"},{"en":"Provided that means only if a certain condition is met.","zh":"provided that 指只有在某個條件達成時才可以。"},{"en":"Students may use the rehearsal room, provided that they clean it afterwards.","zh":"學生可以使用排練室，只要之後清理乾淨。"},{"en":"The screening scheme can help theatre, provided that it encourages live attendance.","zh":"這項放映計劃可以幫助劇場，前提是它鼓勵現場入場。"},{"en":"This phrase is useful for supporting an idea while setting a clear condition.","zh":"這個短語有助在支持一個想法的同時，設下清楚條件。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"present them as","meaning":"將它們定位為","examples":[{"en":"HKAPA should present the recordings as a first step.","zh":"香港演藝學院應將這些錄像定位為第一步。"},{"en":"To present them as something means to describe or frame them in a particular way.","zh":"present them as 某物，指以某種方式描述或定位它們。"},{"en":"A teacher may present mistakes as learning opportunities rather than failures.","zh":"老師可以把錯誤定位為學習機會，而不是失敗。"},{"en":"If HKAPA presents recordings as introductions, viewers may still value live theatre.","zh":"如果香港演藝學院把錄像定位為入門介紹，觀眾仍可能重視現場劇場。"},{"en":"How something is presented can change how people use and understand it.","zh":"某事物如何被定位，會改變人們如何使用和理解它。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"a first step","meaning":"第一步","examples":[{"en":"The screenings should be treated as a first step into theatre.","zh":"這些放映應被視為走進劇場的第一步。"},{"en":"A first step is the beginning action that helps someone move toward a larger goal.","zh":"a first step 指幫助某人走向更大目標的開始行動。"},{"en":"Reading a short article can be a first step toward understanding a difficult topic.","zh":"閱讀一篇短文章可以是理解困難議題的第一步。"},{"en":"A first step should be easy enough to reduce fear but useful enough to create interest.","zh":"第一步應該夠容易去減少恐懼，也夠有用去產生興趣。"},{"en":"Theatre recordings work best when they become a first step toward live performance.","zh":"當戲劇錄像成為走向現場演出的第一步時，效果最好。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"rather than the final destination","meaning":"而不是最終目的地","examples":[{"en":"The recording should be a first step rather than the final destination.","zh":"錄像應是第一步，而不是最終目的地。"},{"en":"Rather than the final destination means not as the end point, but as part of a longer journey.","zh":"rather than the final destination 指不是作為終點，而是作為更長旅程的一部分。"},{"en":"A trial lesson should be an introduction rather than the final destination of learning.","zh":"試堂應該是學習的入門，而不是最終目的地。"},{"en":"If recordings become the final destination, viewers may never experience live theatre.","zh":"如果錄像成為最終目的地，觀眾可能永遠不會體驗現場劇場。"},{"en":"This phrase reminds us that the recording should lead somewhere further.","zh":"這個短語提醒我們，錄像應把人帶向更遠的地方。"}],"source":"2018 Q7.pdf","sourcePage":3},{"front":"greatest strength","meaning":"最大優點","examples":[{"en":"The greatest strength of recorded theatre is that it lowers the entry barrier.","zh":"錄製劇場的最大優點是它降低入門門檻。"},{"en":"Greatest strength means the most important advantage or best quality.","zh":"greatest strength 指最重要的優勢或最好特質。"},{"en":"The greatest strength of a good teacher may be making difficult ideas simple.","zh":"好老師的最大優點可能是把困難想法變得簡單。"},{"en":"The greatest strength of recordings is that they make theatre feel less distant.","zh":"錄像的最大優點是令劇場感覺不再那麼遙遠。"},{"en":"Identifying the greatest strength helps explain why a proposal is worth trying.","zh":"找出最大優點有助解釋為何一項建議值得嘗試。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"recorded theatre","meaning":"錄製劇場","examples":[{"en":"Recorded theatre can introduce new audiences to stage plays.","zh":"錄製劇場可以向新觀眾介紹舞台劇。"},{"en":"Recorded theatre is theatre captured on video so people can watch it later or elsewhere.","zh":"recorded theatre 指被拍攝成影片，讓人日後或在其他地方觀看的劇場演出。"},{"en":"Recorded theatre allows students to see foreign productions without travelling.","zh":"錄製劇場讓學生不用旅行也能觀看外國製作。"},{"en":"Recorded theatre can support learning because viewers can notice details more slowly.","zh":"錄製劇場可以支援學習，因為觀眾可以較慢地留意細節。"},{"en":"It is helpful, but recorded theatre should not be confused with the live event itself.","zh":"它很有幫助，但錄製劇場不應與現場事件本身混為一談。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"lower the psychological barrier to entry","meaning":"降低入門心理門檻","examples":[{"en":"Recorded theatre lowers the psychological barrier to entry.","zh":"錄製劇場降低入門心理門檻。"},{"en":"To lower the psychological barrier to entry means to make people feel less nervous about trying something new.","zh":"lower the psychological barrier to entry 指令人在嘗試新事物時較不緊張。"},{"en":"A free trial class can lower the psychological barrier to entry for shy beginners.","zh":"免費試堂可以為害羞初學者降低入門心理門檻。"},{"en":"Recordings lower this barrier because viewers can watch theatre without feeling judged.","zh":"錄像降低這種門檻，因為觀眾可以在不怕被評價的情況下觀看劇場。"},{"en":"Lowering the psychological barrier matters when fear, not money, stops people from joining.","zh":"當阻止人參與的不是金錢，而是恐懼時，降低入門心理門檻很重要。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"psychological barrier","meaning":"心理門檻","examples":[{"en":"Many non-theatre-goers face a psychological barrier.","zh":"許多平日不看劇場的人面對心理門檻。"},{"en":"A psychological barrier is a fear or mental block that makes someone avoid something.","zh":"psychological barrier 指令某人避開某事的恐懼或心理障礙。"},{"en":"Some students face a psychological barrier before speaking English in public.","zh":"有些學生在公開說英語前會面對心理門檻。"},{"en":"A psychological barrier can be strong even when the actual task is not very difficult.","zh":"即使實際任務不是很難，心理門檻也可能很強。"},{"en":"Friendly introductions help remove psychological barriers by making the first try feel safe.","zh":"友善的介紹能令第一次嘗試感覺安全，從而幫助消除心理門檻。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"barrier to entry","meaning":"入門門檻","examples":[{"en":"A recording can lower the barrier to entry.","zh":"錄像可以降低入門門檻。"},{"en":"A barrier to entry is anything that makes it hard for people to begin or join.","zh":"barrier to entry 指任何令人在開始或參與時感到困難的因素。"},{"en":"High fees can be a barrier to entry for sports clubs.","zh":"高昂費用可以成為加入體育會的入門門檻。"},{"en":"Confusing language can create a barrier to entry for people trying a new subject.","zh":"令人困惑的語言會為嘗試新科目的人製造入門門檻。"},{"en":"Reducing barriers to entry helps more people take the first step.","zh":"降低入門門檻有助更多人踏出第一步。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"non-theatre-goers","meaning":"平日不看劇場的人","examples":[{"en":"Many non-theatre-goers feel nervous about watching a stage play.","zh":"許多平日不看劇場的人對觀看舞台劇感到緊張。"},{"en":"Non-theatre-goers are people who do not usually attend theatre performances.","zh":"non-theatre-goers 指平日不去觀看劇場演出的人。"},{"en":"Non-theatre-goers may worry about ticket prices, dress codes, or understanding the story.","zh":"平日不看劇場的人可能擔心票價、服裝要求或能否理解故事。"},{"en":"Recordings can help non-theatre-goers realise that theatre is not as frightening as they imagined.","zh":"錄像可以幫助平日不看劇場的人明白，劇場沒有他們想像中那麼可怕。"},{"en":"To attract non-theatre-goers, the first experience should feel clear and welcoming.","zh":"要吸引平日不看劇場的人，第一次體驗應該清晰而友善。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"feel unfamiliar","meaning":"感到陌生","examples":[{"en":"A stage play can feel unfamiliar before it even begins.","zh":"舞台劇甚至在開始之前就可能令人感到陌生。"},{"en":"To feel unfamiliar means to seem strange because someone has little experience with it.","zh":"feel unfamiliar 指因為缺乏經驗而感覺陌生。"},{"en":"A new school may feel unfamiliar on the first day.","zh":"新學校在第一天可能令人感到陌生。"},{"en":"Theatre may feel unfamiliar if viewers do not know the rules, language, or style.","zh":"如果觀眾不了解規則、語言或風格，劇場可能令人感到陌生。"},{"en":"Something that feels unfamiliar at first can become enjoyable after a gentle introduction.","zh":"一開始令人感到陌生的事物，在溫和介紹後可以變得有趣。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"before it even begins","meaning":"甚至在開始之前","examples":[{"en":"A stage play may feel unfamiliar before it even begins.","zh":"舞台劇甚至在開始之前就可能令人感到陌生。"},{"en":"Before it even begins means before the main activity has started.","zh":"before it even begins 指在主要活動開始之前。"},{"en":"A student may feel nervous before the exam even begins.","zh":"學生可能在考試甚至開始之前已感到緊張。"},{"en":"People can reject an experience before it even begins if their fears are strong enough.","zh":"如果恐懼夠強，人們可能在一段體驗甚至開始之前就拒絕它。"},{"en":"Theatre can seem difficult before it even begins because newcomers imagine many hidden rules.","zh":"劇場甚至在開始之前就可能顯得困難，因為新觀眾想像有很多隱藏規則。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"What if…?","meaning":"如果……怎麼辦？","examples":[{"en":"Viewers may ask, “What if I do not understand the plot?”","zh":"觀眾可能會問：「如果我不明白情節怎麼辦？」"},{"en":"What if is used to express worry about a possible situation.","zh":"What if 用來表達對可能情況的擔心。"},{"en":"A student may ask, “What if I forget my lines during the speech?”","zh":"學生可能會問：「如果我演講時忘詞怎麼辦？」"},{"en":"What if questions often appear before people try something new or risky.","zh":"當人們嘗試新事物或有風險的事情前，常會出現 What if 問題。"},{"en":"Answering these worries clearly can help beginners feel safer.","zh":"清楚回應這些憂慮，可以幫助初學者感到更安全。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"language is difficult","meaning":"語言艱深","examples":[{"en":"Some viewers worry that the language is difficult.","zh":"有些觀眾擔心語言艱深。"},{"en":"Language is difficult means the words, sentence patterns, or style are hard to understand.","zh":"language is difficult 指用詞、句式或風格難以理解。"},{"en":"A history book may feel difficult if the language is formal and old-fashioned.","zh":"如果語言正式又古舊，一本歷史書可能令人覺得艱深。"},{"en":"Viewers may avoid theatre when they think the language is difficult or too literary.","zh":"當觀眾以為語言艱深或太文學化時，可能會避開劇場。"},{"en":"Introductions and subtitles can help when the language is difficult.","zh":"當語言艱深時，簡介和字幕可以提供幫助。"}],"source":"2018 Q7.pdf","sourcePage":4},{"front":"acting feels exaggerated","meaning":"演技感覺誇張","examples":[{"en":"Some viewers worry that the acting feels exaggerated.","zh":"有些觀眾擔心演技感覺誇張。"},{"en":"Acting feels exaggerated means the performance seems too big, unnatural, or dramatic.","zh":"acting feels exaggerated 指表演看起來過大、不自然或太戲劇化。"},{"en":"New theatre viewers may find stage gestures exaggerated because they are used to film acting.","zh":"新劇場觀眾可能覺得舞台動作誇張，因為他們習慣電影演技。"},{"en":"Stage acting can feel exaggerated when viewers do not understand that actors must reach the whole room.","zh":"當觀眾不明白演員需要讓整個劇場都感受到表演時，舞台演技可能感覺誇張。"},{"en":"After learning theatre style, audiences may see exaggerated acting as expressive rather than strange.","zh":"學會劇場風格後，觀眾可能會把誇張演技視為有表現力，而不是奇怪。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"understand the plot","meaning":"明白情節","examples":[{"en":"Viewers may worry that they will not understand the plot.","zh":"觀眾可能擔心自己不會明白情節。"},{"en":"To understand the plot means to follow the main events and conflicts in a story.","zh":"understand the plot 指跟得上故事中的主要事件和衝突。"},{"en":"Students understand the plot better when they know who wants what and why.","zh":"當學生知道誰想要甚麼以及原因時，就更能明白情節。"},{"en":"If viewers cannot understand the plot, they may feel lost even if the acting is strong.","zh":"如果觀眾不能明白情節，即使演技很強，他們也可能感到迷失。"},{"en":"Short introductions can help audiences understand the plot before the performance begins.","zh":"簡短介紹可以幫助觀眾在演出開始前明白情節。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"answer these fears","meaning":"回應這些憂慮","examples":[{"en":"A recording answers these fears in a low-risk way.","zh":"錄像以低風險方式回應這些憂慮。"},{"en":"To answer these fears means to respond to worries and make them feel less serious.","zh":"answer these fears 指回應擔心，並令它們感覺不那麼嚴重。"},{"en":"A school tour answers students’ fears by showing them where classrooms and toilets are.","zh":"學校導覽透過展示課室和洗手間位置，回應學生的憂慮。"},{"en":"Theatre recordings answer fears by letting people test the experience privately.","zh":"戲劇錄像讓人們私下測試體驗，從而回應憂慮。"},{"en":"Good explanations answer fears better than simply saying, “Do not worry.”","zh":"好的解釋比單純說「不用擔心」更能回應憂慮。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"in a low-risk way","meaning":"以低風險方式","examples":[{"en":"Viewers can try theatre in a low-risk way.","zh":"觀眾可以以低風險方式嘗試劇場。"},{"en":"In a low-risk way means with little chance of losing money, confidence, or comfort.","zh":"in a low-risk way 指損失金錢、信心或舒適感的機會很低。"},{"en":"A free trial lesson lets children try music in a low-risk way.","zh":"免費試堂讓孩子以低風險方式嘗試音樂。"},{"en":"Watching a recording is low-risk because viewers can leave, pause, or try again.","zh":"看錄像風險較低，因為觀眾可以離開、暫停或重新嘗試。"},{"en":"Low-risk first steps are helpful when people feel nervous about a new activity.","zh":"當人們對新活動感到緊張時，低風險的第一步很有幫助。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"first encounter","meaning":"初次接觸","examples":[{"en":"Viewers can first encounter the rhythm of stage dialogue through recordings.","zh":"觀眾可以透過錄像初次接觸舞台對白的節奏。"},{"en":"A first encounter is the first time someone meets, sees, or experiences something.","zh":"first encounter 指某人第一次遇見、看見或體驗某事。"},{"en":"A child’s first encounter with poetry may happen through a song.","zh":"孩子可能透過歌曲初次接觸詩歌。"},{"en":"A positive first encounter can make people more willing to continue learning.","zh":"正面的初次接觸可以令人更願意繼續學習。"},{"en":"Recordings can make a first encounter with theatre calmer and less intimidating.","zh":"錄像可以令初次接觸劇場更平靜、較不令人卻步。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"rhythm of stage dialogue","meaning":"舞台對白的節奏","examples":[{"en":"Viewers can experience the rhythm of stage dialogue.","zh":"觀眾可以體驗舞台對白的節奏。"},{"en":"The rhythm of stage dialogue means the speed, pauses, and flow of spoken lines in a play.","zh":"rhythm of stage dialogue 指舞台劇對白的速度、停頓和流動。"},{"en":"Students notice the rhythm of stage dialogue when actors pause before important words.","zh":"當演員在重要字眼前停頓時，學生會注意到舞台對白的節奏。"},{"en":"The rhythm of stage dialogue can make a scene feel tense, funny, or intimate.","zh":"舞台對白的節奏可以令一場戲感覺緊張、有趣或親密。"},{"en":"Listening to recordings helps beginners hear how theatre speech differs from everyday talk.","zh":"聆聽錄像有助初學者聽出劇場說話與日常說話的不同。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"intimacy of a monologue","meaning":"獨白的親密感","examples":[{"en":"A recording can reveal the intimacy of a monologue.","zh":"錄像可以展現獨白的親密感。"},{"en":"The intimacy of a monologue means the close, private feeling created when one character speaks alone.","zh":"intimacy of a monologue 指一個角色獨自說話時產生的貼近而私密的感覺。"},{"en":"A monologue about grief can feel intimate because the audience hears a character’s inner thoughts.","zh":"關於悲傷的獨白可以感覺親密，因為觀眾聽到角色的內心想法。"},{"en":"Close-up shots may make the intimacy of a monologue easier for beginners to notice.","zh":"特寫鏡頭可能令獨白的親密感更容易被初學者注意到。"},{"en":"This intimacy can make viewers feel as if the actor is speaking directly to them.","zh":"這種親密感可以令觀眾感覺演員像直接對自己說話。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"monologue","meaning":"獨白","examples":[{"en":"A monologue can create a close connection with the audience.","zh":"獨白可以與觀眾建立緊密連繫。"},{"en":"A monologue is a long speech by one character in a play or performance.","zh":"monologue 指戲劇或演出中由一個角色說出的長篇說話。"},{"en":"In a monologue, a character may explain a secret, memory, fear, or decision.","zh":"在獨白中，角色可能解釋秘密、回憶、恐懼或決定。"},{"en":"Monologues help audiences understand a character’s inner world.","zh":"獨白幫助觀眾理解角色的內心世界。"},{"en":"A strong monologue can hold attention even when no other actor is speaking.","zh":"有力的獨白即使沒有其他演員說話，也能抓住注意力。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"tension of a crisis scene","meaning":"危機場面的緊張感","examples":[{"en":"Viewers can feel the tension of a crisis scene.","zh":"觀眾可以感受到危機場面的緊張感。"},{"en":"The tension of a crisis scene means the nervous pressure created when characters face a serious problem.","zh":"tension of a crisis scene 指角色面對嚴重問題時產生的緊張壓力。"},{"en":"A hospital drama may show the tension of a crisis scene when doctors must act quickly.","zh":"醫院劇中，當醫生必須迅速行動時，可能會展示危機場面的緊張感。"},{"en":"Lighting, silence, and fast dialogue can increase the tension of a crisis scene.","zh":"燈光、沉默和快速對白可以增加危機場面的緊張感。"},{"en":"Viewers feel tension when they care about what will happen next.","zh":"當觀眾關心接下來會發生甚麼時，就會感到緊張。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"crisis scene","meaning":"危機場面","examples":[{"en":"The recording showed the tension of a crisis scene.","zh":"錄像展示了危機場面的緊張感。"},{"en":"A crisis scene is a part of a story where characters face danger, conflict, or an urgent decision.","zh":"crisis scene 指故事中角色面對危險、衝突或緊急決定的部分。"},{"en":"A crisis scene may show a family argument, a sudden accident, or a final choice.","zh":"危機場面可能展示家庭爭吵、突發意外或最終選擇。"},{"en":"Crisis scenes are important because they force characters to reveal what they truly value.","zh":"危機場面很重要，因為它迫使角色揭示自己真正重視甚麼。"},{"en":"A well-acted crisis scene can make viewers forget they are watching through a screen.","zh":"演得好的危機場面可以令觀眾忘記自己是透過螢幕觀看。"}],"source":"2018 Q7.pdf","sourcePage":5},{"front":"without paying for","meaning":"不用支付……","examples":[{"en":"Viewers can explore theatre without paying for an expensive seat.","zh":"觀眾可以不用支付昂貴座位費用而探索劇場。"},{"en":"Without paying for means without spending money on something.","zh":"without paying for 指不用花錢購買某物或服務。"},{"en":"Students can learn basic coding online without paying for private lessons.","zh":"學生可以不用支付私人課程費用，在網上學習基本編程。"},{"en":"Recordings let beginners try theatre without paying for a full-price ticket first.","zh":"錄像讓初學者不用先支付正價門票，就能嘗試劇場。"},{"en":"This lowers pressure because people can explore before making a bigger commitment.","zh":"這會降低壓力，因為人們可以先探索，再作較大承諾。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"expensive seat","meaning":"昂貴座位","examples":[{"en":"Some people hesitate because they worry about buying an expensive seat.","zh":"有些人猶豫，因為他們擔心購買昂貴座位。"},{"en":"An expensive seat is a ticket or place that costs a lot of money.","zh":"expensive seat 指花費很高的門票或座位。"},{"en":"A student may avoid a concert if only expensive seats are left.","zh":"如果只剩昂貴座位，學生可能會避開音樂會。"},{"en":"Expensive seats can make beginners feel that one wrong choice will waste money.","zh":"昂貴座位會令初學者覺得一旦選錯就浪費金錢。"},{"en":"Affordable options matter because not everyone can take a financial risk for art.","zh":"可負擔的選擇很重要，因為不是每個人都能為藝術承擔金錢風險。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"theatre etiquette","meaning":"劇場禮儀","examples":[{"en":"New viewers may worry about theatre etiquette.","zh":"新觀眾可能擔心劇場禮儀。"},{"en":"Theatre etiquette means the polite behaviour expected in a theatre, such as being quiet and arriving on time.","zh":"theatre etiquette 指劇場中被期望遵守的禮貌行為，例如保持安靜和準時到達。"},{"en":"A beginner may not know whether they can eat, talk, or take photos during a play.","zh":"初學者可能不知道看劇時可否進食、說話或拍照。"},{"en":"Clear guidance about theatre etiquette helps new audiences feel less embarrassed.","zh":"關於劇場禮儀的清楚指引，能令新觀眾較不尷尬。"},{"en":"Etiquette should welcome people into theatre, not make them feel judged.","zh":"禮儀應該歡迎人走進劇場，而不是令人覺得被評價。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"close-up shots","meaning":"特寫鏡頭","examples":[{"en":"Close-up shots allowed me to notice small changes in facial expression.","zh":"特寫鏡頭讓我留意到面部表情的細微變化。"},{"en":"Close-up shots are camera images taken from near the subject, often showing the face or details clearly.","zh":"close-up shots 指從近距離拍攝主體的鏡頭，常清楚展示面孔或細節。"},{"en":"A close-up shot can show tears, nervous eyes, or a small smile.","zh":"特寫鏡頭可以展示眼淚、緊張的眼神或微笑。"},{"en":"Close-up shots help viewers notice details they might miss from the back row of a theatre.","zh":"特寫鏡頭幫助觀眾留意他們坐在劇場後排時可能錯過的細節。"},{"en":"They guide attention, but they also choose what the viewer sees.","zh":"它們引導注意力，但也選擇了觀眾會看見甚麼。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"allow someone to notice","meaning":"讓某人留意到","examples":[{"en":"Close-up shots allowed me to notice subtle expressions.","zh":"特寫鏡頭讓我留意到細微表情。"},{"en":"To allow someone to notice means to make it possible for someone to see or understand something.","zh":"allow someone to notice 指令某人能看見或理解某事。"},{"en":"Slow replay allows students to notice how a dancer controls balance.","zh":"慢動作重播讓學生留意到舞者如何控制平衡。"},{"en":"Good lighting allows viewers to notice changes in mood on stage.","zh":"良好燈光讓觀眾留意到舞台上情緒的變化。"},{"en":"Recordings can allow beginners to notice theatre details that live viewing may hide.","zh":"錄像可以讓初學者留意到現場觀看時可能看不清的劇場細節。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"facial expression","meaning":"面部表情","examples":[{"en":"The recording showed small changes in facial expression.","zh":"錄像展示了面部表情的細微變化。"},{"en":"Facial expression means the way someone’s face shows feelings or reactions.","zh":"facial expression 指一個人的臉如何顯示感受或反應。"},{"en":"A raised eyebrow or tight smile can be an important facial expression.","zh":"揚起眉毛或勉強微笑都可以是重要的面部表情。"},{"en":"Actors use facial expressions to show fear, doubt, anger, or joy without words.","zh":"演員使用面部表情，在不用說話的情況下表達恐懼、懷疑、憤怒或喜悅。"},{"en":"In recordings, facial expressions may become easier to see through close-up shots.","zh":"在錄像中，面部表情可能透過特寫鏡頭變得更容易看見。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"wider shots","meaning":"廣角鏡頭","examples":[{"en":"Wider shots revealed the careful blocking and lighting.","zh":"廣角鏡頭展現了精心安排的舞台調度和燈光。"},{"en":"Wider shots are camera views that show more of the stage, setting, or group of actors.","zh":"wider shots 指展示更多舞台、場景或演員群體的鏡頭。"},{"en":"A wider shot can show where every actor stands in relation to others.","zh":"廣角鏡頭可以展示每位演員與其他人的位置關係。"},{"en":"Wider shots help viewers understand space, movement, and stage design.","zh":"廣角鏡頭幫助觀眾理解空間、動作和舞台設計。"},{"en":"Close-ups show detail, while wider shots show the whole dramatic picture.","zh":"特寫展示細節，而廣角鏡頭展示整個戲劇畫面。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"reveal the careful blocking","meaning":"展現精心安排的舞台調度","examples":[{"en":"Wider shots revealed the careful blocking on stage.","zh":"廣角鏡頭展現了舞台上精心安排的舞台調度。"},{"en":"To reveal the careful blocking means to show how actors’ positions and movements have been planned.","zh":"reveal the careful blocking 指展示演員的位置和動作如何被計劃。"},{"en":"A video from the back of the hall can reveal the careful blocking of a school play.","zh":"從禮堂後方拍攝的影片，可以展現學校話劇中精心安排的舞台調度。"},{"en":"Careful blocking helps the audience understand relationships between characters.","zh":"精心安排的舞台調度幫助觀眾理解角色之間的關係。"},{"en":"When blocking is revealed clearly, viewers see that theatre movement is not random.","zh":"當舞台調度被清楚展現時，觀眾會看見劇場動作並不是隨意的。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"blocking and lighting","meaning":"舞台調度和燈光","examples":[{"en":"Blocking and lighting shaped the emotional atmosphere.","zh":"舞台調度和燈光塑造了情感氣氛。"},{"en":"Blocking and lighting mean actors’ stage positions and the use of light in performance.","zh":"blocking and lighting 指演員在舞台上的位置安排，以及演出中的燈光運用。"},{"en":"Dark lighting and distant blocking can make two characters feel emotionally separated.","zh":"昏暗燈光和疏離的舞台調度，可以令兩個角色感覺情感上分離。"},{"en":"Blocking and lighting guide where the audience looks and how they feel.","zh":"舞台調度和燈光會引導觀眾看向哪裏，以及如何感受。"},{"en":"These features show that theatre tells stories through space and light, not only words.","zh":"這些特色顯示劇場不只用文字說故事，也用空間和燈光說故事。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"emotional atmosphere","meaning":"情感氣氛","examples":[{"en":"The lighting shaped the emotional atmosphere of the scene.","zh":"燈光塑造了該場景的情感氣氛。"},{"en":"Emotional atmosphere is the feeling or mood created around a scene or place.","zh":"emotional atmosphere 指一個場景或地方周圍營造出的感覺或情緒。"},{"en":"Soft music and warm light can create a calm emotional atmosphere.","zh":"柔和音樂和溫暖燈光可以營造平靜的情感氣氛。"},{"en":"In theatre, emotional atmosphere helps viewers feel sadness, danger, hope, or loneliness.","zh":"在劇場中，情感氣氛幫助觀眾感受悲傷、危險、希望或孤獨。"},{"en":"A strong emotional atmosphere can make a simple scene feel powerful.","zh":"強烈的情感氣氛可以令簡單場景變得有力量。"}],"source":"2018 Q7.pdf","sourcePage":6},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, the camera guided the viewer through the stage.","zh":"換句話說，鏡頭引導觀眾理解舞台。"},{"en":"In other words is used to explain the same idea in a clearer or simpler way.","zh":"in other words 用來以更清楚或更簡單的方式解釋同一個想法。"},{"en":"The lesson was too fast; in other words, many students could not follow it.","zh":"這堂課太快；換句話說，許多學生跟不上。"},{"en":"Writers use in other words when they want to restate a point for better understanding.","zh":"作者在想重新表述一點以便更好理解時，會使用 in other words。"},{"en":"In other words, recordings can guide beginners through theatre instead of leaving them confused.","zh":"換句話說，錄像可以引導初學者理解劇場，而不是令他們困惑。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"destroy the stage","meaning":"破壞舞台感","examples":[{"en":"The camera did not destroy the stage.","zh":"鏡頭並沒有破壞舞台感。"},{"en":"To destroy the stage means to damage the sense of live performance or theatre space.","zh":"destroy the stage 指損害現場演出或劇場空間的感覺。"},{"en":"Bad filming may destroy the stage if it cuts so much that viewers cannot understand the scene.","zh":"如果剪接太多令觀眾不能理解場景，差劣拍攝可能會破壞舞台感。"},{"en":"Careful camera work can support the stage instead of destroying it.","zh":"細心的鏡頭運用可以支援舞台，而不是破壞它。"},{"en":"A recording should respect the stage by showing both detail and space.","zh":"錄像應透過展示細節和空間來尊重舞台。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"guide my inexperienced eye through","meaning":"引導我這雙缺乏經驗的眼睛去理解","examples":[{"en":"The camera guided my inexperienced eye through the performance.","zh":"鏡頭引導我這雙缺乏經驗的眼睛去理解演出。"},{"en":"To guide my inexperienced eye through something means to help me notice important details because I am not yet skilled at watching it.","zh":"guide my inexperienced eye through something 指因我還不懂得觀看某事，而幫助我注意重要細節。"},{"en":"A museum guide can guide an inexperienced eye through a difficult painting.","zh":"博物館導賞員可以引導缺乏經驗的眼睛去理解一幅困難的畫。"},{"en":"Theatre recordings guide beginners by choosing angles that show key actions and expressions.","zh":"戲劇錄像透過選擇展示關鍵動作和表情的角度，引導初學者。"},{"en":"This phrase suggests that the viewer is learning how to watch more carefully.","zh":"這個短語暗示觀眾正在學習如何更仔細觀看。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"inexperienced eye","meaning":"缺乏經驗的眼光","examples":[{"en":"The recording helped my inexperienced eye notice stage details.","zh":"錄像幫助我缺乏經驗的眼光留意到舞台細節。"},{"en":"An inexperienced eye means the viewpoint of someone who has not yet learned how to notice important details.","zh":"inexperienced eye 指尚未學會如何注意重要細節的人的觀看角度。"},{"en":"A beginner’s inexperienced eye may miss the meaning of lighting in a play.","zh":"初學者缺乏經驗的眼光，可能錯過舞台燈光的意義。"},{"en":"Teachers help inexperienced eyes by pointing out patterns, symbols, and choices.","zh":"老師透過指出圖案、象徵和選擇，幫助缺乏經驗的眼光。"},{"en":"With guidance, an inexperienced eye can become more observant and confident.","zh":"有了引導，缺乏經驗的眼光可以變得更善於觀察和更有信心。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"take… for example","meaning":"以……為例","examples":[{"en":"Take a student who only watches films, for example.","zh":"以一個只看電影的學生為例。"},{"en":"Take… for example is used to introduce a specific case that explains a general idea.","zh":"take… for example 用來引入一個具體例子，以解釋一般想法。"},{"en":"Take a shy student, for example: a small group activity may help more than a speech contest.","zh":"以一個害羞學生為例：小組活動可能比演講比賽更有幫助。"},{"en":"This phrase makes an argument clearer by turning an abstract point into a real situation.","zh":"這個短語透過把抽象觀點變成真實情況，令論點更清楚。"},{"en":"Writers use it when they want readers to imagine one concrete person or case.","zh":"作者想讀者想像一個具體人物或個案時，會使用它。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"online videos","meaning":"網上影片","examples":[{"en":"A student may only be used to films and online videos.","zh":"一名學生可能只習慣電影和網上影片。"},{"en":"Online videos are videos watched through the internet on platforms, websites, or apps.","zh":"online videos 指透過互聯網平台、網站或應用程式觀看的影片。"},{"en":"Students often learn recipes, exercises, and study tips from online videos.","zh":"學生常從網上影片學習食譜、運動和溫習技巧。"},{"en":"People used to online videos may expect fast cuts and short scenes.","zh":"習慣網上影片的人，可能期待快速剪接和短場面。"},{"en":"Theatre recordings can connect stage plays with viewers who already watch online videos.","zh":"戲劇錄像可以把舞台劇與已經觀看網上影片的觀眾連接起來。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"once he sees that","meaning":"一旦他看到","examples":[{"en":"Once he sees that a play can be powerful, he may want to watch one live.","zh":"一旦他看到舞台劇可以很有力量，他可能想現場觀看一齣。"},{"en":"Once he sees that means after he realises or notices something important.","zh":"once he sees that 指當他意識到或注意到某件重要事情之後。"},{"en":"Once a student sees that grammar can help writing, they may practise more willingly.","zh":"一旦學生看到文法可以幫助寫作，他們可能更願意練習。"},{"en":"Once viewers see that theatre can be exciting, their old assumptions may change.","zh":"一旦觀眾看到劇場可以很刺激，他們的舊假設可能會改變。"},{"en":"This phrase shows that one moment of understanding can lead to a new action.","zh":"這個短語顯示一刻理解可以帶來新的行動。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"suspenseful, funny and visually powerful","meaning":"有懸念、有趣而視覺效果強","examples":[{"en":"A play can be suspenseful, funny and visually powerful.","zh":"舞台劇可以有懸念、有趣而視覺效果強。"},{"en":"Suspenseful, funny and visually powerful means exciting, humorous, and strong to look at.","zh":"suspenseful, funny and visually powerful 指令人緊張、有幽默感，而且視覺上有力量。"},{"en":"A school performance can be suspenseful, funny and visually powerful if the story, acting, and lighting work well.","zh":"如果故事、演技和燈光配合得好，學校演出也可以有懸念、有趣而視覺效果強。"},{"en":"This combination attracts viewers because it gives them emotion, entertainment, and memorable images.","zh":"這種組合吸引觀眾，因為它帶來情感、娛樂和難忘影像。"},{"en":"Theatre is not always serious or difficult; it can also be suspenseful, funny and visually powerful.","zh":"劇場不一定總是嚴肅或困難；它也可以有懸念、有趣而視覺效果強。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"be more likely to","meaning":"更有可能","examples":[{"en":"He is more likely to watch a live performance after enjoying the recording.","zh":"他在喜歡錄像後，更有可能觀看現場演出。"},{"en":"To be more likely to do something means to have a greater chance of doing it.","zh":"be more likely to do something 指做某事的機會較高。"},{"en":"Students are more likely to read when books match their interests.","zh":"當書本符合學生興趣時，他們更有可能閱讀。"},{"en":"Viewers are more likely to attend theatre if their first contact is enjoyable.","zh":"如果第一次接觸令人愉快，觀眾更有可能入場看劇。"},{"en":"This phrase helps explain how one experience can increase the chance of another action.","zh":"這個短語有助解釋一種體驗如何增加另一個行動的可能性。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"on screen","meaning":"在螢幕上","examples":[{"en":"The play looked powerful on screen.","zh":"這齣劇在螢幕上看起來很有力量。"},{"en":"On screen means shown or seen through a television, computer, cinema, or phone display.","zh":"on screen 指透過電視、電腦、電影或手機螢幕展示或觀看。"},{"en":"A dance performance may look different on screen from how it feels in the theatre.","zh":"舞蹈演出在螢幕上看起來，可能與在劇場中的感受不同。"},{"en":"Stories on screen can reach people who cannot attend in person.","zh":"螢幕上的故事可以接觸不能親身到場的人。"},{"en":"If theatre feels powerful on screen, viewers may wonder how it feels live.","zh":"如果劇場在螢幕上也很有力量，觀眾可能會好奇現場感覺如何。"}],"source":"2018 Q7.pdf","sourcePage":7},{"front":"in person","meaning":"親身；現場","examples":[{"en":"He may wonder what the play feels like in person.","zh":"他可能會好奇這齣劇親身觀看時感覺如何。"},{"en":"In person means physically present at the place, rather than watching through a screen or message.","zh":"in person 指親身在場，而不是透過螢幕或訊息觀看。"},{"en":"A student may understand a campus better after visiting it in person.","zh":"學生親身到訪校園後，可能更了解那所學校。"},{"en":"Seeing theatre in person allows viewers to share the room with actors and other audiences.","zh":"親身觀看劇場讓觀眾與演員和其他觀眾共享同一空間。"},{"en":"Some experiences can be introduced online, but felt more fully in person.","zh":"有些體驗可以在線上介紹，但親身感受會更完整。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"where interest begins","meaning":"興趣開始的地方","examples":[{"en":"That question is exactly where interest begins.","zh":"那個問題正是興趣開始的地方。"},{"en":"Where interest begins means the moment or point at which curiosity starts to grow.","zh":"where interest begins 指好奇心開始增長的時刻或起點。"},{"en":"A child asking why the moon changes shape may be where interest in science begins.","zh":"孩子問月亮為何會改變形狀，可能就是科學興趣開始的地方。"},{"en":"For theatre, interest may begin when viewers wonder how a live show feels.","zh":"對劇場而言，當觀眾好奇現場演出感覺如何時，興趣可能開始。"},{"en":"This phrase shows that curiosity can be the first step toward deeper involvement.","zh":"這個短語顯示好奇心可以是更深入參與的第一步。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"another reason","meaning":"另一個原因","examples":[{"en":"Another reason the scheme may work is theatrical variety.","zh":"這項計劃可能奏效的另一個原因是劇場的多樣性。"},{"en":"Another reason introduces an additional explanation or supporting point.","zh":"another reason 用來引入另一個解釋或支持點。"},{"en":"Another reason students enjoy group projects is that they can share ideas.","zh":"學生喜歡小組專題的另一個原因是他們可以分享想法。"},{"en":"This phrase helps organise an essay by moving from one argument to the next.","zh":"這個短語透過由一個論點轉到下一個論點，幫助組織文章。"},{"en":"Another reason recordings may help is that they expose viewers to many theatre styles.","zh":"錄像可能有幫助的另一個原因是，它們讓觀眾接觸多種劇場風格。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"the scheme may work","meaning":"這計劃可能奏效","examples":[{"en":"The scheme may work because it offers theatrical variety.","zh":"這計劃可能奏效，因為它提供劇場的多樣性。"},{"en":"The scheme may work means the plan has a reasonable chance of being successful.","zh":"the scheme may work 指這項計劃有合理機會成功。"},{"en":"A reading scheme may work if students can choose books they actually enjoy.","zh":"如果學生能選擇自己真正喜歡的書，閱讀計劃可能奏效。"},{"en":"The screening scheme may work because it reduces fear and increases choice.","zh":"這項放映計劃可能奏效，因為它減少恐懼並增加選擇。"},{"en":"Saying a scheme may work shows cautious support, not complete certainty.","zh":"說一項計劃可能奏效，表示謹慎支持，而不是完全肯定。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"Hong Kong audiences","meaning":"香港觀眾","examples":[{"en":"Hong Kong audiences can experience more types of theatre through recordings.","zh":"香港觀眾可以透過錄像體驗更多類型的劇場。"},{"en":"Hong Kong audiences are viewers or spectators in Hong Kong.","zh":"Hong Kong audiences 指香港的觀眾或觀看者。"},{"en":"Hong Kong audiences may have different language backgrounds, ages, and theatre habits.","zh":"香港觀眾可能有不同語言背景、年齡和劇場習慣。"},{"en":"Recordings can help Hong Kong audiences see productions that rarely come to the city.","zh":"錄像可以幫助香港觀眾觀看很少來到本地的製作。"},{"en":"Understanding Hong Kong audiences helps organisers choose suitable plays and support materials.","zh":"了解香港觀眾有助主辦方選擇合適劇目和支援材料。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"a taste of","meaning":"初步體驗；嘗試","examples":[{"en":"The scheme gives Hong Kong audiences a taste of theatrical variety.","zh":"這項計劃讓香港觀眾初步體驗劇場的多樣性。"},{"en":"A taste of something means a small first experience of it.","zh":"a taste of something 指對某事物的小小初步體驗。"},{"en":"A free workshop gives children a taste of painting before they join a full course.","zh":"免費工作坊讓孩子在參加完整課程前初步體驗繪畫。"},{"en":"Recordings give audiences a taste of foreign theatre without requiring travel.","zh":"錄像讓觀眾不用旅行也能初步體驗外國劇場。"},{"en":"A taste of something can create enough interest for people to try more.","zh":"對某事的初步體驗可以產生足夠興趣，令人想嘗試更多。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"theatrical variety","meaning":"劇場的多樣性","examples":[{"en":"Recordings can introduce audiences to theatrical variety.","zh":"錄像可以向觀眾介紹劇場的多樣性。"},{"en":"Theatrical variety means many different types, styles, and traditions of theatre.","zh":"theatrical variety 指許多不同類型、風格和傳統的劇場。"},{"en":"Theatre variety may include comedy, tragedy, political drama, dance theatre, and experimental work.","zh":"劇場的多樣性可以包括喜劇、悲劇、政治劇、舞蹈劇場和實驗作品。"},{"en":"Theatrical variety matters because different audiences connect with different forms.","zh":"劇場的多樣性很重要，因為不同觀眾會與不同形式產生連繫。"},{"en":"Recordings can show beginners that theatre is not one single fixed style.","zh":"錄像可以讓初學者看見劇場不是一種固定風格。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"one city alone","meaning":"單靠一個城市","examples":[{"en":"One city alone cannot provide every kind of stage production.","zh":"單靠一個城市不能提供每一種舞台製作。"},{"en":"One city alone means only one city by itself, without help or examples from elsewhere.","zh":"one city alone 指只有一個城市本身，沒有其他地方的幫助或例子。"},{"en":"One school alone cannot offer every sport that students may want to try.","zh":"單靠一所學校不能提供學生可能想嘗試的每一種運動。"},{"en":"One city alone may have limited theatres, budgets, languages, and audience sizes.","zh":"單靠一個城市可能受劇院、預算、語言和觀眾規模限制。"},{"en":"Recordings help because one city alone cannot show the whole range of world theatre.","zh":"錄像有幫助，因為單靠一個城市不能展示世界劇場的全部範圍。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"not all…","meaning":"並非全都是……","examples":[{"en":"Stage plays are not all Shakespearean kings and tragic speeches.","zh":"舞台劇並非全都是莎士比亞式君王和悲劇式演說。"},{"en":"Not all means a group contains more variety than people may assume.","zh":"not all 指一個群體比人們以為的更有多樣性。"},{"en":"Healthy food is not all salads; it can include soups, rice dishes, and home cooking.","zh":"健康食物並非全都是沙律；它也可以包括湯、飯類和家常菜。"},{"en":"This phrase helps correct a narrow or unfair stereotype.","zh":"這個短語有助糾正狹窄或不公平的刻板印象。"},{"en":"Saying theatre is not all old tragedy can make it feel more open to beginners.","zh":"說劇場並非全都是古老悲劇，可以令初學者覺得它更開放。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"Shakespearean kings","meaning":"莎士比亞式君王","examples":[{"en":"Stage plays are not all Shakespearean kings.","zh":"舞台劇並非全都是莎士比亞式君王。"},{"en":"Shakespearean kings refers to royal characters in traditional Shakespeare-style drama.","zh":"Shakespearean kings 指傳統莎士比亞風格戲劇中的王室角色。"},{"en":"Some students imagine theatre as only Shakespearean kings speaking difficult English.","zh":"有些學生想像劇場只是莎士比亞式君王說着艱深英語。"},{"en":"This image can make theatre seem formal, old, or distant from modern life.","zh":"這種形象會令劇場顯得正式、古舊或遠離現代生活。"},{"en":"Modern theatre also includes ordinary families, students, workers, and everyday conflicts.","zh":"現代劇場也包括普通家庭、學生、工人和日常衝突。"}],"source":"2018 Q7.pdf","sourcePage":8},{"front":"tragic speeches","meaning":"悲劇式演說","examples":[{"en":"Stage plays are not all tragic speeches.","zh":"舞台劇並非全都是悲劇式演說。"},{"en":"Tragic speeches are serious speeches about suffering, loss, or painful choices.","zh":"tragic speeches 指關於痛苦、失去或艱難選擇的嚴肅說話。"},{"en":"A tragic speech may appear when a character realises they have lost someone important.","zh":"當角色意識到自己失去重要的人時，可能會出現悲劇式演說。"},{"en":"Some people avoid theatre because they imagine only tragic speeches and heavy emotions.","zh":"有些人避開劇場，因為他們只想像悲劇式演說和沉重情緒。"},{"en":"Theatre can include tragic speeches, but it can also be funny, playful, and surprising.","zh":"劇場可以包括悲劇式演說，但也可以有趣、 playful 和令人驚喜。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"wooden chairs under yellow lights","meaning":"黃燈下的木椅","examples":[{"en":"Theatre is not limited to wooden chairs under yellow lights.","zh":"劇場不局限於黃燈下的木椅。"},{"en":"Wooden chairs under yellow lights suggests a plain, old-fashioned, or serious image of theatre.","zh":"wooden chairs under yellow lights 暗示劇場樸素、舊式或嚴肅的形象。"},{"en":"A beginner may imagine theatre as wooden chairs under yellow lights and nothing more.","zh":"初學者可能把劇場想像成只有黃燈下的木椅。"},{"en":"This image can make theatre seem narrower than it really is.","zh":"這種形象會令劇場看起來比實際更狹窄。"},{"en":"Modern theatre may use video, movement, music, bright colours, or empty space instead.","zh":"現代劇場可能使用影片、動作、音樂、鮮明色彩或空白空間。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"recording programme","meaning":"錄像放映計劃","examples":[{"en":"A recording programme can bring global productions to local viewers.","zh":"錄像放映計劃可以把全球製作帶給本地觀眾。"},{"en":"A recording programme is an organised plan to show recorded performances to audiences.","zh":"recording programme 指有組織地向觀眾放映錄製演出的計劃。"},{"en":"A university may run a recording programme of international lectures for students.","zh":"大學可能為學生推行國際講座錄像計劃。"},{"en":"A theatre recording programme can give local viewers access to work from many countries.","zh":"劇場錄像放映計劃可以讓本地觀眾接觸來自多國的作品。"},{"en":"The programme works best when recordings are chosen carefully and explained clearly.","zh":"當錄像被仔細選擇並清楚解釋時，這項計劃最有效。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"bring viewers from… to…","meaning":"帶領觀眾從……到……","examples":[{"en":"The programme can bring viewers from Japanese theatre to British political drama.","zh":"這計劃可以帶領觀眾從日本劇場到英國政治劇。"},{"en":"Bring viewers from one thing to another means guide audiences across different styles, topics, or experiences.","zh":"bring viewers from one thing to another 指引導觀眾跨越不同風格、題材或體驗。"},{"en":"A reading course can bring students from short stories to full novels.","zh":"閱讀課程可以帶領學生從短篇故事到完整小說。"},{"en":"A theatre programme can bring viewers from quiet minimalist work to loud political drama.","zh":"劇場計劃可以帶領觀眾從安靜的極簡作品到強烈的政治劇。"},{"en":"This phrase shows movement through variety, not staying with one type only.","zh":"這個短語顯示透過多樣性移動，而不是只停留在一種類型。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"minimalist Japanese production","meaning":"極簡日本製作","examples":[{"en":"A minimalist Japanese production may attract viewers who like subtle drama.","zh":"極簡日本製作可能吸引喜歡含蓄戲劇的觀眾。"},{"en":"A minimalist Japanese production is a Japanese performance that uses few objects, simple design, and quiet control.","zh":"minimalist Japanese production 指使用少量物件、簡潔設計和安靜控制的日本演出。"},{"en":"A minimalist production may use one chair, slow movement, and silence to create meaning.","zh":"極簡製作可能使用一張椅、緩慢動作和沉默來創造意義。"},{"en":"Such theatre can teach viewers that powerful drama does not always need large sets.","zh":"這類劇場可以教觀眾，有力量的戲劇不一定需要大型佈景。"},{"en":"Viewers who enjoy careful detail may find a minimalist Japanese production moving.","zh":"喜歡細節的觀眾可能會被極簡日本製作打動。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"bold British political drama","meaning":"大膽的英國政治劇","examples":[{"en":"A bold British political drama may appeal to socially aware audiences.","zh":"大膽的英國政治劇可能吸引有社會意識的觀眾。"},{"en":"A bold British political drama is a British play that deals directly and strongly with political issues.","zh":"bold British political drama 指直接而有力處理政治議題的英國舞台劇。"},{"en":"A bold political drama may criticise power, inequality, war, or public lies.","zh":"大膽的政治劇可能批判權力、不平等、戰爭或公共謊言。"},{"en":"It appeals to audiences who want theatre to discuss society, not only personal feelings.","zh":"它吸引希望劇場討論社會，而不只是個人感受的觀眾。"},{"en":"Such drama can make viewers argue, question, and think after the show ends.","zh":"這類戲劇可以令觀眾在演出結束後爭論、提問和思考。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"American family tragedy","meaning":"美國家庭悲劇","examples":[{"en":"An American family tragedy may move viewers emotionally.","zh":"美國家庭悲劇可能在情感上打動觀眾。"},{"en":"An American family tragedy is a serious play about pain, conflict, or loss within an American family.","zh":"American family tragedy 指關於美國家庭內痛苦、衝突或失去的嚴肅戲劇。"},{"en":"Such a play may show parents and children hurting one another through silence or anger.","zh":"這類戲劇可能展示父母與子女如何透過沉默或憤怒傷害彼此。"},{"en":"Family tragedies move viewers because private problems often reflect wider social pressure.","zh":"家庭悲劇打動觀眾，因為私人問題常反映更廣泛的社會壓力。"},{"en":"Viewers may recognise their own fears in an American family tragedy.","zh":"觀眾可能在美國家庭悲劇中認出自己的恐懼。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"Korean black comedy","meaning":"韓國黑色喜劇","examples":[{"en":"A Korean black comedy may attract younger audiences.","zh":"韓國黑色喜劇可能吸引年輕觀眾。"},{"en":"A Korean black comedy is a Korean work that treats serious or dark subjects with humour.","zh":"Korean black comedy 指以幽默處理嚴肅或黑暗題材的韓國作品。"},{"en":"A black comedy may make people laugh at situations that are also painful or unfair.","zh":"黑色喜劇可能令人對既痛苦又不公平的情況發笑。"},{"en":"Younger audiences may enjoy black comedy because it feels sharp, surprising, and socially aware.","zh":"年輕觀眾可能喜歡黑色喜劇，因為它感覺尖銳、令人意外並有社會意識。"},{"en":"This genre shows that theatre can be funny and disturbing at the same time.","zh":"這種類型顯示劇場可以同時有趣又令人不安。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"such range matters","meaning":"這種多樣性很重要","examples":[{"en":"Such range matters because different people need different entry points.","zh":"這種多樣性很重要，因為不同人需要不同入門點。"},{"en":"Such range matters means this variety is important and has a real purpose.","zh":"such range matters 指這種多樣性重要，而且有實際作用。"},{"en":"A library’s range matters because children, adults, beginners, and experts need different books.","zh":"圖書館的多樣性很重要，因為兒童、成人、初學者和專家需要不同書本。"},{"en":"In theatre, range matters because one style will not attract everyone.","zh":"在劇場中，多樣性很重要，因為一種風格不會吸引所有人。"},{"en":"Variety gives more people a fair chance to find something they enjoy.","zh":"多樣性給更多人公平機會找到自己喜歡的東西。"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"entry point","meaning":"入門點","examples":[{"en":"One person’s boring theatre may be another person’s perfect entry point.","zh":"一個人覺得沉悶的劇場，可能是另一個人最理想的入門點。"},{"en":"An entry point is the first suitable way into a subject, activity, or experience.","zh":"entry point 指進入某科目、活動或體驗的第一個合適方式。"},{"en":"Comics can be an entry point into reading for children who dislike long books.","zh":"對不喜歡長書的孩子來說，漫畫可以是閱讀的入門點。"},{"en":"Different theatre styles give different audiences their own entry point.","zh":"不同劇場風格為不同觀眾提供自己的入門點。"},{"en":"A good entry point makes people feel, “I can begin here.”","zh":"好的入門點令人覺得：「我可以從這裏開始。」"}],"source":"2018 Q7.pdf","sourcePage":9},{"front":"perfect entry point","meaning":"最理想的入門點","examples":[{"en":"A contemporary comedy may be someone’s perfect entry point into theatre.","zh":"當代喜劇可能是某人進入劇場最理想的入門點。"},{"en":"A perfect entry point is the best first experience for a particular person.","zh":"perfect entry point 指對某個人來說最好的第一次體驗。"},{"en":"A short, funny book may be the perfect entry point for a reluctant reader.","zh":"一本短而有趣的書，可能是不願閱讀者最理想的入門點。"},{"en":"A perfect entry point works because it matches someone’s interests and comfort level.","zh":"最理想的入門點之所以有效，是因為它符合某人的興趣和舒適程度。"},{"en":"For some viewers, comedy is the perfect entry point because it feels friendly and immediate.","zh":"對一些觀眾來說，喜劇是最理想的入門點，因為它感覺親切而直接。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"classical tragedy","meaning":"古典悲劇","examples":[{"en":"A teenager may dislike classical tragedy.","zh":"青少年可能不喜歡古典悲劇。"},{"en":"Classical tragedy is an old or traditional serious play about suffering, fate, and human weakness.","zh":"classical tragedy 指關於痛苦、命運和人性弱點的古老或傳統嚴肅戲劇。"},{"en":"Some students find classical tragedy difficult because the language or setting feels distant.","zh":"有些學生覺得古典悲劇困難，因為語言或背景感覺遙遠。"},{"en":"Classical tragedy can still be powerful when teachers explain the characters’ choices clearly.","zh":"當老師清楚解釋角色選擇時，古典悲劇仍可以很有力量。"},{"en":"Not liking classical tragedy does not mean someone cannot enjoy other forms of theatre.","zh":"不喜歡古典悲劇，不代表某人不能享受其他劇場形式。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"respond to","meaning":"對……有反應；受……吸引","examples":[{"en":"A teenager may respond to a sharp contemporary comedy.","zh":"青少年可能會受尖銳的當代喜劇吸引。"},{"en":"To respond to something means to react to it emotionally, mentally, or practically.","zh":"respond to something 指在情感、思想或實際行動上對某事作出反應。"},{"en":"Students may respond to a lesson better when examples come from daily life.","zh":"當例子來自日常生活時，學生可能對課堂有更好反應。"},{"en":"Viewers respond to theatre when it speaks to their interests, worries, or humour.","zh":"當劇場觸及觀眾的興趣、憂慮或幽默感時，觀眾會有反應。"},{"en":"This phrase does not only mean answering; it can mean being affected by something.","zh":"這個短語不只指回答；也可以指被某事影響。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"sharp contemporary comedy","meaning":"尖銳的當代喜劇","examples":[{"en":"A sharp contemporary comedy may attract viewers who dislike old plays.","zh":"尖銳的當代喜劇可能吸引不喜歡舊劇的觀眾。"},{"en":"A sharp contemporary comedy is a modern funny play with clever, critical, or socially aware humour.","zh":"sharp contemporary comedy 指帶有聰明、批判或社會意識幽默的現代喜劇。"},{"en":"Such comedy may joke about school pressure, family expectations, or online life.","zh":"這類喜劇可能拿學業壓力、家庭期望或網上生活開玩笑。"},{"en":"It can attract new audiences because it feels close to their own world.","zh":"它可以吸引新觀眾，因為它感覺接近他們自己的世界。"},{"en":"Sharp comedy makes people laugh while also asking them to think.","zh":"尖銳喜劇令人發笑，同時也要求人思考。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"experimental drama","meaning":"實驗劇場","examples":[{"en":"Some parents avoid experimental drama.","zh":"有些家長避開實驗劇場。"},{"en":"Experimental drama is theatre that tries unusual forms, structures, sounds, or ways of performing.","zh":"experimental drama 指嘗試不尋常形式、結構、聲音或表演方式的劇場。"},{"en":"Experimental drama may use no clear plot, direct audience interaction, or strange movement.","zh":"實驗劇場可能沒有清晰情節、直接與觀眾互動，或使用奇特動作。"},{"en":"Some people avoid it because they fear they will not understand what is happening.","zh":"有些人避開它，因為害怕不明白正在發生甚麼。"},{"en":"Experimental drama can be challenging, but it may also open new ways of seeing theatre.","zh":"實驗劇場可以具挑戰性，但也可能打開觀看劇場的新方式。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"be moved by","meaning":"被……打動","examples":[{"en":"A parent may be moved by a realistic family story.","zh":"家長可能被一個寫實家庭故事打動。"},{"en":"To be moved by something means to feel strong emotion because of it.","zh":"be moved by something 指因某事而產生強烈情感。"},{"en":"A student may be moved by a speech about friendship and sacrifice.","zh":"學生可能被一場關於友誼和犧牲的演講打動。"},{"en":"Viewers are moved by stories when they recognise feelings from their own lives.","zh":"當觀眾在故事中認出自己生活中的感受時，會被故事打動。"},{"en":"Being moved by theatre can make people remember a performance long after it ends.","zh":"被劇場打動，可以令人於演出結束很久後仍記得它。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"realistic family story","meaning":"寫實家庭故事","examples":[{"en":"A realistic family story may speak to older audiences.","zh":"寫實家庭故事可能打動年長觀眾。"},{"en":"A realistic family story is a believable story about ordinary family life, conflict, and care.","zh":"realistic family story 指關於普通家庭生活、衝突和照顧的可信故事。"},{"en":"Such a story may show parents worrying about money, ageing, or children’s choices.","zh":"這類故事可能展示父母擔心金錢、衰老或孩子的選擇。"},{"en":"Realistic family stories connect with audiences because family problems are familiar.","zh":"寫實家庭故事能與觀眾連繫，因為家庭問題令人熟悉。"},{"en":"A realistic family story can be quiet but emotionally powerful.","zh":"寫實家庭故事可以很安靜，但情感上很有力量。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"the more…, the more likely…","meaning":"越……就越有可能……","examples":[{"en":"The more examples HKAPA offers, the more likely audiences will find something they like.","zh":"香港演藝學院提供的例子越多，觀眾就越有可能找到自己喜歡的東西。"},{"en":"The more…, the more likely… shows that one increase raises the chance of another result.","zh":"the more…, the more likely… 顯示一件事增加時，另一個結果的可能性也提高。"},{"en":"The more books students try, the more likely they are to find one they enjoy.","zh":"學生嘗試的書越多，就越有可能找到自己喜歡的一本。"},{"en":"The more theatre styles audiences see, the more likely they are to find a suitable entry point.","zh":"觀眾看到的劇場風格越多，就越有可能找到合適入門點。"},{"en":"This pattern is useful for explaining how variety increases possibility.","zh":"這個句式有助解釋多樣性如何增加可能性。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"speak to them","meaning":"打動他們；引起共鳴","examples":[{"en":"Different audiences may find a play that speaks to them.","zh":"不同觀眾可能找到一齣能打動他們的劇。"},{"en":"To speak to someone means to connect with their feelings, experiences, or concerns.","zh":"speak to someone 指與某人的感受、經驗或關注產生連繫。"},{"en":"A story about exam pressure may speak to teenagers preparing for public tests.","zh":"關於考試壓力的故事可能引起準備公開考試的青少年共鳴。"},{"en":"Theatre speaks to audiences when it feels relevant to their lives.","zh":"當劇場令人感覺與生活相關時，它就會打動觀眾。"},{"en":"A play that speaks to someone can make them feel seen and understood.","zh":"一齣能打動某人的劇，可以令他感到被看見和被理解。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, recordings can be paired with live-theatre opportunities.","zh":"更重要的是，錄像可以與現場劇場機會配合。"},{"en":"More importantly introduces a point that is even more significant than the previous one.","zh":"more importantly 用來引入比前一點更重要的觀點。"},{"en":"The trip was fun; more importantly, students learned how to work together.","zh":"這次旅行很好玩；更重要的是，學生學會如何合作。"},{"en":"Writers use more importantly to guide readers toward the strongest idea.","zh":"作者使用 more importantly，引導讀者走向最有力的想法。"},{"en":"More importantly, recordings should lead viewers toward real theatre attendance.","zh":"更重要的是，錄像應把觀眾帶向真正入場看劇。"}],"source":"2018 Q7.pdf","sourcePage":10},{"front":"be paired with","meaning":"與……配合","examples":[{"en":"Recordings can be paired with short introductions and ticket discounts.","zh":"錄像可以與簡短介紹和門票折扣配合。"},{"en":"To be paired with something means to be used together with it for a stronger effect.","zh":"be paired with something 指與某物一起使用，以產生更強效果。"},{"en":"A reading task can be paired with discussion questions to deepen understanding.","zh":"閱讀任務可以與討論問題配合，以加深理解。"},{"en":"Screenings paired with talks can help viewers understand what they have watched.","zh":"與座談配合的放映，可以幫助觀眾理解自己看過的內容。"},{"en":"Pairing recordings with ticket discounts can turn interest into action.","zh":"把錄像與門票折扣配合，可以把興趣轉化為行動。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"short introductions","meaning":"簡短介紹","examples":[{"en":"Short introductions can help audiences understand the performance.","zh":"簡短介紹可以幫助觀眾理解演出。"},{"en":"Short introductions are brief explanations given before an event, text, or performance.","zh":"short introductions 指在活動、文本或演出前給予的簡短解釋。"},{"en":"A teacher may give a short introduction before students watch a historical film.","zh":"老師可能在學生觀看歷史電影前給予簡短介紹。"},{"en":"Short introductions reduce confusion by explaining background, characters, or themes.","zh":"簡短介紹透過解釋背景、角色或主題，減少困惑。"},{"en":"For new theatre viewers, a short introduction can make a difficult play feel more open.","zh":"對新劇場觀眾來說，簡短介紹可以令困難劇目感覺更容易進入。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"post-screening talks","meaning":"放映後座談","examples":[{"en":"Post-screening talks can deepen viewers’ understanding.","zh":"放映後座談可以加深觀眾的理解。"},{"en":"Post-screening talks are discussions or sharing sessions held after a film or recording is shown.","zh":"post-screening talks 指影片或錄像放映後舉行的討論或分享環節。"},{"en":"After a documentary, a post-screening talk may let viewers ask questions to the director.","zh":"紀錄片後的放映後座談，可以讓觀眾向導演提問。"},{"en":"These talks deepen understanding because experts explain choices and answer confusion.","zh":"這些座談能加深理解，因為專家會解釋選擇並回應困惑。"},{"en":"Post-screening talks can turn passive watching into active thinking.","zh":"放映後座談可以把被動觀看轉化為主動思考。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"ticket discounts","meaning":"門票折扣","examples":[{"en":"Ticket discounts may encourage viewers to attend live shows.","zh":"門票折扣可能鼓勵觀眾出席現場演出。"},{"en":"Ticket discounts are reduced prices for admission to events or performances.","zh":"ticket discounts 指活動或演出的入場門票減價優惠。"},{"en":"Student ticket discounts can make concerts and plays more affordable.","zh":"學生門票折扣可以令音樂會和舞台劇更可負擔。"},{"en":"Discounts encourage attendance because they reduce the financial risk of trying something new.","zh":"折扣能鼓勵入場，因為它降低嘗試新事物的金錢風險。"},{"en":"Ticket discounts work best when people already feel some interest.","zh":"當人們已經有一些興趣時，門票折扣最有效。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"related live productions","meaning":"相關現場演出","examples":[{"en":"Screenings can be linked to related live productions.","zh":"放映可以連繫到相關現場演出。"},{"en":"Related live productions are live shows connected to the recording by theme, style, artist, or topic.","zh":"related live productions 指在主題、風格、藝術家或題材上與錄像相關的現場演出。"},{"en":"A recording of a comedy could be linked to a related live production by the same theatre company.","zh":"一齣喜劇錄像可以連繫到同一劇團的相關現場演出。"},{"en":"Linking screenings to live productions gives viewers a clear next step.","zh":"把放映連繫到現場演出，能給觀眾清楚下一步。"},{"en":"Related live productions help recordings become invitations rather than final products.","zh":"相關現場演出幫助錄像成為邀請，而不是最終產品。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, the programme becomes more than one evening’s entertainment.","zh":"這樣一來，這項計劃就不只是某個晚上的娛樂。"},{"en":"That way means by doing this or through that method.","zh":"that way 指透過這樣做或使用那種方法。"},{"en":"Students can discuss the play after watching it; that way, they learn more than the plot.","zh":"學生可以在看劇後討論；這樣一來，他們學到的不只是情節。"},{"en":"This phrase connects an action with the result it creates.","zh":"這個短語把一個行動與它造成的結果連接起來。"},{"en":"That way, screenings can become a path toward live theatre.","zh":"這樣一來，放映可以成為走向現場劇場的路徑。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"merely entertain people","meaning":"只是娛樂大眾","examples":[{"en":"The programme should not merely entertain people for one evening.","zh":"這項計劃不應只是娛樂大眾一個晚上。"},{"en":"To merely entertain people means only to amuse them, without deeper learning or further action.","zh":"merely entertain people 指只是令人愉快，而沒有更深入學習或後續行動。"},{"en":"A school talk should not merely entertain students; it should also teach useful ideas.","zh":"學校講座不應只是娛樂學生；它也應教授有用想法。"},{"en":"Theatre recordings should do more than entertain if they aim to build future audiences.","zh":"如果戲劇錄像旨在培養未來觀眾，就不應只做到娛樂。"},{"en":"Entertainment is valuable, but the programme should also create curiosity and understanding.","zh":"娛樂有價值，但這項計劃也應創造好奇心和理解。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"for one evening","meaning":"一個晚上","examples":[{"en":"The screening should do more than entertain people for one evening.","zh":"放映不應只在一個晚上娛樂大眾。"},{"en":"For one evening means only during a single night or short event.","zh":"for one evening 指只在一個晚上或短暫活動期間。"},{"en":"A charity concert should inspire action, not only entertain people for one evening.","zh":"慈善音樂會應激發行動，而不只是娛樂大眾一個晚上。"},{"en":"If a programme ends after one evening, its long-term effect may be weak.","zh":"如果計劃在一個晚上後就結束，其長遠效果可能很弱。"},{"en":"HKAPA’s screenings should create interest that continues after the event ends.","zh":"香港演藝學院的放映應創造活動結束後仍持續的興趣。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"build a bridge from… to…","meaning":"建立由……到……的橋樑","examples":[{"en":"The programme can build a bridge from passive watching to active theatre-going.","zh":"這項計劃可以建立由被動觀看到主動入場看劇的橋樑。"},{"en":"To build a bridge from one thing to another means to create a connection that helps people move between them.","zh":"build a bridge from one thing to another 指建立連繫，幫助人由一件事走向另一件事。"},{"en":"A school workshop can build a bridge from classroom theory to real community service.","zh":"學校工作坊可以建立由課堂理論到真實社區服務的橋樑。"},{"en":"Recordings build a bridge when they turn screen interest into live attendance.","zh":"當錄像把螢幕興趣轉化為現場入場時，它們就建立了橋樑。"},{"en":"This phrase suggests a helpful transition, not a sudden jump.","zh":"這個短語暗示有幫助的過渡，而不是突然跳躍。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"passive watching","meaning":"被動觀看","examples":[{"en":"The scheme can move audiences beyond passive watching.","zh":"這項計劃可以把觀眾帶離被動觀看。"},{"en":"Passive watching means watching without active thought, discussion, or further action.","zh":"passive watching 指觀看時沒有主動思考、討論或後續行動。"},{"en":"Scrolling videos for hours is often passive watching because people do not reflect on what they see.","zh":"連續滑動影片幾小時常是被動觀看，因為人們不反思自己看見甚麼。"},{"en":"Post-screening talks can move viewers beyond passive watching by encouraging questions.","zh":"放映後座談可以透過鼓勵提問，把觀眾帶離被動觀看。"},{"en":"The goal is not only to watch, but to think, discuss, and attend.","zh":"目標不只是觀看，而是思考、討論和入場。"}],"source":"2018 Q7.pdf","sourcePage":11},{"front":"active theatre-going","meaning":"主動入場看劇","examples":[{"en":"The goal is to encourage active theatre-going.","zh":"目標是鼓勵主動入場看劇。"},{"en":"Active theatre-going means choosing to attend live theatre and engage with it seriously.","zh":"active theatre-going 指選擇出席現場劇場，並認真投入其中。"},{"en":"A student practises active theatre-going when they watch a play, read about it, and discuss it afterwards.","zh":"學生觀看舞台劇、閱讀相關資料並在之後討論時，就是實踐主動入場看劇。"},{"en":"Active theatre-going supports the theatre community because people buy tickets and return for more shows.","zh":"主動入場看劇支持劇場社群，因為人們購買門票並再次觀看更多演出。"},{"en":"Screenings should encourage active theatre-going rather than replace it.","zh":"放映應鼓勵主動入場看劇，而不是取代它。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"critics have a point","meaning":"批評者有道理","examples":[{"en":"Critics have a point when they discuss the limits of recordings.","zh":"批評者在討論錄像限制時是有道理的。"},{"en":"Critics have a point means people who disagree have a reasonable argument worth considering.","zh":"critics have a point 指不同意的人有值得考慮的合理論點。"},{"en":"Parents have a point when they say students need rest as well as homework.","zh":"家長說學生除了功課也需要休息時，是有道理的。"},{"en":"This phrase shows fairness because the writer admits the opposing view has value.","zh":"這個短語顯示公平，因為作者承認相反觀點有價值。"},{"en":"Critics have a point: recordings cannot fully recreate live theatre.","zh":"批評者有道理：錄像不能完全重現現場劇場。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"fully reproduce","meaning":"完全重現","examples":[{"en":"A recording can never fully reproduce a live performance.","zh":"錄像永遠不能完全重現現場演出。"},{"en":"To fully reproduce something means to copy or recreate it completely.","zh":"fully reproduce something 指完整複製或重建某事物。"},{"en":"A photo cannot fully reproduce the smell, sound, and movement of a street market.","zh":"相片不能完全重現街市的氣味、聲音和動態。"},{"en":"Recordings cannot fully reproduce live theatre because they remove shared presence.","zh":"錄像不能完全重現現場劇場，因為它拿走了共同臨場感。"},{"en":"This phrase is useful when a copy captures part of an experience but not all of it.","zh":"當複製品捕捉了一部分體驗但不是全部時，這個短語很有用。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"live performance","meaning":"現場演出","examples":[{"en":"A live performance depends on shared presence.","zh":"現場演出依賴共同臨場感。"},{"en":"A live performance is an event performed in real time before an audience.","zh":"live performance 指在觀眾面前即時進行的演出。"},{"en":"In a live performance, the actor’s mistake, pause, or energy happens only in that moment.","zh":"在現場演出中，演員的錯誤、停頓或能量只在那一刻發生。"},{"en":"Live performances feel special because the audience and performers affect one another.","zh":"現場演出特別，因為觀眾和表演者會互相影響。"},{"en":"Watching a recording is useful, but a live performance creates a different kind of connection.","zh":"觀看錄像很有用，但現場演出創造另一種連繫。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"not just about","meaning":"不只是關於","examples":[{"en":"Theatre is not just about plot.","zh":"劇場不只是關於情節。"},{"en":"Not just about means something includes more than the single point mentioned.","zh":"not just about 指某事物包含的不只是提到的單一方面。"},{"en":"Education is not just about exams; it is also about confidence and judgement.","zh":"教育不只是關於考試；也關於信心和判斷力。"},{"en":"Theatre is not just about plot because voice, space, silence, and audience reaction also matter.","zh":"劇場不只是關於情節，因為聲音、空間、沉默和觀眾反應也很重要。"},{"en":"This phrase helps readers see that an idea has deeper layers.","zh":"這個短語幫助讀者看見一個想法有更深層次。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"shared breath","meaning":"共同呼吸","examples":[{"en":"Theatre is about shared breath between actors and audiences.","zh":"劇場關於演員與觀眾之間的共同呼吸。"},{"en":"Shared breath means the feeling that performers and audience are present together, reacting in the same space.","zh":"shared breath 指表演者和觀眾同在一個空間中一起反應的感覺。"},{"en":"During a quiet scene, shared breath can make the whole room feel connected.","zh":"在安靜場面中，共同呼吸可以令整個房間感覺相連。"},{"en":"This phrase suggests the physical closeness and emotional unity of live theatre.","zh":"這個短語暗示現場劇場的身體貼近和情感一致。"},{"en":"A recording can show the performance, but it cannot fully provide shared breath.","zh":"錄像可以展示演出，但不能完全提供共同呼吸。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"risk and presence","meaning":"風險與臨場感","examples":[{"en":"Live theatre involves silence, risk and presence.","zh":"現場劇場包含沉默、風險與臨場感。"},{"en":"Risk and presence mean the uncertainty of live performance and the feeling of being there together.","zh":"risk and presence 指現場演出的不確定性，以及共同在場的感覺。"},{"en":"A live speech has risk and presence because the speaker must face the audience directly.","zh":"現場演講有風險與臨場感，因為講者必須直接面對觀眾。"},{"en":"Theatre feels alive because actors may make mistakes, pause, or change energy in the moment.","zh":"劇場之所以有生命力，是因為演員可能在當下犯錯、停頓或改變能量。"},{"en":"Risk and presence make live theatre different from a perfectly edited video.","zh":"風險與臨場感令現場劇場不同於完美剪接的影片。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"actor pauses on stage","meaning":"演員在台上停頓","examples":[{"en":"When an actor pauses on stage, the audience feels it together.","zh":"當演員在台上停頓時，觀眾會一起感受到。"},{"en":"When an actor pauses on stage means when a performer stops speaking or moving during a live scene.","zh":"actor pauses on stage 指表演者在現場場面中停止說話或動作。"},{"en":"An actor may pause on stage before revealing a secret to build tension.","zh":"演員可能在揭露秘密前在台上停頓，以建立緊張感。"},{"en":"In live theatre, a pause can make the audience hold their breath.","zh":"在現場劇場中，一個停頓可以令觀眾屏息。"},{"en":"A pause on stage matters because everyone shares the silence at the same time.","zh":"台上的停頓很重要，因為所有人同時共享那份沉默。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"whole audience","meaning":"全場觀眾","examples":[{"en":"The whole audience feels the pause together.","zh":"全場觀眾一起感受到那個停頓。"},{"en":"The whole audience means everyone watching the performance in the same space.","zh":"whole audience 指在同一空間觀看演出的所有人。"},{"en":"The whole audience may laugh at the same joke or fall silent at the same moment.","zh":"全場觀眾可能因同一個笑話而發笑，或在同一刻安靜下來。"},{"en":"Live theatre is powerful because the whole audience reacts together.","zh":"現場劇場有力量，因為全場觀眾一起反應。"},{"en":"A recording lets individuals watch, but a theatre lets the whole audience share time.","zh":"錄像讓個人觀看，但劇場讓全場觀眾共享時間。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"feel the pause together","meaning":"一起感受停頓","examples":[{"en":"The audience can feel the pause together in a live performance.","zh":"觀眾可以在現場演出中一起感受停頓。"},{"en":"To feel the pause together means everyone shares the silence or hesitation at the same moment.","zh":"feel the pause together 指所有人在同一刻共享沉默或猶豫。"},{"en":"In a classroom presentation, classmates may feel the pause together before the speaker answers a hard question.","zh":"在課堂匯報中，講者回答難題前，同學可能一起感受停頓。"},{"en":"Shared pauses create tension because nobody knows exactly what will happen next.","zh":"共同停頓會創造緊張感，因為沒有人確切知道接下來會發生甚麼。"},{"en":"This feeling is difficult to reproduce when people watch alone on separate screens.","zh":"當人們獨自在不同螢幕上觀看時，這種感覺很難重現。"}],"source":"2018 Q7.pdf","sourcePage":12},{"front":"joke lands","meaning":"笑話奏效","examples":[{"en":"When a joke lands, laughter travels through the room.","zh":"當笑話奏效時，笑聲會在場內傳開。"},{"en":"When a joke lands means the joke succeeds and makes people laugh.","zh":"joke lands 指笑話成功，令人發笑。"},{"en":"A joke lands better when the audience understands the context.","zh":"當觀眾理解背景時，笑話會更容易奏效。"},{"en":"In theatre, actors can feel immediately whether a joke lands.","zh":"在劇場中，演員可以立即感受到笑話是否奏效。"},{"en":"If a joke does not land, the silence can also become part of the live moment.","zh":"如果笑話沒有奏效，那份沉默也可以成為現場一刻的一部分。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"laughter travels through the room","meaning":"笑聲在場內傳開","examples":[{"en":"When a joke lands, laughter travels through the room.","zh":"當笑話奏效時，笑聲會在場內傳開。"},{"en":"Laughter travels through the room means people’s laughter spreads across the shared space.","zh":"laughter travels through the room 指人們的笑聲在共享空間中擴散。"},{"en":"During a funny school play, laughter may travel through the room from the front row to the back.","zh":"在有趣的學校話劇中，笑聲可能從前排傳到後排。"},{"en":"This shared sound makes live comedy feel different from laughing alone at a video.","zh":"這種共享聲音令現場喜劇不同於獨自看影片時發笑。"},{"en":"Laughter travelling through the room reminds viewers that they are part of an audience.","zh":"笑聲在場內傳開，提醒觀眾自己是觀眾群的一部分。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"blackout falls","meaning":"燈光全黑的一刻","examples":[{"en":"When a blackout falls, darkness seems to belong to everyone.","zh":"當燈光全黑的一刻來臨，黑暗似乎屬於所有人。"},{"en":"When a blackout falls means when the stage lights suddenly go completely dark.","zh":"blackout falls 指舞台燈光突然完全變黑。"},{"en":"A blackout may fall at the end of a shocking scene to leave the audience silent.","zh":"在震撼場面結尾，燈光可能全黑，令觀眾沉默。"},{"en":"In theatre, a blackout can create a shared feeling of suspense or finality.","zh":"在劇場中，燈光全黑可以創造共同的懸念或終結感。"},{"en":"The darkness feels communal because everyone experiences it together.","zh":"黑暗感覺屬於眾人，因為所有人一起經歷它。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"belong to everyone","meaning":"屬於所有人","examples":[{"en":"In live theatre, silence can seem to belong to everyone.","zh":"在現場劇場中，沉默似乎可以屬於所有人。"},{"en":"Belong to everyone means something feels shared by all the people present.","zh":"belong to everyone 指某事物感覺由在場所有人共同擁有。"},{"en":"During a graduation ceremony, a proud silence may seem to belong to everyone in the hall.","zh":"在畢業典禮中，一份自豪的沉默可能似乎屬於禮堂內所有人。"},{"en":"In theatre, a pause belongs to everyone because all viewers feel it at once.","zh":"在劇場中，一個停頓屬於所有人，因為所有觀眾同時感受到它。"},{"en":"This phrase shows how live events create shared emotional ownership.","zh":"這個短語顯示現場事件如何創造共同的情感擁有感。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"however well filmed","meaning":"無論拍得多好","examples":[{"en":"A screen, however well filmed, keeps us at a slight distance.","zh":"螢幕無論拍得多好，都令我們保持一點距離。"},{"en":"However well filmed means no matter how skilfully or beautifully the recording is made.","zh":"however well filmed 指無論錄像拍攝得多有技巧或多美。"},{"en":"A concert video, however well filmed, cannot fully copy the feeling of being in the hall.","zh":"音樂會影片無論拍得多好，也不能完全複製身在音樂廳的感覺。"},{"en":"This phrase admits quality while still pointing out a limitation.","zh":"這個短語承認質素，同時指出限制。"},{"en":"However well filmed a play is, the viewer remains separated by the screen.","zh":"一齣劇無論拍得多好，觀眾仍被螢幕隔開。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"at a slight distance","meaning":"保持一點距離","examples":[{"en":"A screen keeps viewers at a slight distance.","zh":"螢幕令觀眾保持一點距離。"},{"en":"At a slight distance means not completely close or fully involved.","zh":"at a slight distance 指不是完全貼近或完全投入。"},{"en":"Watching a family celebration through video keeps relatives at a slight distance.","zh":"透過影片觀看家庭慶祝活動，會令親人保持一點距離。"},{"en":"Recordings can be moving, but the screen still places viewers at a slight distance from the live event.","zh":"錄像可以令人感動，但螢幕仍令觀眾與現場事件保持一點距離。"},{"en":"This distance is small enough to allow understanding, but large enough to change the experience.","zh":"這種距離小得足以讓人理解，但大得足以改變體驗。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"worse still","meaning":"更糟的是","examples":[{"en":"Worse still, viewers may think recordings are enough.","zh":"更糟的是，觀眾可能認為錄像已經足夠。"},{"en":"Worse still means even worse than the problem already mentioned.","zh":"worse still 指比剛提到的問題更糟糕。"},{"en":"The bus was late; worse still, the students missed the opening ceremony.","zh":"巴士遲到；更糟的是，學生錯過了開幕禮。"},{"en":"Writers use worse still to introduce a more serious danger or consequence.","zh":"作者使用 worse still 來引入更嚴重的危險或後果。"},{"en":"Worse still, recordings could replace live attendance if they are presented carelessly.","zh":"更糟的是，如果定位粗心，錄像可能取代現場入場。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"wrongly assume that","meaning":"錯誤地以為","examples":[{"en":"Viewers may wrongly assume that watching recordings is enough.","zh":"觀眾可能錯誤地以為看錄像已經足夠。"},{"en":"To wrongly assume that means to believe something incorrectly without enough evidence.","zh":"wrongly assume that 指在沒有足夠證據下錯誤地相信某事。"},{"en":"Students may wrongly assume that reading notes once is enough for an exam.","zh":"學生可能錯誤地以為溫習筆記一次就足夠應付考試。"},{"en":"Viewers may wrongly assume that recordings give the full theatre experience.","zh":"觀眾可能錯誤地以為錄像提供完整劇場體驗。"},{"en":"Clear framing prevents people from making the wrong assumption.","zh":"清晰定位可以防止人們作出錯誤假設。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"watching recordings is enough","meaning":"看錄像已經足夠","examples":[{"en":"Some viewers may think watching recordings is enough.","zh":"有些觀眾可能認為看錄像已經足夠。"},{"en":"Watching recordings is enough means people believe there is no need to attend live performances.","zh":"watching recordings is enough 指人們相信沒有需要出席現場演出。"},{"en":"A music fan may think watching concert clips is enough until they feel the energy of a live show.","zh":"音樂迷可能以為看演唱會片段已經足夠，直到他感受到現場演出的能量。"},{"en":"If people think recordings are enough, live theatres may lose future audiences.","zh":"如果人們認為看錄像已經足夠，現場劇場可能失去未來觀眾。"},{"en":"Recordings should create curiosity, not convince people to stop at the screen.","zh":"錄像應創造好奇心，而不是說服人們停留在螢幕前。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"buy a theatre ticket","meaning":"買劇場門票","examples":[{"en":"The danger is that some viewers may never buy a theatre ticket.","zh":"危險是有些觀眾可能永遠不會買劇場門票。"},{"en":"To buy a theatre ticket means to pay for admission to a live theatre performance.","zh":"buy a theatre ticket 指支付費用進入現場劇場演出。"},{"en":"A student may buy a theatre ticket after enjoying a recorded scene in class.","zh":"學生在課堂上喜歡一段錄製場面後，可能會買劇場門票。"},{"en":"Buying a theatre ticket is the action that turns interest into support for live theatre.","zh":"買劇場門票是把興趣轉化為支持現場劇場的行動。"},{"en":"If viewers never buy theatre tickets, recordings may fail to help the stage.","zh":"如果觀眾永遠不買劇場門票，錄像可能未能真正幫助舞台。"}],"source":"2018 Q7.pdf","sourcePage":13},{"front":"a real risk","meaning":"真正的風險","examples":[{"en":"This is a real risk for live theatre.","zh":"這對現場劇場是真正的風險。"},{"en":"A real risk is a genuine danger or problem, not just an imagined worry.","zh":"real risk 指真實存在的危險或問題，而不只是想像中的擔心。"},{"en":"Ignoring fire exits is a real risk during crowded events.","zh":"在擁擠活動中忽視走火通道是真正的風險。"},{"en":"For theatre, the real risk is that recordings may become substitutes instead of invitations.","zh":"對劇場而言，真正的風險是錄像可能變成替代品，而不是邀請。"},{"en":"Recognising a real risk helps organisers design the scheme more carefully.","zh":"承認真正的風險，有助主辦方更仔細設計計劃。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"acknowledge the limitation","meaning":"承認限制","examples":[{"en":"To acknowledge the limitation is not to reject the idea.","zh":"承認限制並不等於否定這個想法。"},{"en":"To acknowledge the limitation means to honestly admit what something cannot do.","zh":"acknowledge the limitation 指誠實承認某事物不能做到甚麼。"},{"en":"A teacher may acknowledge the limitation of online learning while still using it during bad weather.","zh":"老師可能承認網上學習的限制，但仍在惡劣天氣時使用它。"},{"en":"Acknowledging limitations helps people improve a plan instead of pretending it is perfect.","zh":"承認限制幫助人改善計劃，而不是假裝它完美。"},{"en":"The limitation of recordings should be stated clearly so audiences still value live theatre.","zh":"錄像的限制應清楚說明，讓觀眾仍然重視現場劇場。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"reject the idea","meaning":"否定這個想法","examples":[{"en":"The limitation does not mean we should reject the idea.","zh":"這項限制並不代表我們應否定這個想法。"},{"en":"To reject the idea means to refuse or dismiss a proposal.","zh":"reject the idea 指拒絕或否定一項建議。"},{"en":"A school should not reject the idea of online homework just because some students need support.","zh":"學校不應只因有些學生需要支援，就否定網上功課的想法。"},{"en":"People may improve an idea by addressing its weaknesses instead of rejecting it immediately.","zh":"人們可以透過處理弱點來改善想法，而不是立即否定它。"},{"en":"The recording scheme has limits, but those limits do not make it useless.","zh":"錄像計劃有限制，但這些限制不代表它沒有用。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"how it is framed","meaning":"它如何被定位","examples":[{"en":"The success of the scheme depends on how it is framed.","zh":"這項計劃的成功取決於它如何被定位。"},{"en":"How it is framed means how an idea is presented, explained, or positioned.","zh":"how it is framed 指一個想法如何被呈現、解釋或定位。"},{"en":"Homework feels different depending on whether it is framed as punishment or practice.","zh":"功課被定位為懲罰或練習時，感覺會很不同。"},{"en":"If recordings are framed as introductions, they can support live theatre.","zh":"如果錄像被定位為入門介紹，它們可以支援現場劇場。"},{"en":"Framing matters because it shapes what people expect and do next.","zh":"定位很重要，因為它塑造人們的期待和下一步行動。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"promote the screenings as","meaning":"將放映宣傳為","examples":[{"en":"HKAPA should not promote the screenings as a full theatre experience.","zh":"香港演藝學院不應將放映宣傳為完整劇場體驗。"},{"en":"To promote the screenings as something means to advertise or describe them in a particular way.","zh":"promote the screenings as something 指以某種方式宣傳或描述這些放映。"},{"en":"A museum should not promote a short online tour as the same as visiting the exhibition.","zh":"博物館不應把短網上導覽宣傳為等同親身參觀展覽。"},{"en":"If screenings are promoted as complete theatre, audiences may not seek live shows.","zh":"如果放映被宣傳為完整劇場，觀眾可能不會尋找現場演出。"},{"en":"Responsible promotion should make the benefit clear without hiding the limitation.","zh":"負責任的宣傳應清楚說明好處，而不隱藏限制。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"the theatre experience at home","meaning":"在家中的劇場體驗","examples":[{"en":"The recordings should not be sold as the theatre experience at home.","zh":"這些錄像不應被包裝成在家中的劇場體驗。"},{"en":"The theatre experience at home means a version of theatre that people watch from home through a screen.","zh":"the theatre experience at home 指人們透過螢幕在家觀看的劇場版本。"},{"en":"Watching a recording at home can be convenient, but it lacks the shared room of live theatre.","zh":"在家看錄像可以方便，但它缺少現場劇場的共同空間。"},{"en":"If recordings are sold as the full theatre experience at home, live attendance may seem unnecessary.","zh":"如果錄像被包裝成完整的在家劇場體驗，現場入場可能顯得不必要。"},{"en":"A home viewing experience should be presented as an introduction, not the whole art form.","zh":"家中觀看體驗應被定位為入門，而不是整個藝術形式。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"weaken live attendance","meaning":"削弱現場入場人數","examples":[{"en":"Poor framing may weaken live attendance.","zh":"差劣定位可能削弱現場入場人數。"},{"en":"To weaken live attendance means to reduce the number of people going to live performances.","zh":"weaken live attendance 指減少前往現場演出的人數。"},{"en":"Free online concerts may weaken live attendance if people believe the online version is enough.","zh":"如果人們相信網上版本已經足夠，免費網上音樂會可能削弱現場入場人數。"},{"en":"The risk can be reduced if recordings are linked to live tickets and events.","zh":"如果錄像與現場門票和活動連繫起來，這種風險可以降低。"},{"en":"The goal should be to strengthen live attendance, not weaken it.","zh":"目標應該是加強現場入場人數，而不是削弱它。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"live attendance","meaning":"現場入場人數","examples":[{"en":"The programme should support live attendance, not replace it.","zh":"這項計劃應支持現場入場人數，而不是取代它。"},{"en":"Live attendance means going to a performance in person as part of the audience.","zh":"live attendance 指親身作為觀眾出席演出。"},{"en":"Live attendance supports actors, technicians, theatres, and the whole arts community.","zh":"現場入場支持演員、技術人員、劇院和整個藝術社群。"},{"en":"Recordings can encourage live attendance by making audiences curious about the real event.","zh":"錄像可以透過令觀眾好奇真實現場事件，鼓勵現場入場。"},{"en":"Without live attendance, theatre loses the shared presence that makes it special.","zh":"沒有現場入場，劇場會失去令它特別的共同臨場感。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"first step into the theatre","meaning":"走進劇場的第一步","examples":[{"en":"The screenings should be presented as a first step into the theatre.","zh":"這些放映應被定位為走進劇場的第一步。"},{"en":"A first step into the theatre means an easy beginning that leads people toward live theatre.","zh":"first step into the theatre 指帶領人走向現場劇場的容易開始。"},{"en":"A student workshop can be a first step into the theatre before students watch a play.","zh":"學生工作坊可以是學生觀看舞台劇前走進劇場的第一步。"},{"en":"Screenings become useful when they help viewers move from curiosity to attendance.","zh":"當放映幫助觀眾由好奇走向入場時，就變得有用。"},{"en":"A first step into the theatre should make the next step feel possible.","zh":"走進劇場的第一步應令下一步感覺可行。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"become invitations","meaning":"變成邀請","examples":[{"en":"The recordings can become invitations to live theatre.","zh":"這些錄像可以變成走向現場劇場的邀請。"},{"en":"To become invitations means to make people feel welcomed and encouraged to try something further.","zh":"become invitations 指令人感到受歡迎並被鼓勵進一步嘗試。"},{"en":"A free open lesson can become an invitation to join a full course.","zh":"免費公開課可以變成參加完整課程的邀請。"},{"en":"Recordings become invitations when they point clearly toward related live shows.","zh":"當錄像清楚指向相關現場演出時，它們就變成邀請。"},{"en":"An invitation opens a door; it should not replace the whole journey.","zh":"邀請會打開一扇門；它不應取代整段旅程。"}],"source":"2018 Q7.pdf","sourcePage":14},{"front":"cinema trailer","meaning":"電影預告片","examples":[{"en":"A cinema trailer makes people want to see the full film.","zh":"電影預告片令人想看完整電影。"},{"en":"A cinema trailer is a short video preview used to promote a film.","zh":"cinema trailer 指用來宣傳電影的短片預告。"},{"en":"A good cinema trailer shows enough excitement to create interest without giving away everything.","zh":"好的電影預告片展示足夠刺激內容以創造興趣，但不透露一切。"},{"en":"Theatre recordings can work like trailers if they make viewers want the live experience.","zh":"如果戲劇錄像令觀眾想要現場體驗，它們可以像預告片一樣運作。"},{"en":"A trailer is successful when people leave wanting more.","zh":"當人們看完後想看更多，預告片就是成功的。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"make cinema unnecessary","meaning":"令電影變得不必要","examples":[{"en":"A trailer has never made cinema unnecessary.","zh":"預告片從未令電影變得不必要。"},{"en":"To make cinema unnecessary means to remove the need or reason to watch the full film in a cinema.","zh":"make cinema unnecessary 指消除在戲院觀看完整電影的需要或理由。"},{"en":"A menu photo does not make eating the meal unnecessary.","zh":"菜單相片不會令真正吃那道菜變得不必要。"},{"en":"In the same way, a theatre recording should not make live theatre unnecessary.","zh":"同樣地，戲劇錄像不應令現場劇場變得不必要。"},{"en":"A preview should increase desire for the full experience, not replace it.","zh":"預覽應增加人們對完整體驗的渴望，而不是取代它。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"want the full film","meaning":"想看完整電影","examples":[{"en":"A good trailer makes people want the full film.","zh":"好的預告片令人想看完整電影。"},{"en":"To want the full film means to feel interested enough to watch the complete movie.","zh":"want the full film 指有足夠興趣去觀看完整電影。"},{"en":"A short clip can make viewers want the full film if it shows an exciting conflict.","zh":"如果短片展示刺激衝突，就可以令觀眾想看完整電影。"},{"en":"Theatre recordings should similarly make audiences want the full live experience.","zh":"戲劇錄像也應同樣令觀眾想要完整現場體驗。"},{"en":"Wanting the full film shows that the preview has created curiosity, not satisfied it completely.","zh":"想看完整電影顯示預覽創造了好奇心，而不是完全滿足了它。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"do the same for","meaning":"對……產生同樣作用","examples":[{"en":"Theatre recordings can do the same for stage plays.","zh":"戲劇錄像可以對舞台劇產生同樣作用。"},{"en":"To do the same for something means to create a similar effect for another thing.","zh":"do the same for something 指對另一件事產生類似效果。"},{"en":"Book trailers can do the same for novels by making students curious to read.","zh":"書本預告片可以對小說產生同樣作用，令學生好奇想讀。"},{"en":"If film trailers build interest in films, theatre recordings can do the same for plays.","zh":"如果電影預告片能建立對電影的興趣，戲劇錄像也可以對舞台劇產生同樣作用。"},{"en":"This phrase connects one example with a similar possible result.","zh":"這個短語把一個例子與類似的可能結果連接起來。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, HKAPA should go ahead with the plan.","zh":"綜合而言，香港演藝學院應推行這項計劃。"},{"en":"All things considered means after thinking about all the important advantages and disadvantages.","zh":"all things considered 指在考慮所有重要優點和缺點之後。"},{"en":"All things considered, the school trip was worthwhile despite the rain.","zh":"綜合而言，雖然下雨，學校旅行仍然值得。"},{"en":"Writers use this phrase near a conclusion to give a balanced judgement.","zh":"作者常在結論附近使用這個短語，以作出平衡判斷。"},{"en":"All things considered, recordings are useful if they lead people toward live theatre.","zh":"綜合而言，如果錄像能帶人走向現場劇場，它們是有用的。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"go ahead with the plan","meaning":"推行這項計劃","examples":[{"en":"HKAPA should go ahead with the plan.","zh":"香港演藝學院應推行這項計劃。"},{"en":"To go ahead with the plan means to continue and put the proposal into action.","zh":"go ahead with the plan 指繼續並把建議付諸實行。"},{"en":"A school may go ahead with a sports day after checking that the weather is safe.","zh":"學校在確認天氣安全後，可能推行運動日。"},{"en":"Organisations should go ahead with a plan only after considering risks and support.","zh":"機構應在考慮風險和支援後才推行計劃。"},{"en":"Going ahead with the plan does not mean ignoring problems; it means managing them carefully.","zh":"推行這項計劃不代表忽視問題；而是仔細管理它們。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"clear strategy","meaning":"清晰策略","examples":[{"en":"The plan needs a clear strategy.","zh":"這項計劃需要清晰策略。"},{"en":"A clear strategy is a well-organised plan with specific aims and steps.","zh":"clear strategy 指有清楚目標和步驟的良好組織計劃。"},{"en":"A revision group needs a clear strategy so students know what to study each week.","zh":"溫習小組需要清晰策略，讓學生知道每星期要溫習甚麼。"},{"en":"Without a clear strategy, a good idea may fail because people do not know how to use it.","zh":"沒有清晰策略，好想法也可能失敗，因為人們不知道如何使用它。"},{"en":"HKAPA needs a clear strategy to connect recordings with live theatre attendance.","zh":"香港演藝學院需要清晰策略，把錄像與現場劇場入場連接起來。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"curate accessible productions","meaning":"策劃易於入門的製作","examples":[{"en":"HKAPA should curate accessible productions for new audiences.","zh":"香港演藝學院應為新觀眾策劃易於入門的製作。"},{"en":"To curate accessible productions means to choose and arrange performances that beginners can understand and enjoy.","zh":"curate accessible productions 指選擇和安排初學者能理解和享受的演出。"},{"en":"A museum curates accessible exhibitions by using clear labels and familiar examples.","zh":"博物館透過清晰標籤和熟悉例子，策劃易於理解的展覽。"},{"en":"Accessible productions help new audiences enter theatre without feeling lost.","zh":"易於入門的製作幫助新觀眾進入劇場，而不感到迷失。"},{"en":"Careful curation matters because the first play can shape someone’s whole impression of theatre.","zh":"細心策劃很重要，因為第一齣劇可能塑造某人對劇場的整體印象。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"accessible productions","meaning":"易於理解的製作","examples":[{"en":"Accessible productions can help beginners enjoy theatre.","zh":"易於理解的製作可以幫助初學者享受劇場。"},{"en":"Accessible productions are performances that are easier for new audiences to understand, enter, or appreciate.","zh":"accessible productions 指較容易讓新觀眾理解、進入或欣賞的演出。"},{"en":"A play with clear storytelling and helpful subtitles may be an accessible production.","zh":"一齣故事清晰並有有用字幕的劇，可能是易於理解的製作。"},{"en":"Accessible productions reduce fear because viewers do not feel excluded by difficult language or form.","zh":"易於理解的製作能減少恐懼，因為觀眾不會因艱深語言或形式而感到被排除。"},{"en":"Accessible does not mean simple-minded; it means welcoming and understandable.","zh":"易於理解不代表思想簡單；而是代表友善和清楚。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"key dramatic features","meaning":"主要戲劇特色","examples":[{"en":"HKAPA should explain key dramatic features before screenings.","zh":"香港演藝學院應在放映前解釋主要戲劇特色。"},{"en":"Key dramatic features are important elements of a play, such as character, conflict, dialogue, movement, and lighting.","zh":"key dramatic features 指舞台劇的重要元素，例如角色、衝突、對白、動作和燈光。"},{"en":"A teacher may explain key dramatic features before students watch a difficult scene.","zh":"老師可能在學生觀看困難場面前，解釋主要戲劇特色。"},{"en":"Understanding key dramatic features helps viewers notice how theatre creates meaning.","zh":"理解主要戲劇特色幫助觀眾注意劇場如何創造意義。"},{"en":"Explaining these features can turn watching into active learning.","zh":"解釋這些特色可以把觀看轉化為主動學習。"}],"source":"2018 Q7.pdf","sourcePage":15},{"front":"dramatic features","meaning":"戲劇特色","examples":[{"en":"Lighting, dialogue and blocking are dramatic features.","zh":"燈光、對白和舞台調度都是戲劇特色。"},{"en":"Dramatic features are the parts of a performance that help create story, mood, and meaning.","zh":"dramatic features 指演出中幫助創造故事、氣氛和意義的部分。"},{"en":"Music, silence, costume, and movement can all be dramatic features.","zh":"音樂、沉默、服裝和動作都可以是戲劇特色。"},{"en":"Viewers enjoy theatre more when they notice how dramatic features work together.","zh":"當觀眾注意到戲劇特色如何配合時，會更享受劇場。"},{"en":"Dramatic features show that a play communicates through more than spoken words.","zh":"戲劇特色顯示舞台劇不只透過說話溝通。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"actors or directors","meaning":"演員或導演","examples":[{"en":"Actors or directors could speak after screenings.","zh":"演員或導演可以在放映後分享。"},{"en":"Actors or directors are the performers in a play or the people who guide its overall artistic choices.","zh":"actors or directors 指舞台劇中的表演者，或指導整體藝術選擇的人。"},{"en":"Actors can explain how they build characters, while directors can explain stage decisions.","zh":"演員可以解釋如何建立角色，而導演可以解釋舞台決定。"},{"en":"Hearing actors or directors speak can help audiences understand the work behind a production.","zh":"聆聽演員或導演分享，可以幫助觀眾理解製作背後的工作。"},{"en":"Their sharing makes the recording feel connected to real theatre-making.","zh":"他們的分享令錄像感覺與真實劇場創作連接起來。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"speak after screenings","meaning":"放映後分享","examples":[{"en":"HKAPA could invite directors to speak after screenings.","zh":"香港演藝學院可以邀請導演在放映後分享。"},{"en":"To speak after screenings means to give a talk or discussion after the recorded performance is shown.","zh":"speak after screenings 指在錄製演出放映後進行講解或討論。"},{"en":"A film director may speak after screenings to explain why certain scenes were filmed in a particular way.","zh":"電影導演可能在放映後分享，解釋某些場面為何以特定方式拍攝。"},{"en":"When artists speak after screenings, viewers can ask questions and deepen understanding.","zh":"當藝術家在放映後分享時，觀眾可以提問並加深理解。"},{"en":"This practice helps transform a screening into an educational theatre event.","zh":"這種做法幫助把放映轉化為具教育意義的劇場活動。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"practical next steps","meaning":"實際的下一步","examples":[{"en":"The scheme should offer practical next steps.","zh":"這項計劃應提供實際的下一步。"},{"en":"Practical next steps are clear actions people can take after an experience.","zh":"practical next steps 指人們在一段體驗後可以採取的清楚行動。"},{"en":"After a career talk, practical next steps may include joining a workshop or applying for an internship.","zh":"職業講座後，實際的下一步可能包括參加工作坊或申請實習。"},{"en":"Theatre screenings need practical next steps, such as ticket links, discounts, or beginner guides.","zh":"劇場放映需要實際的下一步，例如購票連結、折扣或初學者指南。"},{"en":"Without practical next steps, viewers may feel interested but do nothing.","zh":"沒有實際的下一步，觀眾可能感興趣卻沒有行動。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"beginner-friendly live shows","meaning":"適合初學者的現場演出","examples":[{"en":"Beginner-friendly live shows can help new audiences enter theatre.","zh":"適合初學者的現場演出可以幫助新觀眾進入劇場。"},{"en":"Beginner-friendly live shows are live performances that are suitable for people new to theatre.","zh":"beginner-friendly live shows 指適合剛接觸劇場人士的現場演出。"},{"en":"A beginner-friendly show may have clear storytelling, helpful introductions, and affordable tickets.","zh":"適合初學者的演出可能有清晰故事、有用介紹和可負擔門票。"},{"en":"Such shows reduce anxiety because viewers know they are not expected to understand everything alone.","zh":"這類演出能減少焦慮，因為觀眾知道自己不需要獨自理解一切。"},{"en":"Beginner-friendly live shows help turn first curiosity into repeated attendance.","zh":"適合初學者的現場演出幫助把初步好奇轉化為再次入場。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"student tickets","meaning":"學生票","examples":[{"en":"Student tickets can make theatre more affordable.","zh":"學生票可以令劇場更可負擔。"},{"en":"Student tickets are discounted tickets offered to students.","zh":"student tickets 指提供給學生的折扣門票。"},{"en":"A student ticket may allow young people to attend a play without spending too much money.","zh":"學生票可以讓年輕人不用花太多錢就能觀看舞台劇。"},{"en":"Student tickets matter because cost is often a real barrier for beginners.","zh":"學生票很重要，因為費用常是初學者的真實障礙。"},{"en":"Affordable student tickets can build theatre habits before people become full-price adults.","zh":"可負擔的學生票可以在人們成為全票成人觀眾前，建立看劇習慣。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"the purpose should not be to","meaning":"目的不應該是","examples":[{"en":"The purpose should not be to make theatre permanently safer and flatter.","zh":"目的不應該是令劇場永久變得更安全和更平面。"},{"en":"The purpose should not be to means this should not be the main aim or goal.","zh":"the purpose should not be to 指這不應是主要目的或目標。"},{"en":"The purpose of school rules should not be to control students completely, but to help them learn safely.","zh":"校規的目的不應該是完全控制學生，而是幫助他們安全學習。"},{"en":"The purpose of recordings should not be to replace the challenge of live theatre.","zh":"錄像的目的不應該是取代現場劇場的挑戰。"},{"en":"This phrase helps reject the wrong goal before explaining the better one.","zh":"這個短語幫助先否定錯誤目標，再解釋更好的目標。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"flatter, cheaper and safer","meaning":"更平面、更便宜、更安全","examples":[{"en":"The aim is not to make theatre flatter, cheaper and safer forever.","zh":"目標不是令劇場永遠變得更平面、更便宜、更安全。"},{"en":"Flatter, cheaper and safer means less deep, less costly, and less risky or challenging.","zh":"flatter, cheaper and safer 指較少深度、較低成本，並較少風險或挑戰。"},{"en":"Online versions can make learning cheaper and safer, but sometimes flatter.","zh":"網上版本可以令學習更便宜、更安全，但有時也更平面。"},{"en":"Theatre should become less intimidating at first, not permanently flatter and less alive.","zh":"劇場起初應變得較不令人卻步，而不是永遠更平面、較少生命力。"},{"en":"This phrase warns that convenience can reduce depth if it becomes the final goal.","zh":"這個短語提醒我們，如果便利成為最終目標，可能會減少深度。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"less intimidating","meaning":"較不令人卻步","examples":[{"en":"The aim is to make theatre less intimidating at first.","zh":"目標是令劇場一開始較不令人卻步。"},{"en":"Less intimidating means less frightening, difficult, or discouraging to approach.","zh":"less intimidating 指較不令人害怕、困難或退縮。"},{"en":"A beginner class makes swimming less intimidating by starting in shallow water.","zh":"初學班從淺水開始，令游泳較不令人卻步。"},{"en":"Recordings make theatre less intimidating because viewers can try it before buying tickets.","zh":"錄像令劇場較不令人卻步，因為觀眾可以在買票前先嘗試。"},{"en":"Making theatre less intimidating should help people enter, not avoid, the real experience.","zh":"令劇場較不令人卻步，應幫助人進入真實體驗，而不是避開它。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"at first","meaning":"起初；一開始","examples":[{"en":"The recordings should make theatre less intimidating at first.","zh":"這些錄像應令劇場起初較不令人卻步。"},{"en":"At first means in the beginning stage of an experience or process.","zh":"at first 指在一段體驗或過程的開始階段。"},{"en":"Cycling may feel difficult at first, but practice makes balance easier.","zh":"騎單車起初可能感覺困難，但練習會令平衡更容易。"},{"en":"Theatre may seem strange at first because viewers do not yet know its habits.","zh":"劇場一開始可能顯得奇怪，因為觀眾尚未了解它的習慣。"},{"en":"A helpful first experience can change how people feel later.","zh":"有幫助的第一次體驗，可以改變人們之後的感受。"}],"source":"2018 Q7.pdf","sourcePage":16},{"front":"art form","meaning":"藝術形式","examples":[{"en":"Theatre as an art form is still alive.","zh":"劇場作為一種藝術形式仍然有生命力。"},{"en":"An art form is a way of creating artistic expression, such as theatre, music, painting, or dance.","zh":"art form 指創造藝術表達的方式，例如劇場、音樂、繪畫或舞蹈。"},{"en":"Film is an art form because it uses image, sound, acting, and editing to create meaning.","zh":"電影是一種藝術形式，因為它使用影像、聲音、演技和剪接來創造意義。"},{"en":"Theatre remains a living art form because it changes with performers and audiences.","zh":"劇場仍是一種活的藝術形式，因為它會隨表演者和觀眾改變。"},{"en":"Treating theatre as an art form reminds us that it is more than entertainment.","zh":"把劇場視為藝術形式，提醒我們它不只是娛樂。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"still alive","meaning":"仍然有生命力","examples":[{"en":"The art form is still alive because live presence matters.","zh":"這種藝術形式仍然有生命力，因為現場臨場感很重要。"},{"en":"Still alive means continuing to have energy, meaning, or importance.","zh":"still alive 指仍然有能量、意義或重要性。"},{"en":"Traditional crafts are still alive when young people learn and practise them.","zh":"當年輕人學習和實踐傳統工藝時，傳統工藝仍然有生命力。"},{"en":"Theatre is still alive because each live performance is created again with the audience.","zh":"劇場仍然有生命力，因為每場現場演出都與觀眾重新創造。"},{"en":"Something is still alive when people keep caring about it and renewing it.","zh":"當人們持續關心並更新某事物時，它就仍然有生命力。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"nothing quite replaces","meaning":"沒有東西真正取代","examples":[{"en":"Nothing quite replaces the moment when performers meet the audience.","zh":"沒有東西真正取代表演者與觀眾相遇的一刻。"},{"en":"Nothing quite replaces means no other thing can fully take the place of something special.","zh":"nothing quite replaces 指沒有其他東西能完全取代某件特別事物。"},{"en":"Video calls are useful, but nothing quite replaces meeting an old friend face to face.","zh":"視像通話很有用，但沒有東西真正取代與老朋友面對面相見。"},{"en":"Recordings help, but nothing quite replaces the shared energy of live theatre.","zh":"錄像有幫助，但沒有東西真正取代現場劇場的共同能量。"},{"en":"This phrase admits alternatives while protecting the value of the original experience.","zh":"這個短語承認替代方式，同時保護原本體驗的價值。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"performers and audience","meaning":"表演者和觀眾","examples":[{"en":"Theatre happens when performers and audience meet in the same room.","zh":"當表演者和觀眾在同一空間相遇時，劇場就發生了。"},{"en":"Performers and audience are the people who act, dance, sing, or speak, and the people who watch them.","zh":"performers and audience 指表演、跳舞、唱歌或說話的人，以及觀看他們的人。"},{"en":"In theatre, performers and audience share time, space, silence, and reaction.","zh":"在劇場中，表演者和觀眾共享時間、空間、沉默和反應。"},{"en":"The relationship between performers and audience shapes the energy of a live show.","zh":"表演者和觀眾之間的關係塑造現場演出的能量。"},{"en":"A recording can show performers, but it cannot fully include the live audience relationship.","zh":"錄像可以展示表演者，但不能完全包含現場觀眾關係。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"meet in the same room","meaning":"在同一空間相遇","examples":[{"en":"Performers and audience meet in the same room during live theatre.","zh":"在現場劇場中，表演者和觀眾在同一空間相遇。"},{"en":"To meet in the same room means to be physically present together in one shared space.","zh":"meet in the same room 指在同一個共享空間中親身同在。"},{"en":"A class discussion feels different when students and teachers meet in the same room.","zh":"當學生和老師在同一空間相遇時，課堂討論的感覺會不同。"},{"en":"Live theatre depends on performers and audience meeting in the same room.","zh":"現場劇場依賴表演者和觀眾在同一空間相遇。"},{"en":"This shared room creates reactions that cannot be fully copied by separate screens.","zh":"這個共享空間創造出不能被分開的螢幕完全複製的反應。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"discover that magic on screen","meaning":"先在螢幕上發現那份魔力","examples":[{"en":"Let people discover that magic on screen first.","zh":"讓人們先在螢幕上發現那份魔力。"},{"en":"To discover that magic on screen means to first notice theatre’s special appeal through a recording.","zh":"discover that magic on screen 指先透過錄像注意到劇場的特別吸引力。"},{"en":"A student may discover the magic of dance on screen before attending a live performance.","zh":"學生可能先在螢幕上發現舞蹈的魔力，然後出席現場演出。"},{"en":"Discovering magic on screen can create enough curiosity to seek the real thing.","zh":"先在螢幕上發現魔力，可以創造足夠好奇心去尋找真實體驗。"},{"en":"The screen should be a doorway to the magic, not the only place it exists.","zh":"螢幕應是通往魔力的門口，而不是那份魔力唯一存在的地方。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"give them every reason to","meaning":"給他們充分理由去","examples":[{"en":"HKAPA should give viewers every reason to seek theatre on stage.","zh":"香港演藝學院應給觀眾充分理由去在舞台上尋找劇場。"},{"en":"To give them every reason to do something means to provide strong motivation and support for that action.","zh":"give them every reason to do something 指為某個行動提供強烈動機和支援。"},{"en":"A teacher gives students every reason to read by choosing exciting books and discussing them warmly.","zh":"老師透過選擇精彩書本並熱情討論，給學生充分理由去閱讀。"},{"en":"HKAPA can give viewers every reason to attend by offering introductions, discounts, and related live shows.","zh":"香港演藝學院可以透過提供介紹、折扣和相關現場演出，給觀眾充分理由去入場。"},{"en":"This phrase suggests active encouragement, not just passive hope.","zh":"這個短語暗示積極鼓勵，而不是被動希望。"}],"source":"2018 Q7.pdf","sourcePage":17},{"front":"seek it on stage","meaning":"在舞台上尋找它","examples":[{"en":"Viewers should be encouraged to seek that magic on stage.","zh":"應鼓勵觀眾在舞台上尋找那份魔力。"},{"en":"To seek it on stage means to look for the full theatre experience in a live performance.","zh":"seek it on stage 指在現場演出中尋找完整劇場體驗。"},{"en":"After enjoying a recording, a student may seek the same emotional power on stage.","zh":"喜歡一段錄像後，學生可能會在舞台上尋找同樣的情感力量。"},{"en":"Seeking it on stage matters because theatre’s strongest qualities appear when performers and audiences share space.","zh":"在舞台上尋找它很重要，因為劇場最強的特質在表演者和觀眾共享空間時出現。"},{"en":"The best recording makes viewers want to leave the screen and enter the theatre.","zh":"最好的錄像會令觀眾想離開螢幕，走進劇場。"}],"source":"2018 Q7.pdf","sourcePage":17}],"dse/writing/part-b/2018/Q8":[{"front":"apply for the scholarship","meaning":"申請獎學金","examples":[{"en":"I am writing to apply for the Poetry House Summer Poetry Workshop Scholarship.","zh":"我寫信是為了申請 Poetry House 夏季詩歌工作坊獎學金。"},{"en":"To apply for the scholarship means to formally ask to be considered for financial support or a place.","zh":"apply for the scholarship 指正式申請獲得資助或名額考慮。"},{"en":"A student may apply for the scholarship by sending a letter, portfolio, and application form.","zh":"學生可以透過提交信件、作品集和申請表來申請獎學金。"},{"en":"If the fee is too high, applying for the scholarship can make the programme possible.","zh":"如果費用太高，申請獎學金可以令參加課程變得可能。"},{"en":"Chris applies for the scholarship because he wants to grow as a poet but needs support.","zh":"Chris 申請獎學金，因為他想作為詩人成長，但需要支援。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"Summer Poetry Workshop Scholarship","meaning":"夏季詩歌工作坊獎學金","examples":[{"en":"The applicant is applying for the Summer Poetry Workshop Scholarship.","zh":"申請人正在申請夏季詩歌工作坊獎學金。"},{"en":"The Summer Poetry Workshop Scholarship is financial support for a summer programme about writing poetry.","zh":"Summer Poetry Workshop Scholarship 是為夏季詩歌寫作課程提供的資助。"},{"en":"A young writer may need the Summer Poetry Workshop Scholarship to join classes, readings, and discussions.","zh":"年輕作家可能需要夏季詩歌工作坊獎學金，才能參加課堂、朗讀和討論。"},{"en":"The scholarship can reduce the cost of learning from experienced poets.","zh":"這項獎學金可以減輕向資深詩人學習的費用。"},{"en":"Receiving the Summer Poetry Workshop Scholarship would give Chris time and guidance to improve.","zh":"獲得夏季詩歌工作坊獎學金，會給 Chris 改進所需的時間和指導。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"Scholarship Selection Committee","meaning":"獎學金遴選委員會","examples":[{"en":"The letter is addressed to the Scholarship Selection Committee.","zh":"這封信是寫給獎學金遴選委員會的。"},{"en":"A Scholarship Selection Committee is a group of people who decide who should receive a scholarship.","zh":"Scholarship Selection Committee 是決定誰應獲得獎學金的一組人。"},{"en":"The Scholarship Selection Committee reads applications and compares candidates fairly.","zh":"獎學金遴選委員會閱讀申請，並公平比較候選人。"},{"en":"If the committee sees strong commitment, it may choose the applicant for support.","zh":"如果委員會看見強烈投入，可能會選擇申請人提供支援。"},{"en":"Chris writes formally because he is addressing the Scholarship Selection Committee.","zh":"Chris 使用正式語氣，因為他正寫給獎學金遴選委員會。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"be often described as","meaning":"常被形容為","examples":[{"en":"Poetry is often described as a private art.","zh":"詩歌常被形容為一種私人的藝術。"},{"en":"Be often described as means people commonly explain or present something in a particular way.","zh":"be often described as 指人們常以某種方式解釋或呈現某事物。"},{"en":"Reading is often described as a doorway to other worlds.","zh":"閱讀常被形容為通往其他世界的一道門。"},{"en":"If something is often described as difficult, people may feel nervous before trying it.","zh":"如果某事常被形容為困難，人們嘗試前可能會感到緊張。"},{"en":"Poetry is often described as private, but workshops show that poems can also grow with others.","zh":"詩歌常被形容為私人的，但工作坊顯示詩也可以與他人一起成長。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"a private art","meaning":"私人的藝術","examples":[{"en":"Poetry is often described as a private art.","zh":"詩歌常被形容為一種私人的藝術。"},{"en":"A private art is a creative practice that feels personal, quiet, and inward.","zh":"a private art 指感覺個人化、安靜而向內的創作方式。"},{"en":"Keeping a diary can feel like a private art because it records feelings not meant for everyone.","zh":"寫日記可以像一種私人的藝術，因為它記錄不一定給所有人看的感受。"},{"en":"Poetry may seem like a private art when writers work alone with their own memories.","zh":"當作者獨自處理自己的記憶時，詩歌可能看似私人的藝術。"},{"en":"The workshop challenges the idea that poetry is only a private art.","zh":"工作坊挑戰了詩歌只是私人藝術的想法。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"suggest something larger","meaning":"意味着更宏大的東西","examples":[{"en":"The workshop suggests something larger than private writing.","zh":"這個工作坊意味着比私人寫作更宏大的東西。"},{"en":"To suggest something larger means to point to a bigger meaning, purpose, or possibility.","zh":"suggest something larger 指指向更大的意義、目的或可能性。"},{"en":"A school concert can suggest something larger than performance: it can show community spirit.","zh":"一場學校音樂會可以意味着比表演更宏大的東西：它能展現社群精神。"},{"en":"When a poem connects strangers, it suggests something larger than one person’s feelings.","zh":"當一首詩連繫陌生人，它就意味着比個人感受更大的東西。"},{"en":"The workshop suggests something larger because it joins craft, conversation, and community.","zh":"工作坊意味着更宏大的東西，因為它結合技巧、交流和社群。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"creative community","meaning":"創作社群","examples":[{"en":"Poems can grow in a creative community.","zh":"詩可以在創作社群中成長。"},{"en":"A creative community is a group of people who share ideas, feedback, and artistic energy.","zh":"creative community 是一群分享想法、回饋和藝術能量的人。"},{"en":"A school writing club can become a creative community for young writers.","zh":"學校寫作學會可以成為年輕作家的創作社群。"},{"en":"In a creative community, writers improve because others respond to their work honestly.","zh":"在創作社群中，作者因別人誠實回應作品而進步。"},{"en":"Chris wants to join a creative community where poems are tested and strengthened.","zh":"Chris 想加入一個能檢視並加強詩作的創作社群。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"be sharpened by","meaning":"透過……變得更精煉","examples":[{"en":"Poems can be sharpened by craft, conversation and contact with other voices.","zh":"詩可以透過技巧、交流和接觸其他聲音而變得更精煉。"},{"en":"Be sharpened by means be improved, made clearer, or made stronger through something.","zh":"be sharpened by 指透過某事而改善、變得更清晰或更有力。"},{"en":"An argument can be sharpened by careful evidence and honest questions.","zh":"一個論點可以透過仔細證據和誠實提問而變得更精準。"},{"en":"A poem is sharpened by revision when weak words are replaced with stronger ones.","zh":"當薄弱字詞被更有力的字取代，一首詩就會透過修改變得更精煉。"},{"en":"Chris believes his writing can be sharpened by guidance from other poets.","zh":"Chris 相信他的寫作可以透過其他詩人的指導變得更精煉。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"craft, conversation and contact","meaning":"技巧、交流與接觸","examples":[{"en":"The workshop offers craft, conversation and contact with other writers.","zh":"這個工作坊提供技巧、交流，以及與其他作者接觸的機會。"},{"en":"Craft, conversation and contact mean writing skill, discussion, and direct connection with others.","zh":"craft, conversation and contact 指寫作技巧、討論和與他人的直接連繫。"},{"en":"A good workshop teaches craft, encourages conversation, and creates contact between writers.","zh":"好的工作坊會教授技巧、鼓勵交流，並讓作者彼此接觸。"},{"en":"These three things help writers improve both their technique and confidence.","zh":"這三樣東西能幫助作者改善技巧和信心。"},{"en":"Chris values craft, conversation and contact because poetry should not grow in isolation only.","zh":"Chris 重視技巧、交流與接觸，因為詩不應只在孤立中成長。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"voices from beyond one’s own city","meaning":"來自自己城市以外的聲音","examples":[{"en":"Young writers can learn from voices from beyond their own city.","zh":"年輕作家可以向來自自己城市以外的聲音學習。"},{"en":"Voices from beyond one’s own city means writers, ideas, and experiences from other places.","zh":"voices from beyond one’s own city 指來自其他地方的作者、想法和經驗。"},{"en":"A Hong Kong poet may learn new rhythms from voices from beyond his own city.","zh":"香港詩人可能從自己城市以外的聲音學到新的節奏。"},{"en":"Hearing different voices can challenge local habits and widen imagination.","zh":"聽見不同聲音可以挑戰本地習慣並擴闊想像。"},{"en":"Chris hopes these voices will help him see poetry in a larger world.","zh":"Chris 希望這些聲音幫助他在更大的世界中看見詩歌。"}],"source":"2018 Q8.pdf","sourcePage":1},{"front":"young writer","meaning":"年輕作家","examples":[{"en":"Chris Wong presents himself as a young writer in Hong Kong.","zh":"Chris Wong 把自己呈現為香港的一名年輕作家。"},{"en":"A young writer is someone early in life or early in their writing journey.","zh":"young writer 指年紀尚輕或寫作旅程剛開始的人。"},{"en":"A young writer may keep notebooks, join workshops, and submit poems to magazines.","zh":"年輕作家可能會寫筆記、參加工作坊，並向雜誌投稿詩作。"},{"en":"Young writers need guidance because talent alone does not teach revision.","zh":"年輕作家需要指導，因為單靠天份不能學會修改。"},{"en":"Chris calls himself a young writer to show both promise and room to grow.","zh":"Chris 稱自己為年輕作家，是為了顯示潛力和成長空間。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"develop from...into...","meaning":"由……發展成……","examples":[{"en":"His interest in poetry has developed from a quiet habit into a serious commitment.","zh":"他對詩歌的興趣由靜靜培養的習慣發展成認真的投入。"},{"en":"Develop from A into B means change gradually from one state into another.","zh":"develop from A into B 指逐漸由一種狀態變成另一種狀態。"},{"en":"Her interest in drawing developed from a weekend hobby into a career goal.","zh":"她對繪畫的興趣由週末嗜好發展成職業目標。"},{"en":"A small habit can develop into commitment when someone practises every day.","zh":"當一個人每天練習，小小習慣可以發展成投入。"},{"en":"Chris’s poetry developed from private notes into a serious part of his life.","zh":"Chris 的詩歌由私人筆記發展成生命中認真的一部分。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"a quiet habit","meaning":"靜靜培養的習慣","examples":[{"en":"Writing poetry began as a quiet habit.","zh":"寫詩最初是一個靜靜培養的習慣。"},{"en":"A quiet habit is something someone does regularly, privately, and without much attention.","zh":"a quiet habit 指一個人經常、私下而不張揚地做的事。"},{"en":"Reading before bed can become a quiet habit that calms the mind.","zh":"睡前閱讀可以成為讓心情平靜的靜靜培養的習慣。"},{"en":"A quiet habit can grow important when it helps a person understand themselves.","zh":"當一個習慣幫助人理解自己，它就可能變得重要。"},{"en":"For Chris, poetry began quietly before it became a serious commitment.","zh":"對 Chris 來說，詩歌起初很安靜，後來才成為認真的投入。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"serious commitment","meaning":"認真的投入；嚴肅承諾","examples":[{"en":"His interest in poetry has become a serious commitment.","zh":"他對詩歌的興趣已成為認真的投入。"},{"en":"A serious commitment is a strong promise to continue working at something carefully.","zh":"serious commitment 指認真承諾會細心而持續地投入某事。"},{"en":"Practising the piano every day shows serious commitment to music.","zh":"每天練習鋼琴顯示對音樂的認真投入。"},{"en":"A hobby becomes a serious commitment when someone gives it time, effort, and discipline.","zh":"當一個人投入時間、努力和紀律，嗜好就會變成認真的投入。"},{"en":"Chris shows serious commitment by writing, revising, and reading poetry regularly.","zh":"Chris 透過定期寫作、修改和閱讀詩歌，展現認真的投入。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"be deeply grateful for","meaning":"對……深表感激","examples":[{"en":"He would be deeply grateful for the opportunity to join the workshop.","zh":"他會對參加工作坊的機會深表感激。"},{"en":"Be deeply grateful for means feel very thankful for something important.","zh":"be deeply grateful for 指對重要的事感到非常感謝。"},{"en":"A student may be deeply grateful for a teacher’s patient guidance.","zh":"學生可能對老師耐心指導深表感激。"},{"en":"People feel deeply grateful when support helps them do something they could not do alone.","zh":"當支援幫助人做到獨自無法做到的事，他們會深表感激。"},{"en":"Chris would be deeply grateful because the workshop could change his writing life.","zh":"Chris 會深表感激，因為工作坊可能改變他的寫作生命。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"the opportunity to take part in","meaning":"參加……的機會","examples":[{"en":"He is grateful for the opportunity to take part in the programme.","zh":"他感激有機會參加這個課程。"},{"en":"The opportunity to take part in means the chance to join and be involved in an activity.","zh":"the opportunity to take part in 指加入並參與某項活動的機會。"},{"en":"Students value the opportunity to take part in a debate competition.","zh":"學生珍惜參加辯論比賽的機會。"},{"en":"An opportunity to take part in a workshop can help a young person learn from others.","zh":"參加工作坊的機會可以幫助年輕人向他人學習。"},{"en":"Chris wants the opportunity to take part in a programme that treats poetry seriously.","zh":"Chris 想得到參加一個認真看待詩歌課程的機會。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"promote both the art and the craft of poetry","meaning":"推廣詩歌的藝術與技巧","examples":[{"en":"The programme promotes both the art and the craft of poetry.","zh":"這個課程推廣詩歌的藝術與技巧。"},{"en":"To promote both the art and the craft of poetry means to support poetic imagination and writing technique together.","zh":"promote both the art and the craft of poetry 指同時支持詩的想像力和寫作技巧。"},{"en":"A poetry class promotes art through feeling and craft through careful revision.","zh":"詩歌課透過情感推廣藝術，透過仔細修改推廣技巧。"},{"en":"If a programme teaches only inspiration but not technique, it misses part of poetry.","zh":"如果一個課程只教靈感而不教技巧，就會忽略詩歌的一部分。"},{"en":"Chris is drawn to a workshop that values beauty and skill at the same time.","zh":"Chris 嚮往同時重視美感和技巧的工作坊。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"be selected","meaning":"被選中","examples":[{"en":"He believes he should be selected for the scholarship.","zh":"他相信自己應該被選中獲得獎學金。"},{"en":"Be selected means be chosen from a group of applicants.","zh":"be selected 指從一群申請人中被挑選出來。"},{"en":"Ten students were selected for the summer writing camp.","zh":"十名學生被選中參加夏季寫作營。"},{"en":"A candidate may be selected because their application shows ability and commitment.","zh":"候選人可能因申請顯示能力和投入而被選中。"},{"en":"Chris hopes to be selected because he can benefit from and contribute to the workshop.","zh":"Chris 希望被選中，因為他能從工作坊受益，也能作出貢獻。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"not only benefit from...but also contribute to...","meaning":"不但從……受益，也為……作出貢獻","examples":[{"en":"He would not only benefit from the workshop, but also contribute to it.","zh":"他不但會從工作坊受益，也會為它作出貢獻。"},{"en":"Not only benefit from A but also contribute to A means receive help from something and also add value to it.","zh":"not only benefit from A but also contribute to A 指從某事得到幫助，同時為它增添價值。"},{"en":"A student can not only benefit from a club but also contribute to it by helping new members.","zh":"學生不但可以從學會受益，也可以透過幫助新成員為學會作出貢獻。"},{"en":"Good participants learn from discussions and make those discussions richer.","zh":"好的參加者從討論中學習，也令討論更豐富。"},{"en":"Chris wants to gain guidance while also giving careful feedback to others.","zh":"Chris 想獲得指導，同時也仔細回饋他人。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"contribute to it with","meaning":"以……為其作出貢獻","examples":[{"en":"He would contribute to the workshop with curiosity and discipline.","zh":"他會以好奇心和紀律為工作坊作出貢獻。"},{"en":"To contribute to it with something means to help an activity by bringing that quality or skill.","zh":"contribute to it with something 指帶着某種特質或技能去幫助一項活動。"},{"en":"A student can contribute to a project with research, patience, and teamwork.","zh":"學生可以以資料搜集、耐性和團隊合作為專題作出貢獻。"},{"en":"Workshops improve when members contribute with honest questions and careful listening.","zh":"當成員以誠實提問和細心聆聽作出貢獻，工作坊就會進步。"},{"en":"Chris would contribute with curiosity because he wants to learn, not just impress.","zh":"Chris 會以好奇心作出貢獻，因為他想學習，而不只是令人留下印象。"}],"source":"2018 Q8.pdf","sourcePage":2},{"front":"curiosity, discipline and respect","meaning":"好奇心、紀律和尊重","examples":[{"en":"He would bring curiosity, discipline and respect for language.","zh":"他會帶來好奇心、紀律和對語言的尊重。"},{"en":"Curiosity, discipline and respect mean a wish to learn, steady effort, and careful treatment of words.","zh":"curiosity, discipline and respect 指學習的渴望、穩定努力，以及細心對待文字。"},{"en":"A good writer needs curiosity to ask questions and discipline to revise.","zh":"好作家需要好奇心去提問，也需要紀律去修改。"},{"en":"Respect for language stops writers from using words carelessly.","zh":"對語言的尊重會阻止作者隨便使用文字。"},{"en":"These qualities make Chris a thoughtful participant in a poetry workshop.","zh":"這些特質令 Chris 成為詩歌工作坊中深思熟慮的參加者。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"a sincere respect for language","meaning":"對語言的真誠尊重","examples":[{"en":"The applicant shows a sincere respect for language.","zh":"申請人展現出對語言的真誠尊重。"},{"en":"A sincere respect for language means a genuine care for how words sound, mean, and affect people.","zh":"a sincere respect for language 指真心重視文字的聲音、意義和影響。"},{"en":"A poet shows respect for language by choosing words carefully instead of decoration only.","zh":"詩人透過仔細選字，而不是只追求裝飾，展現對語言的尊重。"},{"en":"Without sincere respect for language, writing may become vague or careless.","zh":"沒有對語言的真誠尊重，寫作可能變得模糊或粗心。"},{"en":"Chris’s respect for language appears in his revision and attention to rhythm.","zh":"Chris 對語言的尊重，體現在他的修改和對節奏的留意中。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"begin in an ordinary place","meaning":"始於一個平凡的地方","examples":[{"en":"His interest in poetry began in an ordinary place.","zh":"他對詩歌的興趣始於一個平凡的地方。"},{"en":"Begin in an ordinary place means start from somewhere simple, familiar, or not special.","zh":"begin in an ordinary place 指從簡單、熟悉或不特別的地方開始。"},{"en":"A love of science may begin in an ordinary place, such as a kitchen experiment.","zh":"對科學的熱愛可能始於一個平凡的地方，例如廚房實驗。"},{"en":"Important interests often begin in ordinary places before becoming serious.","zh":"重要興趣常在平凡地方開始，然後才變得認真。"},{"en":"Chris’s poetry began not on a stage, but at the back of a school notebook.","zh":"Chris 的詩歌不是始於舞台，而是始於學校筆記簿後頁。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"the back of a school notebook","meaning":"學校筆記簿後頁","examples":[{"en":"He first wrote poems at the back of a school notebook.","zh":"他最初在學校筆記簿後頁寫詩。"},{"en":"The back of a school notebook means the unused final pages of a student’s notebook.","zh":"the back of a school notebook 指學生筆記簿最後未用的頁面。"},{"en":"A student may draw or write private thoughts at the back of a school notebook.","zh":"學生可能在學校筆記簿後頁畫畫或寫私人想法。"},{"en":"Writing there feels informal because it is not meant for marks or display.","zh":"在那裏寫字感覺較隨意，因為它不是為了分數或展示。"},{"en":"For Chris, the back of a school notebook became the first home of his poems.","zh":"對 Chris 來說，學校筆記簿後頁成為他詩作最初的家。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"at first","meaning":"起初","examples":[{"en":"At first, he wrote short lines only to record private feelings.","zh":"起初，他只寫短短的詩句來記錄私人感受。"},{"en":"At first means in the beginning, before something changed later.","zh":"at first 指一開始，在後來有所改變之前。"},{"en":"At first, the new student felt shy, but later she joined the class discussion.","zh":"起初，新同學感到害羞，但後來加入課堂討論。"},{"en":"At first, a habit may seem small before it grows into something serious.","zh":"起初，一個習慣可能看似很小，後來才發展成認真的事。"},{"en":"At first, Chris wrote only for himself, but poetry later became a commitment.","zh":"起初，Chris 只為自己寫作，但詩歌後來成為一份投入。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"short lines","meaning":"短短的詩句","examples":[{"en":"At first, he wrote short lines in his notebook.","zh":"起初，他在筆記簿裏寫短短的詩句。"},{"en":"Short lines are brief rows of words, often used in poems to create rhythm or focus.","zh":"short lines 指簡短的一行行文字，常用於詩中創造節奏或焦點。"},{"en":"A poem with short lines can make each word feel important.","zh":"由短短詩句組成的詩，可以令每個字都顯得重要。"},{"en":"Short lines may help a young writer record feelings quickly.","zh":"短短的詩句可以幫助年輕作者快速記錄感受。"},{"en":"Chris began with short lines before learning how to shape fuller poems.","zh":"Chris 從短短的詩句開始，後來才學習如何塑造更完整的詩。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"say aloud","meaning":"說出口","examples":[{"en":"He wrote what he could not say aloud.","zh":"他寫下自己無法說出口的東西。"},{"en":"To say aloud means to speak words so other people can hear them.","zh":"say aloud 指把話說出來，讓其他人聽見。"},{"en":"A shy student may write in a diary what she cannot say aloud in class.","zh":"害羞的學生可能在日記裏寫下自己在課堂上無法說出口的話。"},{"en":"Poetry can give shape to feelings that are difficult to say aloud.","zh":"詩歌可以為難以說出口的感受賦予形狀。"},{"en":"Chris used poems to express thoughts that felt too private to speak.","zh":"Chris 用詩表達那些太私人、難以說出口的想法。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"fading Cantonese songs","meaning":"漸漸淡去的廣東歌","examples":[{"en":"He recorded his grandmother’s fading Cantonese songs.","zh":"他記錄祖母那些漸漸淡去的廣東歌。"},{"en":"Fading Cantonese songs are old Cantonese songs that are slowly being forgotten or disappearing from memory.","zh":"fading Cantonese songs 指慢慢被遺忘或從記憶中消失的舊廣東歌。"},{"en":"A family may sing fading Cantonese songs during festivals to keep memories alive.","zh":"一個家庭可能在節日唱漸漸淡去的廣東歌，以保存回憶。"},{"en":"When older relatives stop singing, fading songs may disappear from family history.","zh":"當年長親人不再唱歌，漸漸淡去的歌曲可能會從家庭歷史中消失。"},{"en":"Chris wrote them down because poetry can preserve voices before they vanish.","zh":"Chris 把它們寫下來，因為詩能在聲音消失前保存它們。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"the loneliness of crossing","meaning":"穿過……時的孤獨感","examples":[{"en":"He wrote about the loneliness of crossing a crowded MTR platform.","zh":"他寫下穿過擠迫港鐵月台時的孤獨感。"},{"en":"The loneliness of crossing means the lonely feeling someone has while moving across a place.","zh":"the loneliness of crossing 指人在穿過某地方時感到的孤單。"},{"en":"A person may feel the loneliness of crossing a busy street where nobody notices them.","zh":"一個人穿過繁忙街道、沒有人留意他時，可能會感到孤獨。"},{"en":"Crowds can make loneliness stronger when everyone seems separate and hurried.","zh":"當人人都像分離又匆忙，群眾反而會加強孤獨感。"},{"en":"Chris noticed that even a crowded platform could hold a private loneliness.","zh":"Chris 留意到，即使擠迫的月台也可以藏着私人孤獨。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"crowded MTR platform","meaning":"擠迫的港鐵月台","examples":[{"en":"The crowded MTR platform made him feel lonely.","zh":"擠迫的港鐵月台令他感到孤獨。"},{"en":"A crowded MTR platform is a busy train platform filled with many passengers.","zh":"crowded MTR platform 指擠滿乘客的繁忙港鐵月台。"},{"en":"During rush hour, a crowded MTR platform can feel noisy and stressful.","zh":"在繁忙時間，擠迫的港鐵月台會令人感到嘈雜和有壓力。"},{"en":"A crowded MTR platform may make people feel small because everyone is rushing.","zh":"擠迫的港鐵月台可能令人覺得渺小，因為人人都在趕路。"},{"en":"Chris turns this ordinary Hong Kong scene into material for poetry.","zh":"Chris 把這個普通香港場景變成詩歌材料。"}],"source":"2018 Q8.pdf","sourcePage":3},{"front":"strange silence","meaning":"奇怪的沉默","examples":[{"en":"He wrote about the strange silence after an argument at home.","zh":"他寫下家中爭執後那種奇怪的沉默。"},{"en":"Strange silence is an unusual quietness that feels uncomfortable or meaningful.","zh":"strange silence 指不尋常、令人不舒服或帶有意義的安靜。"},{"en":"After the teacher became angry, a strange silence filled the classroom.","zh":"老師生氣後，課室充滿奇怪的沉默。"},{"en":"Strange silence can show that people are hurt even when nobody speaks.","zh":"奇怪的沉默可以顯示人們受傷了，即使沒有人說話。"},{"en":"Chris uses poetry to listen to the feelings hidden inside silence.","zh":"Chris 用詩去聆聽沉默中隱藏的感受。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"an argument at home","meaning":"家中的爭執","examples":[{"en":"The poem described the silence after an argument at home.","zh":"這首詩描寫家中爭執後的沉默。"},{"en":"An argument at home is a disagreement or quarrel between family members.","zh":"an argument at home 指家庭成員之間的分歧或爭吵。"},{"en":"A child may feel upset after an argument at home between parents.","zh":"父母家中爭執後，孩子可能會感到不安。"},{"en":"After an argument at home, the quietness can feel heavier than shouting.","zh":"家中爭執後的安靜，可能比叫喊更沉重。"},{"en":"Chris notices family tension and turns it into careful poetic attention.","zh":"Chris 留意家庭中的緊張，並把它化成細心的詩意觀察。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"over time","meaning":"隨着時間過去","examples":[{"en":"Over time, he realised that poetry was a way to pay attention.","zh":"隨着時間過去，他明白詩歌是一種留心觀察的方式。"},{"en":"Over time means gradually as days, months, or years pass.","zh":"over time 指隨着日子、月份或年月逐漸過去。"},{"en":"Over time, a beginner can become confident through regular practice.","zh":"隨着時間過去，初學者可以透過定期練習變得有信心。"},{"en":"Feelings about writing may change over time as a person gains experience.","zh":"隨着經驗增加，一個人對寫作的感受可能會改變。"},{"en":"Chris slowly understood that poetry was not only expression but attention.","zh":"Chris 慢慢明白，詩歌不只是表達，也是留心觀察。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"not simply...rather...","meaning":"不只是……而是……","examples":[{"en":"Poetry was not simply a way to express emotion; rather, it was a way to pay attention.","zh":"詩歌不只是表達情感的方式；而是留心觀察的方式。"},{"en":"Not simply A; rather, B means B is the deeper or more accurate idea.","zh":"not simply A; rather, B 指 B 是更深或更準確的想法。"},{"en":"Learning is not simply memorising facts; rather, it is understanding how ideas connect.","zh":"學習不只是背誦事實；而是理解想法如何連繫。"},{"en":"This structure helps a writer correct a shallow explanation.","zh":"這個結構幫助作者修正表面的解釋。"},{"en":"Chris uses it to show that poetry is more than personal feeling.","zh":"Chris 用它來顯示詩歌不只是私人感受。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"express emotion","meaning":"表達情感","examples":[{"en":"Poetry can express emotion, but it can also sharpen attention.","zh":"詩歌可以表達情感，但也可以加強觀察力。"},{"en":"To express emotion means to show feelings through words, actions, art, or voice.","zh":"express emotion 指透過文字、行動、藝術或聲音表現感受。"},{"en":"A song can express emotion when the singer sounds sad or hopeful.","zh":"當歌手聽起來悲傷或充滿希望，一首歌就能表達情感。"},{"en":"If people cannot express emotion safely, they may feel more alone.","zh":"如果人們無法安全地表達情感，可能會感到更孤單。"},{"en":"Poetry helps Chris express emotion while also noticing the world carefully.","zh":"詩歌幫助 Chris 表達情感，同時細心觀察世界。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"pay attention","meaning":"留心觀察","examples":[{"en":"Poetry taught him to pay attention to ordinary details.","zh":"詩歌教他留心觀察普通細節。"},{"en":"To pay attention means to notice something carefully instead of ignoring it.","zh":"pay attention 指仔細注意某事，而不是忽略它。"},{"en":"A doctor must pay attention to small changes in a patient’s breathing.","zh":"醫生必須留心觀察病人呼吸中的細微變化。"},{"en":"Writers pay attention to sounds, images, gestures, and silence.","zh":"作者會留心觀察聲音、意象、動作和沉默。"},{"en":"Chris believes poetry begins when someone truly pays attention.","zh":"Chris 相信，當一個人真正留心觀察時，詩就開始了。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"a successful poem","meaning":"成功的詩","examples":[{"en":"A successful poem can turn ordinary objects into something human.","zh":"成功的詩可以把普通物件變成有人情味的東西。"},{"en":"A successful poem is a poem that moves readers and makes its images meaningful.","zh":"a successful poem 指能打動讀者並令意象有意義的詩。"},{"en":"A successful poem may make a streetlamp feel lonely or protective.","zh":"成功的詩可能令一盞街燈顯得孤單或像在守護人。"},{"en":"A poem succeeds when readers feel more aware after reading it.","zh":"當讀者讀後變得更有覺察，一首詩就是成功的。"},{"en":"For Chris, a successful poem changes how people see ordinary life.","zh":"對 Chris 來說，成功的詩會改變人們看待日常生活的方式。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"turn something into","meaning":"把……變成","examples":[{"en":"A poem can turn a streetlamp into something unexpectedly human.","zh":"一首詩可以把街燈變成意想不到地有人情味的東西。"},{"en":"To turn something into something else means to change how it appears, feels, or functions.","zh":"turn something into something else 指改變某物的樣子、感覺或功能。"},{"en":"A teacher can turn a mistake into a lesson.","zh":"老師可以把錯誤變成一堂課。"},{"en":"Poetry can turn ordinary details into images full of feeling.","zh":"詩歌可以把普通細節變成充滿情感的意象。"},{"en":"Chris wants his poems to turn small city moments into shared experience.","zh":"Chris 希望他的詩能把城市小片刻變成共同經驗。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"a half-finished bowl of noodles","meaning":"吃了一半的麵","examples":[{"en":"A poem can make a half-finished bowl of noodles feel human.","zh":"一首詩可以令一碗吃了一半的麵顯得有人情味。"},{"en":"A half-finished bowl of noodles is a bowl of noodles that someone has partly eaten but not finished.","zh":"a half-finished bowl of noodles 指一碗有人吃了一部分但未吃完的麵。"},{"en":"A half-finished bowl of noodles may suggest hurry, sadness, or interruption.","zh":"一碗吃了一半的麵可能暗示匆忙、悲傷或被打斷。"},{"en":"In poetry, ordinary food can carry memory and emotion.","zh":"在詩中，普通食物也可以承載記憶和情感。"},{"en":"Chris notices small objects like this because they can reveal human stories.","zh":"Chris 留意這類小物件，因為它們能揭示人的故事。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"unexpectedly human","meaning":"意想不到地有人情味","examples":[{"en":"A poem can make ordinary objects feel unexpectedly human.","zh":"一首詩可以令普通物件顯得意想不到地有人情味。"},{"en":"Unexpectedly human means surprisingly full of feeling, memory, or personal meaning.","zh":"unexpectedly human 指出乎意料地充滿感情、記憶或個人意義。"},{"en":"An empty chair can feel unexpectedly human if it reminds us of someone absent.","zh":"如果空椅子令人想起不在場的人，它可以顯得意想不到地有人情味。"},{"en":"A poem makes objects human when readers sense emotion inside them.","zh":"當讀者在物件中感受到情緒，詩就令物件變得有人情味。"},{"en":"Chris is fascinated by how poetry gives feeling to ordinary things.","zh":"Chris 着迷於詩歌如何賦予普通事物情感。"}],"source":"2018 Q8.pdf","sourcePage":4},{"front":"what fascinates me most","meaning":"最令我着迷的是","examples":[{"en":"What fascinates him most is how poetry balances compression and expansion.","zh":"最令他着迷的是詩歌如何平衡凝練與延展。"},{"en":"What fascinates me most means the thing that interests or attracts me the most deeply.","zh":"what fascinates me most 指最深深吸引我或令我感興趣的事。"},{"en":"What fascinates me most about music is how one melody can hold many memories.","zh":"音樂最令我着迷的是，一段旋律可以承載許多記憶。"},{"en":"This phrase introduces a personal but thoughtful reason for interest.","zh":"這個片語引出個人而深思熟慮的興趣原因。"},{"en":"For Chris, poetry fascinates him because small language can create large meaning.","zh":"對 Chris 來說，詩歌令他着迷，因為小小語言能創造巨大意義。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"balance compression and expansion","meaning":"平衡凝練與延展","examples":[{"en":"Poetry can balance compression and expansion.","zh":"詩歌可以平衡凝練與延展。"},{"en":"To balance compression and expansion means to use few words while opening wide meanings.","zh":"balance compression and expansion 指用少量文字打開廣闊意義。"},{"en":"A haiku balances compression and expansion by using short lines to suggest a whole season.","zh":"俳句透過短短詩句暗示整個季節，平衡凝練與延展。"},{"en":"Poetry feels powerful when a small image expands into a large memory.","zh":"當小小意象延展成巨大記憶，詩就顯得有力。"},{"en":"Chris wants to learn how to make brief lines carry deeper worlds.","zh":"Chris 想學會如何令簡短詩句承載更深的世界。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"a few words","meaning":"寥寥數語","examples":[{"en":"A few words may open a whole landscape of memory.","zh":"寥寥數語可能展開一整片記憶風景。"},{"en":"A few words means a small number of words.","zh":"a few words 指少量文字。"},{"en":"A few words from a teacher can give a student confidence for years.","zh":"老師寥寥數語可以給學生多年的信心。"},{"en":"In poetry, a few words can suggest a feeling without explaining everything.","zh":"在詩中，寥寥數語可以暗示感受，而不必解釋一切。"},{"en":"Chris values how a few words can become larger than they first appear.","zh":"Chris 重視寥寥數語如何變得比表面更廣闊。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"open a whole landscape of memory","meaning":"展開一整片記憶風景","examples":[{"en":"A few words may open a whole landscape of memory.","zh":"寥寥數語可能展開一整片記憶風景。"},{"en":"To open a whole landscape of memory means to bring back many memories through a small image or phrase.","zh":"open a whole landscape of memory 指透過小意象或片語喚起大量記憶。"},{"en":"The smell of rain can open a whole landscape of memory about childhood.","zh":"雨的氣味可以展開一整片關於童年的記憶風景。"},{"en":"A poem can open memory when it connects one detail to a person’s past.","zh":"當詩把一個細節連接到人的過去，它就能打開記憶。"},{"en":"Chris wants his lines to open memory without saying too much.","zh":"Chris 希望自己的詩句能不多說卻展開記憶。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"continue writing","meaning":"繼續寫作","examples":[{"en":"He continued writing even when schoolwork was demanding.","zh":"即使課業繁重，他仍然繼續寫作。"},{"en":"Continue writing means keep writing instead of stopping.","zh":"continue writing 指繼續寫下去，而不是停止。"},{"en":"A student may continue writing a story during lunch breaks.","zh":"學生可能在午膳時間繼續寫故事。"},{"en":"Continuing to write during busy periods shows discipline and commitment.","zh":"在忙碌時期仍繼續寫作，顯示紀律和投入。"},{"en":"Chris continued writing because poetry had become more than a casual hobby.","zh":"Chris 繼續寫作，因為詩歌已不只是隨意嗜好。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"schoolwork was demanding","meaning":"課業繁重","examples":[{"en":"He kept writing even when schoolwork was demanding.","zh":"即使課業繁重，他仍然保持寫作。"},{"en":"Schoolwork was demanding means homework and study required a lot of time and effort.","zh":"schoolwork was demanding 指功課和學習需要很多時間和努力。"},{"en":"Schoolwork was demanding during exam season, so many students slept late.","zh":"考試季期間課業繁重，所以許多學生睡得很晚。"},{"en":"When schoolwork is demanding, hobbies are often the first things people give up.","zh":"當課業繁重，嗜好往往最先被人放棄。"},{"en":"Chris kept writing despite demanding schoolwork, showing serious commitment.","zh":"Chris 面對繁重課業仍然寫作，顯示認真的投入。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"keep a notebook with me","meaning":"隨身帶着筆記簿","examples":[{"en":"He keeps a small notebook with him.","zh":"他隨身帶着一本小筆記簿。"},{"en":"To keep a notebook with me means to carry a notebook so ideas can be written down anytime.","zh":"keep a notebook with me 指隨身帶着筆記簿，以便隨時寫下想法。"},{"en":"A writer keeps a notebook with her on the bus to catch sudden lines.","zh":"作家在巴士上隨身帶着筆記簿，以捕捉突然出現的詩句。"},{"en":"Keeping a notebook nearby prevents small observations from being forgotten.","zh":"把筆記簿放在身邊，可以避免小觀察被忘記。"},{"en":"Chris carries a notebook because poems may begin anywhere.","zh":"Chris 帶着筆記簿，因為詩可能在任何地方開始。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"revise drafts","meaning":"修改草稿","examples":[{"en":"He revises drafts after lessons.","zh":"他下課後修改草稿。"},{"en":"To revise drafts means to improve early versions of writing by changing words, lines, or structure.","zh":"revise drafts 指透過改動字詞、詩句或結構來改善早期作品。"},{"en":"Students revise drafts before handing in essays.","zh":"學生交作文前會修改草稿。"},{"en":"Revising drafts can turn unclear writing into stronger work.","zh":"修改草稿可以把不清楚的寫作變成更有力的作品。"},{"en":"Chris revises drafts because he respects poetry as craft, not just inspiration.","zh":"Chris 修改草稿，因為他尊重詩歌是一門技巧，而不只是靈感。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"read poems in English and Chinese","meaning":"閱讀中英文詩","examples":[{"en":"He reads poems in English and Chinese.","zh":"他閱讀中英文詩。"},{"en":"To read poems in English and Chinese means to study poetry written in both languages.","zh":"read poems in English and Chinese 指研讀以英文和中文寫成的詩。"},{"en":"Bilingual readers can notice how images change between English and Chinese poems.","zh":"雙語讀者可以留意英文詩和中文詩之間意象如何改變。"},{"en":"Reading across languages helps writers understand different rhythms and traditions.","zh":"跨語言閱讀幫助作者理解不同節奏和傳統。"},{"en":"Chris reads in both languages to widen his poetic ear.","zh":"Chris 閱讀兩種語言的詩，是為了擴闊自己的詩歌聽覺。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"rhythm, image and voice","meaning":"節奏、意象和聲音","examples":[{"en":"He studies how rhythm, image and voice work across languages.","zh":"他研究節奏、意象和聲音如何在不同語言中運作。"},{"en":"Rhythm, image and voice are a poem’s sound pattern, picture-making details, and speaking presence.","zh":"rhythm, image and voice 是詩的聲音模式、製造畫面的細節和說話者的存在感。"},{"en":"A strong poem may use rhythm to move, image to show, and voice to speak.","zh":"有力的詩可能用節奏推動、用意象展示、用聲音說話。"},{"en":"Studying rhythm, image and voice helps writers understand why a poem works.","zh":"研究節奏、意象和聲音能幫助作者理解一首詩為何有效。"},{"en":"Chris studies these elements because poetry depends on more than meaning alone.","zh":"Chris 研究這些元素，因為詩歌不只依賴意思。"}],"source":"2018 Q8.pdf","sourcePage":5},{"front":"work differently across languages","meaning":"在不同語言中運作方式不同","examples":[{"en":"Rhythm, image and voice work differently across languages.","zh":"節奏、意象和聲音在不同語言中運作方式不同。"},{"en":"Work differently across languages means function in different ways when used in different languages.","zh":"work differently across languages 指在不同語言中使用時功能或效果不同。"},{"en":"Humour may work differently across languages because jokes depend on sound and culture.","zh":"幽默在不同語言中可能運作方式不同，因為笑話依賴聲音和文化。"},{"en":"A rhythm that sounds natural in English may not work the same way in Chinese.","zh":"英文中自然的節奏，在中文中未必以同樣方式運作。"},{"en":"Chris wants to understand these differences so his writing can become more precise.","zh":"Chris 想理解這些差異，讓自己的寫作更精準。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"be particularly drawn to","meaning":"對……特別嚮往","examples":[{"en":"He is particularly drawn to Poetry House’s workshop.","zh":"他對 Poetry House 的工作坊特別嚮往。"},{"en":"Be particularly drawn to means feel especially attracted to or interested in something.","zh":"be particularly drawn to 指對某事特別被吸引或感興趣。"},{"en":"She is particularly drawn to history because old stories explain modern life.","zh":"她對歷史特別嚮往，因為舊故事能解釋現代生活。"},{"en":"A writer may be drawn to a workshop that offers serious feedback.","zh":"作者可能會對提供認真回饋的工作坊特別嚮往。"},{"en":"Chris is particularly drawn to this programme because it combines craft and community.","zh":"Chris 對這個課程特別嚮往，因為它結合技巧和社群。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"offer what young writers rarely receive","meaning":"提供年輕作家少有的東西","examples":[{"en":"The workshop offers what young writers rarely receive.","zh":"這個工作坊提供年輕作家少有的東西。"},{"en":"Offer what young writers rarely receive means provide something valuable that young writers do not often get.","zh":"offer what young writers rarely receive 指提供年輕作家不常得到的寶貴東西。"},{"en":"A mentor offers what young writers rarely receive when she gives honest line-by-line feedback.","zh":"當導師逐行給予誠實回饋，她就提供了年輕作家少有的東西。"},{"en":"Young writers rarely receive serious attention, so a good workshop can be important.","zh":"年輕作家很少得到認真關注，所以好的工作坊十分重要。"},{"en":"Chris values the workshop because it offers guidance, challenge, and community.","zh":"Chris 重視這個工作坊，因為它提供指導、挑戰和社群。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"serious guidance","meaning":"認真的指導","examples":[{"en":"Young writers rarely receive serious guidance.","zh":"年輕作家很少得到認真的指導。"},{"en":"Serious guidance is careful, thoughtful advice that helps someone improve deeply.","zh":"serious guidance 是細心而深思熟慮、能幫助人深入進步的建議。"},{"en":"Serious guidance helps students understand what works and what needs revision.","zh":"認真的指導幫助學生理解哪些地方有效，哪些地方需要修改。"},{"en":"Without serious guidance, young writers may repeat the same mistakes.","zh":"沒有認真的指導，年輕作家可能會重複同樣錯誤。"},{"en":"Chris hopes serious guidance will make his poems clearer and braver.","zh":"Chris 希望認真的指導能令他的詩更清晰、更勇敢。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"creative environment","meaning":"創意環境","examples":[{"en":"The workshop provides serious guidance in a creative environment.","zh":"這個工作坊在創意環境中提供認真的指導。"},{"en":"A creative environment is a place where people feel free and supported to make new work.","zh":"creative environment 是讓人感到自由並得到支持去創作新作品的地方。"},{"en":"An art room can become a creative environment if students feel safe to experiment.","zh":"如果學生可以安全地嘗試，美術室就能成為創意環境。"},{"en":"Writers produce better work in a creative environment that welcomes questions.","zh":"在歡迎提問的創意環境中，作者能創作出更好的作品。"},{"en":"Chris wants a creative environment where feedback is serious but encouraging.","zh":"Chris 想要一個回饋認真但鼓勵人的創意環境。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"writing alone is necessary","meaning":"獨自寫作是必要的","examples":[{"en":"Writing alone is necessary for any poet.","zh":"對任何詩人來說，獨自寫作是必要的。"},{"en":"Writing alone is necessary means private time is needed to think, draft, and revise.","zh":"writing alone is necessary 指需要私人時間去思考、起草和修改。"},{"en":"A musician needs rehearsal alone before performing with others.","zh":"音樂家與他人表演前，需要獨自練習。"},{"en":"Writers need solitude because first thoughts often arrive quietly.","zh":"作者需要獨處，因為最初的想法常常安靜地出現。"},{"en":"Chris agrees that writing alone matters, but he also needs conversation.","zh":"Chris 同意獨自寫作很重要，但他也需要交流。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"become limiting","meaning":"變得有局限","examples":[{"en":"Writing only alone can become limiting.","zh":"只獨自寫作可能會變得有局限。"},{"en":"Become limiting means start to restrict growth, choice, or understanding.","zh":"become limiting 指開始限制成長、選擇或理解。"},{"en":"Studying only from one textbook can become limiting.","zh":"只從一本教科書學習可能會變得有局限。"},{"en":"Writing alone becomes limiting when no one challenges unclear images or weak endings.","zh":"當沒有人挑戰不清楚的意象或薄弱結尾，獨自寫作就會變得有局限。"},{"en":"Chris wants feedback because isolation can make a writer repeat old habits.","zh":"Chris 想得到回饋，因為孤立可能令作者重複舊習慣。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"give me the chance to","meaning":"給我機會去","examples":[{"en":"The workshop would give him the chance to test his poems.","zh":"這個工作坊會給他機會去檢視自己的詩。"},{"en":"Give me the chance to means allow me the opportunity to do something.","zh":"give me the chance to 指給我做某事的機會。"},{"en":"A debate club can give students the chance to practise public speaking.","zh":"辯論學會可以給學生機會去練習公開演說。"},{"en":"A workshop gives writers the chance to see how readers respond.","zh":"工作坊給作者機會去看讀者如何回應。"},{"en":"Chris wants the chance to test his poems beyond private judgement.","zh":"Chris 想有機會在私人判斷以外檢視自己的詩。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"test whether","meaning":"檢視是否","examples":[{"en":"He wants to test whether his images are clear.","zh":"他想檢視自己的意象是否清晰。"},{"en":"Test whether means check if something is true, effective, or working.","zh":"test whether 指檢查某事是否真實、有效或可行。"},{"en":"A teacher may test whether students understand a topic with a short quiz.","zh":"老師可能用小測檢視學生是否理解某個題目。"},{"en":"Writers test whether a poem works by sharing it with careful readers.","zh":"作者透過與細心讀者分享作品，檢視詩是否有效。"},{"en":"Chris wants to test whether his poems communicate clearly.","zh":"Chris 想檢視自己的詩是否能清楚溝通。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"images are clear","meaning":"意象清晰","examples":[{"en":"He wants to know whether his images are clear.","zh":"他想知道自己的意象是否清晰。"},{"en":"Images are clear means the pictures created by words are easy for readers to see or understand.","zh":"images are clear 指文字創造的畫面容易讓讀者看見或理解。"},{"en":"In a poem, images are clear when readers can imagine the street, room, or face.","zh":"在詩中，當讀者能想像街道、房間或面孔，意象就是清晰的。"},{"en":"If images are unclear, readers may feel lost even if the emotion is strong.","zh":"如果意象不清晰，即使情感強烈，讀者也可能感到迷失。"},{"en":"Chris wants feedback so his images become precise rather than vague.","zh":"Chris 想得到回饋，讓自己的意象變得精準而不模糊。"}],"source":"2018 Q8.pdf","sourcePage":6},{"front":"endings are earned","meaning":"結尾自然有力；結尾有其鋪墊","examples":[{"en":"He wants to know whether his endings are earned.","zh":"他想知道自己的結尾是否自然有力。"},{"en":"Endings are earned means the final lines feel natural because the poem has prepared for them.","zh":"endings are earned 指結尾因前文已有鋪墊而顯得自然合理。"},{"en":"A story’s ending is earned when earlier details make it believable.","zh":"當故事前面的細節令結局可信，結尾就是有鋪墊的。"},{"en":"If an ending appears suddenly without support, readers may not trust it.","zh":"如果結尾突然出現而沒有支撐，讀者可能不會相信它。"},{"en":"Chris wants endings that feel necessary, not decorative or forced.","zh":"Chris 想要必要而自然的結尾，而不是裝飾性或牽強的結尾。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"invite readers in","meaning":"邀請讀者走進作品","examples":[{"en":"He hopes his poems invite readers in.","zh":"他希望自己的詩能邀請讀者走進作品。"},{"en":"Invite readers in means make readers feel welcome and able to enter the poem’s world.","zh":"invite readers in 指令讀者感到被歡迎，能進入詩的世界。"},{"en":"Clear images can invite readers in by giving them something to see.","zh":"清晰意象可以透過給讀者可看的東西，邀請他們走進作品。"},{"en":"A poem may fail to invite readers in if it hides behind private symbols.","zh":"如果一首詩躲在私人象徵背後，可能無法邀請讀者走進去。"},{"en":"Chris wants his poems to share experience, not shut readers out.","zh":"Chris 希望自己的詩分享經驗，而不是把讀者拒於門外。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"rather than merely display","meaning":"而不只是展示","examples":[{"en":"He wants his poems to invite readers in rather than merely display private feelings.","zh":"他希望自己的詩邀請讀者走進作品，而不只是展示私人感受。"},{"en":"Rather than merely display means instead of only showing something without deeper communication.","zh":"rather than merely display 指不是只展示某事，而沒有更深入溝通。"},{"en":"A speech should persuade the audience rather than merely display clever words.","zh":"演講應說服聽眾，而不只是展示巧妙字句。"},{"en":"Poems should create connection rather than merely display the writer’s emotions.","zh":"詩應創造連繫，而不只是展示作者的情緒。"},{"en":"Chris wants his work to reach readers, not simply show his inner life.","zh":"Chris 希望作品能觸及讀者，而不只是展示自己的內心生活。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"private feelings","meaning":"私人感受","examples":[{"en":"His poems should not merely display private feelings.","zh":"他的詩不應只是展示私人感受。"},{"en":"Private feelings are personal emotions that may not yet be shared or understood by others.","zh":"private feelings 指個人的情緒，可能尚未被他人分享或理解。"},{"en":"A diary often records private feelings about family, friendship, or fear.","zh":"日記常記錄關於家庭、友情或恐懼的私人感受。"},{"en":"Poetry can begin with private feelings but must shape them for readers.","zh":"詩可以由私人感受開始，但必須把它們塑造成讀者能進入的作品。"},{"en":"Chris wants to turn private feelings into poems that communicate.","zh":"Chris 想把私人感受變成能溝通的詩。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"guest poets from around the world","meaning":"來自世界各地的客席詩人","examples":[{"en":"He hopes to discuss his work with guest poets from around the world.","zh":"他希望與來自世界各地的客席詩人討論自己的作品。"},{"en":"Guest poets from around the world are visiting poets who come from different countries or cultures.","zh":"guest poets from around the world 指來自不同國家或文化的到訪詩人。"},{"en":"Guest poets may share new forms, traditions, and ways of reading.","zh":"客席詩人可能分享新的形式、傳統和閱讀方式。"},{"en":"Discussing work with international poets can reveal assumptions a local reader may miss.","zh":"與國際詩人討論作品，可以揭示本地讀者可能忽略的假設。"},{"en":"Chris hopes guest poets will challenge his view of poetry.","zh":"Chris 希望客席詩人挑戰他對詩歌的看法。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"broaden my understanding of","meaning":"擴闊我對……的理解","examples":[{"en":"The workshop would broaden his understanding of poetry.","zh":"這個工作坊會擴闊他對詩歌的理解。"},{"en":"Broaden my understanding of means make my knowledge or view of something wider and deeper.","zh":"broaden my understanding of 指令我對某事的知識或看法更廣更深。"},{"en":"Travelling can broaden a student’s understanding of different ways of life.","zh":"旅遊可以擴闊學生對不同生活方式的理解。"},{"en":"Workshops broaden understanding when participants meet ideas beyond their usual circle.","zh":"當參加者接觸平常圈子以外的想法，工作坊就能擴闊理解。"},{"en":"Chris hopes the programme will broaden his understanding of what poetry can do.","zh":"Chris 希望課程能擴闊他對詩歌能做甚麼的理解。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"what poetry can be","meaning":"詩可以是甚麼","examples":[{"en":"He wants to broaden his understanding of what poetry can be.","zh":"他想擴闊自己對詩可以是甚麼的理解。"},{"en":"What poetry can be means the possible forms, purposes, and voices poetry may have.","zh":"what poetry can be 指詩可能具有的形式、目的和聲音。"},{"en":"Poetry can be a protest, a memory, a prayer, or a quiet observation.","zh":"詩可以是抗議、記憶、祈禱，或安靜的觀察。"},{"en":"Meeting different poets can show that poetry does not have only one shape.","zh":"認識不同詩人可以顯示詩不只有一種模樣。"},{"en":"Chris wants to discover versions of poetry beyond his own habits.","zh":"Chris 想發現自己習慣以外的詩歌可能性。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"from another culture","meaning":"來自另一種文化","examples":[{"en":"A poet from another culture may notice hidden assumptions.","zh":"來自另一種文化的詩人可能會留意到隱藏的假設。"},{"en":"From another culture means coming from a different set of customs, language, values, or experiences.","zh":"from another culture 指來自不同的習俗、語言、價值觀或經驗。"},{"en":"A reader from another culture may understand a family poem differently.","zh":"來自另一種文化的讀者，可能會以不同方式理解一首家庭詩。"},{"en":"People from another culture can help writers see what they take for granted.","zh":"來自另一種文化的人可以幫助作者看見自己視為理所當然的事。"},{"en":"Chris welcomes this because poetry grows through difference as well as similarity.","zh":"Chris 歡迎這一點，因為詩歌透過差異和相似而成長。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"notice assumptions hidden in my lines","meaning":"留意到我詩句中隱藏的假設","examples":[{"en":"A poet from another culture may notice assumptions hidden in his lines.","zh":"來自另一種文化的詩人可能會留意到他詩句中隱藏的假設。"},{"en":"To notice assumptions hidden in my lines means to see beliefs inside the writing that the writer may not realise.","zh":"notice assumptions hidden in my lines 指看見作品中作者自己可能未察覺的信念。"},{"en":"A reader may notice assumptions about family roles in a poem.","zh":"讀者可能留意到詩中關於家庭角色的假設。"},{"en":"Hidden assumptions can limit a poem if they remain unexamined.","zh":"如果隱藏假設未被檢視，它們可能限制一首詩。"},{"en":"Chris wants other poets to help him see what his own lines silently carry.","zh":"Chris 希望其他詩人幫他看見自己詩句中默默承載的東西。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"challenge my rhythm","meaning":"挑戰我的節奏","examples":[{"en":"Another poet may challenge his rhythm.","zh":"另一位詩人可能會挑戰他的節奏。"},{"en":"Challenge my rhythm means question or push me to rethink the sound and movement of my lines.","zh":"challenge my rhythm 指質疑或推動我重新思考詩句的聲音和流動。"},{"en":"A teacher may challenge a student’s rhythm if every line sounds the same.","zh":"如果每一行都聽起來一樣，老師可能會挑戰學生的節奏。"},{"en":"Challenging rhythm can make a poem less flat and more alive.","zh":"挑戰節奏可以令詩不那麼平板，而變得更有生命力。"},{"en":"Chris welcomes poets who help him hear his own work differently.","zh":"Chris 歡迎能幫他以不同方式聆聽自己作品的詩人。"}],"source":"2018 Q8.pdf","sourcePage":7},{"front":"challenge my diction","meaning":"挑戰我的用字","examples":[{"en":"Another poet may challenge his diction.","zh":"另一位詩人可能會挑戰他的用字。"},{"en":"Challenge my diction means question my word choices and push me to choose more carefully.","zh":"challenge my diction 指質疑我的選字，推動我更仔細地選擇。"},{"en":"A tutor may challenge a writer’s diction when a word sounds too vague.","zh":"當某個字太模糊，導師可能會挑戰作者的用字。"},{"en":"Strong diction can make a poem more exact and memorable.","zh":"有力的用字可以令一首詩更準確、更令人記得。"},{"en":"Chris wants feedback that tests not only ideas but also every word.","zh":"Chris 想要的不只是檢視想法，還有檢視每個字的回饋。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"what a poem should look like","meaning":"一首詩應該是甚麼模樣","examples":[{"en":"The workshop may challenge his idea of what a poem should look like.","zh":"工作坊可能會挑戰他對一首詩應該是甚麼模樣的想法。"},{"en":"What a poem should look like means someone’s belief about a poem’s form, shape, or style.","zh":"what a poem should look like 指一個人對詩的形式、外觀或風格的看法。"},{"en":"Some people think a poem should look like short lines, but poetry can take many forms.","zh":"有些人認為詩應該是一行行短句，但詩可以有許多形式。"},{"en":"A workshop can challenge fixed ideas by showing experimental poems.","zh":"工作坊可以透過展示實驗詩，挑戰固定想法。"},{"en":"Chris is ready to question his idea of what poetry should be.","zh":"Chris 準備好質疑自己對詩歌應有模樣的看法。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"such criticism","meaning":"這樣的批評","examples":[{"en":"Such criticism would not discourage him.","zh":"這樣的批評不會令他氣餒。"},{"en":"Such criticism means this kind of careful judgement, advice, or challenge.","zh":"such criticism 指這種仔細的判斷、建議或挑戰。"},{"en":"Such criticism can help a writer see weaknesses without giving up.","zh":"這樣的批評可以幫助作者看見弱點，而不放棄。"},{"en":"If criticism is honest and respectful, it can become useful rather than cruel.","zh":"如果批評誠實而尊重人，它可以變得有用，而不是殘酷。"},{"en":"Chris sees such criticism as a path to stronger writing.","zh":"Chris 把這樣的批評視為通往更強寫作的道路。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"discourage me","meaning":"令我氣餒","examples":[{"en":"Criticism would not discourage him.","zh":"批評不會令他氣餒。"},{"en":"Discourage me means make me lose confidence, hope, or willingness to continue.","zh":"discourage me 指令我失去信心、希望或繼續下去的意願。"},{"en":"A low mark may discourage a student if no useful advice is given.","zh":"如果沒有有用建議，低分可能令學生氣餒。"},{"en":"Good feedback challenges writers without discouraging them.","zh":"好回饋會挑戰作者，而不會令他們氣餒。"},{"en":"Chris believes criticism will encourage growth rather than discourage him.","zh":"Chris 相信批評會鼓勵成長，而不是令他氣餒。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"make me a more careful and courageous writer","meaning":"令我成為更細心、更勇敢的作家","examples":[{"en":"Criticism would make him a more careful and courageous writer.","zh":"批評會令他成為更細心、更勇敢的作家。"},{"en":"Make me a more careful and courageous writer means help me write with greater precision and bravery.","zh":"make me a more careful and courageous writer 指幫助我以更精準和更勇敢的方式寫作。"},{"en":"Honest feedback can make a student a more careful writer by showing unclear parts.","zh":"誠實回饋可以透過指出不清楚的部分，令學生成為更細心的作者。"},{"en":"Courage grows when writers learn to revise difficult subjects instead of avoiding them.","zh":"當作者學會修改困難題材而不是避開它們，勇氣就會增長。"},{"en":"Chris wants criticism that makes him both more exact and more willing to risk.","zh":"Chris 想要令他更準確也更願意冒險的批評。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"beyond my usual circle","meaning":"在我平常圈子以外","examples":[{"en":"He wants to listen to readers beyond his usual circle.","zh":"他想聆聽來自平常圈子以外的讀者。"},{"en":"Beyond my usual circle means outside the people I normally know, meet, or share work with.","zh":"beyond my usual circle 指在我平常認識、見面或分享作品的人以外。"},{"en":"A student learns more when she receives feedback beyond her usual circle of friends.","zh":"當學生從朋友圈以外得到回饋，她會學到更多。"},{"en":"Readers beyond one’s usual circle may notice what familiar readers miss.","zh":"平常圈子以外的讀者可能會留意到熟悉讀者忽略的東西。"},{"en":"Chris hopes new readers will test whether his voice can travel further.","zh":"Chris 希望新讀者能檢視他的聲音是否能走得更遠。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"genuinely communicative","meaning":"真正能與人溝通的","examples":[{"en":"He wants to know whether his voice is genuinely communicative.","zh":"他想知道自己的聲音是否真正能與人溝通。"},{"en":"Genuinely communicative means truly able to connect with and be understood by others.","zh":"genuinely communicative 指真正能連繫他人並被他人理解。"},{"en":"A poem is genuinely communicative when readers feel invited rather than confused.","zh":"當讀者感到被邀請而不是困惑，一首詩就是真正能溝通的。"},{"en":"Writing can be beautiful but not communicative if nobody understands its movement.","zh":"寫作可以很美，但如果沒有人理解它的走向，就未必能溝通。"},{"en":"Chris wants his voice to reach readers, not remain locked inside himself.","zh":"Chris 希望自己的聲音能觸及讀者，而不是鎖在自己心裏。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"a suitable participant","meaning":"合適的參加者","examples":[{"en":"He believes he would be a suitable participant.","zh":"他相信自己會是一名合適的參加者。"},{"en":"A suitable participant is someone who fits the aims, expectations, and spirit of a programme.","zh":"a suitable participant 指符合課程目標、期望和精神的人。"},{"en":"A suitable participant for a workshop listens carefully and takes feedback seriously.","zh":"工作坊的合適參加者會細心聆聽並認真看待回饋。"},{"en":"Committees choose suitable participants who can both learn and contribute.","zh":"委員會會選擇既能學習又能貢獻的合適參加者。"},{"en":"Chris believes he is suitable because he brings discipline, openness, and respect.","zh":"Chris 相信自己合適，因為他帶來紀律、開放和尊重。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"take creativity and responsibility seriously","meaning":"認真看待創意和責任","examples":[{"en":"He takes both creativity and responsibility seriously.","zh":"他認真看待創意和責任。"},{"en":"To take creativity and responsibility seriously means to value imagination while also behaving carefully and reliably.","zh":"take creativity and responsibility seriously 指重視想像力，同時謹慎可靠地行事。"},{"en":"A student takes creativity seriously by trying new ideas and responsibility seriously by meeting deadlines.","zh":"學生透過嘗試新想法來認真看待創意，透過準時完成來認真看待責任。"},{"en":"Art communities need members who create freely but respect others’ work.","zh":"藝術社群需要能自由創作但尊重他人作品的成員。"},{"en":"Chris shows this balance through writing and organising poetry activities.","zh":"Chris 透過寫作和籌辦詩歌活動展現這種平衡。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"helped organise","meaning":"協助籌辦","examples":[{"en":"He helped organise a lunchtime Poetry Wall.","zh":"他協助籌辦午膳時間詩牆。"},{"en":"Helped organise means assisted in planning and running an event or activity.","zh":"helped organise 指協助計劃和執行一項活動。"},{"en":"Students helped organise a charity sale by making posters and arranging tables.","zh":"學生透過製作海報和安排桌子，協助籌辦慈善義賣。"},{"en":"Helping organise an event shows responsibility, teamwork, and initiative.","zh":"協助籌辦活動能顯示責任感、團隊合作和主動性。"},{"en":"Chris helped organise the Poetry Wall to make space for other student voices.","zh":"Chris 協助籌辦詩牆，是為了給其他學生聲音留出空間。"}],"source":"2018 Q8.pdf","sourcePage":8},{"front":"lunchtime Poetry Wall","meaning":"午膳時間詩牆","examples":[{"en":"He helped organise a lunchtime Poetry Wall at school.","zh":"他在學校協助籌辦午膳時間詩牆。"},{"en":"A lunchtime Poetry Wall is a school display where students post poems during lunch time.","zh":"lunchtime Poetry Wall 是學生在午膳時間張貼詩作的校內展示牆。"},{"en":"A lunchtime Poetry Wall can turn an ordinary corridor into a small literary space.","zh":"午膳時間詩牆可以把普通走廊變成小小文學空間。"},{"en":"Students may read the wall between classes and feel less alone.","zh":"學生可能在課堂之間閱讀詩牆，並感到沒那麼孤單。"},{"en":"Chris used the Poetry Wall to show that poetry can belong to many students.","zh":"Chris 透過詩牆顯示詩歌可以屬於許多學生。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"invite students to","meaning":"邀請學生去","examples":[{"en":"He invited students to post short poems anonymously.","zh":"他邀請學生匿名張貼短詩。"},{"en":"Invite students to means ask or encourage students to take part in an activity.","zh":"invite students to 指請學生或鼓勵學生參與某項活動。"},{"en":"The teacher invited students to share one line about their weekend.","zh":"老師邀請學生分享一句關於週末的話。"},{"en":"Inviting students to join can make a school activity feel open and welcoming.","zh":"邀請學生參與，可以令學校活動感覺開放而歡迎人。"},{"en":"Chris invited students to write because some voices need encouragement before they appear.","zh":"Chris 邀請學生寫作，因為有些聲音需要鼓勵才會出現。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"post short poems anonymously","meaning":"匿名張貼短詩","examples":[{"en":"Students posted short poems anonymously on the Poetry Wall.","zh":"學生在詩牆上匿名張貼短詩。"},{"en":"To post short poems anonymously means to put brief poems in public without showing the writer’s name.","zh":"post short poems anonymously 指公開張貼短詩，但不顯示作者姓名。"},{"en":"Anonymous posting can help shy students share honest feelings.","zh":"匿名張貼可以幫助害羞學生分享真實感受。"},{"en":"If names are hidden, students may feel safer writing about exams or family pressure.","zh":"如果名字被隱藏，學生寫考試或家庭壓力時可能會更安全。"},{"en":"The Poetry Wall allowed students to speak without fear of being judged personally.","zh":"詩牆讓學生不用害怕被針對個人評價，也能說話。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"family expectations","meaning":"家庭期望","examples":[{"en":"Students wrote about friendship, exams and family expectations.","zh":"學生寫友情、考試和家庭期望。"},{"en":"Family expectations are hopes or demands that family members place on a person.","zh":"family expectations 指家人對一個人抱有的希望或要求。"},{"en":"A teenager may feel pressure from family expectations about grades or career choices.","zh":"青少年可能因家庭對成績或職業選擇的期望而感到壓力。"},{"en":"Family expectations can motivate students, but they can also make them anxious.","zh":"家庭期望可以激勵學生，但也可能令他們焦慮。"},{"en":"Poetry gave students a way to describe expectations they could not say directly.","zh":"詩歌給學生一種方式，去描述他們無法直接說出的期望。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"contributions were rough","meaning":"投稿較粗糙","examples":[{"en":"Some contributions were rough but sincere.","zh":"有些投稿較粗糙，但很真誠。"},{"en":"Contributions were rough means the submitted pieces were not polished or technically smooth yet.","zh":"contributions were rough 指提交的作品尚未精修，技巧上未夠成熟。"},{"en":"A first draft may be rough but still contain a strong feeling.","zh":"初稿可能較粗糙，但仍包含強烈感受。"},{"en":"Rough writing can improve if writers receive patient feedback.","zh":"如果作者得到耐心回饋，粗糙的寫作可以改善。"},{"en":"Chris respected rough contributions because sincerity mattered more than perfection.","zh":"Chris 尊重較粗糙的投稿，因為真誠比完美更重要。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"contributions were moving","meaning":"投稿令人感動","examples":[{"en":"Some contributions were moving and honest.","zh":"有些投稿令人感動，而且真誠。"},{"en":"Contributions were moving means the submitted pieces touched people emotionally.","zh":"contributions were moving 指提交的作品在情感上打動人。"},{"en":"A simple poem about missing a grandparent can be moving.","zh":"一首關於思念祖父母的簡單詩可以令人感動。"},{"en":"Writing becomes moving when readers feel the truth behind the words.","zh":"當讀者感受到文字背後的真實，寫作就會令人感動。"},{"en":"The Poetry Wall showed Chris that young people can write with real emotional power.","zh":"詩牆讓 Chris 看見年輕人能寫出真正有情感力量的作品。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"have much to say","meaning":"有很多話想說","examples":[{"en":"Young people have much to say when given a respectful space.","zh":"當年輕人獲得一個受尊重的空間，他們有很多話想說。"},{"en":"Have much to say means have many thoughts, feelings, or experiences worth sharing.","zh":"have much to say 指有許多值得分享的想法、感受或經驗。"},{"en":"Quiet students may have much to say if adults listen patiently.","zh":"如果大人耐心聆聽，安靜的學生可能有很多話想說。"},{"en":"People speak more honestly when they feel their words will be respected.","zh":"當人們感到自己的話會被尊重，他們會更誠實地說話。"},{"en":"Chris learned that young writers often need space more than pressure.","zh":"Chris 明白年輕作者往往需要空間多於壓力。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"given a respectful space","meaning":"獲得一個受尊重的空間","examples":[{"en":"Young people write more honestly when given a respectful space.","zh":"當年輕人獲得一個受尊重的空間，他們會寫得更誠實。"},{"en":"Given a respectful space means being offered a safe environment where people’s words are taken seriously.","zh":"given a respectful space 指獲得一個安全環境，讓人的說話被認真看待。"},{"en":"Students speak more freely when given a respectful space in class.","zh":"當學生在課堂上獲得受尊重的空間，他們會更自由地說話。"},{"en":"A respectful space reduces fear of being laughed at or dismissed.","zh":"受尊重的空間能減少被嘲笑或忽視的恐懼。"},{"en":"Chris wants poetry to create respectful spaces for uncertain voices.","zh":"Chris 希望詩歌為不確定的聲音創造受尊重的空間。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"this experience taught me that","meaning":"這次經歷讓我明白","examples":[{"en":"This experience taught him that poetry can make room for shy people.","zh":"這次經歷讓他明白，詩歌可以為害羞的人騰出空間。"},{"en":"This experience taught me that means I learned an important lesson from what happened.","zh":"this experience taught me that 指我從發生的事中學到重要一課。"},{"en":"This experience taught me that teamwork needs listening, not just ideas.","zh":"這次經歷讓我明白，團隊合作需要聆聽，而不只是想法。"},{"en":"Writers use this phrase to connect a personal event to a larger lesson.","zh":"作者用這個片語把個人事件連接到更大的教訓。"},{"en":"Chris uses the Poetry Wall experience to explain his belief in poetry’s social value.","zh":"Chris 用詩牆經歷來解釋他對詩歌社會價值的信念。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"not an ornament for","meaning":"不是……的裝飾","examples":[{"en":"Poetry is not an ornament for talented individuals alone.","zh":"詩歌不是只有有才華的人才擁有的裝飾。"},{"en":"Not an ornament for means not merely a decoration used by or belonging to a certain group.","zh":"not an ornament for 指不只是某群人使用或擁有的裝飾品。"},{"en":"Education is not an ornament for rich families; it should serve everyone.","zh":"教育不是富裕家庭的裝飾；它應該服務所有人。"},{"en":"If poetry is treated only as decoration, its power to help people speak is ignored.","zh":"如果詩只被視為裝飾，它幫助人發聲的力量就會被忽略。"},{"en":"Chris believes poetry should be useful, open, and shared.","zh":"Chris 相信詩歌應該有用、開放並能被分享。"}],"source":"2018 Q8.pdf","sourcePage":9},{"front":"talented individuals alone","meaning":"只有有才華的人","examples":[{"en":"Poetry should not belong only to talented individuals alone.","zh":"詩歌不應只屬於有才華的人。"},{"en":"Talented individuals alone means only people who are naturally gifted, excluding everyone else.","zh":"talented individuals alone 指只有天生有才能的人，而排除其他人。"},{"en":"Music classes should not be for talented individuals alone; beginners also need space.","zh":"音樂課不應只給有才華的人；初學者也需要空間。"},{"en":"If art belongs only to talented individuals, many shy people never try.","zh":"如果藝術只屬於有才華的人，許多害羞的人永遠不會嘗試。"},{"en":"Chris believes poetry can welcome ordinary students as well as gifted writers.","zh":"Chris 相信詩歌可以歡迎普通學生，也歡迎有天份的作者。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"make room for","meaning":"為……騰出空間","examples":[{"en":"Poetry can make room for those who are unsure how to begin.","zh":"詩歌可以為不知道如何開始的人騰出空間。"},{"en":"Make room for means create space, opportunity, or acceptance for someone or something.","zh":"make room for 指為某人或某事創造空間、機會或接納。"},{"en":"A good classroom makes room for quiet students to speak.","zh":"好課室會為安靜的學生騰出說話空間。"},{"en":"Communities become kinder when they make room for different voices.","zh":"當社區為不同聲音騰出空間，它就會變得更友善。"},{"en":"Chris wants poetry to make room for students who feel shy or overwhelmed.","zh":"Chris 希望詩歌為害羞或壓力大的學生騰出空間。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"shy, overwhelmed or unsure","meaning":"害羞、壓力大或不確定的","examples":[{"en":"Poetry can support people who are shy, overwhelmed or unsure.","zh":"詩歌可以支持害羞、壓力大或不確定的人。"},{"en":"Shy, overwhelmed or unsure describes people who are timid, under too much pressure, or uncertain what to do.","zh":"shy, overwhelmed or unsure 形容害羞、承受太大壓力或不知道該怎樣做的人。"},{"en":"A shy student may need encouragement before sharing a poem.","zh":"害羞的學生可能需要鼓勵才會分享詩作。"},{"en":"Someone overwhelmed by exams may use writing to slow down and breathe.","zh":"被考試壓得喘不過氣的人，可能用寫作讓自己慢下來呼吸。"},{"en":"Chris believes poetry can help people who do not yet know how to speak.","zh":"Chris 相信詩歌能幫助那些尚未知道如何發聲的人。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"unsure how to begin","meaning":"不知道如何開始","examples":[{"en":"Some students were unsure how to begin writing.","zh":"有些學生不知道如何開始寫作。"},{"en":"Unsure how to begin means not knowing what first step to take.","zh":"unsure how to begin 指不知道第一步該怎樣做。"},{"en":"A student may be unsure how to begin an essay until the teacher gives examples.","zh":"學生可能不知道如何開始寫作文，直到老師提供例子。"},{"en":"People often avoid creative work when they are unsure how to begin.","zh":"當人們不知道如何開始，他們常會避開創作。"},{"en":"Poetry activities can help beginners start with one honest line.","zh":"詩歌活動可以幫助初學者從一句真誠的話開始。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"if selected","meaning":"如獲選","examples":[{"en":"If selected, he would bring openness to the workshop.","zh":"如獲選，他會把開放態度帶到工作坊。"},{"en":"If selected means if he is chosen for the programme or scholarship.","zh":"if selected 指如果他被選中參加課程或獲得獎學金。"},{"en":"If selected for the team, she will attend training every Friday.","zh":"如獲選加入校隊，她每星期五會參加訓練。"},{"en":"Applicants use if selected to explain what they will do after being chosen.","zh":"申請人使用 if selected 來解釋獲選後會做甚麼。"},{"en":"Chris uses this phrase to show he has thought about his responsibilities.","zh":"Chris 用這個片語顯示他已思考自己的責任。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"bring this spirit of openness","meaning":"帶着這種開放精神","examples":[{"en":"He would bring this spirit of openness to the workshop.","zh":"他會帶着這種開放精神參加工作坊。"},{"en":"Bring this spirit of openness means arrive with a willingness to listen, learn, and share honestly.","zh":"bring this spirit of openness 指帶着願意聆聽、學習和誠實分享的態度參與。"},{"en":"A group works better when members bring a spirit of openness to discussion.","zh":"當成員帶着開放精神討論，小組會運作得更好。"},{"en":"Openness helps feedback feel like learning rather than attack.","zh":"開放態度令回饋像學習，而不是攻擊。"},{"en":"Chris would bring openness by reading others’ drafts carefully and respectfully.","zh":"Chris 會透過細心而尊重地閱讀別人的草稿，帶來開放精神。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"read others’ drafts carefully","meaning":"細心閱讀別人的草稿","examples":[{"en":"He would read others’ drafts carefully.","zh":"他會細心閱讀別人的草稿。"},{"en":"Read others’ drafts carefully means examine other writers’ unfinished work with attention and respect.","zh":"read others’ drafts carefully 指專注而尊重地閱讀其他作者未完成的作品。"},{"en":"A good peer reviewer reads others’ drafts carefully before giving advice.","zh":"好的同儕評閱者會先細心閱讀別人的草稿，才給建議。"},{"en":"Careful reading helps writers receive useful feedback instead of quick judgement.","zh":"細心閱讀能幫助作者得到有用回饋，而不是倉促評價。"},{"en":"Chris would read carefully because every draft represents someone’s effort.","zh":"Chris 會細心閱讀，因為每份草稿都代表別人的努力。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"honest but considerate feedback","meaning":"誠實而體貼的回饋","examples":[{"en":"He would offer honest but considerate feedback.","zh":"他會提供誠實而體貼的回饋。"},{"en":"Honest but considerate feedback is advice that tells the truth while respecting the writer’s feelings.","zh":"honest but considerate feedback 指說出真相，同時尊重作者感受的建議。"},{"en":"A teacher gives honest but considerate feedback when she points out weak parts kindly.","zh":"老師親切地指出薄弱部分時，就是給予誠實而體貼的回饋。"},{"en":"Feedback that is honest but considerate helps people improve without feeling attacked.","zh":"誠實而體貼的回饋幫助人進步，而不覺得被攻擊。"},{"en":"Chris wants to help others by being clear, fair, and gentle.","zh":"Chris 想透過清楚、公平和溫和的方式幫助他人。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"take no discussion lightly","meaning":"不會輕視任何討論","examples":[{"en":"He would take no discussion lightly.","zh":"他不會輕視任何討論。"},{"en":"Take no discussion lightly means treat every discussion as important and worth careful attention.","zh":"take no discussion lightly 指把每次討論都視為重要，值得仔細留意。"},{"en":"A responsible team member takes no safety discussion lightly.","zh":"負責任的團隊成員不會輕視任何安全討論。"},{"en":"In a workshop, taking no discussion lightly shows respect for other people’s writing.","zh":"在工作坊中，不輕視任何討論顯示對他人作品的尊重。"},{"en":"Chris would listen seriously because even small comments can help a poem grow.","zh":"Chris 會認真聆聽，因為即使小小評論也能幫助詩成長。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"after the workshop","meaning":"工作坊之後","examples":[{"en":"After the workshop, he hopes to share what he has learnt.","zh":"工作坊之後，他希望分享自己所學到的東西。"},{"en":"After the workshop means when the programme has finished.","zh":"after the workshop 指課程結束之後。"},{"en":"After the workshop, students may revise their poems using the feedback they received.","zh":"工作坊之後，學生可能會根據收到的回饋修改詩作。"},{"en":"Planning what to do after the workshop shows responsibility beyond personal benefit.","zh":"計劃工作坊之後要做甚麼，顯示不只追求個人得益的責任感。"},{"en":"Chris hopes the learning will continue in his school community.","zh":"Chris 希望學習能在他的學校社群中延續。"}],"source":"2018 Q8.pdf","sourcePage":10},{"front":"share what I have learnt","meaning":"分享我所學到的東西","examples":[{"en":"He hopes to share what he has learnt with other students.","zh":"他希望與其他學生分享自己所學到的東西。"},{"en":"Share what I have learnt means pass on new knowledge, skills, or experience to others.","zh":"share what I have learnt 指把新知識、技能或經驗傳給他人。"},{"en":"After a leadership camp, students may share what they have learnt with classmates.","zh":"領袖訓練營後，學生可能與同學分享所學到的東西。"},{"en":"Sharing learning spreads the benefit beyond the person who received the opportunity.","zh":"分享所學能把得益傳到獲得機會的人以外。"},{"en":"Chris wants the scholarship’s value to reach other young writers too.","zh":"Chris 希望這項獎學金的價值也能到達其他年輕作者。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"school-based poetry sharing session","meaning":"校內詩歌分享會","examples":[{"en":"He hopes to run a school-based poetry sharing session.","zh":"他希望舉辦一場校內詩歌分享會。"},{"en":"A school-based poetry sharing session is an event at school where students read or discuss poems.","zh":"school-based poetry sharing session 是在學校舉行、讓學生朗讀或討論詩的活動。"},{"en":"A school-based poetry sharing session can help shy students hear others’ work.","zh":"校內詩歌分享會可以幫助害羞學生聽見其他人的作品。"},{"en":"Such a session spreads workshop learning to students who could not attend.","zh":"這樣的分享會把工作坊學習帶給未能參加的學生。"},{"en":"Chris wants to use the session to build a more open writing culture at school.","zh":"Chris 想用分享會在學校建立更開放的寫作文化。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"the scholarship’s impact","meaning":"獎學金的影響","examples":[{"en":"The scholarship’s impact may extend beyond the applicant.","zh":"獎學金的影響可能延伸至申請人以外。"},{"en":"The scholarship’s impact means the effect or benefit created by the scholarship.","zh":"the scholarship’s impact 指獎學金帶來的效果或益處。"},{"en":"A scholarship’s impact can include confidence, new skills, and opportunities to help others.","zh":"獎學金的影響可以包括信心、新技能和幫助他人的機會。"},{"en":"If the recipient shares learning, the scholarship’s impact reaches a wider community.","zh":"如果獲獎者分享所學，獎學金的影響就會到達更廣的社群。"},{"en":"Chris hopes the scholarship will benefit not only himself but also his schoolmates.","zh":"Chris 希望獎學金不只惠及自己，也惠及同學。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"extend beyond myself","meaning":"延伸至我本人以外","examples":[{"en":"He hopes the scholarship’s impact may extend beyond himself.","zh":"他希望獎學金的影響可以延伸至他本人以外。"},{"en":"Extend beyond myself means reach other people, not only benefit me personally.","zh":"extend beyond myself 指影響到其他人，而不只是讓我個人受益。"},{"en":"A student leader’s training can extend beyond herself if she teaches others.","zh":"如果學生領袖把所學教給他人，她的訓練影響就能延伸至本人以外。"},{"en":"Opportunities become more meaningful when their benefits extend beyond one person.","zh":"當機會的益處能延伸至一個人以外，它就更有意義。"},{"en":"Chris wants his learning to support a wider poetry community.","zh":"Chris 希望自己的學習能支持更廣的詩歌社群。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"needless to say","meaning":"不用說；毋庸置疑","examples":[{"en":"Needless to say, being selected would be a privilege.","zh":"毋庸置疑，獲選將是一份榮幸。"},{"en":"Needless to say means it is obvious or does not need much explanation.","zh":"needless to say 指某事很明顯，不需要多加解釋。"},{"en":"Needless to say, students should arrive on time for an interview.","zh":"不用說，學生面試時應準時到達。"},{"en":"This phrase can introduce something the writer feels is clearly true.","zh":"這個片語可以引出作者認為明顯真實的事。"},{"en":"Chris uses it to show sincere respect for the honour of being chosen.","zh":"Chris 用它來顯示他真誠尊重獲選這份榮譽。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"one of only ten young writers","meaning":"僅有十名年輕作家之一","examples":[{"en":"Being one of only ten young writers selected would be a privilege.","zh":"成為僅有十名獲選年輕作家之一將是一份榮幸。"},{"en":"One of only ten young writers means belonging to a very small group of selected young writers.","zh":"one of only ten young writers 指屬於一小群獲選年輕作家中的其中一人。"},{"en":"A student may feel honoured to be one of only ten young writers invited to a festival.","zh":"學生若成為僅有十名獲邀參加文學節的年輕作家之一，可能會感到榮幸。"},{"en":"Being chosen from a small group suggests strong recognition.","zh":"從小群體中獲選，代表受到高度認可。"},{"en":"Chris understands that such a place would be rare and valuable.","zh":"Chris 明白這樣的名額罕有而寶貴。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"selected would be a privilege","meaning":"獲選將是一份榮幸","examples":[{"en":"Being selected for the scholarship would be a privilege.","zh":"獲選獎學金將是一份榮幸。"},{"en":"Selected would be a privilege means being chosen would be an honour and a special opportunity.","zh":"selected would be a privilege 指被選中是一份榮譽和特別機會。"},{"en":"Being selected to represent the school would be a privilege for any student.","zh":"獲選代表學校，對任何學生來說都是一份榮幸。"},{"en":"Calling selection a privilege shows humility and gratitude.","zh":"把獲選稱為榮幸，顯示謙遜和感激。"},{"en":"Chris sees the scholarship not as something owed to him, but as an honour.","zh":"Chris 並不把獎學金視為理所當然，而是視為榮譽。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"not as a reward for","meaning":"不是作為對……的獎勵","examples":[{"en":"He sees the scholarship not as a reward for what he has written.","zh":"他把獎學金看成不是對自己已寫作品的獎勵。"},{"en":"Not as a reward for means not mainly as a prize given because of past achievement.","zh":"not as a reward for 指不是主要作為對過去成就的獎賞。"},{"en":"A leadership role should be seen not as a reward for popularity but as a duty to serve.","zh":"領袖角色不應被視為對受歡迎的獎勵，而應視為服務的責任。"},{"en":"This phrase shifts the focus from praise to responsibility.","zh":"這個片語把重點由讚賞轉向責任。"},{"en":"Chris does not want the scholarship only as recognition; he wants it as a chance to grow.","zh":"Chris 不只想把獎學金當成認可，而是當成成長機會。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"a responsibility to grow further","meaning":"繼續成長的責任","examples":[{"en":"He sees the scholarship as a responsibility to grow further.","zh":"他把獎學金視為繼續成長的責任。"},{"en":"A responsibility to grow further means a duty to keep improving after receiving support.","zh":"a responsibility to grow further 指得到支援後有責任繼續改進。"},{"en":"A student given a rare opportunity has a responsibility to grow further and share learning.","zh":"獲得難得機會的學生有責任繼續成長並分享所學。"},{"en":"Support becomes meaningful when the receiver uses it seriously.","zh":"當接受者認真使用支援，支援才有意義。"},{"en":"Chris believes being chosen would require effort, not comfort.","zh":"Chris 相信獲選意味着需要努力，而不是安逸。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"ready to revise","meaning":"準備好修改","examples":[{"en":"He is ready to revise his poems.","zh":"他準備好修改自己的詩。"},{"en":"Ready to revise means willing and prepared to change and improve written work.","zh":"ready to revise 指願意並準備好改動和改善作品。"},{"en":"A serious writer is ready to revise even after receiving praise.","zh":"認真的作者即使受到讚賞，也準備好修改。"},{"en":"Revision can be uncomfortable because it asks writers to let go of weak lines.","zh":"修改可能令人不舒服，因為它要求作者放開薄弱的詩句。"},{"en":"Chris is ready to revise because he wants stronger poems, not just finished poems.","zh":"Chris 準備好修改，因為他想要更強的詩，而不只是完成了的詩。"}],"source":"2018 Q8.pdf","sourcePage":11},{"front":"question my own habits","meaning":"質疑自己的習慣","examples":[{"en":"He is ready to question his own habits.","zh":"他準備好質疑自己的習慣。"},{"en":"Question my own habits means examine the ways I usually think, write, or behave.","zh":"question my own habits 指檢視自己平常思考、寫作或行動的方式。"},{"en":"A student may question her study habits if she works hard but still feels confused.","zh":"如果學生努力溫習但仍感困惑，她可能會質疑自己的學習習慣。"},{"en":"Writers grow when they question repeated choices that no longer serve the poem.","zh":"當作者質疑那些不再服務作品的重複選擇，他們就會成長。"},{"en":"Chris is willing to ask whether his familiar methods are limiting him.","zh":"Chris 願意追問自己熟悉的方法是否正在限制他。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"learn from poets whose experiences differ from mine","meaning":"向經歷與我不同的詩人學習","examples":[{"en":"He is ready to learn from poets whose experiences differ from his.","zh":"他準備好向經歷與自己不同的詩人學習。"},{"en":"Learn from poets whose experiences differ from mine means gain insight from writers with different lives, backgrounds, or histories.","zh":"learn from poets whose experiences differ from mine 指向生活、背景或歷史不同的作者學習。"},{"en":"A city poet may learn from a rural poet whose images come from land and seasons.","zh":"城市詩人可能向鄉村詩人學習，因為對方的意象來自土地和季節。"},{"en":"Different experiences can challenge narrow views and make writing more generous.","zh":"不同經歷可以挑戰狹窄看法，令寫作更寬廣。"},{"en":"Chris wants to learn from difference because poetry should not stay inside one life.","zh":"Chris 想向差異學習，因為詩歌不應停留在一種人生之內。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"a small line can carry a large truth","meaning":"小小一行詩能承載巨大的真理","examples":[{"en":"Poetry has taught him that a small line can carry a large truth.","zh":"詩歌教會他，小小一行詩能承載巨大的真理。"},{"en":"A small line can carry a large truth means a brief sentence can express something deep and important.","zh":"a small line can carry a large truth 指簡短句子可以表達深刻而重要的東西。"},{"en":"A child’s simple sentence can carry a large truth about loneliness.","zh":"孩子一句簡單的話，可能承載關於孤獨的巨大真理。"},{"en":"Poetry feels powerful when few words reveal a feeling many people share.","zh":"當少量文字揭示許多人共有的感受，詩就顯得有力。"},{"en":"Chris believes short poetic lines can hold meanings larger than themselves.","zh":"Chris 相信短短詩句能承載比自身更大的意義。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"with your support","meaning":"在你們的支持下","examples":[{"en":"With the committee’s support, he hopes to develop further.","zh":"在委員會的支持下，他希望能進一步發展。"},{"en":"With your support means because of the help, trust, or resources you provide.","zh":"with your support 指因為你們提供的幫助、信任或資源。"},{"en":"With your support, the school club can buy books for younger students.","zh":"在你們的支持下，學校學會可以為年幼學生購買書本。"},{"en":"Support can give a young writer time, guidance, and confidence to continue.","zh":"支持可以給年輕作者時間、指導和繼續下去的信心。"},{"en":"Chris politely asks the committee to help him take the next step.","zh":"Chris 禮貌地請求委員會幫助他踏出下一步。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"how much further my own lines can travel","meaning":"我的詩句能走得多遠","examples":[{"en":"He hopes to discover how much further his own lines can travel.","zh":"他希望發現自己的詩句能走得多遠。"},{"en":"How much further my own lines can travel means how far my poems can develop, reach readers, and gain meaning.","zh":"how much further my own lines can travel 指我的詩能發展多遠、觸及多少讀者並獲得多少意義。"},{"en":"A poem travels further when people outside the writer’s circle understand it.","zh":"當作者圈子以外的人也理解一首詩，它就走得更遠。"},{"en":"Guidance can help a writer’s lines travel beyond private feeling into shared experience.","zh":"指導可以幫助作者的詩句由私人感受走向共同經驗。"},{"en":"Chris wants to know how far his poetry can go with support and revision.","zh":"Chris 想知道在支持和修改下，他的詩能走得多遠。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"thank you for considering my application","meaning":"感謝你考慮我的申請","examples":[{"en":"Thank you very much for considering my application.","zh":"非常感謝你考慮我的申請。"},{"en":"Thank you for considering my application is a polite way to thank someone for reviewing an application.","zh":"thank you for considering my application 是感謝對方審閱申請的禮貌說法。"},{"en":"Students often use this sentence at the end of scholarship letters.","zh":"學生常在獎學金申請信結尾使用這句話。"},{"en":"This phrase shows respect for the reader’s time and decision-making role.","zh":"這個片語顯示對讀者時間和決策角色的尊重。"},{"en":"Chris ends politely because formal applications should close with gratitude.","zh":"Chris 禮貌地結尾，因為正式申請應以感謝作結。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"I look forward to hearing from you","meaning":"期待你的回覆","examples":[{"en":"I look forward to hearing from you.","zh":"我期待你的回覆。"},{"en":"I look forward to hearing from you means I hope to receive your reply soon.","zh":"I look forward to hearing from you 指我希望很快收到你的回覆。"},{"en":"Applicants use this sentence to close letters in a polite and formal way.","zh":"申請人用這句話以禮貌正式的方式結束信件。"},{"en":"This phrase shows interest without sounding impatient.","zh":"這個片語顯示期待，但不會顯得急躁。"},{"en":"Chris uses it to end the letter respectfully and hopefully.","zh":"Chris 用它以尊重和帶希望的方式結束信件。"}],"source":"2018 Q8.pdf","sourcePage":12},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully is a formal closing for an application letter.","zh":"Yours faithfully 是申請信的正式結尾語。"},{"en":"Yours faithfully is used to end a formal letter, especially when the recipient is not named personally.","zh":"Yours faithfully 用於結束正式信件，特別是收信人沒有以姓名稱呼時。"},{"en":"A student may write Yours faithfully before signing a scholarship application letter.","zh":"學生可能在獎學金申請信簽名前寫 Yours faithfully。"},{"en":"Using the correct closing makes a formal letter sound respectful and complete.","zh":"使用正確結尾語，能令正式信件聽起來尊重而完整。"},{"en":"Chris uses Yours faithfully to match the formal tone of his application.","zh":"Chris 使用 Yours faithfully，以配合申請信的正式語氣。"}],"source":"2018 Q8.pdf","sourcePage":12}],"dse/writing/part-b/2018/Q9":[{"front":"left open","meaning":"被留下打開","examples":[{"en":"The cage door was left open one Thursday afternoon.","zh":"某個星期四下午，籠門被留下打開。"},{"en":"If something is left open, nobody closes it after using it.","zh":"如果某物被留下打開，表示有人使用後沒有把它關上。"},{"en":"The classroom window was left open, so rain came in during the night.","zh":"課室窗戶被留下打開，所以晚上雨水飄了進來。"},{"en":"A door left open can create danger if a pet or small child can get out.","zh":"如果門被留下打開，而寵物或小孩可能走出去，就會造成危險。"},{"en":"“Left open” often suggests carelessness, accident, or an unexpected chance.","zh":"“Left open” 常暗示粗心、意外，或一個意想不到的機會。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"when I was young","meaning":"當我年幼時","examples":[{"en":"When I was young, I believed the world ended at the brass bars of my cage.","zh":"當我年幼時，我相信世界止於籠子的黃銅籠條。"},{"en":"“When I was young” refers to an earlier time in a person’s or animal’s childhood.","zh":"“When I was young” 指人或動物童年時較早的一段時間。"},{"en":"When I was young, I thought every city looked like my own neighbourhood.","zh":"當我年幼時，我以為每個城市都像自己的社區一樣。"},{"en":"People often use “when I was young” before explaining an old belief that later changed.","zh":"人們常在解釋後來改變了的舊想法前使用 “when I was young”。"},{"en":"Memories from when I was young can show how limited or innocent my understanding once was.","zh":"當我年幼時的回憶，可以顯示我以前的理解多麼有限或單純。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"the world ended at","meaning":"世界止於……","examples":[{"en":"I believed the world ended at the brass bars of my cage.","zh":"我相信世界止於籠子的黃銅籠條。"},{"en":"“The world ended at” means someone believed nothing important existed beyond a certain boundary.","zh":"“The world ended at” 指某人相信某個界線以外再沒有重要事物存在。"},{"en":"As a child, I thought the world ended at the street where my home was.","zh":"小時候，我以為世界止於我家所在的街道。"},{"en":"Fear can make a person feel that the world ends at the door of their room.","zh":"恐懼可以令人覺得世界止於自己房門之外。"},{"en":"This phrase shows a very limited view of life or space.","zh":"這個說法顯示對生活或空間的理解非常有限。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"brass bars","meaning":"黃銅籠條","examples":[{"en":"The bird believed the world ended at the brass bars of its cage.","zh":"那隻鳥相信世界止於籠子的黃銅籠條。"},{"en":"Brass bars are yellowish metal rods that can form part of a cage, gate, or railing.","zh":"黃銅籠條是帶黃色光澤的金屬條，可構成籠子、閘門或欄杆的一部分。"},{"en":"The old birdcage had brass bars that shone in the afternoon light.","zh":"那個舊鳥籠有黃銅籠條，在午後陽光下閃閃發亮。"},{"en":"Brass bars can look beautiful, but they can still keep a creature trapped.","zh":"黃銅籠條可以看起來很美，但仍然能困住生物。"},{"en":"In this story, the brass bars are both a physical boundary and a symbol of confinement.","zh":"在這個故事中，黃銅籠條既是實際界線，也是囚困的象徵。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"blue water cup","meaning":"藍色水杯","examples":[{"en":"There was a blue water cup inside the cage.","zh":"籠子裏有一個藍色水杯。"},{"en":"A blue water cup is a small blue container used to hold drinking water.","zh":"藍色水杯是用來盛飲用水的小型藍色容器。"},{"en":"The parrot drank from the blue water cup every morning.","zh":"那隻鸚鵡每天早上都從藍色水杯喝水。"},{"en":"A blue water cup inside a cage helps a bird drink without leaving its space.","zh":"籠內的藍色水杯讓鳥不用離開籠子也能喝水。"},{"en":"Small objects such as a blue water cup can make a cage feel familiar.","zh":"藍色水杯這類小物件，可以令籠子感覺熟悉。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"round mirror","meaning":"圓鏡","examples":[{"en":"The bird had a round mirror in its cage.","zh":"那隻鳥的籠子裏有一面圓鏡。"},{"en":"A round mirror is a circular object that reflects an image.","zh":"圓鏡是圓形、能反射影像的物件。"},{"en":"The bird tapped the round mirror as if another bird were inside it.","zh":"那隻鳥啄着圓鏡，好像裏面有另一隻鳥。"},{"en":"A round mirror can entertain a pet bird, but it cannot replace real freedom or company.","zh":"圓鏡可以娛樂寵物鳥，但不能取代真正的自由或陪伴。"},{"en":"In a small cage, a round mirror may make the space feel less lonely.","zh":"在小籠子裏，圓鏡可能令空間沒那麼孤單。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"wooden perch","meaning":"木棲架","examples":[{"en":"Kiwi stood on a wooden perch inside the cage.","zh":"Kiwi 站在籠內的木棲架上。"},{"en":"A wooden perch is a small wooden bar where a bird stands or rests.","zh":"木棲架是鳥兒站立或休息的小木條。"},{"en":"The canary slept on its wooden perch at night.","zh":"那隻金絲雀晚上睡在木棲架上。"},{"en":"A wooden perch gives a bird a place to balance, rest, and watch its surroundings.","zh":"木棲架給鳥兒一個保持平衡、休息和觀察周圍的地方。"},{"en":"Even a comfortable wooden perch is still part of a cage.","zh":"即使木棲架很舒適，它仍然是籠子的一部分。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"school uniform","meaning":"校服","examples":[{"en":"Mina’s school uniform smelled faintly of rain and chalk.","zh":"Mina 的校服隱約有雨水和粉筆的氣味。"},{"en":"A school uniform is the set of clothes students wear to show they belong to a school.","zh":"校服是學生穿着、用來顯示自己屬於某所學校的一套衣服。"},{"en":"His school uniform included a white shirt, dark trousers, and a tie.","zh":"他的校服包括白恤衫、深色長褲和領呔。"},{"en":"A school uniform can make students look similar, but each student still carries their own habits and memories.","zh":"校服可以令學生看起來相似，但每個學生仍有自己的習慣和記憶。"},{"en":"In stories, a school uniform can quickly show that a character is a student.","zh":"在故事中，校服可以很快顯示角色是一名學生。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"smelled faintly of","meaning":"隱約有……的氣味","examples":[{"en":"Her school uniform smelled faintly of rain and chalk.","zh":"她的校服隱約有雨水和粉筆的氣味。"},{"en":"“Smelled faintly of” means had a weak or light smell of something.","zh":"“Smelled faintly of” 指帶有某種微弱或淡淡的氣味。"},{"en":"The old book smelled faintly of dust and paper.","zh":"那本舊書隱約有塵埃和紙張的氣味。"},{"en":"Clothes may smell faintly of smoke after someone sits near a barbecue.","zh":"如果有人坐在燒烤爐附近，衣服可能會隱約有煙味。"},{"en":"This phrase suggests the smell is noticeable but not strong.","zh":"這個說法表示氣味可以察覺，但並不強烈。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"rain and chalk","meaning":"雨水和粉筆的氣味","examples":[{"en":"Mina’s uniform smelled faintly of rain and chalk.","zh":"Mina 的校服隱約有雨水和粉筆的氣味。"},{"en":"Rain and chalk suggest the smell of wet weather mixed with a classroom environment.","zh":"雨水和粉筆的氣味，暗示潮濕天氣與課室環境混在一起的味道。"},{"en":"After sports day, the corridor smelled of rain and chalk from wet uniforms and classroom dust.","zh":"運動會後，走廊因濕校服和課室粉塵而有雨水和粉筆的氣味。"},{"en":"The smell of rain and chalk can remind someone of school days.","zh":"雨水和粉筆的氣味可以令人想起上學日子。"},{"en":"In this sentence, rain and chalk make Mina feel real and familiar.","zh":"在這句中，雨水和粉筆的氣味令 Mina 感覺真實而熟悉。"}],"source":"2018 Q9.pdf","sourcePage":1},{"front":"as if","meaning":"好像；彷彿","examples":[{"en":"She whispered his name as if it were a song.","zh":"她輕聲叫他的名字，好像那是一首歌。"},{"en":"“As if” means in a way that makes something seem true, even if it may not be literally true.","zh":"“As if” 指以某種方式令事情看似真實，即使未必真的如此。"},{"en":"He ran as if he were being chased, though nobody was behind him.","zh":"他跑得好像有人在追他，雖然身後沒有人。"},{"en":"The child held the broken toy as if it were still alive.","zh":"那孩子抱着壞掉的玩具，彷彿它仍然活着。"},{"en":"“As if” helps writers compare actions with imagined situations.","zh":"“As if” 幫助作者把動作與想像情境作比較。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"a song she had invented","meaning":"她創作出來的一首歌","examples":[{"en":"Kiwi’s name sounded like a song Mina had invented.","zh":"Kiwi 的名字聽起來像 Mina 創作出來的一首歌。"},{"en":"A song she had invented is a song she created herself rather than learned from someone else.","zh":"她創作出來的一首歌，是她自己創作而不是向別人學來的歌曲。"},{"en":"The little girl hummed a song she had invented while walking home.","zh":"那小女孩回家時哼着一首自己創作的歌。"},{"en":"Calling a name a song she had invented suggests affection and personal meaning.","zh":"說一個名字像她創作出來的一首歌，暗示當中有感情和個人意義。"},{"en":"Something invented by a child can feel simple, private, and precious.","zh":"小孩創作出來的東西，可以感覺簡單、私密而珍貴。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"sang back","meaning":"唱歌回應","examples":[{"en":"Kiwi sang back because singing felt like freedom.","zh":"Kiwi 唱歌回應，因為唱歌感覺像自由。"},{"en":"To sing back means to answer someone’s voice or song by singing in return.","zh":"“Sing back” 指用歌聲回應某人的聲音或歌聲。"},{"en":"When Mina called his name, the bird sang back from the cage.","zh":"當 Mina 叫他的名字時，那隻鳥在籠裏唱歌回應。"},{"en":"A bird may sing back when it hears a familiar voice or another bird nearby.","zh":"當鳥聽到熟悉的聲音或附近有另一隻鳥時，可能會唱歌回應。"},{"en":"Singing back can show recognition, affection, or a desire to respond.","zh":"唱歌回應可以表示認出對方、表達感情，或想作出回應。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"the one freedom","meaning":"唯一的自由","examples":[{"en":"Singing was the one freedom nobody had thought to lock away.","zh":"唱歌是唯一沒有人想到要鎖起來的自由。"},{"en":"The one freedom means the single freedom that remained when other freedoms were limited.","zh":"“The one freedom” 指在其他自由受限制時仍然保留下來的唯一自由。"},{"en":"In hospital, drawing became the one freedom the patient still controlled.","zh":"在醫院裏，繪畫成為病人仍可控制的唯一自由。"},{"en":"For the caged bird, singing was the one freedom because the bars could not stop sound.","zh":"對籠中鳥來說，唱歌是唯一的自由，因為籠條不能阻止聲音。"},{"en":"This phrase makes the freedom feel rare, precious, and fragile.","zh":"這個說法令那份自由顯得稀有、珍貴而脆弱。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"thought to","meaning":"想到要","examples":[{"en":"Nobody had thought to lock away his singing.","zh":"沒有人想到要鎖起他的歌聲。"},{"en":"“Thought to” means remembered or considered doing something.","zh":"“Thought to” 指記得或考慮去做某件事。"},{"en":"Nobody thought to bring an umbrella, so everyone got wet.","zh":"沒有人想到要帶雨傘，所以大家都淋濕了。"},{"en":"A careful host thinks to prepare water before guests arrive.","zh":"細心的主人會想到要在客人到達前準備水。"},{"en":"This phrase often shows whether someone remembered a small but important action.","zh":"這個說法常顯示某人是否記得一個細小但重要的行動。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"lock away","meaning":"鎖起來","examples":[{"en":"Nobody had thought to lock away his singing.","zh":"沒有人想到要把他的歌聲鎖起來。"},{"en":"To lock something away means to keep it shut inside a place so it cannot be used, seen, or reached.","zh":"“Lock away” 指把某物關在某處，使人不能使用、看見或接觸。"},{"en":"The teacher locked away the chemicals after the science lesson.","zh":"科學課後，老師把化學品鎖起來。"},{"en":"People may try to lock away painful memories, but feelings can return later.","zh":"人們可能嘗試把痛苦回憶鎖起來，但感受之後仍會回來。"},{"en":"In the story, singing cannot be locked away like the bird’s body.","zh":"在故事中，歌聲不能像鳥的身體一樣被鎖起來。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"up until","meaning":"直到……為止","examples":[{"en":"Up until that afternoon, the cage door had always been shut.","zh":"直到那天下午為止，籠門一直都是關上的。"},{"en":"“Up until” means during the whole time before a particular moment.","zh":"“Up until” 指在某個特定時刻之前的整段時間。"},{"en":"Up until last year, I had never travelled outside my city.","zh":"直到去年為止，我從未離開自己的城市旅行。"},{"en":"The shop was quiet up until lunchtime, when many customers suddenly arrived.","zh":"那間店直到午飯時間前都很安靜，之後突然來了很多顧客。"},{"en":"This phrase prepares readers for a change after a long period of sameness.","zh":"這個說法為長時間不變之後的轉變作鋪墊。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"cage door","meaning":"籠門","examples":[{"en":"The cage door had always been shut with a silver hook.","zh":"籠門一直用銀色小鉤扣上。"},{"en":"A cage door is the small door that opens and closes a cage.","zh":"籠門是籠子上可以打開和關上的小門。"},{"en":"The child checked the cage door before leaving the rabbit alone.","zh":"孩子離開兔子前先檢查籠門。"},{"en":"If a cage door is not closed properly, the animal inside may escape.","zh":"如果籠門沒有關好，裏面的動物可能會逃走。"},{"en":"In this story, the cage door becomes the boundary between safety and freedom.","zh":"在這個故事中，籠門成為安全與自由之間的界線。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"had always been shut","meaning":"一直關上","examples":[{"en":"The cage door had always been shut with a small silver hook.","zh":"籠門一直用一個銀色小鉤關上。"},{"en":"“Had always been shut” means it had remained closed every time in the past before a later event.","zh":"“Had always been shut” 表示在較後事件發生前，它過去每次都保持關上。"},{"en":"The garden gate had always been shut until the storm broke the lock.","zh":"花園閘門一直關上，直到暴風雨弄壞了鎖。"},{"en":"A door that had always been shut can feel strange and frightening when it is suddenly open.","zh":"一扇一直關上的門突然打開時，可能令人覺得陌生又害怕。"},{"en":"This phrase shows a long habit or condition that is about to change.","zh":"這個說法顯示一個長久的習慣或狀態即將改變。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"silver hook","meaning":"銀色小鉤","examples":[{"en":"The cage door was usually shut with a small silver hook.","zh":"籠門通常用一個銀色小鉤扣上。"},{"en":"A silver hook is a small metal hook, silver in colour, used to fasten or hang something.","zh":"銀色小鉤是銀色的小金屬鉤，用來扣緊或掛住某物。"},{"en":"The garden gate was held closed by a silver hook.","zh":"花園閘門由一個銀色小鉤扣住。"},{"en":"A small silver hook may look simple, but it can keep a cage securely closed.","zh":"一個小小的銀色鉤看似簡單，卻能把籠門牢牢關住。"},{"en":"In the story, the silver hook represents the ordinary object that controls Kiwi’s movement.","zh":"在故事中，銀色小鉤象徵控制 Kiwi 行動的普通物件。"}],"source":"2018 Q9.pdf","sourcePage":2},{"front":"final and neat","meaning":"乾脆俐落而不可逆轉","examples":[{"en":"The click of the hook sounded final and neat.","zh":"鉤子扣上的聲音聽起來乾脆俐落而不可逆轉。"},{"en":"“Final and neat” means clean, complete, and difficult to change after it happens.","zh":"“Final and neat” 指乾淨、完整，而且發生後很難改變。"},{"en":"The stamp on the form felt final and neat, as if the decision was settled.","zh":"表格上的印章感覺乾脆俐落，好像決定已經定下來。"},{"en":"A door closing with a final and neat sound can make a person feel that escape is impossible.","zh":"門以乾脆而不可逆轉的聲音關上，可能令人覺得無法逃離。"},{"en":"This phrase suggests order, control, and a sense of ending.","zh":"這個說法暗示秩序、控制和一種結束感。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"rushed in","meaning":"匆忙進來","examples":[{"en":"Mina rushed in and changed Kiwi’s water.","zh":"Mina 匆忙進來，替 Kiwi 換水。"},{"en":"To rush in means to enter a place quickly, often because you are busy or worried.","zh":"“Rush in” 指很快地進入某個地方，通常因為忙碌或擔心。"},{"en":"The nurse rushed in when she heard the patient call for help.","zh":"護士聽到病人求助後匆忙進來。"},{"en":"Someone who rushes in may forget small details because they are moving too quickly.","zh":"匆忙進來的人可能因動作太快而忘記小細節。"},{"en":"In the story, Mina rushing in helps explain why she forgets the hook.","zh":"在故事中，Mina 匆忙進來有助解釋她為何忘記扣上鉤子。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"forgot the hook","meaning":"忘記扣上鉤子","examples":[{"en":"Mina forgot the hook and ran out again.","zh":"Mina 忘記扣上鉤子，又跑了出去。"},{"en":"To forget the hook means to fail to fasten the small hook that closes the cage door.","zh":"“Forget the hook” 指忘記扣上用來關住籠門的小鉤。"},{"en":"The child forgot the hook, so the rabbit pushed the cage open.","zh":"那孩子忘記扣上鉤子，所以兔子把籠門推開了。"},{"en":"Forgetting the hook can turn an ordinary moment into a dangerous or important one.","zh":"忘記扣上鉤子可能令普通時刻變成危險或重要的時刻。"},{"en":"In this story, forgetting the hook creates Kiwi’s first real chance to leave.","zh":"在這個故事中，忘記扣上鉤子給 Kiwi 第一次真正離開的機會。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"ran out again","meaning":"又跑出去","examples":[{"en":"Mina changed the water and ran out again.","zh":"Mina 換了水後又跑出去。"},{"en":"To run out again means to leave a place quickly after having just entered it.","zh":"“Run out again” 指剛進入某處後很快又離開。"},{"en":"She ran into the kitchen, picked up her keys, and ran out again.","zh":"她跑進廚房，拿起鑰匙後又跑出去。"},{"en":"A person who runs out again may not notice what they have left behind.","zh":"又急急跑出去的人，可能沒有注意到自己留下了甚麼。"},{"en":"The phrase shows hurry and helps explain Mina’s mistake.","zh":"這個說法顯示匆忙，也幫助解釋 Mina 的錯誤。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"remained open","meaning":"仍然開着","examples":[{"en":"The door remained open.","zh":"那扇門仍然開着。"},{"en":"“Remained open” means the door continued to be open and was not closed.","zh":"“Remained open” 指門繼續保持打開，沒有被關上。"},{"en":"The shop door remained open after closing time by mistake.","zh":"店門在關門時間後因失誤仍然開着。"},{"en":"When the gate remained open, the dog walked into the street.","zh":"當閘門仍然開着時，那隻狗走到街上。"},{"en":"This phrase creates tension because an open door can invite action.","zh":"這個說法製造緊張感，因為開着的門可能引發行動。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"at first","meaning":"起初","examples":[{"en":"At first, nothing happened.","zh":"起初，甚麼都沒有發生。"},{"en":"“At first” means at the beginning of a situation, before anything changes later.","zh":"“At first” 指在情況開始時，之後可能會有變化。"},{"en":"At first, the puppy was afraid to leave the basket.","zh":"起初，小狗不敢離開籃子。"},{"en":"A chance may appear, but at first a person may not know how to react.","zh":"機會出現時，起初人可能不知道如何反應。"},{"en":"This phrase often prepares readers for something important that will happen afterwards.","zh":"這個說法常為之後將會發生的重要事情作鋪墊。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"so still that","meaning":"靜得以致","examples":[{"en":"The room was so still that Kiwi could hear the refrigerator humming.","zh":"房間靜得以致 Kiwi 能聽見雪櫃嗡嗡作響。"},{"en":"“So still that” means extremely quiet or unmoving, with a clear result following it.","zh":"“So still that” 指非常安靜或沒有動靜，並引出明顯結果。"},{"en":"The classroom was so still that everyone heard the clock ticking.","zh":"課室靜得以致每個人都聽見時鐘滴答聲。"},{"en":"A room can be so still that small sounds seem unusually loud.","zh":"房間可以靜得以致細小聲音都顯得特別響。"},{"en":"This structure shows how strong a quality is by showing what it causes.","zh":"這個結構透過顯示結果，表達某種特質有多強烈。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"refrigerator humming","meaning":"雪櫃嗡嗡作響","examples":[{"en":"Kiwi could hear the refrigerator humming.","zh":"Kiwi 能聽見雪櫃嗡嗡作響。"},{"en":"Refrigerator humming is the low continuous sound a fridge makes while it is working.","zh":"雪櫃嗡嗡作響是雪櫃運作時發出的低沉持續聲音。"},{"en":"At midnight, the only sound in the kitchen was the refrigerator humming.","zh":"午夜時，廚房裏唯一的聲音就是雪櫃嗡嗡作響。"},{"en":"Hearing the refrigerator humming can make a quiet room feel even quieter.","zh":"聽到雪櫃嗡嗡作響，可以令安靜的房間顯得更安靜。"},{"en":"This detail helps readers imagine the silence inside the flat.","zh":"這個細節幫助讀者想像單位裏的寂靜。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"traffic breathing below the flat","meaning":"單位下方的車流聲","examples":[{"en":"Kiwi could hear the traffic breathing below the flat.","zh":"Kiwi 能聽見單位下方像呼吸般起伏的車流聲。"},{"en":"Traffic breathing below the flat describes the distant rise and fall of vehicle sounds under an apartment.","zh":"“Traffic breathing below the flat” 描述公寓下方遠處車聲的起伏。"},{"en":"At night, the traffic breathing below the flat made the city feel alive.","zh":"夜裏，單位下方像呼吸般的車流聲令城市感覺有生命。"},{"en":"This phrase compares traffic noise to breathing, making the city seem like a living thing.","zh":"這個說法把車流聲比作呼吸，令城市像一個活物。"},{"en":"It suggests the world outside is moving even while the room is still.","zh":"它暗示即使房間很靜，外面的世界仍在流動。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"below the flat","meaning":"在單位下方","examples":[{"en":"The traffic breathed below the flat.","zh":"車流在單位下方像呼吸般起伏。"},{"en":"“Below the flat” means in the area lower than the apartment.","zh":"“Below the flat” 指在公寓較低的位置或區域。"},{"en":"From the window, she could see shops and buses below the flat.","zh":"她從窗戶看見單位下方的商店和巴士。"},{"en":"Sounds below the flat can travel upward through open windows.","zh":"單位下方的聲音可以透過開着的窗向上傳來。"},{"en":"This phrase helps show that Kiwi is above the busy city.","zh":"這個說法幫助顯示 Kiwi 位於繁忙城市之上。"}],"source":"2018 Q9.pdf","sourcePage":3},{"front":"a thin line of sunlight","meaning":"一線薄薄的陽光","examples":[{"en":"A thin line of sunlight lay across the open doorway.","zh":"一線薄薄的陽光橫落在開着的門口。"},{"en":"A thin line of sunlight is a narrow strip of light from the sun.","zh":"一線薄薄的陽光是太陽光形成的狹長光線。"},{"en":"A thin line of sunlight came through the curtains in the morning.","zh":"早上，一線薄薄的陽光從窗簾縫透進來。"},{"en":"A thin line of sunlight can draw attention to a small opening or path.","zh":"一線薄薄的陽光可以把注意力引向一個小開口或通道。"},{"en":"In the story, the sunlight makes the open door look like an invitation.","zh":"在故事中，陽光令開着的門看起來像一個邀請。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"lay across","meaning":"橫落在……上","examples":[{"en":"Sunlight lay across the open doorway.","zh":"陽光橫落在開着的門口。"},{"en":"“Lay across” means stretched or rested from one side of a surface or space to another.","zh":"“Lay across” 指橫跨或靜靜落在某個表面或空間上。"},{"en":"A scarf lay across the chair after she came home.","zh":"她回家後，圍巾橫放在椅子上。"},{"en":"Morning light lay across the desk, making the papers glow.","zh":"晨光橫落在書桌上，令紙張微微發亮。"},{"en":"This phrase often describes something resting quietly over an area.","zh":"這個說法常描述某物安靜地覆在一個區域上。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"open doorway","meaning":"開着的門口","examples":[{"en":"A thin line of sunlight lay across the open doorway.","zh":"一線薄薄的陽光橫落在開着的門口。"},{"en":"An open doorway is the space of a door that is not closed.","zh":"開着的門口是沒有關上的門所形成的空間。"},{"en":"The cat sat in the open doorway and watched the garden.","zh":"那隻貓坐在開着的門口望着花園。"},{"en":"An open doorway can suggest welcome, danger, or a chance to leave.","zh":"開着的門口可以暗示歡迎、危險，或離開的機會。"},{"en":"For Kiwi, the open doorway is small but full of possibility.","zh":"對 Kiwi 來說，開着的門口雖小，卻充滿可能。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"do justice to","meaning":"充分表達","examples":[{"en":"No words can do justice to how wide that little gap appeared.","zh":"沒有文字能充分表達那個小小空隙看起來有多寬闊。"},{"en":"To do justice to something means to describe or show it well enough to match its real importance or beauty.","zh":"“Do justice to” 指描述或呈現某事時，足以配得上它真正的重要性或美感。"},{"en":"A photo cannot do justice to how beautiful the mountain looked at sunrise.","zh":"一張照片不能充分表達日出時那座山有多美。"},{"en":"A short thank-you message may not do justice to years of help from a friend.","zh":"一句簡短感謝未必能充分表達朋友多年幫助的分量。"},{"en":"This phrase is used when ordinary description feels too weak.","zh":"當普通描述顯得太弱時，人們會使用這個說法。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"little gap","meaning":"小小的空隙","examples":[{"en":"The little gap looked larger than the sky in Kiwi’s dreams.","zh":"那個小小的空隙看起來比 Kiwi 夢中的天空更大。"},{"en":"A little gap is a small opening or space between two things.","zh":"小小的空隙是兩件事物之間細小的開口或空間。"},{"en":"The mouse escaped through a little gap under the door.","zh":"老鼠從門底的小小空隙逃走了。"},{"en":"A little gap may seem unimportant until it becomes the only way out.","zh":"小小的空隙看似不重要，直到它成為唯一出口。"},{"en":"In Kiwi’s eyes, the little gap is tiny in size but huge in meaning.","zh":"在 Kiwi 眼中，那個小小的空隙尺寸很小，但意義巨大。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"not more than","meaning":"不超過","examples":[{"en":"The gap was not more than two inches.","zh":"那個空隙不超過兩英寸。"},{"en":"“Not more than” means no greater than a stated amount.","zh":"“Not more than” 指不大於某個指定數量。"},{"en":"The child was not more than five years old.","zh":"那孩子不超過五歲。"},{"en":"The crack was not more than a centimetre wide, but water still entered.","zh":"那道裂縫不超過一厘米寬，但水仍然滲入。"},{"en":"This phrase emphasises that something is small, limited, or below a maximum.","zh":"這個說法強調某物很小、有限，或低於最高數量。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"looked larger than","meaning":"看起來比……更大","examples":[{"en":"The gap looked larger than the sky in his dreams.","zh":"那個空隙看起來比他夢中的天空更大。"},{"en":"“Looked larger than” means appeared bigger than something else, even if it was not actually bigger.","zh":"“Looked larger than” 指看起來比另一物更大，即使實際未必如此。"},{"en":"In the dark room, the shadow looked larger than the chair that made it.","zh":"在黑暗房間裏，影子看起來比造成它的椅子更大。"},{"en":"Fear can make a small problem look larger than it really is.","zh":"恐懼可以令小問題看起來比實際更大。"},{"en":"This phrase shows perception, not always physical fact.","zh":"這個說法顯示的是感覺，不一定是實際大小。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"in my dreams","meaning":"在我的夢裏","examples":[{"en":"The gap looked larger than the sky in my dreams.","zh":"那個空隙看起來比我夢裏的天空更大。"},{"en":"“In my dreams” means inside the imagined scenes or hopes someone has while sleeping or wishing.","zh":"“In my dreams” 指在睡夢或願望中的想像場景裏。"},{"en":"In my dreams, I could fly over the sea without fear.","zh":"在我的夢裏，我可以毫不害怕地飛越大海。"},{"en":"Something in my dreams may feel larger, brighter, or freer than real life.","zh":"在我的夢裏，事物可能比現實更大、更明亮或更自由。"},{"en":"This phrase can show longing for a world beyond present limits.","zh":"這個說法可以表達對超越現有限制的世界的渴望。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"hopped towards","meaning":"跳向","examples":[{"en":"Kiwi hopped towards the open door.","zh":"Kiwi 跳向開着的門。"},{"en":"To hop towards something means to move in small jumps in its direction.","zh":"“Hop towards” 指朝某個方向小跳着前進。"},{"en":"The rabbit hopped towards the carrot on the floor.","zh":"兔子跳向地上的紅蘿蔔。"},{"en":"A bird may hop towards something new before it is brave enough to fly.","zh":"鳥在有足夠勇氣飛之前，可能會先小心地跳向新事物。"},{"en":"“Hopped towards” suggests cautious movement rather than sudden escape.","zh":"“Hopped towards” 暗示謹慎移動，而不是突然逃走。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"heart beat so violently","meaning":"心跳得非常劇烈","examples":[{"en":"His heart beat so violently that his feathers trembled.","zh":"他的心跳得非常劇烈，以致羽毛也顫抖。"},{"en":"If a heart beats so violently, it beats very hard and fast because of fear, excitement, or shock.","zh":"如果心跳得非常劇烈，表示因恐懼、興奮或震驚而跳得又快又重。"},{"en":"My heart beat so violently before the speech that my hands shook.","zh":"演講前，我的心跳得非常劇烈，手也在發抖。"},{"en":"A sudden chance can make someone’s heart beat violently because they are both afraid and hopeful.","zh":"突然出現的機會可以令人心跳劇烈，因為人同時害怕又充滿希望。"},{"en":"This phrase shows strong emotion through a physical reaction.","zh":"這個說法透過身體反應顯示強烈情緒。"}],"source":"2018 Q9.pdf","sourcePage":4},{"front":"feathers trembled","meaning":"羽毛顫抖","examples":[{"en":"Kiwi’s feathers trembled as his heart beat.","zh":"Kiwi 的心跳着，羽毛也在顫抖。"},{"en":"If feathers trembled, they shook slightly because the bird was frightened, excited, or cold.","zh":"如果羽毛顫抖，表示鳥因害怕、興奮或寒冷而微微發抖。"},{"en":"The small bird’s feathers trembled when thunder shook the window.","zh":"雷聲震動窗戶時，小鳥的羽毛顫抖起來。"},{"en":"Trembling feathers can show fear without the writer directly saying the bird is afraid.","zh":"羽毛顫抖可以顯示恐懼，而不用作者直接說鳥很害怕。"},{"en":"This detail makes Kiwi’s nervousness visible.","zh":"這個細節令 Kiwi 的緊張變得可見。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"for once in my life","meaning":"生平第一次","examples":[{"en":"For once in his life, the bars were not stopping him.","zh":"生平第一次，籠條沒有阻止他。"},{"en":"“For once in my life” means for the first unusual time in a person’s or creature’s experience.","zh":"“For once in my life” 指在人或生物的經歷中，第一次出現某種不尋常情況。"},{"en":"For once in my life, I answered the question without feeling afraid.","zh":"生平第一次，我回答問題時沒有感到害怕。"},{"en":"This phrase is used when something rare finally happens.","zh":"當罕見的事情終於發生時，會使用這個說法。"},{"en":"It often carries surprise, relief, or deep emotion.","zh":"它通常帶有驚訝、釋然或深刻情感。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"the bars were not stopping me","meaning":"籠條沒有阻止我","examples":[{"en":"For once, the bars were not stopping Kiwi.","zh":"這一次，籠條沒有阻止 Kiwi。"},{"en":"“The bars were not stopping me” means the physical barrier was no longer preventing escape or movement.","zh":"“The bars were not stopping me” 指實際的障礙不再阻止逃離或移動。"},{"en":"The gate was open, so the fence was not stopping the dog anymore.","zh":"閘門開了，所以圍欄不再阻止那隻狗。"},{"en":"Sometimes the outside barrier disappears, but fear still stops the person inside.","zh":"有時外在障礙消失了，但內心恐懼仍會阻止人。"},{"en":"This phrase prepares the contrast between outside limits and inner fear.","zh":"這個說法為外在限制與內心恐懼的對比作鋪墊。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"I was stopping myself","meaning":"是我在阻止自己","examples":[{"en":"The problem was that Kiwi was stopping himself.","zh":"問題是 Kiwi 自己在阻止自己。"},{"en":"“I was stopping myself” means my own fear, doubt, or habit prevented me from acting.","zh":"“I was stopping myself” 指自己的恐懼、懷疑或習慣阻止自己行動。"},{"en":"The door was open, but I was stopping myself because I feared failure.","zh":"門已經開了，但我因害怕失敗而阻止自己。"},{"en":"People may stop themselves even when others are no longer blocking them.","zh":"即使別人不再阻止，人仍可能自己阻止自己。"},{"en":"This phrase shows that the real barrier can be inside the mind.","zh":"這個說法顯示真正的障礙可能在心裏。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"beyond the cage","meaning":"籠子之外","examples":[{"en":"Beyond the cage stood Mina’s desk.","zh":"籠子之外是 Mina 的書桌。"},{"en":"Beyond the cage means outside or past the cage.","zh":"“Beyond the cage” 指在籠子外面或越過籠子的地方。"},{"en":"Beyond the classroom window, children were playing in the playground.","zh":"課室窗外，孩子們正在操場玩耍。"},{"en":"For a caged bird, everything beyond the cage may feel unknown and exciting.","zh":"對籠中鳥來說，籠子之外的一切都可能既陌生又令人興奮。"},{"en":"This phrase points to the world outside Kiwi’s usual limits.","zh":"這個說法指向 Kiwi 平常限制之外的世界。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"crowded with textbooks","meaning":"堆滿教科書","examples":[{"en":"Mina’s desk was crowded with textbooks.","zh":"Mina 的書桌堆滿教科書。"},{"en":"If a place is crowded with textbooks, many textbooks fill it and leave little empty space.","zh":"如果某處堆滿教科書，表示許多教科書填滿那裏，留下很少空位。"},{"en":"Before exams, my desk was crowded with textbooks and notes.","zh":"考試前，我的書桌堆滿教科書和筆記。"},{"en":"A desk crowded with textbooks suggests study, pressure, and a busy student life.","zh":"堆滿教科書的書桌暗示學習、壓力和忙碌的學生生活。"},{"en":"This phrase helps readers imagine Mina’s everyday world.","zh":"這個說法幫助讀者想像 Mina 的日常世界。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"moving without permission","meaning":"未經允許地移動","examples":[{"en":"Beyond the window were clouds moving without permission.","zh":"窗外有雲在未經允許地移動。"},{"en":"“Moving without permission” means moving freely without needing anyone’s approval.","zh":"“Moving without permission” 指自由移動，不需要任何人批准。"},{"en":"The stray cat crossed the garden as if moving without permission.","zh":"那隻流浪貓穿過花園，像是未經允許地自由走動。"},{"en":"To a caged bird, clouds moving without permission may look wonderfully free.","zh":"對籠中鳥來說，未經允許地移動的雲可能看起來非常自由。"},{"en":"This phrase contrasts the free outside world with Kiwi’s controlled life.","zh":"這個說法把自由的外面世界與 Kiwi 受控制的生活作對比。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"sparrows","meaning":"麻雀","examples":[{"en":"Kiwi had watched sparrows cut through the air.","zh":"Kiwi 曾看着麻雀劃破空氣。"},{"en":"Sparrows are small brown or grey birds often seen near homes, streets, and parks.","zh":"麻雀是常見於住家、街道和公園附近的小型啡色或灰色鳥。"},{"en":"Sparrows gathered near the bakery to look for crumbs.","zh":"麻雀聚在麵包店附近尋找麵包碎。"},{"en":"For a pet bird, wild sparrows can represent freedom and danger at the same time.","zh":"對寵物鳥來說，野生麻雀可以同時代表自由和危險。"},{"en":"Watching sparrows fly may make a caged bird feel both curious and jealous.","zh":"看着麻雀飛翔，可能令籠中鳥既好奇又羨慕。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"cut through the air","meaning":"劃破空氣","examples":[{"en":"Sparrows cut through the air like thrown stones.","zh":"麻雀像被擲出的石頭般劃破空氣。"},{"en":"To cut through the air means to move quickly and sharply through the air.","zh":"“Cut through the air” 指快速而俐落地穿過空氣。"},{"en":"The arrow cut through the air before landing in the target.","zh":"箭劃破空氣，然後射中目標。"},{"en":"Birds cutting through the air look fast, direct, and confident.","zh":"鳥兒劃破空氣時，看起來快速、直接而自信。"},{"en":"This phrase makes flight sound powerful and swift.","zh":"這個說法令飛行聽起來有力量又迅速。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"like thrown stones","meaning":"像被擲出的石頭","examples":[{"en":"The sparrows cut through the air like thrown stones.","zh":"麻雀像被擲出的石頭般劃破空氣。"},{"en":"“Like thrown stones” compares the sparrows’ movement to stones flying fast after being thrown.","zh":"“Like thrown stones” 把麻雀的動作比作被擲出後快速飛行的石頭。"},{"en":"The boys’ paper planes shot across the classroom like thrown stones.","zh":"男孩們的紙飛機像被擲出的石頭般飛過課室。"},{"en":"This comparison makes the sparrows seem fast, hard, and fearless.","zh":"這個比喻令麻雀顯得快速、堅決而無懼。"},{"en":"Similes like this help readers imagine movement more clearly.","zh":"這類比喻幫助讀者更清楚想像動作。"}],"source":"2018 Q9.pdf","sourcePage":5},{"front":"hated, admired and envied","meaning":"憎恨、欣賞並羨慕","examples":[{"en":"Kiwi had hated, admired and envied the sparrows.","zh":"Kiwi 曾憎恨、欣賞並羨慕那些麻雀。"},{"en":"“Hated, admired and envied” means feeling anger, respect, and jealousy at the same time.","zh":"“Hated, admired and envied” 指同時感到憤怒、敬佩和嫉妒。"},{"en":"She hated, admired and envied her rival because he was arrogant but talented.","zh":"她憎恨、欣賞並羨慕那位對手，因為他傲慢但有才華。"},{"en":"Mixed feelings can happen when someone has the freedom or ability we want.","zh":"當別人擁有我們想要的自由或能力時，混雜的感受可能會出現。"},{"en":"This phrase shows that Kiwi’s feelings towards the sparrows are complicated.","zh":"這個說法顯示 Kiwi 對麻雀的感情很複雜。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"became one","meaning":"合而為一","examples":[{"en":"All three feelings became one.","zh":"三種感覺合而為一。"},{"en":"“Became one” means separate feelings or things joined together into a single experience.","zh":"“Became one” 指分開的感受或事物融合成單一經驗。"},{"en":"Fear, excitement, and hope became one as I walked onto the stage.","zh":"當我走上舞台時，恐懼、興奮和希望合而為一。"},{"en":"Strong emotions can become one when a person faces an important moment.","zh":"當人面對重要時刻，強烈情緒可能會合而為一。"},{"en":"This phrase shows that Kiwi can no longer separate his different feelings.","zh":"這個說法顯示 Kiwi 已不能再分清不同感受。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"the instant","meaning":"一……就","examples":[{"en":"The instant Kiwi pushed the door, it swung open.","zh":"Kiwi 一推門，門就猛地打開。"},{"en":"“The instant” means immediately when something happens.","zh":"“The instant” 指某事一發生便立即。"},{"en":"The instant the bell rang, the students packed their bags.","zh":"鐘聲一響，學生就收拾書包。"},{"en":"This phrase shows that one action and its result happened almost at the same time.","zh":"這個說法顯示一個動作和其結果幾乎同時發生。"},{"en":"It creates a quick, dramatic feeling in a sentence.","zh":"它令句子有快速而戲劇性的感覺。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"pushed the door with my head","meaning":"用頭推門","examples":[{"en":"Kiwi pushed the door with his head.","zh":"Kiwi 用頭推門。"},{"en":"To push the door with my head means to use my head, not my hands, to move the door open.","zh":"“Push the door with my head” 指用頭而不是用手把門推開。"},{"en":"The puppy pushed the door with its head because its paws could not pull the handle.","zh":"小狗用頭推門，因為牠的爪子不能拉門把。"},{"en":"A bird might push a door with its head when trying to escape a cage.","zh":"鳥想逃出籠子時，可能會用頭推門。"},{"en":"This action shows effort, curiosity, and uncertainty.","zh":"這個動作顯示努力、好奇和不確定。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"swung open","meaning":"猛地打開","examples":[{"en":"The cage door swung open.","zh":"籠門猛地打開。"},{"en":"If a door swung open, it moved open quickly on its hinges.","zh":"如果門 swung open，表示它沿着鉸位快速打開。"},{"en":"The classroom door swung open when the wind blew through the corridor.","zh":"走廊吹來一陣風，課室門猛地打開。"},{"en":"A door that swings open can surprise someone who expected it to stay shut.","zh":"一扇猛地打開的門，可能令原本以為它會關着的人吃驚。"},{"en":"In the story, the door swinging open makes freedom suddenly real.","zh":"在故事中，門猛地打開令自由突然變得真實。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"froze","meaning":"僵住","examples":[{"en":"Kiwi froze when the door opened.","zh":"門打開時，Kiwi 僵住了。"},{"en":"To freeze means to suddenly stop moving because of fear, shock, or surprise.","zh":"“Freeze” 指因恐懼、震驚或驚訝而突然停止動作。"},{"en":"The child froze when he heard a strange sound in the dark room.","zh":"孩子在黑暗房間裏聽到怪聲時僵住了。"},{"en":"People may freeze at an important moment because they do not know what to do next.","zh":"人們在重要時刻可能會僵住，因為不知道下一步該做甚麼。"},{"en":"This verb shows that Kiwi is frightened by the freedom he wanted.","zh":"這個動詞顯示 Kiwi 被自己想要的自由嚇住了。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"silence rushed at me","meaning":"寂靜向我湧來","examples":[{"en":"Silence rushed at Kiwi.","zh":"寂靜向 Kiwi 湧來。"},{"en":"“Silence rushed at me” means the sudden quiet felt powerful and overwhelming, almost like something moving towards me.","zh":"“Silence rushed at me” 指突如其來的安靜感覺強烈而壓倒性，像有東西向我衝來。"},{"en":"When the music stopped, silence rushed at me in the empty hall.","zh":"音樂停止時，寂靜在空禮堂裏向我湧來。"},{"en":"Silence can feel active and frightening when a person expected noise or safety.","zh":"當人原本期待聲音或安全感時，寂靜可能感覺主動而可怕。"},{"en":"This phrase turns silence into a force Kiwi can feel.","zh":"這個說法把寂靜變成 Kiwi 能感受到的一股力量。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"leapt","meaning":"跳起；躍起","examples":[{"en":"Then Kiwi leapt.","zh":"然後 Kiwi 躍起。"},{"en":"To leap means to jump suddenly and strongly.","zh":"“Leap” 指突然用力跳起。"},{"en":"The cat leapt from the chair to the windowsill.","zh":"那隻貓從椅子跳到窗台。"},{"en":"A person may leap when they finally decide to act after hesitating.","zh":"人在猶豫後終於決定行動時，也可能會一躍而起。"},{"en":"In the story, Kiwi’s leap is both a physical jump and a brave decision.","zh":"在故事中，Kiwi 的跳躍既是身體動作，也是勇敢決定。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"for a terrifying second","meaning":"在可怕的一秒間","examples":[{"en":"For a terrifying second, Kiwi fell rather than flew.","zh":"在可怕的一秒間，Kiwi 不是飛起，而是往下跌。"},{"en":"“For a terrifying second” means during one very frightening moment.","zh":"“For a terrifying second” 指在一個非常可怕的短暫時刻裏。"},{"en":"For a terrifying second, I thought the child had run into the road.","zh":"在可怕的一秒間，我以為那孩子跑到馬路上去了。"},{"en":"A terrifying second can feel much longer when danger is possible.","zh":"當危險可能發生時，可怕的一秒可以感覺特別漫長。"},{"en":"This phrase slows the action and lets readers feel Kiwi’s fear.","zh":"這個說法放慢動作，讓讀者感受 Kiwi 的恐懼。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"rather than","meaning":"而不是","examples":[{"en":"For a terrifying second, he fell rather than flew.","zh":"在可怕的一秒間，他往下跌，而不是飛起。"},{"en":"“Rather than” shows that one thing happened instead of another expected thing.","zh":"“Rather than” 表示實際發生的是一件事，而不是原本預期的另一件事。"},{"en":"She listened rather than argued when her friend explained the problem.","zh":"朋友解釋問題時，她選擇聆聽，而不是爭辯。"},{"en":"Kiwi fell rather than flew because his wings were not used to real flight.","zh":"Kiwi 往下跌，而不是飛起，因為他的翅膀不習慣真正飛行。"},{"en":"This phrase makes the contrast between expectation and reality clear.","zh":"這個說法令期望與現實之間的對比更清楚。"}],"source":"2018 Q9.pdf","sourcePage":6},{"front":"unused to decision","meaning":"不習慣作決定","examples":[{"en":"His wings were unused to decision.","zh":"他的翅膀不習慣作決定。"},{"en":"“Unused to decision” means not used to choosing and acting freely.","zh":"“Unused to decision” 指不習慣自行選擇和自由行動。"},{"en":"After years of being told what to do, she felt unused to decision.","zh":"多年來一直被人指示該做甚麼後，她變得不習慣作決定。"},{"en":"Someone unused to decision may hesitate even when they finally have freedom.","zh":"不習慣作決定的人，即使終於得到自由，也可能會猶豫。"},{"en":"This phrase suggests that Kiwi’s body and mind have both been trained by captivity.","zh":"這個說法暗示 Kiwi 的身體和思想都受到囚禁生活訓練。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"beat the air clumsily","meaning":"笨拙地拍打空氣","examples":[{"en":"His wings beat the air clumsily.","zh":"他的翅膀笨拙地拍打空氣。"},{"en":"To beat the air clumsily means to flap wings awkwardly and without smooth control.","zh":"“Beat the air clumsily” 指笨拙而不流暢地拍動翅膀。"},{"en":"The young bird beat the air clumsily during its first flight.","zh":"幼鳥第一次飛行時笨拙地拍打空氣。"},{"en":"A creature that has not practised flying may beat the air clumsily at first.","zh":"沒有練習過飛行的生物，起初可能會笨拙地拍打空氣。"},{"en":"This phrase shows effort mixed with inexperience.","zh":"這個說法顯示努力和缺乏經驗同時存在。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"knocked over","meaning":"撞倒","examples":[{"en":"Kiwi knocked over a pencil holder.","zh":"Kiwi 撞倒了一個筆筒。"},{"en":"To knock something over means to hit it so that it falls from an upright position.","zh":"“Knock over” 指撞到某物，使它由直立狀態倒下。"},{"en":"The child knocked over a glass of water by accident.","zh":"那孩子不小心撞倒了一杯水。"},{"en":"Flying clumsily indoors can knock over objects on a desk.","zh":"在室內笨拙飛行可能會撞倒桌上的物件。"},{"en":"This verb shows that Kiwi’s first flight is messy and uncontrolled.","zh":"這個動詞顯示 Kiwi 第一次飛行混亂而不受控制。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"pencil holder","meaning":"筆筒","examples":[{"en":"Kiwi knocked over a pencil holder.","zh":"Kiwi 撞倒了一個筆筒。"},{"en":"A pencil holder is a container used to keep pencils, pens, and similar stationery upright.","zh":"筆筒是用來放鉛筆、原子筆和類似文具的容器。"},{"en":"The pencil holder on Mina’s desk was full of coloured pens.","zh":"Mina 書桌上的筆筒裝滿彩色筆。"},{"en":"If a pencil holder falls, pencils may roll across the table or floor.","zh":"如果筆筒倒下，鉛筆可能會滾到桌上或地上。"},{"en":"In the story, the pencil holder shows how Kiwi’s flight disturbs Mina’s orderly room.","zh":"在故事中，筆筒顯示 Kiwi 的飛行打亂了 Mina 整齊的房間。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"scattered Mina’s notes","meaning":"撒亂 Mina 的筆記","examples":[{"en":"Kiwi scattered Mina’s notes as he tried to fly.","zh":"Kiwi 嘗試飛行時撒亂了 Mina 的筆記。"},{"en":"To scatter Mina’s notes means to spread her papers messily in different directions.","zh":"“Scatter Mina’s notes” 指把 Mina 的紙張亂七八糟地散開到不同方向。"},{"en":"The wind scattered Mina’s notes across the classroom floor.","zh":"風吹亂了 Mina 的筆記，把它們撒到課室地上。"},{"en":"Scattering someone’s notes can create trouble because the pages may lose their order.","zh":"撒亂別人的筆記可能造成麻煩，因為頁面可能失去次序。"},{"en":"This action shows how Kiwi’s search for freedom affects Mina’s world.","zh":"這個動作顯示 Kiwi 尋找自由時也影響了 Mina 的世界。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"landed, panting","meaning":"氣喘吁吁地降落","examples":[{"en":"Kiwi landed, panting, on the curtain rail.","zh":"Kiwi 氣喘吁吁地降落在窗簾路軌上。"},{"en":"“Landed, panting” means came down onto a surface while breathing quickly from fear or effort.","zh":"“Landed, panting” 指落在某處時，因恐懼或用力而急促呼吸。"},{"en":"The runner reached the finish line and stopped, panting heavily.","zh":"跑手到達終點後停下來，氣喘吁吁。"},{"en":"A bird that lands panting has probably used great energy or faced a frightening moment.","zh":"氣喘吁吁地降落的鳥，大概剛用了很多力或經歷了可怕時刻。"},{"en":"This phrase shows both arrival and exhaustion.","zh":"這個說法同時顯示抵達和疲憊。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"curtain rail","meaning":"窗簾路軌","examples":[{"en":"Kiwi landed on the curtain rail.","zh":"Kiwi 降落在窗簾路軌上。"},{"en":"A curtain rail is the bar or track above a window that holds curtains.","zh":"窗簾路軌是窗戶上方用來掛窗簾的桿或軌道。"},{"en":"The cat jumped onto the curtain rail and refused to come down.","zh":"那隻貓跳到窗簾路軌上，不肯下來。"},{"en":"A curtain rail is high above the room, so it gives a bird a place to look down.","zh":"窗簾路軌位於房間高處，所以給鳥一個向下看的地方。"},{"en":"Landing on the curtain rail allows Kiwi to see his cage from above.","zh":"降落在窗簾路軌上，讓 Kiwi 能從上方看自己的籠子。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"from above","meaning":"從上方看","examples":[{"en":"From above, the cage looked like a golden box.","zh":"從上方看，籠子像一個金色盒子。"},{"en":"From above means seen from a higher position looking down.","zh":"“From above” 指從較高位置向下觀看。"},{"en":"From above, the playground looked like a colourful pattern of lines and circles.","zh":"從上方看，操場像一幅由線條和圓圈組成的彩色圖案。"},{"en":"Seeing something from above can change how large or important it seems.","zh":"從上方看某物，可以改變它看起來的大小或重要性。"},{"en":"In the story, seeing the cage from above changes Kiwi’s understanding of it.","zh":"在故事中，從上方看籠子改變了 Kiwi 對它的理解。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"had once seemed like","meaning":"曾經看起來像","examples":[{"en":"The cage had once seemed like the whole universe.","zh":"籠子曾經看起來像整個宇宙。"},{"en":"“Had once seemed like” means something used to appear a certain way in the past, but that view has changed.","zh":"“Had once seemed like” 指某物過去曾看起來像某種樣子，但這種看法已改變。"},{"en":"My old school had once seemed like the whole world to me.","zh":"我的舊學校曾經看起來像我的整個世界。"},{"en":"A problem that had once seemed impossible may look smaller after you gain experience.","zh":"曾經看起來不可能解決的問題，在你有經驗後可能會變小。"},{"en":"This phrase contrasts an old belief with a new understanding.","zh":"這個說法把舊信念與新理解作對比。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"the whole universe","meaning":"整個宇宙","examples":[{"en":"The cage had once seemed like the whole universe.","zh":"籠子曾經看起來像整個宇宙。"},{"en":"The whole universe means everything that exists, or everything someone knows and can imagine.","zh":"整個宇宙指存在的一切，或某人所知道和能想像的一切。"},{"en":"To a young child, one small home can feel like the whole universe.","zh":"對幼童來說，一個小小的家也可以感覺像整個宇宙。"},{"en":"If someone has never left a place, that place may seem like the whole universe.","zh":"如果某人從未離開過一個地方，那地方可能看起來像整個宇宙。"},{"en":"This phrase shows how completely Kiwi’s world was once limited by the cage.","zh":"這個說法顯示 Kiwi 的世界曾經完全受籠子限制。"}],"source":"2018 Q9.pdf","sourcePage":7},{"front":"merely","meaning":"只是；僅僅","examples":[{"en":"From above, the cage was merely a golden box on a table.","zh":"從上方看，籠子僅僅是桌上的一個金色盒子。"},{"en":"“Merely” means only or nothing more than.","zh":"“Merely” 指只是，沒有更多意思。"},{"en":"The mistake was merely a spelling error, not a serious misunderstanding.","zh":"那個錯誤只是一個串字錯誤，不是嚴重誤解。"},{"en":"Something that once felt huge may later seem merely small and ordinary.","zh":"曾經感覺巨大的東西，之後可能看來只是細小而普通。"},{"en":"This word reduces the importance of the thing being described.","zh":"這個詞會降低所描述事物的重要性。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"a golden box","meaning":"金色盒子","examples":[{"en":"The cage was merely a golden box on a table.","zh":"籠子只是桌上的一個金色盒子。"},{"en":"A golden box is a box that looks gold in colour or shines like gold.","zh":"金色盒子是外表呈金色或像金一樣發亮的盒子。"},{"en":"The jewellery was kept inside a small golden box.","zh":"首飾放在一個小金色盒子裏。"},{"en":"Calling the cage a golden box makes it sound beautiful but also limited.","zh":"把籠子稱為金色盒子，令它聽起來美麗但受限制。"},{"en":"In the story, the golden box is attractive from outside but confining from inside.","zh":"在故事中，金色盒子從外面看吸引，從裏面看卻是囚困。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"the window was open too","meaning":"窗也開着","examples":[{"en":"The window was open too.","zh":"窗也開着。"},{"en":"“The window was open too” means that, in addition to the cage door, the window was also not closed.","zh":"“The window was open too” 表示除了籠門，窗戶也沒有關上。"},{"en":"The front door was open, and the window was open too, so the room filled with wind.","zh":"前門開着，窗也開着，所以房間充滿了風。"},{"en":"If both the cage and the window are open, the chance to escape becomes much greater.","zh":"如果籠子和窗戶都打開，逃走的機會就大得多。"},{"en":"This sentence raises the danger and possibility of Kiwi leaving the room.","zh":"這句話增加了 Kiwi 離開房間的危險和可能性。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"entered the room","meaning":"進入房間","examples":[{"en":"Wind entered the room.","zh":"風進入房間。"},{"en":"To enter the room means to come into the room from outside.","zh":"“Enter the room” 指從外面進入房間。"},{"en":"Cold air entered the room when the window opened.","zh":"窗戶打開時，冷空氣進入房間。"},{"en":"When wind enters the room, it can move curtains, papers, and small objects.","zh":"當風進入房間時，它可以吹動窗簾、紙張和小物件。"},{"en":"In the story, the wind entering the room brings the outside world closer to Kiwi.","zh":"在故事中，風進入房間，把外面的世界帶近 Kiwi。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"wet pavement","meaning":"濕潤的行人路","examples":[{"en":"The wind smelled of wet pavement, trees and exhaust fumes.","zh":"風帶着濕潤的行人路、樹木和廢氣的氣味。"},{"en":"Wet pavement is a road or footpath surface that is damp after rain or washing.","zh":"濕潤的行人路是雨後或清洗後變得潮濕的道路或行人路表面。"},{"en":"After the storm, the wet pavement reflected the streetlights.","zh":"暴風雨後，濕潤的行人路反射着街燈。"},{"en":"The smell of wet pavement can make a city feel fresh but also heavy and grey.","zh":"濕潤行人路的氣味可以令城市感覺清新，卻也有點沉重和灰暗。"},{"en":"This detail makes the outside world feel physical and real.","zh":"這個細節令外面的世界感覺具體而真實。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"exhaust fumes","meaning":"廢氣","examples":[{"en":"The wind smelled of exhaust fumes.","zh":"風帶着廢氣的氣味。"},{"en":"Exhaust fumes are the gases and smells released by vehicles or engines.","zh":"廢氣是車輛或引擎排出的氣體和氣味。"},{"en":"The street was full of exhaust fumes during the morning traffic jam.","zh":"早上塞車時，街上充滿廢氣。"},{"en":"Exhaust fumes can make the air smell dirty and unpleasant.","zh":"廢氣可以令空氣聞起來骯髒而令人不舒服。"},{"en":"Mentioning exhaust fumes shows that freedom outside is not perfectly clean or safe.","zh":"提到廢氣，顯示外面的自由並不完全清新或安全。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"did not smell clean","meaning":"聞起來並不清新","examples":[{"en":"Freedom did not smell clean.","zh":"自由聞起來並不清新。"},{"en":"“Did not smell clean” means it had an unpleasant, dirty, or mixed smell instead of a fresh one.","zh":"“Did not smell clean” 指它不是清新的氣味，而是令人不快、骯髒或混雜的氣味。"},{"en":"The river did not smell clean after rubbish had been thrown into it.","zh":"河裏被丟了垃圾後，聞起來並不清新。"},{"en":"Something exciting may not smell clean if it also carries danger and uncertainty.","zh":"令人興奮的東西如果同時帶有危險和不確定，也可能聞起來並不清新。"},{"en":"This sentence challenges the idea that freedom is always pure and beautiful.","zh":"這句話挑戰自由總是純淨美好的想法。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"dangerous, confusing and alive","meaning":"危險、混亂而充滿生命力","examples":[{"en":"Freedom smelled dangerous, confusing and alive.","zh":"自由聞起來危險、混亂而充滿生命力。"},{"en":"“Dangerous, confusing and alive” means full of risk, uncertainty, and powerful movement.","zh":"“Dangerous, confusing and alive” 指充滿風險、不確定和強烈動感。"},{"en":"The busy market felt dangerous, confusing and alive to the child who had never left home.","zh":"對從未離家的孩子來說，繁忙市場感覺危險、混亂而充滿生命力。"},{"en":"New freedom can feel confusing because it brings choices as well as space.","zh":"新得到的自由可能令人混亂，因為它帶來空間，也帶來選擇。"},{"en":"This phrase shows that freedom is exciting but not simple.","zh":"這個說法顯示自由令人興奮，但並不簡單。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"with freedom comes","meaning":"自由帶來","examples":[{"en":"With freedom comes not only space but choice.","zh":"自由帶來的不只是空間，還有選擇。"},{"en":"“With freedom comes” means freedom brings or includes something else as a result.","zh":"“With freedom comes” 指自由會帶來或包含某種結果。"},{"en":"With leadership comes responsibility for other people’s work.","zh":"領導權帶來對別人工作的責任。"},{"en":"With freedom comes risk, because people must decide what to do.","zh":"自由帶來風險，因為人必須決定該做甚麼。"},{"en":"This phrase is useful for showing that something positive also carries a burden.","zh":"這個說法適合顯示正面的東西也帶有負擔。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"not only… but…","meaning":"不只……而且……","examples":[{"en":"With freedom comes not only space but choice.","zh":"自由帶來的不只是空間，而且是選擇。"},{"en":"“Not only… but…” connects two ideas and shows that the second one is also important.","zh":"“Not only… but…” 連接兩個想法，並顯示第二個也很重要。"},{"en":"A good teacher gives students not only answers but confidence.","zh":"好老師給學生的不只是答案，而且是信心。"},{"en":"Moving abroad brings not only new experiences but also loneliness.","zh":"移居海外帶來的不只是新經歷，而且也有孤獨。"},{"en":"This structure helps expand an idea beyond the first obvious point.","zh":"這個結構幫助把想法從第一個明顯重點擴展開去。"}],"source":"2018 Q9.pdf","sourcePage":8},{"front":"choice is heavier than any chain","meaning":"選擇比任何鎖鏈都沉重","examples":[{"en":"Choice is heavier than any chain.","zh":"選擇比任何鎖鏈都沉重。"},{"en":"“Choice is heavier than any chain” means making decisions can feel more difficult than being physically restricted.","zh":"“Choice is heavier than any chain” 指作決定有時比被身體限制更困難。"},{"en":"After graduation, choosing a future path felt heavier than any school rule.","zh":"畢業後，選擇未來道路比任何校規都沉重。"},{"en":"Freedom can be frightening because choice brings responsibility and possible regret.","zh":"自由可能令人害怕，因為選擇帶來責任和可能的後悔。"},{"en":"This sentence suggests that freedom has emotional weight.","zh":"這句話暗示自由有情感上的重量。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"window ledge","meaning":"窗台","examples":[{"en":"Kiwi flew to the window ledge.","zh":"Kiwi 飛到窗台上。"},{"en":"A window ledge is the narrow shelf-like part at the bottom of a window.","zh":"窗台是窗戶底部像窄架一樣的部分。"},{"en":"The cat sat on the window ledge and watched people pass below.","zh":"那隻貓坐在窗台上，看着下面的人經過。"},{"en":"A window ledge can be a dangerous place if the window is high above the street.","zh":"如果窗戶離街道很高，窗台可能是危險的地方。"},{"en":"For Kiwi, the window ledge is the edge between the room and the open world.","zh":"對 Kiwi 來說，窗台是房間與開闊世界之間的邊緣。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"beneath me","meaning":"在我下方","examples":[{"en":"Beneath Kiwi, the city dropped away.","zh":"在 Kiwi 下方，城市向下展開。"},{"en":"Beneath me means below me or under my position.","zh":"“Beneath me” 指在我下面或我的位置之下。"},{"en":"Beneath me, the river looked like a silver line from the bridge.","zh":"我站在橋上時，河流在我下方像一條銀線。"},{"en":"When someone is high up, everything beneath them may look smaller and farther away.","zh":"當人位於高處，下方的一切可能看起來更小、更遠。"},{"en":"This phrase helps readers feel Kiwi’s height and danger.","zh":"這個說法幫助讀者感受 Kiwi 所在的高度和危險。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"the city dropped away","meaning":"城市向下展開","examples":[{"en":"Beneath Kiwi, the city dropped away.","zh":"在 Kiwi 下方，城市向下展開。"},{"en":"“The city dropped away” means the city seemed to fall steeply downward below him.","zh":"“The city dropped away” 指城市好像在他身下陡然向下延伸。"},{"en":"From the balcony, the streets dropped away far below my feet.","zh":"從露台看，街道在我腳下遠遠向下展開。"},{"en":"This phrase creates a feeling of height, depth, and possible danger.","zh":"這個說法製造高度、深度和可能危險的感覺。"},{"en":"It shows how frightening the outside world looks from the window.","zh":"它顯示從窗邊看出去，外面的世界有多可怕。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"balconies","meaning":"露台","examples":[{"en":"Kiwi saw balconies below him.","zh":"Kiwi 看見下方的露台。"},{"en":"Balconies are small outdoor platforms attached to the side of a building.","zh":"露台是連接在建築物外側的小型戶外平台。"},{"en":"People stood on their balconies to watch the fireworks.","zh":"人們站在露台上觀看煙花。"},{"en":"Balconies can make a tall building feel connected to the outside air.","zh":"露台可以令高樓感覺與外面的空氣相連。"},{"en":"For Kiwi, the balconies below show how high and unfamiliar the city is.","zh":"對 Kiwi 來說，下方的露台顯示城市多麼高而陌生。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"laundry","meaning":"晾曬的衣物","examples":[{"en":"Kiwi saw laundry hanging below.","zh":"Kiwi 看見下方掛着晾曬的衣物。"},{"en":"Laundry refers to clothes, towels, or sheets that are being washed, dried, or need washing.","zh":"“Laundry” 指正在清洗、晾乾或需要清洗的衣服、毛巾或床單。"},{"en":"The family hung their laundry on the balcony after washing it.","zh":"那家人洗衣後把衣物掛在露台上晾乾。"},{"en":"Laundry hanging outside can show ordinary home life in a city.","zh":"戶外晾曬的衣物可以顯示城市中的普通家庭生活。"},{"en":"This detail makes the view below Kiwi feel everyday and real.","zh":"這個細節令 Kiwi 下方的景象感覺日常而真實。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"somewhere nearby","meaning":"附近某處","examples":[{"en":"Somewhere nearby, a sparrow chirped sharply.","zh":"附近某處，一隻麻雀尖聲啁啾。"},{"en":"Somewhere nearby means in a place close to the speaker, though the exact place is not known.","zh":"“Somewhere nearby” 指在說話者附近某個地方，但確實位置不明。"},{"en":"Somewhere nearby, a dog barked, but I could not see it.","zh":"附近某處有狗吠，但我看不見牠。"},{"en":"This phrase creates a sense that something is close but hidden.","zh":"這個說法營造某物很接近但隱藏着的感覺。"},{"en":"In the story, the nearby sparrow makes the outside world feel closer to Kiwi.","zh":"在故事中，附近的麻雀令外面的世界感覺更接近 Kiwi。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"chirped sharply","meaning":"尖聲啁啾","examples":[{"en":"A sparrow chirped sharply, as if laughing.","zh":"一隻麻雀尖聲啁啾，好像在笑。"},{"en":"To chirp sharply means to make a short, clear, high bird sound.","zh":"“Chirp sharply” 指發出短促、清晰而高的鳥叫聲。"},{"en":"The sparrow chirped sharply from the roof when the cat came near.","zh":"貓靠近時，麻雀在屋頂尖聲啁啾。"},{"en":"A sharp chirp can sound warning, excited, or mocking depending on the situation.","zh":"尖銳的啁啾聲可因情況不同而像警告、興奮或嘲笑。"},{"en":"This phrase makes the sparrow’s sound feel quick and noticeable.","zh":"這個說法令麻雀的聲音感覺快速而明顯。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"as if laughing","meaning":"好像在笑","examples":[{"en":"The sparrow chirped as if laughing.","zh":"那隻麻雀啁啾着，好像在笑。"},{"en":"“As if laughing” means the sound or action seemed similar to laughter.","zh":"“As if laughing” 指聲音或動作看似像笑。"},{"en":"The children whispered as if laughing at a secret joke.","zh":"孩子們低聲說話，好像在笑一個秘密笑話。"},{"en":"A bird cannot laugh like a person, but its sound may seem playful or mocking.","zh":"鳥不能像人一樣笑，但牠的聲音可能顯得調皮或像在嘲笑。"},{"en":"This phrase shows Kiwi’s interpretation of the sparrow’s call.","zh":"這個說法顯示 Kiwi 如何理解麻雀的叫聲。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"spread my wings","meaning":"張開翅膀","examples":[{"en":"Kiwi spread his wings on the window ledge.","zh":"Kiwi 在窗台上張開翅膀。"},{"en":"To spread my wings means to open my wings wide, often before flying.","zh":"“Spread my wings” 指張開翅膀，通常是在飛行之前。"},{"en":"The young bird spread its wings but did not leave the branch.","zh":"幼鳥張開翅膀，但沒有離開樹枝。"},{"en":"Spreading wings can show readiness, courage, or hesitation before flight.","zh":"張開翅膀可以顯示飛行前的準備、勇氣或猶豫。"},{"en":"The phrase can also mean preparing to become more independent.","zh":"這個說法也可以表示準備變得更獨立。"}],"source":"2018 Q9.pdf","sourcePage":9},{"front":"one more movement","meaning":"再多一個動作","examples":[{"en":"One more movement, and the world would have him.","zh":"再多一個動作，世界便會接住他。"},{"en":"“One more movement” means just one additional action or motion.","zh":"“One more movement” 指只要再多一個行動或動作。"},{"en":"One more movement, and the glass would have fallen off the table.","zh":"再多一個動作，玻璃杯就會從桌上掉下來。"},{"en":"This phrase creates suspense because a small action could change everything.","zh":"這個說法製造懸念，因為一個小動作可能改變一切。"},{"en":"For Kiwi, one more movement could mean leaving the cage life forever.","zh":"對 Kiwi 來說，再多一個動作可能意味着永遠離開籠中生活。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"the world would have me","meaning":"世界便會接住我；我便屬於世界","examples":[{"en":"One more movement, and the world would have Kiwi.","zh":"再多一個動作，世界便會接住 Kiwi。"},{"en":"“The world would have me” means I would belong to the open world beyond my old limits.","zh":"“The world would have me” 指我將屬於舊限制以外的開闊世界。"},{"en":"One step outside the gate, and the city would have me.","zh":"只要走出閘門一步，城市便會接住我。"},{"en":"This phrase can suggest surrendering to freedom, danger, and possibility.","zh":"這個說法可以暗示把自己交給自由、危險和可能性。"},{"en":"For Kiwi, it means the outside world is ready to claim him if he chooses it.","zh":"對 Kiwi 來說，這表示只要他選擇，外面的世界就準備接納他。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"a sob from the corridor","meaning":"走廊傳來的抽泣聲","examples":[{"en":"Kiwi heard a sob from the corridor.","zh":"Kiwi 聽見走廊傳來一聲抽泣。"},{"en":"A sob from the corridor is the sound of someone crying from the hallway outside the room.","zh":"走廊傳來的抽泣聲，是房間外走廊有人哭泣的聲音。"},{"en":"I heard a sob from the corridor and opened the door to check who was there.","zh":"我聽見走廊傳來抽泣聲，便打開門看看是誰。"},{"en":"A sob from the corridor can interrupt a quiet moment and bring emotion into the scene.","zh":"走廊傳來的抽泣聲可以打斷安靜時刻，把情感帶進場景。"},{"en":"In the story, the sob pulls Kiwi’s attention away from the window.","zh":"在故事中，那聲抽泣把 Kiwi 的注意力從窗外拉回來。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"stumbled in","meaning":"踉蹌走進來","examples":[{"en":"Mina stumbled in and saw the empty cage.","zh":"Mina 踉蹌走進來，看見空籠。"},{"en":"To stumble in means to enter unsteadily, often because of shock, fear, hurry, or weakness.","zh":"“Stumble in” 指不穩地走進來，通常因震驚、恐懼、匆忙或虛弱。"},{"en":"He stumbled into the room after running up five flights of stairs.","zh":"他跑上五層樓後踉蹌走進房間。"},{"en":"Someone may stumble in when emotions make their body less controlled.","zh":"當情緒令人身體失去控制時，人可能會踉蹌走進來。"},{"en":"Mina stumbling in shows how frightened and upset she is.","zh":"Mina 踉蹌走進來，顯示她多麼害怕和難過。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"for a moment","meaning":"有一刻","examples":[{"en":"For a moment, Mina did not see Kiwi.","zh":"有一刻，Mina 沒有看見 Kiwi。"},{"en":"For a moment means for a very short period of time.","zh":"“For a moment” 指在非常短的一段時間裏。"},{"en":"For a moment, the room was completely silent.","zh":"有一刻，房間完全寂靜。"},{"en":"A moment of not seeing someone can feel terrifying when you fear they are lost.","zh":"當你害怕某人失蹤時，短短一刻看不見對方也可能令人恐懼。"},{"en":"This phrase slows the scene and increases suspense.","zh":"這個說法放慢場景，增加懸念。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"empty cage","meaning":"空籠","examples":[{"en":"Mina saw the empty cage.","zh":"Mina 看見空籠。"},{"en":"An empty cage is a cage with no animal or bird inside it.","zh":"空籠是裏面沒有動物或鳥的籠子。"},{"en":"The empty cage worried the family because the hamster was missing.","zh":"那個空籠令家人很擔心，因為倉鼠不見了。"},{"en":"An empty cage can suggest escape, loss, or danger.","zh":"空籠可以暗示逃走、失去或危險。"},{"en":"To Mina, the empty cage means Kiwi may be gone forever.","zh":"對 Mina 來說，空籠意味着 Kiwi 可能永遠離開了。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"her hand flew to her mouth","meaning":"她的手猛地掩住嘴","examples":[{"en":"Mina’s hand flew to her mouth.","zh":"Mina 的手猛地掩住嘴。"},{"en":"If someone’s hand flies to their mouth, they quickly cover their mouth because of shock, fear, or emotion.","zh":"如果某人的手猛地掩住嘴，表示因震驚、恐懼或情緒激動而迅速遮住嘴巴。"},{"en":"Her hand flew to her mouth when she saw the broken vase.","zh":"她看見破碎的花瓶時，手猛地掩住嘴。"},{"en":"This action often shows surprise before the person can speak.","zh":"這個動作常在說話前先顯示驚訝。"},{"en":"It lets readers see Mina’s fear through her body language.","zh":"它透過身體語言讓讀者看見 Mina 的恐懼。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"with such fear that","meaning":"帶着如此恐懼以致","examples":[{"en":"She whispered his name with such fear that the sound struck him hard.","zh":"她帶着如此恐懼低聲叫他的名字，以致那聲音重重擊中他。"},{"en":"“With such fear that” means the fear was so strong that it caused a clear result.","zh":"“With such fear that” 指恐懼強烈到造成明顯結果。"},{"en":"He called his sister’s name with such fear that everyone turned around.","zh":"他帶着如此恐懼叫妹妹的名字，以致所有人都轉過頭來。"},{"en":"A voice filled with such fear can affect the listener more than loud shouting.","zh":"充滿如此恐懼的聲音，可能比大聲呼喊更能影響聽者。"},{"en":"This structure shows both the emotion and its impact.","zh":"這個結構同時顯示情緒和它造成的影響。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"struck me harder than","meaning":"比……更猛烈地擊中我","examples":[{"en":"The sound struck Kiwi harder than the wind.","zh":"那聲音比風更猛烈地擊中 Kiwi。"},{"en":"“Struck me harder than” means affected me more strongly than something else.","zh":"“Struck me harder than” 指比另一件事更強烈地影響我。"},{"en":"Her disappointed silence struck me harder than her anger.","zh":"她失望的沉默比她的怒氣更重重擊中我。"},{"en":"A quiet sentence can strike someone harder than a loud warning if it touches their feelings.","zh":"如果一句安靜的話觸動感情，它可能比大聲警告更猛烈地擊中人。"},{"en":"This phrase compares emotional force with physical force.","zh":"這個說法把情感力量與物理力量作比較。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"only then did I understand","meaning":"直到那時我才明白","examples":[{"en":"Only then did Kiwi understand something he had never considered.","zh":"直到那時，Kiwi 才明白一件他從未考慮過的事。"},{"en":"“Only then did I understand” means I understood something only at that particular moment, not before.","zh":"“Only then did I understand” 指我直到那個特定時刻才明白某事，而不是之前就明白。"},{"en":"Only then did I understand why my friend had looked so worried.","zh":"直到那時，我才明白朋友為何看起來那麼擔心。"},{"en":"This phrase often appears after a surprising event reveals a deeper truth.","zh":"這個說法常出現在令人意外的事件揭示更深層真相之後。"},{"en":"It emphasises that the real understanding came late.","zh":"它強調真正理解來得很遲。"}],"source":"2018 Q9.pdf","sourcePage":10},{"front":"had never considered","meaning":"從未考慮過","examples":[{"en":"Kiwi understood something he had never considered.","zh":"Kiwi 明白了一件他從未考慮過的事。"},{"en":"“Had never considered” means had never thought about or examined an idea before that moment.","zh":"“Had never considered” 指在那一刻之前從未想過或仔細思考某個想法。"},{"en":"I had never considered how lonely my grandfather felt after moving house.","zh":"我從未考慮過祖父搬家後有多孤單。"},{"en":"People often fail to consider another person’s feelings until something serious happens.","zh":"人們常直到嚴重事情發生後，才考慮到別人的感受。"},{"en":"This phrase shows a new idea entering Kiwi’s mind for the first time.","zh":"這個說法顯示一個新想法第一次進入 Kiwi 心中。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"imprisoned me","meaning":"囚禁我","examples":[{"en":"The cage had imprisoned Kiwi.","zh":"籠子曾囚禁 Kiwi。"},{"en":"To imprison someone means to keep them trapped and unable to leave freely.","zh":"“Imprison” 指把某人或生物困住，使其不能自由離開。"},{"en":"The locked room imprisoned the animal until the rescue team arrived.","zh":"那個上鎖的房間囚禁了那隻動物，直到救援隊到達。"},{"en":"A place can imprison someone physically, but fear can also imprison the mind.","zh":"一個地方可以囚禁人的身體，恐懼也可以囚禁人的思想。"},{"en":"In the story, the cage has imprisoned Kiwi even though it also feels familiar.","zh":"在故事中，籠子囚禁 Kiwi，即使它也令人感到熟悉。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"my presence","meaning":"我的存在","examples":[{"en":"Kiwi’s presence had comforted Mina.","zh":"Kiwi 的存在曾安慰 Mina。"},{"en":"My presence means the fact that I am there with someone.","zh":"“My presence” 指我在某人身邊這件事。"},{"en":"Her mother’s presence made the child less afraid during the hospital visit.","zh":"媽媽的存在令孩子在看病時沒那麼害怕。"},{"en":"A person’s presence can comfort others even without many words.","zh":"一個人的存在即使沒有太多說話，也可以安慰別人。"},{"en":"Kiwi realises that his presence matters to Mina emotionally.","zh":"Kiwi 意識到自己的存在對 Mina 有情感上的意義。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"comforted her","meaning":"安慰了她","examples":[{"en":"Kiwi’s presence had comforted Mina.","zh":"Kiwi 的存在曾安慰了 Mina。"},{"en":"To comfort her means to make her feel less sad, afraid, or lonely.","zh":"“Comfort her” 指令她沒那麼傷心、害怕或孤單。"},{"en":"The teacher comforted her after she failed the test.","zh":"她測驗不合格後，老師安慰了她。"},{"en":"A familiar pet can comfort someone after a stressful day.","zh":"熟悉的寵物可以在壓力大的一天後安慰人。"},{"en":"Comforting someone does not always solve the problem, but it can make the pain easier to bear.","zh":"安慰某人不一定能解決問題，但可以令痛苦較容易承受。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"both things could be true","meaning":"兩件事可以同時成立","examples":[{"en":"Perhaps both things could be true.","zh":"也許兩件事可以同時成立。"},{"en":"“Both things could be true” means two ideas that seem opposite may both be correct at the same time.","zh":"“Both things could be true” 指兩個看似相反的想法可以同時正確。"},{"en":"The job could be tiring, and it could also be meaningful; both things could be true.","zh":"那份工作可以很累，也可以很有意義；兩件事可以同時成立。"},{"en":"A person can love someone and still need more freedom, so both things can be true.","zh":"一個人可以愛某人，同時仍需要更多自由，所以兩件事可以同時成立。"},{"en":"This phrase helps show emotional complexity instead of choosing only one simple answer.","zh":"這個說法幫助顯示情感的複雜性，而不是只選一個簡單答案。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"on the ledge","meaning":"在窗台上","examples":[{"en":"Mina saw Kiwi on the ledge.","zh":"Mina 看見 Kiwi 在窗台上。"},{"en":"On the ledge means on a narrow shelf-like edge, usually beside a window or wall.","zh":"“On the ledge” 指在狹窄像架子的邊沿上，通常在窗邊或牆邊。"},{"en":"The pigeon stood on the ledge outside the office window.","zh":"鴿子站在辦公室窗外的窗台上。"},{"en":"Being on the ledge can be dangerous because there may be little space to stand safely.","zh":"在窗台上可能很危險，因為可安全站立的空間很小。"},{"en":"In the story, Kiwi on the ledge is close to both escape and return.","zh":"在故事中，窗台上的 Kiwi 同時接近逃離和回來。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"she breathed","meaning":"她輕聲說","examples":[{"en":"“Kiwi,” she breathed.","zh":"「Kiwi，」她輕聲說。"},{"en":"“She breathed” means she spoke very softly, almost like a breath.","zh":"“She breathed” 指她非常輕地說話，幾乎像一口氣。"},{"en":"“I found it,” she breathed, afraid to break the silence.","zh":"「我找到了，」她輕聲說，害怕打破寂靜。"},{"en":"Writers use “she breathed” when a voice is quiet because of fear, relief, or wonder.","zh":"當聲音因恐懼、釋然或驚奇而很輕時，作者會使用 “she breathed”。"},{"en":"This phrase makes Mina’s voice sound fragile and emotional.","zh":"這個說法令 Mina 的聲音顯得脆弱而充滿情感。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"not a command","meaning":"不是命令","examples":[{"en":"Her voice was not a command.","zh":"她的聲音不是命令。"},{"en":"Not a command means the words did not order someone to do something.","zh":"“Not a command” 指那些話不是命令某人做某事。"},{"en":"“Come here” can sound like a request, not a command, if spoken gently.","zh":"如果語氣溫柔，“come here” 可以像請求，而不是命令。"},{"en":"Mina’s voice was not a command because she was not trying to control Kiwi.","zh":"Mina 的聲音不是命令，因為她不是想控制 Kiwi。"},{"en":"This phrase matters because Kiwi must choose whether to return.","zh":"這個說法很重要，因為 Kiwi 必須自己選擇是否回去。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"not even a plea","meaning":"甚至不是懇求","examples":[{"en":"Her voice was not even a plea.","zh":"她的聲音甚至不是懇求。"},{"en":"Not even a plea means it was not even a desperate request for someone to do something.","zh":"“Not even a plea” 指它甚至不是一個迫切要求某人做某事的請求。"},{"en":"His message was not even a plea; it was simply a quiet goodbye.","zh":"他的訊息甚至不是懇求，只是一句安靜的道別。"},{"en":"A plea asks strongly for help, but Mina’s voice only reveals fear and love.","zh":"懇求會強烈要求幫助，但 Mina 的聲音只是透露恐懼和愛。"},{"en":"This phrase shows that Mina does not force Kiwi emotionally.","zh":"這個說法顯示 Mina 沒有在情感上強迫 Kiwi。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"broken open","meaning":"破碎地敞開","examples":[{"en":"His name sounded broken open.","zh":"他的名字聽起來破碎地敞開。"},{"en":"“Broken open” means emotionally split open, revealing pain, fear, or vulnerability.","zh":"“Broken open” 指情感上像被裂開，露出痛苦、恐懼或脆弱。"},{"en":"Her voice sounded broken open when she finally admitted she was lonely.","zh":"當她終於承認自己孤單時，聲音聽起來破碎地敞開。"},{"en":"A simple word can sound broken open if it carries too much feeling.","zh":"如果承載太多感情，一個簡單詞語也可以聽起來破碎地敞開。"},{"en":"This phrase shows that Mina’s whisper exposes her heart.","zh":"這個說法顯示 Mina 的低語暴露了她的心。"}],"source":"2018 Q9.pdf","sourcePage":11},{"front":"looked out once more","meaning":"再次望出去","examples":[{"en":"Kiwi looked out once more.","zh":"Kiwi 再次望出去。"},{"en":"To look out once more means to look outside one final or additional time.","zh":"“Look out once more” 指最後或再一次向外望。"},{"en":"Before leaving home, she looked out once more at the quiet street.","zh":"離家前，她再次望向安靜的街道。"},{"en":"Looking out once more can show hesitation before an important decision.","zh":"再次望出去可以顯示人在重要決定前的猶豫。"},{"en":"In the story, Kiwi looks out again before choosing between freedom and Mina.","zh":"在故事中，Kiwi 再次望出去，然後在自由與 Mina 之間作選擇。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"endless, if not merciless","meaning":"即使不算無情，也是無邊無際","examples":[{"en":"The sky was endless, if not merciless.","zh":"天空即使不算無情，也是無邊無際。"},{"en":"“Endless, if not merciless” means the sky was certainly endless and perhaps also cruel or unforgiving.","zh":"“Endless, if not merciless” 指天空肯定無邊無際，也許還帶點殘酷或無情。"},{"en":"The desert seemed endless, if not merciless, under the noon sun.","zh":"正午陽光下，沙漠即使不算無情，也是無邊無際。"},{"en":"This structure suggests one description is definitely true while a stronger one may also be true.","zh":"這個結構表示一個描述肯定成立，而更強烈的描述也可能成立。"},{"en":"The phrase makes the sky feel beautiful but frightening.","zh":"這個說法令天空既美麗又可怕。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"small, if not safe","meaning":"即使不算安全，也是狹小","examples":[{"en":"The room was small, if not safe.","zh":"房間即使不算安全，也是狹小。"},{"en":"“Small, if not safe” means the room was certainly small, and perhaps not truly safe.","zh":"“Small, if not safe” 指房間肯定狹小，也許並不真正安全。"},{"en":"The shelter was warm, if not comfortable, during the storm.","zh":"暴風雨期間，那個避難處即使不算舒適，也是溫暖的。"},{"en":"This structure shows that the first quality is certain while the second is uncertain or doubtful.","zh":"這個結構顯示第一個特質肯定存在，而第二個則不確定或值得懷疑。"},{"en":"The phrase suggests Kiwi’s room is familiar but not fully protective.","zh":"這個說法暗示 Kiwi 的房間熟悉，卻不完全保護他。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"a life with no bars and no goodbyes","meaning":"沒有籠條、沒有道別的生活","examples":[{"en":"Kiwi wanted a life with no bars and no goodbyes.","zh":"Kiwi 想要沒有籠條、沒有道別的生活。"},{"en":"A life with no bars and no goodbyes means a life with freedom but without painful separation.","zh":"沒有籠條、沒有道別的生活，指有自由但沒有痛苦分離的生活。"},{"en":"A child may dream of a life with no rules and no losses, though real life cannot offer that.","zh":"孩子可能夢想沒有規則、沒有失去的生活，雖然現實不能提供這種生活。"},{"en":"Kiwi wants freedom without having to leave Mina behind.","zh":"Kiwi 想要自由，卻又不必把 Mina 留下。"},{"en":"This phrase shows an impossible wish for both complete freedom and complete security.","zh":"這個說法顯示一個不可能的願望：既有完全自由，也有完全安全。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"perhaps the one thing","meaning":"也許是唯一一件事","examples":[{"en":"That was perhaps the one thing no creature could have.","zh":"那也許是沒有生物能擁有的唯一一件事。"},{"en":"“Perhaps the one thing” means maybe the single thing that is especially important or impossible.","zh":"“Perhaps the one thing” 指也許是特別重要或特別不可能的唯一事情。"},{"en":"Perfect certainty is perhaps the one thing no student can have before an exam.","zh":"完全的肯定也許是學生考試前無法擁有的唯一一件事。"},{"en":"Sometimes perhaps the one thing we want most is the thing life cannot fully give.","zh":"有時，我們最想要的唯一事情，也許正是人生不能完全給予的東西。"},{"en":"This phrase introduces a thoughtful and uncertain conclusion.","zh":"這個說法引出一個帶思考和不確定的結論。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"no bird, no human, no creature","meaning":"沒有鳥、沒有人、沒有生物","examples":[{"en":"No bird, no human, no creature could have such a life.","zh":"沒有鳥、沒有人、沒有生物能擁有這樣的生活。"},{"en":"“No bird, no human, no creature” means absolutely no living being of any kind.","zh":"“No bird, no human, no creature” 指任何種類的生命都不能。"},{"en":"No child, no adult, no family can avoid change forever.","zh":"沒有孩子、沒有成人、沒有家庭能永遠避開改變。"},{"en":"Repeating “no” before each group makes the statement stronger and more final.","zh":"在每個群體前重複 “no”，令句子更強烈和肯定。"},{"en":"This phrase suggests that the wish is impossible for everyone, not only Kiwi.","zh":"這個說法暗示這個願望對所有生命而言都不可能，不只是 Kiwi。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"the only brave thing","meaning":"唯一勇敢的事","examples":[{"en":"Kiwi did the only brave thing he could think of.","zh":"Kiwi 做了他想得到的唯一勇敢的事。"},{"en":"The only brave thing means the one action that seemed courageous and possible in that moment.","zh":"“The only brave thing” 指在那一刻看起來勇敢而可行的唯一行動。"},{"en":"Telling the truth was the only brave thing she could do after the mistake.","zh":"犯錯後，說出真相是她唯一能做的勇敢事情。"},{"en":"Sometimes the brave thing is not escape, but returning to face someone honestly.","zh":"有時勇敢的事不是逃走，而是回去真誠面對某人。"},{"en":"This phrase shows that courage can take an unexpected form.","zh":"這個說法顯示勇氣可以有意想不到的形式。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"could think of","meaning":"想得到","examples":[{"en":"He did the only brave thing he could think of.","zh":"他做了自己想得到的唯一勇敢的事。"},{"en":"“Could think of” means was able to imagine, remember, or come up with an idea.","zh":"“Could think of” 指能想像、記起或想出某個主意。"},{"en":"I tried every solution I could think of, but the computer still would not start.","zh":"我試了所有想得到的方法，但電腦仍然不能啟動。"},{"en":"Under pressure, people may only do the first useful thing they can think of.","zh":"在壓力下，人們可能只會做自己想得到的第一件有用事情。"},{"en":"This phrase shows the limit of someone’s ideas in a difficult moment.","zh":"這個說法顯示人在困難時刻想法上的限制。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"not away, but back","meaning":"不是飛走，而是飛回來","examples":[{"en":"Kiwi flew not away, but back.","zh":"Kiwi 不是飛走，而是飛回來。"},{"en":"“Not away, but back” contrasts the expected direction of leaving with the chosen direction of returning.","zh":"“Not away, but back” 把原本預期的離開方向，與實際選擇的回來方向作對比。"},{"en":"After the argument, she walked not away, but back to apologise.","zh":"爭吵後，她不是走開，而是走回來道歉。"},{"en":"This structure makes the surprising choice stronger and clearer.","zh":"這個結構令意外的選擇更強烈和清楚。"},{"en":"Kiwi’s return shows that freedom can include choosing to stay connected.","zh":"Kiwi 回來顯示自由也可以包括選擇保持連繫。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"landed on Mina’s shoulder","meaning":"落在 Mina 的肩上","examples":[{"en":"Kiwi landed on Mina’s shoulder.","zh":"Kiwi 落在 Mina 的肩上。"},{"en":"To land on Mina’s shoulder means to fly down and rest on her shoulder.","zh":"“Land on Mina’s shoulder” 指飛下來並停在 Mina 的肩膀上。"},{"en":"The trained parrot landed on the boy’s shoulder when he called its name.","zh":"那隻受訓鸚鵡在男孩叫牠名字時，落在他的肩上。"},{"en":"A bird landing on someone’s shoulder can show trust and closeness.","zh":"鳥落在某人的肩上，可以顯示信任和親近。"},{"en":"In the story, this action shows Kiwi’s decision to return to Mina.","zh":"在故事中，這個動作顯示 Kiwi 決定回到 Mina 身邊。"}],"source":"2018 Q9.pdf","sourcePage":12},{"front":"cried into my feathers","meaning":"伏在我的羽毛中哭","examples":[{"en":"Mina cried into Kiwi’s feathers.","zh":"Mina 伏在 Kiwi 的羽毛中哭。"},{"en":"To cry into my feathers means to press her face against the bird’s feathers while crying.","zh":"“Cry into my feathers” 指哭泣時把臉靠在鳥的羽毛上。"},{"en":"The child cried into the dog’s fur after losing the game.","zh":"比賽輸了後，那孩子伏在狗的毛中哭。"},{"en":"Crying into a pet’s feathers or fur can show deep comfort and trust.","zh":"伏在寵物羽毛或毛髮中哭，可以顯示深切安慰和信任。"},{"en":"This phrase makes Mina’s relief and sadness physically visible.","zh":"這個說法令 Mina 的釋然和傷心變得具體可見。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"I let her","meaning":"我由得她","examples":[{"en":"Mina cried into Kiwi’s feathers, and he let her.","zh":"Mina 伏在 Kiwi 的羽毛中哭，而他由得她。"},{"en":"“I let her” means I allowed her to do it and did not stop her.","zh":"“I let her” 指我容許她這樣做，沒有阻止她。"},{"en":"My little sister held my hand tightly, and I let her.","zh":"妹妹緊緊握着我的手，而我由得她。"},{"en":"Letting someone cry can be a quiet way to comfort them.","zh":"讓某人哭出來，可以是一種安靜的安慰方式。"},{"en":"This phrase shows Kiwi’s gentle acceptance of Mina’s need for comfort.","zh":"這個說法顯示 Kiwi 溫柔地接受 Mina 對安慰的需要。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"left the hook hanging loose","meaning":"讓鉤子鬆鬆地掛着","examples":[{"en":"Mina left the hook hanging loose.","zh":"Mina 讓鉤子鬆鬆地掛着。"},{"en":"To leave the hook hanging loose means to let the hook remain unfastened instead of closing it tightly.","zh":"“Leave the hook hanging loose” 指讓鉤子沒有扣緊，只是鬆鬆地掛着。"},{"en":"The farmer left the gate hook hanging loose so the workers could enter easily.","zh":"農夫讓閘門鉤子鬆鬆地掛着，好讓工人容易進入。"},{"en":"Leaving the hook hanging loose shows that the cage is no longer locked in the same way.","zh":"讓鉤子鬆鬆地掛着，顯示籠子不再以同樣方式被鎖住。"},{"en":"In the story, this small action shows Mina’s new trust in Kiwi.","zh":"在故事中，這個小動作顯示 Mina 對 Kiwi 的新信任。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"on the top of the cage","meaning":"在籠頂上","examples":[{"en":"Kiwi slept on the top of the cage.","zh":"Kiwi 睡在籠頂上。"},{"en":"On the top of the cage means on the outside upper surface of the cage.","zh":"“On the top of the cage” 指在籠子外面的頂部表面。"},{"en":"The parrot sat on the top of the cage instead of going inside.","zh":"那隻鸚鵡坐在籠頂上，而不是進入籠內。"},{"en":"Being on the top of the cage is different from being trapped inside it.","zh":"在籠頂上與被困在籠內並不一樣。"},{"en":"This position shows that Kiwi is near the cage but no longer fully imprisoned by it.","zh":"這個位置顯示 Kiwi 仍靠近籠子，但不再完全被它囚禁。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"under a square of moonlight","meaning":"在一方月光下","examples":[{"en":"Kiwi slept under a square of moonlight.","zh":"Kiwi 睡在一方月光下。"},{"en":"A square of moonlight is a square-shaped patch of light from the moon, often formed by a window.","zh":"一方月光是月亮透過窗戶形成的方形光影。"},{"en":"The cat slept under a square of moonlight on the wooden floor.","zh":"那隻貓睡在木地板上一方月光下。"},{"en":"Moonlight can make a quiet room feel gentle and peaceful.","zh":"月光可以令安靜的房間感覺柔和而平靜。"},{"en":"This image suggests a softer kind of freedom after the frightening afternoon.","zh":"這個意象暗示在可怕的下午過後，一種較溫柔的自由出現了。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"the bars were still there","meaning":"籠條仍然存在","examples":[{"en":"The bars were still there, but something had changed.","zh":"籠條仍然存在，但有些東西改變了。"},{"en":"“The bars were still there” means the physical cage had not disappeared.","zh":"“The bars were still there” 指實際的籠子並沒有消失。"},{"en":"The rules were still there, but the teacher now trusted us more.","zh":"規則仍然存在，但老師現在更加信任我們。"},{"en":"A situation can change emotionally even when the physical facts remain the same.","zh":"即使實際情況沒有改變，情感上的關係也可以改變。"},{"en":"This phrase shows that freedom is not only about removing barriers.","zh":"這個說法顯示自由不只是移除障礙。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"something between us had changed","meaning":"我們之間有些東西改變了","examples":[{"en":"Something between Kiwi and Mina had changed.","zh":"Kiwi 和 Mina 之間有些東西改變了。"},{"en":"“Something between us had changed” means the relationship or feeling connecting two people or creatures was now different.","zh":"“Something between us had changed” 指連繫兩個人或生物的關係或感覺已經不同。"},{"en":"After the honest talk, something between the two friends had changed.","zh":"那次坦誠談話後，兩個朋友之間有些東西改變了。"},{"en":"Trust can change a relationship even when daily life looks almost the same.","zh":"信任可以改變一段關係，即使日常生活看起來幾乎一樣。"},{"en":"This phrase points to an emotional change that is hard to name exactly.","zh":"這個說法指向一種難以準確命名的情感改變。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"opened the window","meaning":"打開窗戶","examples":[{"en":"The next morning, Mina opened the window.","zh":"第二天早上，Mina 打開窗戶。"},{"en":"To open the window means to move the window so air can come in or someone can look or go out.","zh":"“Open the window” 指把窗戶打開，讓空氣進來，或讓人望出去、出去。"},{"en":"My grandmother opened the window to let the kitchen smell out.","zh":"祖母打開窗戶，讓廚房氣味散走。"},{"en":"Opening the window can invite fresh air, noise, and the outside world into a room.","zh":"打開窗戶可以把新鮮空氣、聲音和外面的世界帶進房間。"},{"en":"In the story, Mina opening the window shows she is no longer only trying to keep Kiwi enclosed.","zh":"在故事中，Mina 打開窗戶顯示她不再只是想把 Kiwi 關住。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"flew around the room","meaning":"在房間裏飛來飛去","examples":[{"en":"Kiwi flew around the room twice.","zh":"Kiwi 在房間裏飛了兩圈。"},{"en":"To fly around the room means to move through the air inside the room in different directions.","zh":"“Fly around the room” 指在房間內向不同方向飛行。"},{"en":"The small bird flew around the room before landing on the bookshelf.","zh":"那隻小鳥在房間裏飛來飛去，然後停在書架上。"},{"en":"Flying around the room lets a bird use its wings without leaving the house.","zh":"在房間裏飛來飛去，讓鳥可以使用翅膀而不離開家。"},{"en":"This action shows Kiwi practising freedom in a safer space.","zh":"這個動作顯示 Kiwi 在較安全的空間中練習自由。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"before returning to","meaning":"然後回到","examples":[{"en":"Kiwi flew around the room before returning to Mina’s hand.","zh":"Kiwi 在房間裏飛來飛去，然後回到 Mina 的手上。"},{"en":"“Before returning to” means after doing one action first, someone or something goes back to a place or person.","zh":"“Before returning to” 指先做一個動作，之後再回到某個地方或某人身邊。"},{"en":"The child played in the park before returning to his parents.","zh":"那孩子先在公園玩，然後回到父母身邊。"},{"en":"This phrase shows that leaving for a while does not always mean leaving forever.","zh":"這個說法顯示暫時離開不一定代表永遠離開。"},{"en":"In the story, flying first and returning later becomes a sign of trust.","zh":"在故事中，先飛出去再回來成為信任的象徵。"}],"source":"2018 Q9.pdf","sourcePage":13},{"front":"returned to her hand","meaning":"回到她手上","examples":[{"en":"Kiwi returned to Mina’s hand.","zh":"Kiwi 回到 Mina 的手上。"},{"en":"To return to her hand means to go back and rest on her hand again.","zh":"“Return to her hand” 指再次回去並停在她的手上。"},{"en":"The trained bird returned to the keeper’s hand after circling the room.","zh":"那隻受訓的鳥在房間繞了一圈後回到飼養員手上。"},{"en":"Returning to someone’s hand can show trust because the animal chooses closeness.","zh":"回到某人的手上可以顯示信任，因為動物選擇親近。"},{"en":"Kiwi’s return matters because it is voluntary, not forced.","zh":"Kiwi 的回來很重要，因為這是自願的，不是被迫的。"}],"source":"2018 Q9.pdf","sourcePage":14},{"front":"the sparrows were calling","meaning":"麻雀在呼喚","examples":[{"en":"Outside, the sparrows were calling.","zh":"外面，麻雀在呼喚。"},{"en":"“The sparrows were calling” means the sparrows were making sounds that seemed to invite or attract Kiwi.","zh":"“The sparrows were calling” 指麻雀發出叫聲，像在邀請或吸引 Kiwi。"},{"en":"Outside the classroom, birds were calling in the trees.","zh":"課室外，鳥兒在樹上呼喚。"},{"en":"A calling sound can make someone feel pulled towards the outside world.","zh":"呼喚聲可以令人覺得被外面的世界吸引。"},{"en":"In the story, the sparrows’ calls keep the possibility of wider freedom alive.","zh":"在故事中，麻雀的叫聲保留了更廣闊自由的可能性。"}],"source":"2018 Q9.pdf","sourcePage":14},{"front":"one day, perhaps","meaning":"也許有一天","examples":[{"en":"One day, perhaps, Kiwi would answer them.","zh":"也許有一天，Kiwi 會回應牠們。"},{"en":"“One day, perhaps” means maybe at some uncertain time in the future.","zh":"“One day, perhaps” 指也許在未來某個不確定的時候。"},{"en":"One day, perhaps, she would travel to the city she had always imagined.","zh":"也許有一天，她會去那個一直想像的城市旅行。"},{"en":"This phrase expresses hope without promising that something will definitely happen.","zh":"這個說法表達希望，但不承諾事情一定會發生。"},{"en":"It leaves the ending open and gentle.","zh":"它令結局保持開放而溫柔。"}],"source":"2018 Q9.pdf","sourcePage":14},{"front":"answer them","meaning":"回應牠們","examples":[{"en":"One day, Kiwi might answer the sparrows.","zh":"也許有一天，Kiwi 會回應那些麻雀。"},{"en":"To answer them means to respond to their call, invitation, or message.","zh":"“Answer them” 指回應牠們的呼喚、邀請或訊息。"},{"en":"The child heard his friends calling from outside and finally answered them.","zh":"孩子聽到朋友在外面叫他，最後回應了他們。"},{"en":"Kiwi answering the sparrows would mean joining the wider world beyond the room.","zh":"Kiwi 回應麻雀，會意味着加入房間以外更廣闊的世界。"},{"en":"This phrase suggests a future choice that remains possible.","zh":"這個說法暗示未來仍有一個可能的選擇。"}],"source":"2018 Q9.pdf","sourcePage":14},{"front":"not simply the chance to leave","meaning":"不只是離開的機會","examples":[{"en":"Freedom was not simply the chance to leave.","zh":"自由不只是離開的機會。"},{"en":"“Not simply the chance to leave” means freedom is more than just being able to go away.","zh":"“Not simply the chance to leave” 指自由不只是能夠離開。"},{"en":"Independence is not simply the chance to live alone; it also means making responsible choices.","zh":"獨立不只是獨自生活的機會，也包括作負責任的選擇。"},{"en":"A bird may have the chance to leave, but real freedom also includes trust and choice.","zh":"鳥可以有離開的機會，但真正自由也包括信任和選擇。"},{"en":"This phrase deepens the meaning of freedom beyond physical escape.","zh":"這個說法把自由的意義深化，超越身體上的逃離。"}],"source":"2018 Q9.pdf","sourcePage":14},{"front":"being trusted enough to return","meaning":"被信任到可以回來","examples":[{"en":"Freedom was being trusted enough to return.","zh":"自由是被信任到可以回來。"},{"en":"Being trusted enough to return means someone allows you to leave because they believe you may choose to come back.","zh":"“Being trusted enough to return” 指有人容許你離開，因為相信你可能會選擇回來。"},{"en":"A teenager feels more respected when parents trust him enough to return home on time.","zh":"當父母信任少年會準時回家，他會感到更受尊重。"},{"en":"Trust changes control into choice because returning is no longer forced.","zh":"信任把控制變成選擇，因為回來不再是被迫的。"},{"en":"In the story, freedom means Kiwi can leave and still be welcomed back.","zh":"在故事中，自由意味着 Kiwi 可以離開，也仍會被歡迎回來。"}],"source":"2018 Q9.pdf","sourcePage":14}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
